COLLDATA("nasai","ur",[[3809,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے زیادہ اچھے اور بہتر لوگ وہ ہیں جو میرے زمانے کے ہیں، پھر وہ جو ان کے بعد کے ہیں، پھر وہ جو ان کے بعد کے ہیں، پھر وہ جو ان کے بعد کے ہیں\"، مجھے نہیں معلوم کہ آپ صلی اللہ علیہ وسلم نے «ثم الذين يلونهم» کا ذکر دو بار کیا یا تین بار، پھر آپ نے ان لوگوں کا ذکر کیا جو خیانت کریں گے اور انہیں امین (امانت دار) نہیں سمجھا جائے گا، گواہی دیں گے حالانکہ ان سے گواہی نہیں مانگی جائے گی اور نذر مانیں گے اور اسے پورا نہیں کریں گے اور ان لوگوں میں موٹاپا ظاہر ہو گا\" ۱؎۔ ابوعبدالرحمٰن نسائی کہتے ہیں: یہ ابوجمرہ نصر بن عمران ہیں۔\n§وضاحت\n۱؎: کیونکہ جواب دہی کا خوف ان کے دلوں سے جاتا رہے گا، عیش و آرام کے عادی ہو جائیں گے اور دین و ایمان کی فکر جاتی رہے گی جو ان کے مٹاپے کا سبب ہو گی۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے بہترین لوگ میرے دور کے ہیں‘ پھر جو لوگ ان کے بعد آئیں گے اور پھر جو ان کے بعد آئیں گے اور پھر جو ان کے بعد آئیں گے۔‘‘ (راوئی حدیث نے کہا:) مجھے یاد نہیں کہ آپ نے یہ لفظ دو دفعہ فرمائے یا تین دفعہ۔ پھر آپ نے ایسے لوگوں کا ذکر فرمایا جو خیانت کریں گے حتیٰ کہ ان کے پاس امانت نہیں رکھی جائے گی۔ گواہیاں دیں گے جبکہ ان سے گواہی طلب نہیں کی جائے گی۔ وہ نذریں مانیں گے پوری نہیں کریں گے اور ان میں موٹاپا عام ہوجائے گا۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ نصر بن عمران کی کنیت ابو حمزہ ہے (ابوحمزہ نہیں)۔","f2":"(۱) ’’میرے دور کے‘‘ یعنی صحابئہ کرام رضی اللہ عنہم امت میں سب سے افضل ہیں اور یہ بات متفق علیہ ہے کیونکہ انہیں براہ راست نبوی فیضان حاصل ہوا ہ۔ ’’ان کے بعد‘‘ سے مراد تابعین اور ’’ان کے بعد‘‘ سے مراد تبع تابعین ہیں۔ یہ دولفظ ہی صحیح ہیں۔ کیونکہ یہ تن دور ہی مشہور بالخیر ہیں۔ ویسے بھی راوی کو تیسری دفعہ کے بارے میں شک ہے۔ اس لحاظ سے بھی وہ صحیح نہیں۔ اگر بالفرض تین دفعہ یہ لفظ ہوں تو آپ کے دور سے مراد صرف آپ کی حیات طیبہ تک کا دور ہوگا اور ’’ان کے بعد‘‘ سے مراد صحابہ ہوں گے جو آپ کے بعد زندہ رہے۔ صحابہ رضی اللہ عنہم کا دور ۱۱۰ھ تک رہا ہے۔ دوسرے سے مراد تابعین اور تیسرے سے مراد تبع تابعین ہوں گے۔ واللہ اعلم۔ (۲) ’’گواہیاں دیں گے‘‘ یعنی جھوٹی‘ تبھی تو ان سے گواہی نہیں لی جائے گی اور اگر زبردستی دیں گے تو مانی نہیں جائے گی۔ (۳) ’’موٹاپا عام ہوجائے گا‘‘ یعنی اکثر لوگ موٹے ہوں گے اور موٹا ہونے کو پسند کریں گے بلکہ موٹا ہونے کی کوشش کریں گے‘ یعنی عیش پرست ہوں گے۔ سہل پسند ہوں گے۔ کھانے پینے اور سونے پر خوب زور دیں گے۔ پست ہمت ہوں گے۔ غرض ناکارہ بن جائیں گے کیونکہ موٹاپے کو یہ سب چیزیں لازم ہیں۔ آپ کا مقصود بھی یہی چیز بتانا ہے کہ نہ صرف موٹاپا۔ واللہ اعلم۔ (۴) ’’ابوحمزہ ہے‘‘ امام نسائی رحمہ اللہ نے یہ وضاحت اس لیے پیش کی تاکہ التباس کا خطرہ دور ہوجائے کیونکہ امام شعبہ رحمہ اللہ سات ایسے آدمیوں سے روایت کرتے ہیں جن کی کنیت ابوحمزہ ہے اور ایک ایسے آدمی بھی روایت کرتے ہیں جن کی کنیت ابوحمزہ ہے‘ اس سند میں یہی آدمی ہے‘ اس لیے امام نسائی رحمہ اللہ نے وضاحت فرمادی ہے کہ یہ ان آدمیوں سے الگ شخص ہے جن کی کنیت ابوحمزہ ہے۔ اس کی کنیت ابوحمزہ ہے اور ناصر نصر بن عمران ہے۔ واللہ اعلم۔"}],[3810,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک ایسے شخص کے پاس سے گزرے جو ایک آدمی کو رسی میں باندھ کر کھینچے لے جا رہا تھا، آپ نے رسی کو لیا اور اسے کاٹ ڈالا اور فرمایا: \"یہ نذر ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی نذر اس طرح سے بھی ادا ہو جائے گی۔","الألباني: صحيح خ دون قوله إنه نذر",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک آدمی کے پاس سے گزر ے جو ایک دوسرے آدمی کو رسی باندھ کر کھینچ رہا تھا۔ آپ نے وہ رسی پکڑ کر کاٹ دی۔ وہ کہنے لگا: میں نے یہ نذر مانی تھی۔","f2":"ایسے کام کی نذر پوری کرنا ضروری ہے جو نیکی اور تقرب والا ہو۔ اس قسم کی فضول نذر جس سے سوائے مشقت اور ذلت کے کچھ حاصل نہ ہو‘ نہ نذر ماننے واے کو کوئی فائدہ ہو اور نہ کسی دوسرے کو‘ یہ لایعنی نذر ہے۔ اسے پورا نہیں کرنا چاہیے کیونکہ بے فائدہ ہے۔"}],[3811,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ایک آدمی کے پاس سے گزرے جو کعبے کا طواف کر رہا تھا، اور ایک آدمی اس کی ناک میں نکیل ڈال کر اسے کھینچ رہا تھا تو آپ صلی اللہ علیہ وسلم نے اسے اپنے ہاتھ سے کاٹ دیا پھر حکم دیا کہ وہ اسے اپنے ہاتھ سے پکڑ کر لے جائے۔ ابن عباس رضی اللہ عنہما کہتے ہیں: نبی اکرم صلی اللہ علیہ وسلم اس (آدمی) کے پاس سے گزرے، وہ کعبے کا طواف کر رہا تھا اور اس نے ایک آدمی کا ہاتھ ایک دوسرے آدمی سے تسمے سے یا دھاگے سے یا کسی اور چیز سے باندھ رکھا تھا تو آپ صلی اللہ علیہ وسلم نے اپنے ہاتھ سے اسے کاٹ ڈالا اور فرمایا: \"اسے اپنے ہاتھ سے پکڑ کر لے جاؤ۔\"","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ایک آدمی کے پاس سے گزرے جو کعبہ کا طواف کررہاتھا۔ اسے ایک اور انسان ا سکی ناک میں نکیل ڈال کر کھینچ رہا تھا۔ نبی اکرم صلی اللہ علیہ وسلم نے اپنے دستِ مبارک سے اسے کاٹ دیا اور اسے حکم دیا کہ اس کا ہاتھ پکڑ کر اسے چلا۔ اس روایت میں یہ لفظ بھی آتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم طواف کے دوران میں ایک آدمی کے پاس سے گزرے جس نے اپنا ہاتھ کسی دوسرے آدمی کے ساتھ رسی یا دھاگے وغیرہ کے ساتھ باندھ رکھا تھا‘ چنانچہ نبی اکرم صلی اللہ علیہ وسلم نے اپنے دستِ مبارک سے اس رسی کو کاٹ دیا اور فرمایا: ’’اسے ہاتھ پکڑ کر چلا۔‘‘","f2":"گلے‘ ناک یا ہاتھ کو رسی باندھ کر آدمی کو کھینچنا جانوروں کے ساتھ تشبیہ ہے۔ ان کے عاقل نہ ہونے کی وجہ سے ان کے گلے یا ناک وغیرہ میں رسی ڈالنی پڑتی ہے تاکہ انہیں قابو کیا جاسکے‘ جبکہ انسان عاقل ہے۔ اسے زبان یا زیادہ سے زیادہ ہاتھ سے سمجھایا جاسکتا ہے‘ لہٰذا رسی یا نکیل کی ضرورت نہیں بلکہ یہ جانوروں کے ساتھ مشابہت ہے اور انسانیت کی توہین ہے جسے دین فطرت کے آخری نبی کیسے گوارا فرماسکتے تھے؟ فِدَاہُ نَفْسِیْ وَرُوحِي وَأبِي وأمي صلی اللہ علیہ وسلم۔ دور جاہلیت میں لوگ ایسی نذریں مان لیا کرتے تھے۔ جن سے سوائے مشقت‘ تکلیف یا ذلت کے کچھ حاصل نہیں ہوتا۔ شریعتِ اسلامیہ نے ایسی تمام نذروں کو کالعدم قراردیا‘ یعنی نہ وہ مانی جائیں گی‘ اور نہ ان پر عمل کیا جائے گا‘ البتہ کفارہ ادا کرنا ہوگا۔"}],[3812,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی نافرمانی میں نذر نہیں، اور نہ ہی کسی ایسی چیز میں ہے جس کا ابن آدم مالک نہ ہو\"۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ کی نافرمانی اور انسان کی غیر مملوکہ چیز میں نذر ماننا غیر معتبر ہے۔‘‘","f2":"تفصیل کے لیے 3823 ح دیکھیں۔"}],[3813,"ثابت بن ضحاک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی دین اسلام کے سوا کسی دوسری ملت کی جھوٹی قسم کھائے گا تو وہ اسی طرح ہو گا جیسے اس نے کہا، اور جس نے اپنے آپ کو دنیا میں کسی چیز سے قتل کیا تو اسے قیامت کے دن اسی چیز سے عذاب دیا جائے گا، اور آدمی پر اس چیز کی نذر نہیں جس کا وہ مالک نہ ہو\"۔","الألباني: صحيح",{"u2":"حضرت ثاقب بن ضحاک رضی اللہ عنہ سے راویت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص دین اسلام کے علاوہ کسی اور دین کی قسم کھائے اور ہو بھی جھوٹا تو وہ اسی طرح ہوگا جس طرح اس نے (اپنے آپ کو) کہا۔ اور جو شخص دنیا میں کسی چیز سے خود کشی کرے‘ قیامت کے دن اسے اسی چیز کے ساتھ عذان دیا جائے گا۔ اور کسی شخص کے لیے اس نذر کو پورا کرنا جائزنہیں جو ا س نے اپنی غیر مملوکہ چیز کے بارے میں مانی ہو۔‘‘","f2":"تفصیل کے لیے ح نمبر 3801 دیکھیں۔"}],[3814,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ میری بہن نے نذر مانی کہ وہ بیت اللہ پیدل جائے گی، اس نے مجھے حکم دیا کہ میں اس کے لیے رسول اللہ صلی اللہ علیہ وسلم سے اس بارے میں مسئلہ پوچھوں، میں نے اس کے لیے نبی اکرم صلی اللہ علیہ وسلم سے مسئلہ پوچھا تو آپ نے فرمایا: \"وہ پیدل جائے اور سوار ہو کر (بھی) جائے\"۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ سے مروی ہے کہ میری بہن نے بیت اللہ تک پیدل جانے کی نذر مانی‘ پھر اس نے مجھ سے کہا کہ میں اس کے متعلق رسول اللہ صلی اللہ علیہ وسلم سے استفسار کروں‘ چنانچہ میں نے اس کے لیے نبی اکرم صلی اللہ علیہ وسلم سے یہ مسئلہ پوچھا تو آپ نے فرمایا: ’’پیدل بھی چلے اور سوار بھی ہو۔‘‘","f2":":(۱) پیدل جانے کا کوئی فائدہ تو نہیں اور پیدل جانا ممکن بھی ہے‘ لہٰذا یہ نذر پوری کرنی چاہیے ورنہ کفارہ ادا کرے۔ اس راویت میں کفارے کا ذکر نہیں مگر بعض دیگر روایات سے کفارے کا اثبات ہوتا ہے‘ مثلاً: ۳۸۴۶۔ (۲) ’’پیدل بھی چلے اور سوار بھی ہو‘‘ ایک مفہوم تو یہ ہے کہ وہ پیدل چلے جہاں تک چل سکے۔ جب عاجز آجائے تو سوار ہوجائے۔ اور ممکن ہے آپ کا مقصود یہ ہو کہ چاہے پیدل چلے‘ چاہے سوار ہو‘ البتہ سواری کی صورت میں کفارہ دینا ہوگا۔ گویا ایسی نذر بے فائدہ ہونے کی وجہ سے پوری کرنا ضروری نہیں‘ کفارہ دے سکتا ہے۔ پہلے معنی کی رو سے اسے طاقت کی حد تک چلنا ضروری ہے۔ واللہ اعلم۔ (۳) ایسی نذر کی صورت میں کہاں سے پیدل چلے؟ بعض فقہاء کے نزدیک گھر ہی سے پیدل چلے اور بعض کے نزدیک میقات سے احرام باندھنے کے بعد۔ پہلے معنی متبادر ہیں مگر بسا اوقات یہ ممکن نہیں‘ مثلاً: پاکستان والوں کے لیے۔"}],[3815,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے اپنی ایک بہن کے بارے میں پوچھا جس نے نذر مانی تھی کہ وہ دوپٹہ اوڑھے بغیر پیدل (حج کرنے) جائے گی۔ تو نبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اسے حکم دو کہ وہ اوڑھنی اوڑھ کر اور سوار ہو کر جائے اور تین دن کے روزے رکھ لے\"۔","الألباني: ضعيف",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ نے بتایا کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے اپنی ایک بہن کے بارے میں پوچھا جس نے نذر مانی تھی کہ وہ ننگے پاؤں‘ ننگے سر اور پیدل جائے گی۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’اسے کہو کہ سرڈھانپے اور سوار ہوجائے اور تین دن کے روزے رکھ لے۔‘‘"}],[3816,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ایک عورت نے سمندر کا سفر کیا اور نذر مانی کہ وہ ایک مہینہ روزے رکھے گی پھر وہ روزے رکھنے سے پہلے ہی مر گئی تو اس کی بہن نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر آپ سے اس کا ذکر کیا تو آپ نے اسے حکم دیا کہ \"وہ اس کی طرف سے روزے رکھے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے‘ انہوں نے فرمایا: ایک عورت سمندری سفر پر گئی۔ اس نے نذر مانی کہ (صحیح سلامت واپسی کی صورت میں) وہ ایک ماہ کے روزے رکھے گی۔ لیکن وہ روزے رکھنے سے قبل ہی فوت ہوگئی۔ اس کی بہن نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور یہ صورت حال آپ سے ذکر کی تو آپ نے حکم دیا کہ تو اس کی طرف سے روزے رکھ لے۔","f2":"معلوم ہوا کہ میت کے ذمے روزے کے (یا فرضی) روزے ہوں تو اس کے لواحقین اس کی طرف سے روزے رکھ سکتے ہیں۔ بشرطیکہ میت کو روزے رکھنے کا موقع ملا ہو لیکن وہ رکھ نہ سکا ہو۔ احناف کے نزدیک میت کی طرف سے روزے نہیں رکھے جاسکتے بلکہ روزوں کا فدیہ دیا جائے گا۔ مگر یہ اس صریح روایت کی خلاف ورزی ہے۔ ہاں یہ کہا جاسکتا ہے کہ اس کی طرف سے روزے رکھنا فرض نہیں‘ فدیہ بھی دیا جاسکتا ہے۔ واللہ اعلم۔"}],[3817,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ سعد بن عبادہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس نذر کے متعلق مسئلہ پوچھا جو ان کی ماں کے ذمہ تھی اور اسے پوری کرنے سے پہلے ہی ان کا انتقال ہو چکا تھا تو آپ نے فرمایا: \"ان کی طرف سے تم اسے پوری کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ حضرت سعد بن عبادہ رضی اللہ عنہ نے سول اللہ صلی اللہ علیہ وسلم نے سے ایک نذر کے بارے میں پوچھا جو ان کی والدہ کے ذمے تھی لیکن وہ اس کی ادائیگی سے پہلے فوت ہوگئی تھی۔ آپ نے فرمایا: ’’تم اس کی طرف سے ادا کردو۔‘‘","f2":"کسی راویت میں صراحت نہیں کہ وہ نذر کیا تھی؟ بعض حضرات نے ایک روایت سے استنباط کیا ہے کہ وہ نذر غلام آزاد کرنے کی تھی مگر اس روایت میں بھی صراحت نہیں کہ نذر آزاد کرنے کی تھی۔ اس میں صرف غلام آزاد کرنے کا ذکر ہے۔ ممکن ہے وہ غلام نذر کے کفارے میں آزاد کیا گیا ہو‘ نہ کہ بطور نذر۔ بعض نے روزے کہا ہے۔ واللہ اعلم۔ بہر صورت اگر میت نذر پوری کرنے کی وصیت کرجائے تو نذر پوری کرنا ورثاء پر فرض ہوگا ورنہ مستحب"}],[3818,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ سعد بن عبادہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے ایک نذر کے بارے میں مسئلہ پوچھا جو ان کی ماں کے ذمے تھی اور وہ اسے پوری کرنے سے پہلے ہی انتقال کر گئی تھیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے ان کی طرف سے تم پوری کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے‘ کہ انہوں نے فرمایا: حضرت سعد بن عبادہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے ایک نذر کے بارے میں پوچھا جو ان کی والدہ کے ذمے تھی مگر وہ اس کی ادائیگی سے پہلے فوت ہوگئی تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم اس کی طرف سے ادا کردو۔‘‘"}],[3819,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ سعد بن عبادہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے اور عرض کیا کہ میری ماں مر گئیں، ان کے ذمے ایک نذر تھی جو انہوں نے پوری نہیں کی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے ان کی جانب سے تم پوری کر دو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے‘ انہوں نے فرمایا: حضرت سعد بن عبادہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور کہا: میری والدہ فوت ہوگئی ہے۔ اس کے ذمے ایک نذر تھی جسے وہ ادا نہیں کرسکتی تھی۔ آپ نے فرمایا: ’’تم اس کی طرف سے ادا کردو۔‘‘","f2":"تفصیل کے لیے دیکھیے حدیث نمبر:3680‘3694۔"}],[3820,"عمر رضی اللہ عنہ سے روایت ہے کہ انہوں نے جاہلیت میں ایک رات کی نذر مانی تھی کہ وہ اس میں اعتکاف کریں گے، تو انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا تو \"آپ نے انہیں اعتکاف کرنے کا حکم دیا\" ۱؎۔\n§وضاحت\n۱؎: چونکہ یہ نذر ایک جائز چیز میں تھی اس لیے آپ نے اسے پوری کرنے کا حکم دیا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ اپنے والد عمر رضی اللہ عنہ سے روایت کرتے ہیں کہ ان کے ذمے جاہلیت میں ایک رات اعتکاف بیٹھنے کی نذر تھی۔ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا تو آپ نے انہیں (ایک رات) اعتکاف بیٹھنے کا حکم دیا۔","f2":"یہ نذر نیکی کی تھی‘ اس لیے آپ نے اسے پورا کرنے کاحکم فرمایا ورنہ کفر کے دوران میں احکام واجب نہیں ہوتے"}],[3821,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ عمر رضی اللہ عنہ کے ذمہ مسجد الحرام میں ایک رات اعتکاف کرنے کی نذر تھی، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس بارے میں سوال کیا تو آپ صلی اللہ علیہ وسلم نے انہیں اعتکاف کرنے کا حکم دیا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے‘ انہوں نے فرمایا کہ حضرت عمر رضی اللہ عنہ کے ذمے (دور جاہلیت میں) ایک رات مسجد حرام میں اعتکاف بیٹھنے کی نذر تھی۔ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے متعلق پوچھا تو آپ نے انہیں اعتکاف بیٹھنے کا حکم دیا۔"}],[3822,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ عمر رضی اللہ عنہ نے جاہلیت میں (مسجد الحرام میں) ایک دن کا اعتکاف اپنے اوپر واجب کر لیا تھا، انہوں نے اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے پوچھا تو \"آپ نے انہیں اس میں اعتکاف کرنے کا حکم دیا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ حضرت عمر رضی اللہ عنہ نے دور جاہلیت میں ایک دن اعتکاف بیٹھنے کی نذر مانی تھی۔ (مسلمان ہونے کے بعد) انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس بارے میں پوچھا تو آپ نے انہیں اعتکاف بیٹھنے کا حکم دیا۔","f2":"ایسی نذر جو کفر کی حالت میں مانی ہو اور اس میں اللہ تعالیٰ کی اطاعت ہو تو اسلام قبول کرنے کے بعد بھی وہ نذر پوری کی جائے گی۔"}],[3823,"کعب بن مالک رضی اللہ عنہ سے روایت ہے کہ جب ان کی توبہ قبول ہوئی تو رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: اللہ کے رسول! میں اللہ اور اس کے رسول کے نام پر صدقہ کر کے اپنے مال سے علیحدہ ہو جاتا ہوں، رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اپنا کچھ مال روک لو یہ تمہارے لیے بہتر ہو گا ۱؎\"۔ ابوعبدالرحمٰن نسائی کہتے ہیں: ہو سکتا ہے کہ زہری نے اس حدیث کو عبداللہ بن کعب اور عبدالرحمٰن دونوں سے سنا ہو اور انہوں نے ان (کعب رضی اللہ عنہ) سے روایت کی ہو ۲؎۔ اسی لمبی حدیث میں کعب رضی اللہ عنہ کی توبہ کا بھی ذکر ہے۔\n§وضاحت\n۱؎: یہ حدیث اگلے باب سے متعلق ہے، نساخ کی غلطی سے یہاں درج ہو گئی ہے، واللہ اعلم۔ ۲؎: زہری نے یہ حدیث: عبداللہ بن کعب، عبدالرحمٰن بن کعب، نیز عبدالرحمٰن بن عبداللہ بن کعب :(عن أبیہ عبداللہ بن کعب ) تینوں سے سنی ہے، دیکھئیے احادیث رقم: ۳۴۵۱-۳۴۵۶","الألباني: صحيح",{"u2":"حضرت کعب بن مالک رضی اللہ عنہ سے روایت ہے کہ جب ان کی توبہ قبول ہوئی تو انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے کہا: اے اللہ کے رسول! میں اپنے کل مال کو اللہ اور س کے رسول کی مرضی کے مطابق صدقے کرتے ہوئے اس سے لاتعلق ہونا چاہتا ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اپناکچھ مال رکھ لے۔ یہ تیرے لیے بہتر ہوگا۔‘‘\nامام ابو عبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ ممکن ہے زہری نے یہ حدیث عبداللہ بن کعب سے بھی سنی ہو اور ان سے (ان کے بھائی) عبدالرحمن بن کعب کے واسطے سے بھی۔ اس لمبی حدیث میں حضرت کعب بن مالک رضی اللہ عنہ کی توبہ کا ذکر ہے۔","f2":"(۱) امام زہری رحمہ اللہ یہ حدیث چار طریق سے بیان کرتے ہیں: ایک طریق میں وہ عبداللہ بن کعب سے بیان کرتے ہیں اور وہ اپنے والد کعب بن مالک رضی اللہ عنہ سے جیسا کہ اس حدیث کی سند میں ہے۔ دوسرے طریق میں عبدالرحمن بن کعب سے بیان کرتے ہیں جیسا کہ حدیث: ۳۸۵۵ میں ہے۔ تیسرے طریق میں عبدالرحمن بن عبداللہ بن کعب سے بیان کرتے ہیں‘ اور وہ اپنے والد عبداللہ بن کعب سے جیسا کہ حدیث: ۳۸۵۶ میں ہے اور چوتھے طریق میں بھی وہ عبدالرحمن بن عبداللہ بن کعب ہی سے بیان کرتے ہیں‘ لیکن یہاں عبدالرحمن آگے اپنے والد کی بجائے اپنے چچا عبیداللہ بن کعب رضی اللہ عنہ سے بیان کرتے ہیں جیسا کہ حدیث: ۳۸۵۷ میں ہے۔ واللہ اعلم۔ اس واقعے کا تعلق غزوئہ تبوک سے تھا۔ اس جنگ میں حضرت کعب رضی اللہ عنہ سے سستی ہوگئی۔ وہ شامل نہ ہوسکے۔ ان سے بائیکاٹ کیا گیا جو پچاس دن تک جاری رہا پھر ان کی توبہ کی قبولیت کا قرآن مجید میں اعلان کیا گیا۔ رَضِیَ اللّٰہُ عَنْہُ وَأَرْضَاہُ۔ (۲) یہ حدیث مذکورہ باب سے نہیں بلکہ آئندہ باب سے متعلق ہے۔ امام نسائی رحمہ اللہ نے بہت سے مقامات پر ایسے کیا ہے۔ جب ایک باب کے تحت بہت سی احادیث ہوں تو آخر میں ایک حدیث ایسی لاتے ہیں جو آئندہ باب سے تعلق رکھتی ہے۔ شاید یہ اشارہ کرنا مقصود ہو کہ آگے نیا باب آرہا ہے۔ یہ اسلوب صرف امام نسائی رحمہ اللہ نے اختیار کیا ہے۔"}],[3824,"کعب بن مالک رضی اللہ عنہ اپنا وہ واقعہ بیان کرتے ہیں کہ جب وہ غزوہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم سے پیچھے رہ گئے تھے، وہ کہتے ہیں: جب میں آپ صلی اللہ علیہ وسلم کے سامنے بیٹھا تو میں نے عرض کیا: اللہ کے رسول! میری توبہ میں سے یہ بھی ہے کہ میں اللہ اور اس کے رسول کو صدقہ کر کے اپنے مال سے الگ ہو جاؤں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اپنا کچھ مال اپنے لیے روک لو یہ تمہارے لیے بہتر ہو گا\"، میں نے عرض کیا: اچھا تو میں اپنا وہ حصہ روک لیتا ہوں جو خیبر میں ہے، یہ حدیث مختصر ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن کعب سے راویت ہے کہ انہوں نے (اپنے والد محترم) حضرت کعب بن مالک رضی اللہ عنہ کو اپنا واقعہ بیان کرتے ہوئے سنا‘ جب وہ غزوئہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم سے پیچھے رہ گئے تھے۔ انہوں نے فرمایا: جب میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے بیٹھا تو میں نے کہا: اے اللہ کے رسول! میری توبہ میں سے یہ بھی ہے کہ میں اپنے مال کو اللہ اور اس کے رسول کی رضا مندی کے لیے صدقہ کرتے ہوئے اپنے مال سے لا تعلق ہوجاؤں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اپنا کچھ مال رکھ لے۔ یہ تیرے لیے بہتر ہے۔‘‘ میں نے کہا: میں اپنی خیبر والی جائیداد رکھ لیتا ہوں۔ یہ روایت مختصر ہے۔","f2":"(۱) ’’آپ کے سامنے بیٹھا‘‘ یہ اس وقت کی بات ہے جب ان کی توبہ کی قبولیت کااعلان ہوگیا تھا اور وہ رسول اللہ صلی اللہ علیہ وسلم کی ملاقات وزیارت کو بے تابانہ حاضر ہوئے تھے۔ آخر پچاس دن بیت چکے تھے۔ (۲) ’’میری توبہ میں سے ہے‘‘ گویا انہوں نے جب توبہ کی تھی تو ساتھ نذر بھی مانی تھی کہ اگر میری توبہ قبول ہوگئی تو میں اپنا سارا مال صدقہ کردوں گا۔ اب آپ کے سامنے ذکر کیا تو آپ نے اصلاح فرمادی کہ سارا مال صدقہ کرنے کی ضرورت نہیں بلکہ کچھ مال اپنے پاس بھی رکھنا چاہیے تاکہ نذر ماننے والا محتاج ہی نہ ہوجائے۔ اس طرح یہ آئندہ کے لیے بھی دستور بن گیا کہ اگر کوئی شخص اپنا سارا مال صدقہ کرنے کی نذر مان لے تو وہ اپنی ضرورت کے مطابق مال رکھ سکتا ہے بلکہ اسے رکھنا چاہیے۔ اور اس حدیث کو مذکورہ باب کے تحت ذکر کرنے کی یہی وجہ ہے۔ واللہ اعلم۔"}],[3825,"کعب بن مالک رضی اللہ عنہ اپنا اس وقت کا واقعہ بیان کرتے ہیں کہ جب وہ غزوہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم سے پیچھے رہ گئے تھے۔ (کہتے ہیں:) میں نے عرض کیا: اللہ کے رسول! میری توبہ میں سے یہ بھی ہے کہ اللہ اور اس کے رسول کو صدقہ کر کے اپنے مال سے الگ ہو جاؤں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"تم اپنا (کچھ) مال اپنے لیے روک لو یہ تمہارے لیے بہتر ہو گا\"، میں نے عرض کیا: تو میں اپنے پاس اپنا وہ حصہ روک لیتا ہوں جو خیبر میں ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن کعب بن مالک سے راویت ہے‘ انہوں نے فرمایا: میں نے (اپنے والد محترم) حضرت کعب بن مالک رضی اللہ عنہ کو اپنا واقعہ بیان فرماتے ہوئے سنا‘ جب وہ غزوئہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم سے پیچھے رہ گئے تھے۔ انہوں نے فرمایا: میں نے کہا: اے اللہ کے رسول! میری توبہ میں سے یہ بھی ہے کہ میں اپنا مال اللہ اور اس کے رسول کے لیے صدقہ کرتے ہوئے اس سے لاتعلق ہوجاؤں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اپنا کچھ مال رکھ لے۔‘‘ یہ تیرے لیے بہتر ہوگا۔‘‘ میں نے کہا: میں اپنا خیبر والا حصہ رکھ لیتا ہوں۔","f2":"(۱) ’’اللہ اور اس کے رسول کے لیے‘‘ کیونکہ اس موقع پر اللہ اور اس کا رسول دونوں ناراض ہوگئے تھے‘ لہٰذا دونوں کو راضی کرنا مقصود تھا۔ اللہ تعالیٰ کے علاوہ کسی دوسرے کو راضی کرنا منع نہیں‘ مثلاً: والدین کی رضا مندی کا حصول۔ ویسے بھی اللہ تعالیٰ اور رسول اللہ صلی اللہ علیہ وسلم کی رضا مندی اور ناراضی اکٹھی ہی ہوتی ہے۔ اللہ راضی تو رسول بھی راضی۔ اللہ ناراض تو رسول بھی ناراض‘ البتہ کسی عبادت‘ مثلاً: نماز‘ روزہ وغیرہ میں صرف اللہ تعالیٰ کی رضا وثواب ہی مقصود ہونا چاہیے۔ (۲) صدقہ وصول کرنے والے کو صدقہ دینے والے کی طاقت بھی مدنظر رکھنی چاہیے‘ اس پر اتنا بوجھ ڈالا جائے جتنا ہو اٹھا سکے۔"}],[3826,"کعب بن مالک رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! اللہ تعالی نے مجھے صرف سچ کی وجہ سے نجات دی تو میری توبہ میں سے یہ ہے کہ اللہ اور اس کے رسول کو صدقہ کر کے اپنے مال سے الگ ہو جاؤں۔ آپ نے فرمایا: \"اپنا کچھ مال اپنے پاس روک لو یہ تمہارے لیے بہتر ہو گا\"، میں نے عرض کیا: تو میں اپنا وہ حصہ روک لیتا ہوں جو خیبر میں ہے۔","الألباني: صحيح",{"u2":"حضرت کعب بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ میں نے کہا: اے اللہ کے رسول! اللہ تعالیٰ نے مجھے سچ بولنے کی وجہ سے نجات دی ہے‘ نیز میری توبہ میں سے یہ بھی ہے کہ میں اپنا سارا مال اللہ اور اس کے رسول کی رضا مندی کی خاطر صدقہ کرتے ہوئے اس سے لاتعلق ہوجاؤں۔ آپ نے فرمایا: ’’اپنا کچھ مال رکھ لے‘ یہ تیرے لیے بہتر ہوگا۔‘‘ میں نے کہا: ٹھیک ہے۔ میں اپنا خیبر والا حصہ رکھ لیتا ہوں۔","f2":"(۱) ’’خیبر والا حصہ‘‘ یعنی غزوئہ خیبر کی غنیمت سے جو مجھے میرا حصہ ملا تھا۔ اور وہ زمین وباغ کی صورت میں تھا۔ (۲) اللہ اور اس کے رسول کی طرف سے دی گئی رخصت کو قبول کرنا چاہیے‘ خواہ وہ رخصت سفری نمازوں میں ہو یا دیگر معاملات میں‘ اسی میں سعادت ہے۔"}],[3827,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ خیبر کے سال ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، ہمیں مال ۱؎، سامان اور کپڑوں کے علاوہ کوئی غنیمت نہ ملی تو بنو ضبیب کے رفاعہ بن زید نامی ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم کو مدعم نامی ایک کالا غلام ہدیہ کیا، رسول اللہ صلی اللہ علیہ وسلم نے وادی قری کا رخ کیا، یہاں تک کہ جب ہم وادی قری میں پہنچے تو مدعم رسول اللہ صلی اللہ علیہ وسلم کا کجاوا اتار رہا تھا کہ اسی دوران اچانک ایک تیر آ کر اسے لگا اور اسے قتل کر ڈالا، لوگوں نے کہا کہ تمہیں جنت مبارک ہو، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہرگز نہیں، قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے! وہ کملی جو اس نے غنیمت کے مال سے خیبر کے روز لے لی تھی (اور مال تقسیم نہ ہوا تھا) اس کے سر پر آگ بن کر دہک رہی ہے\"۔ جب لوگوں نے یہ بات سنی تو ایک شخص چمڑے کا ایک یا دو تسمہ رسول اللہ صلی اللہ علیہ وسلم کے پاس لے کر آیا تو آپ نے فرمایا: \"یہ ایک یا دو تسمے آگ کے ہیں\"۔\n§وضاحت\n۱؎: اسی لفظ میں باب سے مطابقت ہے، کیونکہ ابوہریرہ رضی اللہ عنہ نے اموال کے لفظ سے زمینیں :(آراضی ) مراد لی ہیں :(خیبر میں زیادہ زمینیں مال غنیمت میں ہاتھ آئی تھیں ) اس سے معلوم ہوا کہ اگر کوئی صرف \" مال \" کی نذر مانے تو اس مال میں زمین بھی داخل گی۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے‘ انہوں نے فرمایا: ہم غزوئہ خیبر والے سال رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے تو ہمیں غنیمت میں صرف مال‘ گھریلو سامان اور کپڑے وغیرہ ہی ملے تھے۔ بنوضبیب کے ایک آدمی حضرت رفاعہ بن زید رضی اللہ عنہ نے آپ کو ایک کالا غلام بطور تحفہ دیا۔ اس کا نام مدعم تھا۔ رسول اللہ صلی اللہ علیہ وسلم وادئی قریٰ کی جانب چلے۔ جب ہم وادئی قریٰ میں پہنچے تو مدعم رسول اللہ صلی اللہ علیہ وسلم (کی سواری) کا پالان وغیرہ اتاررہا تھا کہ ایک تیر آیا۔ اسے لگا اور اسے ختم کردیا۔ لوگ کہنے لگے: اسے جنت مبارک ہو۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہرگز نہیں‘ اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! بلاشبہ وہ چادر جو اس نے غزوئہ خیبر کے دن (میری اجازت کے بغیر) مال غنیمت سے اٹھائی گئی تھی‘ اس پر آگ بن کر بھڑک رہی ہے۔‘ جب لوگوں نے یہ بات سنی تو کوئی آدمی ایک تسمہ‘ کوئی دو تسمے لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچ گیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ ایک دو تسمے بھی آگ کا سبب بن سکتے ہیں۔‘‘","f2":"(۱) غزوئہ خیبر میں رسول اللہ صلی اللہ علیہ وسلم کو غنیمت میں زمینں تو قطعاً ملی تھیں جبکہ اس حدیث میں زمین کا صراحتاً ذکر نہیں بلکہ لفظ ’’اموال‘‘ ذکر ہے۔ لازمی بات ہے کہ اموال سے مراد زمین ہی ہوگی اور یہی باب کا مقصود ہے کہ اگر مال کی نذر مانے تو زمین بھی اس میں داخل ہوگی۔ سابقہ روایات جن میں کعب بن مالک رضی اللہ عنہ کی نذر کا ذکر ہے‘ وہ بھی اس مقصود پر دلالت کرتی ہیں کیونکہ ان میں مال صدقہ کرنے ہی کی نذر تھی‘ بعد میں حضرت کعب نے خیبر کی زمین کو اس سے مستثنیٰ کیا تھا۔ معلوم ہوا کہ مال کی نذر میں زمین بھی شامل تھی۔ (۲) ’’جنت مبارک ہو‘‘ بظاہر کیونکہ وہ سفر جہاد کے دوران میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت کرتے ہوئے کسی کافر کے تیر سے شہید ہوا تھا۔ (۳) ’’سبب بن سکتے ہیں‘‘ اگر خیانت کے ساتھ حاصل کیے جائیں اور بیت المال میں جمع نہ کرائے جائیں‘ یعنی معمولی اشیاء میں خیانت عذاب کا ذریعہ بن سکتی ہے۔"}],[3828,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے قسم کھائی اور ان شاءاللہ کہا تو اس نے استثناء کر لیا\" ۱؎۔\n§وضاحت\n۱؎: یعنی اگر اس نے قسم پوری نہیں کی تو بھی کوئی حرج نہیں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے قسم کھاتے وقت ان شاء اللہ کہہ دیا‘ اس نے اختیار حاصل کرلیا۔‘‘"}],[3829,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ انہوں نے اپنی بیوی کو حیض کی حالت میں طلاق دے دی تو عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے یہ کہہ کر کہ عبداللہ نے اپنی بیوی کو حالت حیض میں طلاق دے دی ہے مسئلہ پوچھا (کہ کیا اس کی طلاق صحیح ہوئی ہے) ؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"عبداللہ سے کہو(طلاق ختم کر کے) اسے لوٹا لے (یعنی اپنی بیوی بنا لے) پھر اسے اپنے اس حیض سے پاک ہو لینے دے، پھر جب وہ دوبارہ حائضہ ہو اور اس حیض سے پاک ہو جائے تو وہ اگر اسے چھوڑ دینا چاہے تو اسے جماع کرنے سے پہلے چھوڑ دے اور اگر اسے رکھنا چاہے تو اسے رکھ لے (اور اس سے اپنی ازدواجی زندگی بحال کرے) یہ ہے وہ عدت جس کے مطابق اللہ عزوجل نے عورتوں کو طلاق دینے کا حکم دیا ہے\"۔\nعبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے قسم کھائی اور \"ان شاءاللہ\" کہا تو اس نے استثناء کر لیا\"۔\nاسید بن ظہیر رضی اللہ عنہ کہتے ہیں کہ ہمارے پاس رافع بن خدیج رضی اللہ عنہ آئے تو انہوں نے کہا، اور میں اس (ممانعت کے راز) کو سمجھ نہیں سکا، پھر انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے تمہیں ایک ایسی بات سے روک دیا ہے جو تمہارے لیے سود مند تھی، لیکن رسول اللہ صلی اللہ علیہ وسلم کی اطاعت تمہارے لیے بہتر ہے اس چیز سے جو تمہیں فائدہ دیتی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے تمہیں «حقل» سے روکا ہے۔ اور «حقل» کہتے ہیں: تہائی یا چوتھائی پیداوار کے بدلے زمین کو بٹائی پر دینا۔ لہٰذا جس کے پاس زمین ہو اور وہ اس سے بے نیاز ہو تو چاہیئے کہ وہ اسے اپنے بھائی کو دیدے، یا اسے ایسی ہی چھوڑ دے، اور آپ نے تمہیں مزابنہ سے روکا ہے۔ مزابنہ یہ ہے کہ آدمی بہت سارا مال لے کر کھجور کے باغ میں جاتا ہے اور کہتا ہے کہ اس سال کی اس مال کو (یعنی پاس میں موجود کھجور کو)اس سال کی (درخت پر موجود) کھجور کے بدلے اتنے اتنے وسق کے حساب سے لے لو۔","الألباني: صحيح",{"u2":"حصرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جس نے قسم کھاتے وقت ان شاء اللہ‘ کہہ دیا اس نے قسم پورا کرنے سے استثنا حاصل کر لیا‘‘"}],[3830,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں اپنی بیوی کو حیض کی حالت میں طلاق دے دی تو عمر بن خطاب رضی اللہ عنہ نے اس کے متعلق رسول اللہ صلی اللہ علیہ وسلم سے مسئلہ پوچھا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عبداللہ سے کہو کہ اس سے رجوع کر لے (یعنی طلاق ختم کر کے اسے اپنی بیوی بنا لے) پھر اسے روکے رکھے جب تک کہ وہ حیض سے پاک نہ ہو جائے پھر اسے حیض آئے پھر پاک ہو (جب وہ دوبارہ حیض سے پاک ہو جائے) تو چاہے تو اسے روک لے اور چاہے تو اسے چھونے (اس کے پاس جانے اور اس سے صحبت کرنے) سے پہلے اسے طلاق دیدے۔ یہی وہ عدت ہے جسے ملحوظ رکھتے ہوئے اللہ عزوجل نے عورت کو طلاق دینے کا حکم دیا ہے\"۔\nعبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی بات پر قسم کھائی اور \"ان شاءاللہ\" کہا تو اب اسے اختیار ہے چاہے تو قسم پوری کرے اور چاہے تو نہ کرے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے کسی چیز پر قسم کھائی اور ساتھ ہی ان شاء اللہ کہہ دیا تو اسے اختیار ہے۔ چاہے تو اسے پورا کرے‘ چاہے پورا نہ کرے۔‘‘"}],[3831,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سلیمان بن داود علیہ السلام نے (قسم کھا کر) کہا: آج رات میں نوے بیویوں کے پاس جاؤں گا، ان میں سے ہر کوئی ایک سوار کو جنم دے گی جو اللہ کے راستے میں جہاد کرے گا، تو ان کے ساتھی نے ان سے کہا: \"ان شاءاللہ\" (اگر اللہ نے چاہا) مگر خود انہوں نے نہیں کہا، پھر وہ ان تمام عورتوں کے پاس گئے لیکن ان میں سوائے ایک عورت کے کوئی بھی حاملہ نہ ہوئی اور اس نے بھی ایک ادھورے بچے کو جنم دیا، قسم ہے اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! اگر انہوں نے \"ان شاءاللہ\" کہا ہوتا تو وہ تمام بیٹے اللہ کی راہ میں سوار ہو کر جہاد کرتے\" ۱؎۔\n§وضاحت\n۱؎: معلوم ہوا کہ قسم کھانے والے نے اگر بذات خود \" ان شاءاللہ \" نہیں کہا ہے بلکہ کسی اور نے کہا ہے تو یہ استثناء قسم کھانے والے کے حق میں مفید نہ ہو گا :(یعنی: اگر قسم توڑی تو حانث ہو جائے گا )۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک دفعہ حضرت سلیمان بن داود علیہ السلام نے فرمایا: میں رات کو اپنی نوے (۹۰) عورتوں کے پاس ضرور جاؤں گا۔ ان میں سے ہر ایک شہسوار جنے گی جو اللہ تعالیٰ کے راستے میں جہاد کرے گا۔ آپ کے ساتھی نے آپ سے (بطور تلقین) کہا: ان شاء اللہ‘ لیکن آپ نے ان شاء اللہ نہ کہا‘ پھر آپ ان سب عورتوں کے پاس گئے لیکن ان میں سے کسی کو بھی حمل نہ ٹھہرا سوائے ایک عورت کے۔ اس نے بھی ناقص بچہ جنا۔ قسم اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! اگر وہ ان شاء اللہ کہہ دیتے تو سب بچے شہسوار بن کر اللہ تعالیٰ کے راستے میں جہاد کرتے۔‘‘","f2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک دفعہ حضرت سلیمان بن داود علیہ السلام نے فرمایا: میں رات کو اپنی نوے (۹۰) عورتوں کے پاس ضرور جاؤں گا۔ ان میں سے ہر ایک شہسوار جنے گی جو اللہ تعالیٰ کے راستے میں جہاد کرے گا۔ آپ کے ساتھی نے آپ سے (بطور تلقین) کہا: ان شاء اللہ‘ لیکن آپ نے ان شاء اللہ نہ کہا‘ پھر آپ ان سب عورتوں کے پاس گئے لیکن ان میں سے کسی کو بھی حمل نہ ٹھہرا سوائے ایک عورت کے۔ اس نے بھی ناقص بچہ جنا۔ قسم اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! اگر وہ ان شاء اللہ کہہ دیتے تو سب بچے شہسوار بن کر اللہ تعالیٰ کے راستے میں جہاد کرتے۔‘‘"}],[3832,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نذر کا کفارہ وہی ہے جو قسم کا کفارہ ہے\" ۱؎۔\n§وضاحت\n۱؎: قسم کے کفارے کا ذکر سورۂ مائدہ کی اس آیت میں ہے «لا يؤاخذكم الله باللغو في أيمانكم ولكن يؤاخذكم بما عقدتم الأيمان فكفارته إطعام عشرة مساكين من أوسط ما تطعمون أهليكم أو كسوتهم أو تحرير رقبة فمن لم يجد فصيام ثلاثة أيام ذلك كفارة أيمانكم إذا حلفتم واحفظوا أيمانكم كذلك يبين الله لكم آياته لعلكم تشكرون» \" اللہ تعالی تمہاری قسموں میں لغو قسم پر تم سے مواخذہ نہیں فرماتا، لیکن مواخذہ اس پر فرماتا ہے کہ تم جن قسموں کو مضبوط کر دو۔ اس کا کفارہ دس محتاجوں کو کھانا دینا ہے اوسط درجے کا جو اپنے گھر والوں کو کھلاتے ہو، یا ان کو کپڑا دینا یا ایک غلام یا لونڈی آزاد کرنا ہے اور جس کو مقدور نہ ہو تو تین دن کے روزے ہیں۔ یہ تمہاری قسموں کا کفارہ ہے جب کہ تم قسم کھا لو اور اپنی قسموں کا خیال رکھو ! اسی طرح اللہ تعالی تمہارے واسطے اپنے احکام بیان فرماتا ہے تاکہ تم شکر کرو \" :(سورة المائدة: 89 )۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’نذر کا کفارہ (وہی ہے جو) قسم کاکفارہ ہے۔‘‘","f2":"قسم کا کفارہ قرآن مجید میں صراحتاً مذکور ہے اور وہ ہے: دس مسکینوں کو کھانا کھلانا یا کپڑے پہنانا یا غلام کی آزادی۔ اگر ان تینوں م میں سے کسی کی طاقت نہ ہو تو پھر تین روزے رکھنا ہوں گے۔ اور یہی نذر کا کفارہ ہے۔ کفارے میں ترتیب ضروری نہیں بلکہ نو نسا عمل آسانی کا باعث ہوکیا جاسکتا ہے۔ اگر نیک کام کی نذر ہو اور اسے پورا کرنے کی استطاعت ہو تو نذر ہی پوری کرنی ہوگی۔ کفارہ اس صورت میں ہے جب نذر پوری کرنا ممکن نہ ہو یا نذر معصیت کی ہو۔"}],[3833,"زبیدی کہتے ہیں: امام زہری سے پوچھا گیا: عدت والی طلاق کس طرح ہوتی ہے؟ (اشارہ ہے قرآن کریم کی آیت: «فطلقوهن لعدتهن» (الطلاق: 1) کی طرف) تو انہوں نے کہا: سالم بن عبداللہ بن عمر نے انہیں بتایا ہے کہ عبداللہ بن عمر رضی اللہ عنہما نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں اپنی بیوی کو حالت حیض میں طلاق دی تھی، اس بات کا ذکر عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ صلی اللہ علیہ وسلم یہ سن کر غصہ ہوئے اور فرمایا:\"اسے رجوع کر لینا چاہیئے، پھر اسے روکے رکھے رہنا چاہیئے یہاں تک کہ (پھر) اسے حیض آئے اور وہ حیض سے پاک ہو جائے، پھر اگر اسے طلاق دے دینا ہی مناسب سمجھے تو طہارت کے ایام میں طلاق دیدے ہاتھ لگانے سے پہلے\"۔ عدت والی طلاق کا یہی طریقہ ہے جیسا کہ اللہ عزوجل نے آیت نازل فرمائی ہے۔ عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں: میں نے اسے لوٹا لیا اور جو طلاق میں اسے دے چکا تھا اسے بھی شمار کر لیا (کیونکہ ان کے خیال میں وہ طلاق اگرچہ سنت کے خلاف اور حرام تھی پروہ پڑ گئی تھی)۔\nام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت (گناہ کے کاموں) میں نذر نہیں\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’گناہ والی نذر پوری نہیں کرنی چاہیے۔‘‘"}],[3834,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت (گناہوں کے کاموں) میں نذر نہیں، اور اس کا کفارہ قسم کا کفارہ ہے\"۱؎۔\n§وضاحت\n۱؎: یعنی اگر کسی نے معصیت کی نذر مانی ہے تو وہ اسے پوری نہیں کرے گا البتہ اس کا کفارہ ضرور ادا کرے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ نے فرمایا: ’’اللہ کی نافرمانی والی نذر پوری نہیں کرنی چاہیے۔ ایسی نذر کا کفارہ قسم کے کفارے کی طرح ہے۔‘‘"}],[3835,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت (گناہوں کے کاموں) میں نذر نہیں، اور اس کا کفارہ قسم کا کفارہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کی نافرمانی والی نذر معتبر نہیں اور اس کا کفارہ قسم والا کفارہ ہے۔‘‘"}],[3836,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت (گناہوں کے کاموں) میں نذر نہیں، اور اس کا کفارہ قسم کا کفارہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’معصیت والی نذر پوری نہ کی جائے (بلکہ اس کا کفارہ دیا جائے) اور اس کا کفارہ قسم والا ہے۔‘‘"}],[3837,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت (گناہوں کے کاموں) میں نذر نہیں اور اس کا کفارہ قسم کا کفارہ ہے\"۔ ابوعبدالرحمٰن نسائی کہتے ہیں: کہا گیا ہے کہ زہری نے اسے ابوسلمہ سے نہیں سنا ۱؎۔\n§وضاحت\n۱؎: لیکن اگلی روایت میں زہری کے ابوسلمہ سے سننے کی صراحت موجود ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’معصیت کی نذر معتبر نہیں اور اس کا کفارہ قسم کے کفارے کی طرح ہے۔‘‘\nامام ابو عبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ کہا گیا ہے کہ امام زہری نے حضرت ابو سلمہ سے یہ روایت نہیں سنی۔","f2":"اس روایت کی سند میں جیسا کہ امام صاحب نے فرمایا: ’انقطاع ہے لیکن شواہد کی بنا پر یہ حدیث صحیح ہے۔"}],[3838,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت (گناہوں کے کاموں) میں نذر نہیں اور اس کا کفارہ قسم کا کفارہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’گناہ کی نذر پوری نہیں کرنی چاہیے (بلکہ اس میں کفارہ ہے) اور اس کا کفارہ قسم والا ہے۔‘‘"}],[3839,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت (گناہوں کے کاموں) میں نذر نہیں اور اس کا کفارہ قسم کا کفارہ ہے\"۔ ابوعبدالرحمٰن نسائی کہتے ہیں: \"سلیمان بن ارقم\" متروک الحدیث راوی ہے، واللہ اعلم، اس حدیث کے سلسلے میں یحیی بن ابی کثیر کے تلامذہ میں سے کئی ایک نے سلیمان بن ارقم کی مخالفت کی ہے ۱؎۔\n§وضاحت\n۱؎: یحیی بن ابی کثیر کے تلامذہ میں سے سلیمان بن ارقم جو متروک الحدیث ہیں نے یحیی سے حدیث کی روایت میں ثقافت کی مخالفت کی ہے، لیکن اصل حدیث دوسرے رواۃ سے ثابت ہے، اور یہ مخالفت بعد کی سندوں میں ظاہر ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کی\nنافرمانی والی نذر پوری نہ کی جائے (بلکہ اس کا کفارہ دیا جائے) اور ایسی نذر کا کفارہ قسم کے کفارے جیسا ہے۔‘‘\nامام ابو عبدالرحمن (نسائی) رحمہ اللہ فرماتے ہیں: (راوئی حدیث) سلیمان بن ارقم وتروک الحدیث ہے۔ واللہ اعلم۔ اس حدیث میں یحییٰ بن ابی کثیر کے کئی ایک شاگردوں نے اس کی مخالفت کی ہے۔","f2":"مخالفت یہ ہے کہ یحییٰ بن ابی کثیر کے باقی شاگرد ایس عمران بن حصی رضی اللہ عنہ کی مسند بناتے ہیں جبکہ سلیمان بن ارقم نے اسے سیدہ عائشہ رضی اللہ عنہا کی مسند بنایا ہے۔ سلیمان بن ارقسم متروک الحدیث ہے جس کی بنا پر یہ راویت سنداً ضعیف ہے لیکن شواہد کی بنا پر صحیح اور قابل عمل ہے۔"}],[3840,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت (گناہ کے کاموں) کی نذر نہیں، اور اس کا کفارہ قسم کا کفارہ ہے\"۔","الألباني: صحيح لغيره",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے راویت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’گناہ کی نذر معتبر نہیں اور اس کا کفارہ قسم کے کفارے کے برابر ہے۔‘‘"}],[3841,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت (گناہ کے کام) میں نذر نہیں، اور اس کا کفارہ قسم کا کفارہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’معصیت کی نذر معتبر نہیں اور اس کا کفارہ قسم والا کفارہ ہے۔‘‘"}],[3842,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"غضب کی نذر نہیں، اور اس کا کفارہ قسم کا کفارہ ہے\"۔ ابوعبدالرحمٰن کہتے ہیں: محمد بن زبیر ضعیف ہیں، ان جیسے سے حجت قائم نہیں ہوتی اور اس حدیث کے سلسلے میں ان کے متعلق اختلاف کیا گیا ہے۔","الألباني: ضعيف",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’غصے میں آکر مانی ہوئی نذر معتبر نہیں اور اس کا کفارہ قسم کے کفارے کی طرح ہے۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ فرماتے ہیں: (راوئی حدیث) محمد بن زبیر ضعیف ہے‘ ایسا شخص حجت نہیں ہوتا‘ ویسے بھی اس حدیث میں اس پر اختلاف کیا گیا ہے۔"}],[3843,"عمران رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"غضب کی نذر نہیں، اور اس کا کفارہ قسم کا کفارہ ہے\"۔","الألباني: ضعيف",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’غصے کی حالت میں نذر معتبر نہیں اور اس کا کفارہ کفارئہ قسم ہے۔‘‘"}],[3844,"عمران رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"غضب کی نذر نہیں، اور اس کا کفارہ قسم کا کفارہ ہے\"۔ کہا گیا ہے کہ (محمد کے والد) زبیر نے اس حدیث کو عمران بن حصین سے نہیں سنا۔\n§وضاحت\n۱؎: اس کی دلیل اگلی روایت ہے۔","الألباني: ضعيف",{"u2":"حضرت عمران رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’غصے کی حالت میں نذر درست نہیں‘ البتہ اس کا کفارہ قسم والا ہے۔‘‘ کہا گیا ہے کہ زبیر نے یہ حدیث حضرت عمران بن حصین رضی اللہ عنہ سے نہیں سنی۔‘‘"}],[3845,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"نذر کی دو قسمیں ہیں: جو نذر اللہ کی اطاعت کی ہو تو وہ اللہ کے لیے ہے اور اسے پورا کرنا ہے اور جو نذر اللہ کی معصیت کی ہو تو وہ شیطان کی ہے اور اسے پورا نہیں کرنا ہے اور اس کا کفارہ وہی ہو گا جو قسم کا ہوتا ہے\"۔","الألباني: صحيح",{"u2":"اہل بصرہ میں سے ایک شخص سے راویت ہے‘ اس نے کہا: میں حضرت عمران بن حصین رضی اللہ عنہ کے پاس رہا۔ انہوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’نذر دوطرح کی ہوتی ہے: جو نذر اللہ تعالیٰ کی اطاعت کے بارے میں ہو‘ وہ تو اللہ کے لیے معتبر ہوگی اور اسے پورا کرنا چاہیے اور جو نذر اللہ تعالیٰ کی نافرمانی کے بارے میں ہو‘ وہ شیطان کام ہے۔ اسے پورا نہیں کیا جائے گا‘ البتہ اس کاکفارہ قسم کے کفارے کی طرح ہوگا۔‘‘"}],[3846,"زبیر حنظلی سے روایت ہے کہ ایک شخص نے ان سے بیان کیا کہ اس نے عمران بن حصین رضی اللہ عنہما سے ایک ایسے شخص کے بارے میں پوچھا، جس نے یہ نذر مانی کہ وہ اپنے قبیلے کی مسجد میں نماز میں حاضر نہیں ہو گا، تو عمران رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"غضب کی کوئی نذر نہیں ہوتی اور اس کا کفارہ قسم کا کفارہ ہے\"۔","الألباني: ضعيف",{"u2":"ایک آدمی نے حضرت عمران بن حصین رضی اللہ عنہ سے اس شخص کے بارے میں پوچھا جس نے نذر مان لی تھی کہ میں اپنی قوم کی مسجد میں نماز پڑھنے نہیں جاؤں گا۔ حضرت عمران نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ’’غصے کی حالت میں نذر معتبر نہیں‘ البتہ اس کا کفارہ قسم ہے۔‘‘"}],[3847,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت کی کوئی نذر نہیں، اور نہ ہی غضب میں، اور اس کا کفارہ قسم کا کفارہ ہے\"۔","الألباني: ضعيف",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے راویت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’غصے اور نافرمانی کی نذر معتبر نہیں اور اس کا کفارہ قسم کے کفارے جیسا ہے۔‘‘"}],[3848,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت میں نذر نہیں، اور اس کا کفارہ قسم کا کفارہ ہے\"۔ منصور بن زاذان کی روایت کے الفاظ اس سے مختلف ہیں (ان کی روایت آگے آ رہی ہے)۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’نافرمانی والی نذر درست نہیں اور اس کا کفارہ قسم کے کفارے جیسا ہے۔‘‘\nالفاظ حدیث میں منصور بن زاذان نے محمد بن زبیر کی مخالفت کی ہے۔"}],[3849,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"آدمی کی ایسی چیزوں میں نذر نہیں، جن کا اسے اختیار نہیں اور نہ ہی اللہ کی معصیت میں نذر ہے\"۔ علی بن زید نے منصور کی مخالفت کی ہے اور اسے بسند حسن بصری عن عبدالرحمٰن بن سمرہ سے روایت کی ہے۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’انسان اس چیز میں نذر نہیں مان سکتا جس کا وہ مالک نہیں اور نہ اللہ تعالیٰ کی نافرمانی کی نذر مان سکتا ہے۔‘‘\nعلی بن زید نے منصور بن زاذان کی مخالفت کی ہے‘ اس نے یہ روایت بواسطئہ حسن‘ حضرت عبدالرحمن بن سمرہ رضی اللہ عنہ سے بیان کی ہے۔","f2":"البتہ اگر نذر مان لے تو دونوں صورتوں میں نذر پوری کرنا منع ہے۔ کفارہ دینا پڑے گا جس طرح پیچھے گزرا"}],[3850,"عبدالرحمٰن بن سمرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"معصیت میں کوئی نذر نہیں اور نہ ہی کسی ایسی چیز میں کوئی نذر ہے جس کا آدمی کو اختیار نہیں\"۔ ابوعبدالرحمٰن نسائی کہتے ہیں: علی بن زید ضعیف ہیں اور اس حدیث میں غلطی ہوئی ہے اور صحیح عمران بن حصین رضی اللہ عنہما ہے اور دوسری سند سے یہ حدیث عمران بن حصین رضی اللہ عنہما سے روایت کی گئی ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت عبدالرحمن بن سمرہ رضی اللہ عنہ سے راویت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’نافرمانی کی نذر معتبر نہیں کہ اور نہ اس چیز کی جس کا وہ مالک نہیں۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ فرماتے ہیں علی بن زید ضعیف راوی ہے۔ اور (اس کی بیان کردہ) یہ حدیث خطا ہے‘ جبکہ درست (عبدالرحمن بن سمرہ کے بجائے) عمران بن حصین ہی ہے‘ نیز حضرات عمران بن حصین رضی اللہ عنہ سے یہ روایت ایک اور سند سے بھی بیان کی گئی ہے۔"}],[3851,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معصیت میں کوئی نذر نہیں اور نہ ہی ایسی چیز میں کوئی نذر ہے جس کا آدمی کو اختیار نہیں\"۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’نافرمانی کی نذر پور نہ کی جائے اور نہ اس چیز کی جس کا وہ انسان مالک نہیں۔‘‘"}],[3852,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک شخص کو دیکھا کہ وہ دو آدمیوں کے بیچ میں ان کے کندھے پر ہاتھ رکھ کر چل رہا ہے، آپ نے فرمایا:\"یہ کیا ہے؟\" لوگوں نے عرض کیا: اس نے نذر مانی ہے کہ وہ بیت اللہ تک پیدل چل کر جائے گا، آپ نے فرمایا: \"اس طرح اپنی جان کو تکلیف دینے کی اللہ کو ضرورت نہیں، اس سے کہو کہ سوار ہو کر جائے\" ۱؎۔\n§وضاحت\n۱؎: معلوم ہوا کہ جاہل صوفیوں نے جو نئی نئی قسم کے پر مشقت افعال یہ سمجھ کر ایجاد کر رکھے ہیں کہ ان سے تزکیہ نفوس حاصل ہوتا ہے حالانکہ شریعت سے ان کا ذرہ برابر تعلق نہیں، یہ احکام شریعت سے ان کی جہالت و ناواقفیت کی دلیل ہے کیونکہ نبی اکرم صلی اللہ علیہ وسلم نے ہمارے لیے کوئی ایسی چیز نہیں چھوڑی جسے صاف صاف طور پر بیان نہ کر دیا ہو۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے‘ انہوں نے فرمایا کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک آدمی کو دیکھا ہے جسے دو شخصوں کے سہارے چلایا جارہا تھا۔ آپ نے فرمایا: ’’ایسے کیوں؟‘‘ لوگوں نے کہا: حضور! اس نے نذر مانی ہے کہ بیت اللہ تک چل کر جائے گا۔ فرمایا: ’’اللہ تعالیٰ کو کیا ضرورت کہ یہ شخص اپنے آپ کو عذاب میں ڈالے؟ اسے کہو سوار ہوجائے۔‘‘","f2":"جو شخص اپنی نذر پوری کرنے سے عاجز آجائے تو اسے کفارہ ادا کرنا ہوگا۔ تفصیل کے لیے دیکھیے‘ روایت: ۳۸۴۵۔"}],[3853,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا گزر ایک ایسے بوڑھے شخص کے پاس سے ہوا جو دو آدمیوں کے درمیان ان کے کندھے پر ہاتھ رکھ کر چل رہا تھا۔ آپ نے فرمایا: \"اس کا کیا حال ہے؟\" ان لوگوں نے عرض کیا: اس نے (کعبہ) پیدل جانے کی نذر مانی ہے، آپ نے فرمایا: \"اس کے اس طرح اپنی جان کو تکلیف پہنچانے کی اللہ کو ضرورت نہیں، اسے حکم دو کہ سوار ہو کر چلے، چنانچہ انہوں نے اسے سوار ہونے کا حکم دیا\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے‘ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم ایک برزرگ آدمی کے پاس سے گزرے جسے دو آدمی سہارا دے کر چلا رہے تھے۔ فرمایا: ’’اسے کیا ہوا؟‘‘ لوگوں نے کہا: اس نے پیدل چلنے کی نذر مانی ہے۔ آپ نے فرمایا: ’’اللہ تعالیٰ کو کوئی ضرورت نہیں کہ یہ اپنے آپ کو عذاب میں ڈالے۔ اسے کہو سوار ہوجائے۔‘‘ تو مخاطب نے اسے سوار ہونے کو کہا۔"}],[3854,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا ایک ایسے شخص کے پاس سے گزر ہوا جو اپنے دو بیٹوں کے درمیان ان کے کندھوں کا سہارا لیے چل رہا تھا، آپ نے فرمایا: \"اس کا کیا معاملہ ہے؟\" عرض کیا گیا: اس نے کعبہ پیدل جانے کی نذر مانی ہے، آپ نے فرمایا: \"اس طرح اپنے آپ کو تکلیف دینے سے اللہ تعالی اس کو کوئی ثواب نہیں دے گا، پھر آپ نے اسے سوار ہونے کا حکم دیا\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کا گزر ایسے شخص پر سے ہوا جسے اس کے دو بیٹے پکڑ کر سہارے سے چلا رہے تھے۔ آپ نے فرمایا: ’’اسے کیا ہوا؟‘‘ کہا گیا: اس نے کعبہ تک پیدل چلنے کی نذر مانی ہے۔ آپ نے فرمایا: ’’اللہ تعالیٰ کو کوئی فائدہ نہیں کہ یہ اپنے آپ کو عذاب میں ڈالے۔‘‘ چنانچہ آپ نے اسے سوار ہونے کا حکم دیا۔","f2":"’’حکم دیا‘‘ کیونکہ وہ چلنے سے عاجز تھا۔ جو چل سکے‘ وہ چلے عاجز ہوجائے تو سوار ہوجائے اور کفارہ دے۔"}],[3855,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص کسی بات کی قسم کھائے، پھر وہ ان شاءاللہ کہے تو اس نے استثناء کر لیا\" ۱؎۔\n§وضاحت\n۱؎: یعنی وہ قسم توڑنے والا نہیں ہو گا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے راویت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے قسم کھاتے وقت ان شاء اللہ کہا‘ وہ قسم پوری کرنے سے مستثنیٰ ہوگیا۔‘‘"}],[3856,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سلیمان علیہ السلام نے کہا: آج رات میں نوے (۹۰) عورتوں (بیویوں) کے پاس جاؤں گا، ان میں سے ہر عورت ایک ایسا بچہ جنے گی جو اللہ کی راہ میں جہاد کرے گا۔ ان سے کہا گیا: آپ ان شاءاللہ کہیں، لیکن انہوں نے نہیں کہا۔ سلیمان علیہ السلام اپنی عورتوں کے پاس گئے تو ان میں سے صرف ایک عورت نے آدھا بچہ جنا\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر انہوں نے \"ان شاءاللہ\" کہا ہوتا تو وہ قسم توڑنے والے نہیں ہوتے اور اپنی حاجت پا لینے میں کامیاب بھی رہتے\"۔\nكتاب المزارعة\n§وضاحت\n۱؎: اس سے پہلے کتاب الأیمان والنذور میں قسم اور نذر کو دو شرط مان کر اس باب میں تیسری شرط کا ذکر کیا، اس لیے کہ ان میں اکثر و بیشتر استثنا اور تعلیق کا تذکرہ ہوتا ہے، اسی لیے اس کو تیسری شرط کا عنوان دے کر یہ بتایا کہ اس میں مزارعت اور و ثائق کا تذکرہ ہو گا :(التعلیقات السلفیۃ )۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مرفوعاً روایت ہے کہ حضرت سلیمان علیہ السلام نے فرمایا: میں رات کو نوے بیویوں کے پاس ضرور جاؤں گا۔ ان میں سے ہر ایک عورت ایسا لڑکا جنے گی جو اللہ تعالیٰ کے راستے میں جہاد کرے گا۔ آپ سے کہا گیا: ان شاء اللہ کہیں لیکن انہوں نے نہ کہا‘ چنانچہ آپ ان سب کے پاس گئے لیکن صرف ایک عورت نے بچہ جنا‘ وہ بھی ناقص۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر وہ ان شاء اللہ کہہ دیتے تو ان کی قسم نہ ٹوٹتی اور ان کی دلی مراد برآتی۔‘‘","f2":"تفصیل کے لیے دیکھیے‘ حدیث: ۳۸۲۴ اور ۳۸۶۲۔"}],[3939,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”دنیا کی چیزوں میں سے عورتیں اور خوشبو میرے لیے محبوب بنا دی گئی ہیں اور میری آنکھوں کی ٹھنڈک نماز میں رکھی گئی ہے“۔","حسن صحیح (ابو غدہ)؛ حسن صحیح (البانی)؛ سند حسن (زبیر علی زئی)"],[3940,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”عورتیں اور خوشبو میرے لیے محبوب بنا دی گئی ہیں اور میری آنکھوں کی ٹھنڈک نماز میں رکھی گئی ہے“۔","صحیح (ابو غدہ)؛ صحیح (البانی)؛ سند حسن (زبیر علی زئی)"],[3941,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ عورتوں کے بعد گھوڑوں سے زیادہ کوئی چیز رسول اللہ صلی اللہ علیہ وسلم کو محبوب نہ تھی۔","ضعیف (ابو غدہ)؛ ضعیف (البانی)؛ ضعیف (زبیر علی زئی)"],[3942,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ”جس کی دو بیویاں ہوں اور وہ ایک کے مقابلے دوسری طرف زیادہ میلان رکھے تو قیامت کے دن وہ اس طرح آئے گا کہ اس کا ایک پہلو جھکا ہوا ہو گا“۔","صحیح (ابو غدہ)؛ صحیح (البانی)؛ ضعیف (زبیر علی زئی)"],[3943,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنی بیویوں کے درمیان کچھ تقسیم کرتے تو برابر برابر کرتے، پھر فرماتے: اللہ! میرا یہ کام تو میرے دائرہ اختیار میں ہے، لہٰذا تو مجھے ملامت نہ کر ایسے کام کے سلسلے میں جو تیرے اختیار کا ہے اور مجھے اس میں کوئی اختیار نہیں۔ حماد بن زید نے یہ حدیث مرسل روایت کی ہے۔","الألباني: ضعيف"],[3944,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کی بیویوں نے فاطمہ بنت رسول صلی اللہ علیہ وسلم کو رسول اللہ صلی اللہ علیہ وسلم کے پاس بھیجا، انہوں نے آپ سے اجازت طلب کی، آپ میرے ساتھ چادر میں لیٹے ہوئے تھے، آپ نے انہیں اجازت دی، وہ بولیں: اللہ کے رسول! آپ کی بیویوں نے مجھے آپ کے پاس بھیجا ہے وہ ابوقحافہ کی بیٹی (عائشہ) کے سلسلے میں آپ سے ۱؎ عدل کا مطالبہ کر رہی ہیں، اور میں خاموش ہوں، تو رسول اللہ صلی اللہ علیہ وسلم نے فاطمہ رضی اللہ عنہا سے فرمایا: اے میری بیٹی! کیا تم اس سے محبت نہیں کرتیں جس سے مجھے محبت ہے؟ وہ بولیں: کیوں نہیں! آپ نے فرمایا: تو تم بھی ان سے محبت کرو، فاطمہ رضی اللہ عنہا نے رسول اللہ صلی اللہ علیہ وسلم سے جب یہ بات سنی تو اٹھیں اور نبی اکرم صلی اللہ علیہ وسلم کی بیویوں کے پاس واپس آ کر انہیں وہ ساری بات بتائی جو انہوں نے آپ صلی اللہ علیہ وسلم سے کہی اور جو آپ نے ان (فاطمہ) سے کہی۔ وہ سب بولیں: ہم نہیں سمجھتے کہ تم نے ہمارا کام کر دیا، تم پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس جاؤ اور آپ سے کہو: آپ کی بیویاں آپ سے ابوقحافہ کی بیٹی کے تعلق سے عدل کی اپیل کرتی ہیں۔ فاطمہ رضی اللہ عنہا نے کہا: نہیں، اللہ کی قسم! میں ان کے سلسلے میں آپ سے کبھی کوئی بات نہیں کروں گی۔ عائشہ رضی اللہ عنہا کہتی ہیں: اب نبی اکرم صلی اللہ علیہ وسلم کی ازواج نے رسول اللہ صلی اللہ علیہ وسلم کے پاس زینب بنت جحش کو بھیجا اور زینب ہی ایسی تھیں جو نبی اکرم صلی اللہ علیہ وسلم کی بیویوں میں رسول اللہ صلی اللہ علیہ وسلم کے نزدیک میرے برابر کا درجہ رکھتی تھیں۔ میں نے کبھی بھی دین کے معاملے میں بہتر، اللہ سے ڈرنے والی، سچ بات کہنے والی، صلہ رحمی کرنے والی، بڑے بڑے صدقات کرنے والی، صدقہ و خیرات اور قرب الٰہی کے کاموں میں خود کو سب سے زیادہ کمتر کرنے والی زینب سے بڑھ کر کوئی عورت نہیں دیکھی سوائے اس کے کہ وہ مزاج کی تیز طرار تھیں لیکن ان کا غصہ بہت جلد رفع ہو جاتا تھا۔ چنانچہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اجازت طلب کی، رسول اللہ صلی اللہ علیہ وسلم عائشہ رضی اللہ عنہا کے ساتھ چادر میں اسی طرح تھے کہ جب فاطمہ رضی اللہ عنہا آپ کے پاس آئی تھیں، رسول اللہ صلی اللہ علیہ وسلم نے انہیں اجازت دے دی، وہ بولیں: اللہ کے رسول! آپ کی بیویوں نے مجھے آپ کے پاس اس لیے بھیجا ہے کہ وہ سب ابوقحافہ کی بیٹی کے تعلق سے آپ سے عدل و انصاف کا مطالبہ کر رہی ہیں اور وہ مجھے برا بھلا کہنے لگیں اور خوب زبان درازی کی، میں رسول اللہ صلی اللہ علیہ وسلم کو دیکھ رہی تھی اور آپ کی نگاہ دیکھ رہی تھی کہ آیا آپ مجھے بھی ان کا جواب دینے کی اجازت دیتے ہیں، زینب رضی اللہ عنہا ابھی وہیں پر تھیں کہ میں نے اندازہ کر لیا کہ اگر میں انہیں جواب دوں تو رسول اللہ صلی اللہ علیہ وسلم کو برا نہیں لگے گا۔ چنانچہ جب میں نے انہیں برا بھلا کہا تو میں نے انہیں ذرا بھی ٹکنے نہیں دیا یہاں تک کہ میں ان سے آگے نکل گئی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ ابوبکر کی بیٹی ہے\"۔\n§وضاحت\n۱؎: یعنی قلبی محبت میں تمام ازواج مطہرات برابر ہوں یا لوگ اپنے ہدایا بھیجنے میں ساری ازواج مطہرات کا خیال رکھیں۔","الألباني: صحيح"],[3945,"اس سند سے بھی ہے کہ عائشہ رضی اللہ عنہا کہتی ہیں کہ پھر انہوں نے اسی طرح بیان کیا اور وہ اس میں (صرف اتنا) کہتی ہیں: نبی اکرم صلی اللہ علیہ وسلم کی بیویوں نے زینب کو بھیجا تو انہوں نے اجازت طلب کی، آپ نے انہیں اجازت دی، پھر وہ اسی طرح آگے کہتی ہیں، معمر نے اس کے برعکس عن الزہری، عن عروۃ، عن عائشہ کہہ کر روایت کی ہے۔","الألباني: صحيح الإسناد"],[3946,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کی بیویاں اکٹھا ہوئیں اور انہوں نے فاطمہ رضی اللہ عنہا کو نبی اکرم صلی اللہ علیہ وسلم کے پاس بھیجا اور ان سے کہا: آپ کی بیویاں - اور ایسا کلمہ کہا جس کا مفہوم یہ ہے - ابوقحافہ کی بیٹی کے تعلق سے آپ سے مطالبہ کرتی ہیں کہ انصاف سے کام لیجئیے۔ چنانچہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس گئیں، آپ عائشہ رضی اللہ عنہا کے ساتھ ان کی چادر میں تھے۔ انہوں نے آپ سے کہا: (اللہ کے رسول!) آپ کی بیویوں نے مجھے آپ کے پاس بھیجا ہے وہ ابوقحافہ کی بیٹی (عائشہ) کے سلسلے میں آپ سے عدل کا مطالبہ کر رہی ہیں، نبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"کیا تمہیں مجھ سے محبت ہے؟\" کہا: جی ہاں! آپ نے فرمایا: \"تو تم بھی ان (عائشہ) سے محبت کرو\"، عائشہ رضی اللہ عنہا کہتی ہیں: فاطمہ رضی اللہ عنہا نے نبی اکرم صلی اللہ علیہ وسلم کی بیویوں کے پاس واپس آ کر انہیں وہ ساری بات بتائی جو آپ نے (فاطمہ سے) کہی، وہ سب بولیں: تم نے ہمارے لیے کچھ بھی نہیں کیا، تم پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس جاؤ۔ فاطمہ نے کہا: نہیں، اللہ کی قسم! میں ان کے سلسلے میں آپ کے پاس کبھی نہیں جاؤں گی اور درحقیقت وہ اللہ کے رسول صلی اللہ علیہ وسلم کی بیٹی تھیں ۱؎، اب نبی اکرم صلی اللہ علیہ وسلم کی ازواج مطہرات نے (رسول اللہ صلی اللہ علیہ وسلم کے پاس) زینب بنت جحش رضی اللہ عنہا کو بھیجا۔ اور زینب ہی ایسی تھیں جو نبی اکرم صلی اللہ علیہ وسلم کی بیویوں میں (رسول اللہ صلی اللہ علیہ وسلم کے نزدیک) میرے برابر کا درجہ رکھتی تھیں۔ وہ بولیں: (اللہ کے رسول!) آپ کی بیویوں نے مجھے آپ کے پاس اس لیے بھیجا ہے کہ وہ سب ابوقحافہ کی بیٹی کے تعلق سے آپ سے عدل و انصاف کا مطالبہ کر رہی ہیں اور وہ مجھے برا بھلا کہنے لگیں۔ میں نبی اکرم صلی اللہ علیہ وسلم کو دیکھ رہی تھی اور آپ کی نگاہ دیکھ رہی تھی کہ آیا آپ مجھے بھی ان کا جواب دینے کی اجازت دیتے ہیں؟ زینب رضی اللہ عنہا ابھی وہیں پر تھیں کہ میں نے اندازہ کر لیا کہ اگر میں انہیں جواب دوں تو رسول اللہ صلی اللہ علیہ وسلم کو برا نہیں لگے گا۔ چنانچہ (جب) میں نے انہیں برا بھلا کہا (تو میں نے انہیں ذرا بھی ٹکنے نہیں دیا) یہاں تک کہ میں ان سے آگے نکل گئی، نبی اکرم صلی اللہ علیہ وسلم نے زینب رضی اللہ عنہا سے فرمایا: \"یہ ابوبکر کی بیٹی ہے\"۔ عائشہ رضی اللہ عنہا کہتی ہیں: میں نے کبھی بھی دین کے معاملے میں بہتر، اللہ سے ڈرنے والی، سچ بات کہنے والی اور صلہ رحمی کرنے والی، بڑے بڑے صدقات کرنے والی، صدقہ و خیرات اور قرب الٰہی کے کاموں میں خود کو سب سے زیادہ کمتر کرنے والی زینب رضی اللہ عنہا سے بڑھ کر کوئی عورت نہیں دیکھا سوائے اس کے کہ وہ مزاج کی تیز طرار تھیں لیکن ان کا غصہ بہت جلد رفع ہو جاتا تھا۔ ابوعبدالرحمٰن نسائی کہتے ہیں: اس (روایت) میں غلطی ہے صحیح وہی ہے جو اس سے پہلے گزری۔\n§وضاحت\n۱؎: یعنی یہ کیسے ممکن تھا کہ وہ آپ صلی اللہ علیہ وسلم کے فرمان کی خلاف ورزی کرتیں جب کی آپ نے ان سے فرمایا تھا تو بھی عائشہ رضی اللہ عنہا سے محبت کر۔","الألباني: صحيح الإسناد"],[3947,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"عورتوں پر عائشہ کی فضیلت ایسے ہی ہے جیسے ثرید کی تمام کھانوں پر\" ۱؎۔\n§وضاحت\n۱؎: ثرید: عربوں کا سب سے اعلی درجے کا کھانا ہے یہ گوشت کا ہوتا ہے، اس میں لذت اور ذائقہ بھی ہے اور قوت و غذائیت بھی۔ کھانے میں بہت آسان ہوتا ہے اور اسے چبانے میں کوئی دقت نہیں ہوتی۔ یہ خوبصورتی بڑھانے اور آواز میں حسن پیدا کرنے میں معاون ہوتا ہے۔","الألباني: صحيح"],[3948,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"عورتوں پر عائشہ کی فضیلت ایسے ہی ہے جیسے ثرید کی سارے کھانوں پر\"۔","الألباني: صحيح"],[3949,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے ام سلمہ! مجھے عائشہ کے تعلق سے ایذا نہ دو، اس لیے کہ اللہ کی قسم! اس کے علاوہ کوئی عورت تم میں سے ایسی نہیں ہے جس کے لحاف میں میرے پاس وحی آئی ہو\"۔","الألباني: صحيح"],[3950,"ام المؤمنین ام سلمہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کی بیویوں نے ان سے بات کی کہ وہ نبی اکرم صلی اللہ علیہ وسلم سے بات کریں کہ لوگ عائشہ کی باری کے دن ہدیے اور تحفے بھیجتے ہیں اور آپ سے کہیں کہ ہمیں بھی خیر سے اسی طرح محبت ہے جیسے آپ کو عائشہ سے ہے، چنانچہ انہوں نے آپ سے گفتگو کی لیکن آپ نے انہیں کوئی جواب نہیں دیا، جب ان کی باری کا دن آیا تو انہوں نے پھر بات کی، آپ نے انہیں جواب نہیں دیا۔ انہوں (بیویوں) نے کہا: آپ صلی اللہ علیہ وسلم نے تمہیں کوئی جواب دیا؟ وہ بولیں: کوئی جواب نہیں دیا۔ انہوں نے کہا: تم چھوڑنا مت، جب تک کوئی جواب نہ دے دیں۔ (یا یوں کہا:) جب تک تم دیکھ نہ لو کہ آپ کیا جواب دیتے ہیں۔ جب پھر ان کی باری آئی تو انہوں نے آپ سے گفتگو کی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ کے تعلق سے مجھے اذیت نہ دو، اس لیے کہ عائشہ کے لحاف کے علاوہ تم میں سے کسی عورت کے لحاف میں ہوتے ہوئے میرے پاس وحی نہیں آئی\"۔ ابوعبدالرحمٰن نسائی کہتے ہیں: عبدہ سے مروی یہ دونوں حدیثیں صحیح ہیں۔","الألباني: صحيح"],[3951,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ لوگ ہدیے اور تحفے بھیجتے جس دن عائشہ کی باری ہوتی، وہ اس طرح رسول اللہ صلی اللہ علیہ وسلم کی خوشی چاہتے تھے۔","الألباني: صحيح"],[3952,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ اللہ تعالی نے نبی اکرم صلی اللہ علیہ وسلم پر وحی نازل کی، میں آپ کے ساتھ تھی، میں اٹھی اور اپنے اور آپ کے درمیان دروازہ بند کر دیا، جب وحی ختم ہو گئی تو آپ نے مجھ سے فرمایا: \"عائشہ! جبرائیل تمہیں سلام کہہ رہے ہیں\"۔","الألباني: ضعيف الإسناد"],[3953,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"جبرائیل تمہیں سلام کہہ رہے ہیں\"، انہوں نے کہا:«وعلیکم السلام ورحمۃ اللہ وبرکاتہ» (جبرائیل کو عائشہ نے سلام کا جواب دیا اور کہا:) آپ تو وہ دیکھتے ہیں جو ہم نہیں دیکھتے\" ۱؎۔\n§وضاحت\n۱؎: یعنی آپ جبرائیل کو دیکھ رہے ہیں اور ان کی باتیں سن رہے ہیں حالانکہ ہم نہیں دیکھ رہے ہیں۔","الألباني: صحيح"],[3954,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! یہ جبرائیل ہیں، تمہیں سلام کہہ رہے ہیں۔ اور آگے ویسے ہی ہے جیسے اوپر گزرا\"۔ ابوعبدالرحمٰن نسائی کہتے ہیں: یہ روایت ٹھیک ہے، پہلی والی غلط ہے ۱؎۔\n§وضاحت\n۱؎: یعنی «شعیب عن الزہری عن أبی سلمۃ عن عائشۃ» کی سند ٹھیک ہے جب کہ «معمر عن الزہری عن عروۃ عن عائشۃ» کی سند میں غلطی ہے، کیونکہ «عن عروۃ عن عائشۃ» کی جگہ «عن أبی سلمۃ عن عائشۃ» ہونا چاہیئے۔","الألباني: صحيح"],[3955,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم امہات المؤمنین میں سے ایک کے پاس تھے، آپ کی کسی دوسری بیوی نے ایک پیالہ کھانا بھیجا، پہلی بیوی نے (غصہ سے کھانا لانے والے) کے ہاتھ پر مارا اور پیالہ گر کر ٹوٹ گیا۔ نبی اکرم صلی اللہ علیہ وسلم نے برتن کے دونوں ٹکڑوں کو اٹھا کر ایک کو دوسرے سے جوڑا اور اس میں کھانا اکٹھا کرنے لگے اور فرماتے جاتے تھے: تمہاری ماں کو غیرت آ گئی ہے (کہ میرے گھر اس نے کھانا کیوں بھیجا)، تم لوگ کھانا کھاؤ۔ لوگوں نے کھایا، پھر قاصد کو آپ نے روکے رکھا یہاں تک کہ جن کے گھر میں آپ تھے اپنا پیالہ لائیں تو آپ نے یہ صحیح سالم پیالہ قاصد کو عنایت کر دیا ۱؎ اور ٹوٹا ہوا پیالہ اس بیوی کے گھر میں رکھ چھوڑا جس نے اسے توڑا تھا۔\n§وضاحت\n۱؎: بظاہر معلوم ہوتا ہے کہ یہ دونوں پیالے آپ کی ذاتی ملکیت تھے، ورنہ کسی ضائع اور برباد چیز کا بدلہ اسی کے مثل قیمت ہوا کرتا ہے، یا یہ کہا جا سکتا ہے کہ دونوں پیالے قیمت میں برابر رہے ہوں گے۔","الألباني: صحيح"],[3956,"ام المؤمنین ام سلمہ رضی اللہ عنہا سے روایت ہے کہ وہ ایک پیالے میں کھانا لے کر رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ کے پاس آئیں۔ اتنے میں عائشہ رضی اللہ عنہا ایک چادر پہنے ہوئے آئیں، ان کے پاس ایک پتھر تھا، جس سے انہوں نے وہ پیالا مار کر دو ٹکرے کر دیا۔ نبی اکرم صلی اللہ علیہ وسلم پیالے کے دونوں ٹکڑے جوڑنے لگے اور کہہ رہے تھے: تم لوگ کھاؤ، تمہاری ماں کو غیرت آ گئی، آپ نے دو بار کہا۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے عائشہ رضی اللہ عنہا کا پیالا لیا اور وہ ام سلمہ رضی اللہ عنہا کو بھجوا دیا اور ام سلمہ رضی اللہ عنہا کا پیالا عائشہ رضی اللہ عنہا کو دے دیا۔","الألباني: صحيح"],[3957,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے ام المؤمنین صفیہ رضی اللہ عنہا کے جیسی کھانا بنانے والی کوئی عورت نہیں دیکھی، انہوں نے نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک برتن بھیجا جس میں کھانا تھا، میں اپنے کو قابو میں نہ رکھ سکی اور میں نے برتن توڑ دیا پھر میں نے نبی اکرم صلی اللہ علیہ وسلم سے اس کے کفارے کے متعلق پوچھا تو آپ نے فرمایا: \"برتن کے جیسا برتن اور کھانے کے جیسا کھانا\"۔","الألباني: ضعيف"],[3958,"ام المؤمنین عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ام المؤمنین زینب بنت جحش رضی اللہ عنہا کے پاس ٹھہرے ہوئے تھے اور ان کے ہاں شہد پی رہے تھے، میں نے اور حفصہ رضی اللہ عنہا نے باہم مشورہ کیا کہ ہم میں سے جس کے پاس نبی اکرم صلی اللہ علیہ وسلم آئیں تو وہ کہے: مجھے آپ سے مغافیر ۱؎ کی بو آ رہی ہے، آپ نے مغافیر کھایا ہے۔ آپ ان میں سے ایک کے پاس گئے تو اس نے یہی کہا، آپ نے فرمایا: \"نہیں، میں نے تو زینب بنت جحش کے پاس شہد پیا ہے اور اب آئندہ نہیں پیوں گا\"۔ تو عائشہ اور حفصہ (رضی اللہ عنہما) کی وجہ سے یہ آیت «يا أيها النبي لم تحرم ما أحل اللہ لك» \"اے نبی! جس چیز کو اللہ تعالی نے حلال کر دیا ہے اسے آپ کیوں حرام کرتے ہیں\"۔ (التحریم: ۱) اور «إن تتوبا إلى اللہ» \"(اے نبی کی دونوں بیویو!) اگر تم دونوں اللہ کے سامنے توبہ کر لو(تو بہت بہتر ہے)\"۔ (التحریم: ۴) نازل ہوئی اور آپ صلی اللہ علیہ وسلم کے اس قول: میں نے تو شہد پیا ہے کی وجہ سے یہ آیت: «وإذ أسر النبي إلى بعض أزواجه حديثا» \"اور یاد کر جب نبی نے اپنی بعض عورتوں سے ایک پوشیدہ بات کہی\" (التحریم: ۳) نازل ہوئی ہے۔\n§وضاحت\n۱؎: ایک قسم کا گوند ہے جو بعض درختوں سے نکلتا ہے۔","الألباني: صحيح"],[3959,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی ایک لونڈی تھی، آپ اس سے مجامعت فرماتے تھے۔ عائشہ اور حفصہ رضی اللہ عنہا ایک دن آپ کے پاس بیٹھی رہیں یہاں تک کہ آپ نے اسے اپنے اوپر حرام کر لی، تو اللہ تعالی نے یہ آیت: «يا أيها النبي لم تحرم ما أحل اللہ لك» إِلَى آخِرِ الآيَةِ\"اے نبی! آپ اس چیز کو اپنے لیے کیوں حرام قرار دے رہے ہیں جسے اللہ تعالی نے آپ کے لیے حلال رکھا ہے\"۔ (التحریم: ۱) مکمل آیت نازل فرمائی ۱؎۔\n§وضاحت\n۱؎: اس سے پہلے والی حدیث میں ہے کہ اس آیت کے نزول کا سبب یہ ہے کہ آپ نے اپنے اوپر شہد کو حرام کر لیا تھا۔ اس سلسلہ میں حافظ ابن حجر کا کہنا ہے کہ ممکن ہے یہ دونوں واقعے آیت کے نزول کا سبب بنے ہوں۔","الألباني: صحيح الإسناد"],[3960,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کی تفتیش کر رہی تھی چنانچہ میں نے اپنا ہاتھ آپ کے بالوں میں داخل کیا تو آپ نے فرمایا:\"تمہارے پاس تمہارا شیطان آ گیا ہے\"۔ میں نے عرض کیا: کیا آپ کا شیطان نہیں ہے؟ آپ نے فرمایا: \"کیوں نہیں، اللہ کی قسم، لیکن اللہ تعالی نے مجھے اس سے محفوظ رکھا ہے لہٰذا میں اس سے محفوظ رہتا ہوں\"۔","الألباني: صحيح الإسناد"],[3961,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک رات میں نے رسول اللہ صلی اللہ علیہ وسلم کو غائب پایا، مجھے گمان ہوا کہ آپ کسی بیوی کے پاس گئے ہوں گے۔ میں آپ کو تلاش کرنے لگی، دیکھا کہ آپ رکوع یا سجدہ میں ہیں اور کہہ رہے ہیں: «سبحانك و بحمدك لا إله إلا أنت» \"پاک ہے تیری ذات، تیری ہی تعریف ہے اور تیرے سوا کوئی حقیقی معبود نہیں\"۔ میں نے کہا: میرے ماں باپ آپ پر قربان ہوں، آپ کچھ کر رہے ہیں اور میں کچھ اور ہی گمان کر رہی تھی۔","الألباني: صحيح"],[3962,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک رات میں نے رسول اللہ صلی اللہ علیہ وسلم کو غائب پایا، مجھے گمان ہوا کہ آپ اپنی کسی بیوی کے پاس گئے ہوں گے، میں آپ کو تلاش کرنے لگی پھر میں لوٹی تو دیکھا کہ آپ رکوع یا سجدے میں ہیں، آپ کہہ رہے ہیں: «سبحانك و بحمدك لا إله إلا أنت» میں نے عرض کیا: میرے ماں باپ آپ پر قربان ہوں، آپ کچھ کر رہے ہیں اور میں کچھ اور ہی گمان کر رہی تھی۔","الألباني: صحيح"],[3963,"محمد بن قیس سے روایت ہے کہ انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا کو کہتے ہوئے سنا کہ کیا میں تم سے نبی اکرم صلی اللہ علیہ وسلم کا اور اپنا ایک واقعہ نہ بیان کروں؟ ہم نے عرض کیا: کیوں نہیں؟ وہ بولیں: جس رات میری باری تھی، آپ عشاء سے لوٹے اور جوتے اپنے پیروں کے پاس رکھ لیے، اپنی چادر رکھی اور بستر پر اپنا تہبند بچھایا، ابھی تھوڑی ہی دیر ہوئی تھی، جب آپ کو اندازہ ہوا کہ میں سو چکی ہوں، تو آپ نے آہستہ سے جوتے پہنے اور آہستہ سے چادر لی پھر دھیرے سے دروازہ کھولا اور باہر نکل کر دھیرے سے بند کر دیا۔ میں نے بھی اوڑھنی اپنے سر پر ڈالی، چادر اوڑھی اور پھر تہبند پہن کر آپ کے پیچھے پیچھے چل پڑی، یہاں تک کہ آپ مقبرہ بقیع آئے، تو آپ نے اپنے ہاتھ تین بار اٹھائے، قیام کو طویل کیا پھر پلٹے تو میں بھی پلٹی، اور تیزی سے چلے، میں بھی تیزی سے چلی، پھر آپ نے رفتار کچھ اور تیز کر دی تو میں نے بھی تیز کر دی پھر آپ دوڑنے لگے تو میں بھی دوڑنے لگی، میں آپ سے آگے نکل گئی اور اندر داخل ہو گئی اور اب میں لیٹی ہی تھی کہ آپ اندر آ گئے اور فرمایا:\"کیا بات ہے عائشہ! سانس کیوں پھولی ہے؟ (سلیمان بن داود نے کہا: میرا خیال ہے کہ میرے شیخ نے یوں فرمایا: «حشیا»، یعنی) تمہاری سانسیں کیوں پھول رہی ہیں؟\" آپ نے فرمایا: \"بتاؤ ورنہ مجھے لطیف و خبیر یعنی اللہ بتا دے گا\"۔ میں نے کہا: اللہ کے رسول! میرے ماں باپ آپ پر قربان ہوں، پھر انہوں نے آپ کو پورا واقعہ بتایا، آپ نے فرمایا: \"تو تمہارا ہی سایہ تھا جو میں نے اپنے آگے دیکھا؟\" میں نے کہا: ہاں، پھر آپ نے میرے سینے پر ایک ایسی تھپکی ماری کہ مجھے تکلیف ہوئی اور فرمایا: \"کیا تم سمجھتی ہو کہ اللہ اور اس کا رسول تم پر ظلم کرے گا؟\" عائشہ رضی اللہ عنہا نے کہا: کوئی بات چاہے لوگوں سے کتنی ہی مخفی رہے، لیکن اللہ تعالی تو اسے بخوبی جانتا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں، پھر فرمایا: جبرائیل علیہ السلام میرے پاس آئے جب تم نے مجھے دیکھا، لیکن وہ اندر تمہارے سامنے نہیں آ سکتے تھے کہ تم اپنے کپڑے اتار چکی تھیں، انہوں نے مجھے پکارا اور تم سے چھپایا، میں نے انہیں جواب دیا اور میں نے اسے تم سے چھپایا (یعنی دھیرے سے کہا) اور میں سمجھا کہ تم سو چکی ہو، تو میں نے مناسب نہیں سمجھا کہ تمہیں جگاؤں۔ اور مجھے ڈر تھا کہ تم تنہائی میں وحشت نہ کھاؤ، تو انہوں (جبرائیل) نے مجھے حکم دیا کہ میں اہل بقیع کے پاس جاؤں اور ان کے لیے استغفار کروں\"۔ حجاج بن محمد نے سند اس کے برعکس یوں بیان کی «عن ابن جریج، عن ابن ابی ملیکۃ، عن محمد بن قیس»۔","الألباني: صحيح"],[3964,"محمد بن قیس بن مخرمہ کہتے ہیں کہ انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا کو کہتے ہوئے سنا: کیا میں تم سے نبی اکرم صلی اللہ علیہ وسلم کا اور اپنا ایک واقعہ نہ بیان کروں؟ ہم نے عرض کیا: کیوں نہیں؟ وہ بولیں: جس رات میری باری تھی، نبی اکرم صلی اللہ علیہ وسلم میرے یہاں تھے، آپ عشاء سے لوٹے اور جوتے اپنے پیروں کے پاس رکھ لیے، اپنی چادر رکھی اور بستر پر تہبند بچھایا، ابھی تھوڑی ہی دیر ہوئی تھی جب آپ کو اندازہ ہوا کہ میں سو چکی ہوں، آپ نے آہستہ سے جوتے پہنے اور آہستہ سے چادر لی پھر دھیرے سے دروازہ کھولا اور باہر نکل کر دھیرے سے بھیڑ دیا، میں نے بھی اوڑھنی اپنے سر پر ڈالی، چادر اوڑھی، پھر تہبند پہن کر آپ کے پیچھے پیچھے چل پڑی، یہاں تک کہ آپ مقبرہ بقیع آئے، تو آپ نے اپنے ہاتھ تین بار اٹھائے، قیام کو طویل کیا پھر پلٹے تو میں بھی پلٹی، اور تیزی سے چلے، میں بھی تیزی سے چلی، پھر آپ نے رفتار کچھ اور تیز کر دی تو میں نے بھی رفتار تیز کر دی پھر آپ دوڑنے لگے تو میں بھی دوڑنے لگی اور میں آپ سے آگے نکل گئی اور اندر داخل ہو گئی اور اب میں لیٹی ہی تھی کہ آپ اندر آ گئے اور فرمایا: \"کیا بات ہے عائشہ! پیٹ کیسا پھولا ہے، تمہاری سانسیں کیوں پھول رہی ہیں؟ بتاؤ ورنہ مجھے لطیف و خبیر یعنی اللہ تعالی بتا دے گا\"۔ میں نے کہا: اللہ کے رسول! میرے ماں باپ آپ پر قربان ہوں، پھر انہوں نے آپ کو پورا واقعہ بتایا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو تمہارا ہی سایہ تھا جو میں نے اپنے آگے دیکھا؟\" میں نے کہا: ہاں، پھر آپ نے میرے سینے پر ایک ایسی تھپکی ماری کہ مجھے تکلیف ہوئی اور فرمایا: \"کیا تم سمجھتی ہو کہ اللہ اور اس کا رسول تم پر ظلم کرے گا؟\" انہوں نے کہا: کوئی بات چاہے لوگوں سے کتنی ہی مخفی رہے، لیکن اللہ تعالی تو اسے جان ہی لے گا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں، (اور) کہا: جبرائیل میرے پاس آئے جب تم نے مجھے دیکھا، لیکن وہ اندر تمہارے سامنے نہیں آ سکتے تھے کہ تم اپنے کپڑے اتار چکی تھیں۔ انہوں نے مجھے پکارا اور تم سے چھپایا، میں نے انہیں جواب دیا اور میں نے اسے تم سے چھپایا (یعنی دھیرے سے کہا) اور میں سمجھا کہ تم سو چکی ہو، اور مجھے ڈر تھا کہ تم تنہائی میں وحشت نہ کھاؤ، تو انہوں (جبرائیل) نے مجھے حکم دیا کہ میں اہل بقیع کے پاس جاؤں اور ان کے لیے استغفار کروں۔ عاصم نے یہ حدیث دوسرے الفاظ کے ساتھ عبداللہ بن عامر سے اور انہوں نے عائشہ رضی اللہ عنہا سے روایت کی ہے۔","الألباني: صحيح"],[3965,"اس سند سے بھی عائشہ رضی اللہ عنہا کہتی ہیں کہ رات کو آپ صلی اللہ علیہ وسلم نے مجھے غائب پایا اور پھر پوری حدیث بیان کی۔","الألباني: صحيح"],[4052,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے تمہیں ایک ایسی بات سے روک دیا جو ہمارے لیے مفید اور نفع بخش تھی لیکن رسول اللہ صلی اللہ علیہ وسلم کی اطاعت ہمارے لیے اس سے زیادہ مفید اور نفع بخش ہے۔ آپ نے فرمایا: \"جس کے پاس زمین ہو تو وہ اس میں کھیتی کرے اور اگر وہ اس سے عاجز ہو تو اپنے (کسی مسلمان) بھائی کو کھیتی کے لیے دیدے\"۔ اس میں عبدالکریم بن مالک نے ان (سعید بن عبدالرحمٰن) کی مخالفت کی ہے ۱؎۔\n§وضاحت\n۱؎: عبدالکریم بن مالک کی روایت آگے آ رہی ہے، اور مخالفت ظاہر ہے۔","الألباني: صحيح",{"u2":"حضرت جریر رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب غلام بھاگ کر مشرکین کے علاقے میں چلا جائے تو اس کا خون بہانا جائز ہو جاتا ہے۔‘‘"}],[4057,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ عثمان رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا کہ کسی مسلمان کا خون حلال نہیں مگر تین صورتوں میں: ایک وہ شخص جس نے شادی شدہ ہونے کے بعد زنا کیا تو اسے رجم کیا جائے گا، یا جس نے جان بوجھ کر قتل کیا تو اس کو اس کے بدلے میں قتل کیا جائے گا، یا وہ شخص جو اسلام لانے کے بعد مرتد ہو گیا، تو اسے بھی قتل کیا جائے گا۔\n§وضاحت\n۱؎: مرتد کے سلسلہ میں اجماع ہے کہ اسے قتل کرنا واجب ہے، اس سلسلہ میں کسی کا اختلاف نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت عثمان رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’کسی مسلمان شخص کا خون بہانا جائز نہیں مگر تین جرائم میں سے کسی ایک کی بنا پر: جو شخص شادی شدہ ہونے کے بعد زنا کرے، اس پر رجم کی سزا ہے۔ جو شخص کسی کو جان بوجھ کر ناحق قتل کر دے تو اسے قصاصاً قتل کر دیا جائے گا اور جو شخص اسلام لانے کے بعد مرتد ہو جائے تو اسے بھی قتل کر دیا جائے گا۔‘‘","f2":"(۱) ترجمۃ الباب کے ساتھ حدیث کی مطابقت بالکل واضح ہے کہ جو شخص مرتد ہو جائے اس کا حکم یہ ہے کہ اسے قتل کر دیا جائے۔ (۲) حضرت عثمان رضی اللہ تعالٰی عنہ نے یہ بات ان بلوائیوں سے فرمائی تھی جنہوں نے ان کا محاصرہ کر رکھا تھا اور بالآخر ان لوگوں نے آپ کو شہید کر دیا۔ (۳) مرتد اپنے ارتداد پر قائم رہے تو اتفاق ہے ک اسے قتل کر دیا جائے گا۔ حضرت ابوبکر رضی اللہ تعالٰی عنہ نے مرتدین کے خلاف جنگ لڑی اور انہیں بلادریغ قتل کیا۔ کسی صحابی نے اس پر اعتراض نہیں کیا۔ گویا صحابہ کا اس سزا پر اجماع ہے۔ البتہ مرتد اسے کہا جائے گا جو صراحتاً جان بوجھ کر کفریہ اعمال کا ارتکاب کرے یا اسلام چھوڑنے کا اعلان کر دے یا کافروں سے مل جائے یا رسول اللہ صلی اللہ علیہ وسلم کو گالی دے وغیرہ۔ اسلامی مذاہب کے باہمی فقہی اختلافات کی بنا پر کسی کو مرتد نہیں کہا جائے گا جب تک وہ اصول دین پر قائم ہے۔"}],[4058,"عثمان بن عفان رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"کسی مسلمان شخص کا خون حلال نہیں تین صورتوں کے سوائے: یہ کہ وہ شادی شدہ ہونے کے بعد زنا کرے، یا وہ کسی انسان کو قتل کرے تو اسے قتل کیا جائے یا وہ اسلام لانے کے بعد کافر (مرتد) ہو جائے تو اسے قتل کیا جائے\"۔","الألباني: صحيح",{"u2":"حضرت عثمان بن عفان رضی اللہ تعالٰی عنہ سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’تین جرائم کے بغیر کسی مسلمان کا خون بہانا جائز نہیں: وہ شادی شدہ ہونے کے بعد زنا کرے یا کسی انسان کو قتل کرے تو اسے قتل کیا جائے گا۔ یا مسلمان ہونے کے بعد کافر بن جائے تو اسے بھی قتل کیا جائے گا۔‘‘"}],[4059,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنے دین و مذہب کو بدلا اسے قتل کر دو\" ۱؎۔\n§وضاحت\n۱؎: دین سے مراد دین اسلام ہے، لہٰذا اگر کوئی کفر سے اسلام میں داخل ہوا یا کسی دوسری ملت سے کسی اور ملت میں داخل ہوا تو اس کے سلسلہ میں یہ حکم نہیں ہے، واضح رہے کہ قتل کا حکم مرد اور عورت دونوں کو شامل ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمای: ’’جو شخص اپنا دین بدلے (اسلام کو چھوڑ کر کوئی دوسرا دین اختیار کر لے) اسے قتل کر دو۔‘‘","f2":"(۱) دین سے مراد دین حق، یعنی اسلام ہے۔ یہ سزا صرف اس شخص کے لیے ہے جو اسلام قبول کرنے کے بعد دوبارہ کافر ہو جائے۔ مرتد بھی صرف اسی شخص کو کہا جائے گا کیونکہ آپ کا خطاب مسلمانوں سے متعلق ہے۔ (۳) دین اسلام سے منحرف ہو کر دوسرا دین اختیار کر لینے پر قتل کیے جانے کا حکم مرد و عورت سب کو شامل ہے۔ احناف مرتد عورت کے قتل کے قائل نہیں الا یہ کہ وہ اس درجے کی ہو کہ مسلمانوں کو نقصان پہنچا سکے۔ گویا ان کے نزدیک قتل ارتداد کی سزا نہیں بلکہ محاربہ کی سزا ہے، حالانکہ حدیث میں دین تبدیل کرنے کی سزا بیان کی گئی ہے نہ کہ محاربہ کی۔"}],[4060,"عکرمہ سے روایت ہے کہ کچھ لوگ اسلام سے پھر گئے ۱؎ تو انہیں علی رضی اللہ عنہ نے آگ میں جلا دیا۔ ابن عباس رضی اللہ عنہما نے کہا: اگر میں ہوتا تو انہیں نہ جلاتا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"تم کسی کو اللہ کا عذاب نہ دو\"، اگر میں ہوتا تو انہیں قتل کرتا (کیونکہ) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"جو اپنا دین بدل ڈالے اسے قتل کر دو\"۔\n§وضاحت\n۱؎: کہا جاتا ہے کہ یہ لوگ عبداللہ بن سبا کے متبعین و پیروکاروں میں سے تھے، انہوں نے فتنہ پھیلانے اور امت کو گمراہ کرنے کے لیے اسلام کا اظہار کیا تھا۔","الألباني: صحيح",{"u2":"حضرت عکرمہ سے روایت ہے کہ کچھ لوگ اسلام سے مرتد ہو گئے۔ حضرت علی رضی اللہ تعالٰی عنہ نے انہیں آگ میں جلا دیا۔ حضرت ابن عباس رضی اللہ عنہ نے فرمایا اگر میں سزا دیتا تو میں انہیں آگ میں نہ جلاتا کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: ’’تم کسی کو اللہ والا عذاب نہ دو۔‘‘ اگر میں انہیں سزا دیتا تو انہیں صرف قتل ہی کر دیتا کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: ’’جو شخص اپنا دین بدل لے، اسے قتل کر دو۔‘‘","f2":"اللہ والے عذاب سے مراد آگ میں جلاتا ہے۔ یہ عذاب صرف اللہ تعالیٰ کے اختیار میں ہے۔ کسی حیوان کو بھی آگ میں جلایا نہیں جا سکتا۔"}],[4061,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنا دین بدلا اسے قتل کر دو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو مسلمان اپنا دین بدل لے، اسے قتل کر دو۔‘‘"}],[4062,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنا دین بدلا اسے قتل کر دو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمای: ’’جو مسلمان اپنا دین بدل لے، اسے قتل کر دو۔‘‘"}],[4063,"حسن بصری کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنا دین بدلا اسے قتل کر دو\"۔ ابوعبدالرحمٰن نسائی کہتے ہیں: یہ عباد کی حدیث کی بہ نسبت صواب کے زیادہ قریب ہے ۱؎۔\n§وضاحت\n۱؎: یعنی قتادہ کے طریق سے اس روایت کا :(بجائے ابن عباس رضی اللہ عنہما کے حسن بصری کی روایت سے ) مرسل ہونا ہی صحیح ہے، ورنہ قتادہ کے سوا دوسروں کے طریق سے یہ روایت مرفوع ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت حسن بصری سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص (مسلمان ہونے کے بعد) اپنا دین بدل لے، اسے قتل کر دو۔‘‘\nامام ابو عبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ حدیث عباد کی حدیث سے زیادہ درست ہے۔","f2":"امام نسائی رحمہ اللہ کا مقصد یہ ہے کہ سعید عن قتادۃ عن عکرمۃ عن ابن عباس والی محمد بن بشر کی روایت اگرچہ مرسل ہے لیکن یہ عباد بن عوام کی سعید عن قتادۃ عن عکرمۃ عن ابن عباس کی موصول روایت کے مقابلے میں زیادہ صحیح اور درست ہے، اس لیے کہ محمد بن بشر خود عباد بن عوام سے احفظ (زیادہ حافظ) ہے۔ عباد بن عوام بھی اگرچہ ثقہ راوی ہے لیکن اس کی سعید بن ابی عروبہ سے مروی روایت میں اضطراب ہوتا ہے۔ عباد بن عوام بھی اگرچہ ثقہ راوی ہے لیکن اس کی سعید بن ابی عروبہ سے مروی روایت میں اضطراب ہوتا ہے۔ عباد کی مذکورہ روایت موصولاً بھی صحیح ہے جیسا کہ دوسری صحیح اسانید سے موصولاً یہ روایت مروی ہے، تاہم امام احمد رحمہ اللہ کا قول یہی ہے کہ عباد، سعید بن ابی عروبہ سے مضطرب الحدیث ہے۔ و اللہ اعلم۔"}],[4064,"انس رضی اللہ عنہ سے روایت ہے کہ ابن عباس رضی اللہ عنہما نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنا دین بدل لیا اسے قتل کر دو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو مسلمان اپنا دین بدل لے، اسے قتل کر دو۔‘‘"}],[4065,"انس رضی اللہ عنہ سے روایت ہے کہ علی رضی اللہ عنہ کے پاس کچھ جاٹ لائے گئے جو بت پوجتے تھے تو آپ نے انہیں جلا دیا ۱؎ ابن عباس رضی اللہ عنہما نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے تو بس اتنا کہا تھا \"جس نے اپنا دین بدل لیا، اسے قتل کر دو\"۔\n§وضاحت\n۱؎: علی رضی اللہ عنہ کا یہ فعل ان کی اپنی رائے اور اجتہاد کی بنیاد پر تھا، یہی وجہ ہے کہ جب انہیں ابن عباس رضی اللہ عنہما سے مروی یہ حدیث پہنچی تو انہوں نے اس سے رجوع کر لیا۔ :(واللہ اعلم )","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ تعالٰی عنہ سے منقول ہے کہ حضرت علی رضی اللہ تعالٰی عنہ کے پاس کچھ سوڈانی (یا ہندوستان) لوگ لائے گئے جنہوں نے (اسلام لانے کے بعد) ایک بت کی پوجا شروع کر دی تھی۔ آپ نے انہیں آگ میں جلا دیا۔ حضرت ابن عباس رضی اللہ عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے تو فرمایا تھا: ’’جو مسلمان اپنا دین بدل لے اسے قتل کر دو۔‘‘"}],[4066,"ابوموسی اشعری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے انہیں یمن بھیجا، پھر اس کے بعد آپ صلی اللہ علیہ وسلم نے معاذ بن جبل رضی اللہ عنہ کو بھیجا، جب وہ (معاذ) یمن آئے تو کہا: لوگو! میں تمہارے پاس رسول اللہ صلی اللہ علیہ وسلم کا قاصد ہوں، ابوموسی اشعری رضی اللہ عنہ نے ان کے لیے گاؤ تکیہ رکھ دیا تاکہ وہ اس پر (ٹیک لگا کر) بیٹھیں، پھر ایک شخص ان کے پاس لایا گیا جو یہودی تھا، وہ اسلام قبول کر لینے کے بعد کافر ہو گیا تھا، تو معاذ رضی اللہ عنہ نے کہا: میں نہیں بیٹھوں گا جب تک اللہ اور اس کے رسول کے فیصلے کی تعمیل کرتے ہوئے اسے قتل نہ کر دیا جائے۔ (ایسا) تین بار (کہا)، پھر جب اسے قتل کر دیا گیا تو وہ بیٹھے۔","الألباني: صحيح",{"u2":"حضرت ابو بردہ اپنے والد محترم (حضرت ابو موسیٰ اشعری رضی اللہ تعالٰی عنہ) سے بیان فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں یمن کی طرف (حاکم بنا کر) بھیجا۔ پھر اس کے بعد حضرت معاذ بن جبل رضی اللہ تعالٰی عنہ کو بھیجا۔ جب وہ آئے تو کہنے لگے: اے لوگو! میں تمہاری طرف رسول اللہ صلی اللہ علیہ وسلم کا قاصد ہوں۔ حضرت ابو موسیٰ رضی اللہ تعالٰی عنہ نے ان کے لیے تکیہ یا گدا رکھا تاکہ وہ اس پر بیٹھیں۔ اتنے میں ایک آدمی لایا گیا جو پہلے یہودی تھا، پھر مسلمان ہو گیا، پھر کافر بن گیا۔ حضرت معاذ رضی اللہ تعالٰی عنہ نے فرمایا: میں نہیں بیٹھوں گا حتیٰ کہ اسے قتل کر دیا جائے۔ یہ اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کا فیصلہ ہے۔ تین مرتبہ فرمایا، پھر جب اسے قتل کر دیا گیا تو آپ بیٹھے۔","f2":"(۱) حدیث کی باب کے ساتھ مناسبت بالکل واضح ہے کہ مرتد اگر اپنے ارتداد سے توبہ نہ کرے تو اس کا حکم یہ ہے کہ اسے قتل کر دیا جائے۔ (۲) اس حدیث سے معلوم وہتا ہے کہ ہر شخص اپنا تعارف کرا سکتا ہے، چاہے وہ صاحب مرتبہ ہو یا کوئی عام آدمی ہو جیسا کہ حضرت معاذ رضی اللہ تعالٰی عنہ نے اہل یمن کو اپنا تعارف کرایا۔ (۳) اس حدیث سے یہ بھی معلوم ہوتا ہے کہ علمائ، امراء اور مسلمان بھائی ایک دوسرے کی زیارت کے لیے جا سکتے ہیں۔ (۴) اکرام ضیف، یعنی مہمان کی عزت افزائی کرنے پر بھی یہ حدیث دلالت کرتی ہے، جس طرح کہ حضرت ابو موسیٰ رضی اللہ تعالٰی عنہ نے معزز مہمان حضرت معاذ رضی اللہ تعالٰی عنہ کے لیی تکیہ یا گدا وغیرہ بچھایا تھا۔ (۵) حدیث سے یہ مسئلہ بھی ثابت ہوتا ہے کہ کسی بھی منکر اور غیر شرعی کام کے انکار میں دیر نہیں کرنی چاہیے۔ (۶) جس شخص پر، اس کے کسی جرم کی وجہ سے، حد واجب ہو چکی ہو اس پر حد قائم کرنا ضروری ہے۔ (۷) یہ حدیث دلیل ہے کہ شرعی حد کی تنفیذ، حاکم وقت کی شرعی ذمہ داری ہے، اس میں سستی، غفلت اور اپنی صوابدید پر معافی دینا درست نہیں۔ و اللہ اعلم۔"}],[4067,"سعد رضی اللہ عنہ کہتے ہیں کہ جب فتح مکہ کا دن آیا تو رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو امان دے دی، سوائے چار مرد اور دو عورتوں کے، اور فرمایا: \"انہیں قتل کر دو چاہے تم انہیں کعبہ کے پردے سے چمٹا ہوا پاؤ\"، یعنی عکرمہ بن ابی جہل، عبداللہ بن خطل، مقیس بن صبابہ، عبداللہ بن سعد بن ابی سرح ۱؎۔ عبداللہ بن خطل اس وقت پکڑا گیا جب وہ کعبے کے پردے سے چمٹا ہوا تھا۔ سعید بن حریث اور عمار بن یاسر (رضی اللہ عنہما) اس کی طرف بڑھے، سعید عمار پر سبقت لے گئے، یہ زیادہ جوان تھے، چنانچہ انہوں نے اسے قتل کر دیا، مقیس بن صبابہ کو لوگوں نے بازار میں پایا تو اسے قتل کر دیا۔ عکرمہ (بھاگ کر) سمندر میں (کشتی پر) سوار ہو گئے، تو اسے آندھی نے گھیر لیا، کشتی کے لوگوں نے کہا: سب لوگ خالص اللہ کو پکارو اس لیے کہ تمہارے یہ معبود تمہیں یہاں کچھ بھی فائدہ نہیں پہنچا سکتے۔ عکرمہ نے کہا: اللہ کی قسم! اگر سمندر سے مجھے سوائے توحید خالص کے کوئی چیز نہیں بچا سکتی تو خشکی میں بھی اس کے علاوہ کوئی چیز نہیں بچا سکتی۔ اے اللہ! میں تجھ سے عہد کرتا ہوں کہ اگر تو مجھے میری اس مصیبت سے بچا لے گا جس میں میں پھنسا ہوا ہوں تو میں محمد (صلی اللہ علیہ وسلم) کے پاس جاؤں گا اور اپنا ہاتھ ان کے ہاتھ میں دے دوں گا اور میں ان کو مہربان اور بخشنے والا پاؤں گا، چنانچہ وہ آئے اور اسلام قبول کر لیا۔ رہا عبداللہ بن ابی سرح، تو وہ عثمان بن عفان رضی اللہ عنہ کے پاس چھپ گیا، جب رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو بیعت کے لیے بلایا۔ تو عثمان ان کو لے کر آئے اور اسے نبی اکرم صلی اللہ علیہ وسلم کے پاس لا کھڑا کر دیا اور بولے: اللہ کے رسول! عبداللہ سے بیعت لے لیجئے، آپ نے اپنا سر اٹھایا اور اس کی طرف تین بار دیکھا، ہر مرتبہ آپ انکار کر رہے تھے، لیکن تین مرتبہ کے بعد آپ نے اس سے بیعت لے لی، پھر اپنے صحابہ کی طرف متوجہ ہو کر فرمایا: \"کیا تم میں کوئی ایک شخص بھی سمجھ دار نہ تھا جو اس کی طرف اٹھ کھڑا ہوتا جب مجھے اس کی بیعت سے اپنا ہاتھ کھینچتے دیکھا کہ اسے قتل کر دے؟\" لوگوں نے عرض کیا: اللہ کے رسول! ہمیں کیا معلوم کہ آپ کے دل میں کیا ہے؟ آپ نے اپنی آنکھ سے ہمیں اشارہ کیوں نہیں کر دیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کسی نبی کے لیے یہ مناسب اور لائق نہیں کہ وہ کنکھیوں سے خفیہ اشارہ کرے\"۔\n§وضاحت\n۱؎: عکرمہ بن ابی جہل اپنے ایام شرک میں نبی کریم صلی اللہ علیہ وسلم کو پنے باپ کے ساتھ مل کر بہت تکلیفیں پہنچایا کرتے تھے، ابوجہل بدر کے دن مارا گیا، اور عکرمہ کو فتح مکہ کے دن قتل کر دینے کا حکم ہوا، اور عبداللہ بن خطل اسلام لا کر مرتد ہو گیا تھا، نیز دو لونڈیاں رکھتا تھا جو رسول اللہ صلی اللہ علیہ وسلم کی ہجو :(مذمت ) میں گایا کرتی تھیں، اور مقیس بن صبابہ اور عبداللہ بن ابی سرح دونوں مرتد ہو گئے تھے۔ ۲؎: «خائنۃ الأعین» دل میں جو بات ہو زبان سے نہ کہہ کر کے آنکھوں سے اشارہ کیا جائے، یہ بات ایک نبی کی شان کے خلاف ہے۔ اس لیے آپ صلی اللہ علیہ وسلم نے ایسا نہیں کیا۔","الألباني: صحيح",{"u2":"حضرت مصعب بن سعد اپنے والد محترم (حضرت سعد رضی اللہ تعالٰی عنہ) سے بیان فرماتے ہیں: جس دن مکہ مکرمہ فتح ہوا، رسول اللہ صلی اللہ علیہ وسلم نے چار مردوں اور دو عورتوں کے سوا تمام لوگوں کو امان دے دی۔ آپ نے فرمایا: ’’اگر تم ان کو کعبہ شریف کے پردوں سے لٹکا وہا پائو، تب بھی قتل کر دو۔‘‘ (وہ چار مرد یہ تھے:) عکرمہ بن ابی جہل، عبداللہ بن خطل، مقیس بن صبابہ اور عبداللہ بن سعد بن ابی سرح۔ عبداللہ بن خطل کعبے کے پردوں سے لٹکا ہوا پایا گیا۔ حضرت سعید بن حریث اور حضرت عمار بن یاسر رضی اللہ تعالٰی عنہ اس کی طرف لپکے۔ سعید عمار سے پہلے پہنچ گئے کیونکہ وہ عمار کی نسبت جوان تھے۔ انہوں نے اسے قتل کر دیا۔ مقیس بن صبابہ کو لوگوں نے بازار میں پکڑ لیا اور قتل کر دیا۔ عکرمہ بھاگ کر سمندر میں کشتی پر سوار ہو گیا۔ بہت تیز ہوا چل پڑی۔ (کشتی طوفان میں پھنس گئی۔) کشتی والے کہنے لگے: اب خالص اللہ تعالیٰ کو پکارو کیونکہ تمہارے معبود (بت وغیرہ) یہاں (طوفان میں) تمہیں کوئی فائدہ نہیں دے سکتے۔ عکرمہ نے کہا: اگر سمندر میں خالص اللہ تعالیٰ کو پکارنے کے علاوہ نجات نہیں تو خشکی میں بھی خالص اللہ تعالیٰ کو پکارے بغیر نجات نہیں مل سکتی۔ اے اللہ! میں تجھ سے عہد کرتا ہوں کہ اگر تو مجھے اس مصیبت سے، جس میں میں پھنس چکا ہوں، بچا لے تو میں ضرور حضرت محمد صلی اللہ علیہ وسلم کے پاس جا کر اپنا ہاتھ ان کے ہاتھ میں دے دوں گا اور مجھے یقین ہے کہ میں انہیں بہت زیادہ معاف کرنے والا اور احسان کرنے والا پائوں گا۔ پھر وہ آئے اور مسلمان ہو گئے۔ باقی رہا عبداللہ بن ابی سرح! تو وہ حضرت عثمان بن عفان رضی اللہ تعالٰی عنہ کے پاس چھپ گیا۔ جب رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو بیعت کے لیے بلایا تو حضرت عثمان اسے لے کر آئے حتیٰ کہ اسے بالکل آپ کے پاس کھڑا کر دیا اور عرض کی: اے اللہ کے رسول! عبداللہ سے بیعت لے لیں۔ آپ سر اٹھا کر اسے دیکھنے لگے۔ تین بار حضرت عثمان رضی اللہ تعالٰی عنہ نے یہی گزارش کی۔ آپ ہر دفعہ (عملاً) انکار فرما رہے تھے۔ آخر تیسری بار کے بعد آپ نے بیعت لے لی، پھر آپ اپنے صحابہ کی طرف متوجہ ہوئے اور فرمایا: ’’کیا تم میں کوئی سمجھ دار شخص نہیں تھا کہ جب تم دیکھ رہے تھے کہ میں نے اس کی بیعت لینے سے ہاتھ روک رکھا ہے تو کوئی شخص اٹھتا اور اسے قتل کر دیتا۔‘‘ انہوں نے عرض کی: اے اللہ کے رسول! ہمیں معلوم نہ تھا کہ آپ کے دل میں کیا ہے؟ آپ آنکھ سے ہلکا سا اشارہ فرما دیتے۔ آپ نے فرمایا: ’’نبی کے لائق نہیں کہ اس کی آنکھ خائن ہو۔‘‘","f2":"(۱) اس حدیث سے استدلال کیا گیا ہے کہ بیت اللہ میں حدود قائم کی جا سکتی ہیں لیکن یہ استدلال محل نظر ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے مساجد میں حدود قائم کرنے سے روکا ہے۔ (سنن ابی داود، حدیث: ۴۴۹۰) جب عام مساجد میں حدود قائم کرنا منع ہے تو بیت اللہ میں بالاولی منع ہو گا، تاہم اگر کوئی مجرم وہاں چھپتا ہے تو اس کو وہاں سے نکال کر اس پر حد قائم کی جا سکتی ہے۔ جہاں تک ابن خطل کے قتل کا تعلق ہے تو اس کا جواز اسی وقت سے مقید ہو گا کیونکہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے بیت اللہ کو محدود وقت کے لیے میرے لیے حلال کیا گیا تھا، البتہ حدود حرم کے اندر شرعی حد قائم کی جا سکتی ہے۔ (۲) توحید خالص، اللہ کی بارگاہ میں التجا اور عجز و نیاز کی وجہ سے دنیوی مصیبتیں بھی ٹل جاتی ہیں اور انسان مشکلات سے صحیح سلامت بچ نکلتا ہے۔ (۳) رسول اللہ صلی اللہ علیہ وسلم خلق عظیم کے مالک تھے۔ {وَاِِنَّکَ لَعَلٰی خُلُقٍ عَظِیْمٍ} (القلم: ۶۴:۴) مکارم اخلاق میں آپ درجۂ کمال پر فائز تھے۔ معاف کرنا، درگزر سے کام لینا، نیز اپنی باکمال شفقت و رحمت سے شاد کام کرنا، آپ کے ایسے عالی شان اور عمدہ فضائل و خصائل ہیں کہ بڑے سے بڑا دشمن بھی ان کا اعتراف کرنے پر مجبور ہے۔ ابو جہل ملعون کے بیٹے، جلیل القدر صحابیٔ رسول حضرت عکرمہ رضی اللہ تعالٰی عنہ کا اقرار اس کی واضح دلیل ہے۔ (۴) اللہ تعالیٰ جس کے ساتھ خیر و بھلائی کا ارادہ کرے، اسے وہ بھلائی او خیر مل کر ہی رہتی ہے۔ اللہ عز و جل کے ارادے کے مقابلے میں کسی کا ارادہ، خواہش اور چاہت پوری ہوتی ہے نہ رکاوٹ ہی بن سکتی ہے۔ (۵) قرائن قویہ پائے جانے کی وجہ سے کسی بھی عمل کی گنجائش نکلتی ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم کا بیعت نہ لینا ایک قوی قرینہ تھا کہ اسے قتل کیا جا سکتا ہے۔ اگر کوئی اس قرینے کو سمجھتے ہوئے عبداللہ بن سعد کو قتل کر دیتا تو جائز تھا۔ (۶) صحابۂ کرام رضی اللہ عنہم کمال درجے کے مؤدب رسول تھے کہ آپ کا صریح حکم نہ ملنے کی وجہ سے انہوں نے ایک بہت بڑے مجرم کو بھی قتل نہیں کیا۔ (۷) انبیاء و رسل علیہم السلام انتہائی ارفع و اعلیٰ شان کے مالک ہوتے ہیں بخلاف ملوک و سلاطین، امراء و وزراء اور عوام الناس کے، کہ وہ خفیہ ذریعے، اشارے اور طریقے سے لوگوں کے ساتھ قطعاً کوئی معاملہ نہیں کرتے۔ (۸) آنکھ وغیرہ سے مخفی اشارہ کرنے کو خیانت قرار دیا گیا ہے، لہٰذا کسی بھی دین دار اور اچھے انسان کے لیے یہ روا نہیں کیونکہ یہ بہت بڑا عیب ہے۔ (۹) ’’چار مرد، دو عورتیں‘‘ دیگر روایات میں اور مرد و عورتوں کا بھی ذکر ہے، مثلاً: وحشی بن حرب اور مفصد وغیرہ، البتہ کسی اور مرد اور عورت کو قتل نہیں کیا گیا۔ ان چار مرد اور دو عورتوں میں سے بھی بعض کو معاف مل گئی۔ (۱۰) ان چار مردوں میں سے تین عبداللہ بن خطل، مقیس بن صبابہ اور عبداللہ بن ابی سرح مسلمان ہو کر بعد میں مرتد ہو گئے تھے۔ عبداللہ بن ابی سرح دوبارہ مسلمان ہو گئے اور حضرت عثمان رضی اللہ تعالٰی عنہ کی سفارش پر ان کو معافی مل گئی۔ عبداللہ بن خطل اور مقیس بن صبابہ دونوں پر قتل کا جرم بھی ثابت تھا۔ دونوں نے ایک ایک مسلمان قتل کیا تھا اور بھاگ کر مکہ آ گئے اور مرتد ہو گئے تھے، لہٰذا ان کو قتل اور ارتداد کے جرم میں قتل کر دیا گیا۔ قتل کی وجہ سے ان کو معافی نہ مل سکتی تھی۔ البتہ عکرمہ بن ابی جہل کا کوئی ایسا جرم نہ تھا بلکہ ان کو اللہ کے دشمن ابوجہل کا بیٹا ہونے اور کفار قریش کا سردار ہونے کی وجہ سے قتل کا مستحق ٹھہرایا گیا۔ لیکن ان کی بیوی ام حکیم بنت حارث رضی اللہ عنہا نے ان کے لیے امان حاصل کی اور ان کو یمن سے واپس لے آئیں اور وہ مسلمان ہو گئے اور خوب مسلمان ہوئے حتی کہ فی سبیل اللہ جہاد کرتے ہوئے شہید ہوئے۔ رضی اللہ عنہ و ارضاہ۔ (۱۱) دو عورتیں عبداللہ بن خطل کی لونڈیاں تھیں جن کو اس نے مرتد ہونے کے بعد رسول اللہ صلی اللہ علیہ وسلم کی ہجو اور توہین کے لیے مقرر کیا تھا۔ رسول اللہ صلی اللہ علیہ وسلم کی توہین بھی سزائے موت کا مستحق بنا دیتی ہے۔ مگر ایک لونڈی کے مسلمان ہو جانے کی وجہ سے اس کو معاف کر دیا گیا اور دوسری کو قتل کر دیا گیا۔ (۱۲) ان مرد و عورت کے علاوہ حویرث بن نقید کو بھی رسول اللہ صلی اللہ علیہ وسلم کی ہجو و توہین کی سزا میں قتل کر دیا گیا۔ باقی سب مکہ والوں کو معافی مل گئی۔ (۱۳) ’’اس کی آنکھ خائن ہو‘‘ آپ حضرت عثمان رضی اللہ تعالٰی عنہ کی وجہ سے قتل کا حکم نہیں دے رہے تھے لیکن اگر کوئی قتل کر دیتا تو آپ روکتے بھی نہ کیونکہ اس کے قتل کا فرمان تو جاری ہو چکا تھا۔ اس بات کو کوئی سمجھ لیتا تو اسے قتل کر دیتا۔ آپ کے بیعت نہ لینے میں بھی اس طرح اشارہ تھا کہ قتل کا فرمان قائم ہے۔ آنکھ سے اشارۂ قتل آپ نہیں فرما سکتے تھے کیونکہ جو بات زبان سے نہیں کہہ رہے تھے، اسے آنکھ سے کہنا خیانت کی ذیل میں آ سکتا ہے۔ کہ حضرت عثمان رضی اللہ تعالٰی عنہ سے چھپا کر قتل کا حکم دیتے یہ نبی کی شان کے لائق نہ تھا۔ کوئی شخص خود سے نہیں اٹھا، لہٰذا آخر آپ نے بیعت لے لی - صلی اللہ علیہ وسلم - (۱۴) ثابت ہوا مرتد توبہ کرے اور اسلام قبول کرنے کا اعلان کرے تو اس کی سزا کی معافی حاکم وقت کا اختیار ہے۔"}],[4068,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ انصار کا ایک شخص اسلام لایا پھر وہ مرتد ہو گیا اور مشرکین سے جا ملا۔ اس کے بعد شرمندہ ہوا تو اپنے قبیلہ کو کہلا بھیجا کہ میرے سلسلے میں رسول اللہ صلی اللہ علیہ وسلم سے پوچھو: کیا میرے لیے توبہ ہے؟ اس کے قبیلہ کے لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور بولے: فلاں شخص (اپنے کئے پر) شرمندہ ہے اور اس نے ہم سے کہا ہے کہ ہم آپ سے پوچھیں: کیا اس کی توبہ ہو سکتی ہے؟ اس وقت یہ آیت اتری: «كيف يهدي اللہ قوما كفروا بعد إيمانهم» سے «غفور رحيم» تک \"اللہ اس قوم کو کیوں کر ہدایت دے گا جو ایمان لانے اور نبی اکرم صلی اللہ علیہ وسلم کی حقانیت کی گواہی دینے اور اپنے پاس روشن دلیلیں آ جانے کے بعد کافر ہوئی، اللہ تعالی ایسے بے انصاف لوگوں کو راہ راست پر نہیں لاتا، ان کی تو یہی سزا ہے کہ ان پر اللہ تعالی کے تمام فرشتوں کی اور تمام لوگوں کی لعنت ہو، جس میں یہ ہمیشہ پڑے رہیں گے، نہ تو ان سے عذاب ہلکا کیا جائے گا اور نہ ہی انہیں مہلت دی جائے گی، مگر وہ لوگ جن ہوں نے اس سے توبہ کر لی اور نیک ہو گئے، پس بیشک اللہ غفور رحیم ہے\" (آل عمران: ۸۶-۸۹) تو آپ نے اسے بلا بھیجا اور وہ اسلام لے آیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ انصار میں سے ایک آدمی مسلمان ہو گیا، پھر مرتد ہو گیا اور مشرکوں سے جا ملا۔ بعد ازاں وہ شرمندہ ہوا تو اس نے اپن قوم کو پیغام بھیجا کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھو، کیا میری توبہ قبول ہو سکتی ہے؟ اس کی قوم کے لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہنے لگے کہ فلاں شخص نادم ہے اور اس نے ہمیں پیغام دیا ہے کہ ہم آپ سے پوچھیں، کیا اس کی توبہ قبول ہو سکتی ہے؟ چنانچہ یہ آیت اتری: {کَیْفَ یَہْدِی اللّٰہُ قَوْمًا کَفَرُوْا بَعْدَ اِیْمَانِہِمْ … غَفُوْرٌ رَّحِیْمٌ} ’’اللہ تعالیٰ ان لوگوں کو کیسے ہدایت دے گا جو اپنے ایمان لانے کے بعد کافر ہو گئے، جبکہ وہ گواہی دے چکے کہ بے شک رسول اللہ(صلی اللہ علیہ وسلم) برحق ہیں اور ان کے پاس واضح نشانیاں آ چکیں اور اللہ ظالم قوم کو ہدایت نہیں دیتا۔ ان لوگوں کی سزا یہی ہے کہ ان پر اللہ کی، فرشتوں کی اور سب لوگوں کی لعنت ہے۔ وہ اس (لعنت) میں ہمیشہ رہیں گے،خ ان سے عذاب نہ تو ہلکا کیا جائے گا اور نہ ان کو مہلت ہی دی جائے گی۔ مگر جن لوگوں نے اس کے بعد توبہ کر کے اپنی اصلاح کر لی، بے شک اللہ تعالیٰ بہت درگزر اور نہایت رحم کرنے والا ہے۔‘‘ پھر اسے پیغام بھیجا گیا اور وہ مسلمان ہو گیا۔","f2":"(۱) باب کے ساتھ حدیث کی مناسبت واضح ہے کہ مرتد کی توبہ قابل قبول ہے۔ (توبہ نہ کرنے کی صورت میں اس کی سزا قتل ہے۔) (۲) حدیث شریف سے بعض آیاتِ قرآنی کا سبب نزول معلوم ہوتا ہے۔ (۳) اس حدیث سے یہ بات بھی معلوم ہوتی ہے کہ ارتداد کی وجہ سے سابقہ تمام اعمالِ صالح باطل اور ضائع ہو جاتے ہیں۔ (۴) خالص توبہ کرنے سے تمام برے اعمال اور کفریہ و شرکیہ عقائد مٹ جاتے ہیں، خواہ جس نوعیت ہی کے ہوں۔ (۵) یہ حدیث شریف اللہ تعالیٰ کی کمال مہربانی، وافر فضل و کرم اور وسعتِ معافی پر بھی دلالت کرتی ہے کہ اگر کوئی شخص اللہ رب العزت سے عمداً اعراض کرتا ہے، پھر توبہ کرتا ہے تو اسے بھی معافی مل جاتی ہے۔ و اللہ اعلم۔"}],[4069,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ انہوں نے سورۃ النحل کی اس آیت: «من كفر باللہ من بعد إيمانه إلا من أكره» \"جس نے ایمان لانے کے بعد اللہ کا انکار کیا سوائے اس کے جسے مجبور کیا گیا ہو … ان کے لیے درد ناک عذاب ہے\" (النحل: ۱۰۶) کے بارے میں کہا: یہ منسوخ ہو گئی اور اس سے مستثنی یہ لوگ ہوئے، پھر یہ آیت پڑھی: «ثم إن ربك للذين هاجروا من بعد ما فتنوا ثم جاهدوا وصبروا إن ربك من بعدها لغفور رحيم» \"پھر جو لوگ فتنے میں پڑ جانے کے بعد ہجرت کر کے آئے، جہاد کیا اور صبر کیا تو تیرا رب بخشنے والا مہربان ہے\" (النحل: ۱۱۰) اور کہا: وہ عبداللہ بن سعد بن ابی سرح تھے جو (عثمان رضی اللہ عنہ کے زمانے میں) مصر کے والی ہوئے، یہ رسول اللہ صلی اللہ علیہ وسلم کے منشی تھے، انہیں شیطان نے بہکایا تو وہ کفار سے مل گئے، آپ صلی اللہ علیہ وسلم نے فتح مکہ کے دن حکم دیا کہ انہیں قتل کر دیا جائے تو ان کے لیے عثمان بن عفان رضی اللہ عنہ نے پناہ طلب کی، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں پناہ دے دی ۱؎۔\n§وضاحت\n۱؎: باب کی دونوں حدیثوں کا خلاصہ یہ ہے کہ مرتد اگر توبہ کر لے تو اس کی توبہ قبول ہو گی، ان شاء اللہ۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ نے سورہ نحل کی آیت: {مَنْ کَفَرَ بِاللّٰہِ مِنْ بَعْدِ اِیْمَانِہٖٓ اِلَّا مَنْ اُکْرِہَ …} ’’جو شخص اپنے ایمان لانے کے بعد کفر کرے، سوائے اس کے جس پر جبر کیا گیا اور اس کا دل ایمان پر مطمئن تھا، لیکن جس نے کفر کے لیے اپنا سینہ کھول دیا (راضی خوشی کفر کیا) تو ایسے لوگوں پر اللہ کا غضب ہے اور ان کے لیے بہت بڑا عذاب ہے۔‘‘ کے بارے میں فرمایا کہ پھر اسے منسوخ کر دیا گیا، یعنی اس سے یہ مستثنیٰ کر لیا گیا۔ {ثُمَّ اِنَّ رَبَّکَ لِلَّذِیْنَ ہَاجَرُوْا …} ’’پھر تیرا رب ان لوگوں کو جنہوں نے آزمائش میں پڑنے کے بعد ہجرت کی، پھر جہاد کیا اور صبر کیا (ثابت قدم رہے) بے شک آپ کا رب ان (آزمائشوں) کے بعد (ان لوگوں کو) بہت معاف فرمانے والا اور رحم کرنے والا ہے۔‘‘ اس سے مراد عبداللہ بن سعد بن ابو سرح ہیں جو (بعد میں حضرت عثمان رضی اللہ تعالٰی عنہ کے دور خلافت میں) مصر کے گورنر رہے۔ رسول اللہ صلی اللہ علیہ وسلم کے لیے (وحی و خطوط وغیرہ) لکھا کرتے تھے۔ شیطان نے انہیں پھسلا دیا اور وہ کافروں سے جا ملے۔ فتح مکہ کے دن آپ نے ان کے قتل کا حکم جاری فرما دیا لیکن حضرت عثمان بن عفان رضی اللہ تعالٰی عنہ نے ان کیل یے پناہ مانگی تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں پناہ دے دی (اور ان کا اسلام قبول کر لیا)۔","f2":"(۱) باب سے حدیث شرف کی مطابقت بالکل واضح ہے کہ مرتد کی توبہ بھی قبول ہے۔ (۲) آیات و احکام الٰہی کا نسخ شرعاً ثابت ہے اور اس مسئلے کی بابت اہل اسلام کا اجماع ہے کہ دین میں کئی احکام پہلے دئیے گئے، بعد ازاں انہیں منسوخ کر دیا گیا۔ پھر کبھی تو ان سابقہ احکام کی مثل عطا فرمایا گیا اور کبھی ان سے بھی بہتر۔ ارشاد باری ہے: {مَا نَنْسَخْ مِنْ اٰیَۃٍ اَوْ نُنْسِہَا نَاْتِ بِخَیْرٍ مِّنْہَآ اَوْ مِثْلِہَا} (البقرۃ ۲:۱۰۶) ’’جس آیت کو ہم منسوخ کر دیں یا بھلا دیں، اس سے بہتر یا اس جیسی اور لاتے ہیں۔‘‘ (۳) تشریح و تنسیخ احکام میں محض اللہ عز و جل کی حکمتِ بالغہ کار فرما ہے۔ وہ ہر چیز کو خوب جانتا اور ہر چیز پر خوب قدرت رکھتا ہے۔ جب، اور جب تک وہ چاہتا ہے کسی چیز کی بابت اسے بجا لانے کا حکم فرماتا ہے اور جس وقت چاہتا ہے اسے ختم فرما دیتا ہے۔ وہ {فَعَّالٌ لِّمَا یُرِیْدُ} ہے۔ (۴) یہ حدیث دلالت کرتی ہے کہ اگر کسی کو زبردستی کفر کرنے پر مجبور کر دیا جائے جبکہ اس شخص کا دل ایمان پر مطمئن ہو تو وہ شخص قابل مؤاخذہ نہیں۔ (۵) اس سے یہ مسئلہ بھی ثابت ہوا کہ جب ربردستی کرائے جانے والے کفر پر گرفت نہیں تو جو …کفریہ اعمال… اس سے کم تر درجے کے ہیں، ان پر بطریق اولیٰ کوئی مؤاخذہ نہیں ہو گا۔ بندوق کے زور پر یا کسی اور طریقے سے زبردستی کی جانے والی طلاق بھی نافذ نہیں ہو گی۔ (۶) کسی بھی معاملے میں جائز سفارش، حاکم یا غیر حاکم کے پاس کی جا سکتی ہے جیسا کہ حضرت عثمان رضی اللہ تعالٰی عنہ نے حضرت عبداللہ بن سعد بن ابو سرح رضی اللہ تعالٰی عنہ کی سفارش رسول اللہ صلی اللہ علیہ وسلم سے کی تھی۔ (۷) حاکم چاہے تو کسی کی جائز سفارش قبول کر لے، چاہے تو رد کر دے اسے اس کا اختیار ہے۔ (۸) رسول اللہ صلی اللہ علیہ وسلم کے ہاں حضرت عثمان رضی اللہ تعالٰی عنہ کا عظیم مقام و مرتبہ بھی اس حدیث پاک سے معلوم ہوتا ہے کہ آپ نے ایک بہت بڑے مجرم کی بابت ان کی سفارش قبول فرما لی، حالانکہ قبل ازیں نبی صلی اللہ علیہ وسلم اسے قتل کرنے کا حکم صادر فرما چکے تھے اور حرم شریف کے اندر بھی اس کا خون بہانا جائز اور حلال ہو چکا تھا۔ وَ لِلّٰہِ دَرُّہٗ۔ (۹) یہ حدیث دلالت کرتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کمال درجے کے مہربان و شفیق انسان تھے۔ مرتد ہو جانے والے، انتہائی ایذا رساں شخص کو معاف کر دینا، آپ کے رحمۃ للعالمین ہونے کا عجیب مظہر ہے۔ صلی اللہ علیہ وسلم- فداہ أبی و أمی و عرضی۔ (۱۰) اس بات پر اتفاق ہے کہ مرتد مرد اور مرتد عورت اگر توبہ کر لیں اور دوبارہ اسلام قبول کر لیں تو ان کو قتل نہیں کیا جائے گا۔ یہ بات رسول اللہ صلی اللہ علیہ وسلم نے حضرت معاذ بن جبل رضی اللہ تعالٰی عنہ کو یمن بھیجتے وقت ارشاد فرمائی تھی۔ اگر وہ توبہ نہ کریں تو انہیں بے دریغ قتل کر دیا جائے گا، مرد ہو یا عورت۔ احناف عورت کو ارتداد کی سزا میں قتل کرنے کے قائل نہیں مگر ان کے پاس اس کی کوئی دلیل نہیں۔"}],[4070,"عثمان شحام کہتے ہیں کہ میں ایک اندھے آدمی کو لے کر عکرمہ کے پاس گیا تو وہ ہم سے بیان کرنے لگے کہ مجھ سے عبداللہ بن عباس رضی اللہ عنہما نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک نابینا آدمی تھا، اس کی ایک ام ولد (لونڈی) تھی، اس سے اس کے دو بیٹے تھے، وہ رسول اللہ صلی اللہ علیہ وسلم کو بہت برا بھلا کہتی تھی، وہ اسے ڈانٹتا تھا مگر وہ مانتی نہیں تھی، وہ اسے روکتا تھا مگر وہ باز نہ آتی تھی (نابینا کا بیان ہے) ایک رات کی بات ہے میں نے نبی اکرم صلی اللہ علیہ وسلم کا ذکر کیا تو اس نے آپ کو برا بھلا کہا، مجھ سے رہا نہ گیا، میں نے خنجر لیا اور اس کے پیٹ پر رکھ کر اسے زور سے دبایا اور اسے مار ڈالا، وہ مر گئی، اس کا تذکرہ نبی اکرم صلی اللہ علیہ وسلم سے کیا گیا تو آپ نے لوگوں کو جمع کیا اور فرمایا: \"میں قسم دیتا ہوں اس کو جس پر میرا حق ہے! جس نے یہ کیا ہے وہ اٹھ کھڑا ہو\"، تو وہ نابینا گرتا پڑتا آیا اور بولا: اللہ کے رسول! یہ میرا کام ہے، وہ میری ام ولد (لونڈی) تھی، وہ مجھ پر مہربان اور رفیق تھی، میرے اس سے موتیوں جیسے دو بیٹے ہیں، لیکن وہ آپ کو اکثر برا بھلا کہتی تھی اور آپ کو گالیاں دیتی تھی، میں اسے روکتا تھا تو وہ باز نہیں آتی تھی، میں اسے ڈانٹتا تھا تو وہ اثر نہ لیتی تھی، کل رات کی بات ہے میں نے آپ کا تذکرہ کیا تو اس نے آپ کو برا بھلا کہا، میں نے خنجر لیا اور اسے اس کے پیٹ پر رکھ کر زور سے دبایا یہاں تک کہ وہ مر گئی، یہ سن کر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سنو! تم لوگ گواہ رہو اس کا خون رائیگاں ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی: اس کے خون کا قصاص یا خون بہا :(دیت ) نہیں ہے، معلوم ہوا کہ نبی اکرم صلی اللہ علیہ وسلم کو گالی دینا، آپ پر طعن و تشنیع کرنا اور اس سے باز نہ آنے کی واجبی سزا قتل ہے اور آپ کو گالیاں دینے اور سب و شتم کرنے والا خواہ ذمی ہی کیوں نہ ہو قتل کیا جائے گا، اور یہ واضح رہے کہ یہ عمل صرف اسلامی حکومت اپنی حکومت ہی میں نافذ کر سکتی ہے کیونکہ اس کا تعلق حدود سے ہے جس کے لیے اسلامی حکومت اور حکمرانی کا ہونا ضروری ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت عثمان شحام سے روایت ہے، انہوں نے کہا کہ میں ایک نابینا شخص کو لیے جا رہا تھا کہ میں حضرت عکرمہ کے پاس پہنچا تو وہ بیان فرمانے لگے کہ مجھے ابن عباس رضی اللہ عنہ نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک نابینا شخص تھا۔ اس کی ایک لونڈی تھی جس سے اس کے دو بیٹے بھی تھے لیکن وہ اکثر رسول اللہ صلی اللہ علیہ وسلم کی عیب جوئی کیا کرتی اور آپ کو گالیاں بکتی تھی۔ وہ (نابینا شخص) اسے ڈانٹتا تھا مگر وہ باز نہ آتی تھی، وہ اسے روکتا تھا مگر وہ رکتی نہ تھی۔ (وہ نابینا شخص کہتے ہیں:) ایک رات میں نے نبیٔ اکرم صلی اللہ علیہ وسلم کا ذکر کیا تو اس نے آپ کو پھر برا بھلا کہنا شروع کر دیا تو میں صبر نہ کر سکا۔ میں نے ایک خنجر پکڑا اور اس کے پیٹ پر رکھ کر اوپر سے پورا بوجھ ڈال دیا اور اسے قتل کر دیا۔ صبح ہوئی تو اس کے قتل کا شور مچ گیا۔ نبی صلی اللہ علیہ وسلم سے بھی اس (کے قتل) کا تذکرہ کیا گیا، چنانچہ آپ نے سب لوگوں کو اکٹھا کیا اور فرمایا: ’’میں اس شخص کو جس پر میرا حق ہے اور اس نے یہ کام کیا ہے، اللہ کی قسم دے کر کہتا ہوں کہ وہ کھڑا ہو جائے۔‘‘ چنانچہ وہ نابینا شخص لڑکھڑاتا ہوا آیا اور کہا: اے اللہ کے رسول! میں نے اسے قتل کیا ہے۔ یہ میری لونڈی تھی اور میرے ساتھ بہت شفقت اور محبت کرنے والی تھی اور اس سے میرے موتیوں جیسے دو بیٹے بھی ہیں لیکن وہ اکثر آپ کی عیب جوئی کیا کرتی تھی اور آپ کو گالیاں بکتی تھی۔ میں اسے روکتا تھا، وہ رکتی نہ تھی۔ میں اسے ڈانٹتا تھا، وہ سمجھتی نہ تھی۔ گزشتہ رات میں نے آپ کا ذکر کیا تو وہ آپ کو برا بھلا کہنے لگی۔ (میں صبر نہ کر سکا۔) میں نے خنجر پکڑا اور اس کے پیٹ پر رکھ کر پورا بوجھ ڈال دیا حتی کہ میں نے اسے قتل کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’خبردار! گواہ رہو کہ اس کا خون ضائع ہے۔ (اس کے قتل کا قصاص ہے نہ دیت)۔‘‘","f2":"(۱) حدیث کی باب کے ساتھ مناسبت بالکل صریح ہے کہ نبی صلی اللہ علیہ وسلم کو گالی بکنے والے کی سزا قتل ہے۔ (۲) اللہ تعالیٰ کی ذاتِ اقدس اور نبی صلی اللہ علیہ وسلم کی پاکیزہ ذات کی بابت اس قسم کی زبان درازی کرنے سے ذمی شخص کا ذمہ اور مسلمان کا اسلام ختم ہو جاتا ہے۔ (۳) اس حدیث سے معلوم ہوا نبیٔ اکرم صلی اللہ علیہ وسلم کو گالی دینے والا واجب القتل ہے، خواہ مرد ہو یا عورت۔ وہ اگر مسلمان تھا تو گالی دینے سے کافر و مرتد بن گیا کیونکہ رسالت کی تصدیق نہ رہی، اور ایک مسلمان کے لیے توحید و رسالت کی تصدیق ضروری چیز ہے، لہٰذا اسے ارتداد والی سزا دی جائے گی اور اگر وہ ذمی تھا تو آپ صلی اللہ علیہ وسلم کو گالی دینے سے اس کا ذمہ ختم ہو گیا کیونکہ اسلامی حکومت کے تحت کافروں کے لیے ذمہ اور پناہ رسول اللہ صلی اللہ علیہ وسلم کی طرف سے ہے، اور آپ کو گالی دینا ذمہ سے دست بردار ہونے کے مترادف ہے، اس لیے اس کا خون معصوم و محفوظ نہ رہا، چنانچہ اسے قتل کیا جائے گا۔ مذکورہ حدیث اس معنی میں صریح ہے۔ وہ لونڈی بھی کافر اور ذمی تھی، مسلمان نہ تھی۔ کعب بن اشرف کا قتل بھی اس مسئلے کی واضح دلیل ہے۔ الا یہ کہ وہ توبہ کر کے مسلمان ہو جائے کیونکہ اسلام پہلے کے ہر گناہ کو ختم کر دیتا ہے۔ ائمۂ کرام میں سے صرف امام ابو حنیفہ رحمہ اللہ سے منقول ہے کہ ’’ذمیوں کو اس جرم میں قتل نہ کیا جائے گا کیونکہ ان کے دوسرے عقائد جو خالص کفر و شرک ہیں، ان کے خون کو مباح نہیں کرتے تو یہ جرم کیسے مباح کر دے گا؟‘‘ حالانکہ ان کو اپنے عقائد و اعمال پر کاربند رہنے کی اجازت ہے مگر علانیہ نہیں۔ نبی صلی اللہ علیہ وسلم کو گالی بکنا کوئی مخفی چیز نہیں بلکہ یہ علانیہ ہو گا، نیز جس طرح انہیں یہ اجازت نہیں کہ کسی کو قتل کریں، اسی طرح ان کو یہ بھی اجازت نہیں کہ آپ صلی اللہ علیہ وسلم کو گالی دیں۔ آپ صلی اللہ علیہ وسلم کو گالی دینا یقینا ایک مسلمان کو قتل کرنے سے بڑھ کر ہے۔ ان کا ذمی ہونا انہیں ہر من مانی کی اجازت نہیں دیتا۔ عام آدمی کو بھی گالی دینے کی اجازت نہیں چہ جائیکہ مسلمانوں کے جان و ایمان سے بڑھ کر محترم نبیٔ اکرم صلی اللہ علیہ وسلم کو (خاکم بدہن) گالی دینے کی اجازت ہو۔ (۴) آفریں صد آفریں ہے اس نابینا صحابی کی ایمان غیرت اور دینی حمیت پر کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی محبت میں ایسے ڈوبے ہوئے تھے جس کی مثال ناپید ہے۔ ہر چند وہ ظاہری بصارت سے محروم تھے، مگر اس کی تلافی ان کی بصیرت اور حب رسول کی معراج سے ہو گئی۔ اس غیور شخص نے اپنے معصوم بچوں کی ماں، اپنی کور چشمی کی لاٹھی اور جاں نثار رفیقۂ زندگی کو آپ کی گستاخی پر موت کے گھاٹ اُتار دیا، اس لیے کہ وہ اس کی متاعِ ایمان و دین کی غارت گر تھی۔ اس بے ادب لونڈی کا جرم اس قدر سنگین تھا کہ جس میں مداہنت کرنا اور چشم پوشی سے کام لینا مومن کی دینی غیرت و حمیت کے منافی اور اس کی شانِ اسلام کے خلاف ہے۔ (۵) اس حدیث شریف سے صحابۂ کرام رضی اللہ عنہم کی اس قلبی الفت و محبت اور شعوری و بابصیرت عقیدت کی نشاندہی بھی ہوتی ہے کہ جس کے مقابلے میں وہ لوگ افرادِ مخلوق میں سے کسی قریبی سے قریبی عزیز اور تعلق دار کی محبت کو خاطر میں لاتے نہ کسی قسم کی مصلحت ہی کو آڑے آنے دیتے تھے۔ رضی اللہ تعالی عنہم أجمعین۔"}],[4071,"ابوبرزہ اسلمی رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے ابوبکر صدیق رضی اللہ عنہ سے سخت کلامی کی تو میں نے کہا کہ کیا میں اسے قتل کر دوں؟ تو آپ نے مجھے جھڑکا اور کہا: یہ مقام رسول اللہ صلی اللہ علیہ وسلم کے بعد کسی کا نہیں ہے ۱؎۔\n§وضاحت\n۱؎: صرف نبی اکرم صلی اللہ علیہ وسلم کو گالی دینے اور سب و شتم پر کسی کو قتل کیا جائے گا، آپ کے سوا کسی کا یہ مرتبہ و مقام نہیں کہ اس کو سب و شتم کرنے والے کو قتل کی سزا دی جائے، ہاں تعزیر کی جا سکتی ہے، جو معاملہ کی نوعیت اور قاضی :(جج ) کی رائے پر منحصر ہے۔","الألباني: صحيح",{"u2":"حضرت ابو برزہ اسلمی رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ ایک آدمی نے حضرت ابوبکر صدیق رضی اللہ تعالٰی عنہ کے بارے میں کوئی بکواس بکا۔ میں نے کہا: میں اسے قتل کر دوں؟ انہوں نے مجھے ڈانٹا اور فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے بعد یہ کسی کا حق نہیں۔","f2":"(۱) خلیفۂ بلا فصل، یعنی خلیفۂ اول کے فرمان سے صاف معلوم ہو گیا کہ حضرت ابوبکر صدیق رضی اللہ تعالٰی عنہ کے نزدیک رسول اللہ صلی اللہ علیہ وسلم کو گالی بکنے والا واجب القتل ہے۔ (۲) اس حدیث سے یہ بھی معلوم ہوا کہ صحابہ کو یا کسی مسلمان حکمران کو گالی دینے والا قتل کا مستحق نہیں کیونکہ نبی صلی اللہ علیہ وسلم کے فرمان کی رو سے وہ فاسق ہے، کافر نہیں۔ سِبَابُ الْمُسْلِمِ فُسُوْقٌ۔ اسے کوئی اور سزا دی جائے گی، مثلاً: قید، کوڑے، جلاوطنی وغیرہ۔ (۳) اس حدیث شریف سے ثابت ہوتا ہے کہ خلیفۂ بلافصل حضرت ابوبکر صدیق رضی اللہ تعالٰی عنہ انتہائی متحمل مزاج، باحوصلہ اور بہت زیادہ درگزر کرنے او معاف کرنے والے انسان تھے۔ (۴) حضرت ابو برزہ رضی اللہ تعالٰی عنہ خلیفۂ رسول کی محبت میں اس قدر سرشار تھے کہ ان کی ذات کے متعلق سوء ادبی کے مرتکب شخص کا سر تن سے جدا کرنے پر تیار ہو گئے تھے۔"}],[4072,"ابوبرزہ رضی اللہ عنہ کہتے ہیں کہ ابوبکر رضی اللہ عنہ ایک آدمی پر غصہ ہوئے، تو میں نے کہا: اے خلیفہ رسول! یہ کون ہے؟ کہا: کیوں؟ میں نے کہا: تاکہ اگر آپ کا حکم ہو تو میں اس کی گردن اڑا دوں؟ انہوں نے کہا: کیا تم ایسا کر گزرو گے؟ میں نے کہا: جی ہاں، ابوبرزہ کہتے ہیں: اللہ کی قسم! میری اس بات کی سنگینی نے جو میں نے کہی ان کا غصہ ٹھنڈا کر دیا، پھر وہ بولے: یہ مقام محمد صلی اللہ علیہ وسلم کے بعد کسی کا نہیں۔","الألباني: صحيح",{"u2":"حضرت ابو برزہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ حضرت ابوبکر رضی اللہ تعالٰی عنہ ایک آدمی پر ناراض ہوئے (کیونکہ اس نے آپ کو گالی دی تھی)۔ میں نے کہا: اے خلیفۂ رسول! یہ کون شخص ہے؟ فرمایا: کیوں؟ میں نے کہا: تاکہ میں اس کی گردن اتار سکوں بشرطیکہ آپ مجھے حکم دیں۔ انہوں نے فرمایا: تو ایسے کر گزرے گا؟ میں نے کہا: ہاں۔ حضرت ابوبرزہ کہتے ہیں: اللہ کی قسم! جو بات میں نے کہی تھی اس کی عظمت نے حضرت ابوبکر رضی اللہ تعالٰی عنہ کا غصہ ختم کر دیا۔ پھر انہوں نے فرمایا: یہ حق رسول اللہ صلی اللہ علیہ وسلم کے بعد کسی اور کو حاصل نہیں۔"}],[4073,"ابوبرزہ رضی اللہ عنہ کہتے ہیں کہ میں ابوبکر رضی اللہ عنہ کے پاس سے گزرا، وہ اپنے ساتھیوں میں سے کسی پر غصہ ہو رہے تھے، میں نے کہا: اے رسول اللہ کے خلیفہ! یہ کون ہے جس پر آپ غصہ ہو رہے ہیں؟ کہا: آخر تم یہ کیوں پوچھ رہے ہو؟ میں نے کہا: تاکہ میں اس کی گردن اڑا دوں۔ ابوبرزہ کہتے ہیں: اللہ کی قسم! میری اس بات کی سنگینی نے ان کا غصہ ٹھنڈا کر دیا، پھر بولے: محمد صلی اللہ علیہ وسلم کے بعد کسی کا یہ مقام نہیں۔","الألباني: صحيح",{"u2":"حضرت ابوبرزہ رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں حضرت ابوبکر رضی اللہ تعالٰی عنہ کے پاس سے گزرا تو وہ اپنے ساتھیوں میں سے کسی آدمی پر غصے ہو رہے تھے۔ میں نے عرض کی: اے خلیفۂ رسول اللہ! یہ کون شخص ہے جس پر آپ اس قدر ناراض ہو رہے ہیں؟ فرمانے لگے: تم اسے بارے میں کیوں پوچھ رہے ہو؟ میں نے کہا: میں اس کی گردن اڑا دوں گا۔ حضرت ابوبرزہ نے کہا: اللہ کی قسم! میری اس بات نے ان کا غصہ ختم کر دیا۔ پھر آپ نے فرمایا: یہ حضرت محمد صلی اللہ علیہ وسلم کے بعد (آپ کے علاوہ) کسی کا حق نہیں۔"}],[4074,"ابوبرزہ رضی اللہ عنہ کہتے ہیں کہ ابوبکر رضی اللہ عنہ ایک شخص پر غصہ ہوئے، میں نے کہا: اگر آپ حکم دیں تو میں کچھ کروں، انہوں نے کہا: سنو، اللہ کی قسم! محمد صلی اللہ علیہ وسلم کے بعد کسی کا یہ مقام نہیں۔","الألباني: صحيح",{"u2":"حضرت ابوبرزہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ حضرت ابوبکر رضی اللہ تعالٰی عنہ کسی آدمی پر بہت ناراض ہوئے۔ میں نے کہا: اگر آپ مجھے حکم دیں تو میں کر گزروں (اسے قتل کر دوں)۔ انہوں نے فرمایا: اللہ کی قسم! حضرت محمد صلی اللہ علیہ وسلم کے بعد کسی انسان کو یہ حق حاصل نہیں۔","f2":"’’یہ حق حاصل نہیں‘‘ کہ اس کے کہنے سے کسی کو قتل کر دیا جائے، بغیر تحقیق کے کہ وہ قتل کا مستحق ہے یا نہیں۔ یہ صرف رسول اللہ صلی اللہ علیہ وسلم کی شان ہے کہ آپ جو بھی فرمائیں، اس پر بلاتحقیق عمل کیا جائے گا۔ دوسرے ہر شخص کی بات کی تحقیق کی جائے گی۔ صحیح ہو تو عمل کی جائے گا ورنہ چھوڑ دیا جائے گا، خواہ وہ خلیفہ اور حاکم ہو یا کوئی کمانڈر۔ دوسرے معنی پیچھے گزر چکے ہیں کہ صرف رسول اللہ صلی اللہ علیہ وسلم کو گالی دینے کی سزا قتل ہے، کسی اور کا یہ مرتبہ نہیں، خواہ وہ صحابی ہی ہو۔"}],[4075,"ابوبرزہ رضی اللہ عنہ کہتے ہیں کہ ابوبکر رضی اللہ عنہ ایک آدمی پر سخت غصہ ہوئے یہاں تک کہ ان کا رنگ بدل گیا، میں نے کہا: اے رسول اللہ کے خلیفہ! اللہ کی قسم! اگر آپ مجھے حکم دیں تو میں اس کی گردن اڑا دوں، اچانک دیکھا گویا آپ پر ٹھنڈا پانی ڈال دیا گیا ہو، چنانچہ اس شخص پر آپ کا غصہ ختم ہو گیا اور کہا: ابوبرزہ! تمہاری ماں تم پر روئے، یہ مقام تو رسول اللہ صلی اللہ علیہ وسلم کے بعد کسی کا ہے ہی نہیں۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ (ابونضرۃ) غلط ہے صحیح ابونصر ہے، ان کا نام حمید بن ہلال ہے۔ شعبہ نے مخالفت کرتے ہوئے اس (ابونضرۃ) کے برعکس (ابونصر) کہا ہے۔ (ان کی روایت آگے آ رہی ہے)۔","الألباني: صحيح",{"u2":"حضرت ابو برزہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ حضرت ابوبکر رضی اللہ تعالٰی عنہ ایک آدمی پر بہت زیادہ ناراض ہوئے حتی کہ ان کا رنگ بدل گیا۔ میں نے عرض کی: اے خلیفۂ رسول اللہ! اللہ کی قسم! اگر آپ مجھے حکم دیں تو میں اس کی گردن اتار دوں گا۔ (میری اس بات سے) گویا ان پر ٹھنڈا پانی ڈال دیا گیا، چنانچہ اس شخص پر سے ان کا غصہ ختم ہو گیا۔ اور فرمانے لگے: اے ابوبرزہ! تیری ماں تجھے گم پائے! رسول اللہ صلی اللہ علیہ وسلم کے بعد کسی کا یہ مرتبہ اور حق نہیں۔\nامام ابو عبدالرحمن نسائی (رحمہ اللہ) بیان کرتے ہیں کہ یہ غلط ہے۔ درست ابو نصر ہے اور اس (ابونصر) کا نام حمید بن ہلال ہے۔ شعبہ نے زید بن ابو انیسہ کی مخالفت کی ہے (یعنی عمرو بن مرہ سے اس کی روایت میں مخالفت کی ہے)۔","f2":"(۱) امام نسائی رحمہ اللہ یہ فرمانا چاہتے ہیں کہ عمرو بن مرہ سے مذکورہ حدیث زید نے بیان کی تو عَنْ عَمْرِو بْنِ مُرَّۃَ عَنْ أَبِیْ نَضْرَۃَ کہا۔ لیکن عمرو بن مرہ سے یہی روایت امام شعبہ نے بیان کی تو فرمایا: عَنْ عَمْرِو بْنِ مُرَّۃَ قَالَ: سَمِعْتُ أَبَا نَصْرٍ، یعنی ابو نضرہ (بالضاد) کے بجائے ابو نصر (بالصاد) کہا، نیز اس میں ۃ، یعنی جو حالت وقف میں ’’ہـ‘‘ پڑھی جاتی ہے، وہ بھی بیان نہیں کی، صرف ابو نصر کہا اور بس۔ امام نسائی رحمہ اللہ کا مقصد یہ ہے کہ شعبہ نے زید کی مخالفت کی ہے اور وہ زید سے احفظ و اتقن ہے، اس لیے شعبہ کی بات درست ہے اور صحیح لفظ ابو نصر ہے، جبکہ زید کی بات مبنی برخطا ہے۔ و اللہ اعلم۔ (۲) ’’رنگ بدل گیا‘‘ حضرت ابوبکر صدیق رضی اللہ تعالٰی عنہ انتہائی بردبار اور متحمل مزاج شخص تھے۔ جلدی اور زیادہ غصے میں نہیں آتے تھے۔ اس شخص نے کوئی بڑی غلطی یا گستاخی کی ہو گی جس پر اس قدر غصہ آ گیا۔ رضی اللہ عنہ و ارضاہ۔ (۳) ’’ٹھنڈا پانی‘‘ قربان جائیے خلیفۂ رسول پر کہ غلط بات سن کر حالت بدل گئی، حالانکہ ظاہراً یہ بات ان کے حق میں تھی۔ اگر کوئی خوشامد پسند بادشاہ ہوتا تو اس کا پارہ اور چڑھتا مگر یہ خلیفۂ رسول تھے۔ فوراً ناراضی کا اظہار فرمایا کہ میرے بارے میں غلو کیوں کیا؟ یاد رہے خلیفۂ رسول کا لقب صرف حضرت ابوبکر صدیق رضی اللہ تعالٰی عنہ کے ساتھ خاص تھا، باقی تمام خلفاء راشدین کو امیر المومنین کہا جاتا تھا۔ اور حق یہ ہے کہ انہوں نے خلافت رسول کا حق ادا کر دیا۔ جب تک اُس ’’کمزور جان‘‘ میں جان رہی، رسول اللہ صلی اللہ علیہ وسلم کے دین میں ذرہ بھر تبدیلی برداشت نہ کی۔ (۴) ’’تیری ماں تجھے گم پائے‘‘ یعنی تو مر جائے۔ یہ عربی زبان کا ایک محاورہ ہے اور اہل عرب میں اس کا استعمال عام ہے۔ اس جگہ اس کا مقصد اظہار ناراضی ہے نہ کہ بددعا۔ عرف عام میں ایسا ہوتا ہے۔ (۵) ’’یہ مرتبہ اور حق نہیں‘‘ کہ اس کی ناراضی کسی کے قتل کا موجب ہو۔ یہ صرف رسول اللہ صلی اللہ علیہ وسلم کی شان ہے کہ جس پر ناراض ہو جائیں، اسے قتل کرنے کی اجازت طلب کی جا سکتی ہے اور اجازت ملنے پر اسے قتل بھی کیا جا سکتا ہے۔ میری تیری ناراضی کا یہ درجہ نہیں۔"}],[4076,"ابوبرزہ رضی اللہ عنہ کہتے ہیں کہ میں ابوبکر رضی اللہ عنہ کے پاس آیا، انہوں نے ایک شخص کو کچھ سخت سست کہا تو اس نے جواب میں ویسا ہی کہا، میں نے کہا: کیا اس کی گردن نہ اڑا دوں؟ آپ نے مجھے جھڑکا اور کہا: رسول اللہ صلی اللہ علیہ وسلم کے بعد کسی کا یہ مقام نہیں۔ ابوعبدالرحمٰن نسائی کہتے ہیں: ابونصر کا نام حمید بن ہلال ہے اور اسے ان سے یونس بن عبید نے مسنداً روایت کیا ہے ۱؎۔\n§وضاحت\n۱؎: عمرو بن مرہ کی پچھلی دونوں سن دوں میں \"حمید بن ہلال\" اور \"ابوبرزہ رضی اللہ عنہ\" کے درمیان انقطاع ہے، اور یونس بن عبید کی یہ روایت متصل ہے کیونکہ اس میں \"حمید\" اور \"ابوبرزہ\" کے درمیان \"عبداللہ بن مطرف\" کا واسطہ ہے۔","الألباني: صحيح",{"u2":"حضرت ابو برزہ رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں حضرت ابوبکر رضی اللہ تعالٰی عنہ کے پاس آیا تو آپ کسی شخص پر سخت ناراض ہو رہے تھے۔ اس نے جواباً آپ کو کچھ کہا (بدتمیزی کی)۔ میں نے کہا: میں اس کی گردن نہ اتار دوں؟ آپ نے مجھے ڈانٹا اور فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے بعد کسی کو یہ حق حاصل نہیں۔\nامام ابو عبدالرحمن (نسائی) رحمہ اللہ فرماتے ہیں کہ ابو نصر کا نام حمید بن ہلال ہے، اور اس سے یہ حدیث یونس بن عبید نے بیان کی تو اس نے اس کو مسند، یعنی متصل بیان کیا ہے۔","f2":"امام نسائی رحمہ اللہ دراصل اس بات کی طرف اشارہ فرماتے ہیں کہ اس میں یونس بن عبید نے عمرو بن مرہ کی مخالفت کی ہے، اور وہ اس طرح کہ ابو نصر سے یہ حدیث عمرو بن مرہ نے بیان کی تو کہا: سَمِعْتُ اَبَا نَصْرٍ یُحَدِّثُ عَنْ اَبِیْ بَرْزَۃَ، اس طرح یہ روایت منقطع بنتی ہے اور یہی حدیث یونس بن عبید نے بیان کی تو کہا: عَنْ حُمَیْدِ بْنِ ہِلَالٍ عَنْ عَبْدِاللّٰہِ بْنِ مُطَرِّفِ بْنِ الشِّخِّیْرِ عَنْ اَبِیْ بَرْزَۃَ الْأَسْلَمِیِّ، یعنی یونس بن عبید نے حمید بن ہلال (ابو نصر) اور حضرت ابو برزہ اسلمی رضی اللہ تعالٰی عنہ کے درمیان عبداللہ بن مطرف کا واسطہ بیان کیا ہے، لہٰذا اس طرح سند متصل قرار پاتی ہے۔"}],[4077,"ابوبرزہ اسلمی رضی اللہ عنہ کہتے ہیں کہ ہم ابوبکر صدیق رضی اللہ عنہ کے پاس تھے، آپ ایک مسلمان آدمی پر غصہ ہوئے اور آپ کا غصہ سخت ہو گیا، جب میں نے دیکھا تو عرض کیا کہ اے خلیفہ رسول! کیا میں اس کی گردن اڑا دوں؟ جب میں نے قتل کا نام لیا تو انہوں نے یہ ساری گفتگو بدل کر دوسری گفتگو شروع کر دی، پھر جب ہم جدا ہوئے تو مجھے بلا بھیجا اور کہا: ابوبرزہ! تم نے کیا کہا؟ میں نے جو کچھ کہا تھا وہ بھول چکا تھا، میں نے کہا: مجھے یاد دلائیے، تو آپ نے کہا: کیا تم نے جو کہا تھا وہ تمہیں یاد نہیں آ رہا ہے؟ میں نے کہا: نہیں، اللہ کی قسم! تو آپ نے کہا: جب مجھے ایک شخص پر غصہ ہوتے دیکھا تو کہا تھا: اے خلیفہ رسول! کیا میں اس کی گردن اڑا دوں؟ کیا یہ تمہیں یاد نہیں ہے؟ کیا تم ایسا کر گزرتے؟ میں نے کہا: جی ہاں، اللہ کی قسم! اگر آپ اب بھی حکم دیں تو میں کر گزروں، تو آپ نے کہا: اللہ کی قسم! محمد صلی اللہ علیہ وسلم کے بعد اب کسی کا یہ مقام نہیں ہے۔ ابوعبدالرحمٰن نسائی کہتے ہیں: اس سے متعلق مروی احادیث میں یہ حدیث سب سے بہتر اور عمدہ ہے ۱؎۔\n§وضاحت\n۱؎: سند کے لحاظ سے بہتر اور عمدہ ہونا ہے، کیونکہ پچھلی دونوں سن دوں میں انقطاع ہے جیسا کہ گزرا۔","الألباني: صحيح",{"u2":"حضرت ابو برزہ اسلمی رضی اللہ تعالٰی عنہ سے روایت ہے کہ ہم حضرت ابوبکر صدیق رضی اللہ تعالٰی عنہ کے پاس بیٹھے تھے۔ آپ کسی مسلمان آدمی پر ناراض ہوئے اور انتہائی زیادہ ناراض ہوئے۔ جب میں نے یہ صورت حال دیکھی تو میں نے کہا: اے خلیفۂ رسول! میں اس کی گردن اتار دوں؟ جب میں نے قتل کا ذکر کیا تو اس بات کو آپ نے مکمل طور پر چھوڑ دیا اور ادھر ادھر کی باتیں شروع کر دیں۔ جب ہم متفرق ہو گئے تو آپ نے مجھے پیغام بھیجا اور فرمایا: ابو برزہ! تم نے کیا کہا تھا؟ میں اس وقت تک بھول چکا تھا کہ میں نے کیا کہا تھا۔ میں نے آپ سے کہا: مجھے یاد دلا دیجیے۔ آپ نے فرمای: کیا تجھے یاد نہیں، تو نے کیا کہا تھا؟ میں نے کہا: اللہ کی قسم! نہیں۔ آپ نے فرمایا: جب تو نے مجھے ایک آدمی پر ناراض ہوتے دیکھا تو تو نے کہا تھا: اے خلیفۂ رسول! میں اس کی گردن اتار دوں؟ کیا تجھے یہ بات یاد نہیں؟ کیا تو (واقعی) ایسے کر دیتا (یعنی اسے قتل کر دیتا؟) میں نے کہا: اللہ کی قسم! ہاں۔ اب بھی اگر آپ حکم دیں تو میں یہ کام کر گزروں گا۔ آپ نے فرمایا: اللہ کی قسم! یہ رتبہ حضرت محمد صلی اللہ علیہ وسلم کے بعد کسی کا بھی نہیں۔\nامام ابو عبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ ان احادیث میں یہ حدیث سب سے بہتر اور احسن ہے۔","f2":"یہ تفصیلی روایت ہے جس سے اوپر والی احادیث کے تمام ابہامات دور ہو جاتے ہیں۔ مسئلۂ باب کی وضاحت اس سے قبل ہو چکی ہے۔ دیکھئے، حدیث: ۴۰۷۵) اس مسئلے کے بارے میں امام ابن تیمیہ رحمہ اللہ کی ایک مستقل کتاب موجود ہے۔ ’’الصارم المسلول علی شاتم الرسول‘‘ یہ بہت مفید اور لائق مطالعہ کتاب ہے۔ اس میں حضرت امام نے تفصیلی دلائل کے ساتھ ثابت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو گالی بکنے والا واجب القتل ہے، خواہ مسلمان ہو یا کافر۔ ذمی کو تو حکومت علانیہ قتل کرے گی اور غیر مسلم ملک کے کافر کو خفیہ قتل کروایا جائے گا۔ یا جیسے بھی ممکن ہو۔ حکومت کرے یا کوئی عام مسلمان۔ و اللہ اعلم۔"}],[4078,"صفوان بن عسال رضی اللہ عنہ کہتے ہیں کہ ایک یہودی نے اپنے دوست سے کہا: ہمیں اس نبی کے پاس لے چلو، دوست نے اس سے کہا: تم یہ نہ کہو کہ وہ نبی ہے، اگر اس نے تمہاری بات سن لی تو اس کی چار چار آنکھیں ہوں گی (یعنی اسے بہت خوشی ہو گی)، پھر وہ دونوں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے نو واضح احکام کے بارے میں پوچھا (جو موسی علیہ السلام کو دیئے گئے تھے) ۱؎ آپ نے ان سے فرمایا: \"اللہ کے ساتھ کسی کو شریک نہ ٹھہراؤ، چوری اور زنا نہ کرو اور اللہ نے جس نفس کو حرام قرار دیا ہے اسے ناحق قتل نہ کرو، کسی بےقصور کو (سزا دلانے کی غرض سے) حاکم کے پاس نہ لے جاؤ، جادو نہ کرو، سود نہ کھاؤ، پاک دامن عورتوں پر الزام تراشی نہ کرو، جنگ کے دن پیٹھ دکھا کر نہ بھاگو، اور اے یہود! ایک حکم تمہارے لیے خاص ہے کہ تم ہفتے (سنیچر) کے دن میں غلو نہ کرو، یہ سن کر ان لوگوں نے آپ کے ہاتھ پاؤں چوم لیے ۲؎ اور کہا: ہم گواہی دیتے ہیں کہ آپ نبی ہیں، آپ نے فرمایا: \"پھر کون سی چیز تمہیں میری پیروی کرنے سے روک رہی ہے؟\" انہوں نے کہا: داود علیہ السلام نے دعا کی تھی کہ ہمیشہ نبی ان کی اولاد میں سے ہو، ہمیں ڈر ہے کہ اگر ہم آپ کی پیروی کریں گے تو یہودی ہمیں مار ڈالیں گے\"۔\n§وضاحت\n۱؎: \" آیات بینات سے مراد یا تو معجزات ہوتے ہیں یا واضح احکام، یہاں احکام مراد ہیں، اور جو نو معجزات موسی علیہ السلام کو دیئے گئے تھے وہ یہ تھے: عصاء، ید بیضاء، بحر طوفان، قحط، ٹڈیاں، کھٹمل، مینڈک، اور خون، اور جو نو واضح احکامات دیئے گئے تھے وہ اس حدیث میں مذکور ہیں اور یہ ساری شریعتوں میں دیئے گئے تھے۔ ۲؎: یہ حدیث ضعیف ہے، نیز ہاتھ چومنے سے متعلق ساری روایات ضعیف ہیں، ان سے استدلال صحیح نہیں، اور تعظیم و تکریم کا یہ عمل اگر صحیح ہوتا تو آپ کی صحبت میں رہنے والے جلیل القدر صحابہ اس کو ضرور اپناتے، لیکن کسی روایت سے یہ ثابت نہیں ہے کہ ابوبکر، عمر، عثمان اور علی وغیرہم رضی اللہ عنہ نے تعظیم کا یہ طریقہ اپنایا ہو۔","الألباني: ضعيف",{"u2":"حضرت صفوان بن عسال رضی اللہ تعالٰی عنہ سے مروی ہے کہ ایک یہودی نے اپنے ساتھی سے کہا: آئو اس نبی کے پاس چلیں۔ اس کے ساتھ نے اس سے کہا: اسے نبی نہ کہو۔ اگر اس نے تیری بات سن لی تو اس کی آنکھیں چار ہو جائیں گی۔ پھر وہ دونوں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے ’’نو واضح آیات‘‘ کے بارے میں پوچھا۔ آپ نے ان سے فرمایا: ’’اللہ تعالیٰ کے ساتھ کسی کو شریک نہ بنائو۔ چوری نہ کرو۔ زنا نہ کرو۔ کسی قابل احترام جان کو ناحق قتل نہ کرو۔ کسی بے گناہ شخص کو (ناحق سزا دلوانے کے لیے) صاحب اقتدار کے پاس نہ لے جائو۔ جادو نہ کرو۔ سود نہ کھائو۔ کسی پاک دامن پر الزام نہ لگائو او جنگ کے دن میدانِ جنگ سے نہ بھاگو۔ اور اے یہودیو! اص تمہارے لیے یہ حکم ہے کہ تم ہفتے کے دن (کی تعظیم) کے بارے میں (اللہ تعالیٰ کے حکم سے) تجاوز نہ کرو۔‘‘ چنانچہ ان دونوں نے (یہ سن کر) آپ کے ہاتھ اور پائوں چومے اور کہا: ہم گواہی دیتے ہیں کہ یقینا آپ نبی ہیں۔ آپ نے فرمایا: ’’پھر تمہیں میرا متبع بننے سے کون سی چیز مانع ہے؟‘‘ انہوں نے کہا: حضرت داود صلی اللہ علیہ وسلم نے دعا فرمائی تھی کہ ہمیشہ نبی ان کی نسل سے آئے، نیز ہم ڈرتے ہیں کہ اگر ہم نے آپ کی پیروی کی تو یہودی ہمیں قتل کر دیں گے۔","f2":"(۱) مذکورہ روایت کی صحت اور ضعف میں اختلاف ہے، تاہم بغرض تفہیم حدیث چند ضروری وضاحتیں حاضر خدمت ہیں: ’’اس کی آنکھیں چار ہو جائیں گی۔‘‘ یعنی وہ بہت خوش ہوں گے کیونکہ خوشی انسان کی قوتوں میں اضافہ کرتی ہے۔ یہ ایک محاورہ ہے۔ (۲) ’’وہ دونوں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے ’’نو واضح آیات‘‘ کے بارے میں پوچھا۔‘‘ ان آیات بینات سے کیا مراد ہے؟ آیات جمع ہے آیَۃٌ کی۔اس کے کئی ایک معانی ہیں، مثلاً: کسی چیز کی ظاہری علامت، نشان، خاص نشان، عبرت، سامانِ عبرت، ذات، جماعت، قرآن مقدس کا ایک جملہ یا چند جملے جن کے آخر میں وقف (گول دائرہ) ہوتا ہے۔ اسی طرح معجزہ بھی آیۃ کہلاتا ہے اور ہر وہ کلام جو لفظاً دوسرے کلام سے منفصل اور جدا وہتا ہے اس پر بھی اس کا اطلاق ہوتا ہے۔ یہ محسوسات پر بھی بولا جاتا ہے اور معقولات پر بھی جس طرح کہ علامۃ الطریق اور الحکم الواضح وغیرہ۔ اس جگہ حدیث میں اس سے کیا مراد ہے، احکام یا معجزے؟ اگر تسع آیات بینات سے مراد احکام ہوں، پھر تو حدیث میں کوئی اشکال باقی نہیں کہتا کیونکہ ان یہودیوں کو سوال کا جواب دیتے ہوئے رسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمایا: ’’شرک نہ کرو، چوری نہ کرو، کسی کو ناحق قتل نہ کرو، جادو نہ کرو، زنانہ کرو، سود نہ کھائو، کسی بے گناہ پر ظلم و زیادتی یا اسے قتل کرانے کے لیے حاکم و سلطان کے پاس نہ لے جائو وغیرہ، یعنی آپ نے ان کے سوال کے جواب میں احکام ذکر فرمائے ہیں۔ چونکہ سوال و جواب میں مطابقت ہے، لہٰذا کوئی اشکال باقی نہیں رہتا۔\nلیکن یہاں آیات بینات سے مراد احکام نہیں بلکہ معجزات ہیں۔ ایک تو اس لیے کہ مسند احمد اور جامع ترمذی کی روایات میں اس کی تصریح موجود ہے۔\nمسند احمد کی روایت میں ہے کہ ان دونوں (یہودیوں) نے آیت مبارکہ {وَ لَقَدْ اٰتَیْنَا مُوْسٰی تِسْعَ اٰیٰتٍ بَیِّنٰتٍ} (بنی اسرائیل الاسراء ۱۷:۱۰۱) کے بارے میں سوال کیا۔ جامع ترمذی کی روایت میں بھی اس قسم کی تصریح ہے۔ دیکھئے: (الموسوعۃ الحدیثیۃ، مسند الامام احمد بن حنبل: ۳۰/۲۲، حدیث: ۱۸۰۹۶، و جامع الترمذی، تفسیر القرآن، بنی اسرائل، حدیث: ۳۱۴۴) بہرحال اس سے واضح ہوتا ہے کہ ان کا سوال احکام کی بابت نہیں تھا بلکہ ان نو معروف اور اہم معجزات کے متعلق تھا جو موسیٰ صلی اللہ علیہ وسلم کو عطا فرما کر فرعون اور اس کی فاسق و فاجر قوم کی طرف بھیجا گیا تھا اور ان معجزات سے مراد ہیں: عصا، ید بیضا وغیرہ۔ ایک مقام پر قرآن مجید میں اس کی صراحت کچھ یوں فرمائی گئی ہے۔\nارشاد باری ہے: {وَاَلْقِ عَصَاکَ … تِسْعِ اٰیٰتٍ اِِلٰی فِرْعَوْنَ وَقَوْمِہِ اِِنَّہُمْ کَانُوْا قَوْمًا فَاسِقِیْنَ} (النمل ۲۷:۱۰-۱۲)\nاس مقام پر نو میں سے صرف دو معجزے مذکور ہیں، باقی مفصل طور پر سورۂ اعراف میں بیان فرمائے گئے ہیں۔ ارشاد باری ہے: {وَ لَقَدْ اَخَذْنَآ اٰلَ فِرْعَوْنَ بِالسِّنِیْنَ وَ نَقْصٍ مِّنَ الثَّمَرٰتِ … فَاسْتَکْبَرُوْا وَ کَانُوْا قَوْمًا مُّجْرِمِیْنَo} (الاعراف ۷:۱۳۰-۱۳۳) ویسے موسی صلی اللہ علیہ وسلم کو ان نو معجزات کے علاوہ اور بھی کئی معجزے دیے گئے تھے، مثلاً: پتھر پر مارنے سے پانی کے چشمے جاری ہونا، بادلوں کا سایہ کرنا اور من و سلویٰ نازل کرنا وغیرہ جو مصر سے نکلنے کے بعد بنی اسرائیل کو دیے گئے۔ اس تفصیل سے یہ بات بالکل واضح ہو جاتی ہے کہ سوال معجزات ہی کے بارے میں تھا، نہ کہ احکام کے بارے میں۔ دوسری بات یہ بھی ہے کہ موسیٰ صلی اللہ علیہ وسلم کو فرعون کی طرف ہی بھیجا گیا تھا جیسا کہ قرآن مجید میں اس کی واضح طور پر تصریح موجود ہے۔ اگر ان نو واضح آیات سے مراد احکام ہوں تو اس سے فرعون اور اس کی قوم پر کوئی حجت ہی ثابت نہیں ہوتی۔ اصل بات تو فرعون اور اس کی قوم سے موسیٰ صلی اللہ علیہ وسلم کی نبوت و رسالت تسلیم کرانا، اور انہیں ان پر ایمان لانے پر آمادہ کرنا تھا۔ اگر ان سے مراد احکام ہوں تو اس سے اصل مقصد حاصل نہیں ہوتا، یعنی موسیٰ صلی اللہ علیہ وسلم کی نبوت و رسالت کا اثبات اور منکرین کی تردید۔\nاب رہا یہ اشکال کہ سوال تو تھا معجزات کی بابت جبکہ جواب میں احکام ارشاد فرما دیے گئے۔ اس کی کیا وجہ؟ علامہ سندھی رحمہ اللہ نے اس کا جواب یہ دیا ہے کہ یہودیوں کے سوال کا جواب دیتے ہوئے رسول اللہ صلی اللہ علیہ وسلم نے ان مشہور و معروف نو معجزات ہی کا ذکر فرمایا تھا، کسی وجہ سے راوی نے ان کا ذکر نہیں کیا، بلکہ اس کے بعد ان عام احکام کا ذکر کر دیا جو تمام اقوام و ملل کے لیے واجب العمل ہیں۔ تورات میں بھی یہ سب احکام مذکور ہیں۔ امام ابن کثیر رحمہ اللہ نے فرمایا ہے کہ اس حدی کے ایک راوی عبداللہ بن سلمہ کے حافظے میں خرابی ہے جس کی وجہ سے اس پر جواب خلط ملط ہو گیا ہے اور اس نے نو معجزات ان دس کلمات کو بنا دیا ہے جو تورات میں مذکور ہیں لیکن یہ فرعون پر حجت قائم کرنے اور موسیٰ صلی اللہ علیہ وسلم کی نبوت و صداقت کی دلیل نہیں بن سکتے۔ تفصیل کے لیے دیکھئے: (تفسیر ابن کثیر، تفسیر سورۃ بنی اسرائیل، تحت آیۃ: ۱۰۱، و ذخیرۃ العقبی، شرح سنن النسائی، المحاربۃ، حدیث: ۳ث۴۰، و التعلیقات السلفیۃ علی سنن النسائی، المحاربۃ، حدیث: ۴۰۸۳)\nبلاشبہ مذکورہ تفصیل سے یہ بات واضح ہو جاتی ہے کہ ’’نو واضح آیات‘‘ سے مراد: عصا، ید بیضا، قحط، پھلوں کی کمی، طوفان، جوئیں، ٹڈیاں، مینڈک اور خون ہیں۔ ویسے ان کے علاوہ حضرت موسیٰ صلی اللہ علیہ وسلم کو اور معجزے بھی دیے گئے تھے مگر ان کا تعلق بنی اسرائیل سے ہے نہ کہ آلِ فرعون سے۔\nیہ تفصیل تو تھی نو واضح آیات کی بابت۔ اب باقی رہ گئی دسویں چیز، یعنی جو صرف یہودیوں کے ساتھ خاص ہے، دوسرا کوئی بھی اس میں ان کا شریک نہیں، تو اس سے مراد، جیسا کہ قرآن و حدیث سے واضح ہوتا ہے، ہفتے کی تعظیم کرنا اور وہ تعظیم بھی صرف اسی حد تک معلوم ہوتی ہے کہ ہفتے کے دن مچھلی کا شکار نہ کریں اور بس۔ چونکہ باقی نو احکام تمام ملل و اقوام میں مشترک ہیں جبکہ یہ دسواں حکم صرف یہودیوں کے لیے تھا، اس لیے فرمایا گیا کہ ’’اے یہودیو! یہ تمہارے ساتھ خاص ہے، دوسرا کوئی اس میں تمہارا شریک نہیں۔ و اللہ اعلم\n(۳) ’’صاحب اقتدار کے پاس نہ لے جائو‘‘ تساکہ اسے کسی جھوٹے مقدمے میں پھنسا کر ناحق سزا دلوائو یا اسے قتل کرا دو، یا اس پر کسی قسم کی زیادتی اور ظلم کرائو۔ (۴) ’’تجاوز نہ کرو‘‘ یعنی اس دن مچھلی کا شکار نہ کرنے کے متعلق۔ (۵) ’’ہاتھ اورپائوں چومے‘‘ محبت اور پایر میں یا بطور احترام بوسہ دینا ایک فطری امر ہے۔ بچوں اور بزرگوں کو بوسے دیے جاتے ہیں، البتہ پائوں کے بوسے میں سجدے سے مشابہت ہوتی ہے، لہٰذا اس سے اجتناب کیا جائے۔ (۶) ’’نبی ان کی نسل سے آئے‘‘ اس بات سے ان کا مقصد یہ معلوم ہوتا ہے کہ وہ کہنا چاہتے تھے کہ داود صلی اللہ علیہ وسلم نے اس کی بابت دعا کی تھی کہ ان کی نسل ہی سے نبی آئیں، چونکہ آپ نبی ہیں، لہٰذا آپ کی یہ دعا قبول ہو گی، اس لیے ہم اس نبی کے آنے کے منتظر ہیں اور پھر ہم اسی کی اتباع کریں گے۔ لیکن یہودیوں کا یہ صرویح جھوٹ ہے، اس لیے کہ یہ ناممکن ہے کہ سیّدنا داود صلی اللہ علیہ وسلم جیسے جلیل القدر نبی اس قسم کی کوئی دعا کریں جبکہ انہیں یہ بھی علم ہو کہ اللہ تعالیٰ نے ختم نبوت کا تاج حضرت محمد کریم صلی اللہ علیہ وسلم کے سر پر سجانا ہے۔ سیدنا داود صلی اللہ علیہ وسلم پر یہودیوں کا یہ محض افترا ہے کیونکہ وہ تو تورات و زبور میں یہ پڑھ چکے تھے کہ حضرت محمد صلی اللہ علیہ وسلم بطور خاتم النبیین مبعوث ہوں گے، نیز یہ بھی کہ آپ سابقہ ادیان و شرائع کو منسوخ کریں گے۔ اس سب کچھ کے ہوتے ہوئے داود صلی اللہ علیہ وسلم ایسی دعا کیونکر فرما سکتے ہیں۔ علاوہ ازیں یہ دعا اللہ تعالیٰ کی اس اطلاع کے بھی خلاف ہے جو کہ اس نے حضرت محمد صلی اللہ علیہ وسلم کی شان و مرتبے کے متعلق اپنے انبیاء و رسل کو دی ہے۔ و اللہ اعلم۔ مذکور بات یہودیوں میں غلط مشہور کر دی گئی تھی ورنہ یہ بات عقلاً صحیح ہے نہ نقلاً۔ حضرت داود صلی اللہ علیہ وسلم سے پہلے بھی انبیاء مختلف نسلوں سے آئے، بعد میں بھی۔ ممکن نہ تھا کہ ساری دنیا کے لیے انبیاء صرف ایک ہی نسل سے آئیں۔ یہ بات نبی کی بصیرت سے مخفی نہیں رہ سکتی تھی، لہٰذا وہ یہ دعا نہیں کر سکتے تھے۔ (۷) ’’قتل کر دیں گے‘‘ رسول اللہ صلی اللہ علیہ وسلم پر ایمان نہ لانے کی دوسری وجہ ان یہودیوں نے یہ بیان کی کہ آپ پر ایمان لانے کی وجہ سے ہمیں جان کا خطرہ ہے، لہٰذا ہم ایمان نہیں لاتے۔ ان کا یہ بہانہ بھی بلاکل بھونڈا اور غلط تھا کیونکہ اگر وہ ایمان لے آتے تو وہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ رضی اللہ عنہم کے ساتھ رہتے، اس لیے باقی یہودیوں کو یہ جرأت ہی نہ ہو سکتی کہ وہ انہیں اسلام قبول کرنے کی وجہ سے قتل کرتے؟ پھر یہ بات بھی ہے کہ حضرت عبداللہ بن سلام رضی اللہ تعالٰی عنہ بھی تو مومن بن گئے تھے، کیا انہیں قتل کیا گیا تھا جو انہیں کیا جاتا؟ یہ بھی ان کا صریح جھوٹ تھا۔"}],[4079,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کوئی گرہ لگائی پھر اس میں پھونک ماری تو اس نے جادو کیا اور جس نے جادو کیا، اس نے شرک کیا ۱؎ اور جس نے گلے میں کچھ لٹکایا، وہ اسی کے حوالے کر دیا گیا\" ۲؎۔\n§وضاحت\n۱؎: یعنی مشرکین کا عمل اپنایا، یہ شرک اس صورت میں ہے جب وہ اس میں حقیقی تأثیر کا اعتقاد رکھے، یہ بھی کہا جاتا ہے کہ اللہ تعالی پر توکل و اعتماد ترک کر دینے کے سبب وہ شرک خفی کا مرتکب ہو گا۔ اور مؤلف کا استدلال اسی جملہ سے ہے، یعنی جادو کرنے والا شرک کا مرتکب ہوا تو مرتد ہو گیا۔ ۲؎: یعنی اللہ کی نصرت و تائید اسے حاصل نہیں ہو گی۔ تعویذ کے سلسلہ میں راجح قول یہ ہے کہ اس کا ترک کرنا ہر حال میں افضل ہے، بالخصوص جب اس میں شرکیہ کلمات ہوں یا اس کے مفید یا مضر ہونے کا اعتقاد رکھے۔ تو اس سے دور رہنا واجب و فرض ہے، ایسے تعویذ جو قرآنی آیات پر مشتمل ہوں اس کی بابت علماء کا اختلاف ہے، کچھ لوگ اس کے جواز کے قائل ہیں اور ممانعت کی حدیث کو اس صورت پر محمول کرتے ہیں جب اس میں شرکیہ کلمات ہوں، جب کہ دوسرے لوگ جیسے عبداللہ بن مسعود رضی اللہ عنہ، نیز دیگر صحابہ ارشاد نبوی «من تعلق شیأ وکل إلیہ» کے عموم سے استدلال کرتے ہوئے، نیز آیات و احادیث کی بیحرمتی کے سبب حرام قرار دیتے ہیں۔","الألباني: ضعيف",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے گرہ باندھی اور اس میں (پڑھ کر) پھونکا، اس نے جادو کیا۔ اور جس نے دجادو کیا، اس نے شرک کیا اور جس شخص نے کوئی (شرکیہ) چیز گلے میں لٹکائی، اسے اسی کے سپرد کیا جائے گا۔‘‘","f2":"(۱) یہ رویات تعلیق والے جملے کے علاوہ ضعیف ہے لیکن مسئلے کی تفہیم کے لیے کچھ ضروری وضاحت درج ذیل ہے۔ ’’جس نے گرہ باندھی‘‘ جادوگر عموماً گرہیں باندھ کر جادو کیا کرتے ہیں، اس لیے گرہ کا ذکر فرمایا، ورنہ جادو کسی بھی طریقے سے کیا جائے، وہ جادو ہی ہے۔ اگر جن و شیطان سے مدد طلب نہ کی جائے اور ایسے کلمات استعمال نہ کیے جائیں جن کے معنی و مفہوم معلوم نہ ہوں تو وہ جادو نہیں، خواہ کوئی گرہ بھی باندھے۔ (۲) ’’جس نے جادو کیا، اس نے شرک کیا‘‘ کیونکہ جادو میں لازماً غیر اللہ، مثلاً: جن و شیطان سے مدد حاصل کی جاتی ہے۔ انہیں پکارا جاتا ہے۔ اس لیے جادو شرک کو مستلزم ہے۔ (۳) ’’جس نے کوئی چیز لٹکائی‘‘ اس دور میں کاہن کوئی چیز پڑھ پھونک کر دے دیتے تھے کہ اسے گلے میں لٹکا لو، فائدہ ہو گا۔ چونکہ کاہن مشرک تھے اور شرکیہ کلمات ہی پڑھتے تھے، لہٰذا اس سے روک دیا گیا۔ ایسا دم بھی منع ہے اور ایسا تعلیق بھی۔ لیکن کیا قرآن مجید یا دعائوں یا اچھے کلمات کو علاج کے لیے استعمال کرنا جائز ہے یا نہیں؟ یقینا یہ جائز ہے۔ رسول اللہ صلی اللہ علیہ وسلم سے قرآن مجید اور اچھے کلمات کو اپنے اور دوسروں کے لیے بطور علاج استعمال کرنا ثابت ہے۔ لیکن دم کی صورت میں۔ رہا مسئلہ قرآن و حدیث پر مبنی ادعیہ سے تحریر کردہ تعویذ یا تعلیق کا کہ آیا وہ بھی مسنون ہے؟ تو اس کا جواب یہ ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم سے تعویذ لکھنا ثابت نہیں۔ البتہ محققین اہل حدیث و فقہاء کا موقف ہے کہ جس طرح کلام اللہ اور منقول ادعیہ اور غیر شرکیہ کلمات کے ساتھ دم جائز ہے، اسی طرح ان سے تعویذ لکھنا بھی جائز ہے۔ لیکن ان دونوں کے مابین یہ فرق ضرور رہے گا کہ دم کرنا مسنون اور تعویذ لکھنا غیر مسنون ہو گا، اس لیے اس مسئلے میں افراط و تفریط درست نہیں۔ نہ تو مطلقاً قرآنی آیات پر مشتمل تعویذ کو لٹکانا حرام اور شرک کہا جائے اور نہ مجہول المعنی اور مشکوک عبارات یا غیر اللہ کو پکارنے والے کلمات پر مشتمل تعویذ لکھے جائیں، لہٰذا دم کنا اگرچہ عمل مسنون اور قرآنی آیات و ادعیہ مأثورہ کے ساتھ تعویذ لکھنا مشروط طور پر جائز ہے، تاہم احوط اور اقرب الی الحق یہی بات ہے کہ تعویذ لکھنے اور لٹکانے سے احتیاط کی جائے۔ و اللہ اعلم۔"}],[4080,"زید بن ارقم رضی اللہ عنہ کہتے ہیں کہ یہود کے ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم کو جادو کیا۔ اس کی وجہ سے آپ کچھ دنوں تک بیمار رہے، آپ کے پاس جبرائیل علیہ السلام نے آ کر کہا: ایک یہودی نے آپ کو جادو کیا ہے، اس نے آپ کے لیے فلاں کنوئیں میں گرہ باندھ کر ڈال رکھی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے کچھ لوگوں کو بھیجا، انہوں نے اسے نکالا، وہ گرہ آپ کے پاس لائی گئی تو آپ کھڑے ہو گئے، گویا آپ کسی رسی کے بندھن سے کھلے ہوں۔ پھر آپ نے اس کا ذکر اس یہودی سے نہیں کیا اور نہ ہی اس نے آپ کے چہرے پر کبھی اس کا اثر پایا ۱؎۔\n§وضاحت\n۱؎: نبی اکرم صلی اللہ علیہ وسلم نے اس یہودی سے اس کے اس عمل کے سبب تعرض اس لیے نہیں کیا کہ جادو کے سبب شرک و ارتداد کا حکم اس پر لاگو نہیں ہوا، کیونکہ اس کا دین دوسرا تھا، نبی اکرم صلی اللہ علیہ وسلم پر جادو کئے جانے کے بارے میں اس حدیث کے علاوہ عائشہ رضی اللہ عنہا سے صحیحین میں بھی حدیثیں مروی ہیں، اس لیے ان کا انکار حدیث کا انکار ہے، سلف صالحین انبیاء علیہم السلام پر جادو کے اثر کے قائل ہیں اور یہ کہ یہ چیز ان کے مرتبہ و مقام میں کسی نقص اور کمی کا باعث نہیں ہے، یہ ایک قسم کا مرض ہی ہے، اور مرض انبیاء پر طاری ہوا کرتا ہے اس میں کسی کا اختلاف نہیں ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت زید بن ارقم رضی اللہ تعالٰی عنہ سے مروی ہے کہ ایک یہودی شخص نے نبی صلی اللہ علیہ وسلم پر جادو کر دیا۔ آپ اس کی وجہ سے کچھ دین بیمار سے رہے۔ پھر جبریل صلی اللہ علیہ وسلم آپ کے پاس آئے اور فرمایا: ایک یہودی نے آپ پر جادو کر دیا ہے۔ اس نے کچھ گرہیں دے کر فلاں کنویں میں رکھ چھوڑی ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے کچھ صحابہ بھیجے۔ انہوں نے ان گرہوں کو نکالا اور ان کو آپ کے پاس لایا گیا تو رسول اللہ صلی اللہ علیہ وسلم اس طرح اٹھ کھڑے ہوئے جیسے کسی اونٹ کا گھٹنا کھول دیا جائے۔ پھر نہ تو آپ نے اس یہودی سے اس کا ذکر کیا اور نہ اس (یہودی) نے کبھی آپ کے چہرے پر اس کا کچھ اثر پایا۔","f2":"(۱) یہ رویات مختصر ہے۔ صحیح بخاری میں یہ روایت حضرت عائشہ رضی اللہ عنہا سے تفصیل کے ساتھ مروی ہے۔ دیکھئے: (صحیح البخاری، بدء الخلق، باب صفۃ إبلیس و جنودہ، حدیث: ۳۲۶۸) (۲) یہ جادو ایک مشہور یہودی جادوگر لبید بن اعصم ملعون نے یہودیوں کے پر زور اصرار پر تین دینار کے عوض کیا تھا۔ اور یہ ماہ محرم ۷ھ کی بات ہے۔ اس نے آپ کی کنگھی اور آپ کے بال ایک یہودی لڑکے کی معرفت حاصل کیے اور ان کو جادو کے لیے استعمال کیا۔ اس کا مقصد (خاکم بدہن) آپ کو ختم کرنا تھا مگر وہ ناکام رہا۔ (۳) ’’کچھ دن بیمار سے رہے‘‘ اس جادو کا اثر آپ پر غیر مرئی رہا، یعنی عام لوگوں کو محسوس نہ ہوتا تھا لیکن آپ پر اس کے اثرات یوں ظاہر ہوئے کہ آپ بعض امور میں متردد ہونے لگے، آیا میں نے یہ کام کیا ہے یا نہیں وغیرہ؟ حصول وحی یا ابلاغ شریعت میں قطعاً آپ پر یہ جادو اثر انداز نہ ہوا، جیسا کہ مختلف روایات کا جائزہ لینے سے معلوم ہوتا ہے، نیز آپ ذرا پریشان سے رہنے لگے تھے۔ دراصل آپ کی روحانی قوت جادو کی قوتوں کا مقابلہ کرتی تھی۔ اور مقابلہ کی صورت میں مندرجہ بالا اثرات لازمی تھے۔ (۴) ’’کچھ صحابہ بھیجے‘‘ دیگر روایات میں صراحت ہے کہ آپ خود بھی تشریف لے گئے تھے۔ مطلب یہ ہے کہ پہلے اپنے کچھ صحابۂ کرام رضی اللہ عنہم کو بھیجا اور پھر خود آپ بھی تشریف لے گئے۔ اس کنویں سے جادو والی چیزیں نکالی گئیں اور آپ نے معوذتین {قل اعوذ برب الفلق} اور {قل اعوذ برب الناس} پڑھ کر جادو کی گرہوں کو کھولا۔ گیارہ گرہیں تھیں اور ان دونوں سورتوں کی آیات بھی گیارہ ہیں۔ آپ ایک ایک آیت پڑھتے جاتے تھے ار گرہیں کھلتی جا رہی تھیں۔ گرہوں کا کھلنا تھا کہ آپ بالکل تندرست ہو گئے۔ (۵) ’’گھٹنا کھول دیا جائے‘‘ تو وہ بڑی چستی سے کھڑا ہو جاتا اور اِدھر اُدھر بھاگتا دوڑتا ہے۔ (۶) آپ نے اس یہودی یا دوسرے یہودیوں سے اس کا تذکرہ نہ فرمایا بلکہ عام لوگوں میں بھی مشہور نہ کیا گیا تاکہ یہودی یہ سمجھیں کہ ہمارے سخت ترین جادو کا بھی کوئی اثر نہیں ہوا اور وہ ناامید ہو کر آپ کا پیچھا چھوڑ دیں۔ اگر آپ اس بات کو اچھالتے تو ان کو پتا چل جاتا کہ آپ پر کچھ نہ کچھ اثر ہوا ہے، لہٰذا وہ مزید سرگرمی کے ساتھ اس سے بھی بڑا جادو کرنے کی کوشش کرتے۔ (۷) باب کا مقصد یہ ہے کہ آپ نے جادو کرنے والے کو کوئی سزا نہیں دی۔ بعض لوگوں نے کہا ہے: یہ اس لیے کہ وہ مسلمان نہیں تھا بلکہ یہودی تھا۔ اور حدود مسلمانوں کے لیے ہیں۔ لیکن یہ استدلال صحیح نہیں ہے۔ صحیح بات یہ ہے کہ اگر جادوگر کے جادو کا کوئی ثبوت مل جائے اور اس نے کسی کا نقصان کیا ہو تو اسے سزا دی جائے گی، خواہ کافر، یعین یہودی ہو یا کوئی اور۔ (۸) جادو کو کتاب المحاربہ میں ذکر کرنے کی وجہ یہ ہے کہ جادو کفر ہے۔ اگر کوئی مسلمان کرے گا تو وہ مرتد سمجھا جائے گا اور اس پر سزاائے ارتداد نافذ کی جائے گی، یعنی اگر وہ توبہ نہ کرے تو اسے قتل کر دیا جائے گا۔ غیر مسلم اگر جادو کرے اور اس سے کسی کو قتل کر دے تو اسے قصاصاً قتل کر دیا جائے گا۔ اور اگر اس نے کسی کا صرف نقصان کیا ہو تو اس سے وصولی کی جائے گی، نیز اسے قید وغیرہ بھی کیا جائے گا تاکہ معاشرہ اس کے مضر اثرات اور مفاسد سے محفوظ رہ سکے۔ (۹) بعض حضرات نے رسول اللہ صلی اللہ علیہ وسلم پر جادو والی روایت کو رد کیا ہے، حالانکہ یہ روایت صحیحین میں قطعاً ثابت ہے۔ کسی محدث یا فقیہ نے اس کی سند یا متن میں کوئی خرابی نہیں سمجھیں۔ نہ اسے عقل، قرآن یا شان رسول صلی اللہ علیہ وسلم کے خلاف سمجھا ہے۔ بعض متکلمین اور متکبرین حدیث کو یہ خلجان ہوا کہ ’’یہ حدیث شان نبوت کے منافی ہے۔‘‘ حالانکہ طبیعت کا ڈھیلا پڑ جانا وغیرہ کسی لحاظ سے بھی شانِ نبوت کے خلاف نہیں۔ آپ کو بخار چڑھتا تھا، سر درد ہوتا تھا، بڑھاپا طاری ہوا۔ اگر یہ جسمانی عوارض شانِ نبوت کے منافی نہیں تو مذکورہ بالا اثرات کیوں منافی ہوں؟ بعض سمجھتے ہیں کہ اگر آپ پر جادو کا اثر مانا جائے تو گویا آپ پر کافروں کو غلبہ حاصل ہو گیا، حالانکہ کافروں کے ہاتھوں آپ زخمی ہوئے، زہر کھلایا گیا۔ اگر اس سے کفار کو غلبہ حاصل نہیں ہوا تو مندرجہ بالا اثرات سے کیسے غلبہ حاصل ہو گیا؟ غلبہ تو تب ہوتا اگر یہودی اپنے مقصد میں کامیاب ہو جاتے۔ بعض حضرات نے آپ پر جادو کو آیت کریمہ {اِنْ تَتَّبِعُوْنَ اِلَّا رَجُلًا مَّسْحُوْرًا} (بنی اسرائیل ۱۷:۷۴) کے خلاف خیال کیا ہے کیونکہ یہ کافروں کا دعویٰ تھا کہ آپ جادو زدہ ہیں۔ اور کفار کا آپ کو جادو زدہ کہنے سے مطلب یہ تھا کہ آپ جو دین پیش کر رہے ہیں، یہ کسی جادو کا اثر ہے جبکہ اس حدیث میں جس جادو کا ذکر ہے، وہ کسی کافر شخص نے کیا تھا اور اس نے آپ پر صرف جسمانی اثر کیا تھا جو کہ عام آدمی کو محسوس بھی نہیں ہوتا تھا۔ اس سے نہ آپ کے دماغ پر کوئی اثر پڑا اور نہ کوئی تعلیمات متأثر ہوئیں۔ ایسے اثرات تو بیماری کی بنا پر بھی ہو سکتے ہیں۔ اگر بیماری طاری ہو سکتی ہے تو ان اثرات میں کیا حرج ہے؟ بلکہ آپ پر جادو کا اثر ہونے سے یہ ثابت ہو گیا کہ آپ جادوگر نہیں کیونکہ جادوگر پر جادو کا اثر نہیں ہوتا، لہٰذا کافروں کے اس الزام کی تردید ہو گئی کہ آپ جادوگر ہیں۔ صحیح بات یہی ہے کہ جادو کا اثر کسی پر بھی ہو سکتا ہے، البتہ جادو کفر ہے او اگر کوئی خاص مصلحت نہ ہو تو جادو کرنے والا واجب القتل ہے۔ یہی اہل سنت و الجماعت کا مسلک ہے۔ و اللہ اعلم"}],[4081,"مخارق رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک شخص نے آ کر کہا: میرے پاس ایک شخص آتا ہے اور میرا مال چھینتا ہے؟ آپ نے فرمایا:\"تو تم اسے اللہ کی یاد دلاؤ\"، اس نے کہا: اگر وہ اللہ کو یاد نہ کرے، آپ نے فرمایا: \"تو تم اس کے خلاف اپنے اردگرد کے مسلمانوں سے مدد طلب کرو\"۔ اس نے کہا: اگر میرے اردگرد کوئی مسلمان نہ ہو تو؟ آپ نے فرمایا: \"حاکم سے مدد طلب کرو۔ اس نے کہا: اگر حاکم بھی مجھ سے دور ہو؟ آپ نے فرمایا: اپنے مال کے لیے لڑو، یہاں تک کہ اگر تم مارے گئے تو آخرت کے شہداء میں سے ہو گے ۱؎ یا اپنے مال کو بچا لو گے\"۔\n§وضاحت\n۱؎: یعنی: اجر و ثواب کے لحاظ سے ایسا آدمی شہداء میں سے ہو گا لیکن عام مردوں کی طرح اس کو غسل دیا جائے گا اور تجہیز و تدفین کی جائے گی۔","الألباني: حسن صحيح",{"u2":"حضرت قابوس کے والد محترم حضرت مخارق رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک آدمی نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور کہا: ایک شخص میرے پاس آتا ہے اور میرا مال چھیننا چاہتا ہے۔ (تو میں کیا کروں؟) آپ نے فرمایا: ’’اسے اللہ تعالیٰ سے نصیحت کر (اس کی وعید سے ڈرا)۔‘‘ اس نے کہا: اگر وہ نصیحت نہ مانے تو؟ آپ نے فرمایا: ’’اپنے آس پاس کے مسلمانوں سے مدد حاصل کر۔‘‘ اس نے کہا: اگر میرے آس پاس کوئی مسلمان نہ ہوں تو؟ آپ نے فرمایا: ’’حاکم سے مدد طلب کر۔‘‘ اس نے کہا: اگر حاکم بھی مجھ سے دور ہو؟ فرمایا: ’’پھر اپنے مال کی حفاظت کے لیے لڑائی کر حتی کہ تو (مارا جائے اور) آخرت میں شہید بن جائے یا اپنے مال کو بچا لے۔‘‘","f2":"(۱) باب کے ساتھ حدیث کی مناسبت بالکل واضح ہے، وہ اس طرح کہ جس شخص سے اس کا مال چھینا جا رہا ہو، اس کے لیے دفاع کرنا جائز ہے۔ (۲) اس حدیث سے معلوم ہوا کہ دفاع کرنا اگرچہ درست ہے، تاہم یہ کام تدریجاً کرنا زیادہ بہتر ہے، یعنی پہلے ڈاکو وغیرہ کو اللہ تعالیٰ کی پکڑ، اس کے مؤاخذے اور عذاب سے ڈرایا جائے۔ اگر اس کا اثر نہ ہو تو آس پاس کے مسلمانوں سے اس کے خلاف مدد لی جائے۔ یہ بھی ممکن نہ ہو تو حاکم وقت سے مدد طلب کی جائے۔ جب کوئی او چارۂ کار نہ ہو تو لڑنا اور اسے قتل کرنا یا اس کے ہاتھوں شہید ہونا جائز ہے۔ ہاں، اس مقابلے میں اگر ڈاکو اور لٹیرا مارا جائے تو اس کا خون ضائع ہے۔ اپنا دفاع کرنے والے شخص سے نہ تو قصاص لیا جائے گا اور نہ اس پر کسی قسم کی کوئی دیت وغیرہ ہی آئے گی۔ و اللہ اعلم (۳) اس حدیث شریف سے واضح طور پر یہ بھی معلوم ہوا کہ لڑائی کرنا آخری چارۂ کار ہے۔ اس سے پہلے ہر ممکن ذرائع سے لڑائی سے بچا جائے کیونکہ لڑائی نقصان والی چیز ہے، البتہ اگر کوئی چارۂ کار نہ رہے تو اپنا مال بچانے کے لیے لڑائی کی جا سکتی ہے۔ اس دوران میں اگر وہ خود مارا جائے تو شہید ہو گا، یعنی عظیم ثواب کا مستحق ہو گا اور اگر وہ ڈاکو کو مار دے تو اس پر کوئی قصاص، دیت یا تاوان عائد نہ ہو گا جیسا کہ اس سے پہلے بھی یہ بیان ہو چکا ہے۔ لیکن لڑائی سے پہلے یہ دیکھ لے کہ میں اس کا ہم پلہ بھی ہوں؟ یعنی میرے پاس بھی اسلحہ وغیرہ ہے۔ خالی ہاتھ مسلح آدمی سے لڑنا حماقت ہے۔ جان یقینا مال سے زیادہ قیمتی ہے اور قرآن مجید کا حکم ہے کہ ’’اپنے آپ کو خواہ مخواہ ہلاکت میں نہ ڈالو‘‘ گویا لڑائی واجب نہیں، جائز ہے بشرطیکہ وہ ڈاکو کا مقابلہ بھی کر سکتا ہو۔ پھر زندگی، موت اللہ کے سپرد ہے۔ البتہ عزت بچانے کے لیے بے دریغ بھی لڑ پڑے تو اجر کا مستحق ہو گا اور مارے جانے کی صورت میں شہید ہو گا۔ (۴) اس حدیث میں جو شہید کہا گیا ہے اس سے مراد شہید معرکہ نہیں بلکہ آخرت میں ثواب کے اعتبار سے اسے شہید قرار دیا گیا ہے، چنانچہ ایسے شخص کو غسل بھی دیا جائے گا اور اس کی نماز جنازہ بھی پڑھی جائے گی۔"}],[4082,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر عرض کیا: اللہ کے رسول! آپ کا کیا حکم ہے اگر کوئی میرا مال ظلم سے لینے آئے؟ آپ نے فرمایا: \"انہیں اللہ کی قسم دو\"، اس نے کہا: اگر وہ نہ مانیں؟ آپ نے فرمایا: \"انہیں اللہ کی قسم دو\" , اس نے کہا: اگر وہ نہ مانیں؟ آپ نے فرمایا:\"انہیں اللہ کی قسم دو\"، اس نے کہا: پھر بھی وہ نہ مانیں؟ آپ نے فرمایا: \"پھر ان سے لڑو، اگر تم مارے گئے تو جنت میں ہو گے ۱؎ اور اگر تم نے انہیں مار دیا تو وہ جہنم میں ہوں گے\"۔\n§وضاحت\n۱؎: جنت میں جانے کے اسباب میں سے ایک سبب اپنے مال کی حفاظت میں مارا جانا بھی ہے، یہ مطلب نہیں ہے کہ اگر کسی کے پاس نہ عقیدہ صحیح ہو نہ ہی صوم و صلاۃ اور دوسرے احکام شریعت کی پاکی پابندی اور ایسا آدمی اپنے مال کی حفاظت میں مارا جائے تو سیدھے جنت میں چلا جائے گا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور کہا: اے اللہ کے رسول! فرمائیے اگر میرے مال پر حملہ کر دیا جائے (تو کیا کروں؟) آپ نے فرمایا: ’’انہیں اللہ تعالیٰ کا واسطہ دے۔‘‘ اس نے کہا: اگر وہ نہ مانیں تو؟ فرمایا: ’’پھر اللہ کا واسطہ دے۔‘‘ اس نے کہا: اگر وہ پھر بھی نہ مانیں تو؟ فرمایا: ’’پھر اللہ تعالیٰ کا واسطہ دے۔‘‘ اس نے کہا: اگر وہ پھر بھی مصر رہیں تو؟ آپ نے فرمایا: ’’پھر ان سے لڑ۔ اگر تو مارا گیا تو جنت میں جائے گا اور اگر تو نے انہیں مار دیا تو وہ آگ میں جائیں گے۔‘‘\nحضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کی خدمت عالیہ میں حاضر ہوا اور کہا: اللہ کے رسول! فرمائیے اگر میرے مال پر حملہ کر دیا جائے تو؟ آپ نے فرمایا: ’’ان کو اللہ کا واسطہ دے۔‘‘ اس نے کہا: اگر وہ (ڈاکو) نہ مانیں؟ آپ نے فرمایا: ’’پھر اللہ عزوجل کا واسطہ دے۔‘‘ اس نے کہا: اگر وہ پھر بھی نہ مانیں تو؟ آپ نے فرمایا: ’’تو پھر اللہ تعالیٰ کا واسطہ دے۔‘‘ اس نے کہا: اگر وہ پھر بھی نہ مانیں تو؟ آپ نے فرمایا: ’’پھر ان سے لڑ۔ اگر تو قتل ہو گیا تو جنت میں جائے گا اور اگر تو نے ان کو مار دیا تو وہ جہنمی ہوں گے۔‘‘","f2":"’’وہ آگ میں جائے گا‘‘ مقصود یہ ہے کہ اس کے قتل پر کوئی تاوان نہیں دینا پڑے گا بلکہ اس کا خون رائیگاں ہو گا۔\n’’جہنمی ہوں گے‘‘ ڈاکو، محاربین (اللہ اور اس کے رسول سے جنگ لڑنے والے) میں داخل ہیں۔ اس کی سزا قتل بھی ہو سکتی ہے۔ جب وہ لڑائی میں مارا گیا تو سزا پوری ہو گئی۔ آخرت میں بھی جہنمی ہو گا کیونکہ بغیر توبہ، علانیہ شریعت کی مخالفت کرتا ہوا، بے گناہ مسلمانوں کو قتل کرتا ہوا مارا گیا، اس لیے بعض علماء اس کے جنازے کے بھی قائل نہیں کیونکہ اس کا جہنمی ہونا قطعی ہے۔ و اللہ اعلم۔"}],[4083,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر عرض کیا: اللہ کے رسول! اگر کوئی میرا مال چھینے تو آپ کیا کہتے ہیں؟ آپ نے فرمایا: \"انہیں اللہ کی قسم دو\"، اس نے کہا: اگر وہ نہ مانیں؟ آپ نے فرمایا: \"تم انہیں اللہ کی قسم دو\"، اس نے کہا: اگر وہ نہ مانیں تو؟ آپ نے فرمایا:\"تم انہیں اللہ کی قسم دو\"، اس نے کہا: اگر وہ پھر بھی نہ مانیں تو؟ آپ نے فرمایا: \"تو تم ان سے لڑو، اب اگر تم مارے گئے تو جنت میں ہو گے اور اگر تم نے مار دیا تو وہ جہنم میں ہو گا\"۔","الألباني: صحيح"],[4084,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جو اپنا مال بچانے کے لیے لڑا اور مارا گیا تو وہ شہید ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جو اپنے مال کو (ڈاکوؤں وغیرہ سے) بچانے کے لیے لڑائی کرے او مارا جائے تو وہ شہید ہے۔‘‘","f2":"’’شہید ہے‘‘ یعنی شہید کی طرح اس کی بھی مغفرت ہو جائے گی۔ اسے اجر عظیم حاصل ہو گا کیونکہ وہ مظلوم مارا گیا۔ شید بھی مظلوم مارا جاتا ہے۔ البتہ اس پر شہید فی سبیل اللہ والے احکام لاگو نہ ہوں گے، مثلاً: اسے عام میت کی طرح غسل دیا جائے گا اور اس کا جنازہ پڑھا جائے گا۔ میدان جنگ کے علاوہ جن کو شہید کہا گیا ہے، ان کا حکم بھی یہی ہے۔ حضرت عمر رضی اللہ تعالٰی عنہ مظلوم شہید ہوئے تھے مگر انہیں غسل دیا گیا تھا اور ان کا جنازہ بھی پڑھا گیا تھا۔ حضرت علی اور حضرت عثمان رضی اللہ عنہ کا معاملہ بھی یہی ہوا۔"}],[4085,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جو اپنے مال کو بچانے کے لیے لڑے اور مارا جائے وہ شہید ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جو شخص اپنے مال کی حفاظت میں لڑتا ہوا مارا جائے، وہ شہید ہے۔‘‘"}],[4086,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنے مال کی حفاظت کرتے ہوئے مظلوم مارا گیا اس کے لیے جنت ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو اپنے مال کی حفاظت میں مظلوم مارا جائے، اس کے لیے جنت ہے۔‘‘","f2":"دیکھئے، حدیث: ۴۰۸۹۔"}],[4087,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنے مال کی حفاظت کی میں مارا گیا وہ شہید ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے مال کی حفاظت کرتا ہوا مارا جائے، وہ شہید ہے۔‘‘"}],[4088,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ناحق جس کا مال چھینا جائے اور وہ لڑے پھر مارا جائے وہ شہید ہے\"۔ (امام نسائی کہتے ہیں:) یہ حدیث غلط ہے، صحیح سعیر بن خمس کی حدیث ہے ۱؎۔\n§وضاحت\n۱؎: بعض نسخوں کے مطابق خطا سعیر بن خمس کی حدیث میں ہے نہ کہ اس حدیث میں، اور خطا سے مراد سند میں خطا ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ بیان فرماتے ہیں کہ نبیٔ اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص کا مال ناحق چھیننے کی کوشش کی جائے اور وہ لڑتا ہوا مارا جائے تو وہ شہید ہو گا۔‘‘\n(امام نسائی رحمہ اللہ نے فرمایا:) یہ (روایت) غلط ہے۔ سعیر بن خمس کی (اس سے پہلی) روایت درست ہے۔","f2":"امام نسائی رحمہ اللہ کا مقصد ہے کہ یہ روایت بواسطہ عبداللہ بن حسن، عکرمہ سے صحیح ہے جیسا کہ سعیر بن خمس نے بیان کیا ہے، نہ کہ بواسطۂ عبداللہ بن حسن عن ابراہیم بن محمد جیسا کہ سفیان ثوری نے بیان کیا ہے۔ لیکن امام صاحب رحمہ اللہ کا سفیان کی حدیث کو خطا کہنا محل نظر ہے کیونکہ ثوری ثقہ اور حافظ ہیں اور پھر وہ منفرد بھی نہیں بلکہ عبدالعزیز بن مطلب نے ان کی متابعت کی ہے۔ اس روایت کو امام ترمذی رحمہ اللہ نے بیان کیا ہے اور حسن کہا ہے۔ گویا اس روایت میں عبداللہ بن حسن کے دو استاد ہیں: عکرمہ اور ابراہیم بن محمد۔ اور روایت دونوں طریق سے صحیح ہے۔ تفصیل کے لیے دیکھئے: (ذخیرۃ العقبی، شرح سنن النسائی: ۳۲/۷۳)"}],[4089,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنے مال کی حفاظت کرتے ہوئے مارا گیا وہ شہید ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے مال کی حفاظت کرتا ہوا مارا جائے، وہ شہید ہے۔‘‘"}],[4090,"سعید بن زید رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنے مال کی حفاظت کرتے ہوئے مارا گیا تو وہ شہید ہے\"۔","الألباني: صحيح",{"u2":"حضرت سعید بن زید رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے مال کی حفات کرتا ہوا مارا جائے، وہ شہید ہے۔‘‘ یہ (حدیث) مختصر ہے۔"}],[4091,"سعید بن زید رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنے مال کی حفاظت کرتے ہوئے لڑائی کی (اور مارا گیا) وہ شہید ہے\"۔","الألباني: صحيح",{"u2":"حضرت سعید بن زید رضی اللہ تعالٰی عنہ سے منقول ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو آدمی اپنے مال کی حفاظت کرتا ہوا لڑائی لڑے (اور مارا جائے) وہ شہید ہے۔‘‘"}],[4092,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنے مال کی حفاظت کرتے ہوئے مارا جائے وہ شہید ہے\"۔","الألباني: صحيح لغيره",{"u2":"حضرت بریدہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے مال کو (ڈاکوئوں سے) بچاتے ہوئے مارا جائے، وہ شہید ہے۔‘‘"}],[4093,"ابو جعفر الباقر کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص ظلم سے بچنے میں مارا جائے تو وہ شہید ہے\"۔ ابوعبدالرحمٰن کہتے ہیں: مؤمل کی حدیث غلط ہے، صحیح عبدالرحمٰن کی حدیث ہے ۱؎۔\n§وضاحت\n۱؎: مومل کی حدیث سے مطلب حدیث رقم ۴۰۹۷ ہے جو مرفوع ہے، اور عبدالرحمٰن کی حدیث سے مطلب یہ مرسل روایت ہے، یعنی اس روایت کا مرسل ہونا ہی صحیح ہے، بہرحال سعید بن زید رضی اللہ عنہ کی روایت سے یہ حدیث صحیح ہے۔","الألباني: صحيح",{"u2":"حضرت ابو جعفر سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص کسی ظالم کے مقابلے میں مارا جائے، وہ شہید ہے۔‘‘\nامام ابو عبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ مؤمل کی (سابقہ) حدیث غلط ہے جبکہ عبدالرحمن کی (یہی) حدیث درست ہے۔","f2":"مؤمل متکلم فیہ راوی ہے جبکہ عبدالرحمن بن مہدی ثقہ اور متقن ہیں۔ عبدالرحمن نے اس روایت کو مرسل بیان کیا ہے اور مؤمل نے اسے موصولاً بیان کیا ہے۔ یقینا مؤمل کی روایت کے مقابلے میں عبدالرحمن کی مرسل روایت محفوظ ٹھہرتی ہے۔ گویا اس روایت کا مؤمل کی سند سے متصل ہونا درست نہیں۔ ویسے (ابو جعفر کی) یہ روایت (۴۰۹۸) صحیح ہے اور موصولاً بھی ثابت ہے اور آگے (۴۱۰۱میں) آ رہی ہے۔"}],[4094,"سعید بن زید رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنے مال کی حفاظت کے لیے لڑے اور مارا جائے تو وہ شہید ہے، جو اپنے خون کی حفاظت کے لیے لڑے (اور مارا جائے) تو وہ شہید ہے اور جو اپنے گھر والوں کی حفاظت کی خاطر لڑے (اور مارا جائے) تو وہ شہید ہے\"۔","الألباني: صحيح",{"u2":"حضرت سعید بن زید رضی اللہ تعالٰی عنہ سے منقول ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جو اپنے مال کی حفاظت کرتے ہوئے مارا جائے، وہ شہید ہے اور جو اپنی جان بچاتے ہوئے مارا جائے، وہ بھی شہید ہے او جو شخص اپنے گھر والوں کے دفاع میں مارا جائے، وہ بھی شہید ہے۔‘‘","f2":"مقصد یہ ہے کہ جو ظلماً مارا جائے، خواہ اپنی جان کی حفاظت کرتے ہوئے یا مال کی حفاظت کرتے ہوئے یا عزت کی حفاظت کرتے ہوئے یا اہل و عیال کی حفات کرتے ہوئے یا دین کی حفاظت کرتے ہوئے، وہ شہید ہے، یعنی اس کی مغفرت ہو جائے گی۔ وہ جنتی ہو گا۔ و اللہ اعلم۔"}],[4095,"سعید بن زید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اپنے مال کی حفاظت میں مارا جائے وہ شہید ہے، جو شخص اپنے گھر والوں کی حفاظت میں مارا جائے وہ شہید ہے، جو اپنے دین کی حفاظت میں مارا جائے تو وہ شہید ہے اور جو اپنے خون کی حفاظت میں مارا جائے وہ شہید ہے\"۔","الألباني: صحيح",{"u2":"حضرت سعید بن زید رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے مال کو (لٹیروں سے) بچاتے ہوئے مارا جائے، وہ شہید ہے۔ اور جو شخص اپنے گھر والوں کا دفاع کرتے ہوئے مارا جائے، وہ شہید ہے۔ اور جو شخص اپنے دین کی خاطر مارا جائے، وہ بھی شہید ہے۔ اور جو شخص اپنی جان بچاتے ہوئے مارا جائے، وہ بھی شہید ہے۔‘‘","f2":"’’دین کی خاطر‘‘ یعنی کسی نے اسے دھمکی دی کہ اپنا دین (اسلام) چھوڑ دے ورنہ تجھے قتل کر دوں گا۔ اس نے دین نہ چھوڑا، قتل ہونا قبول کر لیا، تو وہ شہید ہے۔ اس کی شہادت میں کیا شک ہے جبکہ اسے شرعاً اجازت تھی کہ وہ ایسی حالت میں کلمۂ کفر کہہ سکتا ہے بشرطیکہ دلی طور پر ایمان اسلام پر پکا رہے لیکن اس نے رخصت کی بجائے عزیمت پر عمل کیا۔ رضی اللہ عنہ و أرضاہ۔"}],[4096,"ابو جعفر الباقر کہتے ہیں کہ میں سوید بن مقرن کے پاس بیٹھا ہوا تھا تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص ظلم سے بچنے میں مارا جائے وہ شہید ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو جعفر رحمہ اللہ بیان کرتے ہیں کہ میں حضرت سوید بن مقرن رضی اللہ تعالٰی عنہ کے پاس بیٹھا تھا۔ انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے حق کی خاطر (لڑتا ہوا) مارا جائے، وہ شہید ہے۔‘‘","f2":"کوئی ظالم کسی مظلوم کا حق چھیننا چاہتا ہے اور مال حوالے نہ کرنے کی صورت میں اسے قتل کی دھمکی دیتا ہے۔ مظلوم کو اجازت ہے کہ اس سے لڑ کر اپنا حق بچا لے اور اگر اس کوشش میں وہ مارا جائے تو وہ عنداللہ شہید ہو گا اور اگر ظالم مارا جائے تو اس کا خون ضائع ہے۔"}],[4097,"عبداللہ بن زبیر رضی اللہ عنہما روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنی تلوار باہر نکال لے پھر اسے چلانا شروع کر دے تو اس کا خون رائیگاں اور بیکار ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی: ناحق مسلمانوں کو مارنے لگے تو اس کے قتل میں نہ دیت ہے نہ قصاص۔","الألباني: شاذ",{"u2":"حضرت ابن زبیر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص توار میان سے نکال کر لوگوں پر چلانی شروع کر دے، اس کا خون ضائع ہے۔‘‘ (اس کا قتل جائز ہے۔ اس کی کوئی دیت ہو گی نہ قصاص۔)","f2":"کسی بھی مذہبی، سیاسی یا معاشرتی اختلافی کی وجہ سے کسی شخص کو یہ حق حاصل نہیں کہ وہ مسلح کارروائی کرے۔ اسی طرح کوئی شخص کسی گناہ گار کو بھی قتل نہیں کر سکتا، خواہ حالت گناہ میں پکڑ لے کیونکہ حدود کا نفاذ حکومت کا اختیار ہے، افراد کا نہیں۔ اگر کوئی از خود ایسی کارروائی کرے گا، اسے قتل کر دیا جائے گا، خواہ وہ سچا ہی ہو۔ اس کے بعد اس کا معاملہ اللہ تعالیٰ کے سپرد ہے۔ آج کل مذہبی اختلافات کی بنا پر آپس میں قتل و غارت کرنے والوں کو یہ حدیث مدنظر رکھنی چاہیے، خواہ وہ کتنا ہی خوش نما نعرہ کیوں نہ لگاتے ہوں، مثلاً: عصمت صحابہ و ازواج مطہرات یا اہل بیت وغیرہ۔ و اللہ اعلم۔"}],[4098,"عبدالرزاق بھی اس سند سے اسی جیسی روایت کرتے ہیں، لیکن وہ اسے مرفوع نہیں کرتے (یعنی ابن زبیر کا قول بیان کرتے ہیں)۔","الألباني: صحيح موقوف",{"u2":"عبدالرزاق سے بھی یہ حدیث انہی الفاظ سے مروی ہے مگر اس نے اسے مرفوع بیان نہیں کیا۔"}],[4099,"عبداللہ بن زبیر رضی اللہ عنہما کہتے ہیں کہ جس نے ہتھیار اٹھایا اور اسے لوگوں پر چلایا تو اس کا خون رائیگاں اور بیکار ہے۔","الألباني: صحيح موقوف",{"u2":"حضرت ابن زبیر رضی اللہ عنہ بیان کرتے ہیں کہ جس نے (لوگوں پر) اسلحہ سونتا، پھر اسے چلانا شروع کر دیا تو اس کا خون ضائع ہے۔ (کوئی معاوضہ ہو گا نہ اس کا قصاص ہی لیا جائے گا۔)","f2":"’’چلانا شروع کر دیا‘‘ خواہ کوئی قتل ہو یا نہ مگر اسلحہ چلانے والے کی شرعی سزا قتل ہے کیونکہ وہ لوگوں کے قتل کے درپے ہے۔ واللہ اعلم۔"}],[4100,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ہم پر ہتھیار اٹھایا تو وہ ہم میں سے نہیں ہے\" ۱؎۔\n§وضاحت\n۱؎: یہاں بھی \" ہتھیار اٹھانے \" سے مراد \" ناحق ہتھیار \" اٹھانا ہے، مسلمانوں کی ناحق خونریزی پر یہ شدید وعید سنائی گئی ہے کہ ایسے عمل کے مرتکب کو اگر قتل کر دیا جائے تو اس کے خون کا نہ تو قصاص ہے اور نہ ہی دیت۔ اور یہ کہ ایسا آدمی امت محمدیہ کے زمرہ سے خارج ہے۔ «فاعتبروا یا أولی الأبصار» :(عبرت حاصل کرنی چاہیئے )۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ہم (مسلمانوں) پر ہتھیار اٹھائے، وہ ہم میں سے نہیں۔‘‘","f2":"’’وہ ہم میں سے نہیں‘‘ یعنی ظاہراً کیونکہ مسلمانوں کو قتل کرنا کافروں کا کام ہے، نیز اگر وہ علانیہ مسلمانوں کو قتل کرتا پھرتا ہے جیسے ڈاکو یا باغی تو وہ محاربین میں داخل ہے۔ البتہ اگر جذبات میں آ کر نادانستہ اس سے اسلحہ کے ساتھ قتل صادر ہو جائے تو وہ کافر نہ بنے گا بلکہ اس پر حالات کے مطابق قصاص یا دیت کا حکم لاگو ہو گا۔ سزا ملنے کے بعد معافی ممکن ہے کیونکہ وہ مسلمان ہے۔ و اللہ اعلم۔"}],[4101,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ جس وقت علی رضی اللہ عنہ یمن میں تھے انہوں نے نبی اکرم صلی اللہ علیہ وسلم کے پاس مٹی لگا ہوا سونے کا ایک ٹکڑا بھیجا۔ تو آپ صلی اللہ علیہ وسلم نے اسے اقرع بن حابس حنظلی (جو بنی مجاشع کے ایک شخص تھے)، عیینہ بن بدر فزاری، علقمہ بن علاثہ عامری (جو بنی کلاب کے ایک شخص تھے)، زید الخیل طائی (جو بنی نبہان کے ایک شخص تھے) کے درمیان تقسیم کیا، ابو سعید خدری کہتے ہیں: اس پر قریش اور انصار غصہ ہوئے اور بولے: آپ اہل نجد کے سرداروں کو دیتے ہیں اور ہمیں چھوڑ دیتے ہیں۔ آپ نے فرمایا: \"میں تو صرف ان کی تالیف قلب کر رہا ہوں\"، اتنے میں ایک شخص آیا، اس کی آنکھیں بیٹھی ہوئی تھیں، گال پھولے ہوئے تھے، داڑھی گھنی تھی اور سر منڈا ہوا تھا۔ وہ بولا: محمد! اللہ سے ڈرو، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب میں ہی نافرمانی کرنے لگا تو اللہ کی اطاعت کون کرے گا۔ مجھے اللہ تعالی زمین والوں پر امین بنا رہا ہے اور تم میرا اعتبار نہیں کرتے۔ اتنے میں لوگوں میں سے ایک شخص نے اس کے قتل کی اجازت طلب کی، آپ نے اسے منع فرما دیا۔ جب وہ لوٹ گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کے خاندان میں کچھ ایسے لوگ ہوں گے جو قرآن پڑھیں گے مگر وہ ان کے حلق کے نیچے نہ اترے گا، وہ دین سے اسی طرح نکل جائیں گے جیسے تیر شکار سے نکل جاتا ہے، وہ اہل اسلام کو قتل کریں گے اور بت پرستوں کو چھوڑ دیں گے، اگر میں انہیں پا جاؤں تو انہیں عاد کے لوگوں کی طرح قتل کروں\" ۱؎۔\n§وضاحت\n۱؎: کتاب تحریم الدم یا کتاب المحاربۃ :(جنگ ) سے مطابقت اسی جملے سے ہے، یعنی: خارجیوں کا خون بہانا جائز ہے، اس لیے علی رضی اللہ عنہ نے ان سے جنگ کی تھی۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالٰی عنہ سے روایت ہے کہ حضرت علی رضی اللہ تعالٰی عنہ نے، جب وہ یمن کے حاکم تھے، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں کچھ سونا بھیجا جو ابھی مٹی سے الگ نہیں کیا گیا تھا۔ آپ نے وہ سارا سونا تقسیم فرما دیا، اقرع بن حابس حنظلی کو، جو کہ بنو مجاشع سے تھے، عیینہ بن بدر فزاری کو، علقبمہ بن علاثہ عامری کو، جو کہ بنو کلاب میں سے تھا اور زید خیل طائی کو جو کہ بنو نبہان میں سے تھا۔ اس بات سے قریش اور انصار کو غصہ آ گیا۔ وہ کہنے لگے: آپ نجدی سرداروں کو دے رہے ہیں اور ہمیں چھوڑ رہے ہیں۔ آپ نے فرمایا: ’’میں ان کی تالیف قلب کرتا ہوں۔‘‘ اتنے میں ایک آدمی آیا جس کی آنکھیں اندر کو دھنسی ہوئی، رخسار ابھرے ہوئے، ڈاڑھی گھنی اور سر منڈا ہوا تھا، وہ کہنے لگا: اے محمد! اللہ سے ڈر۔ آپ نے فرمایا: ’’اگر میں ہی اللہ کا نافرمان ہوں تو کون اللہ کی اطاعت کرے گا؟ اس (اللہ تعالیٰ) نے تو مجھے زمین والوں پر امین بنایا ہے (تبھی تو مجھیح نبوت سے سرفراز فرمایا ہے) لیکن تم مجھے امانت دار نہیں سمجھتے؟‘‘ چنانچہ حاضرین میں سے ایک شخص نے اس کے قتل کی اجازت طلب کی لیکن آپ نے اجازت نہ دی۔ جب وہ آدمی چلا گیا تو آپ نے فرمایا: اس کی نسل سے کچھ ایسے لوگ نمودار ہوں گے جو قرآن پڑھیں گے مگر وہ ان کے حلق سے نیچے نہیں جائے گا۔ دین سے اس طرح صاف نکل جائیں گے جس طرح تیر اپنے شکار سے صاف نکل جاتا ہے۔ وہ مسلمانوں کو قتل کریں گے۔ بت پرستوں کو کچھ نہیں کہیں گے۔ (اللہ کی قسم!) اگر میں نے انہیں پایا تو انہیں قوم عاد کی طرح قتل کر دوں گا۔‘‘","f2":"(۱) باب کے ساتھ حدیث کی مناسبت اس طرح بنتی ہے کہ مسلمانوں کے خلاف تلوار اٹھانے والا واجب القتل ہے۔ (۲) اسلام کی طرف مائل کرنے، نیز اسلام کا گرویدہ کرنے کے لیے مؤلفۃ القلوب لوگوں کو زکاۃ دی جا سکتی ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کی تالیف قلب کے لیے انہی چار افراد میں سارا سونا تقسیم فرما دیا۔ چونکہ وہ چاروں افراد بڑے بڑے قبیلوں کے سردار تھے۔ نو مسلم تھے۔ ابھی یہ رسول اللہ صلی اللہ علیہ وسلم کی تربیت سے فیض یاب نہیں ہوئے تھے۔ ایمان دل میں جاگزیں نہ ہوا تھا۔ اس قسم کے لوگوں کو مال مل جائے تو بڑے خوش ہوتے ہیں او وفادار بن جاتے ہیں۔ مال نہ ملے تو فتنہ کھڑا کر دیتے ہیں۔ ارتداد کا بھی خطرہ ہوتا ہے۔ (جیسے رسول اللہ صلی اللہ علیہ وسلم کی وفات کے بعد ہوا۔) اس لیے آپ نے انہیں خوب عطیات دیے۔ حنین کی غنیمت سے بھی انہیں سو سو اونٹ دیے اور دیگر عطیات سے بھی نوازا۔ آپ کا مقصد ان کی تالیف قلب تھا تاکہ ان کے دلوں میں ایمان جاگیزیں ہو جائے اور وہ پکے مومن بن جائیں۔ قریش و انصار چونکہ ایمان میں پختہ تھے، ان سے اس قسم کا کوئی خطرہ نہ تھا، اس لیے آپ نے انہیں کچھ نہ دیا۔ (۳) ’’غصہ آ گیا‘‘ یہ غصہ بھی بعض نوجوانوں کو آیا تھا ورنہ سابقون اولون مہاجرین و انصار سے تو اس کی توقع بھی نہیں کی جا سکتی۔ (۴) اس حدیث شریف سے معلوم ہوتا ہے کہ محض قرآن مجید کی تلاوت کسی شخص کے مومن صادق ہونے کی دلیل نہیں بن سکتی جبکہ وہ قرآن مقدس کے عملی تقاضے پورے نہ کرے۔ (۵) رسول اللہ صلی اللہ علیہ وسلم انتہائی متحمل مزاج او عفو سے کام لینے والے عظیم انسان تھے۔ بڑے بڑے بے ادب اور گستاخ لوگوں سے بھی صرف نظر فرما جایا کرتے تھے، بالخصوص اپنی ذات کی خاطر کسی سے بھی انتقام نہ لیتے تھے۔ (۶) اس حدیث سے خوارج کے ساتھ قتال کرنے کی مشرعیت بھی ثابت ہوتی ہے، خواہ انہیں مرتد سمجھ کر ان سے قتال کیا جائے یا امام عادل کا باغی سمجھ کر کیا جائے۔ (۷) اس حدیث سے خارجیوں کی کچھ نشانیاں بھی معلوم ہوتی ہیں، مثلاً: ظاہراً وہ عام مسلمانوں کی نسبت بہت زیادہ عبادت گزار ہوتے ہیں، نیز یہ بھی کہ وہ دوسرے لوگوں کے مقابلے میں مسلمانوں سے بہت زیادہ عداوت بھی رکھتے ہیں۔ (۸) اس حدیث سے یہ بھی معلوم ہوتا ہے کہ بعض لوگ بغیر قصد و ارادہ کے دین اسلام سے نکل جاتے ہیں، حالانکہ وہ دین اسلام پر کسی بھی دوسرے دین و مذہب کو قطعاً ترجیح نہیں دے رہے ہوتے۔ (۹) رسول اللہ صلی اللہ علیہ وسلم کی تقسیم پر اعتراض کرنے والے شخص کا نام حدیث میں ذوالخویصرہ مذکور ہے۔ دیکھئے: (صحیح البخاری، المناقب، حدیث: ۳۶۱۰) بلاشبہ معترض کا یہ اعتراض غلط اور ایمان کے تقاضوں کے منافی ہے بلکہ اس سے نفاق مترشح ہوتا ہے۔ (۱۰) اس معترض کو قتل کرنے کی اجازت طلب کرنے والے حضرات جناب خالد بن ولید اور حضرت عمر بن خطاب رضی اللہ عنہ ہیں۔ صحیح بخاری میں ان دونوں کے ناموں کی تصریح ہے۔ دیکھئے: (حدیث: ۳۳۴۴، ۳۶۰۱) (۱۱) اس حدیث پاک سے عمر بن خطاب اور خالد بن ولید رضی اللہ عنہ کی عظیم فضیلت و منقبت بھی معلوم ہوتی ہے کہ وہ دونوں رسول اللہ صلی اللہ علیہ وسلم کے گستاخ کو قتل کرنے پر تیار ہو گئے۔ (۱۲) ’’حلق سے نیچے نہ جائے گا‘‘ یعنی قرآن کی سمجھ حاصل نہ ہو گی۔ صرف پڑھنے سے علم و حکمت کا حصول نہیں ہو جاتا بلکہ اس کے ساتھ ساتھ اللہ تعالیٰ کی توفیق کا ہونا بھی ضروری ہے۔ (۱۳) ’’صاف نکل جاتا ہے‘‘ جس طرح تیز تیر اپنے شکار سے بالکل صاف نکل جاتا ہے۔ خون یا گوبر کی آلودگی سے صاف رہتا ہے۔ اسی طرح یہ لوگ قرآن مجید سے کورے نکل جائیں گے اور انہیں دین کا فہم حاصل نہیں ہو گا۔ یہ مطلب نہیں کہ وہ کافر ہوں گے کیونکہ خوارج بہر صورت مسلمانوں کا ایک فرقہ تھے جو دین کے مبادی کا اقرار کرتے تھے مگر صحابۂ کرام رضی اللہ عنہم کا راستہ چھوڑ دینے کی وجہ سے گمراہ ہو گئے۔ (۱۴) یہ لوگ حضرت علی رضی اللہ تعالٰی عنہ کے دور خلافت میں ظاہر ہوئے تھے۔ پہلے حضرت علی رضی اللہ تعالٰی عنہ کے حامی تھے، پھر بغاوت کر دی۔ بغاوت کی وجہ سے انہیں خارجی یا خوارج کہا گیا ہے۔ (عربی میں خروج بغاوت کو کہہ دیتے ہیں۔) یہ لوگ حد سے زیادہ نیک تھے لیکن کم عقلی کی وجہ سے اپنے علاوہ کسی کو مسلمان نہ سمجھتے تھے۔ انتہاء پسند تھے۔ ہر گناہ کو کفر کہتے تھے اور ہر گناہ گار کو کافر۔ نتیجہ یہ نکلا کہ مسلمانوں کو کافر کہہ کر اکثر قتل کرتے تھے اور کافروں کو معذور سمجھ کر چھوڑ دیتے تھے۔ انتہائی پسندی کا نتیجہ ہمیشہ ایسا ہی نکلتا ہے، اس لیے انتہاء پسندی، تشدد اور تکلف کی اسلام میں مذمت کی گئی ہے۔ (۱۵) ’’قتل کر دوں گا‘‘ کیونکہ وہ امت مسلمہ کے لیے ناسور کی حیثیت رکھتے تھے۔ صحابہ کرام رضی اللہ عنہم تک کو کافر کہنے اور قتل کرنے سے دریغ نہیں کرتے تھے۔ ان کا قتل ان کے شر سے بچنے کے لیے تھا نہ اس لیے کہ وہ کافر تھے۔ حضرت علی اور حضرت ابن عباس رضی اللہ عنہ کے سمجھانے کے باوجود باز نہ آئے۔ آخر حضرت علی رضی اللہ تعالٰی عنہ نے انہیں لڑکر شکست دی۔ ہزاروں مارے گئے مگر عرصۂ دراز تک امت مسلمہ کے لیے فتنہ بنے رہے۔ معلوم ہوا، ہدایت کا معیار صرف نیکی نہیں بلکہ صحابہ کرام رضی اللہ عنہم اور خلفاء راشدین کی پیروی بھی ہے جو کہ اصل دین اسلام ہے۔ اسلام کی وہی تعبیر صحیح ہے جو صحابۂ کرام رضی اللہ عنہم نے کی۔ اگر ان کا اتفاق ہو تو اس کی پیروی لازم ہے اور اگر ان میں اختلاف ہو تو پھر بھی صحابہ کرام رضی اللہ عنہم کی اطاعت سے باہر نہیں جانا چاہیے۔ (۱۶) خوارج صرف اس دور کے ساتھ خاص نہیں تھے بلکہ بعد میں بھی اس ذہنیت کے لوگ پیدا ہوتے رہے ہیں اور ہو رہے ہیں اور ہوتے رہیں گے۔ (۱۷) جو شخص بھی انتہا پسند ہو، بات بات پر کفر کے فتوے لگاتا ہو، مسلمانوں کو کافر کہہ کر ان کے قتل کا قائل ہو، صحابۂ کرام رضی اللہ عنہم کو گمراہ یا بدعتی کہتا ہو اور اپنے آپ کو صحابہ سے بڑھ کر دین کا محافظ سمجھتا ہو، وہ خارجی ہے چاہے کسی فرقے سے تعلق رکھتا ہو۔ و اللہ اعلم۔ (۱۸) خارجیوں کی بابت اہل علم کے مابین شدید اختلاف ہے۔ بعض اہلِ علم انہیں کافر قرار دیتے ہیں جبکہ اکثر اہلِ علم انہیں کافر نہیں بلکہ فاسق و فاجر اور بدعتی قرار دیتے ہیں۔ کافر قرار دینے والوں کی دلیل مذکورہ حدیث اور اس جیسی دیگر احادیث ہیں کہ جن میں ان کے متعلق اس قسم کے الفاظ بیان فرمائے گئے ہیں، مثلاً: یَمْرُقُوْنَ مِنَ الدِّیْنِ، فَاقْتُلُوْہُمْ، فَاِنَّ قَتْلَہُمْ اَجْرٌ لِّمَنْ قَتَلَہُمْ یَوْمَ الْقِیٰمَۃِ اور ہُمْ شَرُّ الْخَلْقِ وغیرہ۔ لیکن خارجیوں کو بدعتی اور فاسق و فاجر قرار دینے والوں کا کہنا ہے کہ خارجی لوگ شہادَتَیْن (کلمۂ شہادت) کا اقرار کرتے ہیں اور ارکانِ اسلام پر بھی ان کی مواظبت اور ہمیشگی ہے، لہٰذا وہ کافر نہیں۔ چونکہ اہل اسلام کے متعلق ان کا نقطۂ نظر درست نہیں، اس لیے وہ مبتدع اور فاسق و فاجر ہیں۔ شاید احادیث میں ان کی بابت مذکورہ بالا قسم کے شدید الفاظ بول کر انہیں سخت تنبیہ کرنا اور راہِ مستقیم پر لانا مقصود ہو۔ و اللہ اعلم"}],[4102,"علی رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"آخری زمانے میں کچھ لوگ ہوں گے جو کم سن اور کم عقل ہوں گے، بات چیت میں وہ لوگوں میں سب سے اچھے ہوں گے، لیکن ان کا ایمان ان کے حلق سے نیچے نہ اترے گا، وہ دین سے اسی طرح نکل جائیں گے، جس طرح تیر شکار سے نکل جاتا ہے، لہٰذا جب تم ان کو پاؤ تو انہیں قتل کرو کیونکہ ان کے قتل کرنے والے کو قیامت کے دن اجر ملے گا\"۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: ’’آخر زمانے میں کچھ نو عمر، کم عقل لوگ ظاہر ہوں گے۔ وہ مخلوق میں سے بہترین شخص (حضرت محمد مصطفی رضی اللہ عنہم) کی باتیں کریں گے۔ ان کا ایمان ان کے حلق سے تجاوز نہیں کرے گا۔ دین سے اس طرح نکل جائیں گے جس طرح شکار (کے جسم) سے تیر (صاف) نکل جاتا ہے۔ جب تمہاری ان سے ملاقات ہو تو انہیں (بے دریغ) قتل کرو کیونکہ ان کا قتل قتل کرنے والے کے لیے قیامت کے اجر و ثواب کا ذریعہ ہو گا۔‘‘","f2":"(۱) باب کے ساتھ حدیث کی مناسبت بالکل واضح ہے کہ اہل اسلام کے خلاف تلوار اٹھانے والا واجب القتل ہے (الا یہ کہ وہ تائب ہو جائے)۔ (۲) اس حدیث سے ایسے لوگوں کو زجر و توبیخ کرنا بھی ثابت ہوتا ہے جو قرآنِ مقدس کی ان تمام آیات اور ان احادیث رسول کے، صرف ظاہری معنی مراد لیتے ہیں، نیز یہ بھی کہ ان کے ظاہری معنی اجماعِ اسلام کے خلاف ہوتے ہیں۔ (۳) دین میں غلو کرنے والوں کو تنبیہ کرنا بھی اس حدیث سے معلوم ہوتا ہے۔ اسی طرح اس انداز کی عبادات سے بچنے کا درس بھی ملتا ہے جس کی اجازت شریعت نے نہیں دی اور جس میں شدت اور سختی کا پہلو نمایاں اور غالب ہو، حالانکہ شارع صلی اللہ علیہ وسلم کی لائی ہوئی شریعت انتہائی آسان، سہل اور ہر ایک مرد و زن کے لیے قابل عمل ہے۔ (۴) اس حدیث سے یہ بھی معلوم ہوتا ہے کہ مسلمانوں کے مقابلے میں کافروں پر سختی کرنا اور ان کے ساتھ عداوت و نفرت رکھنا مستحب بلکہ ضروری ہے۔ (۵) یہ حدیث رسول اللہ صلی اللہ علیہ وسلم کی نبوت کی عظیم دلیل بھی ہے کہ آپ نے ایسے لوگوں کی اطلاع (بذریعۂ وحی) ان کے ظہور سے بھی پہلے دے دی تھی۔ (۶) خارجیوں میں پائی جانے والی خرابیاں اگر آج بھی لوگوں میں پائی جائیں تو مذکورہ بالا شروط کے تحت انہیں قتل کرنا جائز ہو گا اور ان کے قاتل کے لیے روزِ قیامت اجر بھی ثابت ہو گا بشرطیکہ یہ کام امام عادل اور حاکم وقت کرے۔ (۷) خارجی لوگ امتِ محمدیہ کے بدعتی گروہوں میں سے گندا اور بدترین بدعتی فرقہ ہیں۔ (۸) اعتقادِ فاسد کی بنا پر امام عادل کے خلاف بغاوت کرنے والے، اس سے جنگ کرنے والے اور زمین میں شر اور فساد کرنے والے، نیز اسی طرح کے قبیح افعال کے مرتکب لوگوں کے خلاف قتال کرنا جائز ہے۔ و اللہ اعلم۔ (۹) ’’نو عمر اور کم عقل‘‘ عموماً نوعمری میں عقل کم ہی ہوتی ہے۔ علم بھی پختہ نہیں ہوتا، جذبات غالب ہوتے ہیں۔ تجربہ وسیع نہیں ہوتا جبکہ علم عمر اور تجربہ و مطالعہ سے پختہ ہوتا ہے، اس لیے ’’نوعمر‘‘ عالم کو فتویٰ بازی سے پرہیز کرنا چاہیے، خصوصاً جبکہ اس کے فتاویٰ جمہور اہل علم اور اہل فتویٰ سے مختلف ہوں۔ نو عمر اور نو آموز لوگ شیطان کے جال میں جلدی پھنستے ہیں اور امت میں فتنے کا سبب بنتے ہیں۔ اَعَاذَنَا اللّٰہُ مِنْہَا۔ ’’مخلوق میں سے بہترین‘‘ احادیث میں دو طرح کے الفاظ آئے ہیں: مِنْ قَوْلِ خَیْرِ الْبَرِیَّۃِ اور مِنْ خَیْرِ قَوْلِ الْبَرِیَّۃِ۔ ترجمہ میں تو فرق ہے مگر نتیجہ ایک ہی ہے۔ اوپر حدیث میں ترجمہ پہلے الفاظ کے لحاظ سے کیا گیا ہے، دوسرے الفاظ کا ترجمہ یوں ہو گا: ’’لوگوں کی بہترین باتیں۔‘‘ اس سے مراد قرآن و احادیث ہی ہیں، یعنی وہ بات تو صحیح کریں گے مگر ان اس کا مفہوم غلط سمجھیں گے۔ قرآن مجید کا صحیح مفہوم احادیث کی مدد سے اور احادیث کا صحیح مفہوم صحابہ کے طرز عمل اور فتاویٰ کی مدد سے سمجھنا چاہیے ورنہ گمراہی کا خطرہ ہے۔ و اللہ اعلم۔"}],[4103,"شریک بن شہاب کہتے ہیں کہ میری خواہش تھی کہ میں صحابہ رسول میں سے کسی صحابی سے ملوں اور ان سے خوارج کے متعلق سوال کروں، تو میری ملاقات عید کے دن ابوبرزہ رضی اللہ عنہ سے ان کے شاگردوں کی جماعت میں ہوئی۔ میں نے ان سے کہا: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کو خوارج کا تذکرہ کرتے سنا ہے؟ کہا: ہاں، میں نے رسول اللہ صلی اللہ علیہ وسلم کو اپنے کانوں سے سنا اور اپنی آنکھوں سے دیکھا، آپ کے پاس کچھ مال آیا، آپ نے اسے تقسیم کیا اور اپنے دائیں اور بائیں جانب کے لوگوں کو دے دیا اور اپنے پیچھے والوں کو کچھ نہیں دیا۔ ایک شخص آپ کے پیچھے سے کھڑا ہوا اور بولا: محمد! آپ نے تقسیم میں انصاف نہیں کیا۔ وہ ایک کالا(سانولا) شخص تھا، جس کے بال منڈے ہوئے تھے اور دو سفید کپڑوں میں ملبوس تھا۔ رسول اللہ صلی اللہ علیہ وسلم سخت غضبناک ہوئے اور فرمایا: \"اللہ کی قسم! تم میرے علاوہ کوئی ایسا شخص نہیں پاؤ گے جو مجھ سے زیادہ عادل ہو\"۔ پھر فرمایا: \"آخری دور میں کچھ لوگ ہوں گے (شاید) یہ بھی انہیں میں سے ہو گا، وہ قرآن پڑھیں گے، مگر وہ ان کی ہنسلی سے نیچے نہ اترے گا، وہ اسلام سے اسی طرح نکل جائیں گے جس طرح تیر شکار سے نکل جاتا ہے۔ ان کی علامت یہ ہے کہ وہ سر منڈائے ہوں گے ۱؎، وہ ہمیشہ پیدا ہوتے رہیں گے یہاں تک کہ ان کا آخری شخص مسیح دجال کے ساتھ نکلے گا، لہٰذا جب تم انہیں پاؤ تو قتل کر دو، وہ بد نفس اور تمام مخلوقات میں بدتر ہیں\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: شریک بن شہاب مشہور نہیں ہیں ۲؎۔\n§وضاحت\n۱؎: اس حدیث سے یہ استدلال قطعا درست نہیں ہے کہ سر منڈانا نعوذباللہ مکروہ ہے کیونکہ کسی چیز کا کسی قوم کے لیے علامت و شناخت بننا یہ اس کے مباح ہونے کے منافی نہیں ہو سکتا، چنانچہ نبی اکرم صلی اللہ علیہ وسلم نے جب ایک بچے کو دیکھا کہ اس کے سر کے کچھ حصوں کا بال منڈا ہوا ہے اور کچھ کا چھوڑ دیا گیا ہے تو آپ نے فرمایا: \" اس کا پورا سر مونڈ دو یا پورا سر چھوڑ دو \"۔ آپ کا یہ فرمان سر منڈانے کے مباح ہونے کے لیے کافی ہے۔ ۲؎: یعنی مشہور نہیں ہیں بلکہ مقبول ہیں، اور مقبول اس کو کہتے ہیں جس کی دوسرے راوی سے متابعت پائی جائے تو اس کی روایت مقبول ہو گی، ورنہ وہ لین الحدیث ہو گا، یہاں اس حدیث کے اکثر ٹکڑوں کی متابعت موجود ہے، اس لیے حدیث مقبول ہو گی۔","الألباني: ضعيف",{"u2":"حضرت شریک بن شہاب سے منقول ہے کہ میری خواہش تھی کہ میں رسول اللہ صلی اللہ علیہ وسلم کے صحابہ کرام رضی اللہ عنہم میں سے کسی کو ملوں اور ان سے خارجیوں کے بارے میں پوچھوں، چنانچہ عید المبارک کے دن حضرت ابو برزہ رضی اللہ تعالٰی عنہ کے ساتھ میری ملاقات ہوئی۔ ان کے ساتھ ان کے کچھ ساتھی بھی تھے۔ میں نے ان سے کہا: آپ نے رسول اللہ صلی اللہ علیہ وسلم کو خارجیوں کا ذکر فرماتے سنا ہے؟ انہوں نے فرمایا: ہاں! میں نے رسول اللہ صلی اللہ علیہ وسلم (کے فرمان) کو اپنے کانوں سے سنا اور میں نے (اس وقت) آپ کو اپنی آنکھوں سے دیکھا کہ آپ کے پاس کچھ مال لایا گیا۔ آپ نے اسے تقسیم فرما دیا۔ اپنی دائیں بائیں طرف والے لوگوں کو دیا لیکن اپنے پیچھے والے لوگوں کو کچھ نہ دیا۔ آپ کے پیچھے سے ایک آدمی کھڑا ہوا اور کہا: اے محمد! آپ نے تقسیم میں انصاف نہیں کیا۔ وہ آدمی کالے رنگ کا، منڈے ہوئے سر والا تھا۔ اس پر دو سفید کپڑے تھے۔ رسول اللہ صلی اللہ علیہ وسلم کو (یہ سن کر) شدید غصہ آیا اور آپ نے فرمایا: ’’اللہ کی قسم! تم میرے بعد کوئی آدمی مجھ سے بڑھ کر انصاف کرنے والا نہیں پائو گے۔‘‘ پھر فرمایا: ’’اخیر زمانے میں ایسے لوگ ظاہر ہوں گے، اور یہ بھی مجھے انہی سے لگتا ہے، جو قرآن پڑھیں گے، مگر وہ ان کے حلق سے نیچے نہیں اترے گا۔ وہ اسلام سے اس طرح نکل جائیں گے جس طرح تیر اپنے شکار سے (صاف) نکل جاتا ہے۔ ان کے خصوصی علامت سر منڈوانا ہے۔ وہ لوگ ہمیشہ (بار بار) نکلتے رہیں گے حتی کہ ان میں سے آخری گروہ مسیح دجال کے ساتھ نکلے گا۔ جب تم ان سے ملو تو انہیں (بے دریغ) قتل کرو۔ وہ تمام مخلوقات میں سے بدترین لوگ ہیں۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ شریک بن شہاب (راویٔ حدیث) کوئی معروف آدمی نہیں۔ (بلکہ مجہول ہے کیونکہ ازرق بن قیس کے علاوہ دوسرے کسی شخص نے اس سے روایت بیان نہیں کی۔)","f2":"(۱) ’’نہیں پائو گے‘‘ نبی سے بڑھ کر کوئی انصاف کنے والا نہیں ہو سکتا، چاہے وہ کتنا بھی انصاف پسند ہو۔ (۲) ’’سر منڈوانا‘‘ سر منڈوانا اگرچہ جائز ہے اور حج میں مستحب ہے مگر کسی جائز چیز کو لازم کر لینا اور اسے شرعی مسئلہ سمجھ لینا اور اسے خواہ مخواہ مستحب بنا لینا قطعاً ناجائز ہے۔ وہ لوگ بھی سر مونڈنے کو اپنا شعار بنا لیں گے اور اسے لازم سمجھیں گے۔ یہ بھی کہا جا سکتا ہے کہ آپ نے اسے صرف بطور علامت بیان فرمایا ہے۔ اس کی مذمت نہیں فرمائی کیونکہ اگر کسی جائز چیز کو مستقلاً اختیار کر لیا جائے مگر اسے شرعی مسئلہ اور افضل خیال نہ کیا جائے تو کوئی حرج نہیں۔ بسا اوقات انسان اپنی سہولت کے لیے ایک جائز چیز کو مستقلاً اختیار کر لیتا ہے، جیسے کوئی شخص ہمیشہ قمیص پہنے یا بند جوتا پہنے۔ ظاہر ہے اس میں کوئی قباحت نہیں اور اگر وہ کام افضل اور مستحب ہے تو پھر اس پر دوام بدرجۂ اولیٰ مستحب ہے، جیسے اشراق کی دو رکعتیں وغیرہ۔ (۳) ’’آخری گروہ‘‘ گویا خوارج والی ذہنیت قیامت تک رہے گی۔ (۴) ’’مسیح دجال‘‘ یعنی جھوٹا اور دغا باز مسیح۔ جس طرح ہم اب کسی مدعی نبوت کو جھوٹا نبی کہیں۔ چونکہ وہ مسیح ہونے کا دعویٰ کرے گا بلکہ اس وقت کے یہودی اسے ’’مسیح‘‘ تسلیم کر کے اس کی پیروی کریں گے۔ اب بھی یہودی مسیح کی آمد کے منتظر ہیں۔ (حالانکہ مسیح صلی اللہ علیہ وسلم تو کب کے آ چکے) اس لیے اسے مسیح دجال کہا گیا۔ دجال صفت کا صیغہ ہے، کسی کا نام یا لقب نہیں۔ اس کے معنی ہیں: انتہائی دغا باز، جھوٹا اور فراڈی۔ گویا ان الفاظ سے اس کا مسیح ہونا ثابت نہیں ہوتا بلکہ جھوٹا ہونا ثابت ہوتا ہے، جیسے ’’جھوٹا نبی‘‘ کہنے سے کسی کی نبوت ثابت نہیں ہوتی۔ (۵) ’’بدترین لوگ‘‘ کیونکہ وہ مسلمانوں کو قتل کریں گے۔ اور مسلمانوں کا قاتل بدترین جہنمی ہے۔"}],[4104,"سعد بن ابی وقاص رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان سے لڑنا کفر (کا کام) اور اسے گالی دینا فسق ہے\" ۱؎۔\n§وضاحت\n۱؎: «فسق» اللہ کی اطاعت سے نکل جانے کو کہتے ہیں، مسلمان کو گالی دینا اور سب وشتم کرنا بھی «فسق» ہے، اور یہاں «کفر» سے مراد کافروں کا عمل ہے، یعنی: ایک مسلمان کو کافر ہی ناحق قتل کرتا ہے کوئی مسلمان نہیں، یہ بطور زجز و توبیخ کے ہے نہ کہ ایسے عمل کو حقیقی کفر کہا گیا ہے۔","الألباني: صحيح",{"u2":"حضرت سعد بن ابو وقاص رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان سے لڑنا کفر اور اسے گالی دینا فسق (کبیرہ گناہ) ہے۔‘‘","f2":"(۱) باب کے ساتھ حدیث کی مناسبت بالکل واضح ہے کہ مسلمان کے ساتھ لڑائی کرنا بہت بڑا کبیرہ گناہ اور کفریہ عمل ہے۔ (۲) اس حدیث سے ثابت ہوتا ہے کہ مسلمان کی عزت و حرمت اور اس کا وقار بہت زیادہ ہے، لہٰذا جو شخص کسی مسلمان کی بے عزتی اور توہین کرتا یا اسے ستاتا ہے، وہ ایمان کے تقاضے پامال کرتا ہے، چنانچہ اپنے ایمان کی حفاظت کے لیے اس پر لازم ہے کہ وہ ہر مسلمان کی تعظیم و تکریم کرے، نیز اسے بے عزت کرنے سے احتراز کرے اور گالی گلوچ جیسے قبیح عمل سے کنارہ کشی کرتے ہوئے محتاط رویہ اپنائے۔ یہ کام کسی مسلمان کے شایانِ شان نہیں۔ (۳) اس حدیث سے یہ بھی ثابت ہوتا ہے کہ جب عام مسلمان کو گالی گلوچ دینا کبیرہ گناہ اور ناجائز عمل ہے تو صحابہ کرام رضی اللہ عنہم جو تمام امت سے افضل و اکرم اور اعلیٰ و ارفع درجے کے مسلمان ہیں، ان کو سب و شتم کا نشانہ بنانا کس قدر گندا او، قبیح و غلیظ عمل اور گھنائونا جرم ہو گا۔ اَعَاذَنَا اللّٰہُ مِنْہُ۔ (۴) یہ حدیث مرجئہ فرقے کے اس باطل عقیدے کا صریح طور پر رد کرتی ہے کہ انسان کے لیے ایمان کے ساتھ گناہ نقصان دہ نہیں ہوتے، نیز ان کے اس عقیدے کا بھی اس حدیث سے رد ہوتا ہے کہ اعمال ایمان کا حصہ نہیں۔ (۵) حقوق اللہ کے ساتھ ساتھ حقوق العباد کی ادائیگی بھی ازحد ضروری ہے۔ ایک کامل مومن کے لیے ضروی ہے کہ سرتاپا اپنے تمام اعضاء کو سوچ سمجھ کر استعمال کرے، بالخصوص ہاتھ اور زبان سے کسی بھی مسلمان کو معمولی سے معمولی نقصان اور تکلیف تک نہ دے۔ (۶) ’’لڑائی لڑنا‘‘ اس سے مسلح لڑائی مراد ہے۔ زبانی یا دستی یا لاٹھی کی لڑائی کو عربی زبان میں قتال نہیں کہتے کیونکہ اس قسم کی لڑائی میں کسی کے قتل ہونے کا غالب امکان نہیں ہوتا۔ (قتال قتل سے بنا ہے۔) (۷) ’’کفر ہے‘‘ یہاں کفر سے مراد کفر دون کفر ہے، وہ کفر مراد نہیں جس کی وجہ سے مسلمان مسلمان ہی نہیں رہتا، یعنی یہاں کفر اکبر مراد نہیں بلکہ کفریہ عمل کی نشاندہی مراد ہے، نیز مسلمان سے لڑائی کی شدید قباحت کا بیان مقصود ہے۔ و اللہ اعلم۔ (۸) فسق سے مراد کبیرہ گناہ ہے۔ جس کے کرنے سے انسان کافر تو نہیں بنتا مگر صحیح مومن بھی نہیں رہتا۔ گالی گلوچ اس لیے فسق ہے کہ یہ لڑائی کا پیش خیمہ ہے۔ عام طور پر گالی گلوچ قتل قتل و قتال کا سبب بن جاتے ہیں، نیز گالی گلوچ کرنا فاسقین کا کام ہے۔ مزید برآں یہ بھی کہ جن کاموں کو کفر و فسق یا جاہلیت کے کام کہا گیا ہے، ان سے بچنا بہت ضروری بلکہ واجب ہے کیونکہ ایسے کام کسی مسلمان کو زیب نہیں دیتے اور نہ کسی مومن کے لائق ہی ہیں۔"}],[4105,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ مسلمان کو گالی دینا فسق اور اس سے لڑنا کفر (کا کام) ہے۔","الألباني: صحيح الإسناد موقوف",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ نے فرمایا: مسلمان کو گالی دینا فسق اور اس سے لڑائی لڑنا کفر ہے۔"}],[4106,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ مسلمان کو گالی دینا فسق اور اس سے لڑنا کفر (کا کام) ہے۔ ابان نے ابواسحاق سبیعی سے پوچھا: ابواسحاق! کیا آپ نے اسے ابوالاحوص کے علاوہ کسی سے نہیں سنا؟ کہا: میں نے اسود اور ہبیرہ سے بھی سنا ہے۔","الألباني: صحيح الإسناد موقوف",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ نے فرمایا: مسلمان کو گالی دینا فسق (کبیرہ گناہ) ہے اور اس سے لڑنا کفر ہے۔ ابان نے (ابو اسحاق سے) پوچھا: ابو اسحاق! آپ نے یہ حدیث صرف ابو الاحوص سے سنی ہے؟ انہوں نے کہا: (نہیں) بلکہ اسود اور ہبیرہ سے بھی میں نے یہ حدیث سنی ہے۔"}],[4107,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ مسلمان کو گالی دینا فسق اور اس سے لڑنا کفر (کا کام) ہے۔","الألباني: صحيح الإسناد موقوف",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ نے فرمایا مسلمان کو گالی دینا فسق اور اس سے لڑائی لڑنا کفر ہے۔","f2":"یہ معنی پہلے معنی سے مختلف ہیں، تاہم عربی ترکیب کے لحاظ سے یہ معنی بھی بن سکتے ہیں کہ مسلمان کو یہ کام نہیں کرنے چاہئیں۔"}],[4108,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان کو گالی دینا فسق اور اس سے لڑنا کفر (کا کام) ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت عبداللہ رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان کو گالی دینا فسق ہے اور اس سے لڑائی کرنا کفر ہے۔‘‘"}],[4109,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان کو گالی دینا فسق اور اس سے لڑنا کفر (کا کام) ہے\"۔ (اس حدیث کی روایت کے بارے میں شعبہ نے حماد سے کہا) آپ کس پر (وہم اور غلطی کی) تہمت (اور الزام) لگاتے ہیں؟ منصور پر، زبید پر یا سلیمان اعمش پر؟ انہوں نے کہا: نہیں، میں تو ابووائل پر تہمت لگاتا ہوں ۱؎۔\n§وضاحت\n۱؎: یعنی مجھے ابووائل شقیق بن سلمہ کے سلسلہ میں شک ہے کہ انہوں نے عبداللہ بن مسعود رضی اللہ عنہ سے یہ حدیث سنی ہے یا نہیں۔ واضح رہے کہ ابووائل شقیق بن سلمہ ثقہ راوی ہیں :(واللہ اعلم )، نیز دیکھئیے اگلی روایت۔","الألباني: صحيح الإسناد",{"u2":"حضرت عبداللہ (بن مسعود) رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان کو گالی گلوچ کرنا فسق اور اس سے لڑائی لڑنا کفر ہے۔‘‘\n(امام شعبہ نے اپنے استاد حماد سے کہا:) تم کس پر تہمت لگاتے ہو؟ کیا تم منصور پر تہمت لگاتے ہو؟ کیا تم زبید پر تہمت لگاتے ہو؟ کیا تم سلیمان پر تہمت لگاتے ہو؟ حماد نے کہا: نہیں (میں ان میں سے کسی پر بھی تہمت نہیں لگاتا) لیکن میں (ان سب کے استاد) ابو وائل پر تہمت لگاتا ہوں۔ (کہ آیا اس نے عبداللہ بن مسعود رضی اللہ تعالٰی عنہ سے یہ حدیث سنی ہے یا نہیں۔)","f2":"مذکورہ بالا مسئلے کی تفصیل کچھ اس طرح سے ہے کہ حماد، جس سے امام شعبہ نے منصور وغیرہ پر تہمت لگانے کی بابت پوچھا تھا، غالباً یہ حماد بن ابو سلیمان ہے۔ وہ امام شعبہ کا شیخ تھا اور مرجئہ میں سے تھا۔ یہ تو معلوم ہی ہے کہ مرجئہ فرقے کا عقیدہ ہے کہ اعمال، ایمان کا جز نہیں اور یہ بھی کہ جب کوئی شخص کلمہ پڑھ کر مسلمان ہو جاتا ہے تو پھر ایمان کے ساتھ اس کے لیی کوئی گناہ نقصان دہ نہیں ہو سکتا اور یہ عقیدہ قطعاً باطل ہے۔ حماد کا ابو وائل کو تمہم کرنا غلط ہے۔ اس سے ان کا مقصد اپنے باطل عقیدے کا دفاع کرنا ہے۔ ابووائل سے مراد حضرت شقیق بن سلمہ ہیں جو حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ کے معروف شاگرد اور مخضرم تابعی ہیں۔ مرجئہ کے ظہور کے بعد، حضرت ابووائل رحمہ اللہ سے جب ان (مرجئہ) کے متعلق پوچھا گیا تو سائل کے جواب میں انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی یہی حدیث بیان فرمائی کہ [سِبَابُ الْمُسْلِمِ فُسُوْقٌ وَ قِتَالُہٗ کُفْرٌ] (صحیح البخاری، الایمان، باب خوف المؤمن…، حدیث: ۴۸، و صحیح مسلم، الایمان، باب بیان قول النبیV…، حدیث: ۶۴) چونکہ اس متفق علیہ حدیث شریف سے مرجئہ کے مذکورہ باطل عقیدے کا صریح طور پر رد ہوتا ہے، اس لیے اس حدیث کے بنیادی راوی حضرت ابو وائل رحمہ اللہ ہی کو متہم کرنے کی ناپاک جسارت کرتے ہوئے یہ کہا گیا کہ معلوم نہیں ابو وائل نے یہ حدیث حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ سے سنی بھی ہے کہ نہیں؟ لیکن اللہ تعالیٰ کروڑوں رحمتیں فرمائے جماعت اصحاب الحدیث پر کہ جنہوں نے مبتدعین کے فرار کی تمام راہیں بند کر دیں، صحیح مسلم میں اس بات کی قطعی صراحت موجود ہے کہ ابو وائل رحمہ اللہ نے جو حدیث بیان فرمائی ہے، لا ریب! وہ رسول اللہ صلی اللہ علیہ وسلم ہی کا سچا فرمان ہے۔ اس میں قطعاً کوئی شک نہیں۔ حضرت ابووائل سے بیان کرنے والے ان کے شاگرد زبید نے کہا کہ میں نے حضرت ابو وائل سے، یہ حدیث شریف سن کر پوچھا: کیا آپ نے حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ سے سنا ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم سے یہ حدیث بیان فرماتے ہیں؟ انہوں نے فرمایا: ہاں! (میں نے حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ سے سنا ہے کہ وہ یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے بیان فرماتے ہیں۔) دیکھئے: (صحیح مسلم، الایمان، باب بیان قول النبیV: سباب المسلم فسوق و قتالہ کفر، حدیث: (۱۱۶)-۶۴)"}],[4110,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان کو گالی دینا فسق اور اس سے لڑنا کفر (کا کام) ہے\"۔ زبید کہتے ہیں کہ میں نے ابووائل سے کہا: کیا آپ نے اسے عبداللہ بن مسعود سے سنا ہے؟ کہا: ہاں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان کا گالی دینا فسق اور اس کا (دوسرے مسلمانوں سے) لڑائی کرنا کفر ہے۔‘‘ زبید کہتے ہیں: میں نے ابو وائل سے پوچھا: کیا آپ نے اس حدیث کو عبداللہ بن مسعود رضی اللہ تعالٰی عنہ سے سنا ہے؟ انہوں نے فرمایا: ہاں! (سنا ہے)۔"}],[4111,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان کو گالی دینا فسق اور اس سے لڑنا کفر (کا کام) ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان کو گالی دینا فسق اور اس سے لڑائی لڑنا کفر ہے۔‘‘"}],[4112,"ابووائل کہتے ہیں کہ عبداللہ بن مسعود رضی اللہ عنہ نے کہا: مسلمان کو گالی دینا فسق اور اس سے لڑنا کفر (کا کام) ہے۔","الألباني: صحيح موقوف",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ نے فرمایا: مسلمان کو گالی دینا فسق اور اس سے لڑائی لڑنا کفر ہے۔"}],[4113,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ مومن کو قتل کرنا کفر (کا کام) اور اسے گالی دینا فسق ہے۔","الألباني: صحيح موقوف",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ نے فرمایا: مومن سے لڑائی لڑنا کفر اور اس کو گالی دینا فسق ہے۔","f2":"تکرار سے مقصود یہ ہے کہ بعض راویوں نے اس روایت کو مرفوع (رسول اللہ صلی اللہ علیہ وسلم کا فرمان) بیان کیا ہے اور بعض نے موقوف (صحابی رضی اللہ تعالٰی عنہ کا قول)۔ یہ اختلاف نقصان دہ نہیں کیونکہ موقوف سے مرفوع کی نفی نہیں ہوتی، اور روایت کا دونوں طرح مروی ہونا درست ٹھہرتا ہے۔ بشرطیکہ اسنادی ضعف سے پاک ہوں گویا اللہ کے رسول صلی اللہ علیہ وسلم نے بھی فرمایا اور صحابی نے بھی وہی بات کہہ دی۔"}],[4114,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو (امیر کی) اطاعت سے نکل گیا اور (مسلمانوں کی) جماعت چھوڑ دی پھر مر گیا تو وہ جاہلیت کی موت مرا، اور جو میرے امتی کے خلاف اٹھے اور اچھے اور خراب سبھوں کو مارتا جائے اور مومن کو بھی نہ چھوڑے اور عہد والے سے بھی وفا نہ کرے تو اس کا مجھ سے کوئی تعلق نہیں، اور جو عصبیت کے جھنڈے تلے لڑے اور لوگوں کو عصبیت کی طرف بلائے یا اس کا غصہ عصبیت کی وجہ سے ہو، پھر وہ مارا جائے تو اس کی موت جاہلیت کی موت ہے\" ۱؎۔\n§وضاحت\n۱؎: کیونکہ عصبیت زمانۂ جاہلیت ہی کی خصوصیات میں سے ہے، مسلمان کو ہمیشہ حق کا متلاشی ہونا چاہیئے، اور حق ہی کے لیے اس کا تعاون ہونا چاہیئے، اندھی عصبیت میں ذات برادری، پارٹی، جماعت اور علاقہ والوں کی اندھی حمایت مسلمان کا شیوہ نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص (تسلیم شدہ امیر کی) اطاعت سے نکل جائے اور جماعت سے جدا ہو جائے، اگر وہ اسی حال میں مرا تو جاہلیت کی موت مرا۔ جو شخص میری امت کے خلاف (مسلح ہو کر) نکلا اور ہر نیک و بد کو بلا امتیاز قتل کرنے لگا، وہ نہ مومن کی پروا کرتا ہے نہ کسی ذمی کے عہد کا لحاظ رکھتا ہے تو اس کا مجھ سے کوئی تعلق نہیں۔ اور جو شخص (کسی قسم کے حزبی، قومی یا مذہبی گروہی تعصب میں آ کر) کسی مبہم اور اندھے جھنڈے کے نیچے لڑا، کسی ایک جماعت کی طرف دعوت دیتا ہے یا کسی جماعت کی خاطر وہ غصے میں آ کر لڑتا ہے اور مارا جاتا ہے تو اس کی موت جاہلیت کی موت ہو گی۔‘‘","f2":"(۱) باب کے ساتھ حدیث کی مناسبت بالکل واضح ہے کہ جو شخص اندھا دھند گروہی اور حزبی تعصب کا شکار ہو کر اندھے اور مبہم جھنڈے کے نیچے لڑتا ہوا مرا، وہ حرام موت ہی مرا۔ (۲) اس حدیث شریف کا تقاضا ہے کہ تمام اہل اسلام کو شرعی طور پر بااختیار حاکم و امیر مقرر کر کے اس کے ہاتھ مضبوط کرنے چاہئیں اور اس کی ہدایات کے مطابق دشمنانِ اسلام کے خلاف برسرپیکار ہونا چاہیے۔ (۳) بااختیار شرعی حاکم و امیر کی اطاعت واجب ہے، نیز مسلمانوں کی جماعت کے ساتھ لزوم بھی ضروری ہے۔ (۴) اہل اسلام جس شخص کو اپنا امام و حاکم مقرر کر دیں، شرعی تقاضوں کے مطابق اس کی اتباع واجب اور سبیل المومنین کی مخالفت حرام ہے۔ (۵) مذکورہ صفات کے حامل شرعی امیر کی اطاعت نہ کرنے والا اہل جاہلیت کے مشابہ ہے، اور اسی حالت میں مر جانے والا جاہلیت کی موت مرے گا۔ (۶) ایسے شرعی حاکم کی مخالفت کرنا، اس کی اطاعت نہ کرنا کبیرہ گناہ ہے۔ (۷) اس حدیث سے یہ بھی ثابت ہوتا ہے کہ فسق و فجور اور کبیرہ گناہوں کا مرتکب، ملتِ اسلامیہ سے خارج نہیں ہوتا الا یہ کہ وہ صریح کفر کا ارتکاب کرے یا مرتد ہو کر دین اسلام سے کنارہ کش ہو جائے۔ اَعَاذَنَا اللّٰہُ مِنْہُ۔ (۸) ’’تسلیم شدہ امیر‘‘ اس سے مراد وہ مسلمان حاکم ہے جو یا تو منتخب شدہ ہو یا ویسے لوگ اس پر متفق ہوں، وہ امن و امان قائم کرتا ہو، مجرمین کو سزائیں دیتا، (شرعی حدود ہوں یا دیگر سزائیں) اور امت مسلمہ کے دفاع کا فریضہ سر انجام دیتا ہو، نہ کہ وہ کاغذی امیر جن کو ٹڈی دل تنظیمیں اپنا امیر بنا لیتی ہیں اور وہ بیکت وقت ایک دوسرے کے مخالف بھی ہوتی ہیں۔ ایسے امیر سوائے دفتری سہولتوں کے استعمال کے اور کچھ نہیں کر سکتے۔ نہ ملکی انتظام میں ان کا کوئی دخل ہوتا ہے اور نہ ملکی دفاع میں۔ نہ ان کی اطاعت کا معاشرے کو کوئی فائدہ ہے نہ ان کی نافرمانی کا نقصان۔ وہ تنظیمیں سیاسی ہوں یا مذہبی، ہر شہر میں وافر مقدار میں پائی جاتی ہیں۔ ایک پولیس اہل کار ان کے امیروں سے زیادہ اختیارات کا مالک ہوتا ہے۔ ایسے امیر اور ایسی تنظیمیں یہاں مراد نہیں۔ جب تک کسی کا جی کرے، ان تنظیموں میں رہے اور اور جب جی کرے، انہیں چھوڑ جائے۔ ان میں داخل ہونے کا کوئی عذاب نہیں، البتہ اگر اس نے کوئی عہد اور وعدہ کیا ہو تو اس کی پابندی ضروری ہے بشرطیکہ وہ وعدہ اور عہد شریعت کے خلاف نہ ہو۔ (۹(’’جماعت سے جدا ہو جائے‘‘ جماعت سے مراد مسلمانوں کی جماعت ہے جو ایک امام و حاکم پر متفق ہو یا اکثریت اس پر متفق ہو۔ ایسی صورت میں اقلیت کو بھی حاکم ہی کی اطاعت کرنا ہو گی۔ اگر کوئی شخص ایسی جماعت سے نکل جائے، یعنی امیر سے باغی ہو جائے اور جماعت میں تفرقہ کی کوشش کرے تو خواہ وہ طبعی موت مرے یا حکومت اسے بغاوت کی سزا میں مار دے، اس کی موت غیر اسلامی ہو گی۔ (۱۰) ’’جاہلیت کی موت‘‘ یعنی جاہلیت میں لوگ بغیر کسی امارت اور نظم کے رہتے تھے۔ کوئی کسی کا ماتحت نہ تھا۔ اسی طرح یہ بھی نظم اور جماعت سے باہر مرا، گویا کافروں جیسی موت مرا اگرچہ وہ کافر نہیں۔ یہ تب ہے اگر وہ بغاوت نہ کرے اور فتنہ پیدا نہ کرے۔ اگر وہ بغاوت کرے، فتنہ پیدا کرے یا امت مسلمہ میں تفریق پیدا کرے تو وہ واجب القتل ہے۔ (۱۱) ’’اس کا مجھ سے کوئی تعلق نہیں‘‘ کیونکہ وہ باغی کے حکم میں ہے۔ اس سے خارجیوں والا سلوک ہو گا۔ (دیکھئے، حدیث: ۴۱۰۴، ۴۱۰۶، ۴۱۰۸) (۱۲) ’’مبہم اور اندھے جھنڈے‘‘ مبہم سے مراد جس کا حق یا باطل ہونا واضح نہ ہو۔ اور اندھے سے مراد کہ وہ لڑائی کسی فرقے، گروہ یا نسل کی خاطر ہو۔ اس کی بنیاد تعصب پر ہو۔ ایسی جنگ میں مارا جانے والا حرام موت مرے گا جس طرح لوگ دور جاہلیت میں اپنے قبیلے، گروہ یا ساتھی اور دوست کے لیے لڑتے تھے۔ حق ناحق کا کوئی ایسا امتیاز نہ تھا اور حرام موت مرتے تھے۔ صرف اعلام کلمۃ اللہ کی خاطر لڑنے والا ہی شہادت کی موت مرے گا نہ کہ مسلمانوں کے ساتھ لڑنے والا، خواہ وہ کیسا ہی خوش نما نعرہ لگا کر کیوں نہ لڑے، مثلاً: حب اہل بیت یا حب صحابہ وغیرہ۔ یہ اس لیے کہ باہمی لڑائی بہرحال حرام ہے۔ و اللہ اعلم۔"}],[4115,"جندب بن عبداللہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص عصبیت کے جھنڈے تلے لڑے اور وہ اپنی قوم کی عصبیت میں لڑے یا عصبیت میں غصہ ہو تو اس کی موت جاہلیت کی موت ہو گی\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: عمران القطان زیادہ قوی نہیں ہیں ۱؎۔\n§وضاحت\n۱؎: مسلم کی سند میں \" عمران القطان \" نہیں ہیں، بلکہ ان کی جگہ معتمر بن سلیمان التیمی ہیں، قتادہ بھی نہیں ہیں، ان کی جگہ سلیمان التیمی ہیں، اس لیے حدیث صحیح ہے۔","الألباني: صحيح",{"u2":"حضرت جندب بن عبداللہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص (اندھا دھند تعصب میں آ کر) کسی مبہم اور اندھے جھنڈے کے تحت لڑا، وہ صرف اپنے گروہ کی حمایت میں لڑتا اور اسی کی حمایت میں غضب ناک ہوتا ہے، (وہ مارا جائے) تو اس کی موت جاہلیت کی (حرام) موت ہو گی۔‘‘ امام ابو عبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ (اس حدیث کا راوی) عمران القطان قوی نہیں ہے۔"}],[4116,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب ایک مسلمان اپنے دوسرے مسلمان بھائی پر ہتھیار اٹھائے (اور دونوں جھگڑنے کے ارادے سے ہوں) تو وہ دونوں جہنم کے کنارے پر ہیں، جب ایک دوسرے کو قتل کرے گا تو دونوں ہی اس میں جا گریں گے\" ۱؎۔\n§وضاحت\n۱؎: اس لیے کہ دونوں ہی ایک دوسرے کے قتل کے درپے تھے، ایک کامیاب ہو گیا۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب کوئی مسلمان اپنے بھائی کی طرف اسلحے کے ساتھ اشارہ کرے (ایک مسلمان دوسرے پر ہتھیار اٹھا لے اور دوسرا بھی اٹھا لے) تو وہ دونوں جہنم کے کنارے پر ہوتے ہیں۔ اور جب ایک، دوسرے کو قتل کر دے تو دونوں اکٹھے جہنم میں گر پڑتے ہیں۔‘‘","f2":"(۱) اس حدیث سے ثابت ہوتا ہے کہ مسلمان کو ناحق قتل کرنا کبیرہ گناہ اور حرام ہے، نیز یہ بھی ثابت ہوتا ہے کہ اس کبیرہ گناہ کا ارتکاب کرنے والا جہنم کی آگ کا مستحق ہو جاتا ہے۔ (۲) اس حدیث شریف سے یہ مسئلہ بھی ثابت ہوتا ہے کہ جب کوئی شخص کسی بھی (اچھے یا برے) کام کا پختہ ارادہ کر لیتا ہے لیکن کسی وجہ سے اس پر عمل نہیں کر سکتا تو بھی اپنے عزم کے مطابق وہ شخص مواخذے یا اجر کا مستحق بن جاتا ہے۔ (۳) مرتکب کبیرہ، ملت اسلامیہ سے خارج نہیں ہوتا بلکہ وہ مومن اور مسلم ہی رہتا ہے جیسا کہ قرآن مجید میں بھی انہیں مومن کہا گیا ہے: {وَاِِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِیْنَ اقْتَتَلُوْا فَاَصْلِحُوْا بَیْنَہُمَا} اور مذکورہ احادیث میں رسول اللہ صلی اللہ علیہ وسلم نے بھی انہیں مسلمان کہا ہے۔ (۴) ’’گر پڑتے ہیں‘‘ یہ تب ہے جب دونوں کی نیت لڑائی کی ہو۔ دونوں ننگے مسلح ہوں۔ دونوں ایک دوسرے کو قتل کرنے کے درپے ہوں، البتہ دائو ایک کا لگ گیا، تو قاتل و مقتول دونوں یکساں جہنمی ہوں گے کیونکہ دونوں کی نیت قتل کی تھی۔ اس حدیث سے مراد بھی یہی ہے کہ دونوں ایک دوسریح کے خلاف ہتھیار اٹھا لیں، جس طرح کہ اگلی احادیث میں اس کی صراحت موجود ہے۔ و اللہ اعلم۔"}],[4117,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ جب دو مسلمان آپس میں ایک دوسرے کے خلاف ہتھیار اٹھا لیں تو وہ دونوں جہنم کے کنارے پر ہیں، پھر جب ان میں سے ایک دوسرے کو قتل کرے گا تو وہ دونوں جہنم میں ہوں گے۔","الألباني: صحيح موقوف",{"u2":"حضرت ابوبکرہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ جب دو مسلمان ایک دوسرے پر اسلحے کے ساتھ حملہ کریں، وہ دونوں جہنم کے کنارے پر ہوتے ہیں۔ پھر جب ان میں سے کوئی ایک، دوسرے کو قتل کر دیتا ہے تو دونوں آگ میں جاتے ہیں۔ (قاتل تو مسلمان کو قتل کرنے کی وجہ سے اور مقتول اس لیے کہ اس کی نیت بھی مسلمان کو قتل کرنے ہی کی تھی۔)"}],[4118,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب دو مسلمان اپنی تلواروں کے ساتھ آمنے سامنے ہوں اور ان میں ایک دوسرے کو قتل کر دے تو وہ دونوں جہنم میں ہوں گے\"، عرض کیا گیا: اللہ کے رسول! یہ تو قاتل ہے، لیکن مقتول کا قصور کیا ہے؟ آپ نے فرمایا: \"اس نے اپنے(مقابل) ساتھی کو مارنا چاہا تھا\"۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ رضی اللہ تعالٰی عنہ سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جب دو مسلمان اپنی تلواریں لے کر ایک دوسرے کے مقابل آ جائیں، پھر ان میں سے ایک دوسرے کو قتل کر دے تو وہ دونوں جہنم میں جائیں گے۔‘‘ پوچھا گیا: اللہ کے رسول! قاتل کا جہنم میں جانا تو سمجھ میں آتا ہے مگر مقتول کے جہنم میں جانے کی وجہ کیا ہے؟ آپ نے فرمایا: ’’اس کا ارادہ بھی اپنے ساتھی کو قتل کرنے کا تھا۔‘‘"}],[4119,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب دو مسلمان تلواروں کے ساتھ آمنے سامنے ہوں، پھر ان میں سے ایک اپنے ساتھی کو قتل کر دے تو وہ دونوں جہنم میں ہوں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ اشعری رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جب دو مسلمان اپنی تلواریں لے کر ایک دوسرے کے مقابل آ جائیں، پھر ان میں سے کوئی دوسرے کو قتل کر دے تو وہ دونوں آگ میں جائیں گے۔‘‘ یہ روایت بھی بالکل پہلی روایت کی طرح ہے۔"}],[4120,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب دو مسلمان اپنی تلواروں کے ساتھ آمنے سامنے ہوں، ان میں سے ہر ایک دوسرے کو قتل کرنا چاہتا ہو، تو وہ دونوں جہنم میں ہوں گے\"۔ آپ سے عرض کیا گیا: اللہ کے رسول! یہ تو قاتل ہے لیکن مقتول کا کیا معاملہ ہے؟ آپ نے فرمایا: \"وہ بھی تو اپنے ساتھی کے قتل کا حریص اور خواہشمند تھا\"۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ تعالٰی عنہ سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جب دو مسلمان اپنی تلواریں لے کر آمنے سامنے آ جائیں جبکہ ان میں سے ہر ایک، دوسرے کو قتل کرنا چاہتا ہو (پھر خواہ کوئی کسی کو قتل کر دے) تو دونوں آگ میں جائیں گے۔‘‘ پوچھا گیا: اے اللہ کے رسول! قاتل تو ٹھیک ہے مگر مقتول کیوں؟ آپ نے فرمایا: ’’وہ بھی اپنے ساتھی کو قتل کرنے پر حریص تھا۔‘‘"}],[4121,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب دو مسلمان اپنی تلواروں کے ساتھ بھڑ جائیں پھر ان میں سے ایک دوسرے کو قتل کر دے تو قاتل و مقتول دونوں جہنم میں ہوں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب دو مسلمان تلواریں لے کر مقابلہ کرنے لگیں، پھر ان میں سے ایک دوسرے کو قتل کر دے تو قاتل اور مقتول دونوں آگ میں جائیں گے۔‘‘"}],[4122,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب دو مسلمان اپنی تلواروں کے ساتھ آمنے سامنے ہوں پھر ان میں سے ایک دوسرے کو قتل کر دے تو قاتل اور مقتول دونوں جہنم میں ہوں گے\"، انہوں نے کہا: اللہ کے رسول! یہ تو قاتل ہے آخر مقتول کا کیا معاملہ ہے؟ آپ نے فرمایا:\"اس نے بھی اپنے ساتھی کے قتل کا ارادہ کیا تھا\"۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جب دو مسلمان اپنی تلواریں (یا کوئی بھی اسلحہ) لے کر آمنے سامنے آ جائیں، پھر ان میں سے ایک دوسرے کو قتل کر دے تو قاتل اور مقتول دونوں آگ میں جائیں گے۔‘‘ صحابہ نے عرض کی: قاتل تو جہنم میں جائے مگر مقتول کیوں؟ آپ نے فرمایا: ’’اس نے بھی تو اپنے ساتھی کو قتل کرنے کا ارادہ کیا تھا۔‘‘"}],[4123,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب دو مسلمان اپنی تلواروں کے ساتھ بھڑ جائیں پھر ان میں سے ایک دوسرے کو قتل کر دے تو قاتل اور مقتول دونوں جہنم میں ہوں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب دو مسلمان تلواریں لے کر ایک دوسرے سے لڑنے لگیں، پھر ان میں سے ایک دوسرے کو مار دے تو قاتل اور مقتول دونوں آگ میں جائیں گے۔‘‘"}],[4124,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب دو مسلمان اپنی تلواروں کے ساتھ آمنے سامنے ہوں پھر ان میں سے ایک دوسرے کو قتل کر دے تو قاتل اور مقتول دونوں جہنم میں ہوں گے\"، ایک شخص نے کہا: اللہ کے رسول! یہ تو قاتل ہے لیکن مقتول کا کیا معاملہ ہے؟ آپ نے فرمایا:\"اس نے بھی اپنے ساتھی کے قتل کا ارادہ کیا تھا\"۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ اشعری رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب دو مسلمان تلواروں سے مسلح ہو کر ایک، دوسرے کے آمنے سامنے آ جائیں (اور لڑنے لگیں)، پھر ان میں سے ایک، دوسرے کو قتل کر دے (یا دونوں ایک دوسرے کو قتل کر دیں) تو قاتل اور مقتول دونوں آگ میں جائیں گے۔‘‘ ایک آدمی نے کہا: اے اللہ کے رسول قاتل کا جہنم میں جانا تو صحیح ہے مگر مقتول کیوں آگ میں جائے گا؟ آپ نے فرمایا ’’اس کا ارادہ بھی اپنے ساتھی کو قتل کرنے ہی کا تھا۔‘‘"}],[4125,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم میرے بعد کافر نہ ہو جانا ۱؎ کہ تم آپس میں ایک دوسرے کی گردن مارنے لگو\"۔\n§وضاحت\n۱؎: یعنی کافروں کی طرح نہ ہو جانا کہ کفریہ اعمال کرنے لگو، جیسے ایک دوسرے کو ناحق قتل کرنا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’میرے بعد کافر نہ بن جانا کہ ایک دوسرے کی گردنیں کاٹنے لگو۔‘‘","f2":"(۱) مسلمانوں سے لڑنا کافروں کا کام ہے۔ اگر مسلمان مسلمانوں سے لڑنے لگیں تو کافروں کے مشابہ ہو گئے، نیز اس سے کافروں کا مقصد پورا ہو گیا۔ انہیں لڑنے کی ضرورت ہی نہ رہی۔ جو شخص باہیم اختلافات کی بنا پر لڑائی کو جائز سمجھتا ہے، وہ حقیقتاً کافر ہے کیونکہ وہ ایک حرام کام کو حلال قرار دیتا ہے۔ اگر ویسے ہی جذبات میں آ کر لڑائی لڑنے لگا تو پھر کافر تو نہ ہو گا مگر اس کا یہ کام کافروں کے مشابہ ہو گا۔ ایسے میں وہ اگر کسی کو قتل کرے گا تو اسے قصاصاً قتل کیا جائے گا۔ (۲) کبھی کبھی غلط فہمی کی بنا پر جنگ چھڑ جاتی ہے یا شرپسند عناصر فریقین میں لڑائی بھڑکا دیتے ہیں تو اس سے فریقین کافر نہ ہوں گے جیسے جنگ جمل اور صفین میں ہوا۔ حضرت عائشہ، زبیر، طلحہ، معاویہ اور عمرو بن عاص رضی اللہ عنہم حضرت عثمان رضی اللہ تعالٰی عنہ کے ناحق قتل کا قصاص چاہتے تھے مگر قاتلین عثمان اپنی گردن بچانے کے لیے جنگ برپا کر دیتے تھے۔ حضرت علی رضی اللہ تعالٰی عنہ اس انداز کے مطالبے کو بغاوت سے تعبیر کرتے تھے اور بغاوف فرو کرنے کو سرکاری فریضہ سمجھتے تھے مگر معاملہ اتنا سادہ نہ تھا۔ غیر مسلموں کی سازشیں کافی گہری تھیں۔ فریقین میں ایسی غلط فہمیاں پیدا ہو چکی تھیں کہ نہ چاہتے ہوئے بھی ان میں لڑائی ہوتی گئی اگرچہ فریقین نیک نیت تھے۔ ان کی نیک نیتی کے لیے ان کا صحابی ہونا ہی کافی ہے۔ صحابہ عام لوگ نہیں تھے بلکہ {اُوْلٰٓئِکَ الَّذِیْنَ امْتَحَنَ اللّٰہُ قُلُوْبَہُمْ لِلتَّقْوٰی} (الحجرات: ۳۹:۳) وہ اللہ تعالیٰ کے منتخب شدہ افراد تھے، اس لیے ان کے بارے میں انتہائی اچھا گمان رکھنا ضروری ہے، ورنہ اپنے ایمان کا خطرہ ہے۔ وہ لوگ یقینا جنتی ہیں۔ ان کے لیے رسول اللہ صلی اللہ علیہ وسلم کی نام بنام بشارتیں موجود ہیں۔ ان سے بدگمانی رکھنے والا ایمان سے بے بہرہ ہے۔ رضی اللہ عنہم و ارضاہم۔ (۳) ’’کافر نہ بن جانا‘‘ کافر کے ایک معنی ناشکرا بھی ہیں۔ آپس میں لڑنا نعمت ایمان کی ناشکری ہے۔"}],[4126,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ میرے بعد کافر نہ ہو جانا کہ تم آپس میں ایک دوسرے کی گردن مارنے لگو، آدمی کو نہ اس کے باپ کے گناہ کی وجہ سے پکڑا جائے گا اور نہ ہی اس کے بھائی کے گناہ کی وجہ سے\"۔ ابوعبدالرحمٰن نسائی کہتے ہیں: یہ غلط ہے (کہ یہ متصل ہے) صحیح یہ ہے کہ یہ مرسل ہے ۱؎۔\n§وضاحت\n۱؎: یعنی: جس سند میں مسروق ہیں اس سند سے اس روایت کا مرسل ہونا ہی صواب ہے، مسروق کے واسطے سے جس نے اس روایت کو متصل کر دیا ہے اس نے غلطی کی ہے، یہ مطلب نہیں ہے کہ سرے سے یہ حدیث ہی مرسل ہے، دیگر محدثین کی سندیں متصل ہیں۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میرے بعد کافر نہ بن جانا کہ ایک دوسرے کی گردنیں کاٹنے لگ جائو۔ کسی شخص کو اس کے باپ یا بھائی کے جرم میں نہ پکڑا جائے گا۔‘‘\nامام ابو عبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ (مذکورہ روایت متصل بیان کرنا) غلط ہے۔ درست (یہ ہے کہ یہ) روایت مرسل ہے۔","f2":"(۱) امام نسائی رحمہ اللہ کے قول کی وضاحت کچھ اس طرح سے ہے کہ مذکورہ روایت بعض رواۃ نے متصل بیان کی ہے اور بعض نے مرسل۔ امام نسائی رحمہ اللہ فرماتے ہیں کہ اس روایت کا متصل ہونا درست نہیں بلکہ درست بات یہ ہے کہ یہ روایت مرسل ہی ہے، اس لیے کہ متصل بیان کرنے والے راوی شریک اور ابوبکر بن عیاش ہیں اور وہ دونوں اعمش سے بیان کرتے ہیں۔ اعمش سے یہ روایت ابوبکر بن عیاش اور شریک کے علاوہ ابو معاویہ اور یعلیٰ نے بھی بیان کی ہے۔ ایک تو اس لیے کہ شریک کثیر الخطاء (بہت غلطیاں کرنے والا) راوی ہے، دوسرے یہ کہ اس نے اور ابوبکر بن عیاش نے ابومعاویہ کی مخالفت کی ہے، حالانکہ ابو معاویہ، اعمش کے تمام شاگردوں میں سے اثبت راوی ہے، سوائے سفیان ثوری کے۔ ابو معاویہ نے اس روایت کو مرسل بیان کیا ہے۔ مزید برآں یہ بھی کہ یعلیٰ بن عبید نے (اس کے مرسل بیان کرنے میں) ابو معاویہ کی متابعت بھی کی ہے۔ (۲) ’’کافر نہ بن جانا‘‘ یہ معنی بھی کیے گئے ہیں کہ تم میرے بعد مرتد ہو کر کافر نہ بن جانا ورنہ تمہاری حالت وہی ہو جائے گی جو اسلام سے پہلے تھی کہ تم ایک دوسرے کی گردنیں کاٹنے لگ جائو گے اور آپس میں قتل و قتال کا دور دورہ ہو گا۔ و اللہ اعلم۔ (۳) ’’نہ پکڑا جائے گا‘‘ یہ اسلام کا سنہری اصول ہے کہ ہر شخص اپنے اعمال کا جواب دہ خود ہے۔ کسی کے جرم میں اس کے بھائی، باپ یا بیٹے کو نہیں پکڑا جا سکتا الا یہ کہ ان کا اس جرم میں دخل ثابت ہو۔ جاہلیت میں یہ عام دستور تھا کہ قاتل کی بجائے اس کے کسی رشتے دار بلکہ اس کے قبیلے کے کسی بھی فرد کا قتل جائز سمجھا جاتا۔ ایک شخص کے جرم کی وجہ سے اس کا پورا قبیلہ مجرم بن جاتا تھا، اس لیے قتل و قتال عام تھا۔ اور ایک قتل پر بسا اوقات سینکڑوں قتل ہو جاتے تھے۔ اسلام نے اس بے اصولی کی نفی اور مذمت فرمائی۔"}],[4127,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میرے بعد کافر نہ ہو جانا کہ آپس میں ایک دوسرے کی گردنیں مارو، کوئی شخص اپنے باپ کے گناہ کی وجہ سے نہ پکڑا جائے گا اور نہ ہی اس کے بھائی کے گناہ کی وجہ سے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میرے بعد کافر نہ بن جانا کہ ایک دوسرے کی گردنیں اتارنے لگو۔ کسی آدمی کو اس کے باپ یا بھائی کے جرم میں نہیں پکڑا جا سکتا۔‘‘","f2":"البتہ قتل خطا میں قاتل کے نسبی رشتے دار بلکہ پورا قبیلہ اس کے ساتھ مل کر دیت ادا کریں گے۔ یہ اس روایت کے خالف نہیں کیونکہ خَطَأ قتل جرم نہیں اور مقتول کی دیت بھرنا رشتے داروں کے لیے سزا نہیں بلکہ یہ تو صرف اس شخص کے ساتھ تعاون ہے جس سے بلاقصد و ارادہ قتل صادر ہو گیا۔ اور مسلمان مقتول کا خون رائیگاں نہیں کیا جا سکتا۔ ہاں، اگر قاتل نے جان بوجھ کر قتل کیا ہو تو اس کا قصاص اسی سے لے لیا جائے گا اور اگر دیت پر معاملہ طے ہو جائے تو وہ دیت بھی خود ہی ادا کرے گا۔ رشتے داروں پر کوئی ذمہ داری عائد نہ ہو گی کیونکہ وہ مجرم ہے اور مجرم سے تعاون کیسا؟"}],[4128,"مسروق کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں تمہیں اس طرح نہ پاؤں کہ تم میرے بعد کافر ہو جاؤ کہ تم ایک دوسرے کی گردنیں مارو، آدمی سے نہ اس کے باپ کے جرم و گناہ کا مواخذہ ہو گا اور نہ ہی اس کے بھائی کے جرم و گناہ کا\"۔ یہی صحیح ہے ۱؎۔\n§وضاحت\n۱؎: یعنی مسروق کی سند سے مرسل روایت ہی صحیح ہے۔","الألباني: صحيح",{"u2":"حضرت مسروق سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں تمہیں اس حال میں نہ پائوں کہ تم میرے بعد کافر بن جائو اور ایک دوسرے کی گردنیں کاٹو۔ کسی شخص کو اس کے باپ یا بھائی کے جرم میں گرفتار نہ کیا جائے گا۔‘‘\nیہ (مرسل روایت، موصول کی نسبت) درست ہے۔"}],[4129,"مسروق کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میرے بعد کافر نہ ہو جانا\"۔ (یہ حدیث) مرسل ہے۔","الألباني: صحيح",{"u2":"حضرت مسروق سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میرے بعد کافر نہ بن جائو۔‘‘ (یہ روایت) مرسل ہے (اور یہی صحیح ہے)۔"}],[4130,"ابوبکرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم میرے بعد کافر نہ ہو جانا کہ آپس میں ایک دوسرے کی گردنیں مارنے لگو\"۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میرے بعد گمراہ نہ بن جانا کہ ایک دوسرے کی گردنیں کاٹنے لگو۔‘‘"}],[4131,"جریر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃالوداع میں لوگوں کو خاموش کیا اور فرمایا: \"میرے بعد تم کافر نہ ہو جانا کہ تم ایک دوسرے کی گردنیں مارنے لگو\"۔","الألباني: صحيح",{"u2":"حضرت جریر رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع کے دن لوگوں کو چپ کرایا اور فرمایا: ’’میرے بعد کافر نہ بن جانا کہ ایک دوسرے کی گردنیں اتارنے لگو۔‘‘"}],[4132,"جریر بن عبداللہ رضی اللہ عنہ کہتے ہیں کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگوں سے خاموش رہنے کو کہو\"، پھر فرمایا: \"اس کے بعد جب میں تمہیں دیکھوں (قیامت کے روز) تو ایسا نہ پاؤں کہ تم کافر ہو جاؤ اور ایک دوسرے کی گردنیں مارو\"۔","الألباني: صحيح",{"u2":"حضرت جریر بن عبداللہ بجلی رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ’’لوگوں کو چپ کرائو۔‘‘ پھر آپ نے فرمایا: ’’(اے لوگو!) تمہیں مسلمان دیکھنے کے بعد میں تمہیں اس حال میں نہ پائوں کہ تم میرے بعد کافر بن جائو اور ایک دوسرے کی گردنیں کاٹنے لگو۔‘‘","f2":"’’میں تمہیں نہ پائو‘‘ یعنی قیامت کے دن کیونکہ اس وقت سب رازکھل جائیں گے اور امت کے اعمال رسول اللہ صلی اللہ علیہ وسلم پر ظاہر ہو جائیں گے، یا جب تم مرنے کے بعد میرے پاس آئو گے تو تمہاری یہ حالت نہیں ہونی چاہیے۔ یہ کلام ظاہراً تو اپنے آپ سے خطاب ہے مگر حقیقتاً مخاطب کو سمجھانا مقصود ہے کہ تمہاری یہ حالت نہیں ہونی چاہیے۔ و اللہ اعلم"}],[4133,"یزید بن ہرمز سے روایت ہے کہ نجدہ حروری جب عبداللہ بن زبیر کے عہد میں شورش و ہنگامہ کے ایام میں (حج کے لیے) نکلا ۲؎ تو اس نے ابن عباس رضی اللہ عنہما کے پاس ایک شخص کو بھیجا کہ وہ ان سے معلوم کرے کہ (مال غنیمت میں سے) ذی القربی کا حصہ (اب) کس کو ملنا چاہیئے ۳؎، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم سے قربت کے سبب وہ ہمارا ہے، رسول اللہ صلی اللہ علیہ وسلم نے اسے انہیں قرابت والوں میں تقسیم کیا تھا، اور عمر رضی اللہ عنہ نے ہمیں ہمارے حق سے کچھ کم حصہ دیا تھا تو ہم نے اسے قبول نہیں کیا، اور جو بات انہوں نے جواز میں پیش کی وہ یہ تھی کہ وہ اس کے ذریعہ (رسول اللہ صلی اللہ علیہ وسلم کے قرابت داروں کا) نکاح کرانے والوں کی مدد کریں گے، اور ان کے قرض داروں کا قرض ادا کیا جائے گا اور ان کے فقراء و مساکین کو دیا جائے گا، اور اس سے زائد دینے سے انکار کر دیا۔\n§وضاحت\n۱؎: مال فئی اس مال کو کہتے ہیں جو مسلمانوں کو کفار سے جنگ و جدال کئے بغیر حاصل ہو، لیکن مؤلف نے اس میں فیٔ اور غنیمت دونوں سے متعلق احادیث ذکر کی ہیں، اور پہلی حدیث میں فیٔ کے ساتھ ساتھ \" غنیمت \" میں سے بھی رسول اللہ صلی اللہ علیہ وسلم کے ذوی القربی کے حصے کی بابت سوال کیا گیا ہے۔۲؎: یہ اس وقت کی بات ہے جب کہ حجاج نے مکہ پر چڑھائی کر کے عبداللہ بن زبیر رضی اللہ عنہما کو قتل کیا تھا۔ ۳؎: رسول اللہ صلی اللہ علیہ وسلم نے مال غنیمت سے ذوی القربی کا حصہ اپنے رشتہ داروں میں تقسیم کیا تھا، آپ کی وفات کے بعد سوال یہ پیدا ہوا کہ یہ حصہ \" رسول اللہ صلی اللہ علیہ وسلم کے رشتہ داروں کا تھا یا امام وقت کے رشتہ داروں کا ؟ \" ابن عباس رضی اللہ عنہما کا خیال تھا :(نیز قرآن کا سیاق بھی اسی کی تائید کرتا ہے ) کہ یہ رسول اللہ صلی اللہ علیہ وسلم کے رشتہ داروں کا تھا اور اب بھی ہے اس لیے ہمیں ملنا چاہیئے، جب کہ عمر رضی اللہ عنہ نے آپ کے رشتہ داروں کے ہاتھ میں نہ دے کر خود ہی آپ کے رشتہ داروں کی ضروریات میں خرچ کیا، ابوبکر اور عمر رضی اللہ عنہما کا موقف بھی یہی تھا کہ امام وقت ہی اس خمس :(غنیمت کے پانچویں حصہ ) کو رسول اللہ صلی اللہ علیہ وسلم کے رشتہ داروں میں خرچ کرے گا۔","الألباني: صحيح",{"u2":"حضرت زید بن ہرمز سے روایت ہے نجدہ حروری (خارجی) جب حضرت عبداللہ بن زبیر رضی اللہ عنہ کی شورش کے دوران میں آیا تو اس نے حضرت ابن عباس رضی اللہ عنہ کو پیغام نامہ بھیجا اور پوچھا کہ آپ کی رائے میں (خمس میں سے) قرابت داروں کا حصہ کسے ملے گا؟ انہوں نے فرمایا: ہمیں، یعنی رسول اللہ صلی اللہ علیہ وسلم کے رشتے داروں کو۔ رسول اللہ صلی اللہ علیہ وسلم نے یہ حصہ ان (بنی ہاشم اور بنی مطلب) کے لیے تقسیم کیا۔ حضرت عمر رضی اللہ تعالٰی عنہ نے بھی ہمیں (خمس میں سے) کچھ مال پیش کیا جسے ہم نے اپنے حق سے کم سمجھا تو ہم نے اسے قبول کرنے سے انکار کر دیا۔ حضرت عمر رضی اللہ تعالٰی عنہ نے انہیں پیش کش کی تھی کہ وہ ان میں سے نکاح کرنے والے کی مدد کریں گے۔ ان کے مقروض کا قرض ادا کریں گے اور ان سے محتاج لوگوں کو عطیات دیں گے۔ اس سے زائد دینے سے انہوں نے انکار کر دیا۔","f2":"(۱) باب کے ساتھ حدیث کی مناسبت بالکل واضح ہے کہ اس میں مال فے کی تقسیم کا مسئلہ بیان کیا گیا ہے۔ (۲) اس حدیث سے یہ مسئلہ بھی ثابت ہوتا ہے کہ خط کتابت کے ذریعے سے علم حاصل کیا جا سکتا ہے جیسا کہ نجدہ حروری نے حضرت عبداللہ بن عباس رضی اللہ عنہ کی طرف ایک تحریر لکھ کر چند ایک مسائل کا جواب معلوم کیا تھا۔ صحیح مسلم میں اس بات کی صراحت ہے کہ اس نے پانچ سوالوں کا واب طلب کیا تھا۔ دیکھئے: (صحیح مسلم، الجہاد، باب النساء الغازیات یرضخ لہن و لا یسہم…، حدیث: ۱۸۱۲) (۳) مذکورہ حدیث سے یہ بھی معلوم ہوتا ہے کہ جب کوئی مصلحت ہو یا کسی قسم کے فساد کا خطرہ ہو تو عالم شخص کو اہل بدعت کو بھی فتویٰ دے دینا چاہیے جیسا کہ حضرت عبداللہ بن عباس رضی اللہ عنہ نے نجدہ حروری کو تحریری جواب لکھ بھیجا تھا۔ (۴) ’’حروری‘‘ یہ نسبت ہے بستی ’’حرورائ‘‘ کی طرف۔ یہاں خارجیوں کا اولین اجتماع ہوا تھا۔ اس نسبت سے ہر خارجی کو حروری کہا جاتا ہے، چاہے وہ حروراء بستی سے تعلق نہ بھی رکھتا ہو۔ اس حوالے سے دیکھئے: حدیث: ۸،۷،۴۱۰۷) (۵) ’’قرابت داروں کا حصہ‘‘ قرآن مجید میں غنیمت کے علاوہ خمس کے مصارف میں ’’قرابت داروں‘‘ کا ذکر ہے۔ اس کے تعین میں اختلاف ہے۔ مشہور بات تو یہی ہے کہ اس سے رسول اللہ صلی اللہ علیہ وسلم کے رشتے دار مراد ہیں جیسا کہ حضرت ابن عباس رضی اللہ عنہ نے فرمای۔ امام شافعی اور دیگر اکثر اہل علم کے نزدیک قرابت داروں سے مراد بنو ہاشم اور بنو مطلب ہیں۔ دوسرا قول یہ ہے کہ حاکم وقت کے رشتے دار مراد ہیں۔ رسول اللہ صلی اللہ علیہ وسلم اپنے دور میں حاکم بھی تھے۔ اس لحاظ سے آپ کے رشتہ دار مَصْرَفْ تھے۔ یہ نہیں کہ اب بھی (آپ کی وفات سے قیامت تک) آل رسول خمس کا مصرف ہیں۔ یہ قول معفول ہے مگر کہا جا سکتا ہے کہ چونکہ آل رسول کے لیے زکاۃ حرام ہے، خواہ غریب ہی ہوں، اس لیے زکاۃ کے عوض ان کا حصہ خمس میں رکھ دیا گیا لیکن اس صورت میں صرف زکاۃ کے مستحق آل رسول ہی خمس کا مصرف ہوں گے نہ کہ عام اہل بیت۔ معلوم ہوتا ہے حضرت عمر رضی اللہ تعالٰی عنہ کا یہی موقف تھا جیسا کہ مندرجہ بالا روایت کے الفاظ سے ظاہر ہو رہا ہے اور یہی بات درست معلوم ہوتی ہے۔ باقی رہے حاکم وقت اور اس کے رشتہ دار تو وہ کوئی حصہ دار نہیں بلکہ آج کل کے رواج کے مطابق حاکم وقت کی مناسب تنخواہ مقرر کی جائے گی جیسا کہ خلفائے راشدین کے دور میں ہوا۔ اس تنخواہ کو وہ خود خرچ کرے گا او رشتے داروں کو بھی اس سے دے گا جس طرح رشتے داروں میں عام لین دین ہوتا ہے۔ ان کی کوئی خصوصی حیثیت نہیں۔ (۶) ’’حق سے کم سمجھا‘‘ حضرت ابن عباس رضی اللہ عنہ اور دیگر اہل بیت کا خیال تھا کہ ہمارا بیت المال میں خصوصی حق ہے۔ بعض کے نزدیک پورا خمس اور بعض کے نزدیک خمس کا خمس (خمس سے مراد مال غنیمت کا پانچواں حصہ ہے جو بیت المال میں جمع ہوتا ہے) جبکہ حضرت عمر رضی اللہ تعالٰی عنہ کا خیال تھا کہ اہل بیت میں سے فقیر اور حاجت مند لوگ زکاۃ کی بجائے بیت المال سے ضرورت کے مطابق مال لے سکتے ہیں۔ اہل بیت کا کوئی مستقل حصہ مقرر نہیں، البتہ حاکم عام شہریوں کی طرح اہل بیت کو بھی عطیات دے سکتا ہے بلکہ ان کو زیادہ بھی دے سکتا ہے کیونکہ ان کی شان بلند ہے، جیسے حضرت عمر رضی اللہ تعالٰی عنہ نے صدقہ النبی(صلی اللہ علیہ وسلم) والی زمین عارضی طور پر حضرت عباس اور حضرت علی رضی اللہ تعالٰی عنہ کی زیر نگرانی دے دی تھی کہ وہ اس کی آمدن سے اپنی اور دیگر اہل بیت کی ضروریات پوری کریں۔ باقی آمدن بیت المال کی ہو گی اور زمین بھی حکومت ہی کی رہے گی۔(۷) آج کل تو یہ مسئلہ خود بخود طے ہو چکا ہے، نہ مال غنیمت آتا ہے اور نہ خمس ہی کی صورت بنتی ہے۔ صرف بیت المال، یعنی سرکاری خزانہ ہوتا ہے جس سے حاجت مند اور فقیر لوگوں کی حاجات پوری کی جائیں گی۔ وہ اہل بیت سے ہوں یا عام مسلمان۔ یہی حضرت عمر رضی اللہ تعالٰی عنہ کی رائے تھی اور یہی درست ہے۔ رَضِیَ اللّٰہُ عَنْہُ وَ اَرْضَاہُ۔"}],[4134,"یزید بن ہرمز کہتے ہیں کہ نجدہ نے ابن عباس رضی اللہ عنہما کو یہ سوال لکھا کہ (نبی اکرم صلی اللہ علیہ وسلم کے) رشتہ داروں کا حصہ (آپ کے بعد) کس کا ہے؟ نجدہ کے پاس ابن عباس رضی اللہ عنہما کا جواب میں نے ہی لکھ کر بھیجا، میں نے لکھا کہ تم نے یہ سوال مجھے لکھ کر بھیجا ہے کہ (نبی اکرم صلی اللہ علیہ وسلم کے) رشتہ داروں کا حصہ کس کا ہے؟ وہ ہم اہل بیت کا ہے۔ البتہ عمر رضی اللہ عنہ نے ہم سے کہا کہ وہ اس مال سے ہماری بیواؤں کا نکاح کرائیں گے، اس کو ہمارے فقراء و مساکین پر خرچ کریں گے اور ہمارے قرض داروں کا قرض ادا کریں گے، لیکن ہم اصرار کرتے رہے کہ وہ ہم ہی کو دیا جائے، تو انہوں نے اس سے انکار کیا، لہٰذا ہم نے اسے انہیں پر چھوڑ دیا۔","الألباني: صحيح لغيره",{"u2":"حضرت یزید بن ہرمز سے منقول ہے کہ نجدہ حروری نے حضرت ابن عباس رضی اللہ عنہ سے تحریری طور پر پوچھا کہ ’’قرابت داری‘‘ کا حصہ کس کو ملے گا؟ یزید بن ہرمز نے کہا کہ حضرت ابن عباس رضی اللہ عنہ کی طرف سے نجدہ کو جواب میں نے تحریر کیا تھا۔ میں نے لکھا تھا کہ تم نے مجھ سے ’’قرابت داروں‘‘ والے کے حصے کے متعلق پوچھا ہے کہ کس کو ملے گا؟ یہ حصہ دراصل ہم اہل بیت کا ہے۔ حضرت عمر رضی اللہ تعالٰی عنہ نے ہمیں یہ پیش کش کی تھی کہ اس حصے میں سے میں، تم میں سے غیر شادی شدہ کی شادی کروں گا اور فقیر کو عطیہ دوں گا اور مقروض کا قرض ادا کروں گا، لیکن ہم نے (اسے قبول کرنے سے) انکار کر دیا الا یہ کہ وہ ہمارا خمس پورے کا پورا ہمیں دے دیں۔ حضرت عمر رضی اللہ تعالٰی عنہ نے اس سے انکار کیا تو ہم نے یہ انہی پر چھوڑ دیا (اور تھوڑا لینے سے انکار کر دیا)۔"}],[4135,"اوزاعی کہتے ہیں کہ عمر بن عبدالعزیز نے عمر بن ولید کو ایک خط لکھا: تمہارے باپ نے تقسیم کر کے پورا خمس (پانچواں حصہ) تمہیں دے دیا، حالانکہ تمہارے باپ کا حصہ ایک عام مسلمان کے حصے کی طرح ہے، اس میں اللہ کا حق ہے اور رسول، ذی القربی، یتیموں، مسکینوں اور مسافروں کا حق ہے۔ تو قیامت کے دن تمہارے باپ سے جھگڑنے والے اور دعوے دار کس قدر زیادہ ہوں گے، اور جس شخص پر دعوے دار اتنی کثرت سے ہوں گے وہ کیسے نجات پائے گا؟ اور جو تم نے باجے اور بانسری کو رواج دیا ہے تو یہ سب اسلام میں بدعت ہیں، میں نے ارادہ کیا تھا کہ میں تمہارے پاس ایسے شخص کو بھیجوں جو تمہارے بڑے بڑے اور برے لٹکتے بالوں کو کاٹ ڈالے ۱؎۔\n§وضاحت\n۱؎: جمہ ایسے بالوں کو کہتے ہیں جو گردن تک لٹکتے ہیں، اس طرح کا بال رکھنا مکروہ نہیں ہے، عمر بن عبدالعزیز نے اس لیے ایسا کہا کیونکہ عمر بن الولید اپنے انہیں بالوں کی وجہ سے گھمنڈ میں مبتلا رہتا تھا۔","الألباني: صحيح الإسناد مقطوع",{"u2":"حضرت اوزاعی سے روایت ہے کہ حضرت عمر بن عبدالعزیز رحمہ اللہ نے عمر بن ولید کو لکھا کہ تیرے باپ (ولید بن عبدالملک بن مروان) نے تجھے پورا خمس دے دیا تھا، حالانکہ درحقیقت تیرے باپ کا حصہ ایک عام مسلمان کے حصے کے برابر تھا۔ اس (خمس) میں تو اللہ تعالیٰ کا حق تھا، رسول اللہ صلی اللہ علیہ وسلم کا، رسول اللہ صلی اللہ علیہ وسلم کے قرابت داروں کا، یتامی و مساکین اور مسافروں کا حق تھا۔ قیامت کے دن تیرے باپ سے جھگڑا کرنے والے لوگ کس قدر ہوں گے! وہ شخص کیسے نجات پائے گا جس سے حق وصول کرنے والے اس قدر زیادہ ہوں؟ پھر تیرا علانیہ آلات موسیقی استعمال کرنا اور بنسری بجانا اسلام کے اندر ایک بدعت ہے۔ میرا ارادہ ہے کہ میں تیرے پاس ایسا شخص بھیجوں جو تیرے لمبے لمبے قبیح بالوں کو کاٹ دے۔ (یا تیرے لمبے قبیح بالوں سے پکڑ کر تجھے گھسیٹ لائے۔)","f2":"(۱) حضرت عمر بن عبدالعزیز رحمہ اللہ کا مسلک بھی یہی ہے کہ خمس صرف ان کا حق ہے جن کا بیان اللہ تعالیٰ نے قرآن مقدس میں فرمایا ہے اور یہ انہی پر خرچ ہو گا۔ اس میں ان کے علاوہ کوئی دوسرا شریک نہیں ہو سکتا، چنانچہ مطلق العنان حکمران اور ملوک و سلاطین اس میں جو من مانے تصرف کرتے ہیں وہ صریح ظلم اور لوگوں کا مال باطل طریقے سے کھانا ہے، لہٰذا ایسے شخص کی نجات ایک سوالیہ نشان ہی ہے۔ (۲) عمر بن ولید خلیفہ ولید بن عبدالملک کا بیٹا تھا۔ یہ شہزادے محلوں میں اور سونے کا چمچہ منہ میں لے کر پیدا ہوئے تھے۔ عیش و عشرت ان کی گھٹی میں پڑ چکی تھی، اس لیے اس کے قبیح کاموں پر اس کو ڈانٹ پلائی۔ رَحِمَہُ اللّٰہُ رَحْمَۃً وَّاسِعَۃً۔ (۳) حضرت عمر بن عبدالعزیز رحمہ اللہ بھی اگرچہ شہزادے ہی تھے مگر اللہ تعالیٰ نے ان کی کایا پلٹ دی تھی۔ خلیفہ بننے کے بعد تو وہ ’’حضرت عمر رضی اللہ تعالٰی عنہ ‘‘ ہی بن گئے تھے حتی کہ تاریخ نے ان کو ’’عمر ثانی‘‘ کا لقب دیا اگرچہ ان کو صرف اڑھائی سال حکومت کا موقع ملا اور وہ صرف سینتیس (۳۷) سال کی عمر میں اپنے مولا کو پیارے ہو گئے۔ صحابی نہ ہونے کے باوجود ان کے لیے رَضِیَ اللّٰہُ عَنْہُ وَ اَرْضَاہُ کہنے کو جی کرتا ہے۔ (۴) ’’لمبے لمبے قبیح بال‘‘ لمبے بال رکھنا منع نہیں۔ ممکن ہے اس نے لمبے بالوں کو تکبر کا ذریعہ بنا لای ہو۔ اور لمبے بال اس کے لیے یا دوسروں کے لیے فتنہ بن گئے ہوں جیسا کہ حضرت عمر رضی اللہ تعالٰی عنہ نے ایک شخص کا سر منڈا دیا تھا جس کی زلفیں دوسروں کے لیے فتنے کا باعث تھیں۔ (تاریخ دمشق الکبیر: ۳۳/۱۷، ۲۰) اس صورت میں یہ انتظامی مسئلہ بن جاتا ہے جو قابل گرفت ہوتا ہے، نیز لڑکوں اور لڑکیوں کا حد سے زیادہ زیب و زینت کی طرف توجہ دینا ہلاکت کا باعث ہے۔"}],[4136,"جبیر بن مطعم رضی اللہ عنہ بیان کرتے ہیں کہ وہ اور عثمان بن عفان رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پاس غزوہ حنین کے اس خمس ۱؎ کے سلسلے میں آپ سے گفتگو کرنے آئے جسے آپ نے بنی ہاشم اور بنی مطلب بن عبد مناف کے درمیان تقسیم کر دیا تھا، انہوں نے کہا کہ اللہ کے رسول! آپ نے ہمارے بھائی بنی مطلب بن عبد مناف میں مال فیٔ بانٹ دیا اور ہمیں کچھ نہ دیا، حالانکہ ہمارا رشتہ انہی لوگوں کے رشتہ کی طرح ہے، رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا:\"میں تو ہاشم اور مطلب کو ایک ہی سمجھتا ہوں\"، لیکن رسول اللہ صلی اللہ علیہ وسلم نے اس خمس میں سے بنی عبد شمس کو کچھ نہ دیا اور نہ ہی بنی نوفل کو جیسا کہ بنی ہاشم اور بنی مطلب کو دیا ۲؎۔\n§وضاحت\n۱؎: دونوں اس خمس کے بارے میں بات چیت کرنے آئے تھے جو ذوی القربی کا حصہ ہے۔ ۲؎: جبیر بن مطعم اور عثمان رضی اللہ عنہما کو اعتراض بنو ہاشم کو دینے پر نہیں تھا کیونکہ نبی اکرم صلی اللہ علیہ وسلم سے ان کا تعلق سب کو معلوم تھا، انہیں اعتراض بنو مطلب کو دے کر بنو عبد مناف کو نہ دینے پر تھا کہ بنو ہاشم کے سوا سب سے آپ صلی اللہ علیہ وسلم سے قرابت برابر تھی تو ایک کو دینا اور دوسرے کو نہ دینا ؟ اور آپ صلی اللہ علیہ وسلم کے جواب کا حاصل یہ تھا کہ بنو مطلب نے بھی بنو ہاشم کی طرح آپ کا زمانۂ جاہلیت میں بھی ساتھ دیا تھا، جبکہ بنو عبد مناف نے دشمن کا رول ادا کیا تھا۔ :(دیکھئیے اگلی حدیث )","الألباني: صحيح",{"u2":"حضرت جبیر بن مطعم رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں اور حضرت عثمان بن عفان رضی اللہ تعالٰی عنہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ ہمارا مقصد آپ سے غزوۂ حنین کی غنیمت بنو ہاشم اور بنو مطلب میں تقسیم کرنے کے بارے میں بات چیت کرنا تھا۔ ہم نے کہا: اے اللہ کے رسول! آپ نے ہمارے بھائیوں بن مطلب بن عبدمناف کو (خمس میں سے) حصہ دیا مگر ہمیں کچھ نہیں دیا جبکہ آپ سے ہماری ان کی رشتے داری ایک جیسی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمای: ’’میں تو بنو ہاشم اور بنو مطلب کو ایک ہی چیز سمجھتا ہوں۔‘‘ حضرت جبیر بن مطعم رضی اللہ تعالٰی عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے بنو عبد شمس اور بنو نوفل کو اس خمس میں سے کچھ نہیں دیا جیسے آپ نے بنو ہاشم اور بنو مطلب کو حصہ دیا۔","f2":"آپ کے جد امجد عبدمناف کے چار بیٹے تھے: ہاشم، مطلب، عبد شمس اور نوفل۔ رسول اللہ صلی اللہ علیہ وسلم ہاشم کی نسل سے تھے۔ مطلب، عبد شمس اور نوفل کی اولاد آپ کے چچا زاد تھے۔ غزوۂ حنین میں بہت زیادہ مال غنیمت حاصل ہوا۔ اس کے خمس کی مقدار بھی بہت زیادہ تھی۔ آپ نے اس سے بڑے بڑے عطیات دئیے۔ اپنے رشتہ داروں میں سے آپ نے اپنے خاندان بنو ہاشم اور اپنے چچا زاد بنو مطلب کے لوگوں کو عطیات دئیے مگر بنو عبد شمس اور بنو نوفل کو کچھ نہ دیا، حالانکہ وہ بھی آپ چچا زاد تھے۔ حضرت عثمان رضی اللہ تعالٰی عنہ بنو عبد شمس میں سے تھے اور حضرت جبیر بن مطعم بنو نوفل میں سے تھے۔ وہ دونوں صورت حاصل کی وضاحت کے لیے آپ کی خدمت میں حاضر ہوئے او عرص کی کہ بنو ہاشم تو آپ کا خاندان ہے ان کو حصہ دینا بجا مگر بنو مطلب اور ہم آپ کے برابر کے رشتہ دار ہیں۔ بنو مطلب کو دینا اور ہمیں نہ دینا سمجھ میں نہیں آتا۔ آپ نے فرمایا کہ بنو ہاشم اور بنو مطلب ایک ہی ہیں۔ چونکہ مکہ مکرمہ میں جب رسول اللہ صلی اللہ علیہ وسلم ابتلاء کا شکار تھے تو بنو ہاشم کے ساتھ ساتھ بنو مطلب نے بھی آپ کی بھرپور مدد کی تھی لیکن بنو عبد شمس اور بنو نوفل مجموعی طور پر آپ سے لاتعلق رہے اور آپ کا ساتھ نہ دیا، اس لیے آپ نے عطیات دیتے وقت بنو مطلب کو اپنے ساتھ رکھا اور بنو نوفل اور بنو عبد شمس کو الگ رکھا۔ اور آپ اس سلسلے میں حق بجانب تھے۔ اس حدیث کو یہاں ذکر کرنے سے امام صاحب رحمہ اللہ کا مقصد یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے رشتے داروں کو خمس میں سے دیا۔ معلوم ہوا آپ کے رشتہ داروں کا خمس میں حصہ ہے لیکن حل طلب مسئلہ یہ ہے کہ کیا اب بھی اہل بیت کا یہ حق قائم ہے اور کیا پورا خمس ان کا ہے؟ بحث گزر چکی ہے۔ (دیکھئے، حدیث: ۴۱۳۸)"}],[4137,"جبیر بن مطعم رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے ذی القربی کا حصہ بنی ہاشم اور بنی مطلب میں تقسیم کیا تو میں اور عثمان بن عفان رضی اللہ عنہ آپ کے پاس آئے، ہم نے عرض کیا: اللہ کے رسول! یہ بنی ہاشم ہیں، آپ کے مقام کی وجہ سے ان کی فضیلت کا انکار نہیں کیا جا سکتا کہ اللہ تعالی نے اس مرتبے کے ساتھ آپ کو ان میں سے بنایا ہے، لیکن بنی مطلب کے بارے میں کیا خیال ہے؟ آپ نے انہیں دیا اور ہمیں نہیں دیا۔ حالانکہ آپ کے لیے ہم اور وہ ایک ہی درجے کے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"انہوں نے مجھے نہ زمانہ جاہلیت میں چھوڑا اور نہ اسلام میں، بنو ہاشم اور بنو مطلب تو ایک ہی چیز ہیں\"، اور آپ نے اپنے ہاتھوں کی انگلیاں ایک دوسرے کے اندر ڈالیں۔","الألباني: حسن صحيح",{"u2":"حضرت جبیر بن مطعم رضی اللہ تعالٰی عنہ سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے قرابت داری کا حصہ بنوہاشم اور بنو مطلب میں تقسیم فرما دیا تو میں اور حضرت عثمان بن عفان رضی اللہ تعالٰی عنہ آپ کی خدمت میں حاضر ہوئے اور ہم نے عرض کی: اے اللہ کے رسول! بنو ہاشم کی فضیلت کا تو ہم انکار نہیں کرتے کیونکہ وہ آپ کا خاندان ہے، اللہ تعالیٰ نے آپ کو ان میں سے بنایا ہے لیکن بنو مطلب کو آپ نے دیا اور ہمیں نہیں دیا، حالانکہ درحقیقت آپ سے ہمارا اور ان کا تعلق ایک جیسا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ دور جاہلیت میں بھی مجھ سے جدا نہیں رہے اور اسلام میں بھی ہمارے ساتھ رہے، لہٰذا بنوہاشم اور بنو مطلب ایک چیز ہیں۔‘‘ (یہ فرماتے ہوئے) آپ نے اپنے دونوں ہاتھوں کی انگلیوں کو ایک دوسرے میں پھنسایا۔"}],[4138,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ غزوہ حنین کے دن رسول اللہ صلی اللہ علیہ وسلم نے اونٹ کی دم کا بال (ہاتھ میں) لے کر فرمایا: \"لوگو! جو اللہ تمہیں مال فیٔ کے طور پر دیتا ہے اس میں سے میرے لیے خمس (پانچواں حصہ) کے سوا اس کی مقدار کے برابر بھی حلال نہیں ہے، اور وہ خمس بھی تم ہی پر لوٹایا جاتا ہے\"۔","الألباني: حسن صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے غزوۂ حنین کے دن ایک اونٹ کے پہلو سے اون کا ایک بال لیا اور فرمایا: ’’اے لوگو! اللہ تعالیٰ نے جو کچھ تمہیں عطا فرمایا ہے، اس میں سے میرے لیے خمس کے علاوہ اتنا بھی جائز نہیں اور خمس بھی پھر تم پر ہی لوٹا دیا جاتا ہے۔\nابو عبدالرحمن (امام نسائی رحمہ اللہ) بیان کرتے ہیں کہ (راویٔ حدیث) ابو سلام کا نام ممطور ہے اور وہ حبشی ہے۔ اور (صحابیٔ رسول صلی اللہ علیہ وسلم) ابو امامہ کا نام صدی بن عجلان ہے۔","f2":"’’تم پر ہی لوٹا دیا جاتا ہے‘‘ کیونکہ یہ خمس دراصل بیت المال میں جمع ہو جاتا ہے اور وہاں سے یہ مال مسلمانوں کی فلاح و بہبود پر خرچ ہوتا ہے۔ ان الفاظ سے امام صاحب رحمہ اللہ نے استدلال فرمایا ہے کہ خمس صرف اہل بیت کا حق نہیں بلکہ یہ بیت المال میں جمع ہوتا ہے۔ وہاں سے ضرورت کے مطابق اہل بیت پر بھی خرچ ہو گا اور دوسرے عوام الناس پر بھی۔ اور یہ استدلال صحیح ہے اور یہی صحیح مسلک ہے۔ و اللہ اعلم۔"}],[4139,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک اونٹ کے پاس آئے اور اس کی کوہان سے اپنی دو انگلیوں کے درمیان ایک بال لیا پھر فرمایا:\"خمس (پانچویں حصے) کے علاوہ مال فیٔ میں سے میرا کچھ بھی حق نہیں اس بال کے برابر بھی نہیں اور خمس بھی تم ہی پر لوٹا دیا جاتا ہے\"۔","الألباني: حسن صحيح",{"u2":"حضرت عمرو بن شعیب کے پردادا محترم (حضرت عبداللہ بن عمرو بن عاص رضی اللہ تعالٰی عنہ) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک اونٹ کے پاس آئے اور اپنی دو انگلیوں کے درمیان اس کے کوہان سے اون پکڑی، اور فرمایا: ’’میرے لیے مال غنیمت سے اتنا بھی جائز نہیں علاوہ خمس کے اور وہ خمس بھی تم پر ہی لوٹا دیا جاتا ہے۔‘‘"}],[4140,"عمر رضی اللہ عنہ کہتے ہیں کہ بنی نضیر کا مال غنیمت مال فی میں سے تھا جو اللہ تعالی نے اپنے رسول کو عطا کیا یعنی مسلمانوں نے اس پر نہ گھوڑے دوڑائے اور نہ جنگ کی۔ آپ اسی میں سے سال بھر کا خرچ اپنے اوپر کرتے، جو بچ جاتا اسے گھوڑوں اور ہتھیار میں جہاد کی تیاری کے لیے صرف کرتے۔","الألباني: صحيح",{"u2":"حضرت عمر رضی اللہ تعالٰی عنہ سے مروی ہے کہ بنو نضیر کا مال ان مالوں میں سے تھا جو اللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم کو جنگ کے بغیر عطا فرمایا تھا، مسملانوں نے اس کے حصول کے لیے اس پر اپنے گھوڑے اور اونٹ نہیںڈ دوڑائے تھے (لڑائی کے بغیر ہی حاصل ہوا)۔ آپ اس میں سے اپنے لیے (اور اپنے گھر والوں کے لیے) ایک سال کی خوراک رکھ لیتے تھے اور باقی مال کو جہاد فی سبیل اللہ کی تیاری کے لیے گھوڑے اور اسلحہ خریدنے میں خرچ فرما دیتے تھے۔","f2":"(۱) بنو نضیر ایک یہودی قبیلہ تھا جس کو ان کی بدعہدی کی سزا میں مدینہ منورہ سے نکال دیا گیا۔ وہ اپنا سامان وغیرہ تو ساتھ لے گئے تھے، البتہ ان کی زمینیں مسلمانوں کے قبضے میں آ گئی تھیں لیکن وہ بیت المال کی ملکیت تھیں۔ رسول اللہ صلی اللہ علیہ وسلم کے ذاتی اور گھریلو اخراجات چونکہ بیت المال کے ذمے تھے، اس لیے آپ اپنے اہل بیت کی سالانہ خوراک اس میں سے رکھ لیتے تھے اور باقی مال مسلمانوں کی فلاح و بہبود کے لیے خرچ فرماتے تھے۔ (۲) جائز اسباب کا حصول توکل کے خلاف نہیں جیسا کہ رسول اللہ صلی اللہ علیہ وسلم جنگی اسلحہ اور ہتھیار وغیرہ خریدا کرتے تھے، نیز اسی طرح اپنے لیے اور اہل و عیال کے لیے سال بھر کا خرچہ جمع کر رکھنا بھی توکل علی اللہ کے منافی نہیں۔"}],[4141,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ فاطمہ رضی اللہ عنہا نے ابوبکر رضی اللہ عنہ کے پاس ایک آدمی بھیجا وہ ان سے نبی اکرم صلی اللہ علیہ وسلم کے صدقے میں سے اپنا حصہ اور خیبر کے خمس (پانچویں حصے) میں سے اپنا حصہ مانگ رہی تھیں، ابوبکر رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے:\"ہمارا (یعنی انبیاء کا) کوئی وارث نہیں ہوتا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ حضرت فاطمہ رضی اللہ عنہا نے حضرت ابوبکر رضی اللہ تعالٰی عنہ کو پیغام بھیجا جبکہ وہ ان سے نبی صلی اللہ علیہ وسلم کے صدقہ اور خمس خیبر سے اپنی وراثت طلب کرتی تھیں۔ حضرت ابوبکر رضی اللہ تعالٰی عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا: ’’ہمارے ترکے میں وراثت نہیں چلتی۔‘‘","f2":"فوائد و مسائل: (۱) پیچھے گزر چکا ہے کہ اہل بیت خمس کو اپنا حق سمجھتے تھے جبکہ دیگر صحابہ کے نزدیک خمس بیت المال کی ملکیت ہوتا ہے، البتہ اس میں سے اہل بیت کے محتاج لوگوں سے تعاون کیا جائے گا۔ حضرت فاطمہ رضی اللہ عنہا نے اپنے خیال کے مطابق خیبر کے خمس، بنو نضیر کی زمینوں، فدک کی زمین اور صدقۃ النبی صلی اللہ علیہ وسلم سے وراثت طلب کی۔ حضرت ابوبکر رضی اللہ تعالٰی عنہ نے وضاحت فرمائی کہ یہ زمینیں آپ کی ذاتی نہیں بلکہ بیت المال کی ملکیت تھیں، لہٰذا ان میں وراثت جاری نہیں ہو گی۔ (۲) ’’نبی صلی اللہ علیہ وسلم کے صدقہ سے‘‘ یہ زمین بعد میں اس نام سے مشہور ہوئی ورنہ اگر اسی وقت یہ صدقہ کے نام سے معروف تھی تو حضرت فاطمہ رضی اللہ عنہا اس سے وراثت طلب نہ فرماتیں۔ بعض دیگر روایات میں آتا ہے کہ یہ زمین ایک یہودی شخص (مخیریق) نے بطور وصیت آپ کے لیے ہبہ کی تھی۔ (۳) ’’وراثت نہیں چلتی‘‘ کیونکہ نبی صلی اللہ علیہ وسلم نے اپنی جائیداد نہیں بنائی، نہ غنیمت سے حصہ لیا بلکہ آپ غنیمت سے خمس وصول فرماتے تھے جس سے اپنے اخراجات پورے کرنے کے بعد وہ مسملانوں کے مصالح میں صرف ہوتا تھا۔ گویا آپ نے خمس سے صرف ضروریات پوری کی تھیں، اسے اپنی ملکیت نہیں بنایا تھا بلکہ وہ دراصل بیت المال ہی کی ملکیت تھا۔ آپ کا یہ طرز عمل، اس لیے تھا کہ کوئی نابکار منافق یا کافر یہ نہ کہہ سکے کہ آپ نے دعوائے نبوت صرف مال جمع کرنے کے لیے کیا ہے۔ جب آپ نے اپنی زندگی میں کوئی جائیداد ہی نہیں بنائی بلکہ جو کچھ آتا تھا، وہ بیت المال میں جمع فرماتے تھے، صرف اپنے ضروی اخراجات وصول فرماتے تھے تو پھر وراثت کا سوال ہی پیدا نہیں ہوتا۔ حضرت فاطمہ رضی اللہ عنہا خاتون ہونے کی وجہ سے اس حقیقت سے واقف نہ تھیں۔ حضرت عباس رضی اللہ تعالٰی عنہ بھی آخری دور میں مدینہ منورہ تشریف لائے تھے، لہٰذا کوئی تعجب کی بات نہیں اگر ان حضرات کو یہ بات معلوم نہ ہو سکی۔ حضرت ابوبکر رضی اللہ تعالٰی عنہ جو کہ راز دار نبوت تھے، اس حقیقت سے مطلع تھے۔ یہ حدیث (ہمارے متروکہ مال میں وراثت نہیں چلتی) حضرت ابوبکر کے علاوہ بعض دیگر صحابہ سے بھی مروی ہے۔ سب سے بڑی دلیل رسول اللہ صلی اللہ علیہ وسلم کا اپنی زندگی میں طرز عمل تھا کہ آپ نے نہ کبھی غنیمت میں اپنا حصہ لیا، نہ خمس کو اپنا ذاتی مال سمجھا۔ صرف ضرورت کے لیے استعمال فرمایا۔ وراثت تو اس مال میں ہوتی ہے جو مملوکہ ہو۔ جب یہ مال (زمینیں وغیرہ) آپ کی ملکیت ہی نہیں تھا تو وراثت کیسے جاری ہوتی؟"}],[4142,"عطاء آیت کریمہ: «واعلموا أنما غنمتم من شىء فأن لله خمسه وللرسول ولذي القربى» \"جان لو کہ تمہیں جو مال غنیمت ملا ہے اس کا خمس اللہ کے لیے اور رسول اور ذی القربی کے لیے ہے\"۔ (الأنفال: ۴۱) کے سلسلے میں کہتے ہیں: اللہ کا خمس اور رسول کا خمس ایک ہی ہے، رسول اللہ صلی اللہ علیہ وسلم اس سے لوگوں کو سواریاں دیتے، نقد دیتے، جہاں چاہتے خرچ کرتے اور جو چاہتے اس سے کرتے۔","الألباني: صحيح الإسناد مرسل",{"u2":"حضرت عطاء سے اللہ تعالیٰ کے فرمان: {وَ اعْلَمُوْٓا اَنَّمَا غَنِمْتُمْ مِّنْ شَیْئٍ…الآیۃ} ’’تم جان لو کہ جو بھی تم غنیمت حاصل کرو، اس کا پانچواں حصہ اللہ تعالیٰ، اس کے رسول(صلی اللہ علیہ وسلم) اور رشتے داروں کے لیے ہے۔‘‘ کے بارے میں مروی ہے کہ اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کا حصہ ایک ہی ہے۔ رسول اللہ صلی اللہ علیہ وسلم اس حصے میں سے (مفلس اور تنگ دست لوگوں کو جہاد کے لیے) سواریاں مہیا کرتے اور اس میں سے ضرورت مندوں اور محتاجوں کو دیتے۔ جہاں چاہتے خرچ فرماتے اور اس سے جو چاہتے کرتے۔","f2":"فائدہ: ’’ایک ہی ہے‘‘ مطلب یہ ہے کہ اللہ تعالیٰ کا ذکر تو بطور تبرک ہے۔ اللہ تعالیٰ کا کوئی الگ حصہ نہیں بلکہ رسول اللہ صلی اللہ علیہ وسلم خمس میں کلیتاً بااختیار تھے۔ بعض کا خیال ہے کہ اللہ تعالیٰ کا حصہ بیت اللہ پر خرچ کیا جائے۔ اس حدیث کو یہاں ذکر کرنے سے مقصود یہ ہے کہ یہ خمس مکمل طور پر رسول اللہ صلی اللہ علیہ وسلم کی صوابدید کے سپرد تھا۔ اس میں کسی کا حصہ مقرر نہیں تھا۔ آپ کی وفات کے بعد یہی اختیار حاکم وقت کو تھا۔"}],[4143,"قیس بن مسلم کہتے ہیں کہ میں نے حسن بن محمد سے آیت کریمہ: «واعلموا أنما غنمتم من شىء فأن لله خمسه» کے بارے میں پوچھا تو انہوں نے کہا: یہ تو اللہ سے کلام کی ابتداء ہے جیسے کہا جاتا ہے \"دنیا اور آخرت اللہ کے لیے ہے\"، انہوں نے کہا: ان دونوں حصوں \"یعنی رسول اور ذی القربی کے حصہ\" میں رسول اللہ صلی اللہ علیہ وسلم کی موت کے بعد لوگوں میں اختلاف ہوا، تو کہنے والوں میں سے کسی نے کہا کہ رسول کا حصہ ان کے بعد خلیفہ کا ہو گا، ایک جماعت نے کہا کہ ذی القربی کا حصہ رسول اللہ صلی اللہ علیہ وسلم کے رشتہ داروں کا ہو گا، دوسروں نے کہا: ذی القربی کا حصہ خلیفہ کے رشتہ داروں کا ہو گا۔ بالآخر ان کی رائیں اس پر متفق ہو گئیں کہ ان لوگوں نے ان دونوں حصوں کو گھوڑوں اور جہاد کی تیاری کے لیے طے کر دیا، یہ دونوں حصے ابوبکر اور عمر رضی اللہ عنہما کی خلافت کے زمانہ میں اسی کام کے لیے رہے۔","الألباني: صحيح الإسناد مرسل",{"u2":"حضرت قیس بن مسلم سے رویات ہے کہ میں نے حضرت حسن بن محمد سے اللہ تعالیٰ کے فرمان: {وَ اعْلَمُوْٓا اَنَّمَا غَنِمْتُمْ مِّنْ شَیْئٍ فَاَنَّ لِلّٰہِ خُمُسَہٗ} ’’جان لو کہ تم جو بھی غنیمت حاصل کرو، اس کا خمس اللہ تعالیٰ کے لیے ہے۔‘‘ کے (مفہوم کے) بارے میں پوچھا۔ انہوں نے فرمایا: یہ اللہ تعالیٰ کا آغاز کلام کا انداز ہے ورنہ دنیا اور آخرت سب اللہ تعالیٰ ہی کے لیے ہیں، البتہ رسول اللہ صلی اللہ علیہ وسلم کی وفات کے بعد آپ اور قرابت داروں کے دو حصوں میں لوگوں نے اختلاف کیا۔ بعض نے کہا کہ آپ کے بعد آپ کا حصہ خلیفہ اور حاکم وقت کے لیے ہو گا۔ اسی طرح بعض نے کہا کہ رشتے داروں کا حصہ اب بھی رسول اللہ صلی اللہ علیہ وسلم کے اہل بیت کے لیے ہے۔ اور بعض نے کہا: اب رشتے داروں کا حصہ خلیفۂ وقت کے رشتے داروں کے لیے ہو گا، پھر بالآخر انہوں نے اس بات پر اتفاق کر لیا کہ یہ دونوں حصے جہاد کے لیے گھوڑے اور اسلحہ خریدنے میں خرچ کیے جائیں، چنانچہ حضرات ابوبکر و عمر رضی اللہ عنہ کے دور خلافت میں یہ دونوں حصے اسی مصرف میں خرچ ہوتے رہے۔","f2":"فوائد و مسائل: (۱) رسول اللہ صلی اللہ علیہ وسلم کا جو حصہ تھا، آپ کے بعد اس کے حق دار خلیفۂ بلافصل سیدنا ابوبکر صدیق رضی اللہ تعالٰی عنہ اور صدیق اکبر کے بعد خلیفۂ ثانی امیر المومنین سیدنا عمر فاروق رضی اللہ تعالٰی عنہ تھے لیکن ان دونوں محترم بزرگوں نے ہرگز وہ حصہ نہ لیا۔ یہ حدیث ان کی حقانیت اور بے نیازی و غناء کی بہت بڑی دلیل ہے۔ (۲) جیسا کہ پہلے بھی پیچھے گزر چکا ہے کہ خمس دراصل بیت المال کا ہے۔ اس میں کسی کا کوئی حصہ مقرر نہیں۔ جہاں ضرورت ہو خرچ کیا جائے، مثلاً: حاکم وقت اور دیگر ملازمین کی تنخواہ، ضرورت مند اور محتاج حضرات کے وظائف، جہاد کی تیاری اور مسلمانوں کی بہبود کے دوسرے کام۔ رسول اللہ صلی اللہ علیہ وسلم نے خمس میں جو تصرف فرمایا، وہ اللہ کے حکم کے مطابق فرمایا اور یہی رسول کی ذمہ داری ہے۔ (مزید تفصیل کے لیے دیکھئے فوائد، حدیث: ۴۱۳۸)"}],[4144,"موسی بن ابی عائشہ کہتے ہیں کہ میں نے یحیی بن جزار سے اس آیت: «واعلموا أنما غنمتم من شىء فأن لله خمسه وللرسول» کے بارے میں پوچھا، میں نے کہا: نبی اکرم صلی اللہ علیہ وسلم کا خمس میں سے کتنا حصہ ہوتا تھا: انہوں نے کہا: خمس کا خمس ۱؎۔\n§وضاحت\n۱؎: یعنی پانچویں حصے کا پانچواں حصہ، کیونکہ خمس کا اکثر حصہ تو آپ صلی اللہ علیہ وسلم اسلامی کاموں میں خرچ کر دیتے تھے۔","الألباني: صحيح الإسناد مرسل",{"u2":"موسیٰ بن ابو عائشہ سے روایت ہے کہ میں نے یحییٰ بن جزار سے اس آیت: {وَ اعْلَمُوْٓا اَنَّمَا غَنِمْتُمْ مِّنْ شَیْئٍ فَاَنَّ لِلّٰہِ خُمُسَہٗ} ’’تم جان لو کہ جو بھی تھ غنیمت حاصل کرو، اس کا پانچواں حصہ اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کے لیے ہے۔‘‘ کے (مفہوم کے) کے بارے میں پوچھا۔ میں نے کہا کہ نبیٔ اکرم صلی اللہ علیہ وسلم کا خمس میں کتنا حصہ تھا؟ انہوں نے کہا: خمس کا پانچواں حصہ۔","f2":"فائدہ: آیت کے ظاہر الفاظ سے استدلال کیا گیا ہے کیونکہ اس میں اللہ تعالیٰ کے علاوہ پانچ مصارف ذکر ہیں، لہٰذا ہر مصرف میں خمس کا پانچواں حصہ صرف کیا جائے گا لیکن یہ استدلال درست نہیں کیونکہ آیت میں یہ کہیں ذکر نہیں کہ ہر ایک کو برابر رکھو بلکہ یہ تو حالات و حاجات پر موقوف ہے۔ جس مصرف میں زیادہ کی ضرورت ہے، وہاں زیادہ صرف کیا جائے اور جس میں کم ضرورت ہے، وہاں کم خرچ کیا جائے۔ کسی ایک کا حصہ مقرر نہیں۔ روایت میں مذکور یحییٰ بن جزار کو غالی شیعہ کہا گیا ہے۔ و اللہ اعلم۔ ویسے وہ سچا تھا۔"}],[4145,"مطرف کہتے ہیں کہ عامر شعبی سے نبی اکرم صلی اللہ علیہ وسلم کے حصے اور آپ کے صفی کے بارے میں پوچھا گیا تو انہوں نے کہا: نبی اکرم صلی اللہ علیہ وسلم کا حصہ ایک مسلمان شخص کے حصے کی طرح ہوتا تھا۔ رہا «صفی» ۱؎ کے حصے کا معاملہ تو آپ کو اختیار ہوتا کہ غلام، لونڈی اور گھوڑے وغیرہ میں سے جسے چاہیں لے لیں۔\n§وضاحت\n۱؎: «صفی» مالِ غنیمت کے اس حصے کو کہتے ہیں جسے حاکم تقسیم سے قبل اپنے لیے مقرر کر لے۔","الألباني: صحيح الإسناد مرسل",{"u2":"حضرت مطرف سے منقول ہے کہ حضرت شعبی سے نبیٔ اکرم صلی اللہ علیہ وسلم کے حصے اور آپ کے صَفِیّ (خاص حصے) کے بارے میں پوچھا گیا تو انہوں نے کہا: نبی صلی اللہ علیہ وسلم کا (عام) حصہ تو ایک عام مسلمان آدمی کے حصے کے برابر تھا، البتہ صفی (خصوصی حصے) کے بارے میں آپ کو اختیار تھا کہ جو بھی پسندیدہ اور نفیس چیز آپ پسند فرماتے، لے سکتے تھے۔","f2":"فوائد و مسائل: (۱) ’’صفی‘‘ اس خصوصی حصے کو کہا جاتا ہے جو امام و رئیس مال غنیمت کی تقسیم سے پہلے اپنی ذات کے لیے چن لے، مثلاً: لونڈی، غلام، اونٹ اور گھوڑا وغیرہ۔ (۲) گویا آپ کو خمس میں مکمل اختیار تھا۔ آپ کسی بھی چیز کو اپنے لیی خصوصی طور پر پسند فرما سکتے تھے جیسے آپ نے خیبر کے قیدیوں سے حضرت صفیہ ام المومنین رضی اللہ عنہا کو پسند فرمایا اور ان کو آزاد فرما کر ان سے نکاح فرما لیا۔ (۳) دلائل کی رو سے مذکورہ روایت مرسل صحیح ہے۔"}],[4146,"یزید بن شخیر کہتے ہیں کہ میں مطرف کے ساتھ کھلیان میں تھا کہ اچانک ایک آدمی چمڑے کا ایک ٹکڑا لے کر آیا اور بولا: میرے لیے رسول اللہ صلی اللہ علیہ وسلم نے یہ لکھا ہے، تو کیا تم میں سے کوئی اسے پڑھ سکتا ہے؟ انہوں نے کہا: میں پڑھوں گا، تو دیکھا کہ اس تحریر میں یہ تھا: \"اللہ کے نبی محمد صلی اللہ علیہ وسلم کی طرف سے بنی زہیر بن اقیش کے لیے: اگر یہ لوگ «لا إله إلا اللہ وأن محمدا رسول اللہ» \"اللہ تعالی کے سوا کوئی معبود برحق نہیں اور محمد اللہ کے رسول ہیں\" کی گواہی دیں اور کفار و مشرکین کا ساتھ چھوڑ دیں اور اپنے مال غنیمت میں سے خمس، نبی کے حصے اور ان کے «صفی» کا اقرار کریں تو وہ اللہ اور اس کے رسول کی امان میں رہیں گے\"۔\n§وضاحت\n۱؎: «صفی» مالِ غنیمت کے اس حصے کو کہتے ہیں جسے حاکم تقسیم سے قبل اپنے لیے مقرر کر لے۔","الألباني: صحيح الإسناد",{"u2":"حضرت یزید بن شخیر سے مروی ہے کہ میں (بصرہ کے محلہ) مربد میں حضرت مطرف کے ساتھ تھا کہ ایک آدمی آیا۔ اس کے پاس سرخ چمڑے کا ایک ٹکڑا تھا۔ اس نے کہا: یہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے لکھ کر دیا تھا۔ تم میں سے کوئی پڑھ سکتا ہے؟ میں نے کہا: میں پڑھ دیتا ہوں۔ اس میں لکھا تھا: ’’یہ دستاویز نبیٔ اکرم حضرت محمد مصطفی صلی اللہ علیہ وسلم کی طرف سے بنو زہیر بن اقیش کے لیے لکھی گئی ہے کہ اگر وہ ’’لا الہ الا اللہ محمد رسول اللہ‘‘ کی گواہی دیں، مشرکین سے الگ تھلگ ہو جائیں اور اپنی حاصل کردہ غنیمتوں میں سے خمس (حکومت کو) دینے کا اقرار کریں، نیز وہ نبی صلی اللہ علیہ وسلم کا عام حصہ اور خصوصی حصہ (صفی) بھی ادا کریں تو (وہ بے خوف ہو کر رہیں)۔ ان کو اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی طرف سے پروانۂ امن حاصل ہو گا۔‘‘","f2":"صحیح بات یہی ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم ک عمومی و خصوصی حصہ بھی خمس میں شامل ہے، اگرچہ ظاہر الفاظ مال غنیمت اور مال فے کی تقسیم کے مسائل ان حصوں کو خمس سے الگ ظاہر کررہے ہیں۔باقی روایات کا لحاظ رکھنا بھی ضروری ہے۔(دیکھیے فوائد‘"}],[4147,"مجاہد کہتے ہیں کہ (قرآن میں) جو خمس اللہ اور رسول کے لیے آیا ہے، وہ نبی اکرم صلی اللہ علیہ وسلم اور آپ کے رشتہ داروں کے لیے تھا، وہ لوگ صدقہ و زکاۃ کے مال سے نہیں کھاتے تھے، چنانچہ نبی اکرم صلی اللہ علیہ وسلم کے لیے خمس کا خمس تھا اور رشتہ داروں کے خمس کا خمس اور اتنا ہی یتیموں کے لیے، اتنا ہی فقراء و مساکین کے لیے اور اتنا ہی مسافروں کے لیے۔ ابوعبدالرحمٰن (امام نسائی) کہتے ہیں: اللہ تعالی نے فرمایا: \"اور جان لو کہ جو کچھ تمہیں مال غنیمت سے ملے تو: اللہ کے لیے، رسول کے لیے، رشتہ داروں، یتیموں، مسکینوں اور مسافروں کے لیے اس کا خمس ہے، اللہ کے اس فرمان «واعلموا أنما غنمتم من شىء فأن لله خمسه وللرسول ولذي القربى واليتامى والمساكين وابن السبيل» میں اللہ کا قول «لِلَّهِ» \"یعنی اللہ کے لیے ہے\" ابتدائے کلام کے طور پر ہے کیونکہ تمام چیزیں اللہ ہی کی ہیں اور مال فیٔ اور خمس کے سلسلے میں بات کی ابتداء بھی اس \"اپنے ذکر\" سے شاید اس لیے کی ہے کہ وہ سب سے اعلی درجے کی کمائی (روزی) ہے، اور صدقے کی اپنی طرف نسبت نہیں کی، اس لیے کہ وہ لوگوں کا میل (کچیل) ہے۔ واللہ اعلم۔ ایک قول یہ بھی ہے کہ غنیمت کا کچھ مال لے کر کعبے میں لگایا جائے گا اور یہی اللہ تعالی کا حصہ ہے اور نبی کا حصہ امام کے لیے ہو گا جو اس سے گھوڑے اور ہتھیار خریدے گا، اور اسی میں سے وہ ایسے لوگوں کو دے گا جن کو وہ مسلمانوں کے لیے مفید سمجھے گا جیسے اہل حدیث، اہل علم، اہل فقہ، اور اہل قرآن کے لیے، اور ذی القربی کا حصہ بنو ہاشم اور بنو مطلب کا ہے، ان میں غنی (مالدار) اور فقیر سب برابر ہیں، ایک قول کے مطابق ان میں بھی غنی کے بجائے صرف فقیر کے لیے ہے جیسے یتیم، مسافر وغیرہ، دونوں اقوال میں مجھے یہی زیادہ صواب سے قریب معلوم ہوتا ہے، واللہ اعلم۔ اسی طرح چھوٹا، بڑا، مرد، عورت سب برابر ہوں گے، اس لیے کہ اللہ تعالی نے یہ ان سب کے لیے رکھا ہے اور رسول اللہ صلی اللہ علیہ وسلم نے اسے انہی سب میں تقسیم کیا ہے، اور حدیث میں کہیں ایسا نہیں ہے کہ آپ نے ان میں سے ایک کو دوسرے پر ترجیح دی ہو، ہمیں اس سلسلے میں علماء کے درمیان کسی اختلاف کا بھی علم نہیں ہے کہ ایک شخص اگر کسی کی اولاد کے لیے ایک تہائی کی وصیت کرے تو وہ ان سب میں تقسیم ہو گا اور مرد و عورت اس سلسلے میں سب برابر ہوں گے جب وہ شمار کئے جائیں گے، اسی طرح سے ہر وہ چیز جو کسی کی اولاد کے لیے دی گئی ہو تو وہ ان میں برابر ہو گی، سوائے اس کے کہ اس چیز کا حکم کرنے والا اس کی وضاحت کر دے۔ «واللہ ولی التوفیق»۔ اور ایک حصہ مسلم یتیموں کے لیے اور ایک حصہ مسلم مساکین کے لیے اور ایک حصہ مسلم مسافروں کے لیے ہے۔ ان میں سے کسی کو مسکین کا حصہ اور مسافر کا حصہ نہیں دیا جائے گا، اور اس سے کہا جائے گا کہ ان (دو) میں سے جو چاہے لے لے اور بقیہ چار خمس کو امام ان بالغ مسلمانوں میں تقسیم کرے گا جو جنگ میں شریک ہوئے۔","الألباني: ضعيف الإسناد مرسل",{"u2":"حضرت مجاہد بیان کرتے ہیںکہ وہ خمس جو ا اللہ تعالیٰ کے لیے اور ان کے رسول کے لیے تھا‘وہ بنیااکرم صلی اللہ علیہ وسلم اور آپ کے رشتے داروں کے لیے تھا کیونکہ وہ صدقہ نہیں لیتے تھے لہٰذا خمس کا پانچواں حصہ نبی اکرم صلی اللہ علیہ وسلم کے لیے تھا۔اور خمس کا ایک اور پانچواں لیے بھی اسی قدر(پانچواں حصہ)تھا۔مساکین کے لیے بھی (پانچواں حصہ)تھا۔اور مسافرقوں کے لیے بھی پانچواں حصہ تھا۔\nثابو عبدالرحمن(امام نسائی)بیان کرتے ہیں کہ ا اللہ تعالیٰ نے فرمایا:’’تم جان لوکہ جو بھی تم غنیمت حاصل کرو‘اس کا پانچواں حصہ ا اللہ تعالیٰ اس کے رسول صلی اللہ علیہ وسلم ‘آپ کے رشتے داروں‘ یتیموں‘مسکینوں اور مسافروں کے لیے ہے۔‘‘ا اللہ تعالیٰ کا فرمانا{ اللہ } یہ تو آغاز کلام (تبرک)کے لیے ہے۔کیونکہ سب چیزیں ا اللہ تعالیٰ ہی کی ہیں۔ممکن ہے ا اللہ تعالیٰ نے غنیمت اور خمس کے مسئلے میں اپناذ کرپہلے اس لیے فرمایا ہو کہ یہ انتہائی عمدہ کمائی ہے۔ا اللہ تعالیٰ مال غنیمت اور مال فے کی تقسیم کے مسائل نے صدقے کی نسبت اپنی طرف نہیں فرمائی کیونکہ یہ لاگوں کامیل کچیل ہے۔یہ بھی کہاگیا ہے کہ غنیمت کے سے کچھ مال لے کر بیت ا اللہ پر صرف کیا جائے گا اور یہ ا اللہ تعالیٰ والا حصہ ہے۔ملے گا۔وہ اس گھوڑے اور اسلحہ وغیرہ خریدے گا اور جن کو وہ مناسب سمجھے‘ان کو اس میں سے عطیات دے گا‘مثلاََ:جن لوگوں نے مسلمانوں کے لیے کوئی کارنامے سرانجام دیے ہوں اور جن سے مسلمانوں کا فائدہ ہو۔محد ثین‘فقہاء حفاظ اور دیگر اہل علم وغیرہ(بھی اس میں شامل ہیں)۔’’قرابت داری‘‘کا حصہ بنو ہاشم اور بنو مطلب میں تقسیم ہوگا‘خواہ وہ مالدار ہوں یا فقیر۔یہ بھی کہا گیا ہے کہ ان میں صرف فقراء کو ملے گا‘اغنیاء کو ملتا ہے۔اور میرے نزدیل یہ قول زیادہ درست ہے۔وا اللہ اعلم۔چھوٹے بڑے‘مرد اور عورت سب اس میں برابر ہوں گے کیونکہ ا اللہ تعالیٰ نے نے یہ حصہ ان کے لیے مقرر فرمادیا ہے اور رسول ا اللہ صلی اللہ علیہ وسلم نے ان میں تقسیم فرمایا۔کسی حدیث میں یہ ذکر نہیںکہ آپ میں کسی کو دوسرے سے زیادہ دیا ہو۔(اس کی دلیل یہ ہے کہ)اگر کوئی شخص کسی خاندان کے لیے اپنی متروکہ جائیدادکے تیسرے حصے کی وصیت کرجائے تو علماء مٰں کوئی اختلاف نہیں کہ وہ ان کے درمیان برابر تقسیم ہو گا۔مذکر مئونث گنتی کے وقت ایک سے ہوں گے(یعنی کم وبیش نہیں دیا جائے گا)۔اسی طرح جوبھی چیز کسی\nماغنیمت اور مال فے کی تقسیم کے مسائل قبیلے کو دی جائے ‘وہ ان میں برابر تقسیم ہوتی ہے الا یہ کہ ہے۔اور یتیموں‘مسکینوں اور مسافروں کے حصے ان میں سے کسی کو دو حصے نہیں دیے جائیں گے‘مثلاََ:مسین کا بھی مسافرکابھی (بلکہ ایک حصہ دیاجائے گا)اسے جائے گا۔ان میں سے جونسا چاہو ہولے لو۔اور باقی چار حصے (یعنی خمس کے علاوہ غنیمت)امام وقت(حاکم اعلیٰ یا اس کا نمائندہ)کنگ میں حاضر ہونے والے بالغ مسلمانوں میں تقسیم کردے گا۔","f2":"غنیمت اور خمس کے بارے میں تفصیلی بحث سابقہ حدیث میں ہوچکی ہے۔ملا حظہ فرمائیں۔باقی رہا امام صاحب کا فرمانا کہ خمس میں فلاں فلاں کے حصے مقرر ہیں اور برابر ہیں۔یہ فرمایا درست نہیں بلکہ خمس کا اور خمس کے مستحقین کا تعین ہے مقدار تعین نہیں۔جس مصرف میں ضرورت ہو‘خرچ کرے اور جس قدر ضرورت ہو‘خرچ کرے۔یہ نہیں کہ فقرا ء مساکین اور قرابت داروں کو عین برابر حصے دے بلکہ ان کو ان کی حاجت کے مطابق ملے گا‘یعنی ا اللہ تعالیٰ نے خمس وبیش۔یہ کہیں منقول نہیں کہ رسول ا اللہ صلی اللہ علیہ وسلم نے اپنے رشتے داروں یا دوسرے مستحقین میں عین برابر مال تقسیم کیا ہو بلکہ غزوہ حین کے خمس سے آپ نے بعض لوگوں کو سوسواونٹ دیے تھے اور بعض کو کچھ بھی نہیں دیا تھا‘نیز یہ بھی تو ممکن ہے کہ کسی علاقے میں اہل بیت ہی نہ ہوں۔تو پھر ان کا حصہ کن کو دیا جائے گا؟اصل یہی ہے کہ مستحقین متعین ہیں لیکن حصہ متعین نہیں جوبھی مستحق پایا جائے گا اس کا حاجت کے مطابق اسے دیا جائے گا۔"}],[4148,"مالک بن اوس بن حدثان کہتے ہیں کہ عباس اور علی رضی اللہ عنہما جھگڑتے ہوئے عمر رضی اللہ عنہ کے پاس آئے، عباس رضی اللہ عنہ نے کہا: میرے اور ان کے درمیان فیصلہ کیجئیے، لوگوں نے کہا: ان دونوں کے درمیان فیصلہ فرما دیجئیے، تو عمر رضی اللہ عنہ نے کہا: میں ان کے درمیان فیصلہ نہیں کر سکتا، انہیں معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"ہمارا ترکہ کسی کو نہیں ملتا، جو کچھ ہم چھوڑیں وہ صدقہ ہے\"۔ راوی کہتے ہیں: زہری ۱؎ نے (آگے روایت کرتے ہوئے اس طرح) کہا: (عمر رضی اللہ عنہ نے کہا:) رسول اللہ صلی اللہ علیہ وسلم (جب) اس مال کے ولی و نگراں رہے تو اس میں اپنے گھر والوں کے خرچ کے لیے لیتے اور باقی سارا اللہ کی راہ میں خرچ کرتے، پھر آپ کے بعد ابوبکر رضی اللہ عنہ متولی ہوئے اور ان کے بعد میں متولی ہوا، تو میں نے بھی اس میں وہی کیا جو ابوبکر رضی اللہ عنہ کرتے تھے، پھر یہ دونوں میرے پاس آئے اور مجھ سے مطالبہ کیا کہ اسے میں ان کے حوالے کر دوں کہ وہ اس میں اس طرح عمل کریں گے جیسے رسول اللہ صلی اللہ علیہ وسلم کرتے تھے اور جیسے ابوبکر رضی اللہ عنہ کرتے تھے اور جیسے تم کرتے ہو، چنانچہ میں نے اسے ان دونوں کو دے دیا اور اس پر ان سے اقرار لے لیا، پھر اب یہ میرے پاس آئے ہیں، یہ کہتے ہیں: میرے بھتیجے کی طرف سے میرا حصہ مجھے دلائیے ۲؎ اور وہ کہتے ہیں: مجھے میرا حصہ بیوی کی طرف سے دلائیے ۳؎، اگر انہیں منظور ہو کہ میں وہ مال ان کے سپرد کر دوں اس شرط پر کہ یہ دونوں اس میں اسی طرح عمل کریں گے جیسے رسول اللہ صلی اللہ علیہ وسلم نے کیا اور جیسے میں نے کیا تو میں ان کے حوالے کرتا ہوں، اور اگر انہیں (یہ شرط) منظور نہ ہو تو وہ گھر میں بیٹھیں ۴؎، پھر عمر رضی اللہ عنہ نے یہ آیات پڑھیں: «واعلموا أنما غنمتم من شىء فأن لله خمسه وللرسول ولذي القربى واليتامى والمساكين وابن السبيل» \"جان لو جو کچھ تمہیں غنیمت میں ملے تو اس کا خمس اللہ کے لیے ہے، رسول کے لیے، ذی القربی، یتیموں، مسکینوں اور مسافروں کے لیے ہے\" (الانفال: ۴۱)۔ اور یہ ان لوگوں کے لیے ہے «إنما الصدقات للفقراء والمساكين والعاملين عليها والمؤلفة قلوبهم وفي الرقاب والغارمين وفي سبيل اللہ» \"صدقات فقراء، مساکین، زکاۃ کا کام کرنے والے لوگوں، مؤلفۃ القلوب، غلاموں، قرض داروں اور مسافروں کے لیے ہیں\" (التوبہ: ۶۰)۔ اور یہ ان لوگوں کے لیے ہے \" «وما أفاء اللہ على رسوله منهم فما أوجفتم عليه من خيل ولا ركاب» \"اور ان کی طرف سے جو اللہ اپنے رسول کو لوٹائے تو جس پر تم نے گھوڑے دوڑائے اور زین کسے\" (الحشر: ۶)۔ زہری کہتے ہیں کہ یہ رسول اللہ صلی اللہ علیہ وسلم کے لیے خاص ہے اور وہ عربیہ کے چند گاؤں ہیں جیسے فدک وغیرہ۔ اور اسی طرح «ما أفاء اللہ على رسوله من أهل القرى فلله وللرسول ولذي القربى واليتامى والمساكين وابن السبيل، و، للفقراء المهاجرين الذين أخرجوا من ديارهم وأموالهم، والذين تبوءوا الدار والإيمان من قبلهم، والذين جاءوا من بعدهم» \"جو اللہ گاؤں والوں کی طرف سے اپنے رسول پر لوٹائے تو وہ اللہ کے لیے رسول کے لیے اور ذی القربی، یتیموں، مسکینوں، مسافروں اور ان فقراء مہاجرین لوگوں کے لیے ہے جو اپنے گھروں اور اپنے اموال سے نکال دیے گئے اور جنہوں نے الدار (مدینہ) کو اپنا جائے قیام بنایا اور ایمان لائے اس سے پہلے اور اس کے بعد\" (الحشر: ۷-۱۰)، اس آیت میں سبھی لوگ آ گئے ہیں، اور کوئی مسلمان ایسا نہیں جس کا اس مال میں حق نہ ہو، یا یہ کہا: حصہ نہ ہو، سوائے چند لوگوں کے جنہیں تم اپنا غلام بناتے ہو اور اگر میں زندہ رہا تو ان شاءاللہ ہر ایک کو اس کا حق۔ یا کہا: اس کا نصیب مل کر رہے گا۔\nكتاب البيعة\n§وضاحت\n۱؎: مالک بن اوس سے اس حدیث کو روایت کرنے والے ایک راوی زہری بھی ہیں، دیکھئیے حدیث نمبر: ۴۱۴۵ ۲؎: کیونکہ عباس رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے چچا تھے۔ ۳؎: کیونکہ علی رضی اللہ عنہ فاطمہ رضی اللہ عنہا کے شوہر تھے۔ ۴؎: یعنی جس عہد و پیمان کے تحت یہ مال تمہیں دیا گیا ہے اسی پر اکتفا کرو مزید کسی مطالبہ کی قطعی ضرورت نہیں۔","الألباني: صحيح",{"u2":"حضرت مالک بن حدثان سے روایت ہے کہ حضرت علی اور حضرت عباس رضی اللہ عنہ حضرت عمر رضی اللہ عنہ کے پاس جھگڑتے ہوئے آئے۔حضرت عباس رضی اللہ عنہ نے فرمایا:میرے اور اس (علی رضی اللہ عنہ)کے درمیان فیصلہ فرمایئے۔حاضرین نے بھی کہا:ان کے درمیان ضرور فیصلہ فرمایئے۔حضرت عمر رضی اللہ عنہ نے فرمایا:لیکن مٰں ان کے درمیان فیصلہ نہیں کروں گا جبکہ انھیں علم ہے کہ رسول ہوتی۔جو کچھ ہم چھوڑ جائیں‘وہ صدقہ ہوتا ہے۔‘‘رسول ا اللہ صلی اللہ علیہ وسلم ان(متنازعہ) زمینوں کے سرپرست اور متولی تھے۔آپ ان سے اپنے اہل بیت کی خوراک لیتے اور باقی آمدن بیت المال میں رکھتے تھے۔پھر حضرت ابوبکر رضی اللہ عنہ آُ کے بعد مٰں ان کا سرپرست اور متولی بنا اور میں نے ان میںوہی کچھ کیا جو کچھ وہ کیا کرتے تھے‘پھر یہ دونوں (حضرات علی وعباس رضی اللہ عنہ) میرے پاس آئے اور مجھ سے مطالبہ کیا کہ یہ زمین ان کے سپرد کی جائے اس شرط پر کہ وہ اسی طریقے سے اس کا انتظام کریں گے جس طرح رسول ا اللہ صلی اللہ علیہ وسلم کرتے تھے‘حضرت ابوبکر رضی اللہ عنہ کرتے تھے اور میں کرتا رہا ہوں۔میں نے اس شرط پر ان کو زمین دے دی اور ان سے عہد و پیمان لے لیا۔پھر یہ دوبارہ میرے پاس آئے۔یہ (حضرت عباس رضی اللہ عنہ) کہتے تھے کہ اتنی زمین میرے انتظام میں دے دیجیے جو مجھے میرے بھیتجے (رسول ا اللہ صلی اللہ علیہ وسلم) سے بطور وراثت ملتی۔اور یہ (حضرت علی رضی اللہ عنہ) کہتے تھے کہ اتنی زمین میرے انتظام میں دے دیجیے جو میری بیوی (حضرت فاطمہ رضی اللہ عنہا) کو وراثت میں ملتی۔اگر تو یہ چاہیں کہ میں ان کو اس شرط پر زمین سپرد کر دوں کہ وہ اس میں اس طرح انتظام کریں جس طرح رسول ا اللہ صلی اللہ علیہ وسلم کرتے تھے‘حضرت ابوبکر رضی اللہ عنہ کرتے تھے اور میں کرتا رہا ہوں‘پھر تو میں اس شرط پر پر زمین ان کے سپرد کرتا ہوں‘ ورنہ میں انتظام سنبھال لیتا ہوں‘پھر آپ نے یہ آیت پڑھی’’تم جان لوکہ جوبھی تم غنیمت حاصل کرو اس پانچواں حصہ ا اللہ تعالیٰ ‘رسول ا اللہ صلی اللہ علیہ وسلم رشتے داروں (ایل بیت)‘یتیموں‘مسکینوں اور مسافروں کے لیے ہے۔‘‘خمس تو ان کے لیے ہوگیا۔ فقراء ‘مساکین‘صدقات جمع کرنے والے ملازمین‘مئولفئہ قلوب‘غلاموں‘مقروضوں اور مجاہدین کے لیے ہیں‘‘یہ (صدقات)ان کے لیے ہوگئے۔’’اور جو مال غنیمت ا اللہ تعالیٰ نے اپنے رسول کریم صلی اللہ علیہ وسلم کو ان سے (بنونضیر) سے عطا فرمایا ہے‘ اس کے لیے تم نے نہ گھوڑے دوڑائے نہ اونٹ۔‘‘حضرت زہری بیان کرتے ہیں کہ یہ زمینین خالص رسول ا اللہ صلی اللہ علیہ وسلم کے لیے تھیں۔اسی طرح کچھ عربی بستیاں جیسے فدک وغیرہ بھی آپ کے لیے خاص تھیں۔’’جو کچھ ا اللہ تعالیٰ نے اپنے رسول کریم (صلی اللہ علیہ وسلم)کو ان بستیوں سے دیا ہے‘وہ ا اللہ تعالیٰ‘اس کے رسول(صلی اللہ علیہ وسلم) اہل بیت یتیموں ‘مسکینوں اور مسافروں کے لیے ‘‘نیز’’یہ ان فقراء مہاجرین کے لیے ہے جن کو ان کے گھر بار سے نکال دیا گیا اور ان انصار کے لیے جودار الاسلام(مدینہ منورہ)کے رہنے والے ہیں اور مہاجرین کی آمد سے قبل ہی مسلمان ہوچکے تھے اور ان لوگوں کے لیے بھی جو ان کے بعد آئے(یا آئیں گے)‘‘۔یہ آیت تمام مسلمانوں شامل ہے۔کسی مسلمان کو بھی باہر نہیں رہنے دیا۔سب کا اس مام میں حق ہے‘لبتہ وہ غلام جو تمھاری ملکیت میں ہیں(ان کا کرئی حق نہیں)۔اور اگر زندہ رہا تو ان شاء ا اللہ ہر مسلمان کو اس کا حق لازمامل کے رہے گا۔","f2":"حضرت عباس اور حضرت علی رضی اللہ عنہما حضرت عمر رضی اللہ عنہ سے ان زمینوں کی ملکیت نہیں مانگتے تھے بلکہ ان کا انتظام ہی ما نگتے تھے لیکن چونکہ دونوں کا آپس میں اتفاق نہیں رہتا تھا‘مزاج مختلف تھے‘ اس لیے عام لڑتے جھگڑتے رہتے تھے۔چونکہ ان کا مطالبہ تھا کہ آپ ہمیں ان کا انتظام تقسیم کرنے سے یہ تصور پیدا ہوگا(خصوصََا حصہ وراثت کے مطابق تقسیم کرنے سے)کہ شایدان کی ملکیت ہے جبکہ یہ تصور صحیح نہیں الہٰذا میں تقسیم نہیں کرتا۔دونوں مل کر انتظام کریں۔اگر وہ اس عاجز ہیں تومیرے سپرد کردیں۔میں خودانتظام کرتا رہوں گا۔صحیح بخاری میں اس کئی تفصیل صراحت سے ہے۔’’بطوروراثت ملتی‘‘یعنی اگر وراثت جاری ہوتی اور حصے تقسیم ہوتے۔یہ مطلب نہیں کہ اب ہمیں کہ اب ہمیں بطور وراثت تقسیم کردیں۔پہلے گزرچکا ہے کہ حضرت عمر رضی اللہ عنہ کے نزدیک خمس خیبر‘بنو نضیر کی زمینیں‘فدک اور صدقتہ النبی صلی اللہ علیہ وسلم وغیرہ(جنھیں اہل بیت رسول ا صلی اللہ علیہ وسلم کی ذاتی جائیداد سمجتے تھے اور بطور وراثت اپنا حق سمجھتے تھے)درصل بیت المال کی ملکیت تھے اور اس میں رسول ا اللہ صلی اللہ علیہ وسلم اہل بیت اور مہاجرین وانصار بلکہ تمام(موجودہ آئندہ)مسلمانوں کو حق سمجھتے تھے‘یعنی جو بھی ضرورت مند اور متحاج ہو ‘اسے دے دیا جائے گا‘خواہ وہ اہل بیت سے ہو یادیگر مسلمانوں سے۔اس بات کو ثابت کرنے کے لیے انھوں نے قرآن مجید کے مختلف مقامات سے یہ آیات واجزاء پڑھے جن سے ان کا مدعی ثابت ہوتا ہے۔یقیناََ اس سلسلے میں حضرت عمر رضی اللہ عنہ کی رائے ان لوگوں سے زیاسہ معتبر ہے جنھوں نے خمس میں باقدعدہ حصے دار بنا دیے ہیں کہ ان کے حصے سے سرموکمی بیشی نہیں ہوسکتی بلکہ تقسیم میں بھی برابری فرض کردی ہے جیسا کہ امام نسائی رحمہ اللہ کے خیالات اوپر گزرے ہیں۔حضرت عمر رضی اللہ عنہ خلیفہ ئراشد ہیں۔تجربہ کار حکمران ہیں۔مالی معاملات کی نزاکتوں سے خوب واقف ہیں‘نیز شریعت سے بھی کما حقہ واقف ہیں۔مجہتد صحابہ میں داخل ہیں بلکہ ان کے سرخیل ہیں۔رسول اللہ صلی اللہ علیہ وسلم نے خصوصََاان کی اتباع کا حکم دیا ہے۔ان کی باعقل اور اصول کے بھی بہت موافق ہے۔"}],[4149,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم سے خوشحالی و تنگی، خوشی و غمی ہر حالت میں سمع و طاعت پر بیعت کی، نیز اس بات پر بیعت کی کہ ہم حکمرانوں سے حکومت کے لیے نہ جھگڑیں، اور جہاں بھی رہیں حق پر قائم رہیں، اور (اس سلسلے میں) ہم کسی ملامت گر کی ملامت سے نہ ڈریں ۲؎۔\n§وضاحت\n۱؎: اس کتاب میں \" بیعت \" سے متعلق جو بھی احکام بیان ہوئے ہیں، یہ واضح رہے کہ ان کا تعلق صرف خلیفہ وقت یا مسلم حکمراں یا اس کے نائبین کے ذریعہ اس کے لیے بیعت لینے سے ہے۔ عہد نبوی سے لے کر زمانہ خیرالقرون بلکہ بہت بعد تک \" بیعت \" سے \" سیاسی بیعت \" ہی مراد لی جاتی رہی، بعد میں جب تصوف کا بدعی چلن ہوا تو \" شیخ طریقت \" یا \" پیر و مرشد \" قسم کے لوگ بیعت کے صحیح معنی و مراد کو اپنے بدعی اغراض و مقاصد کے لیے استعمال کرنے لگے، یہ شرعی معنی کی تحریف ہے، نیز اسلامی فرقوں اور جماعتوں کے پیشواؤں نے بھی \" بیعت \" کے صحیح معنی کا غلط استعمال کیا ہے، فالحذر، الحذر۔ ۲؎: یعنی: ہم آپ کی \" اور آپ کے بعد آپ کے خلفاء کی اگر ان کی بات بھلائی کی ہو \" اطاعت آسانی و پریشانی ہر حال میں کریں گے، خواہ وہ بات ہمارے موافق ہو یا مخالف، اور اس بات پر بیعت کرتے ہیں کہ جو آدمی بھی شرعی قانونی طور سے ولی الامر بنا دیا جائے ہم اس سے اس کے عہدہ کو چھیننے کی کوشش نہیں کریں گے، وہ ولی الامر ہمارے فائدے کا معاملہ کرے یا اس کے کسی معاملہ میں ہمارا نقصان ہو، ہمارے غیروں کی ہم پر ترجیح ہو۔ \" اولیاء الأمور :(اسلامی مملکت کے حکمرانوں ) کے بارے میں سلف کا صحیح موقف اور منہج یہی ہے، اسی کی روشنی میں موجودہ اسلامی تنظیموں کو اپنے موقف ومنہج کا جائزہ لینا چاہیئے۔","الألباني: صحيح",{"u2":"حضرت عبارد بن صامت رضی اللہ عنہ سے مروی ہے کہ ہم نے رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کی کہ ہم ہر آسانی وتنگی اور خوشی و ناخوشی میں آپ کی بات سنیں گے اور اطاعت کریں گے۔اور ہم حاکم سے اس کی حکومت نہیں چھینیں گے۔اور ہم حق لپر قائم رہیں گے جہاں بھی ہوں۔اور کسی ملامت کرنے والے کی ملامت سے نہیں ڈریں گے۔","f2":"۱باب کے ساتھ حدیث کی مناسبت بالکل واضح ہے کہ سمع وطاعت پر امام کی بیعت مشروع ہے۔شرعی امیر کی بات سننا اور اس کی اطاعت کرنا ہر مسلمان پر ہر حالت میں واجب ہے۔حالت تنگی کی ہویا آسانی کی‘خوشی کی ہو یانا خوشی کی۔بات پسند ہویا نا پسند‘یعنی اختلاف احوال سے وجوب اطاعت پر کوئی فرق نہیں پڑتا۔بقدرا استطاعت ہر حال میں اطاعت کرنی پڑے گی الا یہ کہ کوئی شرعی عذرہو۔شرعی امیر جب تک خودا اطاعت الہٰی پر کار بندرہے گا‘اس وقت تک اسے معزول کیا جاسکتا ہے نہ اس کی اطاعت ہی سے دست کش ہوا سکتا ہے۔ہاں اگر کسی امیر ومام میں ظاہر کفر دیکھا جائے تو اس کی اطاعت وفرمانبرداری واجب نہیں رہے گی بلکہ اسے معزول کرنے کی اگر طاقت ہوتو اسے معزول بھی کیا جائے گایا کم از کم اس کی معزولی کی کوشش کی جائے گی۔حق پر قائم رہنا ‘نیز حق کا ظہار امربالمعروف اورنہی عن المنکر کے طور پر کرنا‘ہر شخص کے لیے ہر جگہ ضروری ہے۔اس میں کسی ملامت گرکی ملامت کی پرواکرنے کی قطعاََ کوئی ضرورت نہیں۔’’اسانی وتنگی امیر کے حکم طیکہ وہ شریعت کے خلاف نہ ہو۔’’نہیں چھینیں گے‘‘یعنی کسی ناراضی کی بناپر یا امیر کی کسی غلطی کی بناپر اس کے خلاف بغاوت نہیں کریں گے الا یہ کہ اس سے صر یح کفر صادر ہوجائے تو پھر اس کی امارت شرعاََ ختم ہوجائے گی۔بغاوت نہ کرنے کا حکم ہر امیر کے بارے میں ہے ‘خواہ وہ منتخب ہو یا منتخب امیر کا نامزد کردہ۔’’نہیں ڈریں گے‘‘اس کا مطلب یہ ہے کہ کسی ملامت اور اناراضی کے ڈرے سے حق بات کہنے سے نہیں رکیں گے ورنہ گناہ کے مسئلے میں تو لوگوں کی ملامت سے ڈرنا چاہیے تا کہ انسان گناہوں سے بچ سکے۔"}],[4150,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ ہم نے تنگی و خوشی کی حالت میں سمع و طاعت پر رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی، پھر اسی طرح بیان کیا۔","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ عنہ بیان کرتے ہیں کہ ہم نے رسول ا اللہ صلی اللہ علیہ وسلم سے بیعت کی کہ ہر آسانی اور تنگی میں آپ کی بات سنیںگے اور اطاعت کریں گے۔اور باقی روایت حسب سابق ذکر کی۔"}],[4151,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ ہم نے تنگی و خوشحالی، خوشی و غمی ہر حال میں رسول اللہ صلی اللہ علیہ وسلم سے سمع و طاعت (سننے اور حکم بجا لانے) پر بیعت کی اور اس بات پر کہ ہم اپنے حکمرانوں سے حکومت کے لیے جھگڑا نہیں کریں گے، اور اس بات پر کہ ہم جہاں کہیں بھی رہیں حق کہیں گے یا حق پر قائم رہیں گے اور (اس بابت) ہم کسی ملامت کرنے والے کی ملامت سے نہیں ڈریں گے۔","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ عنہ سے مروی ہے کہ ہم نے رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کی کہ ہم ہر تنگی و آسانی اور ہر پسند و ناپسند میں آپ کی بات سنیں گے اور اطاعت کریں گے۔اور ہم حاکم سے اس کی حکومت کے بارے میں جھگڑا نہیں کریں۔اور ہم جہاں بھی ہوں‘حق پر قائم ودائم رہیں گے اور کسی ملامت کرنے والے کی ملامت سے نہیں ڈریں گے۔","f2":"حاکم‘امیر یا امام کی کسی غلطی کی بنا پر اس کے خلاف بغاوت نہیں کی جاسکتی کیو نکہ غلطی سے پاک تو کوئی بھی نہیں۔کیا اس شخص کے بعد پھر کسی فرشتے کو حاکم یا امام بنائیں گے؟نیا حاکم بھی انسان ہی ہوگا‘نیز بغاوت کرنے والے کیاخود غلطی سے پاک اور معصوم ہیں؟ البتہ اگر حاکم یا امام سے صریح کفرصادر ہوجائے تو اس کو بزور بر طرف کر دیا جائے گا۔"}],[4152,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم سے تنگی و خوشحالی، خوشی و غمی ہر حالت میں سمع و طاعت (سننے اور حکم بجا لینے) پر بیعت کی، اور اس بات پر کہ ہم حکمرانوں سے حکومت کے لیے جھگڑ انہیں کریں گے، اور اس بات پر کہ جہاں کہیں بھی رہیں حق بات کہیں گے۔","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ عنہ نے فرمایا: ہم نے رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کی کہ ہم ہر تنگی وآسانی اور خوشی وناخوشی میں آپ کی بات سنیں گے اور اطاعت کریں گے‘خواہ دوسروں کو ہم پر ترجیح دی جائے۔اور ہم حاکموں سے ان کی حکومت نہیں چھینیں گے۔اور ہم جہاں بھی ہوں‘حق بات ڈنکے کی چوٹ کہیں گے۔","f2":"’’جہاں بھی ہوں‘‘گھر میں ہوں یا باہر بازار میں ہوں یادر بار میں حتیٰ کہ ظالم وجابر سلطان و حاکم کے سامنے بھی حق بات کہیں گے۔"}],[4153,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم سے اپنی تنگی و خوشحالی اور خوشی و غمی ہر حال میں سمع و طاعت (سننے اور حکم بجا لینے) پر بیعت کی، اور اس بات پر کہ حکمرانوں سے حکومت کے سلسلے میں جھگڑا نہیں کریں گے، نیز اس بات پر کہ جہاں کہیں بھی رہیں عدل و انصاف کی بات کہیں گے اور اللہ تعالی کے معاملے میں کسی ملامت کرنے والے کی ملامت سے نہیں ڈریں گے۔","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ عنہ سے منقول ہے کہ ہم نے رسول کریم رضی اللہ عنہ کی بیعت کی کہ ہم اپنے عسر ویسر اور اپنی پسند و ناپسند میں (آپ کی) بات سنیں گے اور اطاعت کریں گے۔اور ہم کسی صاحب اقتدار سے اس کے اقتدار کے بارے میں جھگڑا نہیں کریں گے۔اور ہم جہاں بھی ہوں‘عدل وانصاف پر قائیم رہیں گے۔اور ا اللہ تعالیٰ (کی اطاعت)بارے میں کسی ملامت کرنے والے کی ملامت سے نہیں ڈریں گے۔"}],[4154,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم سے تنگی و خوشحالی اور خوشی و غمی اور دوسروں کو اپنے اوپر ترجیح دئیے جانے کی حالت میں سمع و طاعت (حکم سننے اور اس پر عمل کرنے) پر بیعت کی اور اس بات پر بیعت کی کہ ہم حکمرانوں سے حکومت کے سلسلے میں جھگڑا نہیں کریں گے اور یہ کہ ہم حق پر قائم رہیں گے جہاں بھی ہو۔ ہم اللہ کے معاملے میں کسی ملامت کرنے والے کی ملامت سے نہیں ڈریں گے۔ شعبہ کہتے ہیں کہ سیار نے «حیث ما کان» کا لفظ ذکر نہیں کیا اور یحیی نے ذکر کیا۔ شعبہ کہتے ہیں: اگر میں اس میں کوئی لفظ زائد کروں تو وہ سیار سے مروی ہو گا یا یحیی سے۔","الألباني: صحيح",{"u2":"حضرت عبادہ بن ولید کے دادا محترم(حضرت عبادہ بن صامت رضی اللہ عنہ) سے روایت ہے کہ ہم رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کی کہ ہم اپنی تنگی وآسانی اور اپنی پسند و ناپسند میں (ہر حال میں)آپ کی بات سنیں گے اور اطاعت کریں گے ‘خواہ دوسروں کو ہم پر ترجیح دی جائے۔اور ہم صاحبان اقتدار سے ان کا اقتدار نہیں چھینیں گے۔اور ہم جہاں کہیں بھی ہوں‘حق بات پر قائم رہیں گے۔اور ہم ا اللہ تعالیٰ(کی اطاعت) کے بارے میں کسی ملامت کرنے والے کی ملامت کی پروانہیں کریں گے۔شعبہ نے کہا:حیث ما کان کے الفاظ سیارنے ذکر نہیں کیے‘یحییٰ نے ذکر کیے ہیں۔(سیارنے صرف وان نقول بالحق کے الفاظ کہے ہیں۔)شعبہ نے کہا:اگر میں نے اس میں کچھ زیادتی کی ہے تو وہ سیار یا یحییٰ کی طرف سے ہے۔","f2":"’ترجیح دی جائے‘‘ظاہر ہے سب لوگوں کو عہدے نہیں دیے جاسکتے‘خواہ اہل ہی ہوں‘پھرا امیر سے غلطی بھی ممکن ہے کہ وہ ہر شخص سے اس کے مرتبے کے مطابق سلوک نہ کرسکے۔ایسی صورت میں کوئی کہہ سکتا ہے کہ فلاں کو مجھ پر ترجیح دی گئی ہے اور مجھ سے میرے مقام ومرتبے کے مطابق سلوک نہیں کیا گیا۔لیکن اتنی بات سے امیر سے بغاوت یا اس کی نافامائی کو جائزقرار نہیں دیا جاسکتا لہٰذاایسے حالات میں بھی امیر سے وفادار رہنا ہوگا اور اس کی اطاعت کرنا ہوگی ورنہ وہ شرعاََ سزا لا حق دار ہوگا۔جس رسول ا اللہ صلی اللہ علیہ وسلم کی وفات کے بعد امارت وحکومت قریش مہاجرین ہی کو ملی‘انصار محروم رہے مگر آفرین ہے ان مخلص ترین لوگوں پر کہ انھوں نے اپنے شہر میں اور اکثریت میں ہونے کے باوجود قریش کی امارت کو دل وجان سے تسلیم کیا اور کبھی مخالفت کانہیں سوچا۔"}],[4155,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم پر (امیر و حاکم کی) اطاعت لازم ہے۔ خوشی میں، غمی میں، تنگی میں، خوشحالی میں اور دوسروں کو تم پر ترجیح دئیے جانے کی حالت میں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا:’’(اے ابوہریرہ!) تو اپنی پسند و ناپسند اور ہر تنگی وآسانی میں امیر کی اطاعت پر کار بند رہنا اگرچہ تجھ پر دوسروں کو ترجیح دی جائے۔‘‘"}],[4156,"جریر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے ہر مسلمان کے ساتھ خیر خواہی کرنے پر بیعت کی ۱؎۔\n§وضاحت\n۱؎: \" نصیحت \" کے معنی ہیں: خیر خواہی، کسی کا بھلا چاہنا، یوں تو اسلام کی طبیعت و مزاج میں ہر مسلمان بھائی کے ساتھ خیر خواہی و بھلائی داخل ہے، مگر آپ صلی اللہ علیہ وسلم کبھی کسی خاص بات پر بھی خصوصی بیعت لیا کرتے تھے، اسی طرح آپ کے بعد بھی کوئی مسلم حکمراں کسی مسلمان سے کسی خاص بات پر بیعت کر سکتا ہے، مقصود اس بات کی بوقت ضرورت و اہمیت اجاگر کرنی ہوتی ہے۔","الألباني: صحيح",{"u2":"حضرت جریر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کی کہ ہر مسلمان کی خیر خواہی کروں گا۔","f2":"ترجمہ الباب کے ساتھ حدیث مبارکہ کی مناسبت بالکل واضح ہے کہ خیر خواہی کے جذبے کے ساتھ ہر شرعی امیر کی بیعت مشروع ہے اور شرعی امیر پر اعتماد کا اظہار بھی لہٰذا مقدور بھر اس عہد کی باری تعالیٰ ہے:لفظ’’مسلم‘‘کے عموم کی وجہ سے ہر چھوٹے بڑے امیر غریب عالم جاہل‘مرد عورت‘ کالے گورے ‘آقا وملازم استادک وشاگر‘عربی عجمی اور عزیز واقارب ‘نیز رشتہ دار کی خیر خواہی کرنا اور اسے نصحیت کرنا فرض ہے۔معلوم ہوا کسی بھی مسلمان کے لیے دھوکا دینا‘ملاوٹ کرنا‘بددیانتی اور خیانت کرنا‘دوسرے مسلمان سے کینہ ولغض اور حسد وعناد رکھنا‘کسی کی غیبت کرنا اور چغلی کھانا‘نیز اس کی بابت کسی بھی قسم کے نقصان کا سوچنا قطعاََ ناجائز اور حرام بلکہ تقاضائے ایمان کے بھی منافی ہے۔ایک اور فرمان رسول ہے۔:’’تم میں سے کوئی شخص(اس وقت تک) مومن نہیں ہوسکتا جب تک اپنے بھائی کے لیے وہی کچھ نہ چاہے جو اپنے لیے چاہتا ہے۔‘‘دنیا وآخرت کو کار آمداور قیمتی بنانے ‘نیز ابدی اور لازوال زندگی کو پر سکون اور آرام دہ گزارنے کے لیے ضروری ہے کہ انسان تمام انسانوں کو خیر خواہ رہے اس اس نصیحت و خیر خواہی کا دامن کسی بھی وقت نہ چھوڑے بلکہ تاحیات اس کو حرز جاں بنائے رکھے۔"}],[4157,"جریر رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے بیعت کی سمع و طاعت (بات سننے اور اس پر عمل کرنے) پر اور اس بات پر کہ میں ہر مسلمان کے ساتھ خیر خواہی کروں گا۔","الألباني: صحيح",{"u2":"حضرت جریر رضی اللہ عنہ نے فرمایا:میں نے رسول ا اللہ صلی اللہ علیہ وسلم کی اس بات پر بیعت کی کہ آپ کی بات سنوں گا اور مانوں گا اور ہر مسلمان سے خیر خواہی کروں گا۔","f2":"خیر خواہی کا مطلب یہ ہے کہ دوسرے مسلماں سے بھلا کروں گا اور اسے فائدہ پہنچاؤں گا‘خواہ اپنا نقصان ہوجائے۔"}],[4158,"جابر کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم سے موت پر نہیں بلکہ میدان جنگ سے نہ بھاگنے پر بیعت کی ۱؎۔\n§وضاحت\n۱؎: موت پر بیعت کرنے کی ضرورت اس لیے نہیں ہے کہ موت اللہ کے سوا کسی کے اختیار میں نہیں ہے اور نہ ہی کسی مومن کے لیے جائز ہے کہ جان بوجھ کر اپنی جان دیدے۔ ہاں جنگ سے نہ بھاگنا ہر ایک کے اپنے اختیار کی بات ہے اس لیے آپ سے لوگوں نے میدان جنگ سے نہ بھاگنے پر خاص طور سے بیعت کی :(نیز دیکھئیے اگلی حدیث اور اس کا حاشیہ )۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ فرماتے تھے کہ ہم رسول ا اللہ صلی اللہ علیہ وسلم سے بیعت (کے الفاظ)پر نہیں کی تھی‘ہم نے صرف اس بات کی بیعت کی تھی کہ (میدان جنگ سے)بھاگیں گے نہیں۔","f2":"موت پر بیعت کرنے کا مطلب بھی یہی ہے کہ ہم ثابت قدم رہیںگے‘بھاگیں گے نہیں کہا تھا کہ اگر چہ مرجائیں۔صرف یہ کہا تھا کہ بھاگیں گے نہیں۔ویسے مفہوم اور نتیجے میں کوئی فرق نہیں۔بعض لوگوں نے موت کا لفظ بھی بولا ہے کہ بھاگیں گے نہیں‘خواہ موت بھی آجائے جیسا کہ آئندہ روایت میں اس کی صراحت ہے۔"}],[4159,"یزید بن ابی عبید کہتے ہیں کہ میں نے سلمہ بن الاکوع رضی اللہ عنہ سے کہا: حدیبیہ کے دن نبی اکرم صلی اللہ علیہ وسلم سے آپ لوگوں نے کس چیز پر بیعت کی؟ انہوں نے کہا: موت پر ۱؎۔\n§وضاحت\n۱؎: موت کسی کے اختیار میں نہیں ہے، اس لیے موت پر بیعت کرنے کا مطلب میدان جنگ سے نہ بھاگنے پر بیعت ہے، ہاں میدان جنگ سے نہ بھاگنے پر کبھی موت بھی ہو سکتی ہے، اسی لیے بعض لوگوں نے کہا کہ \" موت پر بیعت کی \"۔","الألباني: صحيح",{"u2":"حضرت یزیدبن ابی عبید سے منقول ہے کہ میں نے حضرت سلمہ بن اکوع رضی اللہ عنہ سے پوچھا کہ حدیبیہ کے دن تم (یعنی صحابہ)نے کس بات پر بنی اکرم صلی اللہ علیہ وسلم سے بیعت کی تھی؟انھوں نے فرمایا:موت پر۔","f2":"موت پر بیعت کا مفہوم سابقہ رویت میں بیان ہوچکا ہے اور دونوں روایات میں تطبیق بھی کہ بعض صحابہ نے بیعت کے موقع پر موت کے لفظ بولے تھے اور بعض نے نہیں۔یہ واقعہ بیعت رضوان کا ہے جو صلح حدیبیہ کے موقع پر لی گئی۔حدیبیہ مکہ مکرمہ سے کچھ فاصلے پر ایک جگہ کا نام ہے جسے آج کل شمسیہ کہا جاتا ہے۔آلپ نے صلح کی بات چیت کے لیے حضرت عثمان رضی اللہ عنہ کو مکہ مکرمہ بھیجا تھا مگر مشہور ہو گیا کہ انھیں شہید کردیا گیا ہے۔اس وقت یہ بیعت لی گئی تھی۔"}],[4160,"یعلی بن ابی امیہ رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس فتح مکہ کے دن ابوامیہ کو لے کر آیا اور میں نے عرض کیا: اللہ کے رسول! میرے باپ نے ہجرت پر بیعت کر لی ہے۔ تو آپ نے فرمایا: \"میں ان سے جہاد پر بیعت لیتا ہوں اور ہجرت کا سلسلہ تو بند ہو گیا\" ۱؎۔\n§وضاحت\n۱؎: یعنی مکہ سے ہجرت کا سلسلہ بند ہو گیا کیونکہ مکہ تو دارالاسلام بن چکا ہے، البتہ دارالحرب سے دارالاسلام کی طرف ہجرت کا سلسلہ قیامت تک جاری رہے گا۔","الألباني: ضعيف",{"u2":"حضرت یعلیٰ بن امیہ رضی اللہ عنہ سے مروی ہے کہ میں فتح مکہ کے دن اپنے والد حضرت امیہ رضی اللہ عنہ کے ساتھ رسول ا اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور میں نے کہا:اے ا اللہ کے رسول!میرے والد سے ہجرت کی بیعت لے لیجیے۔رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا:’’میں ان سے جہاد کی بیعت لیتا ہوں۔ہجرت تو اب ختم ہوچکی۔‘‘","f2":"’’ختم ہوچکی ‘‘مراد مکہ مکرمہ سے ہجرت ہے کیونکہ مکہ مکرمہ فتح کے بعد دارالاسلام بن گیا تھا۔اب وہاں سے ہجرت کرنے کی کوئی ضرورت نہیں تھی‘البتہ اگر کوئی علاقہ کافروں کے قبضے میں ہوا اور وہ مسلمانوں کو اپنے دین پر آزادی سے عمل نہ کرنے دیں تو وہاں سے مسلمانوں کے لیے دارالاسلام کی طرف ہجرت کرجانا اب بھی ضروری ہے۔"}],[4161,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا (اور اس وقت آپ کے اردگرد صحابہ کی ایک جماعت تھی): \"تم مجھ سے اس بات پر بیعت کرو کہ اللہ کے ساتھ شرک نہ کرو گے، چوری نہیں کرو گے، زنا نہیں کرو گے، اپنے بچوں کو قتل نہیں کرو گے، اور اپنی طرف سے گھڑ کر کسی پر بہتان نہیں لگاؤ گے، کسی معروف (بھلی بات) میں میری نافرمانی نہیں کرو گے۔ (بیعت کے بعد) جو ان باتوں کو پورا کرے گا تو اس کا اجر اللہ کے ذمے ہے، تم میں سے کسی نے کوئی غلطی کی ۱؎ اور اسے اس کی سزا مل گئی تو وہ اس کے لیے کفارہ ہو گی اور جس نے غلطی کی اور اللہ نے اسے چھپائے رکھا تو اس کا معاملہ اللہ کے پاس ہو گا، اگر وہ چاہے تو معاف کر دے اور چاہے تو سزا دے۔ احمد بن سعید نے اسے کچھ اختلاف کے ساتھ روایت کیا ہے ۲؎۔\n§وضاحت\n۱؎: یعنی شرک کے علاوہ، کیونکہ توبہ کے سوا شرک کا کوئی کفارہ نہیں ہے۔ ۲؎: یہ اختلاف اس طرح ہے کہ احمد بن سعید کی روایت :(جو آگے آ رہی ہے ) میں صالح بن کیسان اور زہری کے درمیان حارث بن فضیل کا اضافہ ہے، اور زہری اور عبادہ بن صامت کے درمیان ابوادریس خولانی کا اضافہ نہیں ہے، اس اختلاف سے اصل حدیث کی صحت میں کوئی فرق نہیں پڑتا۔","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ عنہ سے مروی ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم کے ارد گرد صحابہ کرام کی ایک جماعت تھی کہ آپن نے فرمایا:’’مجھ سے بیعت کرو کہ ا اللہ تعالیٰ کے ساتھ کسی کو شریک نہیں ٹھہراؤ گے‘چوری نہیں کرو گے زنا نہیں کرو گے‘اپنی اولاد کو قتل نہیں کرو گے‘کسی پر اپنی طرف سے گھڑا کر جھوٹ وبہتان نہیں باندھو گے اور کسی نیکی کے کام میں میری نافرمانی نہیں کروگے‘پھر جوشخص اس عہد کو پورا کرے گا‘اس کا اجروثواب ا اللہ تعالیٰ کے ذمے ہے۔اور تم میں سے جس شخص نے ان میں کوئی کام کرلیا اور اس کو (دنیا میں)اس کی سز امل گئی تو وہ سزا اس کے گناہ کو مٹا دے گی۔اور جس شخص نے ان میں سے کوئی کام کیا‘پھر ا اللہ تعالیٰ نے اس کے گناہ پر پردہ ڈال دیا تو اس کامعاملہ ا اللہ تعالیٰ کے سپرد ہے‘چاہے معاف فرمائے‘چاہے سزادے۔‘‘احمد بن سعید نے(عبید ا اللہ بن سعد کی)امخالفت کی ہے۔","f2":"یہ حدیث مبارکہ جس بیعت پر دلالت کرتی ہے وہ بیعت اسلام ہے جو رسول ا اللہ صلی اللہ علیہ وسلم کے ساتھ خاص تھی‘اب کسی سے یہ بیعت لینا جائز نہیں کیونکہ رسول ا اللہ صلی اللہ علیہ وسلم کے بعد کسی سے یہ بیعت مبارکہ سے معلوم ہوتا ہے کہ جس شخص پر دنیا میں اس کے جرم کی حدک قائم ہوجائے(اسے اپنے جرم کی شرعی سزامل جائے)تو یہ سزااس مجرم کے لیے کفارہ بن جاتی ہے۔جمہور اہم علم کا بھی یہی قول ہے‘البتہ بعض اہل علم اقامت حد کے اعتبار سے مضبوط ہے۔یہ روایت امام نسائی رحمہ اللہ نے دوستادوں‘ یعنی عبید ا اللہ سعد اور احمد بن سعید سے بیان کی ہے۔استاد احمد بن سعید نے اپنی روایت میں امام نسائی رحمہ اللہ کے دوسرے استاد عبید بن سعد کی مخالفت کی ہے اور وہ اس طرح کہ جب عبید ا اللہ بن سعد یہ روایت بیان کرتے ہیں تو وہ ابن شہاب (امام زہری)اور حضرت عبادہ بن صامت رضی اللہ عنہ کے درمیان ابوادریس خولانی کا واسطہ ذکر کرتے ہیں اور جب احمد بن سعید یہ روایت بیان کرتے ہیں تو وہ ابو ادریس خولانی کا واسطہ ذکر نہیں کرتے بلکہ ابن شہاب رحمہ اللہ حضرت عبادہ بن صامت رضی اللہ عنہ کاشاگرد بناتے ہیں‘حالانکہ امام زہری(ابن شہاب)نے حضرت عبادہ رضی اللہ عنہ کو نہیں پایا۔اس طرح یہ روایت منقطع بھی ہے۔"}],[4162,"عبادہ بن صامت رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم مجھ سے ان باتوں پر بیعت نہیں کرو گے جن پر عورتوں نے بیعت کی ہے کہ تم اللہ کے ساتھ کسی چیز کو شریک نہیں کرو گے، نہ چوری کرو گے، نہ زنا کرو گے، نہ اپنے بچوں کو قتل کرو گے اور نہ خود سے گھڑ کر بہتان لگاؤ گے، اور نہ کسی معروف (اچھے کام) میں میری نافرمانی کرو گے؟\"، ہم نے عرض کیا: کیوں نہیں، اللہ کے رسول! چنانچہ ہم نے ان باتوں پر آپ سے بیعت کی، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اس کے بعد کوئی گناہ کیا اور اسے اس کی سزا مل گئی تو وہی اس کا کفارہ ہے، اور جسے اس کی سزا نہیں ملی تو اس کا معاملہ اللہ کے پاس ہے، اگر چاہے گا تو اسے معاف کر دے گا اور چاہے گا تو سزا دے گا\"۔","الألباني: صحيح لغيره",{"u2":"حضرت عبادہ بن صامت رضی اللہ عنہ سے روایت ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا:’’کیا تم ان کاموںکی مجھ سے بیعت نہیں کرتے جن کی عورتوں نے بیعت کی ہے؟کہ تم ا اللہ تعالیٰ کے ساتھ کسی وک شریک نہیں ٹھہراؤ گے‘ چوری نہیں کرو گے‘زنانہیں کرو گے‘ اپنی اولاد کو قتل نہیں کروگے‘کسی پر اپنی طرف سے گھڑکر بہتان نہیں باندھو کروگے اور کسی اچھے کام میں میری نافرانی نہیں کرو گے۔‘‘ہم نے کہا:اے ا اللہ کے رسول! کیوں نہیں؟(ہم بیعت کریں) پھر ہم ان کاموں پر رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کی۔رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا:’’اس کے بعد جس نے ان میں سے کوئی کام کیا اور اس کو سزا مل گئی تو وہ سزا اس کا معاملہ ا اللہ تعالیٰ دے گی اور جس کو(دنیا میں) سزا نہ ملی تو اس کا معاملہ ا اللہ تعالیٰ کے سپرد ہے‘چاہے وہ اسے معاف فرمادے‘چاہے سزادے۔‘‘","f2":"یہ روایت اور سابقہ روایت متعلقہ باب سے تعلق نہیں رکھتیں کیو نکہ ان میں جہاد کا کوئی ذکر نہیں‘البتہ اصل باب‘یعنی بیعت سے مسائل سے تعلق ہے۔الا یہ کہ کہا جائے کہ’’اچھے اور نیکی کے کام‘‘میں جہاد بھی داخل ہے،’’عورتوں نے بیعت کی‘‘جب کوئی عورت مکہ سے ہجرت کرکے آپ کے پاس پہنچتی اور مسلمان ہوتی تو آپ اس سے مندرجہ بالا الفاظ کے ساتھ بیعت لیتے تھے،سورہ ممتحنہ ‘‘آیت نمبر:۱۴ میں آپ کو ان الفاظ کے ساتھ عورتوں سے بیعت لینے کا حکم دیا گیا تھا مگر یادر ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے کسی عورت سے معروف بیعت(درست مبارک سے)نہیں لی بلکہ آپ عورتوں سے صرف زبانی بیعت لیتے تھے۔ساری زندگی آپ کادست مبارک کسی غیر محرم عورت کے ہاتھ کو نہیں لگا۔’’کسی اچھے کام میں ‘‘یہ لفظ عرفاََ آگئے ہیں ورنہ یہ ممکن ہی نہیں کہ رسول ا اللہ صلی اللہ علیہ وسلم کسی برے کام کا حکم دیں۔’’مٹا دے گی‘‘معلوم ہوا کہ دنیا میں ملنے والی شرعی سزا گناہ کو مٹا دیتی ہے۔ا اللہ تعالیٰ اس کی پوچھ گچھ نہیں فرمائے گا۔ احناف کے نزدیک گناہ کی معافی کیک لیے توجہ بھی ضروری ہے۔سزا تو صرف آئندہ روکنے اور عبرت کے لیے ہے لیکن حدیث کے ظاہر الفاظ اس کے خلاف ہیں۔’’ا اللہ تعالیٰ کے سپرد ہے‘‘پردہ پوشی کے بعد ا اللہ تعالیٰ کی رحمت سے امید یہی ہے کہ معاف فرمادے گا بشر گناہ کاارتکاب کرنے والا پردہ پوشی سے فائدہ اٹھاتے ہوئے سچی توبہ کرے۔"}],[4163,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر کہا: میں آپ کے پاس آیا ہوں تاکہ آپ سے ہجرت پر بیعت کروں، اور میں نے اپنے ماں باپ کو روتے چھوڑا ہے، آپ نے فرمایا: \"تم ان کے پاس واپس جاؤ اور انہیں جس طرح تم نے رلایا ہے اسی طرح ہنساؤ\" ۱؎۔\n§وضاحت\n۱؎: نبی اکرم صلی اللہ علیہ وسلم نے ہجرت پر بیعت کرنے سے انکار نہیں کیا، صرف اس آدمی کے مخصوص حالات کی بنا پر ہجرت کی بجائے ماں باپ کی خدمت میں لگے رہنے کی ہدایت کی، اس لیے اس حدیث سے ہجرت پر بیعت لینے کا جواز ثابت ہوتا ہے۔","الألباني: صحيح",{"u2":"حضرت عبدا اللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نبی اکرم صلی اللہ علیہ وسلم کے پاس حاضر ہوااور کہنے لگا کہ میں آپ سے ہجرت پر بیعت کرنے آیا ہوں جبکہ میں اپنے ماں باپ کو روتا چھوڑ آیا ہوں۔آپ نے فرمایا:’’ان کے پاس واپس جااور جیسے تو نے انھیں رلایا ہے اسی طرح انھیں ہنسا۔‘‘","f2":"ہجرت پر بیعت لینا مشروع نہیں رہا‘ہاں دار کفر سے دار اسلام کی طرف ہجرت باقی ہے لیکن بغیر بیعت کے۔ترجمتہ الباب یعنی ہجرت پر بیعت کے ساتھ حدیث کی مناسبت اس طرح بنتی کہ وجہ سے بیعت نہیں لی۔اگر اس کے والدین کا مسئلہ نہ ہوتا تو آُ بیعت لے لیتے۔والاین کی نافرمانی اور ان کوایذا پہنچانا حرام اور ناجائز ہے۔اسی طرح اگر جہازد کی فرضیت کے حالات بھی نہ ہوں تو اجازت کے بغیر جانا درست نہیں۔ہر دار کفر سے ہجرت کرنا فرض نہیں اگر قبضہ کافروں کا ہومگر وہ دینی امور میں رکاوٹ نہ ڈالتے ہوں تو وہاں سے ہجرت فرض نہیں جیسا کہ رسول ا اللہ صلی اللہ علیہ وسلم نے مسلمانوں کو خود حبشہ بھیجا‘حالانکہ وہاں عیسائیوں کی حکومت تھی۔"}],[4164,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ ایک اعرابی نے رسول اللہ صلی اللہ علیہ وسلم سے ہجرت کے متعلق سوال کیا تو آپ نے فرمایا: \"تمہارا برا ہو۔ ہجرت کا معاملہ تو سخت ہے۔ کیا تمہارے پاس اونٹ ہیں؟\" اس نے کہا: جی ہاں۔ آپ نے فرمایا: \"کیا تم ان کی زکاۃ نکالتے ہو؟\" کہا: جی ہاں، آپ نے فرمایا: \"جاؤ، پھر سمندروں کے اس پار رہ کر عمل کرو، اللہ تمہارے عمل سے کچھ بھی کم نہیں کرے گا\" ۱؎۔\n§وضاحت\n۱؎: مفہوم یہ ہے کہ تمہاری جیسی نیت ہے اس کے مطابق تمہیں ہجرت کا ثواب ملے گا تم خواہ کہیں بھی رہو۔ اس حدیث سے یہ بھی معلوم ہوا کہ ہجرت ان لوگوں پر واجب ہے جو اس کی طاقت رکھتے ہوں۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ ایک اعرابی نے رسول ا اللہ صلی اللہ علیہ وسلم سے ہجرت کی اجااز طلب کی۔آپ نے فرمایا:’’ا اللہ تجھ پر رحم کرے!ہجرت بہت مشکل کام ہے۔کیا تیرے پاس اونٹ ہیں؟‘‘اس نے کہا:جی ہاں۔آپ نے فرمایا:’’کیا تو ان کی زکاۃ دیتاہے؟‘‘اس نے کہا:جی ہاں۔آپ نے فرمایا:’’بستیوں سے باہر رہ کرنیکی کے کام کرتارہ۔یقینا ا اللہ تعالیٰ(ہجرت نہ کرنے کی بناپر)تیرے کے ثواب میں کوئی کمی نہیں کرے گا۔‘‘","f2":"باب کے ساتھ حدیث کی مناسبت اس طرح ہے کہ ہجرت کرناانتہائی شکل اور عزیمت وعظمت والا کام ہے‘ایسے لوگ بھی عظیم اور جلیل القدر ہیں‘تاہم یہ ہر ایک کے بس کا معاملہ نہیں بسا اوقات راہ ہجرت میں پیش آمدہ مشکلات سے انسان گھبراجاتا ہے اور اپنی ہجرت پر نادم ہوتا ہے جس سے اس کی ہجرت یقینا متاثر وہتی ہے۔اونٹوں کی زکاۃ ادا کرنا فضیلت والا عمل ہے۔مذکورہ حدیث سے صحرا نشینوں اور اعرابیوں کے لیے ان پر ہجرت فرض نہیں تھی جبکہ مکہ شہروالوں پر ہجرت فرض تھی۔"}],[4165,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ ایک شخص نے کہا: اللہ کے رسول! کون سی ہجرت زیادہ بہتر ہے؟ آپ نے فرمایا: \"یہ کہ وہ تمام چیزیں چھوڑ دو جو تمہارے رب کو ناپسند ہیں\"، اور فرمایا: \"ہجرت دو قسم کی ہے: ایک شہری کی ہجرت اور ایک اعرابی (دیہاتی) کی ہجرت، رہا اعرابی تو وہ جب بلایا جاتا ہے آ جاتا ہے اور اسے جو حکم دیا جاتا ہے مانتا ہے، لیکن شہری کی آزمائش زیادہ ہوتی ہے، اور اسی (حساب سے) اس کو بڑھ کر ثواب ملتا ہے ۱؎۔\n§وضاحت\n۱؎: اس حدیث کا خلاصہ یہ ہے کہ حقیقی ہجرت تو اللہ تعالی نے جن چیزوں سے روکا ہے اس کا چھوڑنا ہی ہے، خود ترک وطن بھی ممنوع چیزوں سے بچنے کا ایک ذریعہ ہے، اور شہر میں رہنے والے سے زیادہ اعرابی :(دیہاتی ) کے لیے وطن چھوڑنا آسان ہے، کیونکہ آبادی میں رہنے والوں کے معاشرتی مسائل بہت زیادہ ہوتے ہیں اس لیے ان کے لیے ترک وطن بڑا ہی تکلیف دہ معاملہ ہوتا ہے، اور اسی لیے ان کی ہجرت :(ترک وطن ) کا ثواب بھی زیادہ ہوتا ہے۔","الألباني: صحيح",{"u2":"حضرت عبدا اللہ بن عمرو رضی اللہ عنہ سے مروی ہے کہ ایک آدمی نے کہا:اے ا اللہ کے رسول!ہجرت کون سی افضل ہے؟آپ نے فرمایا:’’یہ کہ تو ان کوموں کو چھوڑدے جنھیں تیرا رب تعالیٰ ناپسند فرماتا ہے۔‘‘نیز رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ہجرت دوقسم کی ہوتی ہے۔ایک تو شہری کی ہجرت‘دوسری بدوی(اعرابی)کی ہجرت۔بدوی کاکام یہ ہے کہ جب اسے بلایا جائے تو وہ آجائے اور جب اسے حکم دیا جائے تو وہ اطاعت کرے لیکن شہری کو مشقت بھی زیادہ ہے اور ثواب بھی۔‘‘","f2":"’’ان کاموں کو چھوڑ دے ‘‘ہجرت کے لغوی معنی چھوڑ دینے کے ہیں۔معرف ہجرت میں گھر بار‘رشتہ دارو اور مال ومنال چھوڑا جاتا ہے۔آپ نے اس لحاظ سے فرمایا کہ افضل ہجرت گناہوں کو چھوڑنا ہے کیونکہ ہجرت بھی تودین کے تحفظ کے لیے کی جاتی ہے۔گناہوں کے چھوڑنے سے بھی دین محفوظ ہوجاتا ہے۔اگر گناہ نہ چھوڑنا‘وطن چھوڑنے سے بہتر ہے اور ہجرت میں بھی وطن چھوڑنے کا اصل مقصد تو گناہ چھوڑنا اور اپنے ایمان کی حفاظت کرنا ہی ہے۔’’جب اسے بلایا جائے‘‘یعنی جب اسے جہاد کے لیے بلایا جائے تو وہ آجائے۔اور اپنے گھر میں رہ کر شریعت پر عمل کرتا رہے۔گاؤں اور قبائل کے رہنے والوں پر ہجرت فرض نہٰں تھی جبکہ مکہ شہر میں رہنے والے مسلمانوں پر ہجرت فرض تھی لہٰذا شہری کے لیے مشقت بھی زیادہ اور اس کا اجر بھی زیادہ تھا۔"}],[4166,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم، ابوبکر اور عمر مہاجرین میں سے تھے۔ اس لیے کہ انہوں نے مشرکین (ناطے داروں) کو چھوڑ دیا تھا۔ انصار میں سے (بھی) بعض مہاجرین تھے اس لیے کہ مدینہ کفار و مشرکین کا گڑھ تھا اور یہ لوگ (شرک کو چھوڑ کر) عقبہ کی رات رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تھے ۱؎۔\n§وضاحت\n۱؎: یعنی: ہجرت کے اصل معنی کے لحاظ سے مہاجرین و انصار دونوں ہی \" مہاجرین \" تھے۔ ترک وطن کا مقصد اصلی شرک کی جگہ چھوڑنا ہی تو ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول ا اللہ صلی اللہ علیہ وسلم اور ابوبکر وعمر رضی اللہ عنہ اس لیے مہاجر تھے کہ انھوں نے مشرکین(اور ان کے علاقے)کو چھوڑ دیا تھا۔اور انصار میں سے بھی لوگ مہاجر تھے کیو نکہ مدینہ بھی(آپ کی تشریف آوری سے پہلے)شرک اور مشرکین کا علاقہ تھا‘چنانچہ کچھ انصار عقبہ کی رات رسول ا اللہ صلی اللہ علیہ وسلم کے پاس (مکہ مکرمہ)چلے آئے تھے۔","f2":"حضرت ابن عباس رضی اللہ عنہ انتہائی ذہین شخص تھے۔انھوں نے یہ لطیف نکتہ پیدا کیا کہ اگر گھر بار چھوڑ کر جانے کی وجہ سے کوئی شخص مہاجربن سکتا ہے تو وہ انصار جو بیعت کرنے کے لیے مکہ مکرمہ پہنچے تھے‘وہ بھی مہاجر تھے کیونکہ وہ مدینہ چھوڑ کرآپ کے پاس گئے تھے اور آپ کے حکم سے دوبار مدینہ آئے تھے۔اسی طرح مہاجرین کو بھی انصار کہاجاسکتا ہے کیونکہ انھوں نے ہر موقع پر آپ کا ساتھ دیا اور آپ مدد کی۔اور مدد کرنے والوں کو لغت کے لحاظ سے انصار کہاجاسکتا ہے۔یہ صرف ایک نکتہ ہے ورنہ حقیقت یہ ہے کہ مہاجرین وہی تھے جنھوں نے ہمیشہ کے لیے اپنے گھر بار چھوڑ دیے۔حتیٰ کہ مکہ فتح ہونے پر باوجود دارالاسلام بن جانے کے وہاں ٹہرنا پسند نہ کیا۔اور انصار وہی تھے جنھوں نے اپنا شہر‘اپنے گھر اپنی زمینیں‘اپنی جائیدادیں حتیٰ کہ اپنی جانیں رسول ا اللہ صلی اللہ علیہ وسلم کو پیش کردیں۔’’عقبہ کی رات‘‘یہ رات دارصل دو راتیں تھیں۔ایک ۲۱ نبوت میں جسے لیلہ عقبہ اولیٰ کہاجاتا ہے اور دوسری۱۳ بنوت میںجسے لیلہ عقبہ ثانیہ کہاجاتا ہے۔عقبہ منیٰ سے مکہ کی طرف آخری کمرے کا نام ہے۔اس جمرے کے پاس رسول ا اللہ صلی اللہ علیہ وسلم نے مدینہ والوں کو اسلام کی دعوت دی تھی،یہ ۱۱ نبوت کی بات ہے۔وہ چھ آدمی تھے،انھوں نے آئندہ سال آپ نے ملنے کا وعدہ کیا اور دمدینہ جاکر آپ کی دعوت مدینہ والوں کے سامنے پیش کی۔۱۲ نبوت میں حج کے بعد بارہ آدمی اس جمرے کے پاس آپ کو ملے‘اسلام قبول کیا اور آپ کی بیعت کی۔آپ نے ان کے ساتھ مبلغ بھی بھیج دیا۔اگلے سال۱۳ نبوت میں حج کے بعد اسی جمرے کے پاس ستر(۷۰)سے زیادہ انصار نے آپ کی بیعت کی اور آپ سے مدینہ چلنے کی درخواست کی۔آپ نے اسے قبول فرمایا اور مناسب وقت پر مدینہ منورہ تشریف لے گئے۔"}],[4167,"ابوفاطمہ رضی اللہ عنہا کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! مجھے ایسا کام بتائیے جس پر میں جما رہوں اور اس کو کرتا رہوں، رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"تم پر ہجرت لازم ہے کیونکہ اس جیسا کوئی کام نہیں\" ۱؎۔\n§وضاحت\n۱؎: یہ فرمان ابوفاطمہ اور ان جیسے لوگوں کے حالات کے لحاظ سے انہیں کے ساتھ خاص تھا، آپ صلی اللہ علیہ وسلم بہت سے اعمال و افعال کو سائل کے حالات کے لحاظ سے زیادہ بہتر اور اچھا بتایا کرتے تھے۔","الألباني: حسن صحيح",{"u2":"حضرت ابو فاطمہ رضی اللہ عنہا سے منقول ہے کہ انھوں نے کہا:اے ا اللہ کے رسول!مجھے کوئی ایسا کام بتایئے جس پر میں قائم رہوں اور اسے جاری رکھوں۔آپ نے فرمایا:’’ہجرت کر۔ (اس وقت تیرے حق میں) اس کے برابر کوئی اور کام نہیں۔‘‘","f2":"وقت وقت کی بات ہے۔کسی وقت ہجرت افضل ہے‘کبھی جہاد اور کبھی کوئی اور کام۔اسی طرح آدمی آدمی کا فرق ہوترا ہے۔کسی آدمی کے لیے ہجرت افضل ہے‘کسی کے لیے کوئی اور کام جیسے آپ نے اعرابی کو ہجرت سے روک دیا تھا۔ (دیکھیے‘ حدیث: ۴۱۶۸، ۴۱۶۹)"}],[4168,"یعلی رضی اللہ عنہ کہتے ہیں کہ فتح مکہ کے روز میں رسول اللہ صلی اللہ علیہ وسلم کے پاس اپنے والد کے ساتھ آیا، میں نے عرض کیا: اللہ کے رسول! میرے باپ سے ہجرت پر بیعت لے لیجئے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں ان سے جہاد پر بیعت لوں گا، (کیونکہ) ہجرت تو ختم ہو چکی ہے\"۔","الألباني: ضعيف",{"u2":"حضرت یعلیٰ رضی اللہ عنہ بیان کرتے ہیں کہ میں کے پاس حاضر ہوا اورمیں نے کہا:اے ا اللہ کے رسول! میرے والد سے ہجرت کی بیعت لے لیجیے۔رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا:’’میں ان سے جہاد کی بیعت لیتا ہوں۔ ہجرت تو اب ختم ہو چکی ہے۔ ‘‘","f2":"تفصیل کے لیے دیکھیے ‘ حدیث:"}],[4169,"صفوان بن امیہ رضی اللہ عنہ کہتے ہیں کہ میں نے کہا: اللہ کے رسول! لوگ کہتے ہیں کہ جنت میں مہاجر کے علاوہ کوئی داخل نہیں ہو گا، آپ نے فرمایا: \"فتح مکہ کے بعد اب ہجرت نہیں ہے ۱؎، البتہ جہاد ۲؎ اور نیت ہے، لہٰذا جب تمہیں جہاد کے لیے بلایا جائے تو نکل پڑو\"۔\n§وضاحت\n۱؎: نبی اکرم صلی اللہ علیہ وسلم کے عہد مبارک میں یہ حکم اہل مکہ کے لیے خاص تھا کہ اب مکہ سے مدینہ ہجرت کی ضرورت باقی نہیں رہی، ورنہ اس کے علاوہ جہاں بھی ایسی ہی صورت پیش آئے گی ہجرت واجب ہو گی :(دیکھئیے حدیث نمبر ۴۱۷۷ ) إلا یہ کہ وہاں کے ملکی حالات و قوانین اجازت نہ دیتے ہوں، جیسے اس زمانہ میں اب یہ ممکن ہی نہیں بلکہ محال ہے کہ ایک ملک کے شہری کو کوئی دوسرا ملک قبول کر لے تو ہجرت واجب ہوتے ہوئے بھی آدمی اپنے وطن میں رہنے پر مجبور ہے، یہ مجبوری کی حالت ہے۔ ۲؎: یعنی جہاد کی خاطر گھر بار چھوڑنا یہ بھی ایک طرح کی ہجرت ہے، اسی طرح خلوص نیت سے محض اللہ کی رضا حاصل کرنے کے لیے جیسے دینی تعلیم وغیرہ کے لیے گھر سے دور جانا یہ بھی ایک طرح کی ہجرت ہے۔","الألباني: صحيح",{"u2":"حضرت صفوان بن امیہ رضی اللہ عنہ سے روایت ہے کہ میں نے عرض کی: اے ا اللہ کے رسول! لوگ کہتے ہیں کہ مہاجرین کے علاوہ کوئی شخص جنت میں نہیں جائے گا۔آپ نے فرمایا: ’’فتح مکہ کے بعد (مکہ سے) ہجرت (کی کوئی ضرورت) نہیں رہی لیکن جہاد کرو اور نیت رکھو (اگر کبھی ہجرت کرنا پڑی تو کریں گے)اور جب تم سے جہاد کے لیے نکلنے کو کہا جائے تو نکلو۔ ‘‘","f2":"اس حدیث مبارکہ سے معلوم ہوتا ہے کہ اب مستقلاََ گھر بار چھوڑنے کی ضرورت نہیں‘ البتہ جہاد اور دوسرے نیک کاموں کے لیے وقتی طور پر گھروں سے نکلو۔"}],[4170,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے روز فرمایا: \"ہجرت تو (باقی) نہیں رہی البتہ جہاد اور نیت ہے، لہٰذا جب تمہیں جہاد کے لیے بلایا جائے تو نکل پڑو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ بیعت سے متعلق احکام ومسائل رسول ا اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے دن فرمایا: ‘‘ اب (مکہ سے) ہجرت کرنے کی ضرورت نہیں‘ البتہ جہاد کرو اور نیت رکھو۔جب تم سے جہاد کے لیے گھروں سے نکلنے کو کہا جائے تو نکلنے۔‘‘","f2":"1)لا ھجرۃ‘‘اس کے یہ معنی درست نہیں کہ اب ہجرت بالکل ختم ہو چکی ہے‘ کوئی مسلمان دار الکفر میں‘ خواہ کسی بھی حالت میں ہوا‘اس کے لیے دار الا سلام کی طرف ہجرت کرنا جائز نہیں بلکہ اس حدیث کا مطلب یہ ہے کہ فتح مکہ سے ہجرت نہیں جیسا کہ امام نو وی رحمہ اللہ نے فرمایا: ہمارے اصحاب اور دیگر علماء نے کہا ہے: دارالحرب سے سے دار الا سلام کی طرف ہجرت کرنا قیامت تک باقی ہے‘ چنانچہ انھوں نے مذکوہ حدیث مبارکہ کی دو تو جیہیں فرمائی ہیں: ایک تو یہ کہ فتح مکہ کے بعد‘ مکہ سے ہجرت نہیں کیونکہ مکہ دار الا سلام بن چکا ہے‘ اس لیے وہاں سے ہجرت کرنے کا تصور ہی نہیں کیا جا سکتا۔اور دوسری توجیہ یہ کہ وہ فضیلت والی اہم ہجرت جو (ابتدائے اسلام میں) مطلوب تھی اور جس کے فاعل ممتاز حیثیت کے حامل بن گئے‘ اب مکہ سے وہ ہجرت ختم ہوچکی ہے۔ اس ہجرت کا اعزاز جس جس کے مقدر میں تھا‘ وہ ہر اس شخص کو مل چکا ہے جس نے فتح مکہ سے پہلے ہجرت کرلی۔ اب (فتح مکہ کے بعد) ہجرت کرنے کا وہ اعزاز کسی اور کو نہیں مل سکتا‘ اس لیے کہ فتح مکہ کے بعد اسلام معزز اور مضبوط ہوچکا ہے۔دیکھیے: ہجرت کے متعلق کے مزید تفصیل کے لیے دیکھیے:اس حدیث میں ہے کہ اب ہجرت نہیں رہی جبکہ بعد والی احادیث میں ہے کہ ہجرت ختم نہیں ہوسکتی۔ ظاہراََ ان حادیث میں تضاد معلوم ہوتا ہے‘ حالانکہ ان میں کرئی تضاد نہیں بلکہ ان احادیث میں تطبیق ممکن ہے اور وہ اس طرح کہ جن احادیث میں ہے کہ فتح مکہ کے بعد ہجرت ختم ہوچکی ‘ اس مفہوم یہ ہے کہ جو ہجرت فتح مکہ سے پہلے‘ یعنی ابتدائے اسلام میں فرض تھی‘ وہ اب ختم ہوگئی ہے کیونکہ مکہ دار الا سلام بن چکا ہے‘ لہٰذا وہاں سے ہجرت کرنا باقی نہیں رہی۔ اور جن احادیث میں ہے کہ ہجرت ختم نہیں ہوسکتی تو اس کا مطلب ہے کہ ہر دارا لحرب سے‘ دار الا سلام کی طرف ہجرت کرنا باقی ہے۔ اس صورت میں دارا لحرب سے ہر زمانے میں ہجرت کی جائے گی اور ایسی ہجرت قیامت تک باقی ہے۔ اس حدیث مبارکہ سے یہ بھی معلوم ہوتا ہے کہ جہاد فرض عین نہیں بلکہ فرض کفایہ ہے‘ چنانچہ جب کچھ لوگوں کے کرنے سے کفایت ہو جائے تو پھر باقی لوگوں سے جہاد ساقط ہو جائے گا‘ ہاں! اگر تمام لوگ جہاد کرنا چھوڑ دیں تو اس صورت میں سب گناہ گار ہوں گے۔ اس بیعت سے متعلق احکام وسائل حدیث سے یہ بھی معلوم ہوتا ہے کہ جب امام جہاد کے لیے نکلنے کا حکم دے تو ہر اس شخص کے لیے نکلنا ضروری ہو گا جسے امام حکم دے۔ امام قرطبی رحمہ اللہ نے اس مسئلے کے متعلق اہل علم کا اجماع نقل کیا ہے۔ یہ حدیث ہر خیر اور بھلائی کے قول وعمل کا شوق دلاتی ہے، نیز اس سے یہ بھی ثابت ہوتا ہے کہ ہر نیت خیر پر اجرو ثواب ہے، نیز ہر برائی اور عمل شر سے اجتناب کی نیت بھی باعث اجر ہے۔"}],[4171,"عمر بن خطاب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی موت کے بعد کوئی ہجرت نہیں۔","الألباني: صحيح",{"u2":"حضرت عمر بن خطاب رضی اللہ عنہ سے مروی ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم کی وفات بعد ہجرت کی ضرورت نہیں رہی۔","f2":"غالباََ حضرت عمر رضی اللہ عنہ کا مقصود رسول ا اللہ صلی اللہ علیہ وسلم کو قول ہی ہے کہ فتح مکہ کے بعد ہجرت نہیں، ویسے بھی رسول ا اللہ صلی اللہ علیہ وسلم کی وفات فتح مکہ کے زمانے کے قریب ہی تھی۔"}],[4172,"عبداللہ بن وقدان سعدی رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ ہم میں سے ہر ایک کی کچھ غرض تھی، میں سب سے آخر میں آپ کے پاس داخل ہوا اور عرض کیا کہ اللہ کے رسول! میں اپنے پیچھے کچھ ایسے لوگوں کو چھوڑ کر آ رہا ہوں جو کہتے ہیں کہ ہجرت ختم ہو گئی تو آپ نے فرمایا: \"ہجرت اس وقت تک ختم نہیں ہو سکتی جب تک کفار و مشرکین سے جنگ ہوتی رہے گی\" ۱؎۔\n§وضاحت\n۱؎: پچھلی حدیث میں ہے کہ فتح مکہ کے بعد ہجرت ختم ہو گئی، اور اس حدیث میں ہے کہ جب تک دنیا میں اسلام اور کفر کی لڑائی جاری رہے گی تب تک ہجرت جاری رہے گی، دونوں میں کوئی تضاد و اختلاف اور تعارض نہیں ہے، وہاں مراد ہے کہ مکہ سے مدینہ ہجرت کی ضرورت باقی نہیں رہ گئی کیونکہ مکہ فتح ہو کر، اسلامی حکومت میں شامل ہو چکا ہے، رہی دارالحرب سے ہجرت کی بات تو جس طرح فتح مکہ سے پہلے مکہ کے دارالحرب ہونے کی وجہ سے وہاں سے ہجرت ضروری تھی، یہاں بھی ضروری رہے گی، اس بابت اور بھی واضح احادیث مروی ہیں۔","الألباني: صحيح",{"u2":"حضرت عبد ا اللہ بن وقد ان سعدی رضی اللہ عنہ سے روایت ہے کہ ہم ایک دفد کی صورت میں رسول ا اللہ ْ صلی اللہ علیہ وسلم کے پاس حاضر ہوئے۔ ہم میں سے ہر شخص آپ سے کوئی نہ کوئی سوال کرتا تھا۔ میں سب کے بعد رسول ا اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ میں نے عرض کی: اے ا اللہ کے رسول! میں اپنے پیچھے بہت سے لوگ چھوڑ آیا ہوں جو کہتے ہیں کہ اب ہجرت ختم ہو چکی ہے۔آپ نے فرمایا: ’’جب تک کفار سے لڑائی جاری ہے، ہجرت ختم نہیں ہوسکتی۔ ‘‘","f2":"’’ختم نہیں ہوسکتی‘‘ کیونکہ جب تک اسلام وکفر میں آویزش (چپقلش) قائم ہے، کسی نہ کسی علاقے میں مسلمان مظلوم و مقہور رہیں گے، لہٰذادارا لحرب سے دار الا سلام کی طرف سفر جاری رہے گا اوار یہی ہجرت ہے، یا اس سے مراد ہے کہ جہاد کے لیے مسلمان اپنے گھر بار وقتی طور چھوڑتے رہیں گے۔ان دو معانی کی مدد سے ہجرت کے ختم ہونے یا نہ ہونے کے بارے میں مروی روایات میں تطبیق ممکن ہوگی۔"}],[4173,"عبداللہ بن سعدی رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ میرے ساتھی آپ کے پاس داخل ہوئے تو آپ نے ان کی ضرورت پوری کی، میں سب سے آخر میں داخل ہوا تو آپ نے فرمایا: \"تمہاری کیا ضرورت ہے؟\" میں نے عرض کیا: اللہ کے رسول! ہجرت کب ختم ہو گی؟ فرمایا: \"جب تک کفار سے جنگ ہوتی رہے گی ہجرت ختم نہ ہو گی\"۔","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن سعدی رضی اللہ عنہ نے فرمایا:ہم ایک وفد کی صورت میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئے میرے ساتھی(اپنی اپنی باری پر)داخل ہوئے آپ نے ان کی مطلوبہ حاجتیں پوری کیں میں سب سے آخر میں داخل ہوا۔آپ نے فرمایا:’’تجھے کیا کام ہے؟‘میں نے کہا!اے اللہ کے رسول صلی اللہ علیہ وسلم!ہجرت کب ختم ہو گی؟رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:جب تک کافروں سے لڑائی جاری ہے‘ہجرت ختم نہ ہو گی۔"}],[4174,"جریر رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر عرض کیا: میں آپ سے ہر اس چیز میں جو مجھے پسند ہو اور اس میں جو ناپسند ہو سمع و طاعت (سننے اور حکم بجا لانے) پر بیعت کرتا ہوں، آپ نے فرمایا: \"جریر! کیا تم اس کی استطاعت رکھتے ہو، یا طاقت رکھتے ہو؟\" آپ نے فرمایا: \"کہو ان چیزوں میں جن کو میں کر سکتا ہوں، چنانچہ آپ نے مجھ سے بیعت لی، نیز ہر مسلمان کی خیر خواہی پر بیعت لی\"۔","الألباني: صحيح",{"u2":"حضرت جریر رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ سے عرض کی کہ میں آپ سے بیعت کرتا ہوں کہ ہر پسند و ناپسند میں آپ کی بات سنوں گا اور اطاعت کروں گا۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ جریر! تو اس کی طاقت بھی رکھتا ہے؟ ‘‘ اور فرمایا: ’’ تو کہہ اپنی طاقت کہ ہر مسلمان کی خیر خواہی کرنا۔","f2":"’’ اپنی طاقت کے مطابق‘‘ قربان جائیں آپ کی شفقت ورحمت پر کہ خود آسانی کی راہ دکھائی۔"}],[4175,"جریر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے نماز قائم کرنے، زکاۃ ادا کرنے، ہر مسلمان کے ساتھ خیر خواہی کرنے اور کفار و مشرکین سے الگ تھلگ رہنے پر بیعت کی ۱؎۔\n§وضاحت\n۱؎: مسلمانوں کے کفار و مشرکین سے الگ تھلگ رہنے کی بابت اور بھی احادیث مروی ہیں مگر ان کا مصداق اسی طرح کے حالات ہیں جو اس وقت تھے، شریعت نے آدمی کو اس کی طاقت سے زیادہ پابند نہیں کیا ہے، آج کل بہت سے ممالک میں یہ ممکن ہی نہیں ہے کہ مسلمان مشرکین و کفار سے الگ رہیں، حد تو یہ ہے کہ اسلامی ممالک بھی دوسرے ملکوں کے مسلمانوں کو اپنے ملکوں میں آنے نہیں دیتے، صرف چند دنوں کے ویزہ کے مطابق رہنے دیتے ہیں، پھر وقت پر نکل جانے پر مجبور کرتے ہیں۔","الألباني: صحيح",{"u2":"حضرت جریر رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کی نماز قائم کرنے، زکاۃ ادا کرنے، ہر مسلمان کی خیر خواہی کرنے اور مشرکین سے علیحدہ رہنے پر۔"}],[4176,"جریر رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا …، پھر اسی جیسی حدیث بیان کی۔","الألباني: صحيح",{"u2":"حضرت جریر رضی اللہ تعالٰی عنہ نے فرمایا: میں رسول ا اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا۔ پھر راوی نے سابقہ روایت کی طرح بیان کیا۔"}],[4177,"جریر رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، آپ بیعت لے رہے تھے۔ میں نے عرض کیا: اللہ کے رسول! ہاتھ پھیلائیے تاکہ میں بیعت کروں، اور آپ شرط بتائیے کیونکہ آپ زیادہ جانتے ہیں۔ آپ نے فرمایا: \"میں تم سے اس بات پر بیعت لیتا ہوں کہ تم اللہ کی عبادت کرو گے، نماز قائم کرو گے، زکاۃ ادا کرو گے، مسلمانوں کے ساتھ خیر خواہی اور بھلائی کرو گے اور کفار و مشرکین سے الگ تھلگ رہو گے\"۔","الألباني: صحيح",{"u2":"حضرت جریر رضی اللہ تعالٰی عنہ سے منقول ہے، وہ بیان کرتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس حاضر ہوا تو آپ لوگوں سے بیعت لے رہے تھے۔ میں نے عرض کی: اے ا اللہ کے رسول! اپنا ہاتھ بڑھایئے تاکہ میں آپ کی بیعت کروں۔ اور شرطیں آپ خود بتا دیجیے کیونکہ آپ زیادہ جانتے ہیں۔ آپ نے فرمایا: ’’ میں تجھ سے بیعت لیتا ہوں کہ تو ا اللہ وحدہ کی عبادت کرے گا،تماز قائم کرے گا، زکاۃ ادا کرے گا، ہر مسلمان کی خیر خواہی کرے گا اور مشرکین سے جدا رہے گا۔ ‘‘"}],[4178,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ میں نے ایک جماعت کے ساتھ رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی، آپ نے فرمایا: \"میں تم لوگوں سے اس بات پر بیعت لیتا ہوں کہ تم اللہ کے ساتھ کسی کو شریک نہ کرو گے، نہ چوری کرو گے، نہ زنا کرو گے، اور نہ اپنے بال بچوں کو قتل کرو گے، نہ ہی من گھڑت کسی طرح کا بہتان لگاؤ گے، کسی بھی نیک کام میں میری خلاف ورزی نہیں کرو گے، تم میں سے جس نے یہ باتیں پوری کیں تو اس کا اجر و ثواب اللہ کے ذمہ ہے اور جس نے اس میں سے کسی چیز میں غلطی کی ۱؎ پھر اسے اس کی سزا دی گئی تو وہی اس کے لیے کفارہ (پاکیزگی) ہے اور جسے اللہ نے چھپا لیا تو اب اس کا معاملہ اللہ کے پاس ہو گا۔ چاہے تو عذاب دے اور چاہے تو معاف کر دے\"۔\n§وضاحت\n۱؎: شرک کے سوا، اس لیے کہ شرک بغیر توبہ کے معاف نہیں ہو گا۔","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے چند لوگوں کی معیت میں رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کی۔ آپ نے فرمایا: ’’ میں تم سے اس شرط پر بیعت لیتا ہوں کہ تم ا اللہ تعالیٰ کے ساتھ کسی کو شریک نہیں بناؤ گے‘ چوری نہیں کرو گے، زنا نہیں کرو گے، اپنی اولاد کو قتل نہیں کرو گے اور کسی نیک کام میں مری نافرمانی نہیں کرو گے۔ تم میں سے جو شخص اس عہد پر قائم رہا، اس کا اجر وثواب ا اللہ تعالیٰ کام کرلیا، پھر اس کو اس کام کی سزا مل گئی تو اس کا گناہ دھل جائے گا۔ اور جس شخص کی ا اللہ تعالیٰ نے پردہ پوشی کی، تو وہ ا اللہ تعالیٰ کے سپرد ہے۔ چاہے اسے عذاب دے چاہے تواسے معاف فرما دے۔ ‘‘","f2":"اس روایت کا متعلقہ باب سے تو کوئی تعلق نہیں، البتہ اصل باب (بیعت) سے تعلق ہے۔ یہ روایت پیچھے گزر چکی ہے۔ (دیکھیے‘ حدیث: ۴۱۶۷)"}],[4179,"ام عطیہ رضی اللہ عنہا کہتی ہیں کہ جب میں نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کرنی چاہی تو میں نے عرض کیا: اللہ کے رسول! ایک عورت نے زمانہ جاہلیت میں نوحہ (سوگ منانے) میں میری مدد کی تھی تو مجھے اس کے یہاں جا کر نوحہ میں اس کی مدد کرنی چاہیئے، پھر میں آ کر آپ سے بیعت کر لوں گی۔ آپ نے فرمایا:\"جاؤ اس کی مدد کرو\"، چنانچہ میں نے جا کر اس کی مدد کی، پھر آ کر رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی ۱؎۔\n§وضاحت\n۱؎: کیونکہ بیعت کے بعد وہ نوحہ میں مدد نہیں کر سکتی تھیں، جیسا کہ اگلی حدیث میں اس کی صراحت آ رہی ہے، یہ اجازت صرف ام عطیہ رضی اللہ عنہا کے ساتھ خاص تھی اب نبی اکرم صلی اللہ علیہ وسلم کے سوا کسی کو یہ حق نہیں کہ شریعت کے کسی حکم کو کسی کے لیے خاص کرے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ام عطیہ رضی اللہ عنہ فرماتی ہیں کہ جب میں نے رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کرنے کا ارادہ کیا تو میں نے کہا: اے ا اللہ کے رسول! ایک عورت نے دور جاہلیت میں نوحہ کرنے میں مدد کی تھی۔ میں جاکر اس کی مدد کرکے آتی ہوں، پھر آکر آپ کی بیعت کروں گی۔ آپ نے فرمایا: ’’ جا‘ اس کی مدد کرآ۔ ‘‘ میں گئی اور میں نے اس کی مدد کا اسے بدلہ دیا، پھر میں آئی اور رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کی۔","f2":"1۔ترجمتہ الباب کے ساتھ حدیث کی مناسبت بالکل واضح ہے کہ عورتوں سے بیعت لینا مشروع ہے جیسا کہ خود رسول ا اللہ صلی اللہ علیہ وسلم نے عورتوں سے بیعت لی تھی۔ حدیث سے معلوم ہوا کہ نوحہ کرنا حرام اور ناجائز ہے، لہٰذا اس سے بچنا ضروری ہے۔ شرعاََ یہ بہت قبیح کام ہے، اس لیے اس سے روکنے کا خصوصی اہتمام کرنا چاہیے۔ اگر اس سلسلے میں ڈانٹ ڈپٹ سے کام لینا پڑے تو اس میں بھی کوئی حرج نہیں جیسا کہ حضرت عمر رضی اللہ تعالٰی عنہ کی بابت منقول ہے کہ وہ کسی کی وفات پر اگر کسی کو غلط انداز میں اور غیر شرعی رونا روتے دیکھتے تو اسے پتھر وغیرہ مارتے اور اس رونے والے شخص کے منہ میں مٹی ٹھونستے۔ دیکھیے: حرمت نوحہ کی کئی ایک وجوہات ہوسکتی ہیں، مثلاََ: یہ جاہلیت کے کاموں میں سے ہے، غم زیادہ اور صبر نہ کرنے کا سبب بنتا ہے، نیز نوحہ کرنے سے ا اللہ تعالیٰ کی قضا و قدر کی مخالفت اور اس پر عدم رضا لازم آتی ہے۔ ۳ حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ شارع صلی اللہ علیہ وسلم کو یہ حق حاصل تھا کہ وہ جب چاہیں اور جس کے لیے چاہیں عام قانون میں تخصیص فرما دیں جس طرح کہ ام عطیہ رضی اللہ عنہا کے لیے تخصیص کی گئی۔ ۴’’ ایک عورت نے نوحہ کرنے میں میری مدد کی تھی‘‘ جاہلیت میں یہ رواج تھا کہ اگر کسی گھر کوئی میت ہوتی تو دوسری عورتیں باری باری اس کے گھر کی عورتوں سے مل کر جھوٹ موٹ کرتیں اور زبانی رونا روتیں۔ حضرت ام عطیہ رضی اللہ عنہا جب بیعت کرنے لگیں تو آپ نے بیعت کے وقت نوحہ نہ کرنے کا بھی ذکر فرمایا۔ان کو خیال آیا کہ فلاں عورت نے بیعت سے متعلق احکام ومسائل تو نوحہ میں میری مدد کی تھی۔ اور جاہلیت میں اس مدد کو بھی لین دین کی طرح سمجھا جاتا تھا اور اس کا باقاعدہ مطالبہ ہوتا تھا۔ حضرت ام عطیہ رضی اللہ عنہا کو خطرہ ہوا کہ کل کلاں وہ عورت آکر مجھ سے بدلے کا مطالبہ کرے گی، اس لیے مجھے بیعت سے پہلے ہی بدلہ چکا دینا چاہیے۔"}],[4180,"ام عطیہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم سے بیعت لی کہ ہم نوحہ نہیں کریں گے۔","الألباني: صحيح",{"u2":"حضرت ام عطیہ رضی اللہ عنہا سے مروی ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے ہم سے بیعت لی کہ ہم نوحہ نہیں کریں گی۔"}],[4181,"امیمہ بنت رقیقہ رضی اللہ عنہا کہتی ہیں کہ میں انصار کی چند عورتوں کے ساتھ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئی تاکہ ہم بیعت کریں، ہم نے عرض کیا: اللہ کے رسول! ہم آپ سے بیعت کرتے ہیں کہ ہم اللہ کے ساتھ کسی کو شریک نہیں کریں گے، نہ چوری کریں گے، نہ زنا کریں گے، اور نہ ایسی کوئی الزام تراشی کریں گے جسے ہم خود اپنے سے گھڑیں، نہ کسی معروف (بھلے کام) میں ہم آپ کی نافرمانی کریں گے، آپ نے فرمایا: \"اس میں جس کی تمہیں استطاعت ہو یا قدرت ہو\"، ہم نے عرض کیا: اللہ اور اس کے رسول ہم پر زیادہ مہربان ہیں، آئیے ہم آپ سے بیعت کریں، اللہ کے رسول! آپ نے فرمایا: \"میں عورتوں سے مصافحہ نہیں کرتا، میرا سو عورتوں سے کہنا ایک عورت سے کہنے کی طرح ہے یا ایک ایک عورت سے کہنے کے مانند ہے\"۔","الألباني: صحيح",{"u2":"حضرت امیمہ بنت رقیقہ رضی اللہ عنہا فرماتی ہیں کہ میں کچھ انصاری عورتوں کی معیت مٰں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی۔ ہم آپ سے بیعت ہونا چاہتی تھیں۔ہم نے عرض کی: اے ا اللہ کے رسول! ہم آپ سے بیعت کرتی ہیں کہ ہم ا اللہ تعالیٰ کے ساتھ کسی کو شریک نہیں بنائیں گی، چوری نہیں کریں گی، زنا نہیں کریں گی، اپنی طرف سے جھوٹ گھڑ کر کسی بہتان طرازی نہیں کریں گی اور کسی نیک کام میں آپ کی نافرمانی نہیں کریں گی۔ آپ نے فرمایا: ’’اپنی طاقت اور وسعت کے مطابق(تم پابند ہوگی)۔ ‘‘ ہم نے کہا: ا اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم ہم پر(ہم سے بھی) زیادہ مہربان بیعت سے متعلق احکام ومسائل اور رحم فرمانے والے ہیں۔ اے ا اللہ کے رسول! اجازت دیجیے کہ ہم آپ کے دست مبارک پر بیعت کریں۔ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ میں عورتوں سے ہاتھ نہیں ملاتا۔ میرا زبانی طور پر سو عورتوں سے(بیعت کی) بات چیت کرنا ایسے ہی ہے جیسے ہر ہر عورت سے الگ طور پر بات چیت کروں۔ ‘‘","f2":"1۔اس حدیث مبارکہ سے ثابت ہوا ہے کہ عورتوں اور مردوں سے بیعت لینے میں فرق ہے۔ دونوں کی بیعت ایک جیسی نہیں ہے، یعنی بیعت کے وقت عورتوں سے ہاتھ ملانا حرام اور ناجائز ہے جبکہ مردوں سے حلال اور جائز ہے۔ صلح حدیبیہ کے موقع پر رسول ا اللہ صلی اللہ علیہ وسلم نے ہاتھ ملا کرصحابہ اکرم رضی اللہ تعالٰی عنہ سے بیعت لی تھی۔ قرآن و حدیث میں اس کی صراحت موجود ہے۔ رسول ا اللہ صلی اللہ علیہ وسلم غیر محرم عورتوں سے دمصافحہ نہیں کرتے تھے اگرچہ ضرورت کا تقاضا بھی ہوتا جیسا کہ آپ نے عورتوں سے بیعت لیتے وقت صرف زبان سے بیعت لینے پر اکتفا فرمایا ہے۔ ام المومنین حضرت عائشہ صدیقہ رضی اللہ عنہا فرماتی ہیں: ا اللہ کی قسم! بیعت لیتے ہوئے بھی رسول ا اللہ صلی اللہ علیہ وسلم کا ہاتھ مبارک کبھی کسی غیر محرم عورت کے ہاتھ کو نہیں لگا۔ بنابریں کسی بھی نیک وپار سا اور برادری وغیرہ کے کے معزز اور بڑے شخص کے لیے جائز نہیں کہ وہ کسی غیر محرم عورت کے سر پر ہاتھ پھیرے یا کسی سے مصافحہ وغیرہ کرے۔ نبی صلی اللہ علیہ وسلم کا جو حکم امت کے کسی ایک مرد یا ایک عورت کے لیے ہوتا ہے وہ امت کے تمام مردوں اور عورتوں کو شامل ہوتا ہے الا یہ کہ نبی صلی اللہ علیہ وسلم کسی کے لیے خود تخصیص فرما دیں۔ ’’ عورتوں سے ہاتھ نہیں ملاتا‘‘ نبی صلی اللہ علیہ وسلم کے اس طرز عمل میں ان نام نہاد پیروں کے لیے درس عبرت ہے جو مردوں عورتوں سے بلا امتیاز دستی بیعت لیتے ہیں۔ اگر یہ جائز ہوتا تو رسول ا اللہ صلی اللہ علیہ وسلم اس سے پرہیز نہ فرماتے۔ اسی طرح مجالس وعظ و سماع میں عورتوں کا مردوں کے سامنے بلا جحاب بیٹھنا بھی شرعی مزاج سے متصادم ہے۔ ’’ الگ الگ بات چیت کروں‘‘ مقصود یہ ہے کہ زبانی بیعت بھی الگ الگ عورت سے نہیں ہوگی بلکہ تمام عورتوں سے بیک وقت زبانی عہد لیا جائے گا۔ واللہ اعلم"}],[4182,"شرید رضی اللہ عنہ کہتے ہیں کہ ثقیف کے وفد میں ایک کوڑھی تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے اسے کہلا بھیجا کہ \"لوٹ جاؤ، میں نے تمہاری بیعت لے لی\"۱؎۔\n§وضاحت\n۱؎: چونکہ نبی اکرم صلی اللہ علیہ وسلم اچھی طرح سے یہ جانتے تھے کہ اس کے آنے سے لوگ گھن محسوس کریں گے اور ممکن ہے کہ بعض کمزور ایمان والے وہم میں بھی مبتلا ہو جائیں، اس لیے آپ صلی اللہ علیہ وسلم نے اسے کہلا بھیجا کہ تمہیں یہاں آنے کی ضرورت نہیں میں نے تمہاری بیعت لے لی۔ خود آپ کو گھن نہیں آئی، نہ آپ کو کسی وہم میں مبتلا ہونے کا ڈر تھا، آپ سے بڑھ کر صاحب ایمان کون ہو سکتا ہے ؟۔","الألباني: صحيح",{"u2":"آل شرید کے ایک شخص عمرو کے والد سے بیعت سے متعلق احکام ومسائل روایت ہے کہ بنو ثقیف کے وفد میں ایک کوڑھی شخص بھی آیا تھا۔ بنی اکرم صلی اللہ علیہ وسلم نے اسے پیغام بھیجا: ’’ واپس چلے جاؤ (میرے پاس آنے کی ضرورت نہیں) میں نے تیری بیعت قبول کرلی ہے۔ ‘‘","f2":"1۔باب کے ساتھ حدیث کی مناسبت اس طرح بیتی ہے کہ مجذوم شخص سے بیعت لینا مشروع ہے، تا ہم ایسے شخص سے صرف زبانی کلامی بیعت بھی ہوسکتی ہے۔ اس حدیث سے یہ بھی معلوم ہوتا ہے کہ خطر ناک بیماری میں مبتلا شخص سے دوری اختیار کرنا جائز ہے، تاہم ایسے شخص کو بالکل نظر انداز کرنا اور کلی طور پر اسے حالات کے رحم وکرم پر چھوڑ دینا درست نہیں۔ اس کا علاج کرانا چاہیے۔ ضرورت کے مطابق اس سے میل جول اور اس کی معاونت ہو سکتی ہے۔ آفت زدپ شخص سے مراد وہ شخص ہے جو انتہائی قبیح مرض میں گرفتار ہو۔ لوگ اس سے بہت نفرت کرتے ہوں۔دوسرے لوگوں کے متاثر ہونے کا خدشہ ہو، مثلاََ: جذام (کوڑھ) یہ انتہائی قبیح اور خوف ناک مرض ہے۔ طبعاََ ہر آدمی اس سے دور بھاگتا ہے۔ اس مرض کا مواد مریض کے جسم پر ہر وقت موجود رہتا ہے۔ قریب آنے سے دوسرے شخص کو لگ سکتا ہے جس سے اس کے متاثر ہونے کو خدشہ ہے، اس لیے بنی صلی اللہ علیہ وسلم نے اسے مجلس میں آنے سے منع فرما دیا۔ ایسے مریض کو خود بھی حتی الا مجالس میں آنے سے بچنا چاہیے۔ ا اللہ تعالیٰ اس مرض سے بچائے۔ بیعت قبول کرلی ہے‘‘ کیونکہ اصل اعتبار تو دلی عہد کا ہے۔ زبان وہاتھ تو صرف تاکید کے لیے ہیں، ضروری نہیں۔"}],[4183,"ہرماس بن زیاد رضی اللہ عنہ کہتے ہیں کہ میں نے اپنا ہاتھ نبی اکرم صلی اللہ علیہ وسلم کی طرف بڑھایا تاکہ آپ مجھ سے بیعت لے لیں، میں ایک نابالغ لڑکا تھا تو آپ نے مجھ سے بیعت نہیں لی ۱؎۔\n§وضاحت\n۱؎: کیونکہ بیعت میں کسی بات کا عہد و پیمان لیا جاتا ہے، جب کہ نابالغ پر کسی عہد و پیمان کی پابندی واجب نہیں ہے۔","الألباني: حسن الإسناد",{"u2":"حضرت ہر ماس بن زیاد رضی اللہ تعالٰی عنہ سے روایت ہے کہ میں نے (بیعت کے لیے) اپنا ہاتھ نبی اکرم صلی اللہ علیہ وسلم کی طرف بڑھایا جبکہ میں اس وقت (نابالغ) بچہ تھا۔ آپ صلی اللہ علیہ وسلم نے مجھ سے بیعت نہیں لی۔","f2":"بیعت دراصل عظیم الشان عہد ہوتا ہے جو پوری عقل وحواس اور بصیرت سے کیا جاتا ہے۔ یہ بچوں کا کھیل نہیں اور نہ کوئی بے فائدہ رسم ہے جو صرف تبرک کے لیے ہر کس وناکس سے پوری کروائی جائے۔ آج بیعت سے متعلق احکام ومسائل کل بعض حضرات بیعت کو تبرک سمجھ کر کرتے ہیں کہ ہم فلاں بزرگ سے بیعت ہیں اور وہ اسے آخرت میں کوئی مفید شے سمجھتے ہیں جبکہ حقیقت میں یہ غیر اسلامی عمل ہے۔ بیعت امام کی ہوسکتی ہے یا اس کے مقرر کردہ نائب کی۔ اسلامی بیعت تو عہد کا نام ہے جو ایک ذمہ داری ہے جس کی فکر کرنا پڑتی ہے نہ کہ بیعت انسان کو ذمہ داریوں سے آزاد کرتی ہے جیسا کہ خیال کیا جاتا ہے کہ’’ جلاں بزرگ سے بیعت ہو جاؤ بس نجات ہو جائے گی۔ شرعی فرائض کی ادائیگی کوئی ضروری نہیں‘‘ گویا ہر قسم کی ذمہ داری بیعت لینے والے پر ڈال دی جاتی ہے۔ اسلام ایسی خرافات کا قائل نہیں ہے"}],[4184,"جابر رضی اللہ عنہ کہتے ہیں کہ ایک غلام نے آ کر نبی اکرم صلی اللہ علیہ وسلم سے ہجرت پر بیعت کی، آپ یہ نہیں سمجھ رہے تھے کہ یہ غلام ہے، پھر اس کا مالک اسے ڈھونڈتے ہوئے آیا، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اسے میرے ہاتھ بیچ دو\"، چنانچہ آپ نے اسے دو کالے غلاموں کے بدلے خرید لیا، پھر آپ نے کسی سے بیعت نہیں لی یہاں تک کہ آپ اس سے معلوم کر لیتے کہ وہ غلام تو نہیں ہے ۱؎۔\n§وضاحت\n۱؎: غلام اپنے مالک کا تابع ہے، تو وہ کیسے ہجرت کر سکتا ہے اس لیے آپ غلاموں سے بیعت نہیں لیتے تھے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے مروی ہے کہ ایک غلام آیا اور اس نے ہجرت پر بنی اکرم صلی اللہ علیہ وسلم کی بیعت کر لی۔ بنی اکرم صلی اللہ علیہ وسلم کو علم نہیں تھا کہ وہ غلام ہے۔ کچھ دیر بعد اس کا مالک آگیا‘ وہ اسے لے جانا چاہتا تھا۔ بنی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ یہ غلام مجھے بیچ دے۔ ‘‘ پھر آپ نے دوکالے غلام دے کر اس کو خریدا۔ اس کے بعد آپ کسی سے بیعت نہ لیتے حتی کہ پوچھ لیتے: ’’ وہ غلام تو نہیں؟ ‘‘","f2":"1۔اس حدیث سے معلوم ہوا کہ مالک کی اجازت کے بغیر غلام کی بیعت نائزہ ہے۔ یہ حدیث رسول ا اللہ صلی اللہ علیہ وسلم کے عظیم مکارم اخلاق اور عام لوگوں کے ساتھ احسان کرنے پر بھی دلالت کرتی ہے کہ آپ نے غلام کو والپس کرنا پسند نہیں فرمایا تا کہ وہ آزردہ خاطر نہ ہو، نیز جس غرض کے لیے وہ آیا تھا اس میں بھی خلل واقع نہ ہو، چنانچہ آپ نے احسان عظیم فرماتے ہوئے اسے خرید لیا تاکہ اس کا مقصد پورا ہوجائے۔اس حدیث مبارکہ سے یہ مسئلہ بھی اخذ ہوتا ہے کہ دو غلاموں کے بدلے ایک غلام کی بیع جائز ہے، خواہ قیمت ایک جیسی ہو یا قیمت کا فرق ہو۔ تمام جانوروں اور حیوانات کا حکم بھی یہی ہے۔ جمہور اہل علم اس بیع کے جواز کے قائل ہیں جبکہ امام ابو حنیفہ اور اہل کوفہ اس کو ناجائز قرار دیتے ہیں۔ اس حدیث سے یہ مسئلہ بھی ثابت بیعت سے متعلق احکام ومسائل ہوتا ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نہ عالم الغیب تھے اور نہ آپ کو عطائی علم غیب حاصل تھا۔ یہی وجہ ہے کہ آپ نے اس غلام کی بیعت قبول فرمالی جو اپنے آقا کی اجازت کے بغیر آگیا تھا۔ اسی طرح اس واقعے کے بعد آپ بیعت کی خاطر آنے والے ہر شخص سے پوچھا کرتے تھے کہ وہ غلام تو نہیں ہے؟ رسول ا اللہ صلی اللہ علیہ وسلم احتیاط پسند تھے، اسی لیے آپ بیعت کے لیے آنے والوں سے پوچھتے تھے۔ غلام اپنی مرضی کا مالک نہیں ہوتا۔ وہ مالک کے حکم کا پابند ہوتا ہے لہٰذا غلام کا اسلام تو معبتر اور مقبول ہے مگر ہجرت اور جہاد وغیرہ کی بیعت معتبر نہیں۔ ممکن ہے مالک اسے اجازت نہ دے جیسا کہ مندرجہ بالا واقعہ میں ہوا۔ یہ لگ بات ہے کہ آپ نے اس کی بیعت ہجرت کی لاج رکھتے ہوئے اسے خرید لیا مگر ہر غلام کے ساتھ ایسے ممکن نہ تھا۔"}],[4185,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ ایک اعرابی نے رسول اللہ صلی اللہ علیہ وسلم سے اسلام پر بیعت کی، پھر اس کو مدینے میں بخار آ گیا، تو اس نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر کہا: اللہ کے رسول! میری بیعت توڑ دیجئیے ۱؎، آپ نے انکار کیا، اس نے پھر آپ کے پاس آ کر کہا: میری بیعت توڑ دیجئیے، آپ نے انکار کیا، تو اعرابی چلا گیا ۲؎، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مدینہ تو بھٹی کی طرح ہے جو اپنی گندگی کو نکال پھینکتا ہے اور پاکیزہ کو اور خالص بنا دیتا ہے\"۔\n§وضاحت\n۱؎: کیونکہ وہ اس بیماری کو بیعت کی نحوست سمجھ بیٹھا تھا۔ ۲؎: یعنی مدینہ سے چلا گیا، تاکہ اپنے خیال میں اس نحوست سے نجات پا جائے، اس حدیث سے ثابت ہوتا ہے کہ کسی خلیفہ :(حکمراں ) سے خلافت کی بیعت، یا کسی خاص بات کو توڑنا جائز نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت جابربن عبد ا اللہ رضی اللہ عنہا سے روایت ہے کہ ایک اعرابی نے رسول ا اللہ صلی اللہ علیہ وسلم کے دست مبارک پر قبول اسلام کی بیعت کی، پھر اس اعرابی کو مدینہ منورہ میں تپ چڑھ گیا۔ وہ رسول ا اللہ صلی اللہ علیہ وسلم کے پاس آکر کہنے لگا: اے ا اللہ کے رسول! مجھے میری بیعت واپس فرمادیجیے۔ آپ نے انکار کردیا، وہ دوبارہ آیا اور پھر کہنے لگا: میری بیعت واپس فرمادیجیے۔ آپ نے پھر انکار فرمایا۔ آخر وہ اعرابی (بلااجازت) چلا گیا۔ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ مدینہ منورہ بھٹی کی طرح ہے۔ میلہ کچیل کو نکالتا رہتا ہے اور خالص چیز کو باقی رکھتا ہے۔ ‘‘","f2":"1۔باب کے ساتھ حدیث کی مناسبت واضح ہے۔ باب کا مطلب ہے کہ بیعت توڑنے کا کیا حکم ہے؟ رسول ا اللہ صلی اللہ علیہ وسلم کے عمل سے ثابت ہوا کہ یہ کام ناجائز اور حرام ہے۔ کسی شخص نے اسلام پر بیعت کی ہویا ہجرت پر دونوں صورتوں میں بیعت توڑنا درست نہیں۔ اس حدیث مبارکہ سے مدینہ طیبہ کی فضیلت بھی معلوم ہوتی ہے کہ اسے ا اللہ تعالیٰ نے ایک ایسی بھٹی کی طرح بنایا ہے جو شرپسند لوگوں کو نکال باہرپھینکتا ہیط جبکہ بیعت سے متعلق احکام ومسائل ابرارو اخیار لوگ اس میں سکون وقرار حاصل کرتے ہیں۔ ظاہر الفاظ سے معلوم ہوتا ہے کہ مدینہ طیبہ سے نکل جانے والے لوگ مذموم ہیں۔ لیکن کلی طور پر یہ بات درست نہیں ہے کیونکہ صحابہ کرام رضی اللہ عنہم کی بہت بڑی تعداد نے مدینہ کو خیر باد کہہ کر دوسرے مقامات پر بسیرا کر لیا تھا۔ بعد بھی کئی اصحاب العلم فضلاء نے مدینہ چھوڑا۔ اصل بات یہ ہے کہ ان لوگوں کا مدینہ سے نکلنا مذموم ومکروہ ہے جنھیں مدینہ میں رہنا پسند، یعنی مدینہ سے کراہت اور بے رغبتی کرتے ہوئے اس سے نکل جائیں جیسا کہ اس اعرابی نے کیا تھا، تاہم جن لوگوں نے صحیح اور درست مقاصد کی خاطر مدینے کو خیر باد کہا، جیسے تبلیغ دین اور علم کی نشر واشاعت کے لیے، کفار و مشرکین کے علاقے فتح کرنے، سرحدوں کی حفاظت کرنے اور دشمنان دین واسلام کے ساتھ جہاد کرنے کے لیے تو اس میں کوئی حرج نہیں، اور نہ یہ اعمال حدیث میں واردمذمت کے مصداق ہی ہیں۔ جب اسلام پھیل گیا تو بعض لوگ مالی مفادات کے حصول کے لیے بھی اسلام قبول کرنے لگے۔ اسلام لانے کے بعد اگر مال حاصل ہوتا رہتا تو اسلام پر قائم رہتے اور اگر کوئی تکلیف آجاتی یا مال نہ ملتا تو دین سے طرگشتہ ہوجاتے۔ شاید یہ اعرابی بھی اسی قسم کا تھا۔ ممکن ہے اس نے ہجرت کی بھی بیعت کی ہو، پھر بخار سے گھبرا کر مدینہ چھوڑنا چاہتا ہو نہ کہ اسلام۔ ’’بھٹی کی طرح‘‘ مدینہ منورہ میں رہ کر بہت سی جسمانی تکلیفیں برداشت کرنا پڑتی تھیں۔ آب وہوا کی ناموافقت، فقر وفاقہ، اجنبیت، ہر وقت حملے لڑائی کا خطرہ اور وقتاََ فوقتاََ جنگوں میں شرکت جبکہ اسلحہ اور حفاظتی سامان بھی نہ ہونے کے برابر تھا۔ یہ ایسی چیزیں تھیں ناقص اور کمزور ایمان والا شخص برادشت نہیں کرسکتا تھا۔ اولوالعزم اور پختہ ایمان والے ہی ان آزمائشوں پرپورااترتے تھے۔ میل کچیل سے مراد ناقص الایمان اور منافق لوگ ہیں۔ ایسے لوگ مدینہ میں نہیں رہ سکتے مدینہ انھیں باہر نکال دیتا ہے۔"}],[4186,"سلمہ بن الاکوع رضی اللہ عنہ سے روایت ہے کہ وہ حجاج کے پاس گئے تو اس نے کہا: ابن الاکوع! کیا آپ (ہجرت کی جگہ سے) ایڑیوں کے بل لوٹ گئے، اور ایک ایسا کلمہ کہا جس کے معنی ہیں کہ آپ بادیہ (دیہات) چلے گئے۔ انہوں نے کہا: نہیں، مجھے تو رسول اللہ صلی اللہ علیہ وسلم نے بادیہ (دیہات) میں رہنے کی اجازت دی تھی ۱؎۔\n§وضاحت\n۱؎: گناہ کبیرہ میں سے ایک گناہ \" ہجرت کے بعد ہجرت والی جگہ کو چھوڑ دینا \" بھی ہے :(اس سلسلے میں احادیث مروی ہیں ) اسی کی طرف حجاج نے اشارہ کر کے سلمہ بن الاکوع رضی اللہ عنہ سے یہ بات کہی، جب کہ بات یہ تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے سلمہ کے قبیلہ والوں کو فتنہ سے بچنے کے لیے اس کی اجازت پہلے ہی دے دی تھی، اسی لیے امام بخاری نے اس حدیث پر «التعرب فی الفتنۃ» \" فتنہ کے زمانہ میں دیہات میں چلا جانا \" کا باب باندھا ہے۔","الألباني: صحيح",{"u2":"حضرت سلمہ بن اکوع رضی اللہ تعالٰی عنہ جحاج کے پاس تشریف لے گئے۔ اس نے کہا: اے ابن اکوع! تم مرتد ہوگئے ہو اور ایک کلمہ کہا جس کے معنی تھے کہ(مدینہ چھوڑ کر) بادیہ میں رہنے لگے ہو؟ انھوں نے فرمایا: نہیں بلکہ رسول ا اللہ صلی اللہ علیہ وسلم نے مجھے(اپنے بعد) بادیہ میں رہنے کی اجازت دی تھی۔","f2":"1۔باب کے ساتھ حدیث کی مناسبت اس طرح بنتی ہے کہ ہجرت کرنے کے بعد بادیہ نشینی بنی صلی اللہ علیہ وسلم کی اجازت کے بغیر جائز نہیں ہے۔ ییہ حدیث مبارکہ حضرت سلمہ بن اکوع رضی اللہ تعالٰی عنہ کے صبر اور ان کی کرأت پر بھی دلالت کرتی ہے کہ انھوں نے جحاج کی بے ادبی پر صبر کیا، اور پھر اسے جواب بھی دیا۔ جحاج بنوامیہ کے دور کا ایک ظالم اور گستاخی کی واضح دلیل ہے۔اسے اقتدار کے نشے نے چھوٹے بڑے کی تمیز بھلا دی تھی۔ نتیجہ یہ ہے کہ کوئی بھی اسے اچھے لفظوں سے یاد نہیں کرتا بلکہ لعنت تک نوبت پہنچ جاتی ہے۔ بے ادبی انسان کی خوبیوں کو چھپا دیتی ہے۔ ’’بادیہ‘‘ مراد صحرائی علاقہ ہے، یعنی آبادیوں سے باہر کھلے اور آزاد علاقے۔ ان میں رہنے والے کو بدوی یا اعرابی کہتے ہیں۔ جحاج کا اعتراض فضول تھا۔ کوئی شخص کسی بھی جگہ چلے رہائش اختیار رکھ سکتا ہے۔ حضرت سلمہ بن اکوع رضی اللہ تعالٰی عنہ کوئی مہاجر نہیں تھے کہ مدینہ چھوڑ کر اپنے سابقہ گھر چلے گئے ہوں اور ان پر اعتراض ہوسکے۔ بہت سے مہاجر صحابہ بھی مدینہ چھوڑ کر دوسرے علاقوں میں آباد ہوگئے تھے۔ خیر انھوں نے تو بنی صلی اللہ علیہ وسلم سے اجازت بھی لے رکھی تھی اور پھر وہ فوت بھی منورہ ہی ہوئے۔رضی اللہ عنہ وارضاہ"}],[4187,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم سے سمع و طاعت (سننے اور حکم بجا لانے) پر بیعت کرتے تھے، پھر آپ فرماتے تھے: \"جتنی تمہاری طاقت ہے\" ۱؎۔\n§وضاحت\n۱؎: دین اسلام کی طبیعت ہی اللہ تعالی نے یہی رکھی ہے کہ بن دوں پر ان کی طبعی طاقت سے زیادہ بوجھ نہیں ڈالا ہے۔ قرآن میں ارشاد ربانی ہے: «لا يكلف الله نفسا إلا وسعها» \" اللہ تعالی نے کسی نفس پر اس کی طاقت سے زیادہ بوجھ نہیں ڈالا ہے \" :(البقرة: 286 )۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہا بیان کرتے ہین کہ ہم رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کیا کرتے تھے کہ آپ کی بات سنیں گے اور اطاعت کریں گے۔ ا اللہ کے رسول صلی اللہ علیہ وسلم فرماتے کہ اپنی طاقت کے مطابق۔","f2":"باب کا مقصد یہ ہے کہ بیعت کرتے وقت طاقت کی قید بھی ذکر کرنی چاہیے۔ یہ مقصد بھی ہوسکتا ہے کہ بیعت میں طاقت وہ سعت کی قید ملحوظ ہوتی ہے، خواہ الفظاََ ذکر نہ کی جائے۔ طاقت سے بڑھ کر کوئی اطاعت کا مکلف نہیں بن سکتا۔"}],[4188,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ جس وقت ہم رسول اللہ صلی اللہ علیہ وسلم سے سمع و طاعت (سننے اور حکم بجا لانے) پر بیعت کرتے تھے تو آپ ہم سے فرماتے تھے: \"جتنی تمہاری طاقت ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہا سے مروی ہے، وہ بیان کرے ہیں کہ جب ہم سمع وطاعت پر رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کرتے تو آپ ہمیں فرماتے تھے کہ تمھاری طاقت کے مطابق۔"}],[4189,"جریر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے سمع و طاعت (حکم سننے اور اس پر عمل کرنے) پر بیعت کی تو آپ نے مجھے \"جتنی میری طاقت ہے\" کہنے کی تلقین کی، نیز میں نے ہر مسلمان کی خیر خواہی پر بیعت کی۔","الألباني: صحيح",{"u2":"حضرت جریرین عبد ا اللہ رضی اللہ تعالٰی عنہ نے فرمایا: میں نے سمع اور اطاعت پر رسول ا اللہ کی بیعت کی تو آپ نے مجھے (یہ کہنے کی) تلقین فرمائی: ’’اپنی طاعت کے مطابق اور ہر مسلمان سے خیر خواہی کروں گا۔ ‘‘"}],[4190,"امیمہ بنت رقیقہ رضی اللہ عنہا کہتی ہیں کہ ہم نے عورتوں کی ایک جماعت کے ساتھ رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی تو آپ نے ہم سے فرمایا: \"جتنی تم استطاعت اور قدرت رکھتی ہو\"۔","الألباني: صحيح",{"u2":"حضرت امیمہ بنت رقیقہ رضی اللہ عنہا فرماتی ہیں کہ ہم چند عورتوں نے رسول ا اللہ صلی اللہ علیہ وسلم کی بیعت کی۔ آپ نے ہمیں فرمایا: ’’ تمھاری استطاعت اور طاقت کے مطابق (یہ بیعت تم پر لاگو ہوگی)۔ ‘‘"}],[4191,"عبدالرحمٰن بن عبد رب الکعبہ کہتے ہیں کہ میں عبداللہ بن عمرو رضی اللہ عنہما کے پاس گیا، وہ کعبہ کے سائے میں بیٹھے ہوئے تھے، لوگ ان کے پاس اکٹھا تھے، میں نے انہیں کہتے ہوئے سنا: اسی دوران جب کہ ہم ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، ہم نے ایک جگہ پڑاؤ ڈالا، تو ہم میں سے بعض لوگ خیمہ لگانے لگے، بعض نے تیر اندازی شروع کی، بعض جانور چرانے لگے، اتنے میں نبی اکرم صلی اللہ علیہ وسلم کے منادی نے پکارا: نماز کھڑی ہونے والی ہے، چنانچہ ہم اکٹھا ہوئے، نبی اکرم صلی اللہ علیہ وسلم نے کھڑے ہو کر ہمیں مخاطب کیا اور آپ نے فرمایا: \"مجھ سے پہلے کوئی نبی ایسا نہ تھا جس پر ضروری نہ رہا ہو کہ جس چیز میں وہ بھلائی دیکھے اس کو وہ اپنی امت کو بتائے، اور جس چیز میں برائی دیکھے، انہیں اس سے ڈرائے، اور تمہاری اس امت کی خیر و عافیت شروع (کے لوگوں) میں ہے، اور اس کے آخر کے لوگوں کو طرح طرح کی مصیبتیں اور ایسے مسائل گھیر لیں گے جن کو یہ ناپسند کریں گے، فتنے ظاہر ہوں گے جو ایک سے بڑھ کر ایک ہوں گے، پھر ایک ایسا فتنہ آئے گا کہ مومن کہے گا: یہی میری ہلاکت و بربادی ہے، پھر وہ فتنہ ٹل جائے گا، پھر دوبارہ فتنہ آئے گا، تو مومن کہے گا: یہی میری ہلاکت و بربادی ہے۔ پھر وہ فتنہ ٹل جائے گا۔ لہٰذا تم میں سے جس کو یہ پسند ہو کہ اسے جہنم سے دور رکھا جائے اور جنت میں داخل کیا جائے تو ضروری ہے کہ اسے موت ایسی حالت میں آئے جب وہ اللہ، اور آخرت (کے دن) پر ایمان رکھتا ہو اور چاہیئے کہ وہ لوگوں سے اس طرح پیش آئے جس طرح وہ چاہتا ہے کہ اس کے ساتھ پیش آیا جائے۔ اور جو کسی امام سے بیعت کرے اور اپنا ہاتھ اس کے ہاتھ میں دیدے اور اخلاص کے ساتھ دے تو طاقت بھر اس کی اطاعت کرے، اب اگر کوئی اس سے (اختیار چھیننے کے لیے) جھگڑا کرے تو اس کی گردن اڑا دو، یہ سن کر میں نے ان سے قریب ہو کر کہا: کیا یہ آپ نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے؟ کہا: ہاں، پھر(پوری) حدیث ذکر کی ۱؎۔\n§وضاحت\n۱؎: اس حدیث کا آخری حصہ مؤلف نے نہیں ذکر کیا، امام مسلم نے اس کو ذکر کیا ہے، وہ یہ ہے کہ \" عبدالرحمٰن بن عبد رب کعبہ نے عرض کیا: معاویہ رضی اللہ عنہ ایسا ویسا کر رہے ہیں، اس پر عبداللہ بن عمرو رضی اللہ عنہما نے فرمایا: \" تم معروف :(بھلی بات ) میں ان کی اطاعت کرتے رہو، اگر کسی منکر :(برے کام ) کا حکم دیں تو تم انکار کر دو، لیکن ان کے خلاف بغاوت مت کرو :(خلاصہ ) یہ کہ یہ حدیث سلف صالحین کے اس منہج اور طریقے کی تائید کرتی ہے کہ کسی مسلمان حاکم کے بعض منکر کاموں کی وجہ سے ان کو اختیار سے بے دخل کر دینے کے لیے ان کے خلاف تحریک نہیں چلائی جا سکتی، معروف کے سارے کام اس کی ماتحتی میں کئے جاتے رہیں گے۔ اور منکر کے سلسلے میں صرف زبانی نصیحت کی جائے گی۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن عبد رب الکعبہ سے روایت ہے کہ میں حضرت عبد ا اللہ بن عمرو رضی اللہ عنہا کے پاس پہنچا۔ وہ کعبہ کے سائے میں بیٹھے تھے اور لوگ ان کے ارد گرد جمع تھے۔ میں نے انھیں فرماتے سنا کہ ایک دفعہ ہم رسول ا اللہ صلی اللہ علیہ وسلم کے ساتھ سفر میں تھے۔ ہم ایک منزل میں اترے۔ ہم میں سے کوئی شخص ابھی خیمہ لگا رہا تھا، کوئی (بطور مشق) تیر اندازی کررہا تھا اور کوئی اپنے جانوروں کو چرانے کے لیے نکال رہا تھا کہ اتنے میں نبی صلی اللہ علیہ وسلم کے منادی نے اعلان کیا: تماز کے لیے اکٹھے ہوجاؤ، چنانچہ ہم سب اکٹھے ہوگئے۔ نبی اکرم صلی اللہ علیہ وسلم کھڑے ہوئے اور ہمیں خطبہ ارشاد فرمایا۔ آپ نے (خطبہ کے دور ان میں) فرمایا: ’’ جو بھی بنی مجھ سے پہلے گزرے ہیں‘ان پر ضروری تھا کہ اپنی امت کی ان باتوں کی طرف رہنمائی فرمائیں جنھیں وہ ان کے لیے بہتر سمجھتے تھے۔ اور انھیں ان چیزوں سے ڈرائیں جنھیں وہ ان کے لیے برا سمجھتے تھے۔ اور تمھاری اس امت کی خیرو بھلائی اس کے ابتدائی لوگوں میں رکھ دی گئی ہے۔ بعد میں آنے والوں پر بڑی آزمائشیں آئیں گی اور ایسے حالات طاری ہوں گے جنھیں وہ ناپسند کریں گے۔ بے شمار فتنے آئیں گے جو ایک دوسرے کے مقابلے می ہلکے معلوم ہوں گے۔ (ایک سے بڑھ کرایک ہو گا۔) ایک فتنہ آئے گا، مومن سمجھے گا کہ یہ مجھے ہلاک کرڈالے گا، پھر وہ فتنہ ٹل جائے گا اور اس کی جگہ اور بڑا فتنہ آئے گا۔ مومن کہے گا: یہ ہلاک کن ہے (اس سے تو میں بچ ہی نہیں سکتا) پھر وہ بھی ٹل جائے گا، چنانچہ تم میں سے جو شخص چاہتا ہے کہ اسے آگ سے بچا کر جنت میں داخل کر دیا دجائے تو اس حال میں آنی چاہیے کہ وہ ا اللہ تعالیٰ اور یوم آخرت پر یقین رکھتا ہو اور لوگوں کے ساتھ وہی سلوک کرے جو وہ خود پسند کرتا ہے کہ میرے ساتھ کیا جائے۔ جو شخص کسی امام (امیر) کی بیعت کرے، اس کے ہاتھ میں اپنا ہاتھ دے اور اس سے دلی طور پر (خلوص) عہد کرے تو جہاں تک ہو سکے، وہ اس کی اطاعت کرے، پھر اگر کوئی دوسرا شخص (مسلمہ) امیر سے حکومت چھیننے کی کوشش کرے تو اس کی گردن مار دو۔ ‘‘ (راوی نے کہا:) میں نے حضرت عبدا اللہ بن عمرو رضی اللہ عنہا سے قریب ہوکر پوچھا: آپ نے رسول ا اللہ صلی اللہ علیہ وسلم کو یہ سب باتیں فرماتے سنا ہے؟ انھوں نے فرمایا: ہاں! (یقینا)","f2":"1۔باب کے ساتھ حدیث کی مناسبت یوں بنتی ہے کہ جو شخص کسی امیر اور امام برحق کی بیعت کرلیتا ہے اور اسے اپنا تمام تر خلوص و محبت پیش کر دیتا ہے تو اس پر لازم ہے کہ وہ شخص حسب استطاعت وفا کے تقاضے پورے کرے اور اس پر جو اطاعت امیر لازم ہے اسے پورا کرے۔ اگر کوئی دوسرا شخص آکر پہلے امیر کی خلافت چھیننا چاہے تو وہ پہلے امیر کے ساتھ مل کر دوسرے سے لڑائی کرے۔ اس حدیث مبارکہ سے انبیاء کے ذمے ان فرائض کی وضاحر بھی وہتی ہے جو ا اللہ تعالیٰ نے ان پر عائد کیے تھے یعنی اخلاص کے ساتھ انھیں اطاعت امیر سے متعلق احکام ومسائل خیر وشر کے متعلق خبردار کرنا، انھیں ان کی دنیوی واخراوی بھلائیوں کی رہنمائی کرنا اور ابھیں ان کے دینی ودنیوی شر اور نقصان سے ڈرانااور اس پر متنبہ کرنا۔ موت تک ایمان با اللہ اور ایمان بالآخرت پر پکار ہنا،نیز لوگوں شرکے ساتھ حسن سلوک سے پیش آنا، آگ سے نجات اور جنت میں داخلے کا سبب ہے۔ امام نووی رحمہ اللہ فرماتے ہیں کہ اس حدیث مبارکہ سے یہ بات بھی معلوم ہوتی ہے کہ ہر انسان پر لازم ہے کہ وہ لوگوں کے ساتھ ویسا سلوک اور برتاؤ کرے جیساوہ اپنے لیے لوگوں سے چاہتا ہے۔ حدیث اس بات پر صریح نص ہے۔ نبی صلی اللہ علیہ وسلم کے ان کلمات کو آپ کے جومع الکلم میں سے شمار کیا گیا ہے۔ یہ شریعت مطہرہ کا اہم قاعدہ ہے۔ ہر مسلمان مرد اور عورت کو اس کا خاص اہتمام کرنا چاہیے۔ ’’ابتدائی لوگوں مٰن ‘‘ معلوم ہوا صحابہ کرام رضی اللہ عنہم افضل امت تھے۔ ان کا دین محفوظ تھا۔ دنیوی فتنوں کا بہت کم شکار ہوئے۔ ہلکے معلوم ہوں گے‘‘ یعنی بعد والا فتنہ پہلے فتنے سے بڑا ہوگا، لہٰذا پہلا فتنہ دوسرے کے مقابلے میں ہلکا محسوس ہوگا، حالانکہ وہ حقیقتاََ بہت بڑا ہوگا جیسا کہ حدیث ہی میں تفصیل مذکور ہے۔ ’’ گردن ماردو‘‘ اسلام میں بغاوت بہت بڑا جرم ہے۔ لوگ ایک امیر پر متفق اور مطمئن ہوں تو اس کے خلاف افرا تفری پیدا کرنے والا امن وامان کو درہم برہم کرنے والا بڑا مجرم ہے۔ اس کی سزا قتل ہے۔ گویا بغاوت ارتداد کے جرم کے برابر ہے۔ گزشتہ صفحات میں اس کی تفصیل بیان ہوچکی ہے۔"}],[4192,"یحیی بن حصین کی دادی (ام الحصٰن الاحمسیۃ رضی اللہ عنہا) بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو حجۃ الوداع میں فرماتے ہوئے سنا: اگر کوئی حبشی غلام بھی تم پر امیر بنا دیا جائے جو تمہیں کتاب اللہ کے مطابق چلائے تو تم اس کی سنو اور اطاعت کرو۔","الألباني: صحيح",{"u2":"حضرت یحییٰ بن حصین سے روایت ہے کہ میں نے اپنی دادی سے سنا، وہ فرماتی تھیں: میں نے رسول ا اللہ صلی اللہ علیہ وسلم کو حجۃ الوداع میں فرماتے سنا:ن ’’ اگر تم پر ایک حبشی غلام امیر بنادیا جائے جو تمھیں ا اللہ تعالیٰ کی کتاب (شریعت اسلامیہ) کے مطابق چلائے تو تم اس کی بات سنو اور اطاعت کرو۔ ‘‘","f2":"1۔چونکہ عام طورپر معاشرے میں غلام کو کم تر خیال کیا جاتا ہے، اس لیے رسول ا اللہ صلی اللہ علیہ وسلم نے نظر نہیں ہوتا، کو ماتحت امیر وامام مقرر کردے تو اس کی اطاعت و فرماں برداری بھی اسی طرح فرض ہے جس طرح کہ ایک آزاد مردکی۔اس اطاعت میں حریت وعبدیت کی وجہ سے کوئی فرق نہیں پڑتا۔2۔ اس حدیث مبارکہ سے یہ بھی معلوم ہوتا ہے کہ امام وامیر بننے کے لیے حریت اور آزادی شرط نہیں ہے کہ صرف آزاد زشخص ہی امام اور امیر بن سکے۔ آقاو مولا کی اجازت سے غلام بھی امام وامیر بن سکتا ہے۔ اس صورت میں غلام، صرف غلام ہی نہیں بلکہ امام برحق بھی ہوگا، لہٰذا اس کی اطاعت بھی واجب ہوگی۔3 یہ مسئلہ معلوم ہوا کہ کوئی بھی امام و امیر یا خلیفۃ المسلمین صرف اس صورت میں واجب الطاعۃ ہے جب وہ کتاب وسنت کے مطابق احکام دے، لوگوں کو شریعت اسلامیہ کے مطابق چلائے اور خود بھی پابند شریعت بن کررہے، ہاں! اگر کوئی امیر کتاب وسنت کے مخالف محض اپنی خواہش نفس کی اطاعت کرانا چاہے تو اس صورت میں وہ قطعاََ اطاعت کا حق دار نہیں کیونکہ رسول ا اللہ صلی اللہ علیہ وسلم کا ارشاد گرامی ہے:4 نیز اس حدیث مبارکہ سے تقلید شخصی کا مکمل طور پر رد ہوتا ہے۔ غیر مشروط اطاعت صرف ا اللہ اور اس کے رسول صلی اللہ علیہ وسلم کا حق ہے جو کسی دوسرے کو نہیں دیا جاسکتا۔"}],[4193,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے میری اطاعت کی، اس نے اللہ کی اطاعت کی اور جس نے میری نافرمانی کی تو اس نے اللہ تعالی کی نافرمانی کی، اور جس نے میرے امیر کی اطاعت کی اس نے میری اطاعت کی اور جس نے امیر کی نافرمانی کی، اس نے میری نافرمانی کی\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے میری اطاعت کی، درحقیقت اس نے ا اللہ تعالیٰ کی اطاعت کی۔ اور جس شخص نے میری نافرمانی کی، اس نے درحقیقت ا اللہ تعالیٰ کی نافرمانی کی۔ (اسی طرح) جس شخص نے میرے مقرر کردہ امیر کی اطاعت کی، اس نے درحقیقت میری اطاعت کی اور جس نے میرے مقرر کردہ امیر کی نافرمانی اطاعت امیر سے متعلق احکام ومسائل کی، اس نے در حقیقت میری نافرمانی کی۔ ‘‘","f2":"1۔باب کے ساتھ حدیث کی مطابقت واضح ہے۔ رسول ا اللہ صلی اللہ علیہ وسلم نے امیر کی اطاعت کی ترغیب اس طرح دی ہے کہ اس کی اطاعت کو اپنی اور ا اللہ عزو جل کی اطاعت ہی قرار دیا ہے۔ آپ صلی اللہ علیہ وسلم نے اپنی طرف سے کئی صحابہ کو امیر مقرر فرمایا جیسا کہ اہل یمن کی طرف حضرت معاذبن جبل، حضرت علی اور حضرت ابوموسیٰ اشعری رضی اللہ عنہم کو مقرر فرمایا۔2 رسول ا اللہ صلی اللہ علیہ وسلم نے جس اطاعت کی ترغیب دلائی ہے وہ مشروط و مقید اس اطاعت ہے، یعنی صرف معروف میں اطاعت، ا اللہ کی نافرمانی میں کسی کی اطاعت جائز نہیں رسول ا اللہ صلی اللہ علیہ وسلم کا یعنی خالق کی نافرمانی کی صورت میں مخلوق کی اطاعت جائز نہیں۔"}],[4194,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ «يا أيها الذين آمنوا أطيعوا اللہ وأطيعوا الرسول» \"اے لوگو، جو ایمان لائے ہو! اللہ کی اطاعت کرو اور رسول کی اطاعت کرو\" (النساء: ۵۹) یہ آیت عبداللہ بن حذافہ بن قیس بن عدی رضی اللہ عنہ کے سلسلے میں اتری، انہیں رسول اللہ صلی اللہ علیہ وسلم نے ایک سریہ میں بھیجا تھا ۱؎۔\n§وضاحت\n۱؎ عبداللہ بن حذافہ رضی اللہ عنہ اس سریہ میں کسی بات پر اپنے ماتحتوں پر ناراض ہو گئے تو آگ جلانے کا حکم دیا، اور جب آگ جلا دی گئی تو سب کو حکم دیا کہ اس میں کود جائیں، اس پر بعض ماتحتوں نے کہا: ہم تو آگ ہی سے بچنے کے لیے اسلام میں داخل ہوئے ہیں تو پھر آگ میں کیوں داخل ہوں، پھر معاملہ رسول اللہ صلی اللہ علیہ وسلم پر پیش کرنے کی بات آئی، تب یہ آیت نازل ہوئی۔ اس حدیث سے معلوم ہوا کہ اولی الامر سے مراد امراء ہیں نہ کہ علماء اور اگر علماء بھی شامل ہیں تو مقصود یہ ہو گا کہ ایسے امور جن کے بارے میں قرآن و حدیث میں واضح تعلیمات موجود نہ ہوں ان میں ان کی طرف رجوع کیا جائے۔ \" ائمہ اربعہ کے بارے میں خاص طور پر اس آیت کے نازل ہونے کی بات تو قیاس سے بہت زیادہ بعید ہے کیونکہ اس وقت تو ان کا وجود ہی نہیں تھا۔ اور ان کی تقلید جامد تو بقول شاہ ولی اللہ دہلوی چوتھی صدی کی پیداوار ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عباس رضی اللہ عنہ سے مروی ہے کہ یہ آیت: {یٰٓأَیُّہَا الَّذِیْنَ اٰمَنُوْٓا اَطِیْعُوا اللّٰہَ وَ اَطِیْعُوا الرَّسُوْلَ} ’’اے ایمان والو! اللہ تعالیٰ کی اطاعت کرو اور رسول کی اطاعت کرو‘‘ حضرت عبداللہ بن حذافہ بن قیس بن عدی رضی اللہ تعالٰی عنہ کے بارے میں اتری۔ انہیں رسول اللہ صلی اللہ علیہ وسلم نے ایک لشکر میں (امیر بنا کر) بھیجا تھا۔","f2":"(۱) آیت میں {اولی الامر} سے مراد امراء اور حکام ہیں۔ بعض ائمہ کے نزدیک اس سے مراد علماء بھی ہیں، خواہ علماء ہوں یا امراء و حکام سب کی اطاعت قرآن و سنت کے ساتھ مشروط ہے۔ اگر ان کا کوئی حکم شریعت کے مخالف ہو اس میں ان کی اطاعت بجا لانا ناجائز اور حرام ہے۔ (۲) اس آیت سے بعض لوگوں نیح تقلید شخص کا مسئلہ کشید کرنے کی جسارت کی ہے۔ حالانکہ آیت مبارکہ سے تو تقلید شخصی کا رد ہوتا ہے، بالخصوص منصوص امور میں تو کسی کی قطعاً کوئی تقلید جائز ہی نہیں، چاہے کوئی شخص کتنا ہی محترم، بزرگ، فقیہ اور بڑا کیوں نہ ہو، نص کے مقابلے میں تو ہر شخص ہی چھوٹا ہے۔ یہی حل امراء کا بھی ہے کہ ان کی اطاعت بھی صرف معروف میں ہے، نہ کہ منکر میں جیسا کہ متعدد بار سابقہ احادیث کے فوائد میں ذکر ہو چکا ہے۔ (۳) یہ حدیث متفق علیہ، یعنی صحیح بخاری اور صحیح مسلم میں ہے۔ صحیح بخاری میں اس کی پوری تفصیل موجود ہے جس کا خلاصہ یہ ہے کہ نبی صلی اللہ علیہ وسلم نے ایک دستہ بھیجا اور ایک شخص (حضرت عبداللہ بن حذافہ سہمی رضی اللہ تعالٰی عنہ) کو اس دستے کا امیر مقرر فرمایا۔ امیر دستہ نے کسی وجہ سے ناراض ہو کر اپنیح معمورین کو حکم دیا کہ لکڑیوں کا گٹھا جمع کر کے اسے آگ لگائو اور اس آگ میں کود جائو، چنانچہ کچھ لوگ تو آگ میں کودنے پر تیار ہو گئے جبکہ کچھ نے کہا کہ آگ سے بچنے کے لیے تو ہم مسلمان ہوئے ہیں اور نبی صلی اللہ علیہ وسلم کی طرف دوڑ کر آئے ہیں اور وہ آگ کے اندر جانے پر تیار نہ ہوئے۔ بالآخر نبی صلی اللہ علیہ وسلم تک یہ بات پہنچی تو آپ نے اس وقت فرمایا: [لَوْ دَخَلُوْہَا مَا خَرَجُوْا مِنْہَا إِلٰی یَوْمِ الْقِیٰمَۃِ] ’’اگر یہ لوگ آگ میں داخل ہو جاتے تو روز قیامت تک اسی میں رہتے، اس سے نکل نہ سکتے۔‘‘ اور آپ نے مزید فرمایا: [اَلطَّاعَۃُ فِی الْمَعْرُوْفِ] ’’اطاعت تو صرف معروف (شریعت مطہرہ کے عین مطابق) کاموں میں ہے۔‘‘ (صحیح البخاری، المغازی، حدیث: ۴۳۴۰) تقلید شخصی کے لیے اس آیت کو پیش کرنے والوں کو بہت بڑی ٹھوکر لگی ہے کیونکہ نزول قرآن کے وقت تو موجودہ دور کے مقلدین کے مجتہدین کا وجود تک دنیا میں نہیں تھا۔ پھر ان کی تقلید کیسی؟ ان مجتہدین کے زمانے میں بھی ان کی تقلید کا قطعاً کوئی رواج تھا اور نہ اس کا تصور ہی۔ بلکہ بدعتِ تقلید تو ہجرت نبوی کے چار سو سال بعد رائج ہوئی جیسا کہ شاہ ولی اللہ رحمہ اللہ نیح حجۃ اللہ البالغۃ میں اس کی تصریح فرمائی ہے۔ دین اسالم میں تو اس بات کی قطعاً کوئی گنجائش ہی نہیں ہے کہ تمام دینی معاملات میں کسی ایک متعین امتی مجتہد کی تقلید کی جائے چہ جائیکہ اس کو واجب قرار دیا جائے۔"}],[4195,"معاذ بن جبل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا: \"جہاد دو طرح کے ہیں: ایک تو یہ کہ کوئی خالص اللہ کی رضا کے لیے لڑے، امام کی اطاعت کرے، اپنے سب سے پسندیدہ مال کو خرچ کرے اور فساد سے دور رہے تو اس کا سونا جاگنا سب عبادت ہے، دوسرے یہ کہ کوئی شخص دکھاوے اور شہرت کے لیے جہاد کرے، امام کی نافرمانی کرے، اور زمین میں فساد برپا کرے، تو وہ برابر سراسر بھی نہ لوٹے گا\" (بلکہ عذاب کا مستحق ہو گا)۔","الألباني: حسن",{"u2":"حضرت معاذ بن جبل رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جنگ دو قسم کی ہوتی ہے۔ جو شخص اللہ تعالیٰ کی رضامندی کی نیت کرے، امام کی اطاعت کرے اور قیمتی مال (جہاد میں) صرف کرے اور فساد سے بچے تو اس کا سونا جاگنا سب اس کے لیے ثواب کا ذریعہ ہیں۔ لیکن جو شخص ریاکاری اور شہرت کے لیے لڑائی کرے، امام کی نافرمانی کرے اور زمین میں فساد پھیلائے، وہ تو پہلی حالت میں بھی واپس نہیں لوٹے گا۔‘‘","f2":"(۱) حدیث مبارکہ سے معلوم ہوتا ہے کہ بعض گناہ ایسے ہوتے ہیں جن کی وجہ سے سابقہ نیک اعمال ضائع ہو جاتے ہیں۔ اَعَاذَنَا اللّٰہُ مِنْہَا۔(۲) اس حدیث سے ریاکاری، شہرت اور فساد فی الارض کی مذمت ثابت ہوتی ہے، نیز ان کاموںڈ سے نہ صرف نیکیاں برباد ہوتی ہیں بلکہ اس کا مرتکب شخص گناہوں کا بہت بڑا بوجھ بھی اٹھا لیتا ہے۔ (۳) وہ مجاہد جو حدیث میں مذکور صفات کا حامل ہو گا وہی جہاد کے فضائل حاصل کر سکے گا وگرنہ جو امیر کا نافرمان ہو گا وہ جہاد کی فضیلت حاصل نہیں کر پائے گا۔ (۴) ’’فساد سے بچے‘‘ باہمی فساد مراد ہے، یعنی آپس میں لڑائی جھگڑا نہ کرے اس سے مسلمانوں میں آپس میں پھوٹ پڑے گی اور کافروں پر ان کا رعب ختم ہو جائے گا۔ (۵) ’’پہلی حالت میں بھی واپس نہیں لوٹے گا‘‘ یعنی جاد سے پہلے والے اعمال بھی برقرار نہیں رہیں گے بلکہ اس قسم کے جہاد کا گناہ پہلے سے کیے ہوئے بہت سے اعمال کے ثواب کو بھی ضائع کر دے گا، چہ جائیکہ اس جہاد کا ثواب ملے جبکہ صحیح نیت اور طریقے کے ساتھ جہاد کرنے سے جہاد کے علاوہ عادی امور کا بھی ثواب ملے گا، مثلاً: سونا، چلنا، پھرنا اور کھانا، پینا وغیرہ۔"}],[4196,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"امام ایک ڈھال ہے جس کے زیر سایہ ۱؎ سے لڑا جاتا ہے اور اس کے ذریعہ سے جان بچائی جاتی ہے۔ لہٰذا اگر وہ اللہ سے تقوی کا حکم دے اور انصاف کرے تو اسے اس کا اجر ملے گا، اور اگر وہ اس کے علاوہ کا حکم دے تو اس کا وبال اسی پر ہو گا\"۔\n§وضاحت\n۱؎: یعنی اس کی رائے سے اور اس کی قیادت میں جنگ لڑی جاتی ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’امام ڈھال ہے۔ اس کی آڑ میں لڑا جائے اور اس کی مدد کے ساتھ دشمن سے بچا جائے۔ ا گر وہ اللہ تعالیٰ سے ڈرتے ہوئے حکم دے اور انصاف کرے تو اس کو اس کا ثواب ملے گزا اور اگر وہ اس طرح حکم نہ دے تو اسے گناہ ہو گا۔‘‘","f2":"(۱) امیر و امام کے حقوق و فرائض کی تعیین و تبیین کے بعد جو بھی اس سے عدول اور تجاوز کرے گا، گناہ گار ہو گا۔ امام اپنے فرائض عدل و انصاف سے ادا کرے گا تو وہ اجر عظیم کا مستحق ہو گا اور اگر ظلم و بے انصافی کرے گا تو اللہ کے ہاں گناہ گار ٹھہرے گا۔ (۲) حدیث مبارکہ سے واضح ہوتا ہے کہ امام کو ڈھال بنایا جائے، شر اور فتنہ و فساد سے امام کے ذریعے سے بچا جائے۔ تمام معاملات میں اس کے مبنی بر انصاف فیصلے تسلیم کیے جائیں، اور اس کی اطاعت کی جائے، اسے کسی بھی صورت میں اپنے تعاون سے محروم نہ کیا جائے اور نہ اسے کسی حالت میں بے یار و مددگار چھوڑا جائے۔ اپنی ہلاکت کے ڈر سے اسے تنہا نہ چھوڑا جائے وغیرہ۔ بعض اہل علم نے کہا ہے کہ شرعی امیر و حاکم لوگوں کے لیے اس طرح ڈھال ہوتا ہے کہ اس کے ہوتے ہوئے کوئی شخص دوسرے پر ظلم نہیں کرتا، نیز دشمن بھی اس سے خوف زدہ رہتا ہے، لہٰذا اس ڈھال کی حفاظت کرنا تمام مسلمانوں کا فرض ہے۔ بعض نے کہا ہے کہ ’’اس کی آڑ میں لڑا جائے‘‘ کے معنی ہیں کہ امام کو محفوظ جگہ رکھا جائے، دوسرے معنیٰ یہ ہیں کہ امام خود مجاہدین کی اگلی صفوں میں ہو اور بہادری سے دشمن کے ساتھ قتال کرے۔ دونوں معانی درست ہیں کیونکہ بعض مقامات پر نبی صلی اللہ علیہ وسلم کے لیے محفوظ جگہ بنائی گی۔ جہاں سے آپ میدان جنگ کا مشاہدہ کرتے اور اس کے مطابق اوامر جاری فرماتے اور بعض مقامات میں نبی صلی اللہ علیہ وسلم کا اگلی صفوں میں رہ کر قتال کرنا بھی ثابت ہے، جب جنگ کی شدت ہوتی تو صحابہ آپ کو اپنے لیے ڈھال بناتے۔"}],[4197,"تمیم الداری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دین نصیحت خیر خواہی کا نام ہے\"، آپ نے کہا: (نصیحت و خیر خواہی) کس کے لیے؟ اللہ کے رسول! آپ نے فرمایا: \"اللہ کے لیے، اس کی کتاب کے لیے، اس کے رسول کے لیے، مسلمانوں کے اماموں کے لیے اور عوام کے لیے\" ۱؎۔\n§وضاحت\n۱؎: اللہ کے لیے خیر خواہی کا مفہوم یہ ہے کہ بندہ اللہ کی وحدانیت کا قائل ہو اور اس کی ہر عبادت خالص اللہ کی رضا کے لیے ہو۔ کتاب اللہ :(قرآن ) کے لیے خیر خواہی یہ ہے کہ اس پر ایمان لائے اور عمل کرے۔ رسول کے لیے خیر خواہی یہ ہے کہ نبوت و رسالت محمدیہ کی تصدیق کرنے کے ساتھ رسول اللہ صلی اللہ علیہ وسلم جن چیزوں کا حکم دیں اسے بجا لائے اور جس چیز سے منع کریں اس سے باز رہے، اور آپ کی تعلیمات کو عام کرے، مسلمانوں کے حاکموں کے لیے خیر خواہی یہ ہے کہ حق بات میں ان کی تابعداری کی جائے اور کسی شرعی وجہ کے بغیر ان کے خلاف بغاوت کا راستہ نہ اپنایا جائے۔ اور عام مسلمانوں کے لیے خیر خواہی یہ ہے کہ ان میں امربالمعروف اور نہی عن المنکر کا فریضہ انجام دیا جائے، اور ان کے مصالح کی طرف ان کی رہنمائی کی جائے۔","الألباني: صحيح",{"u2":"حضرت تمیم داری رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دین تو بس خلوص و خیر خواہی کا نام ہے۔‘‘ صحابہ نے عرض کی: اے اللہ کے رسول! کس سے؟ آپ نے فرمایا: ’’اللہ تعالیٰ سے، اس کی کتاب سے، اس کے رسول سے، مسلمانوں کے حکام سے او عوام الناس سے۔‘‘","f2":"دین اخلاص کا نام ہے۔ اخلاص نہ ہو تو شرک، نفاق، ریاکاری، دغا بازی اور دھوکا دہی جیسے قبیح اوصاف پیدا ہو جاتے ہیں۔ اور اللہ تعالیٰ سے اخلاص یہ ہے کہ صرف اسی کی عبادت کرے، اسی کو پکارے، اسی پر بھروسا کرے اور اسی سے ڈرے۔ کتاب سے اخلاص یہ ہے کہ اس پر عمل کرے اور اس کا احترام کرے۔ رسول اللہ صلی اللہ علیہ وسلم سے اخلاص یہ ہے کہ آپ کی اطاعت کرے، ہر چیز سے بڑھ کر محبت رکھے، آپ کے فرمان پر مر مٹے۔ آپ کے مقابلے میں کسی کی پروا نہ کرے۔ حکام سے اخلاص یہ ہے کہ ان کی بیعت کر کے ان سے وفادار رہے اور حتی الامکان شرعی حدود کے اندر ان کی اطاعت کرے۔ ان کے خلاف بغاوت نہ کرے۔ او عام مسلمانوں سے اخلاص یہ ہے کہ ان کا خیر خواہ رہے، ان کو دھوکا نہ دے، کسی کو تکلیف نہ پہنچائے اور دوسروں کو اپنے شر سے محفوظ رکھے۔"}],[4198,"تمیم داری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دین خیر خواہی کا نام ہے\" لوگوں نے عرض کیا: کس کے لیے؟ اللہ کے رسول! آپ نے فرمایا: \"اللہ کے لیے، اس کی کتاب (قرآن) کے لیے، اس کے رسول (محمد) کے لیے، مسلمانوں کے ائمہ اور عوام کے لیے\"۔","الألباني: صحيح",{"u2":"حضرت تمیم داری سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دین تو ہے ہی اخلاص کا نام۔‘‘ صحابہ نے عرض کی: اے اللہ کے رسول! کس کے ساتھ اخلاص؟ آپ نے فرمایا: ’’اللہ تعالیٰ کے ساتھ، اس کی کتاب کے ساتھ، اس کے رسول کے ساتھ اور مسلمانوں کے حکام کے ساتھ اور عام مسلمانوں کے ساتھ۔‘‘"}],[4199,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا: \"بلاشبہ دین نصیحت اور خیر خواہی کا نام ہے، بلاشبہ دین خلوص اور خیر خواہی ہے، بلاشبہ دین خلوص اور خیر خواہی ہے\"، لوگوں نے عرض کیا: کس کے لیے، اللہ کے رسول! آپ نے فرمایا: \"اللہ کے لیے، اس کی کتاب (قرآن) کے لیے، اس کے رسول (محمد) کے لیے، مسلمانوں کے حکمرانوں اور عوام کے لیے\"۔","الألباني: حسن صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یقینا دین خیر خواہی کو کہتے ہیں۔ بلاشبہ دین خیر خواہی کا نام ہے۔ بے شک دین خیر خواہی سے عبارت ہے۔‘‘ صحابۂ کرام رضی اللہ عنہم نے پوچھا: اے اللہ کے رسول! کس کی (خیر خواہی۔) آپ نے فرمایا: ’’اللہ تعالیٰ، اس کی کتاب کی، اس کے رسول کی، مسلمان حاکموں کی او عام مسلمانوں کی۔‘‘"}],[4200,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دین نصیحت اور خیر خواہی کا نام ہے۔ لوگوں نے عرض کیا: اللہ کے رسول! کس کے لیے۔ آپ نے فرمایا: \"اللہ کے لیے، اس کی کتاب (قرآن) کے لیے، اس کے رسول (محمد) کے لیے، مسلمانوں کے حکمرانوں کے لیے اور عوام کے لیے\"۔","الألباني: حسن صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دین خلوص کا نام ہے۔‘‘ صحابۂ کرام رضی اللہ عنہم نے عرض کی: اے اللہ کے رسول! کس سے (خلوص۔) آپ نے فرمایا: ’’اللہ تعالیٰ سے، اس کی کتاب سے، اس کے رسول سے، مسلمانوں کے حکا اور رعایا سے۔‘‘"}],[4201,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا کوئی حاکم نہیں جس کے دو قسم کے مشیر نہ ہوں، ایک مشیر اسے نیکی کا حکم دیتا ہے اور برائی سے روکتا ہے، اور دوسرا اسے بگاڑنے میں کوئی کسر نہیں اٹھا رکھتا۔ لہٰذا جو اس کے شر سے بچا وہ بچ گیا اور ان دونوں مشیروں میں سے جو اس پر غالب آ جاتا ہے وہ اسی میں سے ہو جاتا ہے\" ۱؎۔\n§وضاحت\n۱؎: اس لیے ہر صاحب اختیار :(خواہ حاکم اعلی ہو یا ادنی جیسے گورنر، تھا نے دار یا کسی تنظیم کا سربراہ ) اسے چاہیئے کہ اپنا مشیر بہت چھان پھٹک کر اختیار کرے، اس کے ساتھ ساتھ یہ دعا بھی کرتا رہے کہ اے اللہ ! مجھے صالح مشیر کار عطا فرما۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہر حاکم کے مشیر دو قسم کے ہوتے ہیں۔ ایک مشیر وہ جو اسے نیکی کا حکم دیتا ہے اور برائی سے روکتا ہے اور دوسرا مشیر وہ جو اس کو خراب کرنے میں کوئی کسر نہیں چھوڑتا۔ جو حاکم برے مشیروں سے بچ گیا، وہ حقیقتاً بچ گیا۔ اور اس کا شمار ان میں سے ہو گا جو اس پر غالب آئے رہے۔‘‘","f2":"معلوم ہوا کہ امیر یا حاکم کی کامیابی اور ناکامی اس کے مشیروں پر موقوف ہے۔ اگر مشیر اچھے ہوں گے تو حاکم اچھا رہے گا۔ او اگر مشیر برے ہوں گے تو حاکم بھی برا ہو گا، خواہ بذات خود اچھا ہو۔ یہی مطلب ہے آخری جملے کا کہ حاکم پر جس قسم کی مشیروں کا غلبہ ہو، حاکم کو اسی قسم میں شمار کیا جائے گا۔ اس کی اپنی ذات کا لحاظ نہیں رکھا جائے گا۔ تجربہ بھی اس بات کا شاہد ہے کہ بعض برے حاکموں کو اچھے مشیروں کی وجہ سے نیک نامی حاصل ہو گئی، جیسے سلیمان بن عبدالملک کے ہاتھوں حضرت عمر بن عبدالعزیز رحمہ اللہ کی نامزدگی ایک اچھے مشیر کا کارنامہ ہے۔"}],[4202,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے کوئی نبی ایسا نہیں بھیجا اور نہ کوئی خلیفہ ایسا بنایا جس کے دو مشیر (قریبی راز دار) نہ ہوں۔ ایک مشیر اسے خیر و بھلائی کا حکم دیتا ہے اور دوسرا اسے شر اور برے کام کا حکم دیتا اور اس پر ابھارتا ہے، اور برائیوں سے معصوم محفوظ تو وہ ہے جسے اللہ تعالی معصوم محفوظ رکھے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ نے جو بھی نبی بھیجا اور جسے بھی خلیفہ مقرر فرمایا، اس کے دو قسم کے مشیر ہوتے ہیں۔ ایک مشیر اسے نیکی کا حکم دیتے تھے اور دوسرے مشیر اسے برائی کا مشورہ دیتے تھے اور برائی کی ترغیب دلاتے تھے۔ اور محفوظ وہی رہتا ہے جسے اللہ تعالیٰ محفوظ رکھے۔‘‘","f2":"یہ بات صرف نبی و خلیفہ ہی سے خاص نہیں، ہر شخص کو اسی صورت حال سے واسطہ پڑتا ہے۔ اس کو اچھے ساتھی بھی ملتے ہیں اور برے بھی۔ خوش قسمت ہے وہ شخص جس پر غلبہ اچھے ساتھیوں او مشیروں کا ہوتا ہے اور یہ اللہ تعالیٰ کی رحمت کے بغیر ممکن نہیں۔ اور بدنصیب ہے وہ شخص جو برے ساتھیوں اور مشیروں کے زیر اثر رہا۔"}],[4203,"ابوایوب انصاری رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"کوئی نبی ایسا نہیں بھیجا گیا اور نہ اس کے بعد کوئی خلیفہ ایسا ہوا جس کے دو مشیر و راز دار نہ ہوں۔ ایک مشیر و راز دار اسے بھلائی کا حکم دیتا اور برائی سے روکتا ہے اور دوسرا اسے بگاڑنے میں کوئی کسر باقی نہیں چھوڑتا۔ لہٰذا جو خراب مشیر سے بچ گیا وہ (برائی اور فساد سے) بچ گیا\"۔","الألباني: صحيح",{"u2":"حضرت ابو ایوب رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جو بھی نبی مبعوث ہوئے یا جو ان کے بعد خلیفہ بنے، ان کے مشیر دو قسم کے ہوتے تھے۔ ایک مشیر تو ان کو نیکی کا حکم دیتے تھے او برائی سے روکتے تھے اور دوسرے ان کو خراب کرنے کی پوری کوشش کرتے تھے۔ جو شخص برے مشیر سے بچ گیا، وہ حقیقتاً بچ گیا۔‘‘","f2":"(۱) ’’مشیر‘‘ عربی میں لفظ بطانۃ استعمال ہوا ہے۔ اس کے لفظی معنی رازدان اور مشیر کے ہیں۔ گہرے دوست کو بھی بطانۃ کہہ لیا جاتا ہے کیونکہ یہ بھی راز دان ہوتا ہے۔ (۲) ’’حقیقتاً بچ گیا‘‘ دنیا میں خرابی، ذلت اور رسوائی سے اور آخرت میں اللہ تعالیٰ کی ناراضی اور عذات سے۔ خلق بھی راضی، خالق بھی راضی۔"}],[4204,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے جب کوئی کسی کام کا ذمہ دار ہو جائے پھر اللہ اس سے خیر کا ارادہ کرے تو اس کے لیے ایسا صالح وزیر بنا دیتا ہے کہ اگر وہ بھول جائے تو وہ اسے یاد دلاتا ہے اور اگر اسے یاد ہو تو اس کی مدد کرتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت قاسم بن محمد سے روایت ہے کہ میں نے اپنی پھوپھی (حضرت عائشہ رضی اللہ عنہا) کو فرماتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے جو شخص کسی کام کا ذمہ دار بنے، پھر اللہ تعالیٰ اس کے لیے بہتری کا ارادہ فرمائے تو اس کے لیے اچھا وزیر مہیا فرما دیتا ہے۔ جو اس کو بھول جانے کی صورت میں اس کی ذمہ داری یاد دلاتا ہے اور اگر اسے یاد ہو تو اس کی (ذمہ داری کی ادائیگی میں) مدد کرتا ہے۔‘‘","f2":"(۱) باب کے ساتھ حدیث کی مناسبت اس طرح ہے کہ امام اور حاکم کے لیے اچھا، لائق و مخلص وزیر بنانا مشروع ہے تاکہ امارت کے اہم معاملات میں وہ امیر کا معاون و مددگار بنے اور امیر سے امارت کا کچھ بوجھ ہلکا کرے۔ (۲) بعض امراء و حکام پر اللہ تعالیٰ کا خاص فضل و کرم اور اس کی خصوصی عنایت و رحمت ہوتی ہے کہ وہ ان کو سچے، سُچے، خالص اور کھرے وزیر عطا فرماتا ہے جو اس کے مخلص معاون اور ہمدرد و خیر خواہ ہوتے ہیں۔ امر و امام اگر کوئی اہم بات بھول جائے تو وہ اسے یاد کراتے ہیں، اور اگر اسے یاد ہو تو اس سلسلے میں اس کا تعاون کرتے ہیں۔ (۳) امیر و حاکم کو مطلق العنان قطعاً نہیں ہونا چاہیے کہ بغیر کسی کے صلاح و مشورے کے من مانے فیصلے کرے، محض اپنی رائے اور پسند کو ترجیح دے، اپنے آپ کو عقل کل سمجھے اور اپنی مرضی کی سیاست و سیادت اور حکمرانی کرے۔ ایسا کرنے سے رعایا کے بہت سے حقوق ضائع اور پامال ہوتے ہیں، بلکہ امیر و حاکم کو چاہیے کہ امین و دیانت دار، دین پر کاربند، پختہ فکر اور باعمل صاحب بصیرت و صاحب کردار وزیر و مشیر اپنائے جو اچھے مشوروں اور مثبت صلاحیتوں سے اس کی راہنمائی کریں۔ یہ معاملہ اس قدر اہم اور سنجیدہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم جو تمام تر اعلیٰ و افضل انسانی کمالات کے حامل، ذہانت و فطانت اور شرافت و نجابت کے بادشاہ تھے، نیز آپ کو وحیٔ الٰہی کی تائید بھی حاصل تھی، اس کے باوجود آپ صلی اللہ علیہ وسلم کو {وَ شَاوِرْہُمْ فِی الْاَمْرِ} کے امر سے حکماً مشاورت کا پابند کر دیا گیا۔ اس کے بعد تو اس مسئلے کی اہمیت کی بابت کسی مزید بات کی گنجائش ہی باقی نہیں رہی۔ (۴) ’’وزیر‘‘ عربی زبان کا لفظ ہے جس کے معنیٰ بوجھ اٹھانے والے کے ہیں۔ مراد اس سے ساتھی اور معاون ہے۔ اچھا ساتھی اور معاون بھی اللہ تعالیٰ کی نعمت ہے۔ صرف حاکم کے لیے ہی نہیں بلکہ ہر ذمہ دار کے لیے حتیٰ کہ خاوند کے لیے اچھی بیوی بھی۔"}],[4205,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک فوج بھیجی اور ایک شخص ۱؎ کو اس کا امیر مقرر کیا، اس نے آگ جلائی اور کہا: تم لوگ اس میں داخل ہو جاؤ، تو کچھ لوگوں نے اس میں داخل ہونا چاہا اور دوسروں نے کہا: ہم تو (ایمان لا کر) آگ ہی سے بھاگے ہیں، پھر لوگوں نے اس کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا۔ آپ نے ان لوگوں سے جنہوں نے اس میں داخل ہونا چاہا تھا فرمایا: \"اگر تم اس میں داخل ہو جاتے تو قیامت تک اسی میں رہتے، اور دوسروں سے اچھی بات کہی\"۔ (ابوموسی (محمد بن المثنی) نے اپنی حدیث میں :(«خیراً» کے بجائے) «قولاً حسناً» (بہتر بات) کہا ہے)۔ اور آپ صلی اللہ علیہ وسلم نے فرمایا:\"اللہ کی نافرمانی میں اطاعت نہیں ہوتی، اطاعت صرف نیک کاموں میں ہے\" ۲؎۔\n§وضاحت\n۱؎: اس سے مراد وہی عبداللہ بن حذافہ رضی اللہ عنہ ہیں جن کا تذکرہ حدیث نمبر ۴۱۹۹ میں گزرا۔ ۲؎: \" صرف نیک کاموں میں اطاعت، اور نافرمانی کے کاموں میں اطاعت نہ کرنے \" کی بات ہر ایک اختیار والے کے ساتھ ہو گی: خواہ حکمران اعلی ہو یا ادنی، یا والدین، یا اساتذہ، شوہر یا کسی تنظیم کا سربراہ۔ اگر کسی سربراہ کا اکثر حکم اللہ کی نافرمانی والا ہی ہو تو ایسے آدمی کو سارے ماتحت لوگ مشورہ کر کے اختیار سے بے دخل کر دیں۔ لیکن ہتھیار سے نہیں، یا فتنہ و فساد برپا کر کے نہیں۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ تعالٰی عنہ سے رویات ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک لشکر بھیجا اور ان پر ایک آدمی کو امیر مقرر فرمایا۔ اس نے آگ جلائی اور کہنے لگا: اس میں چھلانگیں لگا دو۔ کچھ لوگوں نے چھلانگیں لگانے کا ارادہ کر لیا۔ دوسرے کہنے لگے: ہم آگ سے بچنے کے لیے تو مسلمان ہوئے ہیں (لہٰذا ہم آگ میں چھلانگ نہیں لگائیں گے)۔ پھر (واپسی پر) انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس بات کا ذکر کیا تو آپ نے ان لوگوں کو، جنہوں نے چھلانگ لگانے کا ارادہ کیا تھا، (مخاطب کر کے) فرمایا: ’’اگر تم آگ میں چھلانگیں لگا دیتے تو قیامت تک آگ ہی میں رہتے۔‘‘اور دوسروں کے لیے خیر کا کلمہ کہا۔ (استاد) ابو موسیٰ (محمد بن مثنیٰ) نے اپنی حدیث میں کہا: اور آپ نے دوسرے لوگوں کے بارے میں اچھی بات فرمائی۔ اور فرمایا: ’’اللہ تعالیٰ کی نافرمانی ہوتی ہو تو کسی کی اطاعت جائز نہیں۔ صرف اطاعت اچھے کاموں میں ہے۔‘‘","f2":"(۱) اس حدیث سے معلوم ہوا کہ اگر کوئی امام و امیر ایسا حکم دے جو اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کی نافرمانی پر مبنی ہو تو ایسا حکم اور امیر قطعاً واجب الطاعۃ نہیں۔ اور اگر کوئی شخص ایسے کسی حکم کو مانے گا تو اس کا وبال اسی پر ہو گا۔ (۲) حدیث مبارکہ سے یہ بات بھی معلوم ہوتی ہے کہ غصہ بڑے بڑے عقیل و فہیم اور جلیل القدر عظماء کی عقل کو بھی مائوف کر دیتا ہے جیسا کہ اس صحابیٔ رسول کا معاملہ ہے کہ جسے خود رسول اللہ صلی اللہ علیہ وسلم نے امیر سریہ مقرر فرمایا اور کسی بات پر ناراض ہو کر وہ غصے میں آ گئے اور اپنے ساتھیوں کو آگ جلا کر اس میں کود جانے کا حکم دے دیا۔ (۳) اس حدیث سے یہ بات بھی معلوم ہوتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی ساری امت، ضلالت و گمراہی پر جمع نہیں ہو سکتی جیسا کہ صحابۂ کرام رضی اللہ عنہم کی ایک جماعت نے اپنے امیر کے غیر شرعی حکم کی اطاعت نہیں کی۔ (۴) رسول اللہ صلی اللہ علیہ وسلم نے سریہ میں جانے والے تمام صحابۂ کرام رضی اللہ عنہم کو حکم دیا تھا کہ اپنے امیر کی اطاعت کرنا۔ یہی وجہ ہے کہ جب حالت ناراضی میں بھی انہیں امیر نے آگ میں کودنے کا حکم دیا تو کچھ لوگ اس پر تیار ہو گئے کیونکہ انہوں نے اطاعت امیر والے مطلق حکم کو عام، یعنی ہر قسم کے حالات کو شامل سمجھا، لیکن اس حدیث سے یہ ثابت ہوتا ہے کہ حکم مطلق کا اطلاق عام اور ہر قسم کے حالات پر ضروری نہیں بلکہ وہاں اطلاق ہو گا جہاں اللہ او اس کے رسول صلی اللہ علیہ وسلم کی نافرمانی نہ ہوتی ہو، اسی لیے رسول اللہ صلی اللہ علیہ وسلم نے صحابۂ کرام رضی اللہ عنہم کے لیے اس کی وضاحت فرما دی۔ (۵) ’’آگ ہی میں رہتے‘‘ یعنی ان کو قبر میں عذاب ہوتا۔ برزخی زندگی میں جہنم سے تعلق ہی کو عذاب قبر کہا جاتا ہے اور جنت سے تعلق کو ثواب قبر۔ اور جہنم میں غالب آگ ہی ہے۔"}],[4206,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان شخص پر (امام و حکمراں کی) ہر چیز میں سمع و طاعت (حکم سننا اور اس پر عمل کرنا) واجب ہے خواہ اسے پسند ہو یا ناپسند، سوائے اس کے کہ اسے گناہ کے کام کا حکم دیا جائے۔ لہٰذا جب اسے گناہ کے کام کا حکم دیا جائے تو کوئی سمع و طاعت نہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان شخص پر ضروری ہے کہ وہ امیر کی بات سنے اور اس کی اطاعت کرے، خواہ پسند کرتا ہو یا نہ۔ الا یہ کہ اسے (اللہ اور اس کے رسول کی) نافرمانی اور گناہ والا حکم دیا جائے۔ ایسی صورت میں نہ وہ امیر کی بات سنے، نہ اس کی اطاعت کرے۔‘‘"}],[4207,"کعب بن عجرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس آئے، ہم نو لوگ تھے، آپ نے فرمایا: \"میرے بعد کچھ امراء ہوں گے، جو ان کے جھوٹ کی تصدیق کرے گا اور ظلم میں ان کی مدد کرے گا وہ میرا نہیں اور نہ میں اس کا ہوں، اور نہ ہی وہ (قیامت کے دن) میرے پاس حوض پہ آ سکے گا۔ اور جس نے جھوٹ میں ان کی تصدیق نہیں کی اور ظلم میں ان کی مدد نہیں کی تو وہ میرا ہے اور میں اس کا ہوں اور وہ میرے پاس حوض پر آئے گا\" ۱؎۔\n§وضاحت\n۱؎: کسی حکمران، امیر، صدر، ناظم، کسی ادارہ کے سربراہ کے حوالی موالی جو ہر نیک و بد میں اس کی خوشامد کرتے ہیں اس کی ہر ہاں میں ہاں ملاتے ہیں وہ اس حدیث میں بیان کردہ وعید شدید پر توجہ دیں، نیز یہ بات بھی قابل غور ہے کہ آپ صلی اللہ علیہ وسلم نے ظالم امیر کے ظلم میں تعاون کرنے والے کے لیے اتنی سخت وعید تو سنائی مگر اس ظالم امیر کو ہٹا دینے کی کوئی بات نہیں کی، ایسے ظالم کو نصیحت کی جائے گی یا سارے مسلمانوں کے اصحاب رائے کے مشورہ سے علاحدہ کیا جائے گا :(بغیر فتنہ وفساد برپا کئے )۔","الألباني: صحيح",{"u2":"حضرت کعب بن عجرہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے۔ ہم نو ساتھی تھے۔ آپ نے فرمایا: ’’میرے بعد کچھ ایسے امیر ہوں گے کہ جو شخص ان کے جھوٹ میں ان کی تصدیق کرے گا اور ان کے ظلم میں ان کی مدد کرے گا تو اس کا مجھ سے کوئی تعلق نہیں اور نہ اس سے میرا کوئی تعلق ہے۔ اور اسے میرے پاس حوض کوثر پر آنا نصیب نہیں ہو گا۔ اور جو شخص ان کے جھوٹ میں ان کی تصدیق نہ کرے اور ان کے ظلم میں ان کا ساتھ نہ دے، وہ مجھ سے تعلق رکھتا ہے اور میں اس سے تعلق رکھتا ہوں اور وہ لازماً میرے پاس حوض کوثر پر آئے گا۔‘‘","f2":"(۱) باب کے ساتھ حدیث کی مناسبت واضح ہے کہ جو شخص، کسی بھی طریقے سے، حاکم و امیر کے ظلم پر اس کی حمایت و اعانت کرے گا، اس کے لیے یہ خطرناک وعیدہ ہے کہ وہ حوض کوثر پر آنے اور جامِ کوثر نوش کرنے کی سعادت سے محروم ہو جائے گا، لہٰذا اس وعید شدید کو مدنظر رکھتے ہوئے ظالم حکمرانوں کے حضورت اپنی بزرگانہ و مشفقانہ، نیز عالمانہ و فاضلانہ خدمات پیش کرنے کے عوض اسمبلی کی ممبری، پرمٹ و پلاٹ اور دیگر عارضی و فانی اور زوال پذیر مراعات حاصل کرنے اور ان ’’کامیابیوں‘‘ کو اپنا کمال ہنر سمجھنے والے، متلاشیانِ قربِ شاہی، درباری ملائوں اور اصحاب جبہ و دستار کو بھی اپنی ’’سنہری خدمات‘‘ کا ازسر نو جائزہ ضرور لینا چاہیے۔ ظلم و ناانصافی والے معاملے میں حاکم و امیر کی مدد کرنا کبیرہ گناہ ہے۔ (۲) ظالم حکمرانوں اور بے انصاف امراء سے فاصلہ رکھنا چاہیے تاکہ ان کے شر سے اپنے دین و ایمان کو سلامت رکھا جا سکے۔ ان سے قرب کی صورت میں یا تو ان کے ظلم و زیادتی پر، کسی بھی انداز سے، انہیں تعاون ملے گا یا ان کی تائیدڈ ہو گی یا پھر ظلم و زیادتی پر خاموشی اور سکوت کرنا پڑے گا، اور اصلاح کی صورت میں اپنے دین و ایمان کے فساد یا اپنی جان و مال کے اتلاف کا خطرہ ہے، اس لیے عافیت، اور سلامتی ان لوگوں سے دور رہنے ہی میں ہے۔ یہی وجہ ہے کہ اکثر سلف صلاح حکمرانوں سے دور ہی رہا کرتے تاکہ ان کے شر سے اپنے آپ کو اور اپنے دین کو محفوظ رکھ سکیں۔ (۳) ’’تصدیق نہ کرے‘‘ یعنی ان کے پاس جائے تو سہی مگر حق پر قائم رہے اور انہیں بھی حق کی طرف دعوت دیتا رہے۔ واقعتا یہ بلند مرتبہ ہے۔"}],[4208,"کعب بن عجرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس آئے، ہم نو لوگ تھے، پانچ ایک طرح کے اور چار دوسری طرح کے، ان میں سے کچھ عرب تھے اور کچھ عجم۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"سنو! کیا تم نے سنا؟ میرے بعد عنقریب کچھ امراء ہوں گے، جو ان کے یہاں جائے گا اور ان کے جھوٹ کی تصدیق کرے گا اور ظلم میں ان کی مدد کرے گا تو وہ میرا نہیں اور نہ میں اس کا ہوں، اور نہ وہ میرے پاس (قیامت کے دن) حوض پر نہ آ سکے گا، اور جو ان کے ہاں نہیں گیا، ان کے جھوٹ کی تصدیق نہیں کی، اور ظلم میں ان کی مدد نہیں کی تو وہ میرا ہے اور میں اس کا ہوں اور عنقریب وہ میرے پاس حوض پر آئے گا\"۔","الألباني: صحيح",{"u2":"حضرت کعب بن عجرہ رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے۔ ہم نو آدمی تھے۔ پانچ عربی، چار عجمی یا چار عربی اور پانچ عجمی۔ آپ نے فرمایا: ’’سنو! کیا تم سن رہے ہو؟ یقینا میرے (فوت ہونے کے) بعد کچھ ایسے امیر ہوں گے کہ جو شخص ان کے پاس جائے گا، پھر ان کے جھوٹ میں ان کی تصدیق کرے گا، اور ان کے ظلم میں ان کا ساتھ دے گا، نہ اس کا مجھ سے تعلق ہے اور نہ میرا اس سے۔ اور وہ میرے پاس حوض کوثر پر نہیں آ سکے گا۔ اور جو شخص ان کے پاس نہ گیا (یا گیا لیکن) ان کے جھوٹ کی تصدیق نہ کی اور ظلم میں ان کا ساتھ نہ دیا، وہ میرا ہے۔ میں اس کا ہوں اور وہ ضرور میرے پاس حوض کوثر پر حاضری کی سعادت حاصل کرے گا۔‘‘"}],[4209,"طارق بن شہاب رضی اللہ عنہ ۱؎ کہتے ہیں کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم سے سوال کیا اور وہ یا آپ اپنا پیر رکاب میں رکھے ہوئے تھے، کون سا جہاد افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ظالم حکمراں کے پاس حق اور سچ کہنا\"۔\n§وضاحت\n۱؎: طارق بن شہاب رضی اللہ عنہ کو نبی اکرم صلی اللہ علیہ وسلم کو دیکھنے کا شرف تو حاصل ہے مگر آپ سے خود کوئی حدیث نہیں سنی تھی، آپ کی روایت کسی اور صحابی کے واسطہ سے ہوتی ہے، اور اس صحابی کا نام نہ معلوم ہونے سے حدیث کی صحت میں فرق نہیں پڑتا۔ کیونکہ سارے صحابہ کرام ثقہ ہیں اور سند سے معلوم ثقہ، بالخصوص صحابی کا ساقط ہونا حدیث کی صحت میں موثر نہیں، اس لیے کہ سارے صحابہ ثقہ اور عدول ہیں، اس طرح کی حدیث جس میں حدیث نقل کرنے میں صحابی واسطہ صحابی کا ذکر کئے بغیر حدیث کی نسبت رسول اللہ صلی اللہ علیہ وسلم کی طرف کر دے، علمائے حدیث کی اصطلاح میں \" مرسل صحابی \" کہتے ہیں، اور \" مرسل صحابی \" مقبول و مستفید ہے۔","الألباني: صحيح",{"u2":"حضرت طارق بن شہاب رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک آدمی نے نبیٔ اکرم صلی اللہ علیہ وسلم سے پوچھا، جبکہ آپ صلی اللہ علیہ وسلم اپنا پائو مبارک رکاب میں رکھ چکے تھے: کون سا جہاد افضل ہے؟ آپ نے فرمایا: ’’ظالم بادشاہ کے سامنے حق بات کہنا۔‘‘","f2":"(۱) یہ اس لیے افضل جہاد ہے کہ اس میں جان کا جانا یقینی ہوتا ہے، پھر میدان جنگ میں تو آدمی اپنا دفاع بھی کر سکتا ہے جبکہ یہاں وہ بھی ممکن نہیں۔ ہر لحاظ سے ہاتھ بندھے ہوتے ہیں۔ اور پھر برے طریقے سے مارا جاتا ہے۔ ایسے شخص کی حوصلہ افزائی کرنے والا بھی کوئی نہیں ہوتا۔ ملامت کرنے والے زیادہ ہوتے ہیں۔ (۲) ’’رکاب میں پائوں رکھ چکے تھے‘‘ یعنی اونٹ پر سوار ہو رہے تھے۔ (۳) ’’ظالم بادشاہ‘‘ جو کلمۂ حق کہنے والے کو برداشت نہ کرتا ہو۔"}],[4210,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ ہم ایک مجلس میں نبی اکرم صلی اللہ علیہ وسلم کے پاس تھے تو آپ نے فرمایا: \"تم لوگ مجھ سے بیعت کرو کہ تم اللہ کے ساتھ کسی چیز کو شریک نہ ٹھہراؤ گے، نہ چوری کرو گے، نہ زنا کرو گے، پھر آپ نے لوگوں کو (سورۃ الممتحنہ کی) آیت پڑھ کر سنائی\" ۱؎، پھر فرمایا: \"تم میں سے جس نے بیعت کو پورا کیا تو اس کا اجر اللہ پر ہے، اور جس نے اس میں سے کسی غلط کام کو انجام دیا اور اللہ تعالی نے اسے چھپائے رکھا تو اللہ تعالی کے اختیار میں ہے چاہے تو اسے سزا دے، اور چاہے تو اسے معاف کر دے\"۔\n§وضاحت\n۱؎: اس آیت سے مراد سورۃ الممتحنہ کی یہ آیت ہے: «يا أيها النبي إذا جائك المؤمنات يبايعنك على أن لايشركن بالله شيئا …»:(سورة الممتحنة: 12 )","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ تعالٰی عنہ سے مروی ہے کہ ہم ایک مجلس میں نبیٔ اکرم صلی اللہ علیہ وسلم کے ساتھ تھے۔ آپ نے فرمایا: ’’مجھ سے اس پر بیعت کرو کہ تم اللہ تعالیٰ کے ساتھ کسی کو شریک نہیں ٹھہرائو گے، چوری نہیں کرو گے۔ زنا نہیں کرو گے۔‘‘ (آپ نے پوری آیت تلاوت فرمائی۔) ’’تم میں سے جو شخص اس عہد کو پورا کرے گا، اس کا اجر و ثواب اللہ تعالیٰ کے ذمے ہے لیکن جس شخص نے ان میں سے کوئی کام کر لیا اور اللہ تعالیٰ نے اس پر پردہ ڈال دیا تو وہ اللہ تعالیٰ کے اختیار میں ہے۔ چاہے اس کو عذاب دے، چاہے معاف فرمائے۔‘‘","f2":"(۱) ’’پوری آیت‘‘ اس سے مراد سورۂ ممتحنہ کی آیت ہے جس میں عورتوں سے مذکورہ بالا دیگر امور پر بیعت لینے کا حکم دیا گیا ہے۔ یہ آیت عورتوں کے بارے میں ہے اور الفاظ بھی عورتوں والے ہیں۔ ظاہر تو یہی ہے کہ آپ نے مردوں والے الفاظ کے ساتھ پڑھی ہو گی۔ لیکن اگر اصل الفاظ کے ساتھ پڑھی ہو، تب بھی کوئی بعد نہیں کیونکہ مقصد تو امور بیعت کی نشان دہی ہے۔ (۲) ’’پردہ ڈال دیا‘‘ اس کے گناہ کا کسی کو پتا نہ چلنے دیا۔ گواہ ایسا مہیا نہ ہو سکے جن سے سزا نافذ ہو سکتی ہے۔ یا سزا نہ ملی۔"}],[4211,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"عنقریب تم لوگ امارت و سرداری کی خواہش کرو گے لیکن وہ باعث ندامت و حسرت ہو گی، اس لیے کہ دودھ پلانے والی کتنی اچھی ہوتی ہے، اور دودھ چھڑانے والی کتنی بری ہوتی ہے\" ۱؎۔\nكتاب العقيقة\n§وضاحت\n۱؎: یعنی حکومت ملتے وقت وہ بھلی لگتی ہے اور جاتے وقت بری لگتی ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبیٔ اکرم رضی اللہ عنہم نے فرمایا: ’’عن قریب تم لوگ امارت (اقتدار و سرداری) کی حرص کرو گے اور بلاشبہ یہ (قیامت کے دن) ندامت و شرمندگی اور حسرت و افسوس (کا سبب) ہو گی۔ یہ دودھ پلاتے اچھی لگتی ہے مگر دودھ چھڑاتے ہوئے بری محسوس ہوتی ہے۔‘‘ (اس کی ابتدا اچھی معلوم ہوتی ہے لیکن انجام برا ہو گا۔)","f2":"(۱) باب کے ساتھ حدیث کی مناسبت بالکل واضح ہے کہ امارت، یعنی اقتدار و سرداری کی حرص و ہوس شرعاً ناپسندیدہ اور مذمور ہے۔ (۲) رسول اللہ صلی اللہ علیہ وسلم اپنے مذکورہ بالا فرمان سے امت کو یہ سمجھانا چاہتے ہیں کہ جس کام کے انجام میں دکھ، تکلیف اور رنج و الم ہو، اسے معمولی اور زوال پذیر لذت و راحت کی خاطر ہرگز اختیار نہیں کرنا چاہیے۔ (۳) اس حدیث مبارکہ سے یہ بات بھی معلوم ہوتی ہے کہ دنیوی لذات کے بجائے اخروی سعادت کے حصول اور آخرت کے عذاب سے خلاصی کی کوشش کرنی چاہیے کیونکہ اصل مقصدِ حیات اور کامیابی دنیا کی لذتوں کا حصول نہیں بلکہ عذاب آخرت سے بچائو اور جنت میں داخل ہے۔ (۴) ’’ندامت و شرمندگی اور حسرت و افسوس‘‘ آخرت میں یا دنیا ہی میں کیونکہ جب اقتدار چھن جاتا ہے تو عموماً عذاب سہنا پڑتا ہے۔ تخت یا تختہ۔ (۵) ’’دودھ پلاتے ہوئے‘‘ حدی ثمیں مذکور اس مثال میں امارت کو ماں سے تشبیہ دی گئی ہے اور حریصِ امارت کو بچے سے۔ ماں جب تک دودھ پلاتی ہے، بچہ ماں سے خوب خوش رہتا ہے اور جب وہ دودھ چھڑا دیتی ہے تو کاٹ کھانے کو دوڑتا ہے۔ اقتدار کا بھی یہی حال ہے۔"}],[4212,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے عقیقہ کے سلسلے میں پوچھا گیا تو آپ نے فرمایا: \"اللہ تعالی عقوق کو پسند نہیں کرتا\"۔ گویا کہ آپ کو یہ نام ناپسند تھا۔ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: ہم تو آپ سے صرف یہ پوچھ رہے ہیں کہ جب ایک شخص کے یہاں اولاد پیدا ہو تو کیا کرے؟ آپ نے فرمایا: \"جو اپنی اولاد کی طرف سے قربانی کرنا چاہے ۱؎ کرے، لڑکے کی طرف سے ایک ہی عمر کی دو بکریاں اور لڑکی کی طرف سے ایک بکری\"۔ داود بن قیس کہتے ہیں: میں نے زید بن اسلم سے «مكافئتان» کے بارے میں پوچھا تو انہوں نے کہا: دو مشابہ بکریاں جو ایک ساتھ ذبح کی جائیں ۲؎۔\n§وضاحت\n۱؎: اسی جملے سے استدلال کرتے ہوئے بعض ائمہ کہتے ہیں کہ \" عقیقہ \" فرض نہیں مندوب و مستحب ہے، جب کہ فرض قرار دینے والے حدیث نمبر ۴۲۱۹ سے استدلال کرتے ہیں جس میں حکم ہے کہ \" بچے کی طرف سے خون بہاؤ \" نیز اور بھی کچھ الفاظ ایسے وارد ہیں جن سے عقیقہ کی فرضیت معلوم ہوتی ہے، إلا یہ کہ کسی کو عقیقہ کے وقت استطاعت نہ ہو تو بعد میں استطاعت ہونے پر قضاء کر لے۔ ۲؎: عمر میں برابر ہوں یا وصف میں ایک دوسرے سے قریب تر ہوں۔","الألباني: حسن صحيح",{"u2":"حضرت عمرو بن شعیب کے پردادا (حضرت عبداللہ بن عمرو رضی اللہ عنہ) بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے عقیقے کے بارے میں پوچھا گیا تو آپ نے فرمایا: ’’اللہ تعالیٰ عقوق کو ناپسند فرماتا ہے۔‘‘ (معلوم ہوتا ہے رسول اللہ صلی اللہ علیہ وسلم نے لفظ عقیقہ کو اچھا نہیں سمجھا۔) اس سائل نے رسول اللہ صلی اللہ علیہ وسلم سے کہا: جب ہم میں سے کسی کے ہاں بچہ پیدا ہو تو وہ جانور ذبح کرتا ہے۔ (ہم تو اس کے متعلق پوچھ رہے ہیں) آپ نے فرمایا: ’’جو شخص اپنے بچے کی طرف سے جانور ذبح کرنا چاہے تو وہ لڑکے کی طرف سے دو پوری بکریاں ذبح کرے اور لڑکی کی طرف سے ایک بکری۔‘‘\n(راویٔ حدیث) داود نے کہا کہ میں نے زید بن اسلم سے اَلْمُکَافَأَتَانِ کی بابت پوچھا تو انہوں نے کہا: اس سے مراد دو ایک جیسی بکریاں ہیں جو بیک وقت ذبح کی جائیں۔","f2":"(۱) اس حدیث سے عقیقے کی مشروعیت ثابت ہوتی ہے۔ شریعت مطہرہ نے لڑکے اور لڑکی کے عقیقے میں یہ فرق کیا ہے کہ لڑکے کی طرف سے ایک جیسی دو بکریاں جبکہ لڑکی کی طرف سے ایک بکری بطور عقیقہ ذبح کی جائے گی، تاہم اگر استطاعت نہ ہو تو لڑکے کی طرف سے بھی ایک بکری کفایت کر جائے گی۔ لڑکے کی طرف سے دو اور لڑکی کی طرف سے عقیقہ میں ایک جانور ذبح کرنا متفقہ مسئلہ ہے اور اس میں کوئی تعجب خیز بات نہیں۔ وراثت میں بھی تو لڑکے اور لڑکی کے حصوں میں فرق ہے۔ ویسے بھی عموماً لوگ لڑکے کی پیدائش پر زیادہ خوشی مناتے ہیں، لہٰذا اس کا شکرانہ بھی زیادہ ہی ہونا چاہیے۔ (۲) ’’ناپسند فرماتا ہے‘‘ یعنی لفظ عقوق کو، جیسا کہ راوی نے وضاحت کی ہے۔ عقوق کے معنی نافرمانی کے ہیں۔ یہ لفظ اچھا نہیں، لہٰذا بہتر ہے کہ بجائے عقیقہ کے نسیکۃ (اللہ تعالیٰ کے راستے میں ذبح ہونے والا جانور) کہا جائے لیکن یہ بھی ضروری نہیں۔ بعض احادیث میں صراحتاً لفظ عقیقہ استعمال کیا گیا ہے۔ اس کا یہ مطلب نہیں لے سکتے کہ اللہ تعالیٰ فعل عقیقہ کو ناپسند فرماتا ہے کیونکہ آئندہ الفاظ میں تو آپ خود عقیقے کی سنیت ذکر فرما رہے ہیں۔ یہ معنی بھی ہو سکتے ہیں کہ اللہ تعالیٰ عقیقہ نہ کرنے کو ناپسند فرماتا ہے کیونکہ عقوق کے معنی قطع رحم کے بھی ہیں، جیسے کہ نافرمان اولاد کو عاق کہا جاتا ہے۔ جو والد اپنے بچے کا عقیقہ نہ کرے، گویا اس نے اس رشتے کا حق ادا نہیں کیا، لہٰذا اسے بھی عاق کہا جائے گا کیونکہ اس نے عقوق کیا۔ لیکن یہ معنی ذرا پیچیدہ ہیں۔ (۳) ’’ذبح کرنا چاہے‘‘ ظاہر الفاظ سے معلوم ہوتا ہے کہ ذبح کرنا ضروری نہیں۔ لیکن دوسری روایات کو ساتھ ملانے سے ثابت ہوتا ہے کہ عقیقہ سنت ہے اور سنت کو بلاوجہ چھوڑنے والا گناہ گار ہوتا ہے۔ (۴) ’’دو پوری بکریاں‘‘ یعنی عمر میں بھی پوری ہوں اور اوصاف میں بھی۔ اس سے استدلال کیا گیا ہے کہ عقیقے کا جانور کم از کم قربانی کے جانور کی طرح ہو اور اس میں کوئی عیب نہیں ہونا چاہیے ورنہ وہ پورا نہیں ہو گا۔ اس لفظ کا دوسرا ترجمہ یہ بھی ہو سکتا ہے: ’’دو بکریاں جو قربانی کے جانور کے برابر ہوں۔‘‘ تیسرا ترجمہ یہ کیا گیا ہے کہ ایک جیسی دو بکریاں۔ تینوں ترجمے صحیح ہیں۔ (۵) عقیقہ میں بکرا، بکری، مینڈھا، بھیڑ برابر ہیں۔ ان میں کوئی فرق نہیں۔"}],[4213,"بریدہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حسن اور حسین رضی اللہ عنہما کی طرف سے عقیقہ کیا۔","الألباني: صحيح",{"u2":"حضرت بریدہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سیّدنا حسن او حسین رضی اللہ عنہ کی طرف سے عقیقہ کیا۔"}],[4214,"سلمان بن عامر ضبی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لڑکے کی پیدائش پر ۱؎ اس کا عقیقہ ہے، تو اس کی جانب سے خون بہاؤ۲؎ اور اس سے تکلیف دہ چیز کو دور کرو\" ۳؎۔\n§وضاحت\n۱؎: اس جملہ سے بعض لوگوں نے یہ استدلال کیا ہے کہ \" عقیقہ صرف لڑکے کی پیدائش پر ہے۔ لڑکی کی پیدائش پر نہیں، لیکن یہ استدلال صرف ایک حدیث پر نظر رکھنے کا نتیجہ ہے جو اصول استدلال کے خلاف ہے، متعدد دیگر احادیث وارد ہیں جن میں لڑکی کی طرف سے بھی خون بہا نے کا حکم دیا گیا ہے۔ :(دیکھئیے اگلی حدیث ) ۲؎: اسی جملہ سے :(نیز حدیث نمبر ۴۲۲۵ کے مفہوم ) سے عقیقہ کے واجب ہونے پر استدلال کیا جاتا ہے، جب کہ بعض لوگ حدیث نمبر۴۲۱۸ کے جملہ \" جو چاہے وہ عقیقہ کرے \" سے استحباب پر استدلال کرتے ہیں، سلمان رضی اللہ عنہ کی حدیث صحیح بخاری کی ہے جب کہ عبداللہ بن عمرو رضی اللہ عنہما کی حدیث صرف سنن کی ہے، نیز سلمان رضی اللہ عنہ کی حدیث کے معنی کی تائید حدیث نمبر ۴۲۲۵ کے اس مفہوم سے بھی ہوتی ہے جو امام احمد بن حنبل نے بیان کیا ہے، نیز ام کرز رضی اللہ عنہا کی حدیث سے بھی وجوب ہی کی تائید ہوتی ہے، ہاں جس کو عقیقہ کرنے کی استطاعت ہی نہ ہو تو اس سے معاف ہے، اگر ماں باپ کو اکیسوئیں دن بھی عقیقہ کرنے کی استطاعت ہو جائے تو کر دے، اس کے بعد وجوب ساقط ہو جائے گا۔ ۳؎: یعنی سر کے بال مونڈو اور غسل دو۔","الألباني: صحيح",{"u2":"حضرت سلمان بن عامر ضبی رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بچے کی طرف سے عقیقہ ہونا چاہیے، لہٰذا جانور ذبح کرو اور بچے سے میل کچیل دور کرو۔‘‘","f2":"(۱) ’’ذبح کرو‘‘ حکم ہے، نیز عقیقہ آپ کا فعل ہے، لہٰذا کم از کم سنت تو ہے اگرچہ بعض اہل علم نے امر کی وجہ سے واجب کہا ہے۔ (۲) ’’میل کچیل دور کرو‘‘ مراد سر کے بال ہیں۔ گویا عقیقہ کے ساتھ بچے کا سر بھی مونڈا جائے گا بلکہ ایک روایت کے مطابق اس کے بالوں کے برابر چاندی صدقہ کی جائے۔ بعض نے اس سے ختنہ مراد لیا ہے۔ یا اس سے مراد یہ ہے کہ جانور ذبح کرنے کے بعد اس کا خون بچے کے سر پر نہ ملا جائے جیسا کہ جاہلیت میں رواج تھا۔"}],[4215,"ام کرز رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(عقیقہ کے لیے) لڑکے میں دو ہم عمر بکریاں اور لڑکی میں ایک بکری (کافی)ہے\" ۱؎۔\n§وضاحت\n۱؎: لڑکے کی طرف سے دو جانور اور لڑکی کی طرف سے ایک جانور ذبح کرنے کی حکمت یہ ہے کہ بچے کی طرف سے خون بہانا اس کی جان کی بقاء کی خاطر ہے، تو یہ گویا دیت کی طرح ہوا، اور دیت میں نر جان کی دیت مادہ جان سے دگنی ہوتی ہے :(کما فی المغنی مسألۃ نمبر ۱۴۷۲ ) نیز ایک حدیث میں ہے \" جس نے ایک نر جان کو آزاد کیا اس کا ہر عضو جہنم سے آزاد کیا جائے گا، اور جس نے دو ماہ جان کو آزاد کیا اس کو بھی یہی اجر ملے گا۔ :(فتح الباری تحت ۵۴۷۱ من کتاب العقیقۃ )","الألباني: صحيح",{"u2":"حضرت ام کرز رضی اللہ عنہا بیان کرتی ہیں کہ عقیقے سے متعلق احکام ومسائل رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ لڑکے کی طرف سے دوکامل بکرے ذبح کیے جائیں اور لڑکی کی طرف سے ایک۔ ‘‘","f2":"عقیقہ یا قربانی کے جانور میں نر یا مادہ کی تخصیص کی شرط نہیں"}],[4216,"ام کرز رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(عقیقے کے لیے) لڑکے کی طرف سے دو ہم عمر بکریاں ہوں گی اور لڑکی کی طرف سے ایک بکری\"۔","الألباني: صحيح",{"u2":"حضرت ام کرز رضی اللہ عنہا سے منقول ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ لڑکے کی طرف سے دو کامل بکرے ذبح کیے جائیں اور لڑکی کی طرف سے ایک۔ ‘‘"}],[4217,"ام کرز رضی اللہ عنہا کہتی ہیں کہ میں حدیبیہ میں ہدی کے گوشت کے بارے میں پوچھنے کے لیے نبی اکرم صلی اللہ علیہ وسلم کے پاس آئی، تو میں نے آپ کو فرماتے ہوئے سنا: \"لڑکا ہونے پر دو بکریاں ہیں اور لڑکی پر ایک بکری، نر ہوں یا مادہ اس سے تم کو کوئی نقصان نہیں ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت ام کرز رضی اللہ عنہا فرماتی ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس (حدیبیہ میں) حاضر ہوئی تاکہ آپ سے قربانی کے گوشت کے بارے میں پوچھوں۔ میں آپ کو فرماتے سنا: ’’ لڑکے کی طرف سے دو بکریاں اور عقیقے سے متعلق احکام ومسائل لڑکی کی طرف سے ایک بکری ذبح کرنا لازم ہے۔ کوئی حرج نہیں‘ مذکر ہوں یا مئونث۔ ‘‘","f2":"’’ فرماتے سنا‘‘ یعنی اپنے سوال کے جواب کے علاوہ عقیقے کا مسئلہ فرماتے ہوئے سنا۔ ’’ مذکر ہوں یا مئونث‘‘ لڑکے کی طرف سے مئونث اور لڑکی کی طرف سے مذکریا ملے جلے جانور ذبح کیے جاسکتے ہیں۔ ثواب میں کوئی فرق نہیں۔"}],[4218,"ام کرز رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لڑکے کی طرف سے دو بکریاں ہوں گی اور لڑکی کی طرف سے ایک بکری، نر ہوں یا مادہ اس میں تمہارا کوئی نقصان نہیں\"۔","الألباني: صحيح",{"u2":"حضرت ام کرز رضی اللہ عنہا سے روایت ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ لڑکے کی طرف سے دو بکریاں اور لڑکی کی طرف سے ایک بکری (عقیقہ میں) ذبح کی جائے۔ وہ (عقیقے کے جانور) نر ہوں یا مادہ (بکرے ہوں یا بکریاں) کوئی حرج نہیں۔ ‘‘"}],[4219,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حسن اور حسین رضی اللہ عنہما کی طرف سے دو دو مینڈھے ذبح کیے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا سے مروی ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے حضرت حسن اور حضرت حسین رضی اللہ عنہا کی طرف سے دو ددو مینڈھے عقیقے میں ذبح فرمائے۔","f2":"روایات میں بکری‘ بھیڑ اور مینڈھے کا ذکر آیا ہے‘ لہٰذا عقیقے میں یہی جانور ذبح کرنے چاہئیں۔ گائے اور اونٹ کو عقیقہ میں ذبح کرنا کسی صحیح حدیث سے ثابت نہیں ہے‘ نیز عقیقے کو قربانی پر قیاس کرنے کی عقیقے سے متعلق احکام ومسائل بھی کوئی وجہ نہیں کیونکہ قربانی سب لوگ معین دنوں میں کرتے ہیں جبکہ عقیقہ ہر گھرا نہ اپنے بچے کی پیدائش سے ساتویں دن کرتا ہے۔ عقیقہ کی وضع ہی قربانی سے مختلف ہے۔ لڑکے کے عقیقے میں عقیقے میں صراحناََ دو بکریاں ذبح کرنے کاذکر ہے، اس لیے عقیقے میں بکرا، بکری بھیڑ اور مینڈھے وغیرہ ذبح کیے جائیں اور گائے، اونٹ ذبح نہ کیے جائیں۔"}],[4220,"سمرہ بن جندب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر بچہ اپنے عقیقہ کے بدلے گروی ہے ۱؎ اس کی طرف سے ساتویں روز ذبح کیا جائے ۲؎، اس کا سر مونڈا جائے، اور اس کا نام رکھا جائے\"۔\n§وضاحت\n۱؎: اسی حدیث سے استدلال کرتے ہوئے بعض علماء عقیقہ کے فرض ہونے کے قائل ہیں، کیونکہ اس میں بچے کے عقیقہ کے بدلے گروی باقی رہ جانے کی بات ہے، اور گروی رہنے کا مطلب علماء نے یہ بیان کیا ہے کہ جس لڑکے کا عقیقہ نہ کیا جائے اور وہ بلوغت سے پہلے مر جائے تو وہ قیامت کے دن اپنے ماں باپ کی سفارش :(شفاعت ) نہیں کرے گا، بعض علماء نے اس کا مطلب یہ بیان کیا ہے کہ جس طرح رہن رکھی ہوئی چیز کے بدلے کی ادائیگی ضروری ہے اسی طرح ذبح :(عقیقہ ) ضروری ہے، وغیرہ وغیرہ۔ ۲؎: اگر ساتویں دن عقیقہ کی استطاعت نہیں ہو سکی تو چودہویں دن کرے، اور اگر اس دن میں نہ ہو سکے تو اکیسویں دن کرے، جیسا کہ عائشہ رضی اللہ عنہا سے مستدرک حاکم میں :(۴/۲۳۸ ) صحیح سند سے مروی ہے، اگر اکیسویں دن بھی نہ ہو سکے تو جو لوگ واجب قرار دیتے ہیں ان کے نزدیک زندگی میں کسی دن بھی قضاء کرنا ہو گا۔","الألباني: صحيح",{"u2":"حضرت سمرہ بن جندب رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ ہر بچہ اپنے عقیقے کے عوض گر وی ہوتاہے۔ ساتویں دن اس کی طرف سے جانور ذبح کیا جائے، سر منڈویا جائے اور اس کا نام رکھاجائے۔ ‘‘","f2":"1۔گروی ہوتا ہے‘‘ جس طرح گروی شدہ چیز کو معاوضہ دے کر چھڑانا ضروری ہوتا ہے، اسی طرح بچے کی آزادی کے لیے عقیقہ کرنا ضروری ہے، البتہ اس بات میں اختلاف ہے کہ ’’ آزادی‘‘ کا کیا مطلب ہے۔ امام احمد بن حنبل رحمہ اللہ سے منقول ہے کہ گروی بشہ اگر فوت ہوگیا تو عہ ماں باپ کی سفارش نہیں کرے گا کیونکہ گروی شدہ چیز سے مالک فائدہ نہیں اٹھا سکتا۔ اسے چھڑانے کے بعد ہی فائدہ حاصل کرسکتا ہے جبکہ حافظ ابن قیم رحمہ اللہ نے شیطان کے چنگل سے چھڑانا مراد لیا ہے۔ 2۔ساتویں دن‘‘ گویا اس پہلے عقیقہ نہیں ہوسکتا۔ بالفرض اگر ساتویں دن عقیقہ نہ ہوسکے تو امام مالک کا خیال ہے کہ بعد میں نہیں کرنا شاہیے کیونکہ اس کا وقت گزر گیا، جیسے قربانی کا وقت گزر جائے بعد میں قربانی نہیں کی جاسکتی۔ دیگر ائمہ کا خیال ہے کہ اگر ساتویں دن عقیقہ نہ ہوسکے تو اگلے ساتویں دن، یعنی چودھویں دن عقیقہ کیا جائے،۔ اگر اس دن بھی عقیقہ نہ ہو سکے تو اکیسویں دن عقیقہ کیا جائے۔ اس مفہوم کی ایک مرفوع حدیث بیہقی میں آتی ہے مگر اس کا راوی ضعیف ہے۔ اسی طرح حضرت عائشہ رضی اللہ عنہا کا قول بھی اسی مفہوم کے ساتھ مستدرک حاکم میں آتا ہے، لیکن وہ بھی انقطاع کی وجہ سے ضعیف ہے تفصیل کے لیے دیکھیے: لیے سنت ساتویں دن ہی ہے، تاہم اگر اس روز ممکن نہ ہوتو بعد میں کسی روز بھی کیا جاسکتا ہے۔ اس کا حکم بھی عقیقے سیت متعلق احکام ومسائل قربانی والا ہوگا، یعنی اس سے سب کھا سکتے ہیں۔ گھر والے بھی اور دوسرے بھی۔ میرا بھی اور فقیر بھی۔3۔ ’’ نام رکھا جائے‘‘ ساتویں دن نام رکھنا مستحب ہے‘ البتہ ساتویں دن سے پہلے اور بعد میں بھی رکھا جاسکتا ہے۔4۔ اگر بچہ ساتویں دن سے پہلے ہی فوت ہو جائے ظاہربات یہی ہے کہ اس کا عقیقہ کرنے کی ضرورت نہیں کیونکہ وہ عقیقے کے وقت تک زندہ نہیں رہا۔"}],[4221,"حبیب بن شہید کہتے ہیں کہ مجھ سے محمد بن سیرین نے کہا: حسن (حسن بصری) سے پوچھو، انہوں نے عقیقہ کے سلسلے میں اپنی حدیث کس سے سنی ہے؟ چنانچہ میں نے ان سے اس بارے میں سوال کیا تو انہوں نے کہا: یہ حدیث میں نے سمرہ رضی اللہ عنہ سے سنی ہے۔","الألباني: صحيح",{"u2":"حضرت حبیب بن شہید بیان کرتے ہیں کہ مجھے محمد بن سیرین نے کہا کہ حضرت حسن بصری سے پوچھو، انھوں سے عقیقے کے بارے میں یہ حدیث کس سنی ہے؟ میں ان سے پوچھا تو انھوں نے فرمایا: میں نے یہ روایت حضرت سمرہ(بن جندب) رضی اللہ تعالٰی عنہ سے سنی ہے۔","f2":"امام نسائی رحمہ اللہ نے یہ صراحت اس لیے فرمائی ہے کہ حضرت حسن بصری کے حضت سمرہ بن جند رضی اللہ عنہ رضی اللہ عنہ سے سماع میں اختلاف ہے کہ انھوں نے حضرت سمرہ سے درست نہیں۔ بعض درست سمجھتے ہیں۔ یہ امام بخاری اور امام ترمذی کا خیال ہے۔ بعض محدثین صرف اس روایت میں ان کا سماع درسلت سمجھتے ہیں، باقی میں نہیں۔"}],[4222,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"فرع اور عتیرہ واجب نہیں\" ۱؎۔\n§وضاحت\n۱؎: فرع: زمانہ جاہلیت میں جانور کے پہلوٹے کو بتوں کے واسطے ذبح کرنے کو فرع کہتے ہیں، ابتدائے اسلام میں مسلمان بھی ایسا اللہ تعالی کے واسطے کرتے تھے پھر کفار سے مشابہت کی بنا پر اسے منسوخ کر دیا گیا اور اس سے منع کر دیا گیا۔ اور عتیرہ: زمانہ جاہلیت میں رجب کے پہلے عشرہ میں تقرب حاصل کرنے کے لیے ذبح کرتے تھے، اور اسلام کی ابتداء میں مسلمان بھی ایسا کرتے تھے۔ کافر اپنے بتوں سے تقرب کے لیے اور مسلمان اللہ تعالی سے تقرب کے لیے ذبح کرتے تھے، پھر یہ دونوں منسوخ ہو گئے اب نہ فرع ہے اور نہ عتیرہ بلکہ مسلمانوں کے لیے عید الاضحی کے روز قربانی ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’فرع اور عتیرہ درست نہیں۔ ‘‘","f2":"یہ دو قسم کی قربانیاں تھیں جو جاہلیت میں رائج تھیں۔ اونٹنی سے پیدا ہونے والا پہلا بچہ بتوں کے نام بطور تشکر ذبح کردیا جاتاتھا۔ اسے فرع کہتے تھے۔ یا جس کے پاس سو اونٹ پورے ہوجاتے تو وہ ہر سال ایک جوان اونٹ بتوں کے نام پر ذبح کردیتا تھا۔ اسے بھی فرع کہتے تھے۔ ماہ رجب کے شروع میں مشرکین ایک بکری ذبح کرتے تھے، اسے عتیرہ کہا جاتا تھا۔ اسلام نے جہاں جاہلیت کی دوسری رسمیں ختم کردیں، ان کو بھی ختم کردیا، البتہ اگر کوئی شخص ا اللہ تعالیٰ کے نام پر جانور کا پہلا بچہ یا سواں جانور بطور تشکر ذبح کرکے مساکین کو صدقہ کردے تو اسے صدقہ کا ثواب مل جائے گا جبکہ قربانی کی بجائے مسلمانوں کے لیے ذوالحجہ میں اقربانی مشروع کی گئی ہے، لہٰذا وہی کرنی چاہیے۔ ہاں، کوئی ویسے ہی صدقہ کرنا چاہے تو جب مرضی ہو، گوشت بناکر صدقہ کردے۔ کوئی پابندی نہیں۔ حدیث میں فرع اور عتیرہ کی نفی بتوں کے نام پر قربانی دینے میں وگرنہ ا اللہ کے نام پر کسی بھی وقت قربانی دینا مستحب عمل ہے۔"}],[4223,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرع اور عتیرہ سے منع فرمایا (دوسری روایت میں ہے کہ) آپ نے فرمایا: \"فرع اور عتیرہ واجب نہیں ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی یہ دونوں اب واجب نہیں رہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرع اور عتیرہ سے منع فرمایا ہے۔"}],[4224,"مخنف بن سلیم رضی اللہ عنہ کہتے ہیں کہ ہم عرفہ میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ بیٹھے ہوئے تھے کہ اسی دوران آپ نے فرمایا: \"لوگو! ہر گھر والے پر ہر سال قربانی اور عتیرہ ہے\" ۱؎۔ معاذ کہتے ہیں: ابن عون رجب میں عتیرہ کرتے تھے، ایسا میں نے اپنی آنکھوں سے دیکھا۔\n§وضاحت\n۱؎: فرع اور عتیرہ کے سلسلے میں مروی تمام احادیث کے مطالعے سے یہ بات واضح ہوتی ہے کہ یہ دونوں ایام جاہلیت میں جاہلی انداز میں انجام دیئے جاتے تھے جس میں شرک کی ملاوٹ ہوتی تھی، رسول اللہ صلی اللہ علیہ وسلم نے اسلام میں ان کو جائز قرار تو دیا، مگر وہ شرک و کفر سے خالی اور جاہلی عادات کی مشابہت سے دور ہو، اور اگر نہ انجام دیئے جائیں تو بہتر ہے، خاص طور پر فرع کو اگر چھوڑ رکھا جائے تو یہ جانور بڑا ہو کر زیادہ مفید ثابت ہو سکتا ہے، واللہ اعلم :(دیکھئیے اگلی روایات )۔","الألباني: حسن",{"u2":"حضرت مخنف بن سلیم رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ ہم نبی اکرم صلی اللہ علیہ وسلم کے ساتھ عرففہ میں وقوت کررہے تھے کہ آپ نے فرمایا: ’’اے لوگو‘‘ ہر گھر والوں پر ایک سال بعد قربانی بھی ہے اور عتیرہ بھی۔ ‘‘\n(روی حدیث) معاذ کہتے ہیں کہ میری آنکھوں نے دیکھا کہ(عبدا اللہ) ابن عون رجب میں عتیرہ (جانور) ذبح کرتے تھے۔","f2":"قربانی سے مراد ذالحجہ والی قربانی ہے جو سنت مئوکدہ ہے، البتہ عتیرہ صدقے کے طور پر دیگر دلائل کی رو سے مستحب ہے لیکن ا اللہ تعالیٰ کے نام پر۔"}],[4225,"محمد بن عبداللہ بن عمرو اور زید بن اسلم سے روایت ہے لوگوں (صحابہ) نے عرض کیا: اللہ کے رسول! فرع کیا ہے؟ آپ نے فرمایا: \"حق ہے، البتہ اگر تم اسے چھوڑ دو یہاں تک کہ وہ جوان ہو جائے اور تم اسے اللہ کی راہ میں دو، یا اسے کسی مسکین، بیوہ کو دے دو تو یہ بہتر ہے اس بات سے کہ تم اسے (بچہ کی شکل میں) ذبح کرو اور (اس کے کاٹے جانے کی وجہ سے) اس کا گوشت چمڑے سے لگ جائے\"۔ (یعنی دبلی ہو جائے گی) پھر تم اپنا برتن اوندھا کر کے رکھو گے (کہ وہ دودھ دینے کے لائق ہی نہ ہو گی) اور تمہاری اونٹنی تکلیف میں رہے گی\"۔ لوگوں نے عرض کیا: اللہ کے رسول! اور عتیرہ کیا ہے؟ آپ نے فرمایا: \"عتیرہ بھی حق ہے\" ۱؎۔ ابوعبدالرحمٰن نسائی کہتے ہیں: ابوعلی حنفی چار بھائی ہیں: ابوبکر، بشر، شریک اور ایک اور ہیں۔\n§وضاحت\n۱؎: یعنی باطل اور حرام نہیں ہے۔","الألباني: حسن",{"u2":"حضرت زیدبن اسلم سے روایت ہے کہ لوگوں نے کہا: اے ا اللہ کے رسول! فرع کے بارے میں کیا حکم ہے؟ آپ نے فرمایا: ’’ (ا اللہ کے نام پر) ٹھیک ہے لیکن اگر تو اسے (ذبح کرنے کی بجائے) چھوڑ دے (بڑا ہونے دے) حتی کہ وہ جوان اونٹ ہوجائے، پھر تو اسے ا اللہ تعالیٰ کے راستے میں کسی کو سواری کے لیے دے یا کسی بیوہ کو دے دے تو یہ بہتر ہے اس کے کہ تو اسے (پیدا ہوتے ہی) ذبح کرڈالے جبکہ اس کا گوشت اس کے بالوں ہی سے لگا ہو، اور تو اپنے (دودھ کے) برتن کو اوندھا کردے اور اپنی اونٹنی (اس کی ماں) کو بلاوجہ پریشان کرے۔ ‘‘ لوگوں نے پوچھا: اے ا اللہ کے رسول! عتیرہ؟ آپ نے فرمایا: ’‘’عتیرہ بھی حق ہے۔ (وہ بھی ٹھیک ہے)۔ ‘‘\nابو عبدالرحمن (امام نسائی رحمہ اللہ) نے فرمایا: (راوی حدیث) ابو علی حنفی (اور اس کے بھائیٌ) وہ چار ہیں۔ ان میں ایک ابوبکر ہے، ایک بشر ہے اور ایک شریک ہے، نیز ایک اور ہے (اس کا نام عمیر۔)","f2":"آپ کا مقصود یہ ہے کہ ا اللہ تعالیٰ کے نام پر ذبح کرنا تو ٹھیک ہے مگر وہ کام کرنا چاہیے جس کے کرنے سے زیادہ فائدہ ہو۔ لوگ بچہ پید ہوتے ہی اسے ذبح کردیتے لیکن اس کو کوئی فائدہ نہیں ہوتا تھا۔ گوشت صرف چھیپھڑوں کی صورت میں ہوتا تھا جو کھانے کے قابل بھی نہیں ہوتا تھا۔ اور اس قدر قلیل کہ گوشت پوست میں امتیاز مشکل سے ہوتا تھا۔ اونٹنی غم کی وجہ سے دودھ سے بھی جواب دے دیتی تھی۔ گویا کسی کو بھی فائدہ نہ ہوا۔ الٹا گھر کا نقصان ہوگا و، لہٰذا بہتر یہ ہے کہ اسے بڑا ہونے دیا جائے حتی کہ جب وہ سواری کے قابل ہوجائے تو پھر جہاد فی سبیل ا اللہ می سواری کے لیے دیا جائے، کسی بیوہ کودے دیا جائے یا وہ جانور کسی محتاج ومسکین کودے دیا جائے تاکہ وہ اس سے فائدہ اٹھائے۔2۔ فرع، یعنی جانور کا پہلا بچہ پیدا ہونے یا سو جانور پورے ہونے پر جانور ذبح کرنا، درست ہے۔ اسلام سے پہلے اس قسم کا جانور بتوں اور معبودانِ باطلہ کی\nخوشنودی حاصل کرنے کا ذریعہ سمجھا جاتا تھا اور انھی کی خاطر ذبح کیا جاتا، لیکن اسلام میں اس تصور کو جڑے اکھیڑ دیا گیا۔ غیر ا اللہ کے لیے جانور ذبح کرنا حرام قرار دیا گیا جبکہ ا اللہ تعالیٰ کی رضا کے حصول کے لیے بطور صدقہ جانور ذبح کرنا مستحب ٹھہرایا گیا۔ یہ اب بھی مستحب اور حصول ثواب ودفع مصیبت کا بہترین ذریعہ ہے۔3۔ اس حدیث سے یہ بھی معلوم ہوتا ہے کہ صدقہ کرنا صرف یہ نہیں کہ جانور ذبح کرکے اس کا گوشت لوگوں کو کھلا دیا جائے بلکہ فی سبیل ا اللہ کا مفہوم بہت وسیع ہے اور اس میں بہت سی بہتر صورتیں موجود ہیں جو صدقہ کرنے والے کے لیے کہیں زیادہ اجر وثواب کا سبب ہیں۔4۔ جانوروں کے زائدہ بچوں کو ذبح کرنا یا ابھی ان کی ماؤں سے جدا کرنا قطعاََ پسند یدہ نہیں۔ ایک تو اس لیے کہ اس سے ماں کو تکلیف پہنچتی ہے اور وہ بے چین وبے قرار ہوتی ہے اور دوسرا اس لیے بھی کہ ایسا کرنے سے اس بچے کی ماں کا دودھ بھی کم ہو جاتا ہے۔"}],[4226,"حارث بن عمرو رضی اللہ عنہ کہتے ہیں کہ میں حجۃ الوداع میں رسول اللہ صلی اللہ علیہ وسلم سے ملا، آپ اپنی اونٹنی عضباء، پر سوار تھے۔ میں آپ کی ایک جانب گیا اور عرض کیا: اللہ کے رسول! میرے ماں باپ آپ پر قربان ہوں، میرے لیے مغفرت کی دعا کیجئے، آپ نے فرمایا: \"اللہ تم لوگوں کی مغفرت فرمائے\"۔ پھر میں آپ کی دوسری جانب گیا، مجھے امید تھی کہ آپ خاص طور پر میرے لیے دعا کریں گے، میں نے عرض کیا: اللہ کے رسول! میرے لیے مغفرت کی دعا کیجئے۔ آپ نے اپنے ہاتھوں (کو اٹھا کر) فرمایا: \"اللہ تعالی تم سب کو معاف کرے\"۔ پھر لوگوں میں سے ایک شخص نے کہا: اللہ کے رسول! عتیرہ اور فرع کے بارے میں کیا حکم ہے؟ آپ نے فرمایا: \"جو چاہے عتیرہ ذبح کرے اور جو چاہے نہ کرے اور جو چاہے فرع کرے اور جو چاہے نہ کرے، بکریوں میں صرف قربانی ہے\"، اور آپ نے اپنی سب انگلیاں بند کر لیں سوائے ایک کے (یعنی: سالانہ صرف ایک قربانی ہے)۔","الألباني: ضعيف",{"u2":"حضرت حارث عمرو رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں رسول ا اللہ صلی اللہ علیہ وسلم کو جحۃ الوداع میں ملا۔ آپ اپنی عضباء اونٹنی پر سوار تھے۔ میں ایک جانب سے آپ کے پاس حاضر ہوا اور عرض کی: اے ا اللہ کے رسول! میرے ماں پاب آپ پر قربان! میرے لیے بخشش کی دعا فرمائے۔ آپ نے فرمایا: ’’ا اللہ د تعالیٰ تم سب کو معاف فرمائے۔ ‘‘ پھر میں دوسری جانب سے آپ کے پاس اس امید کے ساتھ آیا کہ آپ میرے لیے خصوصی دعا فرمائیں گے۔ میں نے عرض کی: اے ا اللہ کے رسول! میرے لیے بخشش کی دعا فرمایئے۔ آپ نے اپنے دونوں ہاتھ اٹھائے اور فرمایا: ’’ا اللہ تعالیٰ تم سب کو معاف فرمائے۔ ‘‘ لوگوں میں سے ایک آدمی نے کہا: اے ا اللہ کے رسول! عتیرہ اور فرع کا حکم کیا ہے؟ آپ نے فرمایا: ’’جو چاہے عتیرہ ذبح کرے جو چاہے نہ کرے۔ جو شخص چاہے فرع ذبح کرے، جو چاہے نہ کرے، البتہ بکریوں میں قربانی ضروری ہے۔ ’’آپ نے اشارہ فرماتے وقت اپنی سب انگلیاں بند کرلیں مگر ایک کھلی رکھی۔"}],[4227,"حارث بن عمرو رضی اللہ عنہ کہتے ہیں ہیں کہ میں حجۃ الوداع میں رسول اللہ صلی اللہ علیہ وسلم سے ملا۔ اور آپ سے عرض کیا: اللہ کے رسول! میرے ماں باپ آپ پر قربان ہوں، میرے لیے مغفرت کی دعا کیجئے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی تم سب کو معاف فرمائے\"، آپ صلی اللہ علیہ وسلم اپنی اونٹنی عضباء پر سوار تھے، پھر میں مڑا اور دوسری جانب گیا۔ اور پھر آگے پوری حدیث بیان کی۔","الألباني: ضعيف",{"u2":"حضرت حارث بن عمرو رضی اللہ تعالٰی عنہ سے روایت ہے کہ میں حجۃ الوداع میں رسول ا اللہ صلی اللہ علیہ وسلم کو ملا اور عرض کی: اے ا اللہ کے رسول! میرے ماں باپ آپ پر قربان! میرے لیے بخشش کی دعا کیجیے۔ آپ نے فرمایا: ’’ ا اللہ تعالیٰ تم سب کو معاف فرمائے۔ ‘‘ اس وقت آپ اپنی اونٹنی عضباء پر سوار تھے، پھر میں دوسری جانب سے گھوم کر آیا۔ پھر راوی نے پوری حدیث بیان کی۔"}],[4228,"نبیشہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سے بتایا گیا کہ ہم لوگ جاہلیت میں عتیرہ ذبح کرتے تھے۔ آپ نے فرمایا: \"اللہ کے لیے ذبح کرو چاہے کوئی سا مہینہ ہو، اور اللہ کے لیے نیک کام کرو اور لوگوں کو کھلاؤ\"۔","الألباني: صحيح",{"u2":"حضرت نبیشہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ذکر کیا گیا کہ ہم زمانہ جاہلیت میں (ماہ رجب میں) جانور ذبح کیا کرتے تھے۔ آپ نے فرمایا: ’’ا اللہ تعالیٰ کے نام پر ذبح کروجس مہینے میں بھی ا اللہ تعالیٰ کے لیے نیکی کرو۔ اور (غریبوں کو) کھانا کھلایا کرو۔ ‘‘","f2":"مقصود یہ ہے کہ نیکی کے لیے کسی مہینے سکی قید نہیں، کسی بھی وقت غریبوں کو کھلایا جاسکتا ہے۔ رجب کی قید مناسب نہیں۔ اپنی طرف سے کسی مہینے، دن یا وقت کو متعین کر لینا اور پھر اس کو واجب یا افضل خیال کرنا صحیح نہیں۔ اس کی وجہ یہ ہے کہ کسی بھی نیکی کے لیے خاص اوقات وایام اور ماہ وسال مقرر کرنا کسی انسان کاحق ہے نہ اس کی ذمہ داری، بلکہ نیکی کے لیے وقت کی تعیین صرف ا اللہ تعالیٰ کا حق ہے۔ اس میں تصرف کا اختیار کسی اور کو نہیں۔ مزید بر آں یہ بھی ضروری ہے کہ نیکی کی کیفیت اور مقداروہی معبتر ہوگی جو شریعت نے مقرر کر دی ہے۔ اس سے تجارز بدعات اور ایجادِ بندہ قرار پائیں گی۔"}],[4229,"نبیشہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے منی میں پکار کر کہا: اللہ کے رسول! ہم لوگ جاہلیت میں رجب میں عتیرہ کرتے تھے۔ تو اللہ کے رسول! ہمارے لیے آپ کا کیا حکم ہے؟ آپ نے فرمایا: \"ذبح کرو جس مہینے میں چاہو اور اللہ کی اطاعت کرو اور لوگوں کو کھلاؤ\"، اس نے کہا: ہم فرع ذبح کرتے تھے، تو آپ کا کیا حکم ہے؟ آپ نے فرمایا: \"ہر چرنے والے جانور میں ایک فرع ہے، جسے تم چراتے ہو، جب وہ مکمل اونٹ ہو جائے تو اسے ذبح کرو اور اس کا گوشت صدقہ کرو\"۔","الألباني: صحيح",{"u2":"حضرت نبیشہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک آدمی نے منیٰ میں بآواز بلند کہا: اے ا اللہ کے رسول! ہم جاہلیت میں ماہ رجب میں جانور ذبح کیا کرتے تھے تو اے ا اللہ کے رسول! آپ اب ہمیں کیا حکم دیتے ہیں؟ آپ نے فرمایا: ’’جو بھی مہینہ ہو (ا اللہ تعالیٰ کے لیے) ذبح کرو۔ اور ا اللہ تعالیٰ کی رضا مندی کے لیے نیکی کرو۔ اور (غریبوں کو) کھانا کھلاؤ۔ ‘‘ اس آدمی نے کہا: ہم فرع بھی ذبح کیا کرتے تھے۔ اب آپ کا کیا حکم ہے؟ آپ نے فرمایا: ’’ہر قسم کے چرنے والے جانوروں میں سے کوئی جانور ذبح کرنا چاہیے (مگر اس طرح کہ) بچے کو اس کی ماں دودھ پلائے حتی کہ جب وہ سواری کے قابل ہوجائے (پورا اونٹ بن جائے) تو پھر اس کو ذبح کر اور اس کا گوشت صدقہ کر۔ ‘‘"}],[4230,"بنی ہذیل کے ایک شخص نبیشہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہم نے تم لوگوں کو تین دن کے بعد قربانی کا گوشت کھانے سے اس واسطے روکا تھا تاکہ وہ تم سب تک پہنچ جائے۔ اب اللہ تعالی نے گنجائش دے دی ہے تو کھاؤ اور اٹھا (بھی) رکھو اور (صدقہ دے کر) ثواب (بھی) کماؤ۔ سن لو، یہ دن کھانے، پینے اور اللہ تعالی کی یاد (شکر ادا کرنے) کے ہیں۔ ایک شخص نے کہا: ہم لوگ رجب کے مہینہ میں زمانہ جاہلیت میں عتیرہ ذبح کرتے تھے تو آپ ہمیں کیا حکم دیتے ہیں؟ آپ نے فرمایا: \"اللہ کے لیے ذبح کرو چاہے کوئی سا مہینہ ہو، اور اللہ کے لیے نیک کام کرو اور لوگوں کو کھلاؤ\"۔ ایک شخص نے کہا: اللہ کے رسول! ہم لوگ زمانہ جاہلیت میں فرع ذبح کرتے تھے، تو آپ ہمیں کیا حکم دیتے ہیں؟ آپ نے فرمایا: \"ہر چرنے والی بکری میں ایک فرع ہے، جسے تم چراتے ہو، جب وہ مکمل اونٹ ہو جائے تو اسے ذبح کرو اور اس کا گوشت صدقہ کرو، یہی چیز بہتر ہے\"۔","الألباني: صحيح",{"u2":"حضرت نبیشہ ہذلی رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’میں نے تم کو تین دن سے زائد قربانی کا گوشت کھانے سے سے روکا تھا تاکہ سب لوگ کھا سکیں لیکن ا اللہ تعالیٰ نے صورت حال بہتر فرما دی ہے۔ اب کھاؤ صدقہ کرو اور ذخیرہ کرکے بھی رکھ لو۔ یہ (عید کے) دن کھانے پینے اور ا اللہ تعالیٰ کے ذکر کے ہیں۔‘‘ ایک آدمی نے کہا: ہم زمانہ جاہلیت میں رجب کے دور ان میں جانور ذبح کیا کرے تھے۔ اب آپ کا کیا حکم ہے؟ آپ نے فرمایا: ’’ا اللہ تعالیٰ کے لیے ذبح کرو، جس مہینے میں بھی ممکن ہو۔ اور خالص ا اللہ تعالیٰ کے لیے نیکی کرو اور (غریبوں کو) کھانا کھلاؤ۔ ‘‘ ایک آدمی بھی ذبح کیا کرتے تھے۔ اب آپ کیا فرماتے ہیں؟ رسول ا اللہ نے فرمایا: ’’ چرنے والی بکریوں میں رکھ کر پالے پو سے حتی کہ جب وہ جوان ہوجائے تو تو اسے ذبح کرے، پھر اس کا گوشت مسافروں وغیرہ پر صدقہ کردے۔ یہ طریقہ (جاہلیت کی رسم سے) بدر جہا بہتر ہے۔ ‘‘","f2":"1۔ اس حدیث سے یہ مسئلہ ثابت ہوتا ہے کہ قربانی کا گوشت ذخیرہ کیا جاسکتا ہے۔2۔ ایام تشریق کی بابت بھی مسئلہ واضح ہورہا ہے کہ یہ کھانے، پینے ا اللہ تعالیٰ کا ذکر کرنے کے دن ہیں، اس لیے ان دنوں میں ایام عید کی طرح روزے رکھنا حرام اور ناجائز ہے۔ 3۔مذکورہ احایث میں اس مسئلے کی مکمل طور پر وضاحت موجود ہے کہ ممانعت اس صورت میں ہے کہ جب ایسا کرنے سے معبود ان باطلہ اور غیر ا اللہ کی رضا اور وضاحت موجود ہے کہ ممانعت اس صورت میں ہے کہ جب ایسا کرنے سے معبود ان باطلہ اور غیر ا اللہ کی رضا اور خوشنودی مطلوب ہو، یا خاص وقت کے ساتھ اس کی تخصیص ہوجیسا کہ وہ لوگ ماہِ رجب کے ابتدائی ایام میں جانور ذبح کیا کرتے تھے۔ ہاں، جب جانور ذبح کرنے سے ا اللہ تعالیٰ کی رضا مطلوب ہو اور کسی خاص دن، مہینے اور وقت کا تعین بھی نہ ہو توایسا کرنا صرف جائز نہیں مستحب بھی ہے۔ 4۔اس حدیث مبارکہ سے یہ بھی معلوم ہوتا ہے کہ جانوروں کے چھوٹے اور نوزئیدہ بچے ذبح نہ کیے جائیں بلکہ انھیں پال پوس کر بڑا کیا جائے، جب ان کا گوشت پختہ اور کھانے کے قابل ہوجائے تب ذبح کیے جائیں اور ان کا گوشت صدقہ کیا جائے۔واللہ اعلم"}],[4231,"نبیشہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم کو پکار کر کہا: ہم لوگ عتیرہ ذبح کرتے تھے۔ یعنی زمانہ جاہلیت میں رجب کے مہینے میں، تو اب آپ ہمیں کیا حکم دیتے ہیں؟ آپ نے فرمایا: \"جس مہینہ میں چاہو اسے ذبح کرو، اور اللہ تعالی کی اطاعت کرو اور لوگوں کو کھلاؤ\"، اس نے کہا: ہم لوگ عہد جاہلیت میں فرع ذبح کرتے تھے؟ آپ نے فرمایا: \"ہر چرنے والے جانور میں فرع ہے یہاں تک کہ جب وہ مکمل (جانور) ہو جائے تو تم اسے ذبح کرو اور اس کا گوشت صدقہ کرو، یہی چیز بہتر ہے\"۔","الألباني: صحيح",{"u2":"حضرت نبیشہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ ایک آدمی نے بآواز بلند اکرم صلی اللہ علیہ وسلم کو پکار کر کہا: ہم دور جاہلیت میں ماہ رجب کے دور ان میں عتیرہ ذبح کیا کرتے تھے۔ اب آپ ہمیں کیا حکم دیتے ہیں؟ آپ نے فرمایا: ’’ذبح کرو جس مہینے میں بھی ہو۔ ا اللہ تعالیٰ کے لیے نیکی کرو اور لوگوں کو کھلاؤ۔ ‘ اس نے کہا: ہم جاہلیت میں فرع بھی ذبح کیا کرتے تھے۔ آپ نے فرمایا: ’’ہر چرنے والے جانوروں میں سے جانور ذبح کرنا چاہیے لیکن اس وقت جب وہ جوان ہوجائے، پھر تو اسے ذبح کرے اور اس کا گوشت صدقہ کردے۔ یقینا بہتر ہے۔ ‘‘"}],[4232,"نبیشہ ہذلی رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے کہا: اللہ کے رسول! ہم لوگ زمانہ جاہلیت میں عتیرہ ذبح کرتے تھے، تو اب آپ ہمیں کیا حکم دیتے ہیں؟ آپ نے فرمایا: \"اللہ تعالی کی رضا کے لیے جس مہینے میں چاہو ذبح کرو، اور اللہ تعالی کی اطاعت کرو اور لوگوں کو کھلاؤ\"۔","الألباني: صحيح",{"u2":"حضرت نبیشہ ہذلی رضی اللہ تعالٰی عنہ سے روایت ہے کہ آدمی نے کہا: اے ا اللہ کے رسول! ہم جاہلیت میں عتیرہ ذبح کیا کرتے تھے۔ اب آپ کا کیا حکم ہے؟ آپ نے فرمایا: ’’ ا اللہ تعالیٰ کے لیے ذبح کرو۔ جون سا\nمہینہ بھی ہو۔ ا اللہ تعالیٰ (کی رضا مندی سے حصول) کے لیے نیکی کرو اور لوگوں کو کھانا کھلاؤ۔ ‘‘"}],[4233,"ابورزین لقیط بن عامر عقیلی رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! ہم لوگ جاہلیت میں رجب کے مہینے میں کچھ جانور ذبح کیا کرتے تھے، ہم خود کھاتے تھے اور جو ہمارے پاس آتا اسے بھی کھلاتے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس میں کوئی حرج نہیں\"۔ وکیع بن عدس کہتے ہیں: چنانچہ میں اسے نہیں چھوڑتا۔","الألباني: صحيح لغيره",{"u2":"حضرت ابورزین بن عامر عقیلی رضی اللہ تعالٰی عنہ سے منقول ہے کہ میں نے عرض کی: اے ا اللہ کے رسول! ہم دور جاہلیت میں ماہ رجب کے دور ان میں کچھ جانور ذبح کیا کرتے تھے۔ ہم خود بھی کھاتے تھے، اپنے پاس آنے والوں (اور ملنے ملانے والوں) کو بھی کھلاتے تھے۔ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اس میں کوئی حرج نہیں۔ ‘‘ (راوی حدیث) وکیع بن عدس نے کہا: میں تو یہ نیکی نہیں چھوڑوں گا۔","f2":"ا اللہ تعالیٰ کی رضا مندی کے لیے یا اپنے پکانے کھانے کے لیے کسی وقت بھی جانور ذبح کیا جاسکتا ہے، اوروں کو بھی کھلایا جاسکتا ہے۔ تفصیل کے لیے دیکھیے حدیث نمبر 4227۔"}],[4234,"ام المؤمنین میمونہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کا گزر ایک پڑی ہوئی مردار بکری کے پاس سے ہوا، آپ نے فرمایا: \"یہ کس کی ہے؟\"لوگوں نے کہا: میمونہ کی۔ آپ نے فرمایا: \"ان پر کوئی گناہ نہ ہوتا اگر وہ اس کی کھال سے فائدہ اٹھاتیں\"، لوگوں نے عرض کیا: وہ مردار ہے۔ تو آپ نے فرمایا: \"اللہ تعالی نے (صرف) اس کا کھانا حرام کیا ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی اس کے جسم کے دیگر اعضاء مثلاً بال، دانت، سینگ وغیرہ سے استفادہ کرنے میں کوئی حرج نہیں۔","الألباني: صحيح",{"u2":"حضرت میمونہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ایک مردہ بکری کے پاس سے گزرے جسے باہر پھینک دیا گیا تھا۔ آپ نے فرمایا: ’’یہ جس کی ہے؟ ‘‘ لوگوں نے کہا: (ام المومنین) حضرت میمونہ رضی اللہ عنہا کی۔ آپ نے فرمایا: ‘‘ اگر وہ اس کے چمڑے سے فائدہاٹھا لیتی تو کیا حرج ہوتا؟ ‘‘ لوگوں نے کہا: یہ تو مردہ ہے۔ آپ نے فرمایا: ’’ ا اللہ تعالیٰ نے صرف اس کا (گوشت وغرہ) کھانا حرام کیا ہے۔ ‘‘","f2":"1۔باب کے ساتھ حدیث کی مطابقت اس طرح ہے کہ مردہ جانور چمڑے کا حکم یہ ہے کہ اس سے فائدہ اٹھانا جائز ہے بشر طیکہ اسے رنگ دیا جائے جیسا کہ دیگر احادیث میں اس کی وضاحت موجود ہے۔ 2۔حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوا کہ اگر کسی امام یا ذمہ دار شخص کی بات کا مفہوم سمجھ میں نہ آئے تو اس سے پوچھا جاسکتا ہے، یہ اس کے احترام کے منافی نہیں جس طرح صحابہ کرام رضی اللہ عنہم نے رسول ا اللہ صلی اللہ علیہ وسلم سے پوچھ لیا تھا کہ مردار جانور کے چمڑے سے کس طرح نفع اٹھایا جاسکتا ہے؟ 3۔قابل احترام اور ذی وقار شخصیت کو بھی سوال، بحث و تحقیق کے وقت برہم نہیں ہونا چاہیے اور نہ وہ اس کو اپنی انا کا مسئلہ بنائے جیسا کہ رسول ا اللہ صلی اللہ علیہ وسلم کا بہترین اسوہ ہے کہ آپ نے لوگوں کیک پوچھنے لپر بلاتا مل بتا دیا۔ 4۔اس حدیث مبارکہ سے یہ اہم مسئلہ بھی ثابت ہوتا ہے کہ کتاب ا اللہ عموم کی تخصیص حدیث شریف سے ہوسکتی ہے۔ قرآن مجید میں مطلق طور پر فرمایا گیا ہے: مردار کی حرمت کا حکم اس کے ہر ہر جز کو شامل ہے اور ہر حال میں شامل ہے۔ حدیث اور سنت نے اس عام حکم میں یہ تخصیص کردی ہے کہ مردار جانور چمڑا رنگ لیا جائے تو اس کا استعمال حلال ہوجاتا ہے۔"}],[4235,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا گزر ایک مردار بکری کے پاس سے ہوا جو آپ نے ام المؤمنین میمونہ رضی اللہ عنہا کی لونڈی کو دی تھی، آپ نے فرمایا: \"تم نے اس کی کھال سے کیوں فائدہ نہیں اٹھایا؟\" لوگوں نے عرض کیا: اللہ کے رسول! وہ مردار ہے۔ تو آپ نے فرمایا: \"اس کا کھانا حرام کیا گیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا سے روایت ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم کا گزر ایک مردار بکری کے پاس سے ہوا جو آپ نے اپنی اہلیہ متحرمہ میمونہ رضی اللہ عنہا کی آزاد کردہ لونڈی کو دی تھی، تو (اسے دیکھ کر) آپ نے فرمایا: ’’تم نے اس کی کھال سے فائدہ کیوں نہیں اٹھا لیا؟ ‘‘ انھوں نے کہا: اے ا اللہ کے رسول! وہ تو مردار ہے۔ تو رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مردار (بکری) کر صرف کھانا حرام کیا گیا ہے۔ ‘‘"}],[4236,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مردار بکری کو دیکھا جو ام المؤمنین میمونہ کی لونڈی کی تھی اور وہ بکری صدقے کی تھی، آپ نے فرمایا: \"اگر لوگوں نے اس کی کھال اتار لی ہوتی اور اس سے فائدہ اٹھایا ہوتا\" (تو اچھا ہوتا)۔ لوگوں نے عرض کیا: وہ مردار ہے، آپ نے فرمایا:\"صرف اس کا کھانا حرام کیا گیا ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہا نے بیان کیا کہ رسول ا اللہ صلی اللہ علیہ وسلم نے (اپنی ہلیہ) میمونہ رضی اللہ عنہا کی لونڈی کی مردار بکری کو دیکھا جو صدقے کے مال سے اس کو دی گئی تھی۔ آپ نے فرمایا: ’’اگر وہ اس کی کھال اتار لیتے اور پھر اس سے فائدہ اٹھاتے تو (بہتر ہوتا)۔ ‘‘ انھوں نے کہا: وہ تو مردار ہے۔ آپ نے فرمایا: ’’اس کا صرف کھانا حرام کیا گیا ہے۔ ‘‘"}],[4237,"ام المؤمنین میمونہ رضی اللہ عنہا کہتی ہیں کہ ایک بکری مر گئی، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم لوگوں نے اس کی کھال نہیں اتاری کہ اس سے فائدہ اٹھاتے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا نے کہا: مجھے حضرت میمونہ رضی اللہ عنہا نے بتلایا کہ ایک بکری مرگئی تو نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تم نے اس کی کھال کو رنگ کیوں نہیں لیا کہ اس نے فائدہ اٹھاتے؟ ‘‘"}],[4238,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم ام المؤمنین میمونہ رضی اللہ عنہا کی ایک مردار بکری کے پاس سے گزرے، تو آپ نے فرمایا:\"کیا تم لوگوں نے اس کی کھال نہیں اتاری کہ اسے دباغت دے کر فائدہ اٹھا لیتے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا نے فرمایا: نبی صلی اللہ علیہ وسلم کا گزر حضرت میمونہ رضی اللہ عنہا کی مردار بکری کے پاس سے\nہوا تو آپ نے فرمایا: ’’تم نے اس کی کھال لے کر اسے رنگ کیوں نہیں لیا کہ اس فائدہ اٹھاتے؟ ‘‘"}],[4239,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم ایک مردار بکری کے پاس سے گزرے اور فرمایا: \"کیا تم لوگوں نے اس کی کھال سے فائدہ نہیں اٹھایا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا سے مروی ہے کہ نبی صلی اللہ علیہ وسلم کا گزر ایک مردار نکری کے پاس سے ہوا تو آپ نے فرمایا: ’’تم نے اس کی کھال سے فائدہ کیوں نہیں اٹھالیا؟ ‘‘"}],[4240,"ام المؤمنین سودہ رضی اللہ عنہا کہتی ہیں کہ ہماری ایک بکری مر گئی تو ہم نے اس کی کھال کو دباغت دی، پھر ہم اس میں ہمیشہ نبیذ بناتے رہے یہاں تک کہ وہ پرانی ہو گئی۔","الألباني: صحيح",{"u2":"نبی اکرم صلی اللہ علیہ وسلم کی زوجہ مطہرہ حضرت سودہ رضی اللہ عنہا نے بیان کیا کہ ہماری ایک بکری مر گئی تو ہم نے اس کی کھال کو رنگ لیا، پھر ہم اس میں نبیذ بناتے رہے حتی کہ وہ مشک بن گئی۔"}],[4241,"مجاہد کہتے ہیں کہ میں نے طاؤس کا ہاتھ پکڑا یہاں تک کہ میں انہیں لے کر رافع بن خدیج رضی اللہ عنہ کے بیٹے (اسید) کے یہاں گیا، تو انہوں نے ان سے بیان کیا کہ میرے والد رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے زمین کرائیے پر دینے سے منع فرمایا، تو طاؤس نے انکار کر دیا اور کہا: میں نے ابن عباس رضی اللہ عنہما سے سنا ہے کہ وہ اس میں کوئی حرج نہیں سمجھتے تھے۔ اور اس حدیث کو ابو عوانہ نے ابوحصین سے، اور ابوحصین نے مجاہد سے، اور مجاہد نے رافع رضی اللہ عنہ سے مرسلاً (یعنی منقطعا) روایت کیا ہے ۱؎۔\n§وضاحت\n۱؎: سابقہ تمام سندوں میں مجاہد اور رافع کے درمیان یا تو اسید بن رافع بن خدیج یا اسید بن ظہیر کسی ایک کا واسطہ ہے اور اس سند میں یہ واسطہ ساقط ہے، اس لیے یہ سند منقطع ہے مگر متابعات سے تقویت پا کر یہ روایت بھی صحیح ہے۔\nعبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کھال کو دباغت دے دی جائے وہ پاک ہو گئی\" ۱؎۔\n§وضاحت\n۱؎: حلال جانور کی کھال دباغت کے بعد پاک ہو گی، اور اس کا استعمال جائز ہو گا۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا سے روایت ہے، رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس کچی کھال کو بھی رنگ لیا جائے تو وہ پاک ہو جاتی ہے۔ ‘‘"}],[4242,"عبدالرحمٰن بن وعلہ کہتے ہیں کہ انہوں نے ابن عباس رضی اللہ عنہما سے پوچھا: ہم لوگ مغرب کے علاقہ میں جہاد کو جا رہے ہیں، وہاں کے لوگ بت پرست ہیں، ان کے پاس مشکیں ہیں جن میں دودھ اور پانی ہوتا ہے؟ ابن عباس رضی اللہ عنہما نے کہا: دباغت کی ہوئی کھالیں پاک ہوتی ہیں۔ عبدالرحمٰن بن وعلہ نے کہا: یہ آپ کا خیال ہے یا کوئی بات آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہے۔ انہوں نے کہا: بلکہ رسول اللہ صلی اللہ علیہ وسلم سے (سنی) ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن وعلہ سے روایت ہے کہ میں نے حضرت ابن عباس رضی اللہ عنہا سے پوچھا کہ ہم ان مغربی لوگوں سے جنگ کرنے جاتے ہیں جو کہ بت پرست ہیں۔ ان کے پاس مشکیزے ہوتے ہیں جن میں دودھ یا پانی ہوتا ہے۔ (تو کیا ہم وہ استعمال کر سکتے ہیں؟) حضرت ابن عباس رضی اللہ عنہا نے سنی ہے؟ انھوں نے فرمایا: بلکہ رسول ا اللہ صلی اللہ علیہ وسلم سے سنی ہے۔","f2":"معلوم ہوا اگرچہ بت پرست کا ذبیحہ تو حلال نہیں مگر وہ چمڑے کو دباغت دے تو چمڑا پاک ہو جاتا ہے۔"}],[4243,"سلمہ بن محبق رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے غزوہ تبوک میں ایک عورت کے پاس سے پانی منگوایا۔ اس نے کہا: میرے پاس تو ایک ایسی مشک کا پانی ہے جو مردار کی کھال کی ہے، آپ نے فرمایا: \"تم نے اسے دباغت نہیں دی تھی؟\" وہ بولی: کیوں نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کی دباغت ہی اس کی پاکی ہے\"۔","الألباني: صحيح",{"u2":"حضرت سلمہ بن محبق رضی اللہ تعالٰی عنہ سیف روایت ہے کہ ا اللہ تعالیٰ کے نبی صلی اللہ علیہ وسلم نے غزوہ تبوک (کے سفر) میں ایک عورت کے پاس سے پانی منگوایا۔ وہ کہنے لگی: میرے پاس پانی تو مگر مردار کے چمڑے سے بنے ہوئے مشکیزے میں ہے۔ آپ نے فرمایا: ’’تو نے اسے دباغت نہیں دی تھی؟ ‘‘اس نے کہا: کی! دباغت تو دی تھی۔ آپ نے فرمایا: ’’تو دباغت (رنگنے) سے چمڑا پاک ہو جاتا ہے۔ ‘‘"}],[4244,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سے مردار کی کھال کے بارے میں پوچھا گیا تو آپ نے فرمایا: \"اس کی دباغت ہی اس کی پاکی ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ نبی اکرم سے مردار کے کچے چمڑے کے بارے میں پوچھا گیا تو آپ نے فرمایا: ’’دباغت (رنگنے) سے پاک ہو جاتا ہے۔‘‘","f2":"دباغت کسی بھی ایسی چیز سے دی جاسکتی ہے جو چمڑے کی رطوبت کو ختم کر دے اور بدبو کو زائل کردے۔"}],[4245,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے مردے کی کھالوں کے بارے میں سوال کیا گیا، تو آپ نے فرمایا: \"اس کی دباغت ہی اس کی پاکی ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول ا اللہ صلی اللہ علیہ وسلم سے مردار کے چمڑے کے بارے میں پوچھا گیا تو آپ نے فرمایا: ’’دباغت چمڑے کو پاک کر دیتی ہے۔‘‘"}],[4246,"ام المؤمنین عائشہ رضی اللہ عنہا روایت کرتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مردار کی کھال کی پاکی ہی اس کی دباغت ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’دباغت سے مردار کا چمڑا پاک ہو جاتا ہے۔‘‘"}],[4247,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مردار کی کھال کی پاکی ہی اس کی دباغت ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مردار کا چمڑا دباغت سے پاک ہو جاتا ہے۔ ‘‘"}],[4248,"ام المؤمنین میمونہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے قریش کے کچھ لوگ گزرے، وہ اپنی ایک بکری کو گدھے کی طرح گھسیٹ رہے تھے، ان سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم لوگ اس کی کھال رکھ لیتے\" (تو بہتر ہوتا)، انہوں نے کہا: وہ مردار ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے پانی اور سلم درخت کا پتا (جس سے دباغت دی جاتی ہے) پاک کر دیتے ہیں\" ۱؎۔\n§وضاحت\n۱؎: یہ ضروری نہیں کہ ہمارے زمانہ میں بھی دباغت کے لیے پانی کے ساتھ ساتھ اس دور کے کانٹے دار درخت ہی کا استعمال کیا جائے، موجودہ ترقی یافتہ زمانہ میں جس پاک چیز سے بھی دباغت دی جائے مقصد حاصل ہو گا لیکن اس کے ساتھ پانی کا استعمال ضروری ہے :(قرظ: ایک سلم نامی کانٹے دار درخت کے پتے )۔","الألباني: صحيح",{"u2":"حضرت عالیہ بنت سبیع سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم کی زوجہ محترمہ حضرت میمونہ رضی اللہ عنہا نے مجھے بیان فرمایا کہ رسول ا اللہ صلی اللہ علیہ وسلم کے پاس سے کچھ قریشی گزرے۔ وہ اپنی ایک مری ہوئی بکری کو گدھے کی طرح گھسیٹ کرلے جارہے تھے۔ رسول ا اللہ صلی اللہ علیہ وسلم نے انھیں فرمایا: ’’اگر تم اس کا چمڑا اتار لیتے (تو اچھا ہوتا)۔ ‘‘انھوں نے کہا: یہ تو مری ہوئی ہے۔ رسول ا اللہ صلی اللہ علیہ وسلم نے انھیں فرمایا: ’’اسے پانی اور کیکر کا چھلکا پاک کر دیتا ہے۔ ‘‘","f2":"یہ حدیث اس بات پر دلات کرتی ہے کہ مردار جانور کے کچے چمڑے کورنگنے کے لیے پانی اور کیکر کی چھال ضروری ہے یا اسی قسم کی صلاحیت رکھنے والا ایسا کیمیکل جو چمڑے کی بو اور طوبت کو ختم کر دے، اس کا استعمال بھی جائز ہے۔ مقصود باغت ہے۔"}],[4249,"عبداللہ بن عکیم جہنی کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم کا مکتوب گرامی پڑھ کر سنایا گیا (اس وقت میں ایک نوخیز لڑکا تھا) کہ تم لوگ مردے کی بغیر دباغت کی ہوئی کھال یا پٹھے سے فائدہ مت اٹھاؤ\" ۱؎۔\n§وضاحت\n۱؎: بعض لوگوں نے اس حدیث کو ناسخ، اور ابن عباس اور میمونہ رضی اللہ عنہم کی حدیثوں کو منسوخ قرار دیا ہے کیونکہ یہ مکتوب آپ کی وفات سے چھ ماہ پہلے کا ہے، لیکن جمہور محدثین نے اس کے برخلاف پچھلی حدیثوں کو ہی سند کے لحاظ سے زیادہ صحیح ہونے کی بنیاد پر راجح قرار دیا ہے، صحیح بات یہ ہے کہ دونوں حدیثوں میں کوئی تضاد نہیں، پچھلی حدیثوں میں جو مردار کے چمڑے سے نفع اٹھانے کی اجازت ہے وہ دباغت کے بعد ہے، اور :(مخضرم راوی ) عبداللہ بن عکیم کی حدیث میں جو ممانعت ہے وہ دباغت سے پہلے کی ہے :(دیکھئیے اگلی حدیث ) امام ابوداؤد رحمہ اللہ نے اس حدیث کے بعد نضر بن سہیل سے نقل کیا ہے کہ «إہاب»دباغت سے پہلے والے چمڑے کو کہتے ہیں، اور دباغت کے بعد چمڑے کو «شف» یا «قربۃ» کہتے ہیں۔","الألباني: صحيح",{"u2":"حضرت عبد ا اللہ بن عکیم سے مروی ہے کہ میں اس وقت جوان لڑکا تھا جب ہمیں رسول ا اللہ صلی اللہ علیہ وسلم کا خط پڑھ کر سنایا گیا کہ’’ تم مردار کے چمڑے اور پٹھے سے فائدہ نہ اٹھاؤ۔ ‘‘","f2":"۔ حضرت عبد ا اللہ عکیم صحابی نہیں لیکن آپ کے دور میں موجود تھے اور مسلمان تھے مگر آپ کی زیارت نصیب نہ ہوسکی۔ ایسے شخص کو محد ثین کی اصطلاح میں کہتے ہیں۔ مخضرم کے معنی ہیں: ’’صحابہ سے الگ کیا گیا باوجود اس زمانے میں ہونے کے۔‘‘ 2۔یہ روایت سابقہ روایات کے خلاف ہے مگر وہ اس صحیح تر ہیں، نیز تطبیق بھی ممکن ہے کہ دباغت کے بغیر چمڑے سے فائدہ نہ اٹھاؤ۔ دباغت کے بعد فائدہ اٹھا سکتے ہو۔ یہ اشارہ احادیث میں موجود ہے، لہٰذا جن حضرات نے اس حدیث متاخر ہے کیونکہ یہ آپ کی وفات سے صرف ایک ماہ قبل کی ہے۔ ‘‘مگر نسخ تو آخری حربہ ہے۔ اگر تطبیق ممکن ہے تو نسخ کی کیا ضرورت ہے؟ جمہور تطبیق ہی کے قائل ہیں۔"}],[4250,"عبداللہ بن عُکیم جہنی کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں لکھ بھیجا: \"تم لوگ مردار کی غیر مدبوغ کھال اور پٹھے سے فائدہ نہ اٹھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت عبدا اللہ بن عکیم سے روایت ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے ہمیں یہ تحریر لکھ کر بھیجی: ’’تم مردار کے چمڑے اور پٹھے سے فائدہ نہ اٹھاؤ۔ ‘‘","f2":"’’لکھ کر‘‘ ظاہر الفاظ سے معلوم ہوتا ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے خود یہ تحریر لکھی لیکن صحیح نہیں۔ آپ لکھنا لکھا ہوا پڑھنا نہیں جانتے تھے۔ یہ بات قطعی دلائل سے ثابت ہے، لہٰذا اس حدیث مجاز ہے، یعنی تحریر لکھوائی۔"}],[4251,"جریر رضی اللہ عنہ کہتے ہیں کہ جو کوئی غلام اپنے مالکوں سے بھاگا اور دشمن سے جا کر مل گیا تو اس نے خود کو حلال کر دیا ۱؎۔\n§وضاحت\n۱؎: یعنی اس کا خون حلال ہو گیا۔\nعبداللہ بن عُکیم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قبیلہ جہینہ کے لوگوں کو لکھا: \"مردار کی غیر مدبوغ کھال اور پٹھے سے فائدہ نہ اٹھاؤ\"۔ ابوعبدالرحمٰن(امام نسائی) کہتے ہیں: اس باب میں \"مردار کی کھال جبکہ اسے دباغت دی گئی ہو\" سب سے صحیح حدیث زہری کی حدیث ہے جسے عبیداللہ بن عبداللہ، ابن عباس سے اور وہ ام المؤمنین میمونہ رضی اللہ عنہا سے روایت کرتے ہیں (نمبر ۴۲۳۹)، واللہ اعلم۔","الألباني: ضعيف الإسناد",{"u2":"حضرت عبدا اللہ بن عکیم سے منقول ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے جہینہ قبیلے کی طرف یہ تحریر لکھ کر بھیجی: ’’تم مردار کے (غیرمد بوغ) چمڑے اور پٹھے کو استعمال نہ کرو۔ ‘‘\nابو عبدالرحمن (امام انسائی رحمہ اللہ) نے فرمایا: اس مسئلے میں صحیح ترین روایت وہ ہے جس میں دباغت سے چمڑے کے پاک ہونے کاذکر ہے، یعنی زہری عن عبید ا اللہ، عن ابن عباس، عن میمونہ والی روایت۔","f2":"گویا امام صاحب اس روایت کو ترجیح دے رہے ہیں۔ دونوں روایات میں تطبیق پیچھے گزر چکی ہے۔"}],[4252,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ مردار جانور کی کھال سے فائدہ اٹھایا جا سکتا ہے جب کہ وہ دباغت دی گئی ہو۔","الألباني: ضعيف",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ جب مردار کے چمڑے کو رنگ جائے تو اس سے فائدہ اٹھایا جاسکتا ہے۔","f2":"1۔ محقق کتاب نے مذکورہ روایت کو سنداََ ضعیف قرار دیا ہے جبکہ یہ روایت دیگر شواہد اور متابعات کی بنا پر قابل حجت اور قابل عمل ہے۔ تفصیل کے لیے دیکھیے:(الموسوعۃ الحدیثیۃ مسندالامام الاحمد:40/504 و ذخیرۃ العقبیٰ شرح سنن النسائی:33/44‘46\n(2۔)’’حکم دیا‘‘یعنی اجازت اور رخصت دی۔ ممکن ہے حکم ہی مراد ہو کیونکہ مال ضائع کرنے کی اجازت نہیں۔"}],[4253,"ابوالملیح کے والد اسامہ بن عمیر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے درندوں کی کھالوں سے (فائدہ اٹھانے سے) منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ابوالملیح کے والد محترم (حضرت اسامہ رضی اللہ تعالٰی عنہ) سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے درندوں کے چمڑے استعمال کرنے سے منع فرمایا۔","f2":"درندوں کے چمڑے عموماََ متکبر لوگ استعمال کرتے ہیں، اس لیے ان کے استعمال سے منع فرمایا جس طرح مسلمان مردوں کو سونے اور ریشم کے استعمال سے منع فرمایا گیا ہے۔ شیر اور چیتے وغیرہ کا چمڑا عام استعمال میں تھا۔ ممکن ہے دباغت کے بغیر استعمال کیا گیا ہو لیکن یہ مرجوع احتمال ہے۔ صحیح بات پہلی ہی ہے۔"}],[4254,"مقدام بن معد یکرب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ریشم، سونے اور چیتوں کی کھال کے بستر یا کجاوے وغیرہ سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت مقدام بن معد یکرب رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے (مردوں کو) ریشم، سونے اور چیتوں کے چمڑے سے بنے ہوئے گدیلوں کے استعمال سے منع فرمایا ہے۔"}],[4255,"خالد بن معدان کہتے ہیں کہ مقدام بن معد یکرب رضی اللہ عنہ معاویہ رضی اللہ عنہ کے پاس آئے اور ان سے کہا کہ میں آپ کو اللہ کی قسم دلاتا ہوں۔ کیا آپ جانتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے درندوں کی کھالوں کے لباس پہننے اور ان پر سوار ہونے سے منع فرمایا ہے؟ کہا: ہاں۔","الألباني: صحيح",{"u2":"حضرت خالد سے روایت ہے کہ حضرت مقدام بن معد یکرب رضی اللہ تعالٰی عنہ حضرت معاویہ رضی اللہ تعالٰی عنہ کے پاس آئے اور کہنے لگے: میں آپ سے ا اللہ تعالیٰ کا واسطہ دے کرپوچھتا ہوں، کیا آپ جانتے ہیں کہ رسول ا اللہ صلی اللہ علیہ وسلم نے درندوں کے چمڑے پہننے اور ان پر سوار ہونے سے منع فرمایا ہے؟ انھوں نے فرمایا: جی ہاں۔"}],[4256,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ انہوں نے فتح مکہ کے سال مکہ میں رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا، اللہ اور اس کے رسول نے شراب، مردار، سور اور بتوں کی خرید و فروخت حرام کر دی ہے۔ عرض کیا گیا: اللہ کے رسول! مردار کی چربی کے سلسلے میں آپ کا کیا خیال ہے؟ اسے کشتیوں پر لگایا جاتا اور کھالوں پر ملا جاتا ہے اور لوگ اس سے چراغ جلاتے ہیں، آپ نے فرمایا: \"نہیں، وہ حرام ہے\"، پھر آپ نے فرمایا: \"اللہ تعالی یہودیوں کو تباہ کرے، اللہ تعالی نے جب ان پر چربی حرام کر دی تو انہوں نے اسے گلایا، پھر بیچا، پھر اس کی قیمت کھائی\" ۱؎۔\n§وضاحت\n۱؎: اس حدیث سے حیلہ کی ممانعت ثابت ہوتی ہے، یہ ایسی ہی ہے جیسے یہودیوں نے سنیچر کے دن شکار کی ممانعت پر حیلہ کیا تھا کہ جمعہ کے دن پانی میں جال پھیلا دیتے تاکہ مچھلیاں پھنس جائیں اور سنیچر کی مدت ختم ہونے کے بعد آسانی سے شکار ہاتھ میں آ جائے، کسی بھی حرام چیز سے کسی طرح بھی فائدہ اٹھانا حرام ہے۔","الألباني: صحيح",{"u2":"حضرت جابربن عبدا اللہ رضی اللہ عنہا سے روایت ہے کہ انھوں نے رسول ا اللہ صلی اللہ علیہ وسلم کو فتح مکہ کے سال مکہ مکرمہ میں فرماتے سنا: ’’بلاشبہ ا اللہ عزو جل اور اس کے رسول (صلی اللہ علیہ وسلم) نے شراب، مردار، خنزیر اور بتوں کی خریدو فروخت سے منع فرمایا ہے۔‘‘ عرض کی گئی: اے ا اللہ کے رسول! مردار کی چربی کے بارے میں کیا حکم ہے؟ یہ کشتیوں کو ملی جاتی ہے اور چمڑوں کو لگائی جاتی ہے اور لوگ اس سے چراغ جلاتے ہیں؟ آپ نے فرمایا: ’’نہیں، یہ حرام ہے۔ ‘‘ اس وقت رسول ا اللہ صلی اللہ علیہ وسلم نے ارشاد فرمایا: ’’ا اللہ تعالیٰ یہودیوں پر لعنت فرمائے کہ جب ا اللہ تعالیٰ نے ان پر چربی کو پگھلا کر بیچ دیا اور اس کی قیمت کھانے لگے۔ ‘‘","f2":"1۔مردار جانور کی چربی انواعِ استعمال میں سے کسی بھی نوع میں استعمال نہیں ہوسکتی۔\n2)یہ حدیث مبارکہ اس بات پر بھی دلالت کرتی ہے کہ ہر وہ حیلہ جو کسی حرام چیز کو حلال کرنے کی خاطر اختیار کیا جائے، باطل ہے۔ ایسا حیلہ بھی باطل ہے جو حرام چیز کی حلت تک لے جائے اور اسی طرح اس کے برعکس بھی۔3) اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ کسی چیز کی ہیئت اور اس نام کی تبدیلی سے اس چیز کا حکم نہیں بدلتا، مثلاََ یہودیوں نے جامد چربی کو پگھلا کر اسے مائع میں تبدیل کرکے استعمال کیا، اس کے باوجود ان لپر لعنت کی گئی۔ یہی حکم دیگر اشیا ؤء کاہے۔ نیز اس مسئلے کی طرف بھی اشارہ ملتا ہے کہ جو کوئی حرام چیزوں کو حلال کرنے کی خاطر کسی قسم کا حیلہ تراشتا ہے، وہ ملعون ہے کیونکہ وہ بھی اس سلسلے میں یقینا ان یہودیوں کی راہ پر چلا ہے جنھوں نے ا اللہ تعالیٰ کی حرمتوں کو پامال کرنے کے لیے حیلے بہانے گھڑ لیے تھے۔ مذکورہ تفصیل سے مقصود یہ ہے کہ جو چیز فی نفسہ حرام ہے، اس سے کسی قسم کا فائدہ اٹھانا حرام ہے نیز اس کا کار4)وبار بھی حرام ہے۔ اس کو کسی حیلے سے حلال نہیں کیا جاسکتا، مثلاََ: شراب کو سر کہ بنا کر بیچا نہیں جاسکتا ہ۔ حرام چیز کی قیمت بھی حرام ہے۔"}],[4257,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ عمر رضی اللہ عنہ کو خبر پہنچی کہ سمرہ رضی اللہ عنہ نے شراب بیچی ہے تو انہوں نے کہا: اللہ سمرہ کو ہلاک و برباد کرے، کیا اسے نہیں معلوم کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی یہودیوں کو ہلاک و برباد کرے، ان پر چربی حرام کی گئی تو انہوں نے اسے گلایا۔ سفیان کہتے ہیں: یعنی اسے پگھلایا\" ۱؎۔\n§وضاحت\n۱؎: پھر اس کا تیل بیچا اور اس کی قیمت کھائی۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا سے مروی ہے کہ حضرت عمر رضی اللہ تعالٰی عنہ کو یہ بات پہنچی کہ حضرت سمرہ رضی اللہ تعالٰی عنہ نے شراب بیچی ہے۔ آپ نے فرمایا: ا اللہ تعالیٰ سمرہ کو ہلاک کرے، اسے علم نہیں کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا کہ ا اللہ تعالیٰ یہودیوں پر لعنت فرمائے کہ ان پر چربی حرام ہوئی تو انھوں نے اسے پگھلایا (اور بیچ دیا)۔","f2":"1)ا اللہ تعالیٰ کی حرام کردہ اشیاء سے اٹھانا درست نہیں۔ 2)یہ حدیث ناجائز حیلے کے بطلان پر بھی واضح طور پر دلالت کتی ہے اور یہ بھی کہ شریعت کی حرام کردہ اشیاء کو کسی بھی حیلے بہانے سے یا کسی چیز کی آڑلے کر حلال نہیں کیا جاسکتا۔ ایسی قبیح حرکت لعنت کے مستحق قرار پاسکتے ہیں۔3) اس حدیث مبارکہ سے معلوم ہوا کہ شراب کی خرید و فروخت ناجائز اور حرام ہے، نیز یہ بھی معلوم ہوا کہ جب کوئی چیز فی نفسہ حرام ہو تو اس کی قیمت بھی حرام ہی ہوتی ہے۔4) یہ حدیث مبارکہ سگریٹ، تمباکو، بیڑی، نسوار اور دیگر مسکرات ومفترات کی تجارت کی ممانعت پر بھی دلالت کرتی ہے۔"}],[4258,"ام المؤمنین میمونہ رضی اللہ عنہا سے روایت ہے کہ ایک چوہیا گھی میں گر کر مر گئی تو نبی اکرم صلی اللہ علیہ وسلم سے پوچھا گیا؟ آپ نے فرمایا: \"اسے اور اس کے اردگرد گھی کو نکال کر پھینک دو اور پھر اسے کھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت میمونہ رضی اللہ عنہا سے روایت ہے کہ ایک چوہیا گھی میں گری اور مرگئی۔ نبی اکرم صلی اللہ علیہ وسلم سے (اس کے متعلق) سوال کیا گیا تو آپ نے فرمایا: ’’چوہیا اور اس کے ارد گرد گھی کو پھینک دو اور باقی کھا لو۔‘‘"}],[4259,"ام المؤمنین میمونہ رضی اللہ عنہا روایت کرتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سے اس چوہیا کے بارے میں پوچھا گیا جو کسی جمے ہوئے گھی میں گر جائے تو آپ نے فرمایا: \"اسے اور اس کے اردگرد کے گھی کو لے کر پھینک دو\"۔","الألباني: صحيح",{"u2":"حضرت میمونہ رضی اللہ عنہا سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم سے پوچھا گیا کہ جمے ہوئے گھی میں چوہا گرگیا ہے۔ (اسے کیا کیا جائے؟) آپ نے فرمایا: ’’چوہے اور اس کے ارد گرد کے گھی کو نکال پھینکو۔ ‘‘"}],[4260,"ام المؤمنین میمونہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سے اس چوہیا کے متعلق پوچھا گیا جو گھی میں گر جائے؟ تو آپ نے فرمایا: \"اگر گھی جما ہوا ہو تو اسے اور اس کے اردگرد کے گھی کو نکال پھینکو اور اگر جما ہوا نہ ہو تو تم اس کے قریب نہ جاؤ\"۔\n§وضاحت\n۱؎: سند اور علم حدیث کے قواعد کے لحاظ سے یہ حدیث درجہ میں پہلی حدیث سے کم تر ہے، اور اس کے مخالف ہونے کی وجہ سے \" شاذ \" ہے، لیکن پہلی حدیث کے مضمون ہی سے یہ بات سمجھ میں آتی ہے کہ اسی قسم کے گھی کا \" اردگرد \" ہو سکتا ہے جو جامد ہو، اور اگر سیال :(بہنے والا ) ہو تو اس کا \" اردگرد \" کیسے ہو سکتا ہے ؟ اسی لیے بہت سے علماء اس حدیث کے مطابق فتوی دیتے ہیں۔","الألباني: شاذ",{"u2":"حضرت میمونہ رضی اللہ عنہا سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم سے پوچھا گیا: چوہا گھی میں گر جائے تو (کیا کیا جائے؟) آپ نے فرمایا: ’’اگر (گھی) جما ہوا ہو تو چوہا اور اس کے ارد گرد والا گھی باہر پھینک دو۔ (اور باقی کو استعمال کر لو) لیکن اگر وہ پگھلا ہوا ہے تو اس کے قریب بھی نہ جاؤ۔ ‘‘","f2":"چوہا مرنے سے پلید ہوجاتا ہے۔ ویسے بھی وہ حرام جانور ہے لیکن اگر گھی جماہوا ہو تو اس کی نجاست سارے گھی میں سرایت نہیں کرے گی، لہٰذا چوہے کے قریب والا گھی جو اس متاثر ہوا ہے، مثلا: اس میں آلودگی وغیرہ ہے تو چوہے سمیت باہر پھینک دیا جائے، باقی گھی پاک صاف ہے۔ اس حد تک تو اتفاق ہے لیکن اگر گھی مائع حالت میں ہے تو جمہور اہل علم کے نزدیک اس حدیث کے مطابق اسے ضائع کردیا جائے گا کیونکہ وہ پلید ہوچکا ہے بعض اہل علم نے اس میں بھی پہلے طریقے پر عمل کیا ہے کہ چوہا اور اس کے اترد گرد والا گھی پھینک دیا جائے اور باقی گھی استعمال کرلیا جائے۔ ان کے نزدیک مائع چیز اس وقت تک پلید نہیں ہوتی جب تک اس کا رنگ یا بویا ذائقہ نجاست کے ساتھ بدل نہیں جاتا، لہٰذا اگر چوہے کے مرنے سے گھی (مائع) میں کوئی تبدیلی نہیں آئی تو وہ پلید نہیں، استعمال ہوسکتا ہے۔ اس حدیث کو وہ ضعیف کہتے ہیں (شیخ البانی رحمہ اللہ نے بھی اسے شاذ قرار دیا ہے۔ دیکھیے لیکن امام ابن حبان رحمہ اللہ نے اس حدیث کو صحیح کہا ہے۔ بہر صورت مائع میں امکان ہے کہ چوہا مرنے کے بعد اس میں تیرتا رہا ہو۔ اس صورت میں پورا گھی اس کا ماحول قرار دیا جائے گا، اس لیے سار گھی ہی ضائع کرنا ہوگا۔ ویسے بھی مائع میں چوہے کے قریبی گھی کا تعین مشکل ہے، اس لیے جمہور اہل علم کا مسلک ہی احتیاط کے قریب ہے، اسے ہی اختیار کرنا چاہیے۔ واللہ اعلم۔"}],[4261,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک مردہ بکری کے پاس سے گزرے تو فرمایا: \"اس بکری والوں پر کوئی حرج نہ ہوتا اگر وہ اس کی کھال (دباغت دے کر) سے فائدہ اٹھا لیتے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک مردہ بکری کے پاس سے گزرے۔ آپ نے فرمایا: ’’اگر اس بکری کے مالک اس کے چمڑے سے فائدہ اٹھا لیتے تو کیا حرج تھا؟‘‘","f2":"اس حدیث کا متعلقہ باب سے تو کوئی تعلق نہیں، البتہ گزشتہ ابواب سے تعلق ہے۔ ممکن ہے قریبی باب ضمنی ہو۔ اصل باب سابقہ ہی ہو۔ قریبی باب جملہ معترضہ کی طرح ہو گا۔ و اللہ اعلم۔"}],[4262,"ابو سعید خدری رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کسی کے برتن میں مکھی گر جائے تو اسے اچھی طرح ڈبو دو(پھر اسے نکال کر پھینک دو)\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جب کسی کے (کھانے پینے کے) برتن میں مکھی گر جائے تو اسے ڈبو کر نکال دیا جائے۔‘‘","f2":"(۱) کھانے پینے والی کسی چیز یا برتن میں مکھی گر جائے تو اس کا حکم یہ ہے کہ وہ چیز اور برتن پلید نہیں ہوتا کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے مکھی کی بابت حکم فرمایا ہے کہ اس کو ڈبو دیا جائے اور پھر ڈبو کو نکال پھینکا جائے۔ (۲) اس حدیث سے یہ بات بھی معلوم ہوئی کہ مکھی زندہ ہو یا مردہ، وہ پاک ہوتی ہے۔ (۳) ’’ڈبو کر‘‘ ڈبونے سے اس کے مرنے کا اکان ہے۔ معلوم ہوا مکھی وغیرہ (جن میں خون کثیر مقدار میں نہیں ہوتا) کے مرنے سے مشروب پلید نہیں ہو گا۔ (۴) رسول صادق و مصدوق صلی اللہ علیہ وسلم سے دیگر روایات میں یہ الفاظ بھی آتے ہیں کہ مکھی کے ایک پر میں بیماری اور دوسریح میں شفا ہے۔ اور مکھی کسی چیز میں گرتے وقت وہ پر پہلے لگاتی ہے جس میں بیماری ہے، لہٰذا تم دوسرا پر بھی ڈبو دو تاکہ بیماری کا علاج ساتھ ہو جائے۔ (صحیح الخباری، بدء الخلق، حدیث: ۳۳۲۰، و سنن ابی داود، الأطعمۃ، حدیث: ۳۸۴۴) (۵) بعض حضرات نے اس حدیث پر کیا ہے کہ مکھی تو گندی چیزوں پر بیٹھتی ہے۔ پھر کھانے پینے والی چیزوں کو خراب کرتی ہے، لہٰذا مکھی کو ڈبونے سے تو مزید خرابی پیدا ہو گی۔ ان معترض حضرات کو معلوم ہونا چاہیے کہ وہ اپنی تمام تر کوششوں کے باوجود مکھی سے نہیں بچ سکتے اور نہ اس کی خرابی سے محفوظ رہ سکتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے کمال مہربانی فرماتے ہوئے اس کا علاج تجویز فرمایا ہے تو کیا برا کیا ہے؟ باقی رہی یہ چیز کہ اس کے ایک پر میں بیماری اور دوسرے میں شفا ہے تو یہ کوئی تعجب کی بات نہیں۔ شہد کی مکھی میں شہد بھی ہے اور زہر بھی۔ جانوروں میں دودھ بھی ہے اور گوبر بھی، نیز یہ عملی تجربہ ہے کہ بھڑ وغیرہ کاٹ لے تو اس کو وہیں جسم پر مسل دینے سے زہر ختم ہو جاتا ہے۔ کیوں نہ ایک سچے نبی کی بات کو صدق دل سے مان لیا جائے؟ فداہ نفسی و روحی۔ صلی اللہ علیہ وسلم"}],[4263,"عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے شکار کے بارے میں پوچھا، تو آپ نے فرمایا: \"جب تم اپنے کتے کو شکار کے لیے بھیجو تو اس پر \"بسم اللہ\" پڑھ لو، اب اگر تمہیں وہ شکار مل جائے اور مرا ہوا نہ ہو تو اسے ذبح کرو اور اس پر اللہ کا نام لو ۱؎ اور اگر تم اسے مردہ حالت میں پاؤ اور اس(کتے) نے اس میں سے کچھ نہ کھایا ہو تو اس کو کھاؤ، اس لیے کہ اس نے تمہارے لیے ہی اس کا شکار کیا ہے۔ البتہ اگر تم دیکھو کہ اس نے اس میں سے کچھ کھا لیا ہے تو تم اس میں سے نہ کھاؤ۔ اس لیے کہ اب اس نے اسے اپنے لیے شکار کیا ہے۔ اور اگر تمہارے کتے کے ساتھ دوسرے کتے بھی مل گئے ہوں اور انہوں نے اس (شکار) کو قتل کر دیا ہو اور اسے کھایا نہ ہو تب بھی تم اس میں سے کچھ مت کھاؤ، اس لیے کہ تمہیں نہیں معلوم کہ ان میں سے اسے کس نے قتل کیا ہے\"۔\n§وضاحت\n۱؎: یعنی: اللہ کا نام لے کر ذبح کرو۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے شکار کے بارے میں پوچھا۔ آپ نے فرمایا: ’’جب تو اپنا کتا (شکار کے پیچھے) چھوڑے تو اللہ تعالیٰ کا نام لے کر چھوڑ، پھر اگر تو شکار کو اس حال میں پا لے کہ کتے نے اسے قتل نہیں کیا تو اللہ کا نام لے کر اسے ذبح کر لے۔ اور اگر شکار کو اس حال میں پائے کہ کتا اسے قتل کر چکا ہے لیکن اس نے کچھ نہیں کھایا تو وہ شکار تو کھا سکتا ہے کیونکہ اس نے اسے تیرے لیے پکڑا ہے اور اگر تو دیکھے کہ کتے نے اس میں سے کچھ کھا لیا ہے تو تو اس میں سے کچھ بھی نہ کھا کیونکہ کتے نے تو اسے اپنے لیے پکڑا ہے۔ اور اگر تیرے کتے کے ساتھ اور کتے بھی مل جائیں، پھر وہ مل کر کسی جانور کو قتل کر دیں، پھر خواہ وہ اسے نہ بھی کھائی تو بھی تو اس سے کچھ نہ کھا کیونکہ تجھے علم نہیں کہ ان میں سے کس کتے نے اسے قتل کیا ہے۔‘‘","f2":"(۱) جب شکاری کتا شکار کے لیے چھوڑا جائے تو اس وقت بسم اللہ پڑھ کر چھوڑا جائے کیونکہ یہ رسول اللہ صلی اللہ علیہ وسلم کا حکم ہے۔ یہی حکم تیرا اور دوسرے آلاتِ شکار کا ہے کہ ان کے ذریعے سے بھی بسم اللہ پڑھ کر ہی شکار کیا جائے۔ (۲) حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوا کہ اس طریقے سے شکار کرنا جس کا حدیث شریف میں ذکر ہے، مباح اور جائز کام ہے۔ یہ اس لہو و لعب کی قسم سے نہیں جس سے منع کیا گیا ہے۔ اگر شکار کرنا ممنوع ہوتا تو رسول اللہ صلی اللہ علیہ وسلم اس کی قطعاً اجازت نہ دیتے۔ (۳) شوقیہ طور پر کتے پالنا جائز نہیں، تاہم بغرض شکار اس کی اجازت ہے۔ اسی طرح کتوں کی خرید و فروخت ویسے تو ممنوع ہے البتہ ایسے ’’سدھائے ہوئے‘‘ کتے کی خرید و فروخت کی بعض فقہاء اجازت دیتے ہیں۔ (۴) سکھلایا ہوا کتاب اگر بسم اللہ پڑھ کر شکار پر چھوڑا جائے اور وہ مالک کی خاطر ہی شکار کرے اور اس اثنا میں شکار ذبح کرنے سے پہلے مر جائے تو بھی اس کو کھانا درست ہے۔ ہاں، البتہ شکار اگر زندہ حالت میں مل جائے تو اسے بسم اللہ پڑھ کر ذبح کرنا ضروری ہے۔ یاد رہے کہ شکاری اور تربیت یافتہ کتے کے جھوٹے کا بھی وہی حکم ہے جو غیر تربیت یافتہ کتے کے جھوٹے کا حکم ہے کہ وہ حرام ہے۔ یہی وجہ ہے کہ شریعت مطہرہ نے اس شکار کے کھانے کی اجازت نہیں دی جسے کتے نے کھایا ہو، خواہ تھوڑا سا حصہ ہی سہی۔ حکمت اس کی یہی معلوم ہوتی ہے کہ امت اور مخلوق کے حقیقی خیر خواہ انہیں کتے کے زہریلے جراثیم کے خطرناک نتائج سے محفوظ رکھنا چاہیے ہیں … صلی اللہ علیہ وسلم … مزید تفصیل کے لیے دیکھئے: (سنن نسائی (اردو) ج: ۱، ص: ۳۱۸-۳۲۲ طبع دار السلام) (۵) اس حدیث سے ضمناً یہ مسئلہ بھی معلوم ہوا کہ اگر ایک جانور کو شکار کرنے کے لیے کتا چھوڑا جائے لیکن کتا اس کے علاوہ کوئی دورا جانور مالک کی خاطر شکار کر لے تو اس کو کھانا بھی جائز ہے کیونکہ کتے نے اسے اپنے مالک کے لیے شکار کیا ہے۔ (۶) کتے کا شکار جائز ہے مگر اس کے لیے دو شرطیں ہیں: بسم اللہ پڑھ کر کتا چھوڑا جائے اور اس کے ساتھ کوئی ایسا کتا شریک نہ ہو جس کو چھوڑتے وقت بسم اللہ نہ پڑھی گئی ہو، کتا شکار کے لیے سدھایا گیا ہو، یعنی وہ شکار کو مالک کے لیے پکڑے نہ کہ اپنے لیے، اور اس کی نشانی یہ ہے کہ وہ شکار کو صرف پکڑے، کھائے نہ۔ اگر کھا لے تو وہ سدھایا ہوا شمار نہ ہو گا۔ بعض علماء نے یہ بھی ضروری قرار دیا ہے کہ وہ کتاب شکار کو بھنبھوڑ کر نہ مار دے بلکہ دانت لگائے اور جانور خون نکلنے سے ختم ہو ورنہ بھنبھوڑنے سے مرنے والا جانور حلال نہ ہو گا۔ (۷) جس شخص کا ذبیحہ حلال ہے، اسی کے چھوڑے ہوئے کتے کا شکار حلال ہے، مثلاً: مسلمان، یہودی، عیسائی۔ اور جس شخص کا ذبیحہ حلال نہیں، اس کے چھوڑے ہوئے کتے کا شکار بھی حلال نہیں، مثلاً: بت پرست، مجوسی، آتش پرست وغیرہ۔ و اللہ اعلم۔"}],[4264,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے «معراض» (بے پر کے تیر) کے شکار کے بارے میں پوچھا تو آپ نے فرمایا:\"اگر اسے نوک لگی ہو تو کھاؤ اور اگر اسے آڑی لگی ہو تو وہ «موقوذہ» ہے\" ۱؎ میں نے آپ سے کتے کے (شکار کے) بارے میں پوچھا تو آپ نے فرمایا: \"جب تم(شکار پر) کتا دوڑاؤ پھر وہ اسے پکڑے اور اس میں سے کھایا نہ ہو تو تم اسے کھاؤ اس لیے کہ اس کا پکڑ لینا ہی گویا شکار کو ذبح کرنا ہے۔ لیکن اگر تمہارے کتے کے ساتھ کوئی اور کتا ہو اور تمہیں اندیشہ ہو کہ تمہارے کتے کے ساتھ دوسرے کتے نے بھی پکڑا ہو اور وہ شکار مر گیا ہو تو مت کھاؤ۔ اس لیے کہ تم نے بسم اللہ صرف اپنے کتے پر پڑھی تھی دوسرے کتے پہ نہیں۔\n§وضاحت\n۱؎: یعنی جو شکار کسی بھاری چیز سے مارا گیا ہو جیسے لاٹھی یا پتھر وغیرہ سے، یا کوئی جانور چھت وغیرہ سے گر کر مر جائے۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے معراض تیر کے شکار کے بارے میں پوچھا تو آپ نے فرمایا: ’’جو جانور تو تیر کی نوک سے شکار کرے، وہ تو کھا لے اور جو جانور اس کے پہلو سے شکار کرے (وہ نہ کھا کیونکہ) وہ چوٹ سے مرا ہے۔‘‘ میں نے آپ سے کتے (کے شکار) کے بارے میں پوچھا تو آپ نے فرمایا: ’’جب تو اپنا کتا چھوڑے اور وہ جانور کو جا پکڑے لیکن خود نہ کھائے تو تو اسے کھا سکتا ہے کیونکہ کتے کا پکڑنا بھی ذبح ہی ہے۔ اور اگر تیرے کتے کے ساتھ کوئی اور کتا مل جائے اور تجھے خطرہ ہو کہ شاید اس کے ساتھ اس نے بھی پکڑا ہے اور مار دیا ہے تو تو نہ کھا کیونکہ تو نے اپنے کتے کو چھوڑتے وقت بسم اللہ پڑھی ہے، دوسرے کتے پر نہیں۔‘‘","f2":"معراض ایک خاص قسم کا تیر ہوتا تھا جس کے نہ تو پر ہوتے تھے نہ نوک۔ بس ایک چھڑی سمجھ لیجیے۔ اس کی چوٹ سے شکار مر جاتا تھا جبکہ تیر کے شکار میں ضروری ہے کہ تیر کی نوک لگے تاکہ جانور خون نکل کر ختم ہو۔ اگر تیر بسم اللہ پڑھ کر چھوڑا گیا ہو تو خون نکل کر ختم ہونے کی وجہ سے یہ ذبح کے قائم مقام ہے، لہٰذا اس کا کھانا جائز ہے، البتہ چوٹ لگے تو پھر ذبح شرط ہے ورنہ وہ جانور حرام ہو گا۔ بندوق سے کیے گئے شکار کا بھی یہی حکم ہے۔"}],[4265,"عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: میں (شکار پر) سدھایا ہوا کتا چھوڑتا ہوں اور وہ جانور پکڑ لیتا ہے؟ آپ نے فرمایا: \"جب تم سدھایا کتا چھوڑو اور اس پر اللہ کا نام لے لو پھر وہ شکار پکڑے تو تم اسے کھاؤ میں نے عرض کیا: اگر وہ اسے مار ڈالے؟\" تو آپ نے فرمایا:\"اگرچہ وہ اسے مار ڈالے\"۔ میں نے عرض کیا: میں معراض پھینکتا ہوں؟ آپ نے فرمایا: \"اگر نوک لگے تو کھاؤ اور اگر آڑا لگے تو نہ کھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ سے منقول ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا کہ میں اپنا سدھایا ہوا کتا شکار پر چھوڑتا ہوں، وہ اسے پکڑ لے تو؟ آپ نے فرمایا: ’’جب تو اپنا سدھایا ہوا کتا چھوڑے اور بسم اللہ بھی پڑھے، پھر وہ پکڑ لے تو تو کھا سکتا ہے۔‘‘ میں نے کہا: اگرچہ وہ قتل کر دے؟ آپ نے فرمایا: ’’اگرچہ قتل کر دے۔‘‘ میں نے کہا: میں معراض تیر چلاتا ہوں تو پھر؟ آپ نے فرمایا: ’’اگر وہ نوک کے بل لگے تو تو کھا سکتا ہے اور اگر وہ کسی او جانب سے لگے تو پھر نہ کھا۔‘‘","f2":"سدھائے ہوئے اور تربیت یافتہ کتے سے شکار کرنا جائز ہے، نیز سدھائے اور غیر سدھائے کتوں کے شکار کا فرق ہے۔ اس حدیث سے یہ مسئلہ بھی معلوم ہوا کہ تیر اور اس قسم کی دیگر چیزوں، مثلاً: بندوق وغیرہ کے ذریعے سے شکار کرنا بھی جائز ہے، تاہم اس کے لیے شرط یہ ہے کہ تیر یا بندوق کی گولی شکار کیے جانے والے پرندے یا جانور کا خون نکال دے، اسے محض چوٹ کے انداز پہ نہ مار ڈالے، یعنی ان کے ذریعے سے بھی اس طرح سے شکار کیا جائے جس طرح دھار دار چیز سے کیا جاتا ہے۔ اگر تیر یا بندوق وغیرہ بسم اللہ پڑھ کر چلائی جائے اور شکار مر جائے تو وہ شکار حلال ہے بصورت دیگر ناجائز ہو گا، تاہم اگر بندوق چلاتے وقت شکاری اللہ کا نام لینا بھول جائے تو ایسی صورت میں اس شکار کو کھانا جائز ہو گا کیونکہ اللہ تعالیٰ نے اس امت کو بھول چوک معاف فرما دی ہے۔ و اللہ اعلم۔"}],[4266,"ابوثعلبہ خشنی رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! ہم لوگ اس سر زمین میں رہتے ہیں جہاں شکار بہت ملتا ہے۔ میں تیر کمان سے شکار کرتا ہوں اور سدھائے ہوئے کتے سے بھی شکار کرتا ہوں اور غیر سدھائے ہوئے کتے سے بھی۔ آپ نے فرمایا: \"جو شکار تم تیر سے کرو تو اللہ کا نام لے کر اسے کھاؤ ۱؎ اور جو شکار تم سدھائے ہوئے کتے سے کرو تو اللہ کا نام لے کر اسے کھاؤ، اور جو شکار تم غیر سدھائے ہوئے کتے سے کرو تو اگر اسے ذبح کر سکو تو کھا لو\" ۲؎۔\n§وضاحت\n۱؎: یعنی تیر پھینکتے وقت اللہ کا نام لو پھر اسے کھاؤ۔ ۲؎: اور اگر پانے سے پہلے مر گیا ہو تو مت کھاؤ۔","الألباني: صحيح",{"u2":"حضرت ابو ثعلبہ خشنی رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے کہا: اے اللہ کے رسول! ہم شکار والے علاقے میں رہتے ہیں۔ میں تیر سے بھی شکار کرتا ہوں، اپنے سدھائے ہوئے اور ان سدھائے کتوں کے ساتھ بھی۔ آپ نے فرمایا: ’’جو تو اپنے تیر سے شکار کرے، اسے کھا سکتا ہے بشرطیکہ تو نے (چھوڑتے وقت) بسم اللہ پڑھی ہو۔ اسی طرح جو شکار سدھائے ہوئے کتے سے کرے، وہ بھی کھا سکتا ہے بشرطیکہ تو نے کتا چھوڑتے وقت بسم اللہ پڑھی ہو، البتہ جو شکار تو ان سدھائے (غیر تربیت یافتہ) کتے سے کرے، اگر اس کو اپنے ہاتھ سے ذبح کرے، تب کھا سکتا ہے۔‘‘","f2":"یہ باب ان سدھائے اور غیر تربیت یافتہ کتے کے ذریعے سے کیے ہوئے شکار کے متعلق ہے، یعنی ایسے شکار کو کھانے کی بابت شریعت کا حکم کیا ہے؟ ان سدھائے، کتے کے ذریعے سے کیا ہوا شکار مطلقاً حرام ہے نہ مطلقاً حلال، بلکہ اس میں تفصیل ہے کہ اگر ایسے کتے کے ذریعے سے کیا ہوا شکار زندہ حالت میں مل جائے اور اسے ذبح کر لیا جائے تو اس کو کھانا جائز ہو گا اور اگر شکار مر چکا ہو، خواہ کتے نے اس میں سے کچھ بھی نہ کھایا ہو تو بھی اس کو کھانا حرام ہے اگرچہ کتے کو چھوڑتے وقت اللہ کا نام بھی لیا گیا ہو۔"}],[4267,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! میں سدھائے ہوئے کتے چھوڑتا ہوں تو وہ میرے لیے شکار پکڑ کر لاتے ہیں، کیا میں اسے کھا سکتا ہوں؟ آپ نے فرمایا: \"جب تم سدھائے ہوئے کتے چھوڑو (اور وہ تمہارے لیے شکار پکڑ کر لائیں) تو اسے کھا لو\"، میں نے عرض کیا: اگر وہ اسے مار ڈالیں؟ آپ نے فرمایا: \"اگرچہ وہ اسے مار ڈالیں، مگر یہ اسی وقت جب کہ اس کے ساتھ کوئی اور کتا شریک نہ ہوا ہو\" ۱؎ میں نے عرض کیا: میں معراض پھینکتا ہوں اور وہ(جانور کے جسم میں) گھس جاتا ہے؟ آپ نے فرمایا: \"اگر وہ گھس جائے تو تم کھا لو اور اگر وہ آڑا پڑے تو نہ کھاؤ\"۔\n§وضاحت\n۱؎: اس حدیث سے کئی مسئلے معلوم ہوئے: ۱- سدھائے ہوئے کتے کا شکار مباح اور حلال ہے۔ ۲- کتا سدھایا ہو یعنی اسے شکار کی تعلیم دی گئی ہو۔ ۳- اس سدھائے ہوئے کتے کو شکار کے لیے بھیجا گیا ہو، پس اگر وہ خود سے بلا بھیجے شکار کر لائے تو اس کا کھانا حلال نہیں، یہی جمہور علماء کا قول ہے۔ ۴- کتے کو شکار پر بھیجتے وقت بسم اللہ کہا گیا ہو۔ ۵- سدھائے کتے کے ساتھ کوئی دوسرا کتا شکار میں شریک نہ ہو اگر دوسرا شریک ہے تو حرمت کا پہلو غالب ہو گا اور یہ شکار حلال نہ ہو گا۔ ۶- کتا شکار میں سے کچھ نہ کھائے بلکہ اپنے مالک کے لیے محفوظ رکھے تب یہ شکار حلال ہو گا ورنہ نہیں۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم (طائی) رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے عرض کی: اے اللہ کی رسول! میں اپنے سدھائے ہوئے کتے شکار پر چھوڑتا ہوں۔ وہ شکار کو میرے لیے پکڑ کر رکھتے ہیں تو کیا میں کھا سکتا ہوں؟ آپ نے فرمایا: ’’جب تو سدھائے ہوئے کتے چھوڑے اور وہ تیرے لیے شکار پکڑے رکھیں (خود نہ کھائیں) تو کھا لے۔‘‘ میں نے کہا: اگر وہ قتل کر دیں تو؟ آپ نے فرمایا: ’’خواہ قتل کر دیں، البتہ ان کے ساتھ کوئی اور کتا شریک نہ ہو۔‘‘ میں نے کہا کہ میں معراض تیر پھینکتا ہوں جو شکار کو پھاڑ دیتا ہے؟ آپ نے فرمایا: ’’اگر تو تیر پھاڑ دے تو کھا لے لیکن اگر وہ جانور کو نوک کی بجائے کسی اور جگہ سے لگے تو نہ کھا۔‘‘"}],[4268,"عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے شکار کے متعلق سوال کیا۔ آپ نے فرمایا: \"جب تم (شکار پر) اپنا کتا چھوڑو پھر اس کے ساتھ کچھ ایسے کتے بھی شریک ہو جائیں جن پر تم نے بسم اللہ نہیں پڑھی ہے تو تم اسے مت کھاؤ۔ اس لیے کہ تمہیں نہیں معلوم کہ اسے کس کتے نے قتل کیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے شکار کے بارے میں پوچھا۔ آپ نے فرمایا: ’’جب تو اپنے (سدھائے ہوئے) کتے کو چھوڑے، پھر اس کے ساتھ اور کتے مل جائیں جن پر اللہ تعالیٰ کا نام نہ لیا گیا ہو تو اسے نہ کھا کیونکہ تو نہیں جانتا کہ ان میں سے کس کتے نے قتل کیا ہے۔‘‘","f2":"معلوم ہوا اگر ان کو چھوڑتے وقت بسم اللہ پڑھی گئی ہو، خواہ کسی دوسرے نے پڑھی ہو تو شکار حلال ہے۔"}],[4269,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے کتے کے بارے میں پوچھا تو آپ نے فرمایا: \"جب تم اپنے کتے کو چھوڑو اور اس پر بسم اللہ پڑھو تو اسے (شکار کو) کھاؤ اور اگر تم اپنے کتے کے ساتھ کوئی دوسرا کتا پاؤ تو مت کھاؤ اس لیے کہ تم نے صرف اپنے کتے پر بسم اللہ پڑھی تھی، دوسرے کتے پر نہیں\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے کتے کے بارے میں پوچھا۔ آپ نے فرمایا: ’’جب تو اپنا کتا چھوڑے، بسم اللہ پڑھے تو اس کا شکار کھا لے۔ اور اگر تو اپنے کتے کے ساتھ کوئی اور کتا پائے تو پھر نہ کھا کیونکہ تو نے اپنے کتے پر بسم اللہ پڑھی تھی نہ کہ دوسرے پر۔‘‘"}],[4270,"شعبی کہتے ہیں کہ عدی بن حاتم رضی اللہ عنہ نہرین میں ہمارے پڑوسی تھے، ہمارے گھر آتے جاتے تھے اور ایک زاہد شخص تھے، ان سے روایت ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا: میں اپنا کتا چھوڑتا ہوں تو میں اپنے کتے کے ساتھ ایک کتا دیکھتا ہوں جس نے شکار پکڑ رکھا ہے مجھے نہیں معلوم ہوتا کہ ان میں سے کس نے پکڑا ہے، آپ نے فرمایا: \"اسے مت کھاؤ، اس لیے کہ تم نے «بسم اللہ» صرف اپنے کتے پر پڑھی تھی، دوسرے پر نہیں\"۔","الألباني: صحيح",{"u2":"حضرت شعبی نے کہا کہ حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ جو کہ نہرین شہر میں ہمارے پڑوسی تھے، ملنے جلنے والے اور اللہ لوگ (زاہد) آدمی تھے، نے فرمایا کہ میں نے نبیٔ اکرم صلی اللہ علیہ وسلم سے پوچھا کہ میں اپنا کتا شکار پر چھوڑتا ہوں، پھر اپنے کتے کے ساتھ کوئی اور کتا پاتا ہوں۔ میں نہیں جانتا کہ ان میں سے کس نے شکار پکڑا ہے؟ آپ نے فرمایا: ’’تو نہ کھا کیونکہ تو نے صرف اپنے کتے پر بسم اللہ پڑھی تھی نہ کہ دوسرے پر۔‘‘"}],[4271,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہماری طرف نکلے تو آپ نے ہمیں ایک ایسی چیز سے روک دیا جو ہمارے لیے نفع بخش تھی اور فرمایا: \"جس کے پاس کوئی زمین ہو تو چاہیئے کہ وہ اس میں کھیتی کرے یا وہ اسے کسی کو دیدے یا اسے (یونہی) چھوڑ دے\"۔\nعدی بن حاتم رضی اللہ عنہ اس سند سے بھی نبی اکرم صلی اللہ علیہ وسلم سے اسی جیسی روایت کرتے ہیں۔","الألباني: صحيح لغيره",{"u2":"حضرت شعبی بیان کرتے ہیں کہ حضرت عدی رضی اللہ تعالٰی عنہ سے اسی قسم کی روایت آتی ہے۔"}],[4272,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: میں اپنا کتا چھوڑتا ہوں؟ آپ نے فرمایا: \"جب تم اپنا کتا چھوڑو اور اس پر«بسم اللہ» پڑھ لو تو اسے (شکار کو) کھاؤ اور اگر اس نے اس (شکار) میں سے کچھ کھایا ہو تو تم اسے نہ کھاؤ، اس لیے کہ اسے اس کتے نے اپنے لیے شکار کیا ہے، اور جب تم اپنے کتے کو چھوڑو پھر اس کے ساتھ اس کے علاوہ (کوئی کتا) پاؤ تو اس شکار کو مت کھاؤ، اس لیے کہ تم نے «بسم اللہ» صرف اپنے کتے پر پڑھی ہے، دوسرے پر نہیں۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ نے فرمایا، میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا کہ میں شکار کے لیے اپنا کتا چھوڑتا ہوں۔ آپ نے فرمایا: ’’جب تو اپنا کتا چھوڑے اور بسم اللہ پڑھے تو اس کا شکار کھا سکتا ہے۔ اگر کتا اس میں سے کچھ کھا لے تو پھر تو نہ کھا کیونکہ اس نے وہ شکار اپنے لیے پکڑا ہے۔ اور جب تو اپنا کتا چھوڑے، پھر اس کے ساتھ کوئی اور کتا پائے تو اس کا شکار نہ کھا کیونکہ تو نے صرف اپنے کتے پر بسم اللہ پڑھی ہے نہ کہ دوسرے پر۔‘‘"}],[4273,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: میں اپنا کتا چھوڑتا ہوں تو اپنے کتے کے ساتھ دوسرے کتے کو پاتا ہوں۔ مجھے نہیں معلوم کہ ان میں سے کس نے شکار کیا؟۔ آپ نے فرمایا: \"اسے (شکار کو) مت کھاؤ، اس لیے کہ تم نے صرف اپنے کتے پر «بسم اللہ» پڑھی تھی، کسی دوسرے (کتے) پر نہیں\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ نے فرمایا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: میں اپنا کتا چھوڑتا ہوں، پھر اپنے کتے کے ساتھ کوئی اور کتا بھی پاتا ہوں۔ میں نہیں جانتا کہ ان میں سے کس نے شکار پکڑا ہے؟ آپ نے فرمایا: ’’نہ کھا کیونکہ تو نے صرف اپنے کتے پر اللہ کا نام لیا ہے دوسرے پر نہیں۔‘‘"}],[4274,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے معراض کے متعلق پوچھا تو آپ نے فرمایا: \"اگر وہ نوک سے مارا جائے تو کھا لو اور اگر وہ آڑے سے مارا جائے تو وہ «موقوذہ» ہے (جو حرام ہے)\"۔ میں نے آپ سے شکاری کتے کے متعلق پوچھا تو آپ نے فرمایا: \"جب تم اپنا کتا چھوڑو اور اس پر اللہ کا نام لے لو تو اسے (شکار کو) کھاؤ\"، میں نے عرض کیا: اگرچہ وہ اسے مار ڈالے؟ آپ نے فرمایا: \"اگرچہ وہ اسے مار ڈالے، ہاں اگر اس میں سے اس نے بھی کھا لیا تو تم مت کھاؤ اور اگر تم اس کے ساتھ اپنے کتے کے علاوہ کوئی کتا دیکھو اور اس نے شکار مار ڈالا ہو تو مت کھاؤ، اس لیے کہ تم نے اللہ کا نام صرف اپنے کتے پر لیا تھا کسی اور کتے پر نہیں\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے معراض کے تیر کے شکار کے بارے میں پوچھا۔ آپ نے فرمایا: ’’جسے تیر نوک کے بل لگا ہو، اسے کھا لے اور جسے عرض کے بل (یا کسی اور طرف سے) لگا ہو، وہ چوٹ سے مرنے والا جانور ہے۔‘‘ میں نے آپ سے شکاری کتے کے بارے میں پوچھا۔ آپ نے فرمایا: ’’جب تو کتا چھوڑے اور اللہ کا نام لے تو اس کا شکار کھا لے۔‘‘ میں نے کہا: اگر وہ قتل کر دے؟ آپ نے فرمایا: ’’خواہ وہ قتل کر دے۔ لیکن اگر وہ اس میں سے کھانے لگے تو پھر نہ کھا۔ اور اگر تو اس کے ساتھ کوئی اور کتا پائے جبکہ جانور ختم ہو چکا ہو تو اسے نہ کھا کیونکہ تو نے اللہ کا نام صرف اپنے کتے پر لیا ہے نہ کہ دوسرے کتے پر۔‘‘"}],[4275,"عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے شکار کے بارے میں پوچھا، تو آپ نے فرمایا: \"جب تم اپنے کتے کو چھوڑو اور اس پر اللہ کا نام لے لو پھر وہ اسے مار ڈالے اور اس نے اس میں سے کچھ نہ کھایا ہو تو تم کھاؤ، اور اگر اس نے اس میں سے کچھ کھایا ہو تو مت کھاؤ اس لیے کہ اس نے اسے اپنے لیے پکڑا ہے نہ کہ تمہارے لیے\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے شکار کے بارے میں پوچھا تو آپ نے فرمایا: ’’جب تو اپنا کتا چھوڑے اور اس پر بسم اللہ پڑھے، پھر وہ قتل بھی کر دے لیکن خود نہ کھائے تو وہ شکار تو کھا لے۔ اور اگر وہ کھانا شروع کر دے تو پھر نہ کھا کیونکہ (اس سے معلوم ہوتا ہے کہ) اس نے شکار اپنے لیے پکڑا ہے نہ کہ تیرے لیے۔‘‘","f2":"’’نہ کہ تیرے لیے‘‘ مقصد یہ ہے کہ وہ کتا سدھایا ہوا نہیں، لہٰذا اس کا شکار جائز نہیں۔ حدیث کا اس قدر تکرار تمام تفصیلات بتانے کے لیے ہے، نیز یہ بتانا بھی مقصود ہے کہ یہ حدیث غریب (ایک آدھ سند والی) نہیں۔"}],[4276,"ام المؤمنین میمونہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے جبرائیل علیہ السلام نے فرمایا: \"لیکن ہم ایسے گھر میں داخل نہیں ہوتے جس میں کتا ہو اور مجسمہ (مورت) ہو\"۔ اس دن جب صبح ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے کتوں کو مار ڈالنے کا حکم دیا، یہاں تک کہ آپ چھوٹے چھوٹے کتوں(پلوں) کو بھی مارنے کا حکم دے رہے تھے ۱؎۔\n§وضاحت\n۱؎: صحیح مسلم کے الفاظ یہ ہیں \" چھوٹے باغوں کے کتوں کو مارنے اور بڑے باغوں کے کتوں کو چھوڑ دینے کا حکم دے رہے تھے، بعد میں یہ حکم منسوخ ہو گیا، اور صرف کالے کتوں کو مارنے کا حکم دیا۔","الألباني: صحيح بلفظ يقتل كلب الحائط الصغير ويترك كلب الحائط الكبير",{"u2":"حضرت میمونہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو حضرت جبریل صلی اللہ علیہ وسلم نے بتایا: … لیکن ہم کسی ایسے گھر میں داخل نہیں ہوتے جس میں کتا یا تصویر ہو۔ اس دن آپ نے صبح کے وقت کتے مارنے کا حکم دیا حتی کہ آپ چھوٹے چھوٹے کتے مارنے کا بھی حکم دیتے تھے۔","f2":"(۱) ضرورت پڑنے پر کتوں کو قتل کرنا جائز ہے۔ (۲) ’’داخل نہیں ہوتے‘‘ یعنی رحمت کے فرشتے ورنہ کاتب، محافظ اور موت کے فرشتے تو ہر گھر میں جاتے ہیں۔ (۳) ’’تصویر‘‘ مراد ذی روح کی تصویر ہے، خواہ وہ آدمی کی ہو یا حیوان کی، مجسم ہو یا منقش و نگار کی صورت میں ہو یا کپڑے پر بنائی گئی ہو یا وہ شمسی تصویر ہو، یہ سب اقسام حرام ہیں۔ صحیح احادیث کی روشنی میں فرشتے ان گھروں میں داخل نہیں ہوتے جن میں تصویریں ہوں۔ ہاں! صرف ان تصویروں کی رخصت ہے جو ناگزیر مقاصد کے لیے ہوں اور ان کے بغیر کوئی چارہ نہ ہو، جیسے پاسپورٹ، شناختی کارڈ یا لائسنس وغیرہ کے لیے انہیں بھی محفوظ یا بند مقام میں رکھا جائے، آویزاں نہ کیا جائے۔ اسی طرح کسی کپڑے پر بنی تصاویر کو پھاڑ کر بستر یا تکیے بنا لیے جائیں اور استعمال میں لایا جائے تو جائز ہے۔ بالفاظ دیگر اگر اس قسم کی صورت میں ان کی پامالی ہوتی ہے تو جائز ہیں۔ (۴) ’’کتے مارنے کا حکم‘‘ رسول اللہ صلی اللہ علیہ وسلم نے ناپسندیدگی کا اظہار کرتے ہوئے آغاز میں کتوں کو قتل کرنے کا حکم دیا۔ یہ حکم عام تھا جو ہر قسم کے کتے کے قتل کو شامل تھا، اس لیے کسی قسم کے کتے کو پالنا جائز نہ تھا، پھر آپ نے کالے کتے کے علاوہ باقی کتوں کے قتل سے منع فرما دیا اور شکاری، کھیتی باڑی اور جانوروں کی حفاظت کے لیے کتے پالنے کی اجازت دے دی۔ ان اقسام کے علاوہ تمام کتوں کو ضرورت کے تحت خصوصاً اس وقت قتل کرنا جائز ہے جب وہ ضرر رساں بھی ہوں۔ و اللہ اعلم۔"}],[4277,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کتوں کو مار ڈالنے کا حکم دیا سوائے ان (کتوں) کے جو اس حکم سے مستثنی (الگ) ہیں ۱؎۔\n§وضاحت\n۱؎: جیسے کھیتی، مویشی اور شکار کے کتے، لیکن بعد میں یہ حکم بھی منسوخ ہو گیا، اور صرف کالے کتوں کو مارنے کا حکم برقرار رہا، لیکن عام کتوں کو بھی بغیر ضرورت پالنے کو ناپسندیدہ عمل قرار دیا گیا :(دیکھئیے اگلی حدیث )۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مستثنیٰ شدہ کتوں کے علاوہ کتوں کو مارنے کا حکم دیا۔","f2":"مستثنیٰ کتوں کا ذکر آئندہ حدیث میں آرہا ہے۔"}],[4278,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اونچی آواز سے کتوں کو مار ڈالنے کا حکم فرماتے سنا، چنانچہ کتے مار دیے جاتے سوائے شکاری کتوں کے یا جو جانوروں کی رکھوالی کرتے ہوتے۔","الألباني: صحيح",{"u2":"حضرت عبد ا اللہ عمر رضی اللہ عنہا بیان فرماتے ہیں کہ میں نے رسول ا اللہ صلی اللہ علیہ وسلم کو بلند آواز کے ساتھ کتوں کے قتل کا حکم دیتے سنا، پھر کتے مارے جاتے تھے مگر شکاری یا جانوروں (اور کھیتوں) کی حفاظت کی خاطر رکھے ہوئے کتوں کو قتل نہیں کیا جاتا تھا۔"}],[4279,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے شکاری، یا جانوروں کی رکھوالی کرنے والے کتوں کے سوا باقی کتوں کو مار ڈالنے کا حکم دیا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہا سے منقول ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے شکاری اور جانوروں (یا کھیتوں) کی حفاظت کے لیے رکھے گئے کتوں کے علاوہ دوسرے کتے مارنے کا حکم دیا۔"}],[4280,"عبداللہ بن مغفل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر یہ بات نہ ہوتی کہ کتے بھی امتوں (مخلوقات) میں سے ایک امت (مخلوق)ہیں ۱؎ تو میں ان سب کو قتل کا ضرور حکم دیتا، اس لیے تم ان میں سے بالکل کالے کتے کو (جس میں کسی اور رنگ کی ذرا بھی ملاوٹ نہ ہو) قتل کرو، اس لیے کہ جن لوگوں نے بھی کھیت، شکار یا جانوروں کی رکھوالی کرنے والے کتوں کے علاوہ کسی کتے کو رکھا تو ان کے اجر میں سے روزانہ ایک قیراط کم ہوتا ہے ۲؎۔\n§وضاحت\n۱؎: یعنی اللہ تعالی کی دیگر مخلوقات کی طرح یہ بھی ایک مخلوق ہیں۔ ۲؎: اس حدیث سے معلوم ہوا کہ چوپایوں کی نگہبانی، زمین جائیداد کی حفاظت اور شکار کی خاطر کتوں کا پالنا درست ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مغفل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ اگر یہ بات نہ ہوتی کہ کتے بھی ایک مخلوق ہیں تو میں ان سب کے قتل کا حکم دیتا۔ اب تم خالص سیاہ کتے کو قتل کرو۔ جو لوگ بھی ایسا کتا رکھیں جو نہ تو کھیتی یا جانوروں کی حفاظت کے لیے ہو اور نہ شکار کے لیے تو ان کی نیکیوں سے ہر روز ایک قیراط کی کمی ہوتی رہے گی۔","f2":"1-کھيتي اور جانوروں کي حفاظت کے ليے اور شکار کرنے کي خاطر کتا رکھا جا سکتا ہے ?اس صورت ميں انسان گناہ گار نہيں ہوگا-اسي طرح اشد ضرورت کي بنا پر گھر کي رکھوالي کے ليے بھي اس کي اجازت ہو سکتي ہے جس نے مذکورہ صورتوں کے علاوہ کتا رکھا تو وہ شخص بہت گناہ گار ہوگا اور نہايت خسارے ميں ہے اس ليے کہ بلا ضرورت کتا رکھنے والے شخص کے نيک اعمال ميں سے روزانہ ايک قيراط وزن کم کرديا جاتا ہےذرا سوچيے کہ يہ کس قدر عظيم نقصان ہے?\n2-انسان کو نيک اعمال کر کےان کي حفاظت کرتے رہنا چاہيے‘اور ايسے برے اعمال سے گريز کرنا چاہيے?جنکي وجہ سے نيک اعمال کي بربادي لازم آتي ہودوسرے لفظوں ميں ہم يہ کہہ سکتے ہيں کہ زيادہ سے زيادہ نيک اعمال کرنے اور برے اعمال سے بچنے کي ترغيب بھي اس حديث ميں معلوم ہوتي ہے?\n3-اس حديث ميں اللہ تعالي? کے اس عظيم لطف کي طرف بھي اشارہ ہے جو وہ اپني معزز مخلوق انسان پر فرماتا ہے‘يعني جس چيز سے لوگوں کو کسي قسم کا فائدہ ہو سکتا ہ اسے ان کے ليے مباح اور جائز فرما دينا?\n4?اس سے يہ بھي معلوم ہوا کہ رسول ا? ? نے اپني امت کے ليے ان کي معاش و معاد کے تمام امور، جن کے وہ محتاج اور ضرورت مند تھے، بيان فرما ديے\n5? اس حديث مبارکہ سے يہ اصول اور قاعدہ معلوم ہوا کہ نفع نقصان دونوں کي حامل چيز ميں اگر مصلحت راجح ہو تو اسے ترجيح حاصل ہوگي، يعني مصلحتِ راجحہ کا لحاظ رکھا جائے گا? تفصيلہ اس اجمال کي يہ ہے کہ کتے ميں نفع و نقصان کي دونوں صفات پائي جاتي ہيں? عام طور پر اس ميں نقصان و فساد والي صفت کا غلبہ ہوتا ہے، اس ليے کتا رکھنے سے احتراز کا حکم ديا گيا ہے، تا ہم جہاں اس لوگوں کو فائدہ پہنچنا راجح تھا، وہاں عام حکم سے استشنا فرما ديا گيا\n6?ايک مخلوق‘‘ عربي يعني امتوں ميں سے ايک امت، کے الفاظ ہيں? ا? تعالي? نے کسي مخلوق کو بے فائدہ نہيں بنايا، خواہ وقتي طور پر کسي کے ليے نقصان دہ ثانت ہو\nمگر مجموعي طور پر ہر مخلوق انسان کے ليے بلا واسطہ با لواسبہ مفيد ہے، مثلاََ: کتے حفاظت کاکام ديتے ہيں? شکار بھي کرتے ہيں? بعض ايسے مقامات ہوتے ہيں جہاں کتوں کے\nعلاوہ شکار کيا ہي نہيں جا سکتا? اور بھي بہت سے فوائد ہيں جن کو ا? تعالي? ہي جانتا ہے جو خالق ورازق ہے، اس ليے کسي بھي مخلوق کو مکمل طور پر ختم کر دينا حکمت الہ?يہ کے منافي ہے، نيز يہ انساني بقا کے بھي خلاف ہے، لہ?ذا صرف موذي کو ختم کيا جائے،\nمثلاََ: باو? لا کتا، بہت کاٹنے والا کتايا ا?وارہ اور فالتو کتا وغيرہ?\n7?’’خالص سياہ کتا‘‘ يہ بہت ڈراو?نا ہوتا ہے? ايک حديث ميں يوں بيان کيا گيا ہے کہ’’کالا کتا شيطان کہا جاسکتا ہے? جس طرح برے اور شرارتي انسان کو شيطان کہہ ديا جاتا ہے، اسي طرح ڈراو?نے اور موذي کتے کو بھي شيطان کہا جا سکتا ہے? شيطان کسي کا نام نہيں بلکہ يہ وصف ہے? جس ميں بھي پايا جائے، وہ شيطان ہے?’’\n8?ايک قيراط‘‘ ايک قيراط سے مراد کيا ہے؟ اس ميں تفصيل ہے اور وہ اس طرح کہ قيراط کا اطلاق دو طرح کے وزن پر ہوتا تھا? ايک انتہائي معمولي وزن پر اور دوسرے انتہائي غير معمولي وزن پر? معمولي وزن پر اس طرح کہ ايک دينار بيسک قيراط کا ہوتا ہے، اور دينار ساڑھے چار ماشے، يعني ???.? گرام کا ہوتا ہے? گويا ايک قيراط کا وزن تقربياََ ??? ملي گرام بنتا ہے? دوسري قسم کا قيراط وہ ہے جسے رسول اللہ ? نے احد پہاڑ کے برابر قرار ديا ہے? اس کي مقدار کو اللہ تعالي? ہي جانتا ہے? يہاں اس حديث ميں قيراط سے مراد کون سا قيراط ہے؟ تو اس کي بابت اہل علم کي ا?راء مختلف ہيں? بعض اہل علم نے اس معمولي وزن مراد ليا ہے جبکہ بعضج نے غير معمولي وزن? ہمارا رجحان پہلي رائے کي طرف ہے? يہاں اس حديث ميں قيراط سے مراد ليا ہے جبکہ بعض نے غير معمولي وزن? ہمارا رجحان پہلي رائے کي طرف ہے? اس کي ايک وجہ تو يہ ہے کہ شريعت مطہرہ کا مزاج نرمي کرنا ہے، سختي اور شدت نہيں اور نرمي پہلي صورت ميں ہے نہ کہ دوسري ميں? دوسري وجہ يہ ہے کہ رسول اللہ ? نے مطلقاََ قيراط فرمايا ہے، کسي قسم کا تعين نہيں کيا، يہ تو معلوم بات ہے کہ اللہ تعالي? کا فضل و کرم اور اس کي رحمت، اس کے غصے اور سزا سے کہيں زيادہ وسيع ہے، اس ليے سزا ميں تخفيقف اور فضل ميں تکثير والے ضابطے کي بنياد پر بھي يہي بات راجح معلوم ہوتي ہے کہ قيراط سے مراد پہلي صورت ہوگي اور يہي ارحم الراحمين کے فضل و کرم اور اس کي رحمت و مہرباني کا تقاضا ہے?\nاس سب کچھ کے باوجود حتمي اور يقيني طور پر صرف ايک بات کہي جا سکتي ہے کہ اللہ ہي کے علم ميں ہے کہ اس حديث ميں قيراط سے مراد کونسا قيراط ہے؟ بہر حال ايک مومن شخص کو اس سے بھي بچنا چاہيے کہ وہ کسي ايسے کام کا مرتکب ہو کہ جس کي وجہ سے اس کے نيک اعمال ميں سے زرہ بھر کمي کر دي جائے?\n9’’کمي ہوتي رہے گي‘‘ يعني ہر روز کي ہوئي نيکيوں ميں سے اتني مقدار ضائع ہوتي رہے گي کيونکہ ضرورتک کے بغير کتا گھر والوں کے ليے بھي نقصان دہ ہے اور گزرنے والوں کے ليے بھي? مزيد بر ا?ں يہ کہ کتے ميں باو?لا ہونے کے امکانات بھي ہوتے ہيں? ايسي صورت ميں وہ لوگوں کے ليے خوف ناک اذيت اور موت کا سبب بھي بنے گا? بہر حال بے فائدہ کتا رکھنے والے کے ليے يہ حديث بہت بڑي و عيد ہے"}],[4281,"علی بن ابی طالب رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ملائکہ (فرشتے) ۱؎ اس گھر میں داخل نہیں ہوتے جس میں تصویر (مجسمہ) ہو یا کتا ہو یا جنبی (ناپاک شخص) ہو\" ۲؎۔\n§وضاحت\n۱؎: \" فرشتوں \" سے مراد رحمت کے فرشتے ہیں نہ کہ حفاظت کرنے والے فرشتے، کیونکہ حفاظت کرنے والے فرشتوں کا کسی انسان یا انسان کے رہنے والی جگہ سے دور رہنا ممکن نہیں۔ ۲؎: حدیث میں صحت و ثبوت ہونے کے اعتبار سے \" جنبی \" کا لفظ \" منکر \" یعنی ضعیف ہے اور \" کتا \" سے مراد شکار، کھیتی یا جانوروں کی حفاظت کے مقصد سے پالے جانے والے کتوں کے علاوہ کتے مراد ہیں، اور \" تصویر \" سے وہ تصویریں مراد ہیں جس کا سایہ ہوتا ہے، یعنی ہاتھ سے بنائے ہوئے مجسمے، یا دیواروں پر لٹکائی جانے والی کاغذ پر بنی ہوئی تصویریں ہیں، کرنسی نوٹوں، کتابوں اور رسائل و جرائد میں بنی ہوئی تصویروں سے بچنا اس زمانہ میں بڑا مشکل بلکہ محال ہے۔","الألباني: صحيح ق دون قوله ولا جنب",{"u2":"حضرت علی بن ابی طالب رضی اللہ تعالٰی عنہ سے روادیت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’فرشتے اس گھر میں داخل نہیں ہوتے جس میں تصویر یا کتا یا جنبی ہو۔‘‘","f2":"بلا ضرورت جنبی رہنا بھی قبیح بات ہے۔ جب جنابت طاری ہو جائے تو فوراََ نہانا چاہیے۔ زیادہ سے زیادہ تاخیر ہو تو آئندہ فرض نماز تک لازمی نہا لینا چاہیے۔ اس سے زائد تا خیر کرنا گناہ کا موجب ہے۔ اصل یہی ہے کہ فوراََ نہائے شرعی اور طبی اعتبار سے یہی بہتر ہے۔"}],[4282,"ابوطلحہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایسے گھر میں فرشتے داخل نہیں ہوتے جس میں کتے، یا تصاویر (مجسمے) ہوں\"۔","الألباني: صحيح",{"u2":"حضرت ابو طلحہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’فرشتے اس گھر میں داخل نہیں ہوتے جس میں کتایا تصویر ہو۔‘‘"}],[4283,"ام المؤمنین میمونہ رضی اللہ عنہا سے روایت ہے کہ ایک روز صبح کو رسول اللہ صلی اللہ علیہ وسلم بہت غمگین اور اداس اٹھے، میمونہ رضی اللہ عنہا نے آپ سے عرض کیا: اللہ کے رسول! مجھے آپ کی حالت آج کچھ بدلی بدلی عجیب و غریب لگ رہی ہے، آپ نے فرمایا: \"جبرائیل نے مجھ سے رات میں ملنے کا وعدہ کیا تھا، لیکن وہ ملنے نہیں آئے، اللہ کی قسم! انہوں نے کبھی وعدہ خلافی نہیں کی\"، آپ اس دن اسی طرح (غمزدہ) رہے، پھر آپ کو کتے کے ایک بچے (پلے) کا خیال آیا جو ہمارے تخت کے نیچے تھا، آپ نے حکم دیا تو اسے نکالا گیا پھر آپ نے اپنے ہاتھ میں پانی لے کر اس سے اس جگہ پر چھینٹے مارے، پھر جب شام ہوئی تو آپ کو جبرائیل علیہ السلام ملے، رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"آپ نے مجھ سے گزشتہ رات ملنے کا وعدہ کیا تھا؟\" انہوں نے فرمایا: جی ہاں، لیکن ہم ایسے گھر میں داخل نہیں ہوتے جہاں کتا ہو یا تصویر (مجسمہ) ہو، پھر جب صبح ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے کتوں کو مار ڈالنے کا حکم دیا۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا سے روایت ہے کہ مجھے نبی اکرم صلی اللہ علیہ وسلم کی زوجہ محترمہ حضرت میمونہ رضی اللہ عنہا نے بیان فرمایا کہ ایک رسول اللہ صلی اللہ علیہ وسلم بڑے افسردہ سے تھے۔ میں نے کہا: اے اللہ کے رسول! آج صبح سے آپ کی حالت عجیب سی محسوس ہو رہی ہے۔ آپ نے فرمایا:’’جبریل صلی اللہ علیہ وسلم نے مجھ سے آج رات ملنے کا وعدہ کیا تھا لیکن وہ ملے نہیں۔ اللہ کی قسم! انھوں نے کبھی مجھ سے وعدہ خلافی نہیں کی۔‘‘ آپ سارا دن اسی طرح رہے، پھر آپ کو خیال آیا کہ ہماری بستروں والی چار پائی کے نیچے کتے کا ایک پلا بیٹھا ہے۔ آپ نے حکم دیا اور اسے نکال دیا گیا، پھر آپ نے اپنے دست مبارک سے وہاں کچھ پانی چھڑک دیا۔ جب شام ہوئی تو جبریل صلی اللہ علیہ وسلم آپ سے ملے۔ رسول اللہ صلی اللہ علیہ وسلم نے انھیں فرمایا:’’آپ نے تو مجھ سے وعدہ کیا تھا کہ گزشتہ رات مجھ سے ملیں گے؟‘‘ وہ کہنے لگے: ہاں، لیکن ہم کسی ایسے گھر میں داخل نہیں ہوتے جس میں کتایا تصور ہو۔ اس دن سے رسول اللہ صلی اللہ علیہ وسلم نے کتوں کے قتل کا حکم دے دیا۔","f2":"1) مسئلہ واضح ہے کہ رحمت کے فرشتے اس گھر میں داخل نہیں ہوتے جس میں کتا ہو۔ لیکن یہ بات ضرور یاد رہنی چاہیے کہ جس گھر میں بوجہ ضرورت کتا رکھا جائے وہ اس سے متشنی ہے کوینکہ اس کی اجازت شارع علیہ السلام نے خود دی ہے۔ اور آپ علیہ السلام کا ہر کام منشائے الٰہی کے مطابق ہی ہوتا ہے۔2) اس حدیث مبارکہ سے وعدہ وفا کرنے کی اہمیت بھی معلوم ہوتی ہے۔ وعدہ وفائی ضروری ہے۔ جس سے وعدہ کیا جاتا ہے وہ وعدے کا منتظر رہتا ہے۔ اندازہ لگایئے ایک بار جبریل امین علیہ السلام وعدے کے مطابق نہیں آئے تو رسول اللہ صلی اللہ علیہ وسلم سارا دن پریشان رہے۔ 3)معلوم ہوا فرشتے بھی قوانین الٰہی کے پابند ہیں، نیز انبیاء کے لیے بھی قانون بدلا نہیں جاتا رونہ رسول اکرم صلی اللہ علیہ وسلم کے لیے قانون بدل دیا جاتا۔"}],[4284,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کوئی کتا پالا تو روزانہ اس کے اجر سے دو قیراط اجر کم ہو گا، سوائے شکاری یا جانوروں کی رکھوالی کرنے والے کتے کے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہا سے وایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جو شخص کتا رکھے، اس کے ثواب سے ہر روز دو قیراط کم کیے جائیں گے، الا یہ کہ وہ شکاری ہو یا جانوروں کی حفاظت کے لیے رکھا گیا ہو۔‘‘","f2":"یہ تفصیلی بحث:۴۲۸۵ میں گزر چکی ہے، البتہ وہاں ای قیراط کا ذکر تھا یہاں دو قیراط کا ذکر ہے ممکن ہے کتے، کتے فرق ہو، یعنی جو زیادہ نقصان دہ ہو، وہاں دو قیراط کی کمی ہوتی ہے اور کم نقصان دہ پر ایک قیراط کی۔ یا یہ بھی ہوسکتا ہے کہ اس کا سبب جگہ کا فرق ہو، یعنی شہری آبادی میں دو قیراط اور باد یہ اور کھلی جگہ ایک قیراط وغیرہ۔ بعض لوگوں نے اس فرق کا سبب مدینہ اور غیر مدینہ میں کتا رکھنے کو قرار دیا ہے۔ واللہ اعلم"}],[4285,"سائب بن یزید رضی اللہ عنہ کہتے ہیں کہ سفیان بن ابی زہیر شنائی رضی اللہ عنہ ہمارے پاس آئے اور کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"جس نے ایسا کتا پالا جو نہ کھیت کی حفاظت کرے اور نہ جانوروں کی تو اس کے عمل میں سے ہر روز ایک قیراط کم ہو گا\"، میں نے عرض کیا: سفیان! کیا آپ نے اسے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے؟ انہوں نے کہا: جی ہاں، اس مسجد کے رب کی قسم! ۱؎۔\n§وضاحت\n۱؎: ایک قیراط اور دو قیراط کا اختلاف شاید زمان و مکان کے اعتبار سے ہے، چنانچہ ابتداء میں کتوں کے قتل کا حکم ہوا پھر یہ حکم منسوخ ہو گیا اور ثواب میں سے دو قیراط کی کمی کی خبر دی گئی پھر اس میں تخفیف ہوئی اور ایک قیراط کی خبر دی گئی :(واللہ اعلم )۔","الألباني: صحيح",{"u2":"حضرت سائب بن یزید بیان کرتے ہیں کہ ہمارے پاس سفیان بن ابوز ہیر شنائی رضی اللہ تعالٰی عنہ آئے اور فرمانے لگے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جس نے ایسا کتا رکھا جو نہ کھیتی کی حفاظت کرتا ہو اور نہ جانوروں کی(اور نہ وہ شکاری ہو) تو اس کے عمل سے ہر روز ایک قیراط ثواب کم کیا جائے گا۔‘‘ میں نے کہا: اے سفیان! کیا آپ نے یہ فرمان رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے؟ انھوں نے فرمایا: ہاں‘ اس مسجد کے رب کی قسم!"}],[4286,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے شکار کرنے والے کتے یا جانوروں کی دیکھ بھال کرنے والے کتے کے سوا کوئی کتا پالا تو روزانہ اس کا اجر دو قیراط کم ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جو شخص شکار یا جانوروں کے لیے کتے کے علاوہ کتا رکھے تو اس کے ثواب سے ہر روز دو قیراط کم جائیں گے۔‘‘"}],[4287,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے شکاری کتے یا جانوروں کی رکھوالی کرنے والے کتے کے سوا کوئی کتا پالا تو روزانہ اس کا اجر دو قیراط کم ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت سالم سے والد متحرم(حضرت ابن عمر رضی اللہ عنہا) سے منقول سے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’جس شخص نے شکار یا جانوروں(اور کھیتی) کے کتے کے علاوہ کتا رکھا، اس کے ثواب سے ہر روز وہ قیراط کم کیے جائیں گے۔‘‘"}],[4288,"عبداللہ بن مغفل رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے شکاری کتے، یا جانوروں یا کھیت کی رکھوالی کرنے والے کتے کے سوا کوئی کتا پالا تو روزانہ اس کا اجر ایک قیراط کم ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن مغفل رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ جس شخص نے کتا رکھا جو نہ شکاری ہو اور نہ جانوروں یا کھیتی کی حفاظت کے لیے ہو تو اس کے ثواب سے ہر روز ایک قیراط کی کمی ہوتی رہے گی۔‘‘","f2":"ممکن ہے نیکیوں میں کمی یا تو لوگوں کی تکلیف کی بنا پر ہو یا فرشتوں کے گھر میں داخل نہ ہونے کی وجہ سے کیونکہ فرشتوں کی آمد سے اہل خانہ میں نیکیوں کا رجحان پیدا ہوتا ہے۔ یا شرعی حکم نافرمانی کی وجہ سے، یا اس لیے کہ وہ کتا گھر کے برتنوںمیں منہ مارتا رہے اور صاحب خانہ کو پتا نہ چلے وغیرہ۔ المختصر اس کی وجہ اللہ ہی بہتر جانتا ہے کوئی قطعی بات نہیں کہی جا سکتی۔"}],[4289,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے شکاری کتے یا کھیتی اور جانوروں کی رکھوالی کرنے والے کتے کے سوا کوئی کتا پالا تو اس کے عمل (اجر) میں سے روزانہ ایک قیراط کم ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جس شخص نے شکار یا کھیتی یا جانوروں کے کتے کے علاوہ کوئی کتار رکھا، اس کے اعمال صالحہ سے ہر روز ایک قیراط کی کمی ہوتی رہے گی۔‘‘"}],[4290,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی ایسے کتے کو پالا جو نہ تو شکاری ہو نہ جانوروں کی نگرانی کے لیے ہو اور نہ ہی زمین (کھیتی) کی رکھوالی کے لیے، تو روزانہ اس کا اجر دو قیراط کم ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت ابو ہر یرہ رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جس شخص نے جانوروں کی حفاظت یا شکار کرنے والے کتے کے علاوہ کتا رکھا، اس کے نیک اعمال سے ہر روز ایک قیراط کی کمی کی جائے گی۔‘"}],[4291,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے جانوروں کی رکھوالی کرنے والے کتے یا شکاری کتے کے علاوہ کوئی کتا پالا تو روزانہ اس کے عمل (اجر) میں سے ایک قیراط کم ہو گا\"، عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں: ابوہریرہ رضی اللہ عنہ نے یہ بھی کہا: \"یا کھیتی کا کتا\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جس شخص نے جانوروں کی حفاظت یا شکار کرنے والے کتے کے علاوہ کتا رکھا، اس کے نیک اعمال سے ہر روز ایک قیراط کی کمی کی جائے گی۔‘‘ حضرت عبد اللہ رضی اللہ تعالٰی عنہ نے فرمایا کہ حضرت ابو ہر یرہ رضی اللہ تعالٰی عنہ نے یہ الفاظ بھی بیان فرمائے کہ کھیتی کی حفاظت والا کتا بھی رکھ کتا بھی رکھ سکتا ہے۔","f2":"1۔شکار کے کتے سے مرادووہ کتا ہے جو عملاََ شکار کے لیے استعمال ہو، یعنی اس کے ساتھ شکار کیا جائے نہ کہ صرف شکاری نسل سے ہو جیسا کہ آج کل سمجھا جاتا ہے۔ شرعاََ ہر وہ کتا شکاری ہو سکتا ہے جسے شکار کی بیت و تعلیم دی جائے۔ یہ بات بہر صورت یاد رہنی چاہیے کہ جس شکار کی تربیت دے کر کتے کو سدھانا ہے، وہ شوفیہ خنزیر وغیرہ کا شکار نہیں بلکہ حلال جانوروں کا شکار ہے۔ 2۔دوڑ کے لیے کتا رکھنا بھی گناہ ہے کیونکہ اللہ تعالیٰ نے کتے کو دوڑنے کے لیے پیدا نہیں کیا۔ کتے کے درڑنے سے بنی نوع انسان کو کوئی فائدہ بھی حاصل نہیں ہوتا۔ 3۔کھیتی کی حفاظت کرنے والا کتا کھیت میں ہی رہنا چاہیے۔ اسی طرح جانوروں کی حفاظت کرنے والا کتا بھی جانوروں ہی میں رہے۔ گھر میں ان کوئی کام نہیں۔ شکار والا کتا بھی ممکن حد تک گھر سے باہر ہی رکھا جائے تو بہتر ہے۔"}],[4292,"ابومسعود عقبہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کتے کی قیمت ۱؎ زانیہ عورت کی کمائی ۲؎ اور کاہن کی اجرت ۳؎ سے منع فرمایا ہے۔\n§وضاحت\n۱؎: کتا نجس و ناپاک جانور ہے اس لیے اس سے حاصل ہونے والی قیمت بھی ناپاک ہو گی، اس کی نجاست کا حال یہ ہے کہ شریعت نے اس برتن کو جس میں کتا منہ ڈال دے سات مرتبہ دھونے کا حکم دیا ہے جس میں پہلی مرتبہ مٹی سے دھونا بھی شامل ہے، اسی سبب سے کتے کی خرید و فروخت اور اس سے فائدہ اٹھانا منع ہے الا یہ کہ کسی اشد ضرورت مثلاً گھر، جائیداد اور جانوروں کی رکھوالی کے لیے ہو۔ مگر ایسے کتوں کی بھی تجارت ناپسندیدہ ہے، اور جس حدیث میں اس کی رخصت کی بات آئی ہے اس کی صحت میں سخت اختلاف ہے، :(جیسے حدیث نمبر ۴۳۰۰ ) ۲؎ چونکہ زنا بڑے گناہوں اور فحش کاموں میں سے ہے اس لیے اس سے حاصل ہونے والی اجرت بھی ناپاک اور حرام ہے اس میں کوئی فرق نہیں کہ زانیہ لونڈی ہو یا آزاد عورت۔ ۳؎: علم غیب رب العالمین کے لیے خاص ہے اس کا دعوی کرنا بڑا گناہ ہے اسی طرح اس دعوی کی آڑ میں کاہن اور نجومی باطل طریقے سے لوگوں سے جو مال حاصل کرتے ہیں وہ بھی حرام ہے۔","الألباني: صحيح",{"u2":"حضرت ابو مسعود عقبہ رضی اللہ تعالٰی عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے کتے کی قیمت، زانیہ کی اجرت اور کاہن کی شیر ینی(نذرو نیاز) سے منع فرمایا ہے۔","f2":"1۔جمہور اہل علم کے نزدیک کتے کی خریدو فروخت منع ہے، خواہ اس کا رکھنا جائز ہو یا ناجائز، اور یہی بات صحیح ہے کیونکہ کتا خریدنے یا بیچنے والی چیز نہیں کہ اس کو کمائی کا ذریعہ بنایا جائے، البتہ امام ابو حنیف رحمہ اللہ کتے کی خریدو فروخت کو جائز سمجھتے ہیں کیونکہ اس سے فائدہ اٹھانا جائز ہے۔ چونکہ ہر کتے سے شکار اور حفاظت کا کام لیا جاسکتا ہے، لہٰذا ہر کتے کی خریدو فروخت جائز ہے، عام کی نہیں۔ امام ابوحنیفہ رحمہ اللہ کی بات صریح حدیث کے مقابلے میں قابل تسلیم نہیں۔ وہ اس حدیث کو اس دور سے متعلق بتاتے ہیں جب آپ نے کتے مارنے کا حکم دیا تھا۔ گویا یہ وقتی پابندی تھی۔ لیکن یہ صرف ایک احتمال ہے جس کی کوئی دلیل نہیں۔2۔’’زانیہ کی اجرت‘‘ چونکہ زنا جرم ہے، لہٰذا اس کی اجرت بھی حرام ہے اور یہ متفقہ بات ہے۔3۔’’کاہن کی نذر ونیاز‘‘کاہن سے مراد غیب کی خبریں بتانے والا ہے۔ ان لوگوں کے جنات وشیا طین سے روابط ہوتے ہیں، لہٰذا یہ لوگوں کو گمراہ کرتے ہیں۔ چونکہ یہ کام منع ہے، اس لیے اس پر ملنے چیز بھی منع ہے۔ شریعت اسلامیہ میں نہ کسی سے غیب کی خبریں پوچھنا جائز ہے اور نہ بتانا کیونکہ جنات وشیا طین ایک سچ کے ساتھ کئی جھوٹ بھی لولتے ہیں، لہٰذا ان کی بات کا یقین نہیں کیا جا سکتا۔"}],[4293,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کتے کی قیمت حلال نہیں، نہ ہی کاہن کی اجرت، اور نہ ہی زانیہ عورت کی کمائی\"۔","الألباني: صحيح",{"u2":"حضرت ابوہر یرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’کتے کی قیمت، کاہن کی نذرو نیاز اور زانیہ کی اجرت حلال نہیں۔‘‘"}],[4294,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بری کمائی زانیہ عورت کی کمائی، کتے کی قیمت، اور پچھنا لگانے کی اجرت ہے\" ۱؎۔\n§وضاحت\n۱؎: «کسب الحجام» کے سلسلہ میں «شرالکسب» کا لفظ حرام ہونے کے مفہوم میں نہیں ہے بلکہ گھٹیا اور غیر شریفانہ ہونے کے معنی میں ہے، رسول اللہ صلی اللہ علیہ وسلم نے محیصہ رضی اللہ عنہ کو یہ حکم دیا کہ پچھنا لگانے کی اجرت سے اپنے اونٹ اور غلام کو فائدہ پہنچاؤ، نیز آپ صلی اللہ علیہ وسلم نے بذات خود پچھنا لگوایا اور لگانے والے کو اس کی اجرت بھی دی، پس پچھنا لگانے والے کی کمائی کے متعلق «شر» کا لفظ ایسے ہی ہے جیسے آپ نے «ثوم و بصل»:(لہسن، پیاز ) کو خبیث کہا جب کہ ان دونوں کا استعمال حرام نہیں ہے، اسی طرح حجام کی کمائی بھی حرام نہیں ہے یہ اور بات ہے کہ یہ پیشہ گھٹیا اور غیر شریفانہ ہے۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’زانیہ کی اجرت، کتے کی قیمت اور جحام کی کمائی بہت بری کمائی ہے،‘‘","f2":"’’جحام ‘‘ اس دور میں سنگی لگانے والے جحام کہتے تھے۔ چونکہ سنگی لگانے والے کو گندا خون چوسنا پڑتا ہے، اس لیے آپ نے اس پیشے کو کمائی کے لیے مناسب خیال نہیں فرمایا، کمائی کے لیے کوئی اچھا پیشہ اختیار کیا جائے۔ ہاں، ہمدردی کے طور پر سنگی لگائے تو مفت لگائے تا کہ ثواب حاصل ہو۔ جمہور اہل علم کے نزدیک جحام کی اجرت مکر دہ تنز یہی ہے، حرام نہیں کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے خود سنگی لگانے والے کو اجرت دی ہے۔ اگر حرام ہوتی تو آپ نہ دیتے۔ کسی مسئلے کا فیصلہ کرتے وقت متعلقہ تمام روایات کو دیکھنا ضروری ہے نہ کسی ایک کو دیکھ کر حکم لگانا درست ہے۔"}],[4295,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بلی ۱؎ اور کتے کی قیمت لینے سے منع فرمایا، سوائے شکاری کتے کے۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: حماد بن سلمہ سے حجاج (حجاج بن محمد) نے جو حدیث روایت کی ہے وہ صحیح نہیں ہے ۲؎۔\n§وضاحت\n۱؎: چونکہ بلی سے کوئی ایسا فائدہ جو مقصود ہو حاصل ہونے والا نہیں اسی لیے نبی اکرم صلی اللہ علیہ وسلم نے اس کی قیمت لینے سے منع فرمایا ہے اور یہی اس کے حرام ہونے کی علت اور اس کا سبب ہے۔ ۲؎: اس کے راوی \" ابوالزبیر \" مدلس ہیں اور روایت عنعنہ سے ہے، اور یہ لفظ مسلم کی روایت میں ہے بھی نہیں ہے، انہیں اسباب و وجوہ سے بہت سے ائمہ نے اس حدیث کو ضعیف قرار دیا ہے، تفصیل کے لیے دیکھئیے فتح الباری :(۴/۴۲۷ ) اور التعلیقات السلفیہ۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بلی اور کتے کی قیمت سے منع فرمایا ہے مگر شکاری کتے کی قیمت لی جاسکتی ہے۔\nابو عبد الرحمن(امام نسائی رحمہ اللہ) بیان کرتے ہیں کہ جحاج کی حماد بن سلمہ سے مروی(بیان کردہ) روایت صحیح نہیں۔","f2":"امام صاحب کی بات کی تائید دوسرے محدثین نے بھی کی ہے کیونکہ یہ روایت شکاری کتے کے استشنا کے بغیر صحیح سندوں کے ساتھ آتی ہے۔ صحیح مسلم میں یہ روایت موجود ہے مگر شکاری کتے کا استشنا مذکور نہیں۔ اس روایت کے الفاظ ہیں:’’بلاشبہ رسول اللہ صلی اللہ علیہ وسلم نے کتے کی قیمت، زانیہ کیا اجرت اور کاہن کی شیر ینی(نذرو نیاز) سے منع کیا ہے۔‘‘ صحیح مسلم‘المساقاۃ‘باب تحریم ثمن الکلب.....حدیث:1567)"}],[4296,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر کہا: اللہ کے رسول! میرے پاس کچھ شکاری کتے ہیں، آپ نے فرمایا: \"تمہارے لیے تمہارے کتے جو پکڑ کر لائیں اسے کھاؤ\"۔ میں نے عرض کیا: اگرچہ وہ اسے قتل کر ڈالیں؟ آپ نے فرمایا: \"اگرچہ قتل کر ڈالیں\"، اس نے کہا: (میں اپنے تیر کمان سے فائدہ اٹھاتا ہوں لہٰذا) مجھے تیر کمان کے سلسلے میں بتائیے، آپ نے فرمایا: \"جو شکار تمہیں تیر سے ملے تو اسے کھاؤ\"، اس نے کہا: اگر وہ (شکار تیر کھا کر) غائب ہو جائے؟ آپ نے فرمایا: \"اگرچہ وہ غائب ہو جائے، جب تک کہ تم اس میں اپنے تیر کے علاوہ کسی چیز کا نشان نہ پاؤ یا اس میں بدبو نہ پیدا ہوئی ہو\" ۱؎۔ ابن سواء کہتے ہیں: میں نے اسے ابو مالک عبیداللہ بن اخنس سے سنا ہے وہ اسے بسند عمرو بن شعیب عن ابیہ عن جدہ عبداللہ بن عمرو بن العاص رضی اللہ عنہما عن النبی کریم صلی اللہ علیہ وسلم روایت کرتے ہیں۔\n§وضاحت\n۱؎: اس حدیث سے مؤلف نے باب پر اس طرح استدلال کیا ہے کہ جب شکار کے لیے کتے استعمال کرنے کی رخصت ہے تو بھر اس کی خرید و فروخت کی بھی رخصت ہے، لیکن جمہور اس استدلال کے خلاف ہیں، پچھلی احادیث میں صراحت ہے کہ کتے کی قیمت لینی دینی حرام ہے۔","الألباني: حسن صحيح",{"u2":"حضرت عمر و بن شعیب کے پردادا متحرم(حضرت عبد اللہ بن عمر و بن عاص رضی اللہ عنہا کے پاس آیا اور کہنے لگا: اے اللہ کے رسول! میرے پاس سدھائے ہوئے کتے ہیں۔ مجھے ان کے بارے میں بتایئے؟ آپ نے فرمایا:’’جو جانور وہ تیرے لیے پکڑ رکھیں، تو کھا سکتا ہے،‘‘ میں نے کہا: اگر چہ وہ اسے قتل کر دیں؟ آپ نے فرمایا:’خواہ وہ اسے قتل کر دیں۔‘‘ اس آدمی نے کہا: مجھے میرے تیر کمان کے بارے میں بتایئے؟ آپ نے فرمایا:’’تیرا تیر جو کچھ شکار کرے، وہ تو کھا سکتا ہے۔‘‘ اس نے کہا: اگرچہ وہ شکار مجھ سے غائب ہو جائے۔ جب تک تو اس میں اپنے تیر کے علاوہ کسی اور تیر کا نشان نہ پائے یا وہ بدبودار نہ ہوجائے۔‘‘\nابن سواء نے کہا: میں نے یہ حدیث(جس طرح سعید کے واسطے سے سنی ہے، اسی طرح واسطے کے بغیر، براہ راست بھی) ابو مالک عبید اللہ بن اخنس سے سنی ہے۔","f2":"1۔سکھلائے اور سدھائے ہوئے کتے سے شکار کرنا درست ہے۔2۔ اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوا کہ جو شکار کتے نے مالک کے لیے پکڑا ہو اور اسے مار ڈالا ہو لیکن خود اس میں سے نہ کھایا ہو تو شکاری کتے کا مارا ہوا جانور کھایاجا سکتا ہے اگرچہ اسے ذبح نہ کیا جا سکا ہو بلکہ وہ ذبح کیے جانے سے پہلے ہی مر گیا ہو، البتہ اس میں یہ شرط ضروری ہے کہ کتا چھوڑتے وقت بسم اللہ پڑھی گئی ہو۔3۔ یہ حدیث تیر کے ساتھ کیے ہوئے شکار اور اس علاوہ آلات شکار کے ذریعے سے کیے ہوئے شکار حلت پر دلالت کرتی ہے بشر طیکہ شکار اس آلہ شکار کی دھار سے قتل ہوا ہو نہ کہ اس چوٹ سے۔ مزید بر آں یہ بھی ضروری ہے کہ تیر وغیرہ چلاتے وقت اللہ کا نام بھی لیا گیا ہو جیسا کہ پہلے بھی اس کا ذکر کیا جاچکا ہے۔4۔ اگر شکاری شخص اپنے زخمی شکار کو چند دن بعد مردہ حالت میں پاتا ہے جبکہ اس میں ابھی بو پیدا نہ ہوئی ہو تو وہ اسے کھا سکتا ہے، البتہ اس کے لیے یہ ضروری ہے کہ اس شکار کو کسی اور شکار کو کسی اور شکاری نے ذخمی نہ کیا ہو۔ یہ اس لیے کہ اس صورت میں یہ بات معلوم ہی نہیں ہو سکتی کہ دوسرے شکاری نے تیر وغیرہ چھوڑتے وقت اللہ کانام لیا تھا یا نہیں‘لہذا ایسے شکار کو کھانا جو مشکوک ہو کس طرح جائز ہو سکتاہے؟5۔غائب ہو جائے‘‘یعنی تیر کھانے کے بعد وہ جانور بھاگ جائے اور پھر کسی اور جگہ بے جان لے تو کیا اسے کھایا سکتا ہے۔؟6۔’’بدبو دار نہ ہو جائے‘‘ظاہر الفاظ سٰے معلوم ہوتا ہےکہ اسے کھایانہیں جاسکتا حالانکہ بدبو کسی جانور یا گوشت کو حرام نہیں کرتی لیکن چونکہ بدبودار چیز میں طبی طور پر مفاسد پیدا ہو جاتے ہیں، لہٰذا اسے کھانا مناسب نہیں، سوائے اشد ضرورت کے ایسی چیز استعمال نہ کی جائے۔ 7اس حدیث کا متعلقہ باب سے تو کوئی تعلق نہیں، البتہ اصل کتاب تعلق ہے۔ ممکن ہے۔ یہ باب ضمنی ہو۔"}],[4297,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ اسی دوران کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تہامہ کے ذی الحلیفہ میں تھے تو لوگوں کو کچھ اونٹ ملے اور کچھ بکریاں (بطور مال غنیمت) اور رسول اللہ صلی اللہ علیہ وسلم تمام لوگوں کے پیچھے تھے، تو آگے کے لوگوں نے جلدی کی اور (تقسیم غنیمت سے پہلے) انہیں ذبح کیا اور ہانڈیاں چڑھا دیں، اتنے میں رسول اللہ صلی اللہ علیہ وسلم پہنچے، آپ نے حکم دیا تو ہانڈیاں الٹ دی گئیں، پھر آپ نے ان کے درمیان مال غنیمت تقسیم کیا اور دس بکریوں کو ایک اونٹ کے برابر قرار دیا، ابھی وہ اسی میں مصروف تھے کہ اچانک ایک اونٹ بھاگ نکلا، لوگوں کے پاس گھوڑے بہت کم تھے، وہ اس کو پکڑنے دوڑے تو اس نے انہیں تھکا دیا، ایک شخص نے ایک تیر پھینکا تو اللہ تعالی نے اسے روک دیا (تیر لگ جانے سے) اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ان چوپایوں میں بعض وحشی ہو جاتے ہیں جنگلی جانوروں کی طرح، لہٰذا جو تم پر غالب آ جائے (یعنی تمہارے ہاتھ نہ آئے) اس کے ساتھ ایسا ہی کرو ۱؎\"۔\n§وضاحت\n۱؎: یعنی: جب اختیاری طور پر ذبح نہ کر سکو تو ذبح کی اضطراری شکل اختیار کرو۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ تعالٰی عنہ نے فرمایا کہ ہم ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تہامہ کے ذوالحلیفہ میں تھے۔ لوگوں کو کچھ اونٹ اور بکریاں ملیں۔ رسول اللہ میں تھے۔ لوگوں کے آخر میں تھے۔ لشکر کے ابتدائی لوگوں نے جلدی کرتے ہوئے ان جانوروں کو ذبح کیا اور ہانڈیاں(یا دیگیں) چڑھا دیں۔ جب رسول اللہ صلی اللہ علیہ وسلم ان کے پاس پہنچے تو آپ نے حکم دیا کہ دیگیں فرمائی الٹ دی جائیں، پھر آپ نے غنیمت ان میں تقسیم فرمائی اور دس بکریوں کو ایک اونٹ کے برابر قرار دیا۔ اس دور ان میں ایک اونٹ کے برابر قرار دیا۔ اس دور ان میں ایک اونٹ بھاگ کھڑا ہوا۔ لوگوں کے پاس خال خال گھوڑے تھے۔ لوگوں نے اس کو پکڑنے کی کوشش کی لیکن وہ قابو نہ آسکا۔ ایک آدمی نے اس کو تیر مارا تو وہ رک گیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ان گھریلو جانوروں میں بھی بعض کبھی کبھی وحشی بن جاتے(جنگلی جانوروں کی طرح انسانوں سے بھاگنے لگتے) ہیں، لہٰذا اگر کوئی جانور قابو نہ آئے تو اس سے یہی سلوک کرو۔‘‘","f2":"1۔گھریلو جانور جب وحشی بن جائے اور انسانوں سے متنفر ہو کر بھاگ کھڑا ہو تو اس پر وحشی(جنگلی) جانور والا حکم لگے گا۔ ایسی صورت میں جب اس قسم کے جانور پر قابو پانا اور اسے ذبح کرنا ممکن نہ ہو تو اسے خشکی کے شکار کی طرح ذخمی کیا جا سکتا ہے۔ پھر ذبح کرنے سے پہلے مر جانے کی صورت میں اس پر جنگلی شکاری جانوروں والا حکم ہی لاگو ہوگا، یعنی زخمی ہونے کے بعد زندہ قابو آنے کی صورت میں اسے ذبح کرنا ضروری ہو گا جبکہ اس سے پہلے مر جانے کی صورت میں، اگر اسے اللہ کا نام لے کر تیریا گولی وغیرہ ماری گئی ہو تو وہ حلال سمجھا جائے گا اور اس گوشت کھانا درست ہو گا۔ جمہور اہل علم کاقول ہے۔2۔مشترکہ مال میں‘اجازت کے بغیر انفرادی اور شخصی تصرف ناجائز ہے اگرچہ وہ مال تھوڑا یہی ہو، خواہ ضرورت ماری گئی ہو تو وہ حلال میں، اجازت کے بغیر انفرادی اور شخصی تصرف نا جائز ہے اگر چہ وہ مال تھوڑا ہی ہو، خواہ ضرورت کا تقاضا یہی کیوں نہ ہو۔ 3۔یہ حدیث صحابہ کرام رضی اللہ عنہم کے کمال درجے کی اطاعت رسول اللہ صلی اللہ علیہ وسلم کی واضح دلیل ہے کہ سخت بھو کے ہونے کے باوجود انھوں نے ابلتی ہانڈیاں الٹا دیں لیکن رسول اللہ صلی اللہ علیہ وسلم کے حکم سے سر موانحراف نہیں کیا۔ 4۔شرعی مصلحت کا تقاضا ہو تو حاکم وقت رعایا کو سزا دے سکتا ہے، خواہ اس صورت میں مال ضائع ہی کیوں نہ ہوتا ہو لیکن شرط یہ ہے کہ شرعی مصلحت ہی غالب ہو۔ محض اپنی اَنا کی تسکین کے لیے سزا دینا مقصود نہ ہو۔ 5۔اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ مخلوط اور ملے جلے غنیمت میں ہر چیزک کی الگ الگ تقسیم ضروری نہیں بلکہ تعدیل و تقویم(مختلف اشیاء میں کمی بیشی کر کے انھیں قیمتاََ ایک دوسرے کے برابر قرار دینا) بھی جائز ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے دس بکریوں کو ایک اونٹ کے برابر قرار دیا تھا۔ 6۔اصول یہ ہے کہ گھریلو جانوروں کو قابو کر کے حلق باندھ کر اس کے حلق میں چھری کی نوک یا نیز وغیرہ مار کر اسے نحر کیا جائے۔ گھریلو جانوروں کو شکار کی طرح تیر مار کر ذبح نہیں کرنا چاہیے، البتہ جنگلی جانور چونکہ انسانوں کے قابو میں آتے، لہٰذا ان کے لیے یہی طریقہ ہے کہ بسم اللہ پڑھ کر تیر پھینکا جائے، جہاں بھی جا لگے۔ جب وہ خون نکلنے سے کمزور ہو جائے تو اس کو پکڑلے اور ذبح کر لے لیکن اگر وہ اسی تیرے بے جان ہو جائے تب بھی کوئی حرج نہیں۔7۔’’تہامہ کا ذوالحلیفہ‘‘اشارہ ہے کہ یہاں وہ ذوالحلیفہ مراد نہیں جو مدینہ کا میقات ہے اور جہاں احرام باندھا جاتا ہےبلکہ یہ اور ذوالحلیفہ ہے۔8۔’’ذبح کیا‘‘ نبی صلی اللہ علیہ وسلم کی اجازت کے بغیر، حالانکہ مال غنیمت امیر کی معرفت تقسیم ہونا چاہیے۔9۔’’دس بکریوں‘‘ معلوم ہوا دس بکریوں ایک اونٹ کے برابر ہیں، لہٰذا اونٹ کی قربانی میں دس افراد شریک ہو سکتے ہیں۔10۔’’خال خال گھوڑے تھے‘‘ یعنی کا تعاقب کرنے اور اسے پکڑنے لے لیے گھوڑے مہیا نہ ہو سکے۔ اور گھوڑوں کے بغیر اسے پکڑا نہیں جا سکتا تھا۔11۔’’بھاگنے لگتے ہیں‘‘ یعنی وحشت محسوس کرتے ہیں۔ عربی میں لفظ استعمال ہوا ہے جو کی جمع ہے۔ اس سکے معنی غیر مانوس، وحشتی، بدکنے اور بھاگنے والے جانور کے ہیں۔ چونکہ جنگلی جانور انسان سے غیر مانوس ہوتے ہیں اور دیکھتے ہی بھاگنے ہیں، اس لیے انھیں اوابد کہا جاتا ہے۔"}],[4298,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے شکار کے بارے میں پوچھا، آپ نے فرمایا: \"جب تم اپنا تیر چلاؤ تو اللہ کا نام لو پھر اگر تم دیکھو کہ وہ اس تیر سے مر گیا تو اسے کھاؤ إلا یہ کہ وہ پانی میں گر جائے، اس لیے کہ تمہیں نہیں معلوم کہ وہ پانی سے مرا ہے یا تیر سے\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے شکار کے بارے میں پوچھا تو آپ نے ارشاد فرمایا:’’جب تو چلائے تو بسم اللہ پڑھ لے۔ اگر وہ تیر جانور قتل بھی کر دے تو بھی کھالے الا یہ تو اسے پانی میں گرا ہوا پائے۔ تجھے کیا علم کہ اسے پانی نے مارا ہے یا تیرے تیرنے؟‘‘","f2":"کسی زخمی جانور یا پرندے کے محض پانی میں گرنے سے وہ شکار حرام نہیں ہو جاتاق بلکہ حرام اس صورت میں ہو گا جب پانی میں گرنے ہی سے اس کی موت واقع ہوئی ہو۔ اگر پانی میں اس انداز میں گرے کہ اسے زندہ حالت میں پالیا جائے تو اسے ذبح کر کے کھانا درست ہے۔ مطلب یہ ہے کہ پانی کے اندر ڈوب کر نہ مرا ہو۔"}],[4299,"عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے شکار کے بارے میں پوچھا، آپ نے فرمایا: \"جب تم اپنا تیر چلاؤ یا کتا دوڑاؤ اور اس پر اللہ کا نام لے لو پھر وہ تمہارے تیر سے مر جائے تو اسے کھاؤ\"، انہوں نے کہا: اللہ کے رسول! اگر وہ ایک رات میری پہنچ سے باہر رہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم اپنا تیر پاؤ اور اس کے علاوہ کسی اور چیز کا اثر نہ پاؤ تو اسے کھاؤ اور اگر وہ پانی میں گر جائے تو نہ کھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت عد بن حاتم رضی اللہ تعالٰی عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے شکار کے بارے میں پوچھا تو آپ نے فرمایا:’’ جب تو بسم اللہ پڑھ کر اپنا تیر چلائے یا کتا چھوڑے اور تیرا تیر(شکار کو) قتل کر دے تو تو شکار کھا سکتا ہے۔‘‘ میں نے کہا: اے اللہ کے رسول! اگر وہ شکار مجھ سے ایک رات تک غائب رہا تو؟ آپ نے فرمایا:’’ اگر تو اس جانور میں اپنا تیر پالے اور اس کے علاوہ کسی اور زخم کا نشان نہ ہو تو اسے کھا سکتا ہے، البتہ اگر وہ پانی میں گر گیا(اور مرگیا) ہو تو اسے مت کھا۔‘‘"}],[4300,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! ہم لوگ شکاری ہیں، ہم میں سے ایک شخص شکار کو تیر مارتا ہے تو وہ ایک رات یا دو رات غائب ہو جاتا ہے، وہ اس کا پتا لگاتا ہے یہاں تک کہ اسے مردہ پاتا ہے اور اس کا تیر اس کے اندر ہوتا ہے، آپ نے فرمایا: \"جب تم اس میں تیر پاؤ اور اس میں کسی درندے کا نشان نہ ہو اور تمہیں یقین ہو جائے کہ وہ تمہارے تیر سے مرا ہے تو اسے کھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں عرض کی: اے اللہ کے رسول! ہم شکاری لوگ ہیں۔ کبھی ہم میں سے کوئی شخص شکار پر تیر چلاتا ہے اور وہ(شکار) اس سے ایک دو راتیں غائب رہتا ہے۔ شکاری اس کی کھوج لگاتا ہوا پہنچتا ہے تو اسے بے جان پاتا ہے جبکہ اس کا تیر اس میں پیوست ہوتا ہے؟ آپ نے فرمایا:’’جب تو اپنا تیر اس میں لگا ہوا پہچان لے اور جانور میں کسی درندے کے زخم لگانے کا کوئی نشان نہ ہو اور تجھے یقین ہوکہ تیرے تیر ہی نے اسے قتل کیا ہے تو تو اسے کھا سکتا ہے۔‘‘","f2":"البتہ یہ ضروری ہے کہ وہ بدبودار نہ ہو چکا ہوا اور نہ کسی درندے نے اسے کھایا ہو۔"}],[4301,"عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم اپنا تیر اس (شکار) میں دیکھو اور اس کے علاوہ اس میں کوئی نشان نہ دیکھو اور تمہیں یقین ہو جائے کہ اسی سے وہ مرا ہے تو اسے کھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جب تو اپنا تیر اس میں لگا ہوا پہچان لے اور کوئی دوسرا نشان اس میں نہ ہو اور تجھے یقین ہو کہ تیرے تیرہی نے اسے قتل کیا ہے تو تو اسے کھا سکتا ہے۔‘‘"}],[4302,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! میں شکار کو تیر مارتا ہوں پھر میں ایک رات کے بعد اس کے نشانات ڈھونڈتا ہوں، آپ نے فرمایا: \"جب تم اس کے اندر اپنا تیر پاؤ اور اس میں سے کسی درندے نے نہ کھایا ہو تو تم کھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت عد بن حاتم رضی اللہ تعالٰی عنہ نے فرمایا کہ میں عرض کی: اے اللہ کے رسول! میں شکار کو تیر مارتا ہوں، پھر اس کا کھوج لگاتے ہوئے ایک رات کے بعد اسے پاتا ہوں(تو کیا کروں؟) آپ نے فرمایا:’’جب تو اس میں اپنا تیر پہچان لے۔ تو اسے کھا سکتا ہے بشر طیکہ کسی درندے نے اس میں سے کچھ نہ کھایا ہو۔‘‘"}],[4303,"ابوثعلبہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی اپنا شکار تین دن کے بعد پائے تو اسے کھائے إلا کہ اس میں بدبو پیدا ہو گئی ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابو ثعلبہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’جو شخص اپنے شکار کو تین دن بعد بھی پالے تو اسے کھا سکتا ہے الا یہ کہ وہ بدبودار ہوجائے۔‘‘"}],[4304,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں عرض کیا: اللہ کے رسول! میں اپنا کتا چھوڑتا ہوں، وہ شکار پکڑ لیتا ہے، لیکن مجھے ایسی کوئی چیز نہیں ملتی جس سے ذبح کروں تو میں پتھر (چاقو نما سفید پتھر) سے یا (دھاردار) لکڑی سے اسے ذبح کرتا ہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جس سے چاہو خون بہاؤ اور اللہ کا نام لو\"۔","الألباني: صحيح",{"u2":"حضت عدی بن حاتم رضی اللہ تعالٰی عنہ نے فرمایا کہ میں نے عرض کی: اسے اللہ کے رسول! میں اپنا کتا چھوڑتا ہوں، وہ کسی شکار کو پکڑ لیتا ہے لیکن میں کوئی ایسی چیز نہیں پاتا جس کے ساتھ اسے ذبح کر سکوں تو میں کسی تیز دھار پتھر یا لکڑی سے اسے ذبح کا لیتا ہوں(تو کیا یہ درست ہے)؟ آپ نے فرمایا:’’خون بہا جس چیز سے بھی ہو سکے۔(اور ذبح کرتے وقت) اللہ تعالیٰ کا نام لے۔‘‘","f2":"’’خون بہا‘‘ جانور کے ذبح ہونے کے لیے خون کا مکمل بہہ جانا ضروری ہے، چاہے کسی چیز سے بہایا جائے، یعنی لوہا، پتھر، لکڑی وغیرہ۔ مگر اس کا تیز دھار ہونا لازمی ہے تا کہ جانور ناجائز تکلیف نہ ہو، نیز جانور کو چوٹ نہ لگے، دباؤ نہ پڑے ورنہ جانور چوٹ یا دباؤ سے بھی ختم ہو سکتا ہے یا مکمل خون بہنے سے رک سکتا ہے۔ اس طرح جانور حرام ہو جائے گا۔ اس روایت کا باب سے کوئی تعلق نہیں، البتہ کتاب الصید سے تعلق ہے۔ سنن نسائی میں ایسے بہت ہے۔ کیوں؟ ممکن ہے کسی ناسخ کی غلطی ہو یا لفظ باب چھوٹ گیا ہو۔ کوئی اور وجہ بھی ہو سکتی ہے۔"}],[4305,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! میں سدھائے ہوئے کتے چھوڑتا ہوں تو وہ میرے لیے شکار پکڑ کر لاتے ہیں، کیا میں اس سے کھا سکتا ہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم کتے دوڑاؤ یا چھوڑو، (یعنی سدھائے ہوئے) اور اللہ کا نام لے لو اور وہ تمہارے لیے شکار پکڑ لائیں تو تم کھاؤ\"۔ میں نے عرض کیا: اور اگر وہ اسے مار ڈالیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگرچہ وہ اسے مار ڈالیں جب تک کہ اس میں کوئی ایسا کتا شریک نہ ہو جو ان کتوں میں سے نہیں تھا\"۔ میں نے عرض کیا: میں «معراض» (بے پر کے تیر) سے شکار کرتا ہوں اور مجھے شکار مل جاتا ہے تو کیا میں کھاؤں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم «معراض» (بغیر پر والا تیر) پھینکو اور «بسم اللہ» پڑھ لو اور وہ (شکار کو) چھید ڈالے تو کھاؤ اور اگر وہ آڑا لگے تو مت کھاؤ\" ۱؎۔\n§وضاحت\n۱؎: شکار کو چھید ڈالنے کی صورت میں اس سے خون بہے گا جو ذبح کا اصل مقصود ہے، اور آڑا لگنے کی صورت میں صرف چوٹ لگے گی اور خون بہے بغیر شکار مر جائے گا۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ سے منقول ہے کہ میں نے عرض کیا: اے اللہ کے رسول! میں سدھائے ہوئے کتے شکار پرچھوڑتا ہوں اور وہ اسے میرے لیے پکڑ رکھتے ہیں تو کیا میں اسے کھا لیا کروں؟ آپ نے فرمایا:’’جب تو سدھائے ہوئے کتے اللہ کانام لے چھوڑے اور وہ شکار کر تیرے لیے پکڑ رکھیں(خود نہ کھائیں) تو تو اسے کھا سکتا ہے۔‘‘ میں نے کہا: خواہ اسے قتل کر دیں؟ آپ نے فرمایا:’’خواہ قتل کر دیں بشر طیکہ ان کے ساتھ کوئی اور کتا شریک نہ ہو۔‘‘ میں نے کہا: میں معراض تیر پھینکتا ہوں اور کوئی جانور شکار کرتا ہوں تو کیا اسے کھا سکتا ہوں؟ آپ نے فرمایا:’’جب تو معراض تیر پھینکے اور بسم اللہ پڑھے، پھر وہ تیر شکار کو نوک کے ساتھ پھاڑے تو اسے کھا سکتا ہے۔ اور اگر وہ تیر چوڑائی کے بل جا کر لگے تو پھر اسے نہ کھا۔‘‘"}],[4306,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے «معراض» (آڑے نیزہ اور تیر) کے متعلق پوچھا تو آپ نے فرمایا: \"جب(شکار میں) «معراض» کی نوک لگے تو اسے کھاؤ اور جب آڑا «معراض» پڑے اور وہ (شکار) مر جائے تو وہ «موقوذہ» ۱؎ ہے، اسے مت کھاؤ\"۔\n§وضاحت\n۱؎: «موقوذہ»: چوٹ کھایا ہوا جانور، اس کا کھانا حرام ہے۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ نے فرمایا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے معراض تیر کے بارے میں پوچھا تو آپ نے فرمایا:’’جب وہ جانور کو نوک کے بل لگے تو اسے کھا سکتا ہے اور جب وہ عرض کے بل لگے اور جانور کو قتل کر دے تو وہ چوٹ سے مرا ہے۔ اسے مت کھا۔‘‘"}],[4307,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے «معراض» (آڑے نیزہ اور تیر) کے شکار کے پوچھا سوال کیا تو آپ نے فرمایا:\"جب (شکار میں) «معراض» (آڑے نیزہ اور تیر) کی نوک لگے تو کھاؤ اور جب وہ آڑا لگے تو مت کھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے معراض کے شکار کے بارے میں پوچھا تو آپ نے فرمایا:’’جب وہ نوک کے بل لگے تو شکار کھا لے اور جب عرض کے بل لگے تو مت کھا۔‘‘"}],[4308,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے «معراض» (آڑے نیزہ اور تیر) کے شکار کے بارے میں پوچھا تو آپ نے فرمایا:\"جب اس (شکار) میں «معراض» کی نوک لگے تو کھاؤ اور جب وہ آڑا لگے تو مت کھاؤ کیونکہ وہ «موقوذہ» (چوٹ کھایا ہوا شکار) ہے\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ تعالٰی عنہ سے منقول ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم سے معراض کے شکار بارے میں پوچھا تو آپ نے فرمایا:’’جس جانور کو تو اس کی نوک سے شکار کرے، اسے تو کھالے اور جس جانور کو وہ عرض کے بل لگے، وہ چوٹ سے مرنے والا جانور ہے۔‘‘"}],[4309,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو «باديہ» (دیہات) میں رہے گا وہ سخت مزاج ہو گا، اور جو شکار کا پیچھا کرے گا وہ (اس کے علاوہ دوسری چیزوں سے) غافل ہو جائے گا، اور جو بادشاہ کا چکر لگائے گا وہ فتنے اور آزمائش میں پڑ جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص صحرا میں رہے گا، سخت طبیعت ہو جائے گا۔ اور جو شخص شکار کے پیچھے لگ گیا، وہ (ہر چیز سے) غافل ہوگیا۔ اور جو شخص بادشاہ کا دم چھلہ بنا، وہ آزمائش میں پڑ گیا۔‘‘ الفاظ ابن مثنیٰ کے ہیں۔","f2":"(۱) اس حدیث مبارکہ سے بادیہ نشینی اور صحرا نشینی کی مذمت کا پہلو نکلتا ہے، اور وہ اس طرح کہ ایسا شخص زیادہ تر اہل علم کی مجلس سے دور ہی رہتا ہے، اسی طرح وہ اخلاق فاضلہ سے بھی دور ہوتا ہے۔ مزید برآں یہ بھی کہ صحرا نشین شخص جمعہ وجماعت اور اس کی دیگر خیر و برکات اور فہم دین کی مجالس و محافل سے بھی اکثر و بیشتر الگ تھلگ رہتا ہے۔ (۲) شرعاً ایک حد تک شکار کرنے کی اجازت ہے، تاہم یہ حدیث مبارکہ اس اہم مسئلے کی وضاحت بھی کرتی ہے کہ کسی انسان کا محض شکار کا ہو کر رہ جانا انتہائی مذموم ہے، اس لیے کہ ایسا شخص اپنے دینی اور دنیوی واحباب و فرائض سے غافل ہو جاتا ہے۔ شکار کے لیے جانا بالکل ممنوع نہیں۔ اگر شکار ممنوع ہوتا تو رسول اللہ صلی اللہ علیہ وسلم حضرت عدی بن حاتم اور ابو ثعلبہ خشنی رضی اللہ عنہ کو اس کی اجازت نہ دیتے۔ المختصر اعتدال میں رہتے ہوئے شکار کرنا درست ہے، افراط و تفریط کا شکار نہیں ہونا چاہیے۔ (۳)حدیث مذکور سے حکمرانوں اور صاحب اختیار واقتدار لوگوں کا کاسہ لیسی کرنے اور ان کے دروازوں پر حاضری دینے کی مذمت ظاہر ہوتی ہے۔ یہ حقیقت بالکل واضح ہے کہ ملوک وسلاطین کا قرب اچھے بھلے انسان کو فتنوں میں مبتلا کر دیتا ہے۔ یہ فتنے کئی طرح کے ہو سکتے ہیں جسمانی بھی اور روحانی بھی۔ جسمانی فتنے تو اس طرح ہو سکتے ہیں کہ حکمرانوں کی ہاں میں ہاں نہ ملانے کی وجہ سے اور ان کے اختیار کردہ منکرات و فواحش کا انکار کرنے سے جسمانی سزائیں بھگتنا پڑ سکتی ہیں جیسا کہ دنیا دار، نفس پرست بادشاہوں اور اصحاب اقتدار کی تاریخ اس حقیقت کی گواہ ہے۔ جبکہ اس کے برعکس ان کے دین کو خطرہ ہوتا ہے، یعنی حکمرانوں کی موافقت کرنے سے یا ان کی بے راہ روی اور منکرات پر خاموش رہنے سے دین سے ہاتھ دھونے پڑتے ہیں۔ اعاذنا اللہ منہ۔ (۴) ’’وہ غافل ہو گیا‘‘ کیونکہ شکار پتا نہیں کہاں کہاں بھاگتا پھرے۔ ایک کھیت سے دوسرے کھیت میں، دوسرے سے تیسرے میں وہکذا، لہٰذا اس کے پیچھے پیچھے پھرنے والا شخص اپنے گھر بار سے دور ہوجائے گا۔ گھریلو کام پڑے رہ جائیں گے۔ ایسا شخص نماز روزے کا پابند بھی نہیں رہ سکتا۔ پھر شکار ملے یا نہ ملے۔ گویا وہ دنیا سے بھی گیا اور آخرت سے بھی۔"}],[4310,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک اعرابی نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک خرگوش لایا، اس نے اسے بھون رکھا تھا، اسے آپ کے سامنے رکھ دیا، رسول اللہ صلی اللہ علیہ وسلم رکے رہے اور خود نہیں کھایا اور لوگوں کو کھانے کا حکم دیا۔ اعرابی بھی رک گیا، رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"تمہیں کھانے سے کیا چیز مانع ہے؟\" وہ بولا: میں ہر ماہ تین دن کے روزے رکھتا ہوں۔ آپ نے فرمایا: \"اگر تمہیں روزے رکھنے ہیں تو چاندنی راتوں (تیرہویں، چودہویں اور پندرہویں تاریخوں) میں رکھا کرو\"۔","الألباني: ضعيف",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک اعرابی نبی اکرم صلی اللہ علیہ وسلم کے پاس خرگوش بھون کر لایا اور آپ کے آگے رکھ دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے ہاتھ نہ بڑھایا اور نہ کھایا لیکن آپ نے لوگوں سے فرمایا کہ کھائیں۔ اعرابی نے بھی نہ کھایا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا: ’’تو کیوں نہیں کھاتا؟‘‘ اس نے کہا: میں ہر مہینے سے تین دن روزہ رکھتا ہوں (آج میرا روزہ ہے)۔ آپ نے فرمایا: اگر تو نے نفل روزے رکھنے ہوں تو چاندانی راتوں کے روزے رکھا کر۔‘‘"}],[4311,"عمر رضی اللہ عنہ کہتے ہیں کہ قاحہ (مکہ اور مدینہ کے درمیان ایک مقام) کے دن ہمارے ساتھ کون تھا؟ ابوذر رضی اللہ عنہ بولے: میں، (اس دن) نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک خرگوش لایا گیا تو جو لے کر آیا اس نے کہا: میں نے اسے حیض آتے دیکھا ہے، تو نبی اکرم صلی اللہ علیہ وسلم نے اسے نہیں کھایا پھر فرمایا:\"تم لوگ کھاؤ\"، ایک شخص نے کہا: روزہ دار ہوں، آپ نے فرمایا: \"تمہارا یہ کون سا روزہ ہے؟\" اس نے کہا: ہر ماہ تین دن والا، آپ صلی اللہ علیہ وسلم نے فرمایا:\"تو تم ایام بیض یعنی تیرہویں، چودہویں اور پندرہویں راتوں کے روزے کیوں نہیں رکھتے؟\"۔","الألباني: حسن",{"u2":"حضرت عمر رضی اللہ تعالٰی عنہ نے ایک دفعہ فرمایا: قاحہ کے دن ہمارے ساتھ کون حاضر تھا؟ حضرت ابو ذر رضی اللہ تعالٰی عنہ کہنے لگے: میں، وہاں نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک خرگوش لایا گیا۔ لانے والے شخص نے یہ بھی کہا کہ میں نے اسے حیض آتے دیکھا ہے۔ میرا خیال ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے اسے نہ کھایا، پھر آپ نے (حاضرین سے) کہا: تم کھاؤ۔ وہ آدمی کہنے لگا: میرا روزہ ہے۔ آپ نے فرمایا: ’’کیسا روزہ؟‘‘ اس نے کہا: ہر مہینے سے تین روزے۔ آپ نے فرمایا: ’’پھر تو چاندنی راتوں تیرہ، چودہ اور پندرہ تاریخ کے کیوں نہیں رکھتا؟‘‘","f2":"(۱) ’’قاحہ‘‘ یہ مکہ مکرمہ اور مدینہ منورہ کے درمیان ایک جگہ کا نام ہے۔ (۲) ’’نہ کھایا‘‘ رسول اللہ صلی اللہ علیہ وسلم بہت لطیف اور حساس مزاج والے تھے۔ حیض کے خون کا نام سن کر آپ کی لطیف طبع نے کھانا گوارا نہ فرمایا اگرچہ حیض کے خون کا جانور کی حلت اور حرمت سے کوئی تعلق نہیں۔ ہر جانور سے نجاست خارج ہوتی ہے، حلال ہو یا حرام۔ اگر کسی سے حیض کا خون خارج ہوگیا تو کیا قباحت ہے؟ تبھی تو آپ نے دیگر حاضرین کو کھانے کا حکم دیا۔ معلوم ہوا خرگوش نہ حرام ہے نہ مکروہ بلکہ مستحب کہا جا سکتا ہے کیونکہ آپ نے کھانے کا حکم دیا ہے، بلکہ جب ایک شخص نے کھایا تو آپ نے اس سے وضاحت طلب فرمائی۔ (۴) ’’چاندانی راتیں‘‘ گویا ان دنوں کا روزہ افضل ہے۔ کیوں؟ واللہ اعلم! ممکن ہے ان راتوں اور دنوں میں چاند کے کامل ہونے کی بنا پر طبع انسانی میں چستی اور نشاط کامل ہوتے ہوں، جیسے سمندر۔ یہاں ذکر تو راتیں ہیں مگر مراد دن ہیں کیونکہ روزہ تو دن کا ہوتا ہے نہ کہ رات کا۔ ہاں، ابتدا اندھیرے میں ہوتی ہے۔"}],[4312,"انس رضی اللہ عنہ کہتے ہیں کہ مرالظہران میں میں نے ایک خرگوش کو چھیڑا اور اسے پکڑ لیا، میں اسے لے کر ابوطلحہ رضی اللہ عنہ کے پاس آیا، انہوں نے اسے ذبح کیا، پھر مجھے اس کی دونوں رانیں اور پٹھے دے کر نبی اکرم صلی اللہ علیہ وسلم کے پاس بھیجا، تو آپ نے اسے قبول فرمایا۔\n§وضاحت\n۱؎: \"مرالظہران\" مکے سے کچھ دور ایک مقام کا نام ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ تعالٰی عنہ سے مروی ہے کہ مقام مرالظہران میں ہم ایک خرگوش کے پیچھے بھاگے۔ میں نے اسے پکڑ لیا اور اسے لے کر ابو طلحہ رضی اللہ تعالٰی عنہ کے پاس آیا۔ انھوں نے اسے ذبح کیا، پھر اس کی چاروں ٹانگیں مجھے دے کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں بھیجا۔ آپ نے انھیں قبول فرما لیا۔","f2":"(۱) خرگوش حلال ہے۔ امام ابن قدامہ فرماتے ہیں: ’’خرگوش مباح ہے۔ حضرت سعد بن ابی وقاص رضی اللہ تعالٰی عنہ نے بھی خرگوش کا گوشت کھایا ہے۔ ابو سعید، عطائ، سعید بن مسیب، لیث، امام مالک، امام شافعی، ابو ثور اور ابن منذرM سے خرگوش کا گوشت کھانے کی رخصت منقول ہے۔ ہمیں خرگوش کو حرام قرار دینے والا ایک شخص بھی معلوم نہیں، ہاں! عمرو بن عاص رضی اللہ تعالٰی عنہ سے کچھ اختلاف منقول ہے، لیکن دیگر نے ان کی مخالفت بھی کی ہے۔ دیکھیے: (ذخیرۃ العقبیٰ: ۳۳/ ۱۷۴، ۱۷۵) (۲) حدیث مبارکہ سے یہ مسئلہ بھی ثابت ہوا کہ اگر کئی لوگ ایک شکار کو پکڑنے کے لیے اس کا پیچھا کریں تو پکڑے جانے کی صورت میں اس کو پکڑنے والا شخص ہی اس کا مالک ہوگا، دوسرا شخص اس کا مالک نہیں ہوگا۔ ہاں، اگر وہ سارے لوگ ہی مشترکہ طور پر شکار کر رہے ہوں تو وہ تمام اس میں شریک ہوں گے اور باہمی رضا مندی سے اپنا حصہ لیں گے۔ (۳) اس حدیث سے یہ بھی معلوم ہوا کہ شکار کا ہدیہ دینا اور لینا دونوں جائز ہیں جیسا کہ حضرت انس رضی اللہ تعالٰی عنہ نے شکار کیا ہوا خرگوش ہدیہ کیا اور رسول اللہ صلی اللہ علیہ وسلم نے وہ ہدیہ قبول فرمایا۔ (۴)چھوٹے بچے کا سرپرست اس کی مملوکہ چیز میں، کسی مصلحت کے تحت جائز تصرف کر سکتا ہے۔ سرپرست کو شرعاً ایسا کرنے کا اختیار حاصل ہے۔ حضرت ابو طلحہ رضی اللہ تعالٰی عنہ نے اسی شرعی اختیار کے تحت ہی حضرت انس رضی اللہ تعالٰی عنہ کے کیے ہوئے شکار میں سے گوشت رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں ہدیتاً پیش کیا اور آپ نے بلا تردد وہ ہدیہ قبول فرما لیا۔ (۵)’’مر الظہران‘‘ مکہ مکرمہ سے تقریباً سولہ میل کے فاصلے پر ایک مقام ہے۔ (۶)’’ابو طلحہ‘‘ یہ حضرت انس رضی اللہ تعالٰی عنہ کی والدہ کے دوسرے خاوند تھے۔ (۷) ’’چاروں ٹانگیں‘‘ حدیث میں فَخِذَیْن اور وَرِکَیْن کا لفظ ہے۔ فَخِذَیْن رانوں کو کہتے ہیں مگر جانور کے فَخِذَیْن اگلی ٹانگوں کو کہتے ہیں۔ اسی طرح وَرِکَیْن چوتڑوں کو کہتے ہیں مگر جانور کے وَرِکَیْن اس کی پچھلی ٹانگیں ہوتی ہیں۔ (۸) ’’قبول فرمایا‘‘ یہ خرگوش کے حلال ہونے کی واضح دلیل ہے۔"}],[4313,"ابن صفوان رضی اللہ عنہ کہتے ہیں کہ مجھے دو خرگوش ملے، انہیں ذبح کرنے کے لیے کوئی چیز نہ ملی تو میں نے انہیں سفید پتھر سے ذبح کر دیا ۱؎، پھر نبی اکرم صلی اللہ علیہ وسلم سے اس سلسلے میں پوچھا، تو آپ نے مجھے انہیں کھانے کا حکم دیا۔\n§وضاحت\n۱؎: یہ سفید پتھر نوک دار تھا، کسی بھی دھاردار یا نوکدار چیز سے جس سے خون بہہ جائے، ذبح کر دینے سے جانور کا ذبح کرنا شرع کے مطابق صحیح ہو گا اور اس کا کھانا حلال ہو گا، ذبح کا اصل مقصود اللہ کا نام لینا اور خون بہنا ہے۔","الألباني: صحيح",{"u2":"حضرت ابن صفوان رضی اللہ تعالٰی عنہ سے روایت ہے کہ میں نے دو خرگوش شکار کیے لیکن مجھے کوئی ایسی چیز نہ مل سکی جس سے میں انھیں ذبح کر سکتا تو میں نے انھیں ایک تیز دھار پتھر سے ذبح کر دیا، پھر میں نے نبی اکرم صلی اللہ علیہ وسلم سے اس بارے میں پوچھا تو آپ نے مجھے ان کے کھانے کا حکم دیا۔ (کھانے کی اجازت دی)۔"}],[4314,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم منبر پر تھے تو ضب کے بارے میں سوال کیا گیا تو آپ نے فرمایا: \"میں اسے نہ کھاتا ہوں اور نہ ہی اسے حرام قرار دیتا ہوں\" ۱؎۔\n§وضاحت\n۱؎: ضب: گوہ ایک رینگنے والا جانور جو چھپکلی کے مشابہ ہوتا ہے، اس کو سوسمار بھی کہتے ہیں، سانڈا بھی گوہ کی قسم کا ایک جانور ہے جس کا تیل نکال کر گٹھیا کے درد کے لیے یا طلاء کے لیے استعمال کرتے ہیں، یہ جانور نجد کے علاقہ میں بہت ہوتا ہے، حجاز میں نہ ہونے کی وجہ سے نبی اکرم صلی اللہ علیہ وسلم نے اس کو نہ کھایا لیکن آپ صلی اللہ علیہ وسلم کے دستر خوان پر یہ کھایا گیا اس لیے حلال ہے۔ جس جانور کو نبی اکرم صلی اللہ علیہ وسلم کے دستر خوان پر صحابہ کرام رضی اللہ عنہم نے کھایا اس کو عربی میں ضب کہتے ہیں اور خود حدیث میں اس کی صراحت ہے کہ یہ نجد کے علاقہ میں پایا جانے والا جانور ہے، جو بلاشبہ حلال ہے۔ احناف اور شیعی فرقوں میں امامیہ کے نزدیک گوہ کا گوشت کھانا حرام ہے، فرقہء زیدیہ کے یہاں یہ مکروہ ہے، لیکن صحیح بات اس کی حلت ہے۔ نجد کے علاقے میں پایا جانے والا یہ جانور برصغیر :(ہندوستان، پاکستان، بنگلہ دیش ) میں پائے جانے والے گوہ یا سانڈے سے بہت سی چیزوں میں مختلف ہے: ضب نامی یہ جانور صحرائے عرب میں پایا جاتا ہے، اور ہندوستان میں پایا جانے والا گوہ یا سانڈاز رعی اور پانی والے علاقوں میں عام طور پر پایا جاتا ہے۔ - نجدی ضب :(گوہ ) پانی نہیں پیتا اور بلا کھائے اپنے سوراخ میں ایک لمبی مدت تک رہتا ہے، کبھی طویل صبر کے بعد اپنے بچوں کو کھا جاتا ہے، جب کہ برصغیر کا گوہ پانی کے کناروں پر پایا جاتا ہے، اور خوب پانی پیتا ہے۔ - نجدی ضب :(گوہ ) شریف بلکہ سادہ لوح جانور ہے، جلد شکار ہو جاتا ہے، جب کہ ہندوستانی گوہ کا پکڑنا نہایت مشکل ہوتا ہے۔ - ہندوستانی گوہ سانپ کی طرح زبان نکالتی اور پھنکارتی ہے، جب کہ نجدی ضب :(گوہ ) ایسا نہیں کرتی۔ نجدی ضب :(گوہ ) کی کھال کو پکا کر عرب اس کی کپی میں گھی رکھتے تھے، جس کو \" ضبة \" کہتے ہیں اور ہندوستانی گوہ کی کھال کا ایسا استعمال کبھی سننے میں نہیں آیا اس لیے کہ وہ بدبودار ہوتی ہے۔ ضب اور ورل میں کیا فرق ہے ؟ صحرائے عرب میں ضب کے مشابہ اور اس سے بڑا بالو، اور صحراء میں پائے جانے والے جانور کو \" وَرَل \" کہتے ہیں، تاج العروس میں ہے: ورل ضب کی طرح زمین پر رینگنے والا ایک جانور ہے، جو ضب کی خلقت پر ہے، إلا یہ کہ وہ ضب سے بڑا ہوتا ہے، بالو اور صحراء میں پایا جاتا ہے، چھپکلی کی شکل کا بڑا جانور ہے، جس کی دم لمبی اور سر چھوٹا ہوتا ہے، ازہری کہتے ہیں: \" وَرَل \" عمدہ قامت اور لمبی دم والا جانور ہے، گویا کہ اس کی دم سانپ کی دم کی طرح ہے، بسا اوقات اس کی دم دو ہاتھ سے بھی زیادہ لمبی ہوتی ہے، اور ضب :(گوہ ) کی دم گانٹھ دار ہوتی ہے، اور زیادہ سے زیادہ ایک بالشت لمبی، عرب ورل کو خبیث سمجھتے اور اس سے گھن کرتے ہیں، اس لیے اسے کھاتے نہیں ہیں، رہ گیا ضب تو عرب اس کا شکار کرنے اور اس کے کھانے کے حریص اور شوقین ہوتے ہیں، ضب کی دم کھُردری، سخت اور گانٹھ والی ہوتی ہے، دم کا رنگ سبز زردی مائل ہوتا ہے، اور خود ضب مٹ میلی سیاہی مائل ہوتی ہے، اور موٹا ہونے پر اس کا سینہ پیلا ہو جاتا ہے، اور یہ صرف ٹڈی، چھوٹے کیڑے اور سبز گھاس کھاتی ہے، اور زہریلے کیڑوں جیسے سانپ وغیرہ کو نہیں کھاتی، اور ورل بچھو، سانپ، گرگٹ اور گوبریلا سب کھاتا ہے، ورل کا گوشت بہت گرم ہوتا ہے، تریاق ہے، بہت تیز موٹا کرتا ہے، اسی لیے عورتیں اس کو استعمال کرتی ہیں، اور اس کی بیٹ :(کا سرمہ ) نگاہ کو تیز کرتا ہے، اور اس کی چربی کی مالش سے عضو تناسل موٹا ہوتا ہے :(ملاحظہ ہو: تاج العروس: مادہ ورل، و لسان العرب ) سابقہ فروق کی وجہ سے دونوں جگہ کے نجدی ضب اور ورل اور ہندوستان پائے جانے والے جانور جس کو گوہ یا سانڈا کہتے ہیں، ان میں واضح فرق ہے، بایں ہمہ نجدی ضب :(گوہ ) کھانا احادیث نبویہ اور اس علاقہ کے مسلمانوں کے رواج کے مطابق حلال ہے، اور اس میں کسی طرح کی قباحت اور کراہت کی کوئی بات نہیں، رہ گیا ہندوستانی گوہ کی حلت وحرمت کا مسئلہ تو سابقہ فروق کو سامنے رکھ کر اس کا فیصلہ کرنا چاہیئے، اگر ہندوستانی گوہ نجاست کھاتا اور اس نجاست کی وجہ سے اس کے گوشت سے یا اس کے جسم سے بدبو اٹھتی ہے تو یہ چیز علماء کے غور کرنے کی ہے، جب گندگی کھانے سے گائے بکری اور مرغیوں کا گوشت متاثر ہو جائے تو اس کا کھانا منع ہے، اس کو اصطلاح میں \" جلالہ \" کہتے ہیں، تو نجاست کھانے والا جانور گوہ ہو یا کوئی اور وہ بھی حرام ہو گا، البتہ برصغیر کے صحرائی علاقوں میں پایا جانے والا گوہ نجد کے ضب :(گوہ ) کے حکم میں ہو گا۔ ضب اور ورل کے سلسلے میں نے اپنے دوست ڈاکٹر محمد احمد المنیع پروفیسر کنگ سعود یونیورسٹی، ریاض جو زراعت اور غذا سے متعلق کالج میں پڑھاتے ہیں، اور صحرائے نجد کے جانوروں کے واقف کار ہیں، سوال کیا تو انہوں نے اس کی تفصیل مختصراً یوں لکھ کر دی: نجدی ضب نامی جانور کھایا جاتا ہے، اور \" ورل \" نہیں کھایا جاتا ہے ضب کا شکار آسانی سے کیا جا سکتا ہے اور ورل کا شکار مشکل کام ہے، ضب گھاس کھاتا ہے، اور ورل گوشت کھاتا ہے، ضب چیر پھاڑ کرنے والا جانور نہیں ہے، جب کہ ورل چیر پھاڑ کرنے والا جانور ہے، ضب کا ایک ہی رنگ ہوتا ہے، اور ورل دھاری دھار ہوتا ہے، ضب کی جلد کھُردری ہوتی ہے اور ورل کی جلد نرم ہوتی ہے، ضب کا سر چوڑا ہوتا ہے، اور وَرل کا سر دم نما ہوتا ہے، ضب کی گردن چھوتی ہوتی ہے، اور ورل کی گردن لمبی ہوتی ہے، ضب کی دم چھوٹی ہوتی ہے اور ورل کی دم لمبی ہوتی ہے، ضب کھُردرا اور کانٹے دار ہوتا ہے، اور ورل نرم ہوتا ہے، ضب اپنی دم سے اپنا دفاع کرتا ہے، اور ورل بھی اپنی دم سے اپنا دفاع کرتا ہے، اور دم سے شکار بھی کرتا ہے، ضب گوشت بالکل نہیں کھاتا، اور ورل ضب اور گرگٹ سب کھا جاتا ہے، ضب تیز جانور ہے، اور ورل تیز ترضب میں حملہ آوری کی صفت نہیں پائی جاتی جب کہ ورل میں یہ صفت موجود ہے، وہ دانتوں سے کاٹتا ہے، اور دم اور ہاتھ سے حملہ کرتا ہے، ضب ضرورت پڑنے پر اپنا دفاع کاٹ کر اور ہاتھوں سے نوچ کر یا دم سے مار کرتا ہے، اور وَرل بھی ایسا ہی کرتا ہے، ضب میں کچلی دانت نہیں ہے، اور وَرل میں کچلی دانت ہے، ضب حلال ہے، اور ورل حرام، ورل کے بارے میں یہ بھی کہا جاتا ہے کہ یہ زہریلا جانور ہے۔ صحرائے عرب کا ضب، وَرل اور ہندوستانی گوہ یا سانڈا سے متعلق اس تفصیل کا مقصد صرف یہ ہے کہ اس جانور کے بارے میں صحیح صورت حال سامنے آ جائے، حنفی مذہب میں بھینس کی قربانی جائز ہے اور دوسرے فقہائے کے یہاں بھی اس کی قربانی اس بنا پر جائز ہے کہ یہ گائے کی ایک قسم ہے، جب کہ گائے کے بارے میں یہ مشہور ہے اور مشاہدہ بھی کہ وہ پانی میں نہیں جاتی جب کہ بھینس ایسا جانور ہے جس کو پانی سے پیار اور کیچڑ سے محبت ہے اور جب یہ تالاب میں داخل ہو جائے تو اس کو باہر نکالنا مشکل ہوتا ہے، اگر بھینس کی قربانی کو گائے پر قیاس کر کے فقہاء نے جائز کہا ہے تو دونوں جگہ گوہ کے بعض فرق کا اعتبار نہ کرتے ہوئے اس جنس کے جانوروں کو حلال ہونا چاہیئے، اہل علم کو فقہی تنگنائے سے ہٹ کر نصوص شرعیہ کی روشنی میں اس مسئلہ پر غور کرنا چاہیئے اور عاملین حدیث کے نقطہٰ نظر کو صحیح ڈھنگ سے سمجھنا چاہیئے۔ گوہ کی کئی قس میں ہیں اور ہو سکتا ہے کہ بہت سی چیزیں سب میں قدر مشتر کہوں جیسے کہ قوت باہ میں اس کا مفید ہونا اس کی چربی کے طبی فوائد وغیرہ وغیرہ۔ حکیم مظفر حسین اعوان گوہ کے بارے میں لکھتے ہیں: نیولے کے مانند ایک جنگلی جانور ہے، دم سخت اور چھوٹی، قد بلی کے برابر ہوتا ہے، اس کے پنجے میں اتنی مضبوط گرفت ہوتی ہے کہ دیوار سے چمٹ جاتا ہے، رنگ زرد سیاہی مائل، مزاج گرم وخشک بدرجہ سوم … اس کی کھال کے جوتے بنائے جاتے ہیں۔ :(کتاب المفردات: ۴۲۷ )، ظاہر ہے کہ یہ برصغیر میں پائے جانے والے جانور کی تعریف ہے۔ گوہ کی ایک قسم سانڈہ بھی ہے جس کے بارے میں حکیم مظفر حسین اعوان لکھتے ہیں: مشہور جانور ہے، جو گرگٹ یا گلہری کی مانند لیکن اس سے بڑا ہوتا ہے، اس کی چربی اور تیل دواء مستعمل ہے، مزاج گرم و تر بدرجہ اول، افعال و استعمال بطور مقوی جاذب رطوبت، معظم ذکر، اور مہیج باہ ہے :(کتاب المفردات: صفحہ ۲۷۵ )","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم منبر پر تشریف فرما تھے کہ آپ سے سانڈے کے بارے میں پوچھا گیا۔ آپ نے فرمایا ’’میں نہ تو اسے کھاتا ہوں نہ حرام کہتا ہوں۔‘‘","f2":"(۱) سانڈا حلال ہے۔ حدیث میں مذکور الفاظ [وَلَا أُحَرِّمُہٗ] اس کی تصریح دلیل ہیں۔ صحیح بخاری اور صحیح مسلم میں مروی حضرت خالد بن ولید رضی اللہ عنہ کی حدیث اس سے بھی صریح ہے کہ انھوں نے ضب، یعنی سانڈے کے متعلق خود رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: [أَحْرَامٌ الضَّبُّ یَا رَسُولَ اللّٰہِ؟] ’’اے اللہ کے رسول! کیا سانڈا حرام ہے؟‘‘ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: [لَا، وَلٰکِنْ لَمْ یَکُنْ بِأَرْضِ قَوْمِی، فَأَجِدُنِی أَعَافُہٗ] ’’نہیں (سانڈا حرام نہیں) لیکن یہ میری قوم کے علاقے میں نہیں تھا، اس لیے میں اس سے (طبعی طور پر)کراہت محسوس کرتا ہوں۔‘‘ (صحیح البخاری، الاطعمہ، حدیث: ۵۳۹۱، وصحیح مسلم، الصید والذبائح، حدیث: ۱۹۴۵) (۲) معلوم ہوا حلال وطیب چیز جو طبعاً ناپسند ہو اسے کھانے سے ناخوش گوار اور منفی اثرات مرتب ہو سکتے ہیں۔ (۳) حدیث میں لفظ ’’ضب‘‘ استعمال ہوا ہے۔ ہمارے ہاں عموماً اس کے معنی ’’گوہ‘‘ کیے جاتے ہیں لیکن جو اوصاف ضب کے بیان کیے گئے ہیں، وہ تمام کے تمام سانڈے میں بھی پائے جاتے ہیں، اس لیے درست بات یہی ہے کہ اس سے مراد سانڈا ہے، گوہ نہیں۔ واللہ اعلم۔\n(۵) معلوم ہوا ضب حرام نہیں ورنہ آپ کھانے سے منع فرما دیتے، بلکہ آپ کے دستر خوان پر آپ کے سامنے اسے کھایا گیا۔ باقی رہا آپ کا اسے نہ کھانا تو آپ کی طبیع لطیف کا تقاضا تھا۔ آپ بہت سی ایسی چیزوں سے پرہیز فرماتے تھے جو قطعاً حلال ہیں، مثلاً: لہسن، پیاز وغیرہ۔ حلت اور حرمت الگ چیز ہے اور طبعی کراہت وناپسندیدگی الگ چیز ہے۔"}],[4315,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے کہا: اللہ کے رسول! ضب کے بارے میں آپ کی کیا رائے ہے؟ آپ نے فرمایا: \"میں نہ اسے کھاتا ہوں اور نہ ہی اسے حرام قرار دیتا ہوں\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے کہا: اے اللہ کے رسول! سانڈے کے بارے میں آپ کا کیا خیال ہے؟ آپ نے فرمایا: ’’نہ میں اسے کھاتا ہوں نہ حرام کرتا ہوں۔‘‘"}],[4316,"خالد بن ولید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس بھنا ہوا ضب لایا گیا اور آپ کے قریب رکھا گیا، آپ نے اپنا ہاتھ اس کی طرف بڑھایا تاکہ اس سے کھائیں، تو وہاں موجود کچھ لوگوں نے آپ سے کہا: اللہ کے رسول! یہ تو ضب کا گوشت ہے، آپ نے اس سے اپنا ہاتھ اٹھا لیا، اس پر خالد بن ولید رضی اللہ عنہ نے آپ سے کہا کہ اللہ کے رسول! کیا ضب حرام ہے؟ آپ نے فرمایا: \"نہیں، لیکن میری قوم کی زمین میں نہیں تھا، لہٰذا مجھے اس سے گھن آ رہی ہے\"، پھر خالد رضی اللہ عنہ نے اپنا ہاتھ ضب کی طرف بڑھایا اور اس میں سے کھایا اور رسول اللہ صلی اللہ علیہ وسلم دیکھ رہے تھے۔","الألباني: صحيح",{"u2":"حضرت خالد بن ولید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک بھنا ہوا ضب لایا گیا اور آپ کو پیش کیا گیا۔ آپ نے اسے کھانے کے لیے ہاتھ بڑھایا کہ حاضرین میں سے کسی نے کہا: اے اللہ کے رسول! یہ ضب کا گوشت ہے۔ آپ نے اپنا ہاتھ روک لیا۔ حضرت خالد بن ولید رضی اللہ عنہ نے کہا: اے اللہ کے رسول! کیا ضب حرام ہے؟ آپ نے فرمایا: ’’نہیں۔ لیکن یہ میری قوم کے علاقے (میرے وطن) میں نہیں پایا جاتا، اس لیے مجھے اس سے کچھ کراہت سی محسوس ہوتی ہے۔‘‘ حضرت خالد رضی اللہ عنہ ضب کی طرف بڑھے اور اس سے کھایا جبکہ رسول اللہ صلی اللہ علیہ وسلم دیکھ رہے تھے۔","f2":"(۱) کسی حلال چیز سے مطلقاً نفرت کرنا یا طبیعت کو اس کا اچھا نہ لگنا اس کی حرمت کو لازم نہیں، تفصیل گزشتہ حدیث کے فوائد میں دیکھی جا سکتی ہے۔ (۲)کسی چیز کو حلال یا حرام قرار دینا صرف اللہ تعالیٰ کا اختیار ہے۔ اس کے سوا کوئی شخص طبعی کراہت یا کسی اور وجہ سے کسی حلال چیز کو حرام قرار نہیں دے سکتا۔ (۳) حدیث میں مذکور ہے کہ رسول اللہ صلی اللہ علیہ وسلم کسی کھانے پر عیب نہیں لگاتے تھے جبکہ اس حدیث میں ہے کہ آپ صلی اللہ علیہ وسلم نے ناپسندیدگی کا اظہار فرمایا ہے۔ بظاہر تعارض ہے، دونوں میں کیا تطبیق ہے؟ تعارض والی کوئی بات نہیں کیونکہ کسی چیز کی ناپسندیدگی اور چیز ہے اور اس پر عیب لگانا اور ہے۔ عیب لگانا تو یہ ہے کہ کوئی شخص یا اہل خانہ آپ کے لیے چیز پکائیں اور آپ اس پکی پکائی چیز میں کیڑے نکالنا شروع کر دیں وغیرہ۔ (۴) حدیث مبارکہ سے یہ بھی معلوم ہوتا ہے کہ اچھے لوگوں کی طبیعتیں بھی ایک دوسرے سے مختلف ہوتی ہیں جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے سانڈے کا گوشت کھانے سے کراہت محسوس فرمائی جبکہ حضرت خالد بن ولید رضی اللہ عنہ نے اسے کھا لیا۔"}],[4317,"عبداللہ بن عباس رضی اللہ عنہا سے روایت ہے کہ انہیں خالد بن ولید رضی اللہ عنہ ۱؎ نے بتایا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ام المؤمنین میمونہ رضی اللہ عنہا کے پاس گئے (یہ ان کی خالہ تھیں) ۲؎، تو رسول اللہ صلی اللہ علیہ وسلم کے سامنے ضب کا گوشت پیش کیا گیا، آپ کا معمول تھا کہ آپ کوئی چیز نہ کھاتے جب تک معلوم نہ ہو جائے کہ وہ کیا ہے، تو امہات المؤمنین رضی اللہ عنہم میں سے کسی نے کہا: کیا تم رسول اللہ صلی اللہ علیہ وسلم کو نہیں بتاؤ گی کہ آپ کیا کھا رہے ہیں؟ تو انہوں نے آپ کو بتایا کہ یہ ضب کا گوشت ہے، چنانچہ آپ نے اسے چھوڑ دیا، خالد رضی اللہ عنہ کہتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: کیا وہ حرام ہے؟ آپ نے فرمایا: \"نہیں، لیکن وہ ایسا کھانا ہے جو میری قوم کی زمین میں نہیں ہوتا، اس لیے مجھے اس سے گھن آ رہی ہے\"۔ خالد بن ولید رضی اللہ عنہ کہتے ہیں: تو میں نے اسے اپنی طرف کھینچا اور اسے کھایا اور رسول اللہ صلی اللہ علیہ وسلم دیکھ رہے تھے۔ اس حدیث کو ابن الاصم نے ام المؤمنین میمونہ رضی اللہ عنہا سے روایت کیا ہے، ابن الاصم آپ کی گود میں پلے تھے۔\n§وضاحت\n۱؎: ام المؤمنین میمونہ رضی اللہ عنہا ابن عباس کے دونوں بیٹے عبداللہ اور فضل اور خالد بن الولید تین کی خالہ ہیں، عبداللہ بن عباس کی والدہ کا نام لبابۃ الکبری ام الفضل ہے، اور خالد کی والدہ کا نام لبابۃ الصغری بنت حارث بن حزن الھلالی ہے، رضی اللہ عنھن۔ ۲؎: ام المؤمنین خالد بن ولید رضی اللہ عنہما کی خالہ تھیں، ابن الاصم یہ یزید بن الاصم، عمرو بن عبید بن معاویہ ہیں اور یزید میمونہ رضی اللہ عنہا کے بھانجے ہیں۔","الألباني: صحيح",{"u2":"حضرت خالد بن ولید رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے (آپ کی زوجہ محترمہ) حضرت میمونہ بنت حارث رضی اللہ عنہا کے ہاں گیا۔ وہ میری خالہ تھیں۔ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں سانڈے کا گوشت پیش کیا گیا۔ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں سانڈے کا گوشت پیش کیا گیا۔ رسول اللہ صلی اللہ علیہ وسلم اس وقت تک کوئی چیز نہیں کھاتے تھے، جب تک پتا نہ چل جاتا کہ یہ کیا ہے؟ اس لیے ایک عورت نے کہا: تم رسول اللہ صلی اللہ علیہ وسلم کو بتا کیوں نہیں دیتے کہ آپ کیا کھانے لگے ہیں؟ پھر اس نے آپ کو بتا دیا کہ یہ سانڈے کا گوشت ہے۔ آپ نے اسے چھوڑ دیا۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: کیا یہ حرام ہے؟ آپ نے فرمایا: نہیں۔ لیکن یہ میری قوم کے علاقے (میرے وطن) میں نہیں پایا جاتا، اس لیے مجھے اس سے کچھ کراہت سی محسوس ہوتی ہے۔‘‘ حضرت خالد رضی اللہ عنہ نے فرمایا: میں نے برتن اپنی طرف کھینچ لیا اور اسے کھا لیا جبکہ رسول اللہ صلی اللہ علیہ وسلم مجھے (کھاتے ہوئے) دیکھ رہے تھے۔\nاور (یزید) ابن الاصم نے (یہ روایت اپنی خالہ ام المومنین) حضرت میمونہ رضی اللہ عنہا سے اس (ابن شہاب امام زہری رحمہ اللہ) کو بیان کی۔ اور وہ (ابن اصم) حضرت میمونہ کی پرورش میں تھے۔","f2":"(۱) اس حدیث مبارکہ سے یہ مسئلہ بھی ثابت ہوتا ہے کہ کسی شخص کی بیوی کے رشتہ دار اس کے خاوند کی اجازت اور رضا مندی سے اس کے گھر آجا سکتے ہیں جیسا کہ حضرت خالد رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی رضا مندی اور اجازت سے اپنی خالہ ام المومنین کے گھر تشریف لے گئے تھے۔ (۲)اس حدیث مبارکہ سے یہ اہم مسئلہ بھی ثابت ہوتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کوئی کام ہوتا دیکھ کر خاموش رہیں تو وہ کام شرعاً جائز اور حجت ہوتا ہے اور یہ صرف نبی صلی اللہ علیہ وسلم کا مقام ومرتبہ ہے۔ اسے محدثین کرام کی اصطلاح میں حدیث تقریری کہا جاتا ہے۔"}],[4318,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ میری خالہ (ام حفید رضی اللہ عنہا) نے مجھے پنیر، گھی اور ضب دے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس بھیجا، آپ نے پنیر اور گھی میں سے کھایا اور کراہت کی وجہ سے ضب چھوڑ دی، لیکن وہ رسول اللہ صلی اللہ علیہ وسلم کے دستر خوان پر کھائی گئی ۱؎ اگر وہ حرام ہوتی تو رسول اللہ صلی اللہ علیہ وسلم کے دستر خوان پر نہ کھائی جاتی اور نہ ہی آپ اسے کھانے کا حکم فرماتے۔\n§وضاحت\n۱؎: یعنی دوسروں نے ضب بھی کھایا۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ نے فرمایا: میری خالہ محترمہ نے رسول اللہ صلی اللہ علیہ وسلم کو پنیر، گھی اور سانڈے پیش کیے۔ آپ نے پنیر اور گھی تو کھا لیا لیکن سانڈے ناپسند کرتے ہوئے چھوڑ دیے (نہ کھائے)، البتہ وہ آپ کے دستر خون پر کھائے گئے۔ اگر یہ حرام ہوتے تو رسول اللہ صلی اللہ علیہ وسلم کے دستر خوان پر نہ کھائے جاتے اور نہ آپ ان کے کھانے کا حکم دیتے۔"}],[4319,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ان سے ضب کھانے کے بارے میں پوچھا گیا تو انہوں نے کہا: ام حفید (ابن عباس رضی اللہ عنہما کی خالہ) نے رسول اللہ صلی اللہ علیہ وسلم کے پاس گھی پنیر اور ضب بھیجا تو آپ نے گھی اور پنیر کھایا اور کراہت کی وجہ سے ضب چھوڑ دیا، لیکن اگر وہ حرام ہوتی تو رسول اللہ صلی اللہ علیہ وسلم کے دستر خوان پر نہ کھائی جاتی اور نہ آپ اسے کھانے کا حکم دیتے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے سانڈے (کا گوشت) کھانے کے بارے میں پوچھا گیا تو آپ نے فرمایا کہ ام حفید رضی اللہ عنہا نے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں گھی، پنیر اور سانڈے بھیجے۔ آپ نے گھی اور پنیر تو کھا لیے لیکن سانڈے ناپسند کرتے ہوئے چھوڑ دیے۔ اگر یہ حرام ہوتے تو نہ آپ کے دستر خوان پر کھائے جاتے اور نہ آپ ان کے کھانے کی اجازت دیتے۔","f2":"یہ ام حفید حضرت میمونہ رضی اللہ عنہا کی ہمشیرہ تھیں اور یہ دونوں حضرت ابن عباس اور حضرت خالد بن ولید رضی اللہ عنہم کی خالہ تھیں۔ ان روایات سے صاف معلوم ہوتا ہے کہ ضب حرام نہیں، البتہ آپ اس میں رغبت نہیں رکھتے تھے۔"}],[4320,"ثابت بن یزید انصاری رضی اللہ عنہ کہتے ہیں کہ ہم ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے ہم ایک جگہ ٹھہرے، لوگوں کو ضب ملی، میں نے ایک ضب پکڑی اور اسے بھونا، پھر اسے لے کر میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، آپ نے ایک لکڑی لی اور اس کی انگلیاں گنیں، پھر فرمایا: \"بنی اسرائیل کے کچھ لوگوں کی شکل مسخ کر کے زمین کے کچھ جانوروں کی طرح بنا دی گئی، مجھے نہیں معلوم کہ وہ کون سا جانور ہے\" ۱؎، میں نے عرض کیا: اللہ کے رسول! لوگوں نے اس میں سے کھا لیا ہے، تو پھر نہ آپ نے کھانے کا حکم دیا اور نہ ہی روکا۔\n§وضاحت\n۱؎: احتمال ہے کہ آپ کا یہ فرمان اس وقت کا ہو جب آپ کو یہ علم نہیں تھا کہ مسخ کی ہوئی مخلوق تین دن سے زیادہ مدت تک باقی نہیں رہتی۔","الألباني: صحيح الإسناد",{"u2":"حضرت ثابت بن یزید انصاری رضی اللہ عنہ نے فرمایا: ہم ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے۔ لوگ ایک منزل میں اترے تو انھیں بہت سے سانڈے مل گئے۔ میں نے ایک سانڈا پکڑا، اسے بھونا اور نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں لے آیا۔ آپ نے ایک لکڑی پکڑی اور اس کے ساتھ اس کی انگلیاں گننے لگے، پھر فرمایا: ’’بنی اسرائیل کی ایک قوم کو زمین کے جانوروں کی شکل میں مسخ کر دیا گیا تھا۔ میں نہیں جانتا کہ وہ کون سے جانور تھے؟‘‘ میں نے کہا: اے اللہ کے رسول! لوگوں نے تو اسے کھا بھی لیا ہے۔ لیکن آپ نے نہ تو اس کے کھانے کا حکم دیا اور نہ (اس کے کھانے سے) روکا۔"}],[4321,"ثابت بن یزید بن ودیعہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک ضب لایا۔ آپ اسے دیکھنے لگے اور اسے الٹا پلٹا اور فرمایا:\"ایک امت کی صورت مسخ کر دی گئی تھی، نہ معلوم اس کا کیا ہوا، اور میں اس کا علم نہیں، شاید یہ اسی میں سے ہو\"۔","الألباني: صحيح",{"u2":"حضرت ثابت بن ودیعہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک سانڈا لے کر آیا۔ آپ اسے الٹ پلٹ کر دیکھنے لگے، پھر فرمایا: ’’ایک قوم کی شکلیں بگاڑ دی گئی تھیں، معلوم نہیں اس کا کیا بنا؟ مجھے معلوم نہیں، شاید یہ بھی انھی میں سے ہو۔‘‘"}],[4322,"ثابت بن یزید بن ودیعہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک ضب لایا، آپ نے فرمایا: \"ایک امت مسخ کر دی گئی تھی\"، واللہ اعلم۔","الألباني: صحيح",{"u2":"حضرت ثابت بن ودیعہ رضی اللہ عنہ سے منقول ہے کہ ایک آدمی نبی اکرم صلی اللہ علیہ وسلم کے پاس ضب لے کر آیا۔ آپ نے فرمایا: ’’ایک امت کو مسخ کر دیا گیا تھا، (یہ ان میں سے نہ ہو)۔ واللہ اعلم","f2":"(۱) اس باب کے تحت آنے والی روایات سے صاف ثابت ہو رہا ہے کہ ضب حلال ہے۔ اسے بلا شک وشبہ کھایا جا سکتا ہے، البتہ آپ اس سے مالوف نہیں تھے، لہٰذا آپ کو طبعاً اچھا نہیں لگتا تھا، ورنہ آپ کے سامنے کھایا گیا، اگر حرام یا مکروہ ہوتا تو آپ کھانے نہ دیتے، البتہ آخری تین روایات سے معلوم ہوتا ہے کہ آپ کو اس کے بارے میں شک تھا کہ کہیں یہ مسخ شدہ نسل نہ ہو۔ لیکن ایک صحیح روایت میں آپ نے فرمایا ہے کہ مسخ شدہ نسل تین دن سے زائد زندہ نہیں رہتی۔ معلوم ہوتا ہے، پہلے آپ کو شک تھا، پھر آپ کو اللہ تعالیٰ کی طرف سے بتا دیا گیا کہ یہ مسخ شدہ نسل نہیں کیونکہ مسخ شدہ نسل تین دن سے زائد زندہ نہیں رہتی، اس لیے ان روایات میں ذکر کردہ شک کا ضب کی حلت پر کوئی اثر نہیں پڑتا، البتہ سنن ابوداود کی ایک روایت، جس کی سند کو حافظ ابن حجر رحمہ اللہ نے حسن قرار دیا ہے اور شیخ ناصر الدین البانی رحمہ اللہ اسے سلسلۃ الاحادیث الصحیحۃ (۲۳۹۰) میں لائے ہیں۔ اس روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ضب کھانے سے منع فرمایا۔ بلا شبہ حلت کی روایات اعلیٰ درجے کی صحیح اور صریح ہیں، اس لیے اس روایت کو اس دور پر محمول کیا جائے گا جب آپ کو اس کے بارے میں مسخ شدہ نسل ہونے کا شک تھا۔ اس بنا پر آپ صلی اللہ علیہ وسلم اس سے کنارہ کش رہے۔ صحابہ کرام رضی اللہ عنہم کو اسے کھانے کا حکم دیا نہ اس سے روکا۔ بعد ازاں جب آپ کو اس کی حلت سے آگاہ کر دیا گیا تو آپ نے صراحتاً اسے حلال قرار دیا، البتہ خود طبعاً اسے پسند نہیں فرماتے تھے، اس لیے نہیں کھایا۔ لہٰذا ممانعت اور اباحت وحلت کی روایات کے مابین تطبیق ہی بہتر ہے کہ ممانعت وکراہت کا تعلق رسول اللہ صلی اللہ علیہ وسلم کے اول دور سے ہے جبکہ اباحت واجازت کا تعلق بعد کے دور سے ہے۔ ہاں! جو طبعاً اسے ناپسند کرتا ہو اس کے حق میں یہ کراہت تنزیہ پر محمول ہوگی۔ واللہ اعلم۔ تفصیل کے لیے حوالہ مذکورہ دیکھیے۔ (۲) عام مترجمین ’’ضب‘‘ کے معنی ’’گوہ‘‘ کرتے ہیں لیکن یہ قطعاً صحیح نہیں ’’ضب‘‘ سانڈا ہی ہے، گوہ یا سوسمار نہیں۔ اگرچہ ان کی شکل وصورت ایک دوسرے سے ملتی جلتی ہے۔ ان میں ایک بنیادی فرق یہ بھی ہے کہ گوہ، مینڈک اور چھپکلیاں وغیرہ کھاتی ہے جبکہ سانڈا گھاس کھاتا ہے۔ مزید برآں یہ کہ گوہ جسامت میں سانڈے سے بڑی ہوتی ہے۔ حدیث میں سانڈے کا گوشت کھانے کا ذکر ہے لیکن گوہ کا کوئی ذکر نہیں۔"}],[4323,"ابن ابی عمار کہتے ہیں کہ میں نے جابر بن عبداللہ رضی اللہ عنہما سے لکڑ بگھا کے بارے میں پوچھا، تو آپ نے اسے کھانے کا حکم دیا، میں نے کہا: کیا وہ شکار ہے؟ انہوں نے کہا: ہاں، میں نے کہا: کیا آپ نے اسے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے؟ کہا: \"ہاں\"۔\n§وضاحت\n۱؎: «ضبع»: ایک درندہ ہے، جو کتے سے بڑا اور اس سے زیادہ مضبوط ہوتا ہے، اس کا سربڑا اور جبڑے مضبوط ہوتے ہیں، اس کی جمع «اضبع» ہے :(المعجم الوسیط: ۵۳۳-۵۳۴ ) ہند و پاک میں اس درندے کو لکڑ بگھا کہتے ہیں، جو بھیڑیئے کی قسم کا ایک جنگلی جانور ہے، اور جسامت میں اس سے بڑا ہوتا ہے، اور اس کے کیچلی کے دانت بڑے ہوتے ہیں، اس کے جسم کے بال کالے اور راکھ کے رنگ کے رنگ دھاری دار ہوتے ہیں، پیچھے بائیں پاؤں دوسرے پاؤں سے چھوٹا ہوتا ہے، اس کا سر چیتے کے سر کی طرح ہوتا ہے، لیکن اس سے چھوٹا ہوتا ہے، وہ اپنے چوڑے چکلے مضبوط جبڑوں سے شیر اور چیتوں کے سر کو توڑ سکتا ہے، اکثر رات میں نکلتا ہے، اور اپنے مجموعے کے ساتھ رہتا ہے، یہ جانور زمین میں سوراخ کر کے مختلف چھوٹے چھوٹے کمرے بناتے ہیں، اور بیچ میں ایک ہال ہوتا ہے، جس میں سارے کمروں کے دروازے ہوتے ہیں، اور ایک دروازہ اس ہال سے باہر کو جاتا ہے، نجد میں ان کی اس رہائش کو «مضبعہ» یا «مجفرہ» کہتے ہیں، ماں پورے خاندان کی نگران ہوتی ہے، اور سب کے کھانے پینے کا انتظام کرتی ہے، اور نر سوراخ کے کنارے پر چھوٹوں کی نگرانی کرتا ہے، یہ جانور مردہ کھاتا ہے، لیکن شکار کبھی نہیں کرتا اور کسی پر حملہ بھی نہیں کرتا إلا یہ کہ کوئی اس پر حملہ آور ہو، یہ جانوروں کے پیچھے رہتا ہے، اس کی گردن سیدھی ہوتی ہے، اس لیے دائیں بائیں جسم موڑے بغیر نہیں ہو سکتا۔ اہل نجد کے یہاں یہ جانور کھایا جاتا تھا اور لوگ اس کا شکار کرتے تھے، میں نے اس کے بارے میں اپنے ایک دوست ڈاکٹر محمد احمد المنیع پروفیسر کنگ سعود یونیورسٹی، ریاض جو زراعت اور غذا سے متعلق کالج میں پڑھاتے ہیں، اور بذات خود صحرائی جانور کا تجربہ رکھتے ہیں، سے پوچھا تو انہوں نے مذکورہ بالا تفصیلات سے مجھے آگاہ کیا اور اس کے زمین کے اندر کے گھر کا نقشہ بھی بنا کر دکھایا۔ اس کے گھر کو ماند اور کھوہ سے بھی تعبیر کیا جا سکتا ہے۔ یہ تفصیل اس واسطے درج کی جاری ہے کہ مولانا وحیدالزماں نے «ضبع» کا ترجمہ بجو سے کیا ہے، فرماتے ہیں: فارسی زبان میں اسے \" کفتار \" اور ہندی میں بجو کہتے ہیں، یہ گوشت خور جانور ہے، جو بلوں میں رہتا ہے، مولانا محمد عبدہ الفلاح فیروز پوری کہتے ہیں کہ «ضبع» سے مراد بجو نہیں ہے بلکہ اس نوع کا ایک جانور ہے جسے شکار کیا جاتا ہے، اور اس کو لکڑ بگڑ کھا کہا جاتا ہے، جو سابقہ ریاست سندھ اور بہاولپور میں پایا جاتا ہے۔ اوپر کی تفصیل سے پتہ چلتا ہے کہ حدیث میں مذکور ضبع سے مراد لکڑ بگھا ہے، بجو نہیں، شاید مولانا وحیدالزماں کے سامنے دمیری کی حیاۃ الحیوان تھی جس میں «ضبع» کی تعریف بجو سے کی گئی ہے، اور شیخ صالح الفوزان نے بھی حیاۃ الحیوان سے نقل کر کے یہی لکھا ہے، مولانا وحیدالزماں بجو کے بارے میں فرماتے ہیں: \" اس سے صاف نکلتا ہے کہ بجو حلال ہے، امام شافعی کا یہی قول ہے، اور ابوحنیفہ کہتے ہیں کہ وہ دانت والا درندہ ہے، تو اور درندوں کی طرح حرام ہو گا، اور جب حلت اور حرمت میں تعارض ہو تو اس سے باز رہنا بھی احتیاط ہے \"، سابقہ تفصیلات کی روشنی میں ہمارے یہاں لکڑ بگھا ہی «ضبع» کا صحیح مصداق ہے، اور اس کا شکار کرنا اور اس کو کھانا صحیح حدیث کی روشنی میں جائز ہے۔ واضح رہے کہ چیر پھاڑ کرنے والے حیوانات حرام ہے، یعنی جس کی کچلی ہوتی ہے، اور جس سے وہ چیر پھاڑ کرتا ہے، جیسے: کتا، بلی جن کا شمار گھریلو یا پالتو جانور میں ہے اور وحشی جانور جیسے: شیر، بھیڑیا، چیتا، تیندوا، لومڑی، جنگلی بلی، گلہری، بھالو، بندر، ہاتھی، سمور :(نیولے کے مشابہ اور اس سے کچھ بڑا اور رنگ سرخ سیاہی مائل ) گیدڑ وغیرہ وغیرہ۔ حنفیہ، شافعیہ اور حنابلہ کے یہاں یہ سارے جانور حرام ہیں، اور مالکیہ کا ایک قول بھی ایسے ہی ہے، لکڑ بگھا اور لومڑی ابویوسف اور محمد بن حسن کے نزدیک حلال ہے، جمہور علماء ان حیوانات کی حرمت کے دلیل میں ابوہریرہ رضی اللہ عنہ کی یہ حدیث پیش کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \" ہر کچلی والے درندے کا کھانا حرام ہے \" :(صحیح مسلم و موطا امام مالک )۔ لکڑ بگھا حنابلہ کے یہاں صحیح حدیث کی بنا پر حلال ہے، کچلی والے درندے میں سے صرف لکڑ بگھا کو حرمت کے حکم سے مستثنی کرنے والوں کی دلیل اس سلسلے میں وارد احادیث و آثار ہیں، جن میں سے زیر نظر جابر رضی اللہ عنہ کی حدیث ہے، جو صحیح ہے بلکہ امام بخاری نے بھی اس کی تصحیح فرمائی ہے :(کمافي التلخیص الحبیر۴/۱۵۲ )، نافع مولی ابن عمر سے روایت ہے کہ ایک آدمی نے ابن عمر کو یہ بتایا کہ سعد بن ابی وقاص لکڑ بگھا کھاتے ہیں تو ابن عمر نے اس پر نکیر نہیں فرمائی۔ مالکیہ کے یہاں ان درندوں کا کھانا حلال ہے، ان کا استدلال اس آیت کریمہ سے ہے: «قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به فمن اضطر غير باغ ولا عاد فإن ربك غفور رحيم» :(سورة الأنعام: 145 ) ان آیات میں درندوں کے گوشت کا ذکر نہیں کیا گیا ہے، اس لیے یہ حلال ہوں گے اور ہر کچلی والے درندے کے گوشت کھانے سے ممانعت والی حدیث کراہت پر محمول کی جائے گی۔ خلاصہ یہ کہ مالکیہ کے علاوہ صرف حنبلی مذہب میں صحیح حدیث کی بنا پر لکڑ بگھا حلال ہے :(ملاحظہ ہو: الموسوعۃ الفقہیۃ الکویتیۃ: ۵/۱۳۳-۱۳۴ )۔","الألباني: صحيح",{"u2":"حضرت ابن ابی عمار سے روایت ہے کہ میں نے حضرت جابر بن عبداللہ رضی اللہ عنہ سے لگڑ بگڑ کے بارے میں پوچھا تو انھوں نے مجھے اس کے کھانے کو کہا۔ میں نے کہا: کیا وہ شکار میں داخل ہے؟ انھوں نے فرمایا: ہاں۔ میں نے کہا: کیا آپ نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے سنی ہے۔ کہنے لگے: ہاں۔","f2":"(۱) مذکورہ حدیث سے معلوم ہوا کہ لگڑ بگڑ شکار ہے، اس لیے محرم شخص اس کا شکار کرے گا تو اسے اس کی مثل یعنی مینڈھا بطور فدیا دینا پڑے گا۔ (۲) اسلاف میں یہ سوچ شعوری طور پر کار فرما تھی کہ وہ اپنے سوال کا مدلل ومحکم جواب حاصل کرنے کے لیے دلیل ضرور طلب کیا کرتے تھے۔ جیسا کہ ابن ابو عمار نے حضرت جابر رضی اللہ عنہ سے پوچھا کہ آپ نے یہ رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے؟ اور انھوں نے فرمایا: ہاں! میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے۔ (۳)کسی بڑے سے بڑے عالم سے بھی دلیل طلب کی جا سکتی ہے۔ (۴) دلیل طلب کرنا اس عالم کی توہین نہیں اور نہ اسے اپنی توہین ہی سمجھنا چاہیے بلکہ اسے بخوشی دلیل بیان کر دینی چاہیے۔"}],[4324,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو بھی دانت (سے پھاڑے) والا درندہ ہو، اسے کھانا حرام ہے\"۔\n§وضاحت\n۱؎: مثلاً شیر، چیتا، بھیڑیا اور کتا وغیرہ۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ہر کچلی والا درندہ حرام ہے۔‘‘","f2":"(۱) لگڑ بگڑ کے علاوہ باقی تمام درندوں کا یہی حکم ہے۔ لگڑ بگڑ کو خود رسول اللہ صلی اللہ علیہ وسلم نے اس عام حکم سے مستثنیٰ فرمایا ہے۔ ہر درندے کو کچلی (نوکیلا دانت) لازم ہے۔ اور شکار میں اس کا بہت دخل ہے۔ یہ اوپر نیچے دونوں طرف کل چار ہوتی ہیں۔ درمیان والے چار دانتوں سے آگے اور کچلیوں کے بعد ڈاڑھیں ہوتی ہیں۔ (۴)درندے کو حرام قرار دینے کی وجہ شاید یہ ہو کہ درندے کا گوشت کھانے سے انسان میں بھی درندگی پیدا ہونے کا امکان ہے، پھر یہ درندے جانور کو مار کر اس کا خون بھی پی لیتے ہیں جو کہ حرام ہے۔ گویا ان کی اصل غذا حرام ہے۔ واللہ اعلم"}],[4325,"ابوثعلبہ خشنی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے دانت (سے پھاڑنے) والے تمام درندوں کو کھانے سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"حضرت ابو ثعلبہ خشنی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ہر کچلی والے درندے کو کھانے سے منع فرمایا ہے۔"}],[4326,"ابوثعلبہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوٹا ہوا مال حلال نہیں، دانت (سے پھاڑنے) والا درندہ حلال نہیں، اور «مجثمہ» حلال نہیں\" ۱؎۔\n§وضاحت\n۱؎: مجثمہ ہر وہ جانور جسے باندھ کر اس پر تیر وغیرہ چلایا جائے یہاں تک کہ وہ مر جائے۔","الألباني: صحيح",{"u2":"حضرت ابو ثعلبہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ڈاکا ڈالنا حلال نہیں اور کوئی کچلی والا درندہ بھی حلال نہیں۔ اور باندھ کر نشانوں سے مارا ہوا جانور بھی حلال نہیں۔‘‘","f2":"’’باندھ کر نشانوں سے مارا ہوا جانور‘‘ اس سے مراد وہ جانور ہے جس کو پکڑ کر اس طرح باندھ دیا جائے کہ وہ بھاگ نہ سکے بلکہ حرکت بھی نہ کر سکے اور پھر تیروں وغیرہ کے ساتھ نشانے باندھ باندھ کر اسے تڑپا تڑپا کر مارا جائے۔ یہ طریقہ ظالمانہ ہونے کے ساتھ ساتھ اور شکار کے اصولوں کے بھی خلاف ہے۔ اصول یہ ہے کہ جو جانور پکڑا ہوا ہے، خواہ وہ گھریلو ہو یا جنگلی، اسے لٹا کر ذبح کیا جائے یا کھڑا کر کے نحر کیا جائے۔ اور اگر وہ جانور قابو میں نہ رہے، جیسے جنگلی جانور ہوتے ہیں تو اسے بسم اللہ پڑھ کر تیر یا کتے کے ساتھ شکار کیا جائے۔ ان دو طریقوں کے علاوہ مارا گیا جانور حرام ہوگا۔ اس کا حکم مردار کا ہوگا۔"}],[4327,"جابر رضی اللہ عنہ کہتے کہ رسول اللہ صلی اللہ علیہ وسلم نے جنگ خیبر کے دن گدھوں کا گوشت کھانے سے منع فرمایا اور گھوڑوں کے گوشت کھانے کی اجازت دی۱؎۔\n§وضاحت\n۱؎: یہی جمہور علماء کا مسلک ہے اور یہی صحیح ہے، حنفیہ گھوڑے کے گوشت کو حرام کہتے ہیں۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر کے دن گدھوں کے گوشت سے منع فرمایا اور گھوڑوں کا گوشت کھانے کی اجازت دی۔","f2":"جمہور اہل علم اسی بات کے قائل ہیں کہ گھوڑا حلال جانور ہے کیونکہ اس کی حلت کی روایات صریح ہیں اور اعلیٰ درجے کی صحیح ہیں۔ ائمہ میں سے صرف امام ابوحنیفہ رحمہ اللہ گھوڑے کی حرمت کے قائل ہیں لیکن ان کے شاگرد امام ابو یوسف اور امام محمد رحمہ اللہ اس مسئلے میں ان کے ساتھ نہیں، مانعین کی طرف سے یہ معذرت پیش کی گئی ہے کہ وہ گھوڑے کو پلید نہیں سمجھتے، بلکہ قابل احترام ہونے کی وجہ سے حرام سمجھتے ہیں کیونکہ وہ جہاد میں استعمال ہوتا ہے۔ اگر گھوڑے ذبح کر کے کھائے جائیں تو جہاد کے لیے گھوڑوں کی قلت ہو جائے گی۔ ان کی طرف سے ایک وجہ یہ بھی بیان کی گئی ہے کہ گھوڑا جنسی لحاظ سے گدھے اور خچر کا ساتھی ہے۔ قرآن مجید میں بھی ان تینوں کا اکٹھا ذکر کیا گیا ہے۔\n{وَّ الْخَیْلَ وَ الْبِغَالَ وَ الْحَمِیْرَ لِتَرْکَبُوْہَا وَ زِیْنَۃً} (النحل ۱۶: ۸)\nان کا مقصد زینت اور سواری بیان کیا گیا ہے نہ کہ کھانا، لہٰذا گھوڑے کو کھانا نہیں چاہیے لیکن یہ بات محل نظر ہے کیونکہ اللہ تعالیٰ نے اونٹ کو کھائے جانے والے جانوروں میں ذکر کیا ہے جبکہ اسے خوراک کی بجائے سواری او ر باربرداری میں بھی یکساں استعمال کیا جاتا ہے، اس لیے صحیح بات یہی ہے کہ گھوڑا حلال ہے۔ اگر ضرورت پڑ جائے تو اسے کھایا جا سکتا ہے۔ ہاں، جہاد کے لیے قلت کا خطرہ ہو تو پھر گھوڑے نہ کھائے جائیں لیکن آج کل تو جہاد میں گھوڑوں کا استعمال نہ ہونے کے برابر ہے، لہٰذا وہ وجہ بھی ختم ہوگئی جس کی بنا پر امام صاحب اس کے نہ کھانے کے قائل تھے۔ گویا اب تو اس کی حلت پر ’’اجماع‘‘ ہوگیا ہے۔"}],[4328,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم نے ایک ایسی بات سے روک دیا جو ہمارے لیے نفع بخش اور مفید تھی، آپ کا حکم سر آنکھوں پر، آپ صلی اللہ علیہ وسلم نے ہمیں زمین کو اس کی کچھ پیداوار کے بدلے کرائے پر دینے سے منع فرمایا۔ ابراہیم بن مہاجر نے ابوحصین کی متابعت کی ہے (ان کی روایت آگے آ رہی ہے)۔\nجابر رضی اللہ عنہ کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے گھوڑے کا گوشت کھلایا ۱؎ اور گدھوں کے گوشت سے منع فرمایا۔\n§وضاحت\n۱؎: یعنی: کھانے کی اجازت دی، جیسا کہ پچھلی روایت میں ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں گھوڑے کا گوشت کھانے دیا اور گدھے کے گوشت سے روک دیا۔"}],[4329,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جنگ خیبر کے دن ہمیں گھوڑے کا گوشت کھلانا اور گدھوں کے گوشت کھانے سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر کی جنگ کے دن ہمیں گھوڑے کا گوشت کھانے دیا اور گدھے کے گوشت سے روک دیا۔"}],[4330,"جابر رضی اللہ عنہ کہتے ہیں کہ ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں گھوڑے کا گوشت کھاتے تھے۔","الألباني: صحيح الإسناد",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں گھوڑے کا گوشت کھایا کرتے تھے۔"}],[4331,"خالد بن ولید رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"گھوڑے، خچر اور گدھے کا گوشت کھانا حلال نہیں\"۔","الألباني: ضعيف",{"u2":"حضرت خالد بن ولید رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’گھوڑے، خچر اور گدھے کا گوشت کھانا جائز نہیں۔‘‘","f2":"علامہ سندھی فرماتے ہیں کہ امام نووی رحمہ اللہ نے فرمایا ہے: اس بات پر علماء کا اتفاق ہے کہ یہ روایت ضعیف ہے۔ امام نسائی رحمہ اللہ نے سنن کبریٰ میں فرمایا ہے: اس سے پہلے آنے والی حدیث زیادہ صحیح ہے۔ اگر یہ صحیح بھی ہو تو یہ منسوخ ہے کیونکہ جواز کی روایت میں اجازت دینے کے الفاظ اس کے منسوخ ہونے کی تائید کرتے ہیں۔ دیکھیے: (التعلیقات السلفیۃ علی سنن النسائی: ۴/ ۶۰۳) یہ حدیث کسی بھی لحاظ سے جواز کی روایات کا مقابلہ نہیں کر سکتی۔"}],[4332,"خالد بن ولید رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے گھوڑے، خچر اور گدھے اور دانت والے ہر درندے کا گوشت کھانے سے منع فرمایا۔","الألباني: ضعيف",{"u2":"حضرت خالد بن ولید رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے گھوڑے، خچر، گدھے اور کچلی والے درندے کا گوشت کھانے سے منع فرما دیا۔","f2":"یہ روایت امام ابوحنیفہ رحمہ اللہ کے قول سے مطابقت نہیں رکھتی کیونکہ ان کے نزدیک گھوڑا جہاد میں استعمال ہونے کی وجہ سے حرام ہے، اس لیے اس کا گوشت نہیں کھایا جائے گا مگر اس حدیث میں گھوڑے کو خچر، گدھے اور درندوں کے مشابہ قرار دیا گیا ہے۔ گویا یہ پلید ہے۔ دونوں باتوں میں بہت فرق ہے۔ حدیث کی حیثیت پر سابقہ حدیث میں بھی بحث ہو چکی ہے۔"}],[4333,"جابر رضی اللہ عنہ کہتے ہیں کہ ہم لوگ گھوڑوں کا گوشت کھاتے تھے، عطاء کہتے ہیں: میں نے کہا: خچر؟ کہا: نہیں ۱؎۔\n§وضاحت\n۱؎: امام نسائی نے پہلے گھوڑے کی حلت سے متعلق باب میں صحیح احادیث کی تخریج کی پھر اس کی حرمت سے متعلق باب میں دو حدیث ذکر کی، جس کی سند میں دو ضعیف راوی ہیں، اور آخر میں جابر رضی اللہ عنہ کے اس اثر کو ذکر کر کے اس بات کو راجح قرار دیا کہ گھوڑے کا گوشت حلال ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت جابر رضی اللہ عنہ نے فرمایا: ہم گھوڑے کا گوشت کھاتے تھے۔ عطاء (شاگرد) نے کہا: خچر کا بھی؟ فرمایا: نہیں۔"}],[4334,"علی رضی اللہ عنہ نے ابن عباس رضی اللہ عنہما سے کہا: نبی اکرم صلی اللہ علیہ وسلم نے خیبر کے دن نکاح متعہ ۱؎ سے اور گھریلو گدھوں کے گوشت سے منع فرمایا۔\n§وضاحت\n۱؎: نکاح متعہ یعنی وقتی نکاح جو جاہلیت میں کچھ پیسوں کے بدلے کیا جاتا تھا، شروع اسلام میں یہ حلال تھا، پھر جنگ خیبر کے دن ہمیشہ کے لیے حرام کر دیا گیا۔ اس حدیث میں خاص توجہ کی چیز یہ ہے کہ شیعہ متعہ کو اب بھی حلال مانتے ہیں جب کہ آخری ممانعت کی حدیث علی رضی اللہ عنہ ہی سے ہے۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ نے حضرت ابن عباس رضی اللہ عنہ سے فرمایا: نبی اکرم صلی اللہ علیہ وسلم نے غزوئہ خیبر کے دن نکاح متعہ اور گھریلو گدھوں کے گوشت سے منع فرما دیا تھا۔","f2":"تفصیل کے لیے دیکھیے، حدیث: ۳۳۶۷۔"}],[4335,"علی بن ابی طالب رضی اللہ عنہ کہتے ہیں کہ جنگ خیبر کے دن رسول اللہ صلی اللہ علیہ وسلم نے عورتوں کے ساتھ نکاح متعہ اور گھریلو گدھوں کے گوشت (کھانے)سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت علی بن ابی طالب رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے خیبر کے دن عورتوں کے ساتھ نکاح متعہ کرنے اور گھریلو گدھوں کا گوشت کھانے سے روک دیا تھا۔"}],[4336,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر کے دن پالتو گدھوں سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر کے دن گھریلو گدھوں سے منع فرما دیا تھا۔"}],[4337,"اس سند سے بھی ابن عمر رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم سے اسی جیسی روایت کرتے ہیں، اس میں انہوں خیبر کا ذکر نہیں کیا۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت ابن عمر رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے ایسی ہی حدیث ذکر فرمائی ہے مگر اس میں خیبر کا ذکر نہیں کیا۔"}],[4338,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر کے دن پالتو گدھوں کے گوشت (پکا ہوا ہو یا غیر پکا ہوا) سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت براء رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر کے دن گھریلو گدھوں کے گوشت سے روک دیا تھا۔ بھنا ہوا یا کچا۔"}],[4339,"عبداللہ بن ابی اوفی رضی اللہ عنہ کہتے ہیں کہ جنگ خیبر کے دن ہم نے گاؤں سے باہر کچھ گدھے پکڑ کر پکائے، اتنے میں نبی اکرم صلی اللہ علیہ وسلم کے منادی نے آواز لگائی کہ رسول اللہ صلی اللہ علیہ وسلم نے (گھریلو) گدھوں کے گوشت کو حرام قرار دیا ہے، لہٰذا تم لوگ ہانڈیاں الٹ دو، چنانچہ ہم نے ہانڈیاں الٹ دیں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن ابی اوفیٰ رضی اللہ عنہ نے فرمایا: ہم نے خیبر کے دن بستی سے باہر کچھ گدھے پکڑ لیے اور ان کا سالن پکایا، پھر نبی اکرم صلی اللہ علیہ وسلم کی طرف سے ایک اعلان کرنے والے نے اعلان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے گدھے کے گوشت کو حرام قرار دے دیا ہے، لہٰذا گدھے کے گوشت والی ہانڈیاں الٹ دو۔ ہم نے الٹا دیں۔","f2":"(۱) گھریلو گدھے حرام ہیں، نیز معلوم ہوا کہ جس جانور یا پرندے کا گوشت کھانا حرام ہے، اس جانور یا پرندے پر اللہ کا نام لے کر بھی ذبح کیا جائے تب بھی وہ حرام ہی رہتا ہے کیونکہ صحابہ کرام رضی اللہ عنہم نے جو گدھوں کا گوشت پکانا شروع کیا ہوا تھا، انھیں اللہ کے نام پر ہی ذبح کیا گیا تھا۔ (۲) اگر کوئی پلید چیز، کسی پاک چیز کے ساتھ لگ جائے تو اس کی نجاست صرف ایک بار دھونے سے زائل ہو جاتی ہے۔ ہاں، اگر شریعت ایک سے زیادہ بار دھونے کا مطالبہ کرے تو، پھر شریعت مطہرہ کا تقاضا پورا کرنا ضروری ہوگا۔ (۳) اشیاء میں اصل اباحت (حلال اور جائز ہونا) ہے۔ یہی وجہ ہے کہ صحابہ کرام رضی اللہ عنہم نے بلا تامل گدھے ذبح کر کے ان کا گوشت پکانا شروع کر دیا، حالانکہ رسول اللہ صلی اللہ علیہ وسلم بھی ان میں موجود تھے لیکن انھوں نے اس سلسلے میں آپ سے کوئی بات کی نہ مشورہ ہی لیا کیونکہ ان کے ذہنوں میں یہی بات راسخ تھی کہ چیزیں دراصل حلال ہی ہوتی ہیں، البتہ حرمت کی دلیل ہوا کرتی ہے۔ (۵) امیر، مسئول اور ذمہ دار شخص کی ذمہ داری ہے کہ وہ اپنے ماتحت اور مامورین کے حالات معلوم کرے، ان کے مسائل اور ان کی مشکلات حل کرے۔ مزید برآں یہ کہ اگر ان میں کوئی غیر رعی معاملہ دیکھے تو خود اس کی اصلاح کرے یا اپنے کسی نمائندے کے ذریعے اس کی اصلاح کرائے تاکہ ایسا نہ ہو کہ غیر شرعی معاملہ پر خاموشی کو لوگ جائز سمجھنا شروع کر دیں اور اس طرح ایک ناجائز کام محض غفلت سے جائز قرار پائے۔ (۶) ’’ہم نے الٹا دیں‘‘ یعنی ہم نے وہ گوشت باہر پھینک دیا اور ضائع کر دیا۔ اس سے ان لوگوں کی تردید ہوتی ہے جن کا خیال ہے کہ گدھے بذات خود حرام نہیں مگر چونکہ لوگوں نے آپ کی اجازت اور تقسیم کے بغیر گدھے ذبح کر لیے تھے جبکہ ان میں سے خمس بھی نہیں دیا گیا تھا، اس لیے آپ نے بطور سزا ہانڈیاں الٹانے کا حکم دیا تھا، حالانکہ اگر یہ بات ہوتی تو گوشت ضائع نہ کیا جاتا بلکہ اسے بحق سرکار ضبط کر لیا جاتا۔ حلال چیز کو ضائع کرنا حرام ہے۔"}],[4340,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم صبح کے وقت خیبر پہنچے اور وہ سب (خیبر والے) ہماری طرف نکلے تھے، ان کے ساتھ کدال (بیلچے)تھے، جب انہوں نے ہمیں دیکھا تو کہا: محمد اور فوج، اور جلدی جلدی واپس قلعے میں چلے گئے، یہ دیکھ کر رسول اللہ صلی اللہ علیہ وسلم نے اپنے ہاتھ اٹھائے، پھر فرمایا: \"«اللہ أكبر اللہ أكبر»، خیبر کا برا ہوا، جب ہم کسی قوم کے میدان میں اترتے ہیں تو ان لوگوں کی صبح بہت بری ہوتی ہے جنہیں تنبیہ کی جا چکی ہے\"، وہاں کچھ گدھے ملے جنہیں ہم نے پکایا، اتنے میں نبی اکرم صلی اللہ علیہ وسلم کے منادی نے آواز لگائی: کہا: اللہ تعالی اور اس کے رسول تمہیں گدھوں کے گوشت سے منع کرتے ہیں اس لیے کہ یہ (یعنی گوشت) «رجس» (ناپاک) ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صبح کے وقت خیبر پر حملہ کیا جبکہ وہ اپنی کدالیں لے کر (کام کاج کے لیے) ہماری طرف آ رہے تھے۔ جونہی انھوں نے ہمیں دیکھا، شور مچا دیا: محمد(صلی اللہ علیہ وسلم) اور اس کا لشکر آگیا۔ اور وہ مڑ کر قلعے کی طرف بھاگے۔ رسول اللہ صلی اللہ علیہ وسلم نے (از راہ تشکر و دعا) اپنے مبارک ہاتھ اٹھائے اور فرمایا: ’’اللہ اکبر! اللہ اکبر! خیبر تباہ ہوگیا۔ ہم جب کسی قوم کے علاقے میں آ دھمکتے ہیں تو ان ڈرائے ہوئے لوگوں کا بہت برا حال ہوتا ہے۔‘‘ ہم نے وہاں گدھے پکڑ لیے اور ان کو پکا لیا تو نبی اکرم صلی اللہ علیہ وسلم کے منادی نے اعلان کرتے ہوئے کہا: اللہ تعالیٰ اور اس کے رسول مکرم(صلی اللہ علیہ وسلم) تمھیں گدھوں کے گوشت سے روکتے ہیں کیونکہ وہ پلید (حرام) ہیں۔","f2":"(۱) ’’شور مچا دیا‘‘ کیونکہ انھوں نے مدینہ منورہ میں نبی صلی اللہ علیہ وسلم اور آپ کے ساتھیوں کو دیکھا ہوا تھا۔ (۲) ’’ہاتھ اٹھائے‘‘ ممکن ہے نعرہ تکبیر (اللہ اکبر) لگانے کے لیے ہاتھ اٹھائے ہوں، جیسے نماز کے شروع میں اٹھائے جاتے ہیں یا اس سے اوپر۔ (۳) ’’خیبر تباہ ہوگیا‘‘ یا خیبر تباہ ہو جاے‘‘ دونوں معانی ہو سکتے ہیں بطور فال فرما دیا یا بطور پیش گوئی یا یہ دعا ہے کہ خیبر تباہ ہو جائے۔ (۴) ’’وہ پلید ہیں‘‘ مطلب یہ کہ گدھوں کا گوشت حرام ہے۔ ویسے ان پر سواری کرنا جائز ہے، البتہ گدھے کے پیسنے، لعاب اور جوٹھے وغیرہ کی بابت حدیث میں کسی قسم کی کوئی کراحت نہیں ملتی۔ ظن غالب یہی ہے کہ یہ چیزیں پلید نہیں مزید برآں یہ کہ رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنہم نے بکثرت گدھے اور خچر پر سواری کی ہے۔ اگر ان کا پسینہ، لعاب اور جھوٹا وغیرہ پلید ہوتا تو رسول اللہ صلی اللہ علیہ وسلم ضرور اس کی وضاحت فرماتے۔ واللہ اعلم! اس مسئلے کی مزید تفصیل کے لیے دیکھیے: (سنن النسائی، مترجم: ۱/ ۳۱۹، ۳۲۰، مطبوعہ دارالسلام)"}],[4341,"ابوثعلبہ خشنی رضی اللہ عنہ کہتے ہیں کہ وہ لوگ (صحابہ کرام) رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوہ کے لیے خیبر گئے، لوگ بھوکے تھے، انہیں وہاں گھریلو گدھوں میں سے کچھ گدھے مل گئے، لوگوں نے ان میں سے کچھ ذبح کیے۔ اس کا ذکر نبی اکرم صلی اللہ علیہ وسلم سے کیا گیا تو آپ نے عبدالرحمٰن بن عوف رضی اللہ عنہ کو حکم دیا۔ انہوں نے لوگوں میں اعلان کیا: سنو! پالتو گدھوں کا گوشت اس شخص کے لیے حلال نہیں جو گواہی دے کہ میں اللہ کا رسول ہوں ۱؎۔\n§وضاحت\n۱؎: یعنی مسلمان کے لیے گدھا کا گوشت کھانا حلال نہیں۔","الألباني: صحيح لغيره",{"u2":"حضرت ابو ثعلبہ خشنی رضی اللہ عنہ نے بیان فرمایا: لوگ جہاد کرنے کی خاطر رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خیبر کی طرف گئے۔ لوگوں کو اس وقت بہت بھوک لگی تھی۔ وہاں لوگوں نے گھریلو گدھے پائے تو انھوں نے ان کو ذبح کر لیا۔ یہ بات نبی اکرم صلی اللہ علیہ وسلم سے ذکر کی گئی تو آپ نے حضرت عبدالرحمن بن عوف کو حکم دیا اور انھوں نے لوگوں میں اعلان کیا: خبردار! گھریلو گدھوں کا گوشت کسی ایسے شخص کے لیے حلال نہیں جو میری رسالت کی گواہی دیتا ہے۔"}],[4342,"ابوثعلبہ خشنی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دانت (سے پھاڑ نے) والے تمام درندوں اور گھریلو گدھوں کا گوشت کھانے سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ابو ثعلبہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہر کچلی والے درندے اور گھریلو گدھوں کا گوشت کھانے سے منع فرمایا ہے۔","f2":"گھریلو گدھوں سے مراد وہ گدھے ہیں جنھیں لوگ گھروں میں رکھتے ہیں۔ گھریلو کی صراحت اس لیے کہ جنگلی گدھا حرام نہیں جیسا کہ آئندہ باب میں آرہا ہے۔"}],[4343,"جابر رضی اللہ عنہ کہتے ہیں کہ غزوہ خیبر کے دن ہم نے گھوڑوں اور نیل گائے کا گوشت کھایا، اور ہمیں نبی اکرم صلی اللہ علیہ وسلم نے (گھریلو) گدھے (کے گوشت کھانے) سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ نے فرمایا: ہم نے خیبر کے دن گھوڑوں اور جنگلی گدھوں کا گوشت کھایا، البتہ نبی اکرم صلی اللہ علیہ وسلم نے ہمیں گدھے کا گوشت کھانے سے منع فرما دیا۔","f2":"جنگلی گدھا صرف نام کا گدھا ہوتا ہے۔ اس کے صرف گھر گدھے کی طرح ہوتے ہیں۔ ورنہ حقیقتاً وہ جنگلی گائے ہے۔ شکل وصورت کے لحاظ سے بھی گائے ہوتی ہے۔ صرف کھروں کی وجہ سے اسے جنگلی گدھا کہہ دیا جاتا ہے۔ جنگلی گائے ایک خوبصورت جانور ہے بلکہ خوبصورتی میں ضرب المثل ہے۔ یہ قطعاً حلال ہے۔"}],[4344,"عمیر بن سلمہ ضمری رضی اللہ عنہ کہتے ہیں کہ اس دوران جب کہ ہم نبی اکرم صلی اللہ علیہ وسلم کے ساتھ روحاء کے پتھروں میں چل رہے تھے اور لوگ احرام باندھے ہوئے تھے کہ اچانک ایک زخمی نیل گائے ملی، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے چھوڑ دو ممکن ہے اسے زخمی کرنے والا آئے\"، اتنے میں قبیلہ بہز کا ایک شخص آیا، اسی نے اس کو زخمی کیا تھا، وہ بولا: اللہ کے رسول! آپ اس نیل گائے کو لے لیجئے تو آپ نے ابوبکر رضی اللہ عنہ کو حکم دیا کہ وہ اسے لوگوں میں بانٹ دیں۔","الألباني: صحيح الإسناد",{"u2":"حضرت عمیر بن سلمہ ضمری رضی اللہ عنہ سے روایت ہے کہ ایک دفعہ ہم نبی اکرم صلی اللہ علیہ وسلم کے ساتھ روحاء کے کسی مقام پر تھے۔ سب لوگ محرم تھے۔ انھوں نے ایک زخمی جنگلی گدھا دیکھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اسے کچھ نہ کہو حتی کہ اس کو شکار کرنے والا آجائے۔‘‘ تھوڑی دیر بعد بہز قبیلے کا وہ آدمی بھی آگیا جس نے اسے زخمی کیا تھا۔ وہ کنے لگا: اے اللہ کے رسول! آپ اس گدھے کو جو چاہیں کیجئے! رسول اللہ صلی اللہ علیہ وسلم نے حضرت ابوبکر رضی اللہ عنہ کو حکم دیا کہ اسے لوگوں میں تقسیم کر دیں۔","f2":"(۱) شکاری شخص ہی اپنے مارے یا زخمی کیے ہوئے شکار کا مالک ہوتا ہے۔ حدیث میں مذکور، رسول اللہ صلی اللہ علیہ وسلم کے الفاظ: دَعُوہُ فَیُوشِکَ صَاحِبُہٗ أَنْ یَّأْتِیَہٗ اسی بات پر دلالت کرتے ہیں۔ (۲)احرام والے شخص کے لیے شکار کی طرف اشارہ کرنا، شکار کو دوڑانا یا شکار کرنا وغیرہ سب کچھ ناجائز ہے۔ ہاں،اگر غیر محرم شخص نے اپنے لیے شکار کیا ہو، جبکہ اس شکار کرنے کرانے میں اس (محرم) کا کوئی عمل دخل نہ ہو تو وہ اسے کھا سکتا ہے۔ اور اگر کوئی عمل دخل ہو تو پھر کھا بھی نہیں سکتا۔ (۳) یہ حدیث مبارکہ اس بات پر بھی دلالت کرتی ہے کہ کئی لوگوں کو مشترکہ طور پر ایک چیز ہبہ کی جا سکتی ہے جیسا کہ اس ’’بہزی‘‘ شخص نے ایک جنگلی گدھا، رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ کرام کو مشترکہ طور پر ہبہ کیا تھا۔ بعد ازاں رسول اللہ صلی اللہ علیہ وسلم نے سیدنا ابوبکر صدیق رضی اللہ عنہ کو اسے لوگوں میں تقسیم کرنے کا حکم دیا۔"}],[4345,"ابوقتادہ رضی اللہ عنہ کہتے ہیں کہ انہوں نے ایک نیل گائے شکار کیا اور اسے اپنے ساتھیوں کے پاس لے کر آئے، وہ لوگ احرام باندھے ہوئے تھے اور میں حلال(یعنی احرام سے باہر) تھا تو ہم نے اس میں سے کھایا، پھر ہم میں سے ہر ایک نے دوسرے سے کہا: ہم اس کے متعلق رسول اللہ صلی اللہ علیہ وسلم سے پوچھ لیتے تو بہتر ہوتا، چنانچہ ہم نے آپ صلی اللہ علیہ وسلم سے پوچھا، تو آپ نے فرمایا: \"تم نے ٹھیک کیا\"، پھر فرمایا: \"کیا تم لوگوں کے پاس اس میں سے کچھ ہے؟\" ہم نے کہا: جی ہاں، آپ نے فرمایا: \"ہمیں بھی دو\"، تو ہم اس میں سے کچھ گوشت آپ کے پاس لے آئے، آپ نے اس میں سے کھایا حالانکہ آپ احرام باندھے ہوئے تھے۔","الألباني: صحيح",{"u2":"حضرت ابوقتادہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے ایک جنگلی گدھا شکار کیا۔ میں اسے لے کر اپنے ساتھیوں کے پاس آیا۔ وہ سب محرم تھے۔ صرف میں محرم نہیں تھا۔ ہم سب نے اس میں سے کچھ گوشت کھا لیا، پھر ہم ایک دوسرے سے کہنے لگے: اگر ہما س کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے پوچھ لیں (تو بہتر ہے)۔ ہم نے آپ سے پوچھا۔ آپ نے فرمایا: ’’تم نے اچھا کیا۔‘‘ پھر فرمایا: ’’کیا تمھارے پاس اس کا کچھ گوشت باقی ہے؟‘‘ ہم نے کہا: جی ہاں! آپ نے فرمایا: ’’کچھ ہمیں بھی بھیجو!‘‘ ہم نے آپ کو بھیجا۔ آپ نے اسے کھایا، حالانکہ آپ محرم تھے۔","f2":"غیر محرم کا اپنے لیے کیا ہوا شکار محرم کے لیے کھانا جائز ہے بشرطیکہ اس نے کوئی تعاون نہ کیا ہو حتی کہ اشارہ تک نہ کیا ہو، نیز شکار کرتے وقت غیر محرم کی نیت محرمین کے لیے شکار کی نہ ہو۔ بلکہ وہ شکار اپنے لیے کرے، پھر بے شک وہ اس میں سے کچھ گوشت کسی محرم کو دے دے۔"}],[4346,"زہدم سے روایت ہے کہ ابوموسی رضی اللہ عنہ کے پاس ایک مرغی لائی گئی تو لوگوں میں سے ایک شخص وہاں سے ہٹ گیا، ابوموسی اشعری رضی اللہ عنہ نے پوچھا: کیا بات ہے؟ وہ بولا: میں نے اسے دیکھا کہ وہ کوئی چیز کھا رہی تھی تو میں نے اس کو گندہ سمجھا اور قسم کھا لی کہ میں اسے نہیں کھاؤں گا، ابوموسی اشعری رضی اللہ عنہ نے کہا: قریب آؤ اور کھاؤ، میں نے رسول اللہ صلی اللہ علیہ وسلم کو اسے کھاتے دیکھا ہے، اور اسے حکم دیا کہ وہ اپنی قسم کا کفارہ ادا کرے۔","الألباني: صحيح",{"u2":"حضرت زہدم سے روایت ہے کہ حضرت ابو موسیٰ رضی اللہ عنہ کے پاس ایک مرغ لایا گیا۔ ایک شخص ایک طرف کو ہٹ گیا (باقی لوگ کھانے لگے)۔ حضرت ابو موسیٰ رضی اللہ عنہ کہنے لگے: تجھے کیا ہوا؟ اس نے کہا: میں نے اسے گندگی کھاتے دیکھا ہے، اس لیے مجھے اس سے نفرت ہوگئی ہے۔ تو میں نے قسم کھا لی تھی کہ مرغ کا گوشت نہیں کھاؤں گا۔ حضرت ابو موسیٰ رضی اللہ عنہ فرمانے لگے: قریب آکر کھا کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو مرغ کھاتے دیکھا ہے، پھر آپ نے اسے اپنی قسم کا کفارہ ادا کرنے کو کہا۔","f2":"(۱) رسول اللہ صلی اللہ علیہ وسلم نے خود مرغ کا گوشت کھایا ہے، اس لیے اس کا گوشت کھانے میں قطعاً کوئی حرج نہیں۔ بعض لوگ، اللہ تعالیٰ کی ایسی نعمتوں کے استعمال سے اپنے آپ کو دور رکھتے ہیں کیونکہ وہ اس کو تقویٰ کے منافی خیال کرتے ہیں۔ یاد رہے اللہ تعالیٰ کو ایسا ’’اندھا‘‘ تقویٰ قطعاً مطلوب نہیں جو اسوئہ رسول صلی اللہ علیہ وسلم سے ٹکراتا ہو، بلکہ اصل تقویٰ تو یہ ہے کہ اللہ تعالیٰ کی نعمتوں سے فیض یاب اور مستفید ہو کر، کما حقہ اس کا شکر ادا کیا جائے۔ (۲) اگر کوئی جانور یا پرندہ اس قدر زیادہ گدنگی کھاتا ہو کہ اس کا اثر اس جانور کے دودھ اور گوشت میں محسوس ہو تو ایسا جانور اس وقت تک استعمال میں نہ لایا جائے جب تک اس سے گندگی کا اثر (بو وغیرہ) زائل نہ ہو جائے۔ جب گندگی کا اثر زائل ہو جائے تو ایسے جانور یا پرندے کا گوشت اور دودھ، بلا تردد، استعمال کرنا مباح اور جائز ہے۔ ہاں، البتہ جو جانور تھوڑی بہت گندگی کھاتے رہتے ہوں اور اس کا اثر ان میں نہ ہو تو اس کو کھا لینے میں کوئی حرج نہیں۔ حضرت ابو موسیٰ اشعری رضی اللہ عنہ کا عمل اس کی واضہ دلیل ہے۔ (۳) صاحب طعام کو چاہیے کہ آنے والے شخص کو کھانا کھانے کی دعوت دے، اسے اپنے قریب بٹھائے اور کھانا پیش کرے، خواہ کھانا تھوڑا ہی کیوں نہ ہو۔ جب زیادہ لوگ کھانا کھائیں گے تو اس میں زیادہ برکت ہوگی، اس لیے کہ اجتماعی طور پر کھانا کھانے میں برکت ہی ہوتی ہے۔ (۴) ’’میں نے اسے‘‘ مراد وہ خاص مرغ نہیں جو بھون کر لایا گیا تھا بلکہ عام مراد ہے، یعنی مرغ گندگی کھاتے ہیں، لہٰذا میں اس کا گوشت نہیں کھاؤں گا۔ حضرت ابو موسیٰ رضی اللہ عنہ کا مقصد یہ تھا کہ یہ کوئی نئی بات نہیں۔ مرغ کچھ نہ کچھ گندگی کھاتے ہی ہیں۔ اس کے باوجود میں نے رسول اللہ صلی اللہ علیہ وسلم کو مرغ کھاتے ہوئے دیکھا ہے۔ معلوم ہوا، اتنی گندگی سے کوئی فرق نہیں پڑتا، البتہ اگر کوئی جانور اس قدر گندگی کھاتا ہو کہ اس کے گوشت یا دودھ میں گندگی کا رنگ، بو یا ذائقہ محسوس ہو تو پھر اس جانور کا گوشت کھانا یا اس کا دودھ پینا حرام ہے۔ اس سے کم میں کوئی حرج نہیں۔ واللہ اعلم"}],[4347,"زہدم جرمی کہتے ہیں کہ ہم ابوموسی اشعری رضی اللہ عنہ کے پاس تھے، اتنے میں انہیں ان کا کھانا پیش کیا گیا اور ان کے کھانے میں مرغی کا گوشت پیش کیا گیا، لوگوں میں بنی تیم کا ایک سرخ آدمی تھا جیسے وہ غلام ہو ۱؎، وہ کھانے کے قریب نہیں آیا، اس سے ابوموسی رضی اللہ عنہ نے کہا: قریب آؤ، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اسے کھاتے دیکھا ہے۔\n§وضاحت\n۱؎: اس لیے کہ عام طور پر غلام عجمی ہوتے ہیں جو رومی یا ایرانی اور ترکی ہوتے تھے۔","الألباني: صحيح",{"u2":"حضرت زہدم جرمی سے روایت ہے کہ ہم حضرت ابو موسیٰ رضی اللہ عنہ کے اپس بیٹھے تھے کہ ان کا کھانا پیش تھا۔ حاضرین میں بنو تمیم اللہ کے قبیلے میں سے ایک سرخ رنگ کا شخص تھا۔ ایسے لگتا تھا جیسے وہ غلام ہو۔ وہ کھانے کے قریب نہ آیا۔ حضرت ابوموسیٰ رضی اللہ عنہ نے فرمایا (کھانے کے) قریب ہو۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو مرغ کا گوشت کھاتے دیکھا ہے۔"}],[4348,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے غزوہ خیبر کے دن پنجے والے تمام پرندوں کو کھانے سے اور دانت (سے پھاڑنے)والے تمام درندوں کو کھانے سے روکا۔\n§وضاحت\n۱؎: اور چونکہ مرغی ان میں سے نہیں ہے اس لیے حلال ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ اللہ کے نبی صلی اللہ علیہ وسلم نے خیبر کے دن پنجے کے ساتھ شکار کرنے والے پرندے اور کچلی والے درندے کا گوشت کھانے سے منع فرمایا۔","f2":"ظاہراً تو اس حدیث کا باب سے تعلق نہیں بتنا بلکہ اس کے لیے الگ باب ہونا چاہیے تھا، تاہم یہ کہا جا سکتا ہے کہ مرغ پنجے کے ساتھ شکار کرنے والا پرندہ نہیں، لہٰذا حلال ہے۔"}],[4349,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو بھی انسان کسی گوریا، یا اس سے بھی زیادہ چھوٹی چڑیا کو ناحق قتل کرے گا، اللہ تعالی اس سے اس کے متعلق سوال کرے گا\"، عرض کیا گیا: اللہ کے رسول! اس کا حق کیا ہے؟ آپ نے فرمایا: \"وہ اسے ذبح کرے اور کھائے اور اس کا سر کاٹ کر نہ پھینکے\" ۱؎۔\n§وضاحت\n۱؎: یہ حدیث گرچہ ضعیف ہے، لیکن دیگر دلائل سے گوریا حلال پرندوں میں سے ہے :(دیکھئیے پچھلی حدیث )۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص چڑیا یا اس سے بھی چھوٹے جانور کو ناحق قتل کرے، اللہ تعالیٰ (قیامت کے دن) اس سے اس کے بارے میں پوچھے گا۔‘‘ پوچھا گیا: اے اللہ کے رسول! اس کا حق کیا ہے؟ آپ نے فرمایا: ’’اسے ذبح کر کے کھائے۔ اس کا سر کاٹ کر نہ پھینک دے۔‘‘","f2":"(۱) ’’اس سے بھی چھوٹا جانور‘‘ مثلاً ٹڈی۔ یہ معنی بھی ہو سکتا ہے ’’چڑیا یا اس سے بڑا جانور‘‘ مثلاً: مرغی، کبوتر وغیرہ فَمَا فَوْقَھَا میں یہ دونوں مفہوم پائے جاتے ہیں اور دونوں ہی صحیح ہیں۔ (۲) بعض لوگ شغلاً شکار کرتے ہیں۔ کھانا مقصد نہیں ہوتا بلکہ یا تو کتے بھگانے کا شوق ہوتا ہے یا نشانہ بازی کا اور وہ اپنے شوق کو شکار کی صورت میں پورا کرتے ہیں، یہ شرعاً گناہ ہے۔ کسی بھی جاندار چیز کو بلا وجہ قتل نہیں کیا جا سکتا۔ اگر وہ حلال جانور ہے تو اسے صرف کھانے کے لیے شکار یا ذبح کیا جا سکتا ہے اور اگر وہ حرام جانور ہے تو اس کے نقصان سے بچنے کے لیے ہی اسے مارا جا سکتا ہے۔ یا دوسری معاشی ضروریات کے لیے، مثلاً: کاروبار جیسے ہاتھی کے دانت۔ صرف شوق پورا کرنے کے لیے کسی جاندار کو ضائع نہیں کیا جا سکتا۔"}],[4350,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے سمندر کے پانی کے سلسلے میں فرمایا: \"اس کا پانی پاک ہے اور اس کا مردار حلال ہے\" ۱؎۔\n§وضاحت\n۱؎: سمندر کا مردار حلال ہے اس سے مراد سمندر کے وہ حلال جانور ہیں جو کسی صدمہ سے مر گئے اور سمندر نے ان کو ساحل کی طرف بہا دیا ہو اسی کو قرآن میں: «أحل لكم صيد البحر وطعامه» :(المائدة: 96 ) میں طَعام سے مراد لیا گیا ہے، یاد رہے سمندری جانور وہ کہلاتا ہے جو خشکی میں زندگی نہ گزار سکے جیسے مچھلی۔ مچھلی کی تمام اقسام حلال ہیں، دیگر جانور اگر مضر اور خبیث ہیں یا ان کے بارے میں نص شرعی وارد ہے تو حرام ہیں اگر کسی جانور کا نص شرعی سے نبی اکرم صلی اللہ علیہ وسلم یا صحابہ رضوان اللہ علیہم اجمعین سے کھانا ثابت نہیں ہے، جبکہ وہ جانور ان کے زمانہ میں موجود تھا تو اس کے نہ کھانے کے بارے میں ان کی اقتداء ضروری ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے سمندر کے پانی کے بارے میں فرمایا: ’’سمندر کا پانی طاہر ومطہر ہے اور اس کا جانور بلا ذبح حلال ہے۔‘‘","f2":"(۱) سمندر کا پانی ذائقے کے لحاظ سے عام پانی سے مختلف ہوتا ہے۔ اس میں رہنے والے جانوروں اور سفر کرنے والے انسانوں کی گندگی پانی ہی میں رہتی ہے۔ اگر ان میں سے کوئی مر جائے تو وہ بھی پانی میں ہی گلتا سڑتا ہے۔ اس سے یہ شبہ پڑ سکتا ہے کہ شاید وہ پاک نہ ہو، اس لیے آپ نے یہ ارشاد فرمایا کیونکہ اولاً تو وہ انتہائی کثیر پانی ہے۔ ثانیاً اللہ تعالیٰ نے اپنی قدرت کاملہ سے ایسا انتظام کر رکھا ہے کہ نہ تو پانی متعفن ہوتا ہے اور نہ کوئی آلودگی اپنا اثر چھوڑتی ہے۔ واللہ عزیز حکیم۔ (۲) ’’طاہر ومطہر‘‘ عربی میں لفظ طہور استعمال ہوا ہے۔ اس کے معنی ہیں، خود بھی پاک، دوسری چیزوں کو بھی پاک کرنے والا۔ (۳) ’’بلا ذبح حلال ہے‘‘ عربی میں لفظ مَیْتَۃَ استعمال ہوا ہے، یعنی جو بغیر ذبح کیے مر جائے، مثلاً: جسے شکار کیا جائے یا جو طبعی موت پانی میں مر جائے۔ احناف طبعی موت والے آبی جانور کی حلت کے قائل نہیں لیکن حدیث کے الفاظ عام ہیں۔ اسی طرح یہ حدیث ہر آبی جانور کو شامل ہے۔ امام شافعی رحمہ اللہ اسی کے قائل ہیں جبکہ امام مالک صرف ان آبی جانوروں کو حلال سمجھتے ہیں جن کے نام کے جانور خشکی میں حلال ہیں۔ اور احناف صرف مچھلی کو حلال سمجھتے ہیں، کیونکہ بعض روایات میں مچھلی کا لفظ مذکور ہے لیکن قرآن وحدیث کے الفاظ عام ہیں۔ قرآن مجید کے الفاظ اس مفہوم کو واضح طور پر بیان کرتے ہیں۔ ارشاد باری ہے: {اُحِلَّ لَکُمْ صَیْدُ الْبَحْرِ} (المآئدۃ ۵: ۹۶) (۴) آبی جانوروں کو ذبح کرنے کی ضرورت اس لیے نہیں کہ اس میں خون نہیں ہوتا۔ اور ذبح خون نکالنے کے لیے ہوتا ہے۔ باقی رہا وہ سرخ محلول جو مچھلی وغیرہ سے زخم کے وقت نکلتا ہے تو اس میں خون کی خصوصیات نہیں پائی جاتیں، مثلاً: اسے دھوپ میں رہنے دیا جائے تو وہ سفید ہو جائے گا جبکہ خون تو سیاہ ہو کر جم جاتا ہے اور حرام خون ہی ہے، لہٰذا اسے ذبح کرنے کی ضرورت نہیں۔"}],[4351,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ ہمیں نبی اکرم صلی اللہ علیہ وسلم نے (سریہ فوجی ٹولی میں) بھیجا، ہم تین سو تھے، ہم اپنا زاد سفر اپنی گردنوں پر لیے ہوئے تھے، ہمارا زاد سفر ختم ہو گیا، یہاں تک کہ ہم میں سے ہر شخص کے حصے میں روزانہ ایک کھجور آتی تھی، عرض کیا گیا: ابوعبداللہ! اتنی سی کھجور آدمی کا کیا بھلا کرے گی؟ انہوں نے کہا: ہمیں اس کا فائدہ تب معلوم ہوا جب ہم نے اسے بھی ختم کر دیا، پھر ہم سمندر پر گئے، دیکھا کہ ایک مچھلی ہے جسے سمندر نے باہر پھینک دیا ہے، تو ہم نے اسے اٹھارہ دن تک کھایا۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ نے فرمایا: نبی اکرم صلی اللہ علیہ وسلم نے ہمیں (ساحل سمندر پر) بھیجا۔ ہم تین سو آدمی تھے۔ ہم نے اپنا زادِ راہ اپنی گردنوں پر اٹھایا ہوا تھا۔ وہ بھی ختم ہوگیا حتی کہ ہم میں سے ہر آدمی کو ایک دن میں ایک کھجور ملتی تھی۔ ان سے پوچھا گیا: اے ابوعبداللہ! ایک کھجور آدمی کا کیا گزارا کرتی ہوگی؟ انھوں نے فرمایا: جب کھجوریں بالکل ختم ہوگئیں تو ہمیں اس ایک کھجور کی بھی قدر معلوم ہوتی تھی۔ ہم ساحل سمندر پر پہنچے تو ہم نے ناگہاں وہاں ایک بڑی مچھلی دیکھی جسے سمندر نے باہر پھینک دیا تھا۔ ہم نے اس میں سے اٹھارہ دن کھایا۔","f2":"اس حدیث کی مزید تفصیل آئندہ حدیث میں آرہی ہے۔ اس سے یہ ثابت ہوتا ہے کہ مچھلی حلال ہے، خواہ وہ شکار کی گئی ہو یا اسے سمندر کی لہروں نے باہر پھینک دیا ہو۔ یا وہ سمند پر بے جان تیر رہی ہو۔ کیونکہ سمندر عموماً بے جان مچھلی کو باہر ہی پھینک دیتا ہے۔ زندہ مچھلیاں تو پانی کے ساتھ واپس چلی جاتی ہیں، پھر اتنی بڑی مچھلی کہ جسے تین سو آدمی اٹھارہ دن تک کھاتے رہے ہوں اور وہ پھر بھی ختم نہ ہوئی ہو، زندہ حالت میں ساحل کے قریب نہیں آتی بلکہ گہرے سمندر میں رہتی ہے۔ لازماً اس کی لاش پانی پر تیرتی ہوئی کنارے پر آئی ہوگی۔"}],[4352,"جابر رضی اللہ عنہ کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے تین سو سواروں کے ساتھ بھیجا۔ ہمارے امیر ابوعبیدہ بن جراح رضی اللہ عنہ تھے، ہم قریش کی گھات میں تھے، چنانچہ ہم سمندر کے کنارے ٹھہرے، ہمیں سخت بھوک لگی یہاں تک کہ ہم نے درخت کے پتے کھائے، اتنے میں سمندر نے ایک جانور نکال پھینکا جسے عنبر کہا جاتا ہے، ہم نے اسے آدھے مہینہ تک کھایا اور اس کی چربی کو تیل کے طور پر استعمال کیا، تو ہمارے بدن صحیح ثابت ہو گئے، ابوعبیدہ رضی اللہ عنہ نے اس کی ایک پسلی لی پھر فوج میں سے سب سے لمبے شخص کو اونٹ پر بٹھایا، وہ اس کے نیچے سے گزر گیا، پھر ان لوگوں کو بھوک لگی، تو ایک شخص نے تین اونٹ ذبح کئے، پھر ابوعبیدہ رضی اللہ عنہ نے اسے روک دیا، (سفیان کہتے ہیں: ابوالزبیر جابر رضی اللہ عنہ سے روایت کرتے ہیں)، پھر ہم نے نبی اکرم صلی اللہ علیہ وسلم سے سوال کیا، تو آپ نے فرمایا: \"کیا اس کا کچھ بقیہ تمہارے پاس ہے؟\" پھر ہم نے اس کی آنکھوں کی چربی کا اتنا اتنا گھڑا (بھرا ہوا) نکالا اور اس کی آنکھ کے حلقے میں سے چار لوگ نکل گئے، ابوعبیدہ کے ساتھ ایک تھیلا تھا، جس میں کھجوریں تھیں وہ ہمیں ایک مٹھی کھجور دیتے تھے پھر ایک ایک کھجور ملنے لگی، جب وہ بھی ختم ہو گئی تو ہمیں اس کے نہ ملنے کا احساس ہوا ۱؎۔\n§وضاحت\n۱؎: اس حدیث میں واقعات کی ترتیب آگے پیچھے ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم تین سو اونٹ سواروں کو (ساحل کی طرف) بھیجا۔ ہمارے امیر حضرت ابو عبیدہ بن جراح تھے۔ ہم قریش کے ایک قافلے کی گھات میں تھے۔ ہم ساحل پر جا ٹھہرے۔ ہمیں سخت بھوک کا سامنا تھا حتی کہ ہم پتے کھانے لگے، پھر سمندر (کی لہروں) نے ایک آبی جانور (ساحل پر) پھینک دیا۔ اس کوعنبر کہا جاتا تھا۔ ہم اس سے تقریباً نصف ماہ کھاتے رہے۔ ہم نے اس کی چربی کو بھی خوب استعمال کیا تو ہمارے جسم پہلے کی طرح موٹے تازے ہوگئے۔ حضرت ابوعبیدہ رضی اللہ عنہ نے اس کی ایک پسلی کو کھڑا کیا، پھر لشکر میں سے سب سے اونچا اونٹ اور سب سے لمبا آدمی تلاش کیا۔ وہ آدمی اس اونٹ پر سوار ہو کر پسلی کے نیچے سے صاف گزر گیا۔ (اسی سفر کا واقعہ ہے کہ) پھر لوگ بھوک میں مبتلا ہوئے تو ایک آدمی نے تین اونٹ نحر کیے، پھر انھیں بھوک لگی تو مزید تین اونٹ نحر کر دیے، وہ پھر بھوک کا شکار ہوئے تو اسی نے مزید تین اونٹ نحر کر دیے، وہ پھر بھوک کا شکار ہوئے تو اسی نے مزید تین اونٹ نحر کیے، پھر حضرت ابوعبیدہ رضی اللہ عنہ نے (بحیثیت امیر) اسے روک دیا۔ (راوی حدیث) سفیان نے ابو زبیر سے، انھوں نے حضرت جابر رضی اللہ عنہ سے بیان کیا (انھوں نے فرمایا کہ جب ہم نبی اکرم صلی اللہ علیہ وسلم کے پاس واپس پہنچے اور) ہم نے نبی صلی اللہ علیہ وسلم سے (اس کے متعلق) پوچھا۔ آپ نے فرمایا: ’’کیا تمھارے پاس اس جانور کا کچھ گوشت باقی ہے؟‘‘ (حضرت جابر نے فرمایا:) ہم نے اس آبی جانور کی آنکھوں سے بہت سے مٹکے چربی کے نکالے۔ اور اس کی آنکھ کے گڑھے میں چار آدمی باآسانی اتر گئے۔ اور (اسی سفر کا واقعہ ہے کہ) حضرت ابوعبیدہ رضی اللہ عنہ کے پاس ایک کھجوروں کی تھیلی تھی جس میں سے وہ ہمیں مٹھی مٹھی دیا کرتے تھے، پھر نوبت ایک ایک کھجور تک آگئی۔ جب کھجوریں بالکل ختم ہوگئیں تو (اس وقت) ہمیں ایک کھجور کی قدر وقیمت معلوم ہوتی تھی۔","f2":"(۱) ’’میتۃ البحر‘‘ (دریائی اور سمندری مردار) کے متعلق شریعت کا حکم یہ ہے کہ وہ حلال ہے۔ سابقہ اور اس حدیث میں اس بات کی تصریح موجود ہے کہ وہ مچھلی سمندری لہروں نے باہر پھینکی تھی، یعنی صحابہ کرام رضی اللہ عنہم میں سے کسی نے اسے شکار نہیں کیا تھا۔ مزید برآں یہ بھی کہ اسے ذبح بھی نہیں کیا گیا تھا بلکہ ویسے ہی استعمال کیا تھا۔ تین سو صحابہ کرام رضی اللہ عنہم اٹھارہ دن تک مسلسل اسے کھاتے رہے، بعد ازاں رسول اللہ صلی اللہ علیہ وسلم نے بھی اس میں سے کھایا۔ (۲) حدیث مبارکہ اس بات پر بھی دلالت کرتی ہے کہ ہر چھوٹے بڑے لشکر پر امیر مقرر کرنا چاہیے جو اس لشکر کے لیے درست انتظام کرے، ان کی ضروریات وغیرہ کا خیال رکھے اور انھیں پورا کرنے کی بھر پور کوشش کرے۔ امیر کے لیے یہ بھی مستحب ہے کہ اپنے ساتھیوں کے ساتھ نرمی بریت۔ (۳) امیر لشکر، ان میں سے افضل اور بہتر شخص کو بنانا چاہیے۔ اگر ایسا کرنا ممکن نہ ہو تو پھر ان کے بہترین اور اچھے لوگوں میں سے کسی کو امیر بنایا جائے۔ لوگوں کے لیے ضروری ہے کہ وہ اپنے امیر کے احکام کی تعمیل کریں۔ ہاں، اگر وہ انھیں غیر شرعی حکم دے تو پھر اس کی اطاعت قطعاً جائز نہیں جیسا کہ معروف حدیث ہے: [لَا طَاعَۃَ لِأَحَدٍ فِی مَعْصِیَۃِ اللّٰہِ تَبَارَکَ وَتَعَالٰی] ’’اللہ تبارک و تعالیٰ کی نافرمانی کر کے کسی کی اطاعت جائز نہیں۔‘‘ (سلسلۃ الاحادیث الصحیحۃ، حدیث: ۱۷۹۔ ۱۸۱) (۴) صحابہ کرام رضی اللہ عنہم کے نزدیک دنیاوی مال و متاع اور اس کی آسائشوں کی کوئی حیثیت نہیں تھی۔ انھوں نے یہ اللہ تعالیٰ کی رضا جوئی اور حصول جنت کے لیے ہر قسم کے مصائب کو برداشت کیا… رضی اللہ عنہم … (۵) بھوک، غربت، افلاس اور تنگ دستی کے وقت ہمدردی اور ایثار سے بہت سی مشکلات آسان ہو جاتی ہیں۔ اس حدیث سے اس کی مشروعیت معلوم ہوتی ہے۔ (۶) انسان اپنے قریبی احباب اور دوستوں سے ان کا مال ومتاع مانگ سکتا ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ کرام رضی اللہ عنہم سے فرمایا تھا: ’’اگر تمھارے پاس عنبر مچھلی میں سے کچھ باقی ہو تو مجھے بھی دو۔‘‘ (۷) یہ حدیث مبارکہ دلیل ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاکیزہ دور میں بھی اجتہاد جائز تھا جیسا کہ آج کے دور میں جائز ہے۔ اگلی حدیث: ۴۳۵۹ میں حضرت ابوعبیدہ بن جراح رضی اللہ عنہ کے یہ الفا: [لَا تَأْکُلُوہُ، ثُمَّ قَالَ: جَیْشُ رَسُوْلِ اللّٰہِV، وَفِی سَبِیْلِ اللّٰہِ عَزَّوَجَلَّ وَنَحْنُ مُضْطَرُّونَ کُلُوا بِاسْمِ اللّٰہِ] احکام میں اجتہاد کی بہت واضح اور کھلی دلیل ہیں۔ (۸) ’’اپنی گردنوں پر اٹھایا ہوا تھا‘‘ اس میں اشارہ ہے کہ ہمارے پاس زاد راہ بہت کم مقدار میں تھا۔ اسے اٹھانے کے لیے جانور کی ضرورت نہیں تھی۔ (۹) اس روایت میں واقعات کی ترتیب آگے پیچھے ہے، مثلاً: لشکر کے ساحل پر پہنچنے سے پہلے وہ آبی جانور موجود تھا۔ اس طرح اونٹوں کو نحر کرنے کا واقعہ آبی جانور کے ملنے سے پہلے کا ہے۔ کھجوریں بانٹنے کا واقعہ بھی آبی جانور ملنے سے پہلے کا ہے اگرچہ ذکر آخر میں ہے۔ آبی جانور سے چربی وغیرہ نکالنے کے واقعات بھی ساحل سمندر سے تعلق رکھتے ہیں نہ کہ مدینہ منورہ سے جیسا کہ ظاہراً معلوم ہوتا ہے۔ (۱۰) اونٹ نحر کرنے والے شخص بنو خزرج کے سردار حضرت سعد بن عباد رضی اللہ عنہ کے بیٹے حضرت قیس بن سعد رضی اللہ عنہ تھے۔ جو بہت سخی تھے اور سخی باپ کے بیٹے تھے۔ مذکور ہے جب حضرت سعد رضی اللہ عنہ کو اس واقعہ کا پتا چلا تو بیٹے سے کہا: تم نے اور جانور کیوں نہ ذبح کیے؟ انھوں نے بتایا کہ امیر صاحب نے روک دیا تھا، مبادا تیرے والد محترم ناراض ہوں۔ حضرت سعد رضی اللہ عنہ یہ سن کر غصے میں آگئے اور فوراً ایک بہت بڑا باغ بیٹے کے نام منتقل کر دیا تاکہ کل کو کوئی شخص سخاوت سے نہ روک سکے۔ رضی اللہ عنھما وارضاھم۔ (۱۱) ’’نحر کیے‘‘ نحر کرنا اس طرح ہوتا ہے کہ اونٹ کا بایاں گھٹنا رسی وغیرہ کے ساتھ باندھ دیا جاتا ہے اور پھر جھری کی نوک اس کے لیے (گردن کی نچلی طرف انتہائی نرم گڑھے) میں چبھو دی جاتی ہے۔ اونٹ کو، دوسرے جانوروں کی طرح ذبح نہیں کیا جاتا۔"}],[4353,"جابر رضی اللہ عنہ کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے ابوعبیدہ رضی اللہ عنہ کے ساتھ ایک سریے (فوجی مہم) میں بھیجا، ہمارا زاد سفر ختم ہو گیا، ہمارا گزر ایک مچھلی سے ہوا جسے سمندر نے باہر نکال پھینکا تھا۔ ہم نے چاہا کہ اس میں سے کچھ کھائیں تو ابوعبیدہ رضی اللہ عنہ نے ہمیں اس سے روکا، پھر کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے نمائندے ہیں اور اللہ کے راستے میں نکلے ہیں، تم لوگ کھاؤ، چنانچہ ہم نے کچھ دنوں تک اس میں سے کھایا، پھر جب ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو ہم نے آپ کو اس کی خبر دی، آپ نے فرمایا: \"اگر تمہارے ساتھ (اس میں سے) کچھ باقی ہو تو اسے ہمارے پاس بھیجو\" ۱؎۔\n§وضاحت\n۱؎: گویا کہ آپ صلی اللہ علیہ وسلم نے اس کو حلال قرار دیا تبھی تو اس میں سے طلب فرمایا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حضرت ابوعبیدہ رضی اللہ عنہ کے ماتحت ایک لشکر میں بھیجا۔ ہمارے زاد ختم ہوگئے۔ ہم ایک مچھلی کے پاس سے گزرے جسے سمندر نے (ساحل پر) پھینک دیا تھا۔ ہم نے اس میں سے کھانے کا ارادہ کیا تو حضرت ابوعبیدہ رضی اللہ عنہ نے ہمیں روک دیا، پھر خود ہی کہنے لگے: ہم رسول اللہ صلی اللہ علیہ وسلم کے بھیجے ہوئے ہیں اور اللہ تعالیٰ کے راستے میں آئے ہیں، اس لیے کھا لو۔ ہم کئی دن تک اس میں سے کھاتے رہے۔ جب ہم واپس رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو ہم نے آپ کو اس بات سے مطلع کیا۔ آپ نے فرمایا: ’’اگر تمھارے پاس کچھ گوشت باقی ہے تو ہمارے پاس بھی بھیجو۔‘‘"}],[4354,"جابر رضی اللہ عنہ کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے ابوعبیدہ رضی اللہ عنہ کے ساتھ (ایک فوجی مہم میں) بھیجا، ہم تقریباً تین سو دس لوگ تھے، ہمیں توشہ کے بطور کھجور کا ایک تھیلا دیا گیا، وہ ہمیں ایک ایک مٹھی دیتے، پھر جب ہم اکثر کھجوریں کھا چکے تو ہمیں ایک ایک کھجور دینے لگے، یہاں تک کہ ہم اسے اس طرح چوستے جیسے بچہ چوستا ہے اور اس پر پانی پی لیتے، جب وہ بھی ختم ہو گئی تو ہمیں ختم ہونے پر اس کی قدر معلوم ہوئی، نوبت یہاں تک پہنچی کہ ہم اپنی کمانوں سے پتے جھاڑتے اور اسے چبا کر پانی پی لیتے، یہاں تک کہ ہماری فوج کا نام ہی جیش الخبط (یعنی پتوں والا لشکر) پڑ گیا، پھر جب ہم سمندر کے کنارے پر پہنچے تو ٹیلے کی طرح ایک جانور پڑا ہوا پایا جسے عنبر کہا جاتا ہے، ابوعبیدہ رضی اللہ عنہ نے کہا: مردہ ہے مت کھاؤ، پھر کہا: رسول اللہ صلی اللہ علیہ وسلم کا لشکر ہے اور اللہ تعالی کے راستے میں ہے اور ہم مجبور ہیں، اللہ کا نام لے کر کھاؤ، چنانچہ ہم نے اس میں سے کھایا اور کچھ گوشت بھون کر سکھا کر رکھ لیا، اس کی آنکھ کی جگہ میں تیرہ لوگ بیٹھے، ابوعبیدہ رضی اللہ عنہ نے اس کی پسلی لی پھر کچھ لوگوں کو اونٹ پر سوار کیا تو وہ اس کے نیچے سے گزر گئے، جب ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو آپ نے فرمایا: \"تمہیں کس چیز نے روکے رکھا؟\" ہم نے عرض کیا: ہم قریش کے قافلوں کا پیچھا کر رہے تھے، پھر ہم نے آپ سے اس جانور (عنبر مچھلی) کا معاملہ بیان کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ رزق ہے جو اللہ تعالی نے تمہیں بخشا ہے، کیا اس میں سے کچھ تمہارے پاس ہے؟\" ہم نے عرض کیا: جی ہاں۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حضرت ابوعبیدہ رضی اللہ عنہ کے ساتھ بھیجا۔ ہم تین سو دس سے زائد تھے۔ آپ نے ہمیں کھجوروں کی ایک بوری بطور زاد راہ دی تھی۔ حضرت ابوعبیدہ ہمیں روزانہ ایک ایک مٹھی کھجوریں دیتے تھے۔ جب ہم نے انھیں تقریباً ختم کر دیا تو وہ ہمیں ایک ایک کھجور دینے لگے حتی کہ ہم اسے بچوں کی طرح چوستے رہتے۔ اوپر سے پانی پی لیتے۔ جب کھجوریں بالکل ختم ہوگئیں تو ایک کھجور کا نہ ملنا بھی ہم کو محسوس ہوتا تھا حتی کہ ہم اپنی لاٹھیوں سے درختوں کے پتے جھاڑ لیتے اور انھیں پھانک لیتے، پھر اوپر سے پانی پی لیتے حتی کہ ہمارے اس لشکر کا نام ہی پتوں والا لشکر رکھ دیا گیا، پھر ہم ساحل پر پہنچے تو وہاں ٹیلے جیسا ایک آبی جانور پڑا تھا جسے عنبر کہا جاتا تھا۔ حضرت ابوعبیدہ نے فرمایا: یہ مرا ہوا ہے، لہٰذا اسے نہ کھاؤ، پھر خود ہی کہنے لگے: ہم اللہ کے رسول صلی اللہ علیہ وسلم کی فوج ہیں اور اللہ تعالیٰ کے راستے میں جا رہے ہیں، پھر ہم لاچار بھی ہیں، اس لیے اللہ کا نام لے کر کھاؤ۔ ہم نے کچھ تو کھایا، کچھ سکھا لیا۔ اس جانور کی آنکھ کے گڑھے میں تیرہ آدمی (آرام سے) بیٹھ گئے، پھر حضرت ابوعبیدہ نے اس کی پسلی لی، پھر ایک موٹے اونچے اونٹ پر پالان کس کر (ایک لمبا تڑنگا آدمی بٹھا کر) اسے پسلی کے نیچے سے گزارا تو وہ صاف گزر گیا۔ جب ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تو آپ نے فرمایا: ’’تم اتنے دن کہاں رکے رہے؟‘‘ ہم نے عرض کی: ہم قریش کے تجارتی قافلوں کو تلاش کرتے رہے، پھر ہم نے آپ کے سامنے اس آبی جانور کا ذکر کیا تو آپ نے فرمایا: ’’وہ رزق تھا جو اللہ تعالیٰ نے تمھارے لیے مہیا فرمایا۔ کیا تمھارے پاس اس کا کچھ گوشت ہے؟‘‘ ہم نے کہا: جی ہاں۔","f2":"(۱) تین سو دس سے زائد یعنی تین سو بیس سے کم۔ معلوم ہوا سابقہ روایات میں کسر گرا کر تین سو کہا گیا ہے۔ (۲) ’’تیرہ آدمی‘‘ پچھلی روایت میں ’’چار‘‘ کا ذکر ہے لیکن چار میں تیرہ کی نفی نہیں۔ چار چلتے پھرتے ہوئے گے اور تیرہ جڑ کر بیٹھے ہوں گے۔ واللہ اعلم! (۳) ’’عنبر‘‘ یہ عظیم الشان مچھلی ہوتی ہے جو جہاز کو ٹکر مار دے تو اسے بھی توڑ دیتی ہے۔ اللہ تعالیٰ ہی جانتا ہے کہ سمندر میں کیسی کیسی عظیم الشان مخلوقات پوشیدہ ہیں۔"}],[4355,"عبدالرحمٰن بن عثمان رضی اللہ عنہ سے روایت ہے کہ ایک طبیب نے رسول اللہ صلی اللہ علیہ وسلم کے پاس دوا میں مینڈک کا تذکرہ کیا تو آپ نے اسے مار ڈالنے سے روکا ۱؎۔\n§وضاحت\n۱؎: یعنی آپ صلی اللہ علیہ وسلم نے مینڈک کو مار کر دوا میں استعمال کرنے سے روکا، کیونکہ یہ نجس و ناپاک ہے اور ناپاک چیزوں سے علاج حرام ہے، نیز مینڈک کو مارنے سے روکنے سے ثابت ہوتا ہے کہ اس کا کھانا بھی حرام ہے، کیونکہ کھانے کے لیے بھی قتل کرنا پڑتا ہے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن عثمان رضی اللہ عنہ سے منقول ہے کہ ایک طبیب نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے کسی دوائی میں مینڈک ڈالنے کا ذکر کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے مینڈک کے قتل سے منع فرما دیا۔","f2":"(۱) مینڈک کے متعلق حکم شریعت یہ ہے کہ وہ حرام ہے۔ بوقت ضرورت بھی رسول اللہ صلی اللہ علیہ وسلم نے اس کے استعمال کی اجازت نہیں دی۔ آپ کا اجازت نہ دینا ہی اس کی حرمت کی دلیل ہے۔ (۲) مینڈک اگرچہ آبی جانور ہے لیکن یہ پانی سے باہر بھی زندہ رہ سکتا ہے بلکہ عرصہ دراز تک باہر پھرتا رہتا ہے، لہٰذا اسے آبی جانوروں والا حکم نہیں دیا جاسکتا، یعنی اسے حلال نہیں کہا جائے گا۔ (۳) ’’منع فرما دیا‘‘ مقصد یہ ہے کہ مینڈک کو دوا کے طور پر استعمال نہیں کیا جا سکتا کیونکہ قتل کیے بغیر تو اسے دوا میں ڈالنے سے رہے۔ جب قتل حرام ہے تو اس کو بطور دوا استعمال کرنا بھی حرام ہے کیونکہ یہ پلید جانور ہے یا کم از کم قابل نفرت تو ضرور ہے۔ تبھی آپ نے اس کے قتل سے منع فرمایا۔ قتل سے نہی بھی حرمت کی علامت ہے۔"}],[4356,"عبداللہ بن ابی اوفی رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سات جنگیں کیں، ہم (ان میں) ٹڈی کھاتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن ابی اوفیٰ رضی اللہ عنہ نے فرمایا ہم سات جنگوں میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ گئے۔ ہم (آپ کے ساتھ رہتے ہوئے) ٹڈیاں کھایا کرتے تھے۔","f2":"اس ٹڈی سے مراد وہ ٹڈی نہیں جو عام گھروں میں ہوتی ہے بلکہ اس سے مراد وہ ٹڈی ہے جسے مکڑی بھی کہا جاتا ہے، وہ جو فصلوں کو بھی چٹ کر جاتی ہے۔ یہ حلال جانور ہے۔ اس کو ذبح کرنے کی بھی ضرورت نہیں کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: [أُحِلَّتْ لَنَا مَیْتَتَانِ وَدَمَانِ: اَلْجَرَادُ وَالْحِیتَانُ وَالْکَبِدُ وَالطِّحَالُ] ’’ہمارے لیے دو مردار اور دو خون حلال کیے گئے ہیں۔ دو مردار (جنھیں ذبح نہ کیا گیا ہو) ٹڈی (مکڑی) اور مچھلی ہیں۔ اور دو خون جگر اور تلی ہیں۔‘‘ (مسند احمد: ۲/ ۹۷ وسنن الکبریٰ للبیہقی: ۱/ ۲۵۴) اس میں بھی مچھلی کی طرح دم مسفوح ہے (بہنے والا خون) نہیں ہوتا۔"}],[4357,"ابویعفور کہتے ہیں کہ میں نے عبداللہ بن ابی اوفی رضی اللہ عنہ سے ٹڈی کے مارنے کے بارے میں پوچھا تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چھ جنگیں کی ہیں، ہم (ان میں) ٹڈی کھاتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابو یعفور نے کہا کہ میں نے حضرت عبداللہ بن ابی اوفی رضی اللہ عنہ سے ٹڈی کو قتل کرنے کے بارے میں پوچھا تو انھوں نے فرمایا: میں چھ جنگوں میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حاضر ہوا۔ ہم ٹڈیاں کھایا کرتے تھے۔","f2":"’’چھ جنگوں میں‘‘ سابقہ روایت میں سات جنگوں کا ذکر ہے۔ چھ، سات کے منافی نہیں ہے۔"}],[4358,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک چیونٹی نے نبیوں میں سے ایک نبی کو کاٹ لیا تو انہوں نے چیونٹیوں کے گھر کو جلا دینے کا حکم دیا اور وہ جلا دیا گیا، اس پر اللہ تعالی نے وحی نازل کی: اگر تمہیں کسی چیونٹی نے کاٹ لیا تھا تو (ایک ہی کو مارتے مگر) تم نے ایک ایسی امت (مخلوق) کو مار ڈالا جو (ہماری) تسبیح (پاکی بیان) کر رہی تھی\" ۱؎۔\n§وضاحت\n۱؎: اس سے پتہ چلتا ہے کہ اس نبی کی شریعت میں کاٹنے والی چیونٹی کو جلانا جائز تھا مگر اسلامی شریعت میں جلانا جائز نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک چیونٹی نے ایک نبی کو کاٹ لیا تو انھوں نے چیونٹی کی اس پوری آبادی کو آگ لگانے کا حکم دیا۔ انھیں جلا دیا گیا۔ اللہ تعالیٰ نے ان کی طرف وحی فرمائی کہ تجھے ایک چیونٹی نے کاٹ لیا، تو نے اللہ تعالیٰ کی تسبیح کرنے والی مخلوق کو ہلاک کر دیا۔","f2":"(۱) چیونٹی کے متعلق حکم شریعت یہ ہے کہ اگر وہ تکلیف پہنچائے تو اسے مارا جا سکتا ہے۔ ہر تکلیف دینے والی مخلوق کو قتل کیا جا سکتا ہے، البتہ اس بات کا خاص خیال رکھنا ضروری ہے کہ صرف اسے قتل کیا جائے جس نے تکلیف پہنچائی ہو۔ مذکورہ حدیث میں ایک نبی کا قصہ اسی بات پر دلالت کرتا ہے۔ اصول یہ ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم سابقہ شریعتوں میں سے کسی شریعت کی کوئی بات بتائیں تو وہ ہمارے لیے بھی شریعت ہی ہوتی ہے۔ ہاں، اگر ہماری شریعت میں اس کے منافی حکم آجائے تو پھر سابقہ شریعت کی بات ہمارے لیے حجت نہیں ہوگی۔ (۲) معلوم ہوا حیوان بھی اللہ تعالیٰ کی تسبیح کرتے ہیں۔ قرآن کریم نے تو اس حد تک تصریح فرمائی ہے کہ ساتویں آسمان وزمین اور جو مخلوق ان (آسمانوں اور زمین) میں ہے، وہ اللہ کی تسبیح کرتی ہیں۔ مطلب بالکل واضح ہے کہ ہر چیز اللہ تعالیٰ کی حمد سمیت اس کی تسبیح کرتی ہے۔ ارشاد باری ہے:\n{تُسَبِّحُ لَہُ السَّمٰوٰتُ السَّبْعُ وَ الْاَرْضُ وَ مَنْ فِیْہِنَّ وَ اِنْ مِّنْ شَیْئٍ اِلَّا یُسَبِّحُ بِحَمْدِہٖ} (بنی اسرائیل ۱۷: ۴۴)\nاور یہ حقیقت ہے کہ ہر مخلوق ہی اللہ تعالیٰ کی تسبیح کرتی ہے۔ بعض لوگوں نے حیوانات وغیرہ کی تسبیح کو مجازی معنی پر محمول کرنے کی کوشش کی ہے، یہ قطعاً درست نہیں۔ (۳) حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ انبیائے کرام رضی اللہ عنہم کو بھی عام انسانوں کی طرح درد اور موذی چیزوں کے کاٹنے سے تکلیف محسوس ہوتی تھی۔ (۴) اس حدیث مبارکہ سے یہ مسئلہ بھی ثابت ہوتا ہے کہ صرف ذوی العقول، یعنی صاحب شعور مخلوق ہی سے ظلم کا بدلا نہیں لیا جائے گا بلکہ غیر ذوی العقول، سے بھی اس کے ظلم وزیادتی کا بدلہ لیا جا سکتا ہے۔ واللہ اعلم (۵) شاید آگ سے جلانا ان کی شریعت میں جائز ہوگا، ہماری شریعت میں منع ہے۔ (۶) چیونٹی کے قتل سے نہی اس کے حرام ہونے کی دلیل ہے۔"}],[4359,"حسن بصری سے روایت ہے کہ ایک نبی ایک درخت کے نیچے ٹھہرے تو انہیں ایک چیونٹی نے کاٹ لیا، انہوں نے ان کے گھروں کے بارے میں حکم دیا تو ان میں جو بھی تھا اسے جلا دیا گیا، اللہ تعالی نے ان کی طرف وحی نازل کی: \"آخر تم نے صرف ایک کو کیوں نہ جلایا\"۔ اشعث کہتے ہیں: ابن سیرین سے روایت ہے وہ ابوہریرہ سے اور ابوہریرہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم سے اسی جیسی حدیث روایت کرتے ہیں، اس میں یہ زائد ہے \"اس لیے کہ وہ تسبیح (اللہ کی پاکی بیان) کر رہی تھیں\"۔","الألباني: صحيح مقطوع",{"u2":"حضرت حسن بصری رحمہ اللہ سے منقول ہے کہ (سابقہ) انبیاء میں سے ایک نبی ایک درخت کے نیچے فروکش ہوئے۔ ایک چیونٹی نے انھیں کاٹ لیا۔ انھوں نے حکم دیا تو ان کے پورے بل کو تمام چیونٹیوں سمیت جلا دیا گیا۔ اللہ تعالیٰ نے ان کی طرف وحی فرمائی۔ کہ آپ نے کیوں نہ صرف ایک چیونٹی کو مارا؟ (آخری یہ بھی تو اللہ تعالیٰ کی تسبیح بیان کرتی ہیں۔)\nاور اشعث نے ابن سیرین سے، انھوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی (سابقہ) حدیث کی مثل بیان کیا۔ اور اس میں یہ الفاظ زیادہ ہیں: [فَاِنَّھُنَّ یُسَبِّحْنَ] ’’بلا شبہ یہ (چیونٹیاں اللہ تعالیٰ کی) تسبیح بیان کرتی ہیں۔‘‘","f2":"اس کا مفہوم یہ ہے کہ اشعث نے یہ روایت دو شیوخ سے بیان کی ہے: ایک حسن بصری سے اور دوسرے محمد بن سیرین سے۔ حسن بصری سے جو روایت ہے، وہ موقوف ہے جبکہ دوسری، یعنی محمد بن سیرین رحمہ اللہ سے بیان کردہ روایت مرفوع ہے۔ دونوں روایتیں، یعنی موقوف اورمرفوع صحیح ہیں، البتہ دوسری مرفوع روایت میں [فَاِنَّھُنَّ یُسَبِّحْنَ] کے الفاظ زیادہ ہیں۔ موقوف، یعنی حسن بصری رحمہ اللہ والی روایت میں یہ الفاظ نہیں ہیں۔"}],[4360,"عبداللہ بن عباس رضی اللہ عنہما آیت کریمہ «إنما جزاء الذين يحاربون اللہ ورسوله» \"ان لوگوں کا بدلہ جو اللہ اور اس کے رسول سے لڑتے ہیں …\"کے سلسلے میں کہتے ہیں کہ یہ آیت مشرکین کے سلسلے میں نازل ہوئی، پس ان میں سے جو شخص توبہ کرنے سے پہلے اسے پکڑا جائے تو اس کو سزا دینے کا کوئی جواز نہیں، یہ آیت مسلمان شخص کے لیے نہیں ہے، پس جو (مسلمان) زمین میں فساد پھیلائے اور اللہ اور اس کے رسول سے لڑے، پھر پکڑے جانے سے پہلے کفار سے مل جائے تو اس کی جو بھی حد ہو گی، اس کے نفاذ میں کوئی چیز رکاوٹ نہیں ہو گی ۱؎۔\n§وضاحت\n۱؎: ابن عباس رضی اللہ عنہما کا مطلب یہ ہے کہ اگر مشرکین میں سے کوئی زمین میں فساد پھیلائے اور پکڑے جانے سے پہلے توبہ کر لے، تو اب اس پر زمین میں فتنہ و فساد پھیلانے کے جرم کی حد نافذ نہیں کی جائے گی، لیکن اگر مسلمانوں میں سے کوئی زمین میں فساد پھیلائے اور پکڑے جانے سے پہلے توبہ کر لے، تو بھی اس پر حد نافذ کی جائے گی اس کو معاف نہیں کیا جائے گا، یہ رائے صرف ابن عباس رضی اللہ عنہما کی ہے، علی رضی اللہ عنہ، نیز دیگر لوگوں نے توبہ کر لینے پر حد نہیں نافذ کی تھی :(ملاحظہ ہو: عون المعبود )۔\nاس سند سے بھی ابوہریرہ رضی اللہ عنہ سے اسی طرح مروی ہے لیکن یہ مرفوع نہیں ہے۔","الألباني: صحيح الإسناد",{"u2":"اسی قسم کی روایت حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے مگر وہ مرفوع نہیں (بلکہ ان کا اپنا قول ہے)۔"}],[4361,"ام المؤمنین ام سلمہ رضی اللہ عنہا روایت کرتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص نے ذی الحجہ کے مہینے کا چاند دیکھا پھر قربانی کرنے کا ارادہ کیا تو وہ اپنے بال اور ناخن قربانی کرنے تک نہ لے\" ۱؎۔\n§وضاحت\n۱؎: بال اور ناخن وغیرہ کچھ نہ کاٹے، جمہور کے نزدیک یہ حکم استحبابی ہے۔","الألباني: صحيح",{"u2":"حضرت ام سلمہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ذوالحجہ کا چاند دیکھ لے اور وہ قربانی کرنے کا ارادہ رکھتا ہو تو وہ اپنے بال اور ناخن نہ کاٹے حتی کہ قربانی کر لے۔","f2":"(۱) اس حدیث سے قربانی کی مشروعیت ثابت ہوتی ہے۔ (۲)اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوا کہ جو آدمی قربانی کرنا چاہتا ہو، وہ ذوالحجہ کا چاند نظر آنے کے بعد اپنے بال اور ناخن وغیرہ کاٹے نہ تراشے۔ (۳) ’’چاند دیکھ لے۔‘‘ مقصد یہ ہے کہ ذوالحجہ کا چاند طلوع ہو جائے ورنہ یہ ضروری نہیں کہ ہر آدمی اسے دیکھے۔ (۴) ’’ارادہ رکھتا ہو‘‘ گویا جو شخص قربانی کا ارادہ نہ رکھتا ہو، اس پر یہ پابندی نہیں مگر اس کے لیے بہتر ہے کہ وہ قربانی کے دن ہی حجامت بنوائے۔"}],[4362,"ام المؤمنین ام سلمہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص قربانی کرنا چاہے تو وہ ذی الحجہ کے ابتدائی دس دنوں میں نہ اپنے ناخن کترے اور نہ بال کٹوائے\"۔","الألباني: صحيح",{"u2":"نبی اکرم صلی اللہ علیہ وسلم کی زوجہ محترمہ حضرت ام سلمہ رضی اللہ عنہا سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص قربانی کرنے کا ارادہ رکھتا ہو، وہ نہ اپنے ناخن کٹوائے اور نہ بال۔ یہ حکم ذوالحجہ کے پہلے دس دن کے لیے ہے۔‘‘","f2":": ’’دس دن‘‘ یعنی دسویں دن قربانی ذبح کرنے تک۔ قربانی ذبح کرنے کے بعد حجامت بنوا لینی چاہیے۔"}],[4363,"تابعی سعید بن مسیب کہتے ہیں کہ جو شخص قربانی کا ارادہ کرے اور (ذی الحجہ کے ابتدائی) دس دن شروع ہو جائیں تو اپنے بال اور اپنے ناخن نہ کترے، میں نے اس چیز کا ذکر عکرمہ سے کیا تو انہوں نے کہا: وہ عورتوں اور خوشبو سے بھی دور رہے ۱؎۔\n§وضاحت\n۱؎: ان کو اس بابت مرفوع حدیث نہیں پہنچی تھی اس لیے بطور طنز ایسا کہا، ویسے اس کی سند ضعیف ہے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت سعید بن مسیب رحمہ اللہ سے مروی ہے کہ جو آدمی قربانی ذبح کرنے کا ارادہ رکھتا ہو اور ذوالحجہ شروع ہو جائے تو وہ اپنے بال اور ناخن نہ کاٹے۔ میں نے عکرمہ سے اس کا ذکر کیا تو وہ کہنے لگے: کیا وہ عورت اور خوشبو سے بھی الگ نہ رہے؟","f2":"حضرت عکرمہ کا مطلب یہ ہے کہ اگر حجامت نہیں بنوانی تو پھر عورت اور خوشبو کا استعمال بھی منع ہونا چاہیے کیونکہ محرم سے مشابہت تو تب ہی مکمل ہوگی۔ شاید انھوں نے اسے حضرت سعید بن مسیب کا اپنا قول سمجھا ہوگا۔ اور ان کو مرفوع روایت نہیں پہنچی ہوگی۔ رسول اللہ صلی اللہ علیہ وسلم کے فرمان پر تو اعتراض ہو ہی نہیں سکتا۔ شریعت نے جتنی پابندی مناسب سمجھی، لگا دی، جیسے وضو اور غسل کا فرق ہے۔ جنبی کے لیے غسل مشروع فرما دیا اور محدث (بے وضو) کے لیے وضو۔ اسی طرح محرم کے لیے زیادہ پابندیاں لگا دیں اور صرف قربانی کرنے والے کے لیے کم۔ یہ کون سی قابل اعتراض بات ہے؟"}],[4364,"ام المؤمنین ام سلمہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب ذی الحجہ کا پہلا عشرہ شروع ہو جائے اور تم میں کا کوئی قربانی کا ارادہ رکھتا ہو تو اسے اپنے بال اور اپنی کھال سے کچھ نہیں چھونا چاہیئے\"۔","الألباني: صحيح",{"u2":"حضرت ام سلمہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب ذوالحجہ شروع ہو جائے تو جو شخص قربانی کا ارادہ رکھتا ہو، تو وہ اپنے بال یا جسم کا کوئی اور حصہ (مثلاً ناخن وغیرہ) نہ کاٹے۔‘‘"}],[4365,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص سے فرمایا: \"مجھے قربانی کے دن (دسویں ذی الحجہ) کو عید منانے کا حکم ہوا ہے، اللہ تعالی نے اس دن کو اس امت کے لیے عید کا دن بنایا ہے\"، وہ شخص بولا: اگر میرے پاس سوائے ایک دو دھاری بکری کے کچھ نہ ہو تو آپ کا کیا خیال ہے؟ کیا میں اس کی قربانی کروں؟ آپ نے فرمایا: \"نہیں، بلکہ تم (قربانی کے دن) ۱؎ اپنے بال، ناخن کاٹو، اپنی مونچھ تراشو اور ناف کے نیچے کے بال کاٹو، تو یہ اللہ تعالی کے نزدیک تمہاری مکمل قربانی ہے\"۔\n§وضاحت\n۱؎: یعنی: ذی الحجہ کا چاند دیکھنے کے بعد اپنے بال اور ناخن کاٹنے سے رک جاؤ، اور عید کی نماز پڑھ کر ان کو کاٹو تو تمہیں بھی مکمل قربانی کا ثواب ملے گا۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی سے فرمایا: ’’مجھے قربانیوں والے دن کو عید بنانے کا حکم دیا گیا ہے جسے اللہ تعالیٰ نے اس امت کے لیے مقرر فرمایا ہے۔‘‘ اس شخص نے عرض کی: اگر میرے پاس دودھ والی بکری کے علاوہ کوئی اور جانور قربانی کے لیے نہ ہو تو فرمائیے کیا میں اسے ہی ذبح کر دوں؟ آپ نے فرمایا: ’’نہیں۔ لیکن تو (قربانی والے دن) اپنے بال کاٹ لے، ناخن اور مونچھیں تراش لے اور زیر ناف بال صاف کر لے۔ اللہ تعالیٰ کے ہاں تیری طرف سے یہی مکمل قربانی شمار ہوگی۔","f2":"(۱) باب کے ساتھ حدیث کی مناسبت واضح ہے کہ جو شخص قربانی کرنے کی طاقت نہیں رکھتا، اس کے لیے شریعت کا حکم یہ ہے کہ وہ اپنی جسمانی صفائی ستھرائی کا خاص اہتمام کرے۔ عید والے دن اپنے بال اور ناخن تراشے۔ اپنی مونچھیں کاٹے اور زیر ناف بالوں کی صفائی کرے۔ یہ اہتمام اس کے لیے قربانی کرنے کے قائم مقام ہوگا۔ ان شاء اللہ۔ (۲)عید کے دن بننا سنورنا اور صفائی ستھرائی کا اہتمام کرنا مستحب ہے چونکہ یہ لوگوں کے اجتماع کا دن ہے، اس لیے اس دن کی خاطر خاص طور پر نہانا دھونا، اچھا لباس پہننا، خوشبو لگانا اور شریعت کے بتلائے ہوئے دیگر امور بجا لانا مطلوب اور شریعت مطہرہ کی نظر میں پسندیدہ عمل ہے۔ یہی وجہ ہے کہ قربانی نہ کر سکنے کے باوجود مذکورہ امور کو کما حقہ بجا لانا، اجر و ثواب میں مکمل قربانی کرنے کے مترادف قرار دیا گیا ہے۔ (۳) یہ حدیث مبارکہ قربانی کرنے کی خصوصی اہمیت بھی اجاگر کرتی ہے کیونکہ قربانی کرنے کا اس قدر بنانا مستحب قرار دیا گیا ہے تاکہ قربانی کرنے والے لوگوں کے ساتھ بدنی مشابہت ہو جائے۔ (۴) معلوم ہوا قربانی کی طاقت نہ رکھنے والے شخص کو قربانی معاف ہے۔ {لَا یُکَلِّفُ اللّٰہُ نَفْسًا اِلَّا وُسْعَھَا}"}],[4366,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عید گاہ میں ہی (قربانی کا جانور) ذبح یا نحر کرتے تھے ۱؎۔\n§وضاحت\n۱؎: نبی اکرم صلی اللہ علیہ وسلم کے زمانہ میں مدینہ میں عید گاہ کے اندر قربانی کرنے کی سہولت میسر تھی تو آپ نے ایسا کیا، اگر آج ایسی سہولت میسر ہو تو عید گاہ کے اندر ایسا کیا جا سکتا ہے، یہ کوئی واجب اور سنت نہیں کہ ہر حال میں ایسا ہی کیا جائے، اس زمانہ میں تو اب شاید کسی دیہات میں بھی یہ سہولت نہ ہو، شہروں میں تو اب ایسا ممکن ہی نہیں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عیدگاہ میں قربانی ذبح یا نحر فرماتے تھے۔","f2":"(۱) مقصد یہ تھا کہ لوگوں میں شوق پیدا ہو۔ آپ کو قربانی ذبح کرتے دیکھنے کے بعد کوئی شخص سستی نہیں کر سکتا تھا بشرطیکہ وہ طاقت رکھتا ہو۔ اب بھی امام کے لیے یہ طریقہ مستحب ہے، ضروری نہیں۔ امام مالک نے اسے ضروری خیال کیا ہے مگر وجوب کی کوئی دلیل نہیں۔ (۲) ’’ذبح یا نحر‘‘ گائے، بکری اور دنبہ، چھترا وغیرہ کو ذبح کیا جاتا ہے جبکہ اونٹ کو نحر۔"}],[4367,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عید الاضحی کے دن مدینے میں اونٹ نحر (ذبح) کیا، اور جب آپ (اونٹ) نحر نہیں کرتے تو عید گاہ میں ذبح کرتے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عیدالاضحی کے دن مدینہ منورہ میں اونٹ نحر فرمایا۔ اور اگر (کسی سال) اونٹ نحر نہ فرماتے تو قربانی کو عید گاہ میں ذبح فرماتے۔","f2":"گویا اونٹ کو عید گاہ میں نہ لے جاتے بلکہ اسے شہر ہی میں ذبح کر دیتے۔ چھوٹا جانور ہوتا تو ساتھ لے جاتے کیونکہ بڑے جانور کو ذبح کرنے میں دیر بھی لگتی ہے اور معاون بھی زیادہ چاہئیں، اس لیے گھر ہی بہتر ہے۔"}],[4368,"جندب بن سفیان رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عید الاضحی میں تھا، آپ نے لوگوں کو نماز عید پڑھائی، جب نماز مکمل کر لی تو آپ نے دیکھا کہ کچھ بکریاں (نماز سے پہلے ہی) ذبح کر دی گئیں ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"نماز عید سے پہلے جس نے ذبح کیا ہے اسے چاہیئے کہ وہ اس کی جگہ دوسری بکری ذبح کرے اور جس نے ذبح نہیں کیا ہے تو وہ اللہ کا نام لے کر ذبح کرے\" ۱؎۔\n§وضاحت\n: ۱؎ واضح طور پر باب کے مطابق پچھلی حدیث ہے، مؤلف نے اس حدیث سے اس طرح استدلال کیا ہے کہ آپ صلی اللہ علیہ وسلم نے عید گاہ میں ذبح پر کچھ نہیں فرمایا: بلکہ صرف نماز عید سے پہلے ذبح کر دیئے جانے پر اعتراض کیا۔","الألباني: صحيح",{"u2":"حضرت جندب بن سفیان رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عید الاضحی میں حاضر ہوا۔ آپ صلی اللہ علیہ وسلم نے لوگوں کو نماز پڑھائی۔ جب آپ نے نماز ادا کر لی تو آپ نے دیکھا کہ کچھ بکریاں ذبح ہو چکی ہیں۔ آپ نے فرمایا: ’’جس نے نماز سے پہلے قربانی ذبح کر دی ہے، وہ اس کی جگہ اور بکری ذبح کرے اور جو ذبح نہیں کر چکا تو وہ اللہ عزوجل کا نام لے کر ذبح کرے۔‘‘","f2":"(۱) مصنف رحمہ اللہ نے اس حدیث پر جو باب باندھا ہے، وہ عام لوگوں کے عید گاہ میں قربانی کے جانور ذبح کرنے کے متعلق ہے۔ ترجمۃ الباب کے ساتھ حدیث کی مناسبت اس طرح ہے کہ آپ صلی اللہ علیہ وسلم نے نماز عید ادا کرنے کے بعد دیکھا تو کچھ بکریاں ذبح کی جا چکی تھیں، ظاہر ہے کہ آپ نے نماز عید، عیدگاہ ہی میں پڑھائی تھی، لہٰذا ذبح کی ہوئی بکریاں بھی آپ نے وہاں ہی دیکھی ہوں گی۔ (۲)مسجد سے الگ، باہر کھلے میدان میں نماز عید ادا کرنا سنت ہے۔ عام حالات میں باہر، عید گاہ ہی میں عید ادا کی جائے، تاہم بوقت ضرورت یعنی بارش، آندھی اور سخت سردی وغیرہ کی صورت میں نماز عید، مسجد میں بھی پڑھی جا سکتی ہے۔ (۴) نماز عید کی ادائیگی سے پہلے قربانی کا جانور ذبح نہیں کیا جا سکتا۔ اگر کوئی شخص نماز عید پڑھنے سے پہلے قربانی ذبح کرے گا تو اس کی قربانی ہرگز ہرگز نہیں ہوگی، لہٰذا اس پر قربانی کے لیے دوسرا جانور ذبح کرنا ضروری ہوگا، بشرطیکہ دوسرے جانور کی استطاعت ہو۔ یہ اس لیے کہ قربانی کا وقت مقرر ہے۔ اس سے پہلے قربانی غیر معتبر ہے، جیسے نماز کا وقت مقرر ہے۔ وقت سے پہلے پڑھی ہوئی نماز دوبارہ پڑھنی پڑے گی۔ اسی طرح عید کی نماز کے اختتام سے قبل قربانی کا وقت نہیں ہوتا، لہٰذا قربانی دوبارہ کرنا ہوگی۔"}],[4369,"ابوالضحاک عبید بن فیروز کہتے ہیں کہ میں نے براء رضی اللہ عنہ سے کہا: مجھے بتائیے کہ کن کن جانوروں کی قربانی سے رسول اللہ صلی اللہ علیہ وسلم نے روکا ہے؟ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے (اور براء نے ہاتھ سے اشارہ کیا اور کہا) میرا ہاتھ آپ کے ہاتھ سے چھوٹا ہے، آپ نے فرمایا: \"چار طرح کے جانور جائز نہیں: ایک تو کانا جس کا کانا پن صاف معلوم ہو، دوسرا بیمار جس کی بیماری واضح ہو، تیسرا لنگڑا جس کا لنگڑا پن صاف ظاہر ہو، چوتھا وہ دبلا اور کمزور جانور جس کی ہڈیوں میں گودا نہ ہو\"۔ میں نے کہا: مجھے یہ بھی ناپسند ہے کہ اس کے سینگ میں کوئی نقص عیب ہو یا اس کے دانت میں کوئی کمی ہو ۱؎، انہوں نے کہا: جو تمہیں ناپسند ہو اسے چھوڑ دو، لیکن تم کسی اور کو اس سے مت روکو۔\n§وضاحت\n۱؎: اس سے مراد: سینگ یا دانت میں معمولی سی کمی ہے، اسی لیے اتنی کمی والے جانور کے بارے میں آپ صلی اللہ علیہ وسلم نے فرمایا: \" جو تمہیں ناپسند ہو … \" ورنہ مذکورہ چاروں عیوب کی طرح کسی بھی بڑے عیب کی موجودگی میں جمہور کے نزدیک قربانی جائز نہیں جیسے آدھا سے زیادہ کان کٹا ہوا ہو سینگ ٹوٹی ہوئی، پاؤں کٹا ہوا ہو، اندھا ہو، وغیرہ وغیرہ۔","الألباني: صحيح",{"u2":"حضرت ابوضحاک عبید بن فیروز مولی بنی شیبان سے روایت ہے، انھوں نے کہا کہ میں نے حضرت برائ رضی اللہ عنہ سے عرض کی: مجھے بتائیے رسول اللہ صلی اللہ علیہ وسلم نے کن جانوروں کی قربانی سے منع فرمایا ہے؟ انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم خطبہ دینے کے لیے اٹھے اور (اپنے ہاتھ مبارک کے ساتھ اشارہ کرتے ہوئے) فرمایا: ویسے میرا ہاتھ ہر لحاظ سے آپ صلی اللہ علیہ وسلم کے ہاتھ سے کوتاہ ہے۔‘‘ چار جانور قربانی میں کفایت نہیں کرتے: کانا جانور جس کا کانا پن واضح ہو، بیمار جانور جس کی بیماری واضح ہو، لنگڑا جانور جس کا لنگڑا پن واضح ہو۔ اور وہ جانور جو ہڈی ٹوٹنے سے اتنا کمزور ہو چکا ہو کہ اس میں گودانہ رہا ہو۔‘‘ میں نے کہا: میں تو یہ بھی ناپسند کرتا ہوں کہ سینگ میں کوئی نقص ہو یا دانت میں کوئی نقص ہو۔ وہ فرمانے لگے: جسے تو ناپسند کرتا ہے، اس کی قربانی نہ کر لیکن کسی پر حرام نہ کر۔","f2":"(۱) جس جانور کا کانا پن واضح ہو، اس کی قربانی جائز نہیں۔ یہی حکم دوسرے عیوب ونقائص یعنی بیمار، لنگڑے اور انتہائی لاغر وکمزور جانور کا ہے کہ اگر ان کے یہ عیوب واضح ہوں تو ان کی قربانی بھی درست نہیں ہوگی۔ (۲) اس حدیث مبارکہ سے یہ اہم بات بھی معلوم ہوتی ہے کہ صحابہ کرام رضی اللہ عنہم کمال درجے رسول اللہ صلی اللہ علیہ وسلم کا ادب واحترام کیا کرتے تھے۔ یہی وجہ ہے کہ حضرت براء بن عازب رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے فعل کی نقل کرتے ہوئے جب اپنے ہاتھ کی چار انگلیوں سے قربانی کے ممنوعہ جانوروں کی بابت اشارہ کیا تو یہ بھی فرما دیا کہ میرے ہاتھ (اور انگلیوں) کا رسول اللہ صلی اللہ علیہ وسلم کے مبارک ہاتھ سے کوئی موازنہ ہی نہیں۔ میرا ہاتھ رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ مبارک سے، ہر لحاظ سے چھوٹا ہے۔ (۳)تقرب الی اللہ کے حصول کے لیے صحابہ کرام رضی اللہ عنہم تندفرست اور فربے جانور اور دوسری قیمتی اور پسندیدہ اشیاء ہی خرچ کرنے کو ترجیح دیا کرتے تھے، خواہ اس کے متعلق حکم شریعت نہ بھی ہو۔ (۴) حدیث مذکور اس بات پر بھی دلالت کرتی ہے کہ کسی کی ذاتی پسند اور ناپسند کا دین وشریعت میں کوئی عمل دخل نہیں بلکہ شریعت خالصتاً منصوص (کتاب وسنت) سے ثابت امور کا نام ہے۔ اسی لیے حضرت برائ رضی اللہ عنہ نے عبید بن فیروز سے فرمایا کہ تجھے جو جانور ناپسند ہے تو اس کی قربانی نہ کر لیکن کسی اور کو مت رو۔ یہ تیرا نہیں، شریعت مطہرہ کا کام ہے، اس لیے جس عیب کے متعلق شریعت کی نص (اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی طرف سے ممانعت) نہیں، اس عیب کے ہوتے ہوئے بھی جانور کی قربانی جائز ہے۔ اور اس پر امت کا اجماع ہے۔ واللہ اعلم! (۵) ’’کسی پر حرام نہ کر‘‘ یعنی کسی کو حرمت کا فتویٰ نہ دے۔ معمولی نقص جو محسوس نہ ہوتا ہو، قابل درگزر ہے، البتہ قربانی کرنے والا اپنی طرف سے بہترین جانور ذبح کرے۔ سینگ اور کان کے بارے میں روایات آگے آرہی ہیں اس لیے بحث بھی وہاں ہوگی۔ ان شاء اللہ"}],[4370,"عبید بن فیروز کہتے ہیں کہ میں نے براء بن عازب رضی اللہ عنہما سے کہا: مجھے بتائیے کہ رسول اللہ صلی اللہ علیہ وسلم کو کن کن جانوروں کی قربانی ناپسند تھی، یا آپ ان سے منع فرماتے تھے؟ انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے (اور اس طرح انہوں نے اپنے ہاتھ سے اشارہ کیا، اور میرا ہاتھ رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ سے چھوٹا ہے): \"چار جانوروں کی قربانی درست اور صحیح نہیں ہے: کانا جس کا کانا پن ظاہر ہو، بیمار جس کی بیماری واضح ہو، لنگڑا جس کا لنگڑا پن ظاہر ہو، اور دبلا اور کمزور جس میں گودا نہ ہو\"، انہوں نے کہا: مجھے ناپسند ہے کہ اس جانور کے سینگ اور کان میں کوئی عیب ہو، انہوں نے کہا: جو تمہیں ناپسند ہو اسے چھوڑ دو لیکن کسی اور کو اس سے مت روکو۔","الألباني: صحيح",{"u2":"حضرت عبید بن فیروز سے منقول ہے کہ میں نے حضرت براء بن عازب رضی اللہ عنہ سے کہا: مجھے بیان فرمائیے کہ رسول اللہ صلی اللہ علیہ وسلم نے کن جانوروں کی قربانی سے منع فرمایا ہے یا ناپسند فرمایا ہے؟ وہ فرمانے لگے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے دست مبارک سے یوں اشارہ فرمایا:… اور میرا ہاتھ رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ سے چھوٹا ہے… ’’چار جانور قربانی میں کفایت نہیں کرتے: کانا جس کا کانا پن واضح ہو، بیمار جس کی بیماری واضح ہو، لنگڑا جس کا لنگڑا پن واضح ہو اور وہ جانور جس کی ہڈی ٹوٹ چکی ہو اور وہ اتنا کمزور ہو چکا ہو کہ اس میں گودا باقی نہ رہا ہو۔‘‘ میں نے کہا: میں تو کان اور سینگ کے نقص کو بھی ناپسند کرتا ہوں۔ وہ فرمانے لگے: جس کو تو ناپسند کرتا ہے اسے قربانہ نہ کر لیکن اسے دوسروں کے لیے حرام قرار نہ دے۔","f2":"معلوم ہوا تھوڑا بہت لنگڑا پن جو غور کیے بغیر محسوس نہ ہوتا ہو یا صرف بھاگتے ہوئے محسوس ہوتا ہو، قربانی میں عیب نہیں ہے۔ اسی طرح دوسرے عیوب غیر محسوس حد تک معاف ہیں۔ واللہ اعلم"}],[4371,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا، انہوں نے اپنی انگلیوں سے اشارہ کیا اور میری انگلیاں رسول اللہ صلی اللہ علیہ وسلم کی انگلیوں سے چھوٹی ہیں، انگلیوں سے اشارہ کرتے ہوئے آپ فرما رہے تھے: \"قربانی کے جانوروں میں یہ جانور جائز نہیں ہیں: کانا جس کا کانا پن صاف معلوم ہو، لنگڑا جس کا لنگڑا پن واضح ہو، بیمار جس کی بیماری صاف ظاہر ہو رہی ہو اور دبلا اور کمزور جس کی ہڈیوں میں گودا نہ ہو\"۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہ سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا اور آپ اپنی مبارک انگلیوں کے ساتھ اشارہ بھی فرما رہے تھے:… اور میری انگلیاں رسول اللہ صلی اللہ علیہ وسلم کی مقدس انگلیوں سے کوتاہ ہیں… ’’چار قسم کے جانور قربانی میں جائز نہیں: کانا جس کا کانا پن ظاہر ہو، لنگڑا جس کا لنگڑا پن واضح ہو، مریض جس کا مرض واضح ہو اور اتنا کمزور جانور کہ اس میں گودا تک نہ ہو۔‘‘"}],[4372,"علی رضی اللہ عنہ کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ ہم (جانوروں کے) آنکھ اور کان دیکھ لیں اور کسی ایسے جانور کی قربانی نہ کریں جس کا کان سامنے سے کٹا ہو، یا جس کا کان پیچھے سے کٹا ہو، اور نہ دم کٹے جانور کی، اور نہ ایسے جانور کی جس کے کان میں سوراخ ہوں۔","الألباني: ضعيف لكن جملة الاستشراف صحيحة",{"u2":"حضرت علی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا کہ ہم (قربانی والے جانور کے) آنکھ اور کان کو غور سے دیکھیں اور ہم کوئی ایسا جانور ذبح نہ کریں جس کا کان آگے سے کٹا ہو یا پیچھے سے کٹا ہوا ہو یا دم کٹی ہوئی ہو یا کان میں سوراخ ہو۔","f2":"جانور کی خوبصورتی اس کے کان آنکھ ہی سے ہوتی ہے، اس لیے آپ نے ان میں ہلکا سا عیب بھی قبول نہیں فرمایا، خصوصاً اس لیے بھی کہ مشرکین بتوں کے نام پر جانوروں کے کان کچھ حد تک کاٹ دیتے تھے۔ چونکہ کن کٹنے جانور کے بارے میں یہ شبہ قائم ہے کہ شاید وہ کسی بت کے لیے نامزد ہو، لہٰذا اس قسم کے ہر جانور کو قربانی میں ممنوع قرار دے دیا گیا ہے۔ دم بھی جانور کی خوبصورت میں اصل ہے، لہٰذا دم کٹا جانور بھی ممنوع ہے۔"}],[4373,"علی رضی اللہ عنہ کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے (جانوروں کے) آنکھ اور کان دیکھ لینے کا حکم دیا، اور یہ کہ ہم کسی ایسے جانور کی قربانی نہ کریں جو کانا ہو، جس کا کان سامنے سے کٹا ہو، یا جس کا کان پیچھے سے کٹا ہو، اور نہ کسی ایسے جانور کی جس کے کان چرے ہوئے ہوں، اور نہ ایسے جانور کی جس کے کان میں سوراخ ہو۔","الألباني: ضعيف",{"u2":"حضرت علی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا کہ ہم (قربانی والے جانور کے) آنکھ اور کان کو اچھی طرح دیکھیں۔ اور ہم کوئی ایسا جانور ذبح نہ کریں جو کانا ہو یا اس کا کان آگے یا پیچھے سے کٹا ہوا ہو، یا وہ درمیان سے چرا ہوا ہو یا اس میں سوراخ ہو۔"}],[4374,"علی بن ابی طالب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سامنے اور پیچھے سے کان کٹے ہوئے جانور، اور پھٹے کان والے جانور اور چرے ہوئے کان والے جانور اور ایسے جانور جن کے کان میں سوراخ ہو اور کان کٹے ہوئے جانور کی قربانی کرنے سے منع فرمایا۔","الألباني: ضعيف",{"u2":"حضرت علی بن ابی طالب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ ایسا جانور قربانی میں ذبح کیا جائے جس کا کان آگے یا پیچھے سے کٹا یا چرا ہوا ہو یا اس میں سوراخ ہو۔ یا اس کا کوئی عضو کٹا ہوا ہو۔","f2":"’’کوئی عضو کٹا ہوا ہو‘‘ مثلاً ناک، کان یا ہونٹ وغیرہ۔ عربی میں اسے جدعاء کہتے ہیں۔"}],[4375,"علی بن ابی طالب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سامنے سے اور پیچھے سے کان کٹے ہوئے، اور کان چرے ہوئے اور کان پھٹے ہوئے اور کانے جانوروں کی قربانی نہ کی جائے\"۔","الألباني: ضعيف",{"u2":"حضرت علی بن ابی طالب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایسا جانور قربانی میں ذبح نہ کیا جائے جس کا کان آگے یا پیچھے سے کٹا ہوا ہو یا چرا ہوا ہو، یا اس میں سوراخ ہو یا وہ آنکھ سے کانا ہو۔‘‘"}],[4376,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں آنکھ اور کان دیکھ لینے کا حکم دیا ہے۔","الألباني: حسن صحيح",{"u2":"حضرت علی رضی اللہ عنہ فرماتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا کہ قربانی کے جانور کے کان اور آنکھ غور سے یکھیں(کہ ان میں کسی قسم کی کوئی خرابی نہ ہو)۔","f2":"’’غور سے دیکھیں‘‘ بعض حضرات نے معنی کیے ہیں کہ ہم بہترین کانوں اور آنکھوں والا پسند کریں۔ مفہوم اس کا بھی یہی ہے کہ آنکھوں اور کانوں میں کسی قسم کا، سا بھی کوئی عیب گوارا نہیں۔ مزید برآں یہ بھی کہ آنکھ اور کان وہی خوبصورت اور بہترین ہوگے جو نقص اور عیب سے پاک ہوں، عیب والی آنکھ کان تو بہترین نہیں ہوسکتے۔"}],[4377,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سینگ ٹوٹے جانور کو ذبح کرنے سے منع فرمایا ہے۔ (راوی قتادہ کہتے ہیں): میں نے اس کا ذکر سعید بن مسیب سے کیا تو انہوں نے کہا: ہاں، جس جانور کا آدھا سینگ یا اس سے زیادہ ٹوٹا ہو ۱؎۔\n§وضاحت\n۱؎: سعید بن مسیب کا قول قتادہ نے نقل کیا ہے اور قتادہ مدلس ہیں لیکن انہوں نے سعید بن المسیب سے اپنی بات نقل کی ہے تو اس طرح حدیث بیان کرنے کی صراحت کر دی ہے، اس لیے سعید بن المسیب کے قول کی روایت صحیح ہے اس سے اس بات کی تائید ہوتی ہے کہ سینگ ٹوٹے جانور کی قربانی جائز نہ ہونے کی بات اس جانور کے بارے میں ہے جس کا سینگ آدھے سے زیادہ ٹوٹا ہو، نیز دیکھئیے حاشیہ حدیث نمبر: ۴۳۷۴۔","الألباني: ضعيف",{"u2":"حضرت علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ٹوٹے ہوئے سینگ والے جانور کی قربانی سے منع فرمایا ہے۔ ییہ بات حضرت سعید بن مسیب سے ذکر کی گئی تو انھوں نے فرمایا: اس سے مراد وہ جانور ہے جس کا نصف یا نصف زیادہ سینگ ٹوٹا ہوا ہو۔","f2":"عربی لفظ استعمال ہوا ہے۔ حضرت سعید بن مسیب نے اسی لفظ تشریح فرمائی ہے کہ معمولی ٹوٹے ہوئے سینگ کی وجہ سے جانور کو اوعضب نہیں کہا جاتا، بلکہ نصف یا اس سے زائد ٹوٹا ہوتب اس کی قربانی منع ہو گی۔ گویا سینگ کی حیثیت کان کی سی نہیں۔ اس میں تھوڑا بہت نقص معاف ہے۔"}],[4378,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"صرف مسنہ ذبح کرو سوائے اس کے کہ اس کی قربانی تم پر گراں اور مشکل ہو تو تم بھیڑ میں سے جذعہ ذبح کر دو\"۔\n§وضاحت\n۱؎: «مُسِنّہ»: وہ جانور ہے جس کے دودھ کے دانت ٹوٹ چکے ہوں، اور یہ اونٹ میں عموماً اس وقت ہوتا ہے جب وہ پانچ سال پورے کر کے چھٹے میں داخل ہو گیا ہو، اور گائے اور بیل میں اس وقت ہوتا ہے جب وہ دو سال پورے کر کے تیسرے میں داخل ہو گئے ہوں، اور بکری اور بھیڑ میں اس وقت ہوتا ہے جب وہ ایک سال پورا کر کے دوسرے میں داخل ہو جائیں، اور جذعہ اس دنبہ یا بھیڑ کو کہتے ہیں جو سال بھر کا ہو چکا ہو، :(محققین اہل لغت اور شارحین حدیث کا یہی صحیح قول ہے، دیکھئیے مرعاۃ شرح مشکاۃ المصابیح ) لیکن یہاں «مسنہ» سے مراد «مسنۃ من المعز» :(یعنی دانت والی بکری ) مراد ہے، کیونکہ اس کے مقابلے میں «جذعۃ من الضان» :(ایک سال کا دنبا ) لایا گیا ہے، یعنی: دانت والی بکری ہی جائز ہے، جس کے سامنے والے دو دانت ٹوٹ چکے ہوں ایک سال کی بکری جائز نہیں، ہاں اگر دانت والی بکری میسر نہ ہو تو ایک سال کا دنبہ جائز ہے۔","الألباني: ضعيف",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’تم قربانی میں صرف مسنہ جانور ہی ذبح کر والا یہ تمھیں مسنہ ملنا مشکل ہو تو پھر تم بھیڑ کا جذعہ ذبح کر سکتے ہو۔‘‘","f2":"دو دانتا جانور قربان کرنا مستحب ہے۔ مسنہ نہ ملنے یاعدم استطاعت کی صورت میں بھیڑ کا جذعہ بھی جائز ہے۔ اس کی عمر متعلق اہل علم کے مختلف اقوال ہیں کہ کتنی عمر جذعہ قربانی کے قابل ہو گا۔ جمہور اہل علم اور محدثین کا نقطہ نظریہ ہے کہ اس کی عمر سال یا سکے قریب قریب ہونی چاہیے۔ نیز معلوم ہوا کہ جذعہ، یعنی پکا کھیرا صرف بھیڑ کا قربان ہو سکتا ہے۔ بکری، گائے یا اونٹ وغیرہ کا نہیں۔ حدیث کے اس کی صریح اور ٹھوس دلیل ہیں۔ اہل علم محدثین وغیرہ کا یہی قول ہے۔ جس جانور کیک دانت گر جائیں، اسے عربی زبان میں کہا جاتا ہے۔ اردو میں اسے’’ دہ دانتا‘‘ اور پنجابی میں’’دوندا‘‘ کہتے ہیں۔ بعض حضرات نے مسنہ کے معنی’’ایک سال‘‘ کا کیا ہے، حالانکہ یہ معنی لغت کے لحاظ سے صحیح ہیں نہ عرف کے لحاظ سے کیونکہ مسنہ لفظ سے بنا ہے جس کے معنی دانت ہوتے ہیں، نہ کہ سے جس کے معنی سال کے ہوتے ہیں۔ عرفاََ بھی بکرا ایک سال میں دو دانتا نہیں ہوتا، اکثر بعد میں ہوتا ہے۔ شاذ و نادر طور پر ایک سال کا بھی ہو سکتا ہے مگر عموماََ نہیں۔ حکم عموم سے لحاظ سے ہوتا۔ ہے۔ جبکہ اصل مقصد دانت کا گرنا ہے نہ کہ عمر، اس لیے کہ دانت گرنے کے لیے کوئی عمر معین نہیں، نیز عمر کا تعین بھی مسکل ہے۔ اس میں اختلاف ہو سکتا ہے۔ کوئی شخص بیچنے کے لیے جھوٹ بھی بول سکتا ہے، مگر دانت گرنا اور اس کی جگہ نیا دانت آنا ایک واضح اور یقینی علامت ہے جس میں فراڈ ممکن نہیں، لہٰذا صحیح بات یہی ہے کہ قربانی کا جانور دود انتا(دوندا) ہو، بکرا ہویا گائے یا اونٹ اور یہ سب جانور مختلف عمروں میں دودانتے ہوتے ہیں، البتہ اگر یہ نہ مل سکے یا اس کی استطاعت نہ ہو تو بھیڑ کے جذعہ کی بھی اجازت ہے مگر ضروری ہے کہ وہ موٹا تازہ اور دو دانتے سے قریب ہو۔ بعض لوگوں نے تحدید کی کوشش کی ہے۔ چھ ماہ سے لے کر ایک سال تک کے اقوال ہیں۔ شک و شبہ سے بچنے کے لیے ایک سال سے کم بھیڑ یا دنبہ کرنا چاہیے۔ لغت میں ایک سال قول ہی زیادہ مشہور ہے، جمہور اہل علم نے اسے ہی اختیار کیا۔ عقلاََ بھی یہی بات درست ہے کیونکہ دو دانتا نہ ہونے کی صورت میں کوشش یہی ہونی چاہیے کہ اس ملتا جلتا جانور ہی ذبح کیا جائے نہ کہ چھ ماہ کا جو دو دانتے سے بہت کم ہوتا ہے۔"}],[4379,"عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم کو آپس میں تقسیم کرنے کے لیے بکریاں دیں، صرف ایک سال کی بکری بچ رہی۔ اس کا ذکر انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے کیا۔ تو آپ نے فرمایا: \"تم اسے ذبح کر لو\" ۱؎۔\n§وضاحت\n۱؎: «عتود» ایک سال کی بکری کو کہتے ہیں۔ «جذعہ» بھی اسی معنی میں ہے، پس اگلی دونوں روایتوں میں جو «جذعہ» کا لفظ ہے اس کا مطلب ہے «جذعۃ من المعز» یعنی بکری کا ایک سالہ بچہ۔ نبی اکرم صلی اللہ علیہ وسلم نے عقبہ یا ابوبردہ رضی اللہ عنہما کو مجبوری کے تحت ایک سال کی بکری کی اجازت خصوصی طور سے دی تھی ورنہ قربانی میں اصل دانتا ہوا جانور ہی جائز ہے جیسا کہ حدیث نمبر: ۴۲۸۳ میں گزرا۔ ۲؎: \"تم اسے ذبح کر لو\" یعنی صرف تمہارے لیے جائز ہے۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اسے کچھد بکریاں دیں کہ صحابہ میں تقسیم کر دے۔ آخر میں ایک جذعہ(بکری کا ایک سالہ بچہ، یعنی میمنا) بچ گیا۔ انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے ذکر کیا تو آپ نے فرمایا:’’چلو! تم اس کی قربانی کردو۔‘‘","f2":"1)امام اور حاکم وقت کو چاہیے کہ جب رعایا کے پاس قربانی کرنے کے لیے جانور نہ ہوں تو وہ قربانی کے جانور ان میں تقسیم کرے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ کرام رضی اللہ عنہم میں بکریاں تقسیم وہ قربانی کے جانور ان میں تقسیم کرے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ کرام رضی اللہ عنہم بکریاں تقسیم فرمائیں۔ 2)حدیث مبارکہ سے مسئلہ تو کیل(کسی کو اپنا و کیل بنانا) بھی ثابت ہوتا ہے جس طرح کہ رسول اللہ صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم میں بکریاں تقسیم کرنے کے لیے حضرت عقبہ بن عامر رضی اللہ عنہ کو وکیل تقسیم بنایا۔3) ایک بکری بھی قربانی کے لیے کافی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے اس مقصد کی خاطر صحابہ کرام رضی اللہ عنہم میں ایک ایک بکری ہی تقسیم کرائی تھی۔4)جذعہ حدیث میں لفظ عتود آیا ہے اور اس سے مراد بکری کا نو جوان بچہ ہے جو ماں کے بغیر چرتا پھرتا ہے اور ایک سال کا ہو جائے۔ جذعہ بھی اسی طرح کا ہوتا ہے، لہٰذا معروف لفظ کے ساتھ ترجمہ کیا گیا ہے۔ مزید برآں یہ بھی ہے کہ دیگر صحیح احادیث میں بھی یہی لفظ’’جذعہ‘‘ مذکور ہے جیسا کہ امام نسانی رحمہ اللہ نے خود بھی وہ احادیث بیان کی ہیں۔ سابقہ اور آنے والی احادیث ملا حظہ فرمائیں۔5)’’اس کی قربانی کردو‘‘ بعض روایات میں یہ الفاظ بھی ہیں کہ تیرے علاوہ کسی کفایت نہیں کرے گا۔ معلوم ہوا انھیں رسول اللہ صلی اللہ علیہ وسلم کی طرف سے خاص اجازت ملی، اس لیے اب کسی فرد کے لیے اس کا جواز نہیں، خواہ تنگ دست ہی کیوں نہ ہو۔"}],[4380,"عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم کے درمیان قربانی کے جانور تقسیم کیے، میرے حصے میں ایک جذعہ آیا، میں نے عرض کیا: اللہ کے رسول! میرے حصے میں تو ایک جذعہ آیا ہے؟ آپ نے فرمایا: \"تم اسی کی قربانی کر لو\"۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ میں قربانی کے جانور تقسیم فرمائے۔ میرے لیے ایک جذعہ رہ گیا۔ میں نے عرض کی: اے اے اللہ کے رسول! میرے لیے جذعہ بچا ہے۔ آپ نے فرمایا:’’تو وہی قربان کر دے۔‘‘"}],[4381,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم کے درمیان قربانی کے جانور تقسیم کیے، تو مجھے ایک جذعہ ملا، میں نے عرض کیا: اللہ کے رسول! مجھے تو ایک جذعہ ملا ہے؟ آپ نے فرمایا: \"تم اسی کی قربانی کرو\"۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ میں قربانی جانور تقسیم فرمائیْ مجھے ایک جذعہ ملا۔ میں نے عرض کی: اللہ کے رسول! مجھے جذعہ ملا ہے۔ آپ نے فرمایا:’’تو یہی ذبح کر دے۔‘‘"}],[4382,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جذعہ یعنی ایک سال کی بھیڑ کی قربانی کی ۱؎۔\n§وضاحت\n۱؎: اولاً تو اس کے راوی \"معاذ بن عبداللہ\" بذات خود صدوق ہونے کے باوجود روایت میں وہم کا شکار ہو جایا کرتے تھے، تو ممکن ہے کہ «جذعۃ من المعز» یا صرف «جذعۃ» ہو اور انہوں نے وہم سے «جذعۃ من الضان» کر دیا ہو، ثانیاً: ہو سکتا ہے کہ یہ مجبوری کی صورت میں ہو، بہرحال بعض علماء اس حدیث اور اگلی دونوں حدیثوں سے استدلال کرتے ہوئے بغیر مجبوری کے بھی \"ایک سالہ دنبہ\" کی قربانی کو جائز قرار دیتے ہیں اور «مسنہ» والی حدیث کو استحباب پر محمول کرتے ہیں۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ سے مروی ہے کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم سے ساتھ قربانی میں بھیڑ کے جذعے ذبح کیے۔"}],[4383,"کلیب کہتے ہیں کہ ہم سفر میں تھے کہ عید الاضحی کا وقت آ گیا، تو ہم میں سے کوئی دو دو یا تین تین جذعوں (ایک سالہ بھیڑوں) کے بدلے ایک مسنہ خریدنے لگا، تو مزینہ کے ایک شخص نے ہم سے کہا: ہم لوگ ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ یہی دن آ گیا (یعنی عید الاضحی) تو ہم میں سے کوئی دو یا تین جذعے دے کر مسنہ خریدنے لگا، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جذعہ سے بھی وہی حق ادا ہو سکتا ہے جو «ثنی» یعنی مسنہ سے ہوتا ہے\" ۱؎۔\n§وضاحت\n۱؎: ایک تو بقول ابن المدینی \"عاصم بن کلیب\" جب روایت میں منفرد ہوں تو ان کی روایت سے استدلال جائز نہیں، دوسرے: ممکن ہے کہ«الجذع» سے مراد «الجذع من الضان» \" بھیڑ کا ایک سالہ بچہ \" ہو، بکری کا نہیں، تاکہ حدیث نمبر ۴۳۸۳ سے مطابقت ہو سکے۔","الألباني: صحيح",{"u2":"حضرت عاصم بن کلیب کے والد محترم نے فرمایا: ہم ایک سفر میں تھے۔ قربانیوں کا وقت آ گیا تو ہم میں سے کوئی شخص دو دو، تین تین جذعے دے کر مسنہ خریدتا تھا۔ مزینہ قبیلے کا ایک شخص ہمیں کہنے لگا: ہم ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ یہ دن(عید الاضحی) آ گیا تو لوگ دو دو، تین تین جذعے دے کر مسنہ خریدنے لگے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جذعہ کفایت کر سکتا ہے جہاں دو دانتا کفایت کرتا ہے۔‘‘","f2":"1)مسنہ اور بوقت ضرورت بھیڑ کے جذعہ کی قربانی جائز ہے۔2) اس حدیث مبارکہ سے یہ بھی معلوم ہوتا ہے کہ سفر میں بھی قربانی کرنا مشروع ہے۔3) جانوروں کی،جانوروں کے بدلے خریدہ فروخت جائز ہے، نیز اس میں کمی بیشی بھی جائد ہے، یعنی ایک جانور بدلے میں دو یا زیادہ جانور لیے اور دیے جا سکتے ہیں۔4) اس اور دیگر روایات کا جائزہ لینے سے معلوم ہوتا ہے کہ مسنہ کی قربانی افضل ہے۔"}],[4384,"کلیب ایک شخص سے روایت کرتے ہیں کہ اس نے کہا: ہم عید الاضحی سے دو دن پہلے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ تھے، ہم دو جذعے دے کر «ثنیہ» یعنی مسنہ لے رہے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جذعہ بھی اس کام کے لیے کافی ہے جس کے لیے «ثنیہ» یعنی مسنہ کافی ہے\"۔","الألباني: صحيح",{"u2":"ایک صحابی رضی اللہ عنہ سے روایت ہے کہ ہم عیدالاضحی سے دو دن قبل نبی اکرم صلی اللہ علیہ وسلم کے ساتھ تھے۔ ہم دو دانتے کے عوض دو دو جذعے دیتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’دو دانتے کی جگہ جذعہ بھی کفایت کر سکتا ہے۔‘‘"}],[4385,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم دو مینڈھوں کی قربانی کرتے تھے اور میں بھی دو مینڈھوں کی قربانی کرتا تھا ۱؎۔\n§وضاحت\n۱؎: یہ بطور استحباب ہے :(ورنہ ایک جانور ایک گھر کی طرف سے کافی ہے ) آپ صلی اللہ علیہ وسلم تو کبھی سو سو اونٹ ذبح کر دیا کرتے تھے، تو اس سے وجوب پر کسی نے استدلال نہیں کیا ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم دو مینڈھے قربان کیا کرتے تھے اور میں بھی دو مینڈھے ہی قربان کرتا ہوں۔","f2":"دیگر روایات میں ہے کہ ایک مینڈھا اپنی طرف سے اور دوسرا مینڈھا اپنی امت کے ان غریب لوگوں کی طرف سے قربان کرتے تھے جو خود قربانی نہیں کر سکتے تھے۔ یہ رسول اللہ صلی اللہ علیہ وسلم کا خاصا ہے کیونکہ عام امتی کی قربانی صرف اپنے اہل خانہ کی طرف سے کفایت کرتی ہے۔ اس لیے اس حدیث سے صرف فوت شدہ کے لیے قربانی کرنے کا جواز کشید کرنا، جبکہ قربانی کرنے والا خود اس قربانی میں شریک نہ ہو، محل نظر ہے۔"}],[4386,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے خطبے میں صدقہ پر ابھارتے اور مثلہ سے منع فرماتے تھے۔\n§وضاحت\n۱؎: مردہ کے ہاتھ پاؤں اور کان ناک کاٹ دینے کو مثلہ کہتے ہیں۔\nانس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دو چتکبرے مینڈھوں کی قربانی کی۔\n§وضاحت\n۱؎: \"چتکبرے\" یعنی سفید اور کالا یا کالا اور لال رنگ۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دو چتکبرے مینڈھے قربان کیے۔"}],[4387,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے دو چتکبرے مینڈھوں کی جن کے سینگ برابر تھے قربانی کی، انہیں اپنے ہاتھ سے ذبح کیا اور «بسم اللہ واللہ اکبر» کہا اور اپنا (دایاں) پاؤں ان کی گردن کے پہلو پر رکھا ۱؎۔\n§وضاحت\n۱؎: جانور کو قبلہ رخ لٹا کر اس کی گردن کے دائیں پہلو پر ذبح کرنے والا اپنا دایاں پاؤں رکھے گا اس سے جانور پر مکمل قابو حاصل ہو جاتا ہے، اور جانور زیادہ حرکت نہیں کر پاتا جو اسی کے لیے بہتر ہوتا ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے دو چتکبرے، سینگوں والے مینڈھے قربان کیے۔ آپ نے ان کو اپنے سے ذبح فرمایا۔ بسم اللہ پڑھی اور اللہ اکبر کہا اور اپنا پاؤں ان کی گردن کے پہلو پر رکھا۔","f2":"ترتیب الٹ ہے۔ آپ نے جانور لٹایا۔ اپنا پاؤں اس کی گردن کے پہلو پر رکھا۔ بسم اللہ و اللہ اکبر پڑھا اور اپنے دست مبارک سے اسے ذبح فرمایا۔ گردن کے پہلو پر پاؤں رکھنے کی وجہ اسے قابو تھا تاکہ چھری چلنے کے دور ان میں ان وہ اٹھ کٹھرا نہ ہو، نیز چھری تیزی اور قوت سے چل سکے۔ سر ادھر ادھر نہ حرکت کرے۔ اور زیادہ تکلیف نہ ہو۔"}],[4388,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے عید الاضحی کے دن خطبہ دیا اور دو چتکبرے مینڈھوں کے پاس آئے پھر انہیں ذبح کیا(مختصر)۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے عید الاضحی کے دن خطبہ ارشاد فرمایا، پھر دو سیاہ و سفید مینڈھوں کی طرف بڑھے اور ان کو ذبح فرمایا۔((یہ روایت) مختصر ہے۔"}],[4389,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ پھر آپ (گویا کہ ان کی مراد رسول اللہ صلی اللہ علیہ وسلم ہیں) قربانی کے دن (نماز عید کے بعد) دو چتکبرے مینڈھوں کی طرف مڑے، انہیں ذبح کیا، اور بکری کے ایک ریوڑ کی طرف گئے اور انہیں ہمارے درمیان تقسیم کیا۔","الألباني: صحيح",{"u2":"حضرت ابو بکرہ رضی اللہ عنہ بیان کرتے ہیں کہ پھر نبی اکرم صلی اللہ علیہ وسلم قربانی والے دن دو سیاہ و سفید مینڈھوں کی طرف متوجہ ہوئے اور انھیں ذبح فرمایا، نیز آپ نے کچھ بکریاں صحابہ میں تقسیم فرمائیں(تاکہ وہ بھی قربانی کر سکیں)۔"}],[4390,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سینگ والے موٹے دنبہ کی قربانی کی جو چلتا تھا سیاہی میں کھاتا تھا سیاہی میں اور دیکھتا تھا سیاہی میں ۱؎۔\n§وضاحت\n۱؎: یعنی اس کا پاؤں، اس منہ اور اس کی آنکھیں سب سیاہ :(کالے ) تھے۔","الألباني: صحيح",{"u2":"حضرت ابو سعید رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ایک نر، سینگوں والا مینڈھا قربان فرمایا جس کی ٹانگیں سیاہ تھیں، منہ اور پیٹ بھی سیاہ تھا اور آنکھیں بھی سیاہ تھیں۔(باقی سفید تھا۔)","f2":"1)مینڈھے دنبے اور چھترے وغیرہ کی قربانی جائز ہے۔2) سینگوں والے مینڈھے کی قربانی کرنا مستحب ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم بذات خود سینگوں والے مینڈھے قربان فرمایا کرتے تھے۔3)حدیث مبارکہ سے سینگوں والے، چتکبرے اور نر مینڈھوں کی قربانی کا استحباب معلوم ہوتا ہے، نیز خصی جانور کو قربان کرنا بھی جائز ہے جیسا کہ دوسری حدیث میں آتا ہے۔"}],[4391,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مال غنیمت کی تقسیم کے وقت دس بکریوں کو ایک اونٹ کے برابر رکھتے تھے۔ شعبہ کہتے ہیں: مجھے غالب یقین یہی ہے کہ میں نے اسے سعید بن مسروق (سفیان ثوری کے والد) سے سنا ہے اور اسے مجھ سے سفیان نے ان سے روایت کرتے ہوئے بیان کیا، واللہ اعلم۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم غنیمت تقسیم فرماتے وقت دس بکریوں کو ایک اونٹ کے برابر رکھا کرتے تھے۔\n(راوی حدیث امام) شعبہ نے یہ حدیث کی سند سے بیان کی ہے، یعنی شعبہ یہ حدیث سفیان ثوری سے اور وہ اپنے باپ(سعید بن مسروق) سے بیان کرتے ہیں، تاہم امام شعبہ فرماتے ہیں کہ میرا خیال ہے کہ میں یہ حدیث(سفیان ثوری کے واسطے کے بغیر) اس(سفیان) کے والد محترم سعید بن مسروق سے بھی سنی ہے۔","f2":"قربانی اونٹ، گائے، بکری اور بھیڑ کی ہو سکتی ہے۔ چونکہ ہر آدمی بڑے جانور کی استطاعت نہیں رکھتا، لہٰذا چھوٹے جانور، یعنی بھیڑ بکری کی قربانی کرنا بھی درست ہے جبکہ گائے اور اوٹ کی قربانی مستحب۔ جس طرح ایک قربانی واجب ہے، زائد مستحب۔ گائے، بکری سے بہت ہوتی ہے اور اونٹ گائے سے کافی بڑا، اس لیے گائے کو برابر سمجھتے ہیں جیسا کہ آئندہ حدیث میں آرہا ہے مگر اونٹ اور گائے کا فرق واضح ہے جسے بچہ بھی محسوس کر سکتا ہے۔ دونوں کو برابر سمجھنا عجیب بات ہے۔ باب والی حدیث اونٹ کو دس بکریوں کے برابر قرار دے رہی ہے۔ باقی رہی سات والی حدیث تو اس میں اس سات سے زائد کی نفی نہیں جبکہ آئندہ حدیث دس کے بارے میں صریح ہے،لہٰذا اس کو ترجیح ہونی چاہیے۔ بعض علماء نے یوں تطبیق دینے کی کوشش کی ہے کہ دس والی روایت عام قربانیوں کے بارے میں جبکہ سات والی روایت حرم میں ذبح ہونے والی قربانیوں کے بارے میں ہے۔ بعض اہل علم نے سفر میں اونٹ کو دس قربانیوں کے برابر قرار دیا ہے جبکہ حضر میں سات کے برابر لیکن یہ سارے کے سارے اپنے اپنے انداز اور تخمینے ہی ہیں۔"}],[4392,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ہم لوگ ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ قربانی کا دن آ گیا، ہم ایک اونٹ میں دس دس لوگ اور ایک گائے میں سات سات لوگ شریک ہوئے ۱؎۔\n§وضاحت\n۱؎: اس حدیث سے استدلال کرتے ہوئے کچھ علماء قربانی میں اونٹ میں دس آدمیوں کی شرکت کو جائز قرار دیتے ہیں، جب کہ جمہور علماء صحیح مسلم میں مروی جابر رضی اللہ عنہ کی حدیث :(حج ۶۱، ۶۲ ) کی بنیاد پر اونٹ میں بھی صرف سات آدمیوں کی شرکت کے قائل ہیں، حالانکہ دونوں :(جابر و ابن عباس رضی اللہ عنہم کی ) حدیثوں کا محمل اور مصداق الگ الگ ہے، ابن عباس رضی اللہ عنہما کی حدیث قربانی میں شرکت کے سلسلے میں ہے جب کہ جابر رضی اللہ عنہ کی حدیث ہدی :(حج کی قربانی ) سے متعلق ہے، دونوں :(قربانی و ہدی ) کو ایک دوسرے پر قیاس کرنے کی وجہ سے علماء میں مذکورہ اختلاف واقع ہوا ہے، دونوں حدیثوں میں تطبیق کی یہی صورت ہے کہ دونوں کا محل الگ الگ ہے، :(یعنی قربانی میں اونٹ دس کی طرف سے کافی ہے اور ہدی میں صرف سات کی طرف سے ) علامہ شوکانی نے یہی بات لکھی ہے :(کمافی نیل الا ٔوطار )۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ ہم ایک سفر میں رسو ل اللہ صلی اللہ علیہ وسلم کے ساتھ تھے۔ قربانیوں کا وقت ا ٓگیا تو اہم اونٹ میں دس اور گائے میں سات افراد شریک ہوئے۔","f2":"معلوم ہوا سفر میں بھی قربانی کی جائے گی جس طرح گھر میں۔ یا د رہنا چاہیے کہ پور ے ایک گھر پر ایک قربانی ہی واجب ہے، نہ کہ ہر ہر فر د پر۔ گائے سات گھر وں کی طرف سے اور اونٹ دس گھروں کی طرف سے کافی ہے۔ گھر سے مراد خاوند بیوی بچے ہیں یا وہ افراد جو ایک سربراہ (باپ) کی کفالت میں رہتے ہوں جبکہ شادی شدہ مرد الگ گھر انہ ہو گا، بشر طیکہ وہ خود کفیل ہوں۔ اگر خود کفیل نہیں بلکہ باپ ہی کے زیر دست ہوں تو پھرو ہ سب ایک ہی فیملی شمار ہو ں گے۔"}],[4393,"جابر رضی اللہ عنہ کہتے ہیں کہ ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (حج) تمتع کر رہے تھے تو ہم سات لوگوں کی طرف سے ایک گائے ذبح کرتے اور اس میں شریک ہوتے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کر تےہیں کہ ہم نے رسو ل اللہ صلی اللہ علیہ وسلم کے ساتھ تمتع کیا تو گائے سات افراد کی طرف سے ذبح کرتے تھے اور اس میں شریک ہو تے تھے۔","f2":"یہ شرکت قربانی ہی میں ہو سکتی ہے عقیقے میں نہیں کیونکہ قربانی کا ایک ہی دن معین ہے جبکہ عقیقہ ہر بچے کی پیدائش کے حساب سے کیا جاتا ہے۔"}],[4394,"براء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عید الاضحی کے دن کھڑے ہو کر فرمایا: \"جس نے ہمارے قبلے کی طرف رخ کیا، ہماری جیسی نماز پڑھی اور قربانی کی تو وہ جب تک نماز نہ پڑھ لے ذبح نہ کرے۔ یہ سن کر میرے ماموں کھڑے ہوئے اور عرض کیا: اللہ کے رسول! میں نے قربانی میں جلدی کر دی تاکہ میں اپنے بال بچوں اور گھر والوں - یا اپنے گھر والوں اور پڑوسیوں - کو کھلا سکوں، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دوبارہ قربانی کرو\"، انہوں نے عرض کیا: میرے پاس بکری کا ایک چھوٹا بچہ ۲؎ ہے جو مجھے گوشت والی دو بکریوں سے زیادہ عزیز ہے، آپ نے فرمایا: \"تم اسی کو ذبح کرو، یہ ان دو کی قربانی سے بہتر ہے، لیکن تمہارے بعد جذعے کی قربانی کسی کی طرف سے کافی نہیں ہو گی\"۔\n§وضاحت\n۱؎: یعنی: امام سے پہلے یعنی عید الاضحی کی نماز سے پہلے قربانی کا کیا حکم ہے ؟ ۲؎: «عناق لبن» سے مراد وہ بکری جو ابھی ایک سال کی نہیں ہوئی ہو، اور حدیث نمبر ۴۳۸۴ میں اسی تناظر میں «عتود» کا لفظ آیا ہے، جس کے معنی ہیں بکری کا وہ بچہ جو ایک سال ہو چکا ہو مگر دانتا ہوا نہ ہو، اور دونوں کا خلاصہ یہ ہے کہ مذکورہ دونوں قسم کے جانوروں کی قربانی کی اجازت صرف مذکورہ دونوں صحابہ کے لیے دی گئی، اور عام حالات میں عام مسلمانوں کے لیے صرف دانتا جانور ہی جائز ہے۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہ نے فرمایارسو ل اللہ صلی اللہ علیہ وسلم عید الا ضحی ٰ کے دن (خطبہ ارشاد فرمانے کے لیے) کھڑے ہوئے اور فرمایا: \" جو شخص ہمارے قبلے کی طرف منہ کر تا ہے، ہماری طر ح نما ز پڑ ھتا ہے اور ہما ری طر ح قربانی کر تاہے تو و ہ اپنی قر بانی ذبح نہ کر ے حتی کہ نماز عید نماز پڑھ لے۔\" میرے ماموں کھڑے ہو ئے اور کہنے لگے: اے اللہ کے رسو ل! میں نے تواپنی قربانی جلدی ذبح کر لی تاکہ میں اپنے گھر والوں اور محلے دار پڑ و سیوں کو (جلدی) گو شت کھلاوں۔ رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا: \" اور قربانی ذبح کر۔ \" انھوں نے کہا:میرے پاس بکری کا ایک مادہ بچہ ہے جو مجھے گوشت کے لحاظ سے دو بکریوں سے بھی اچھا لگتا ہے۔ آپ نے فرمایا: \" اسے ہی ذبح کردے۔ وہ تیری دو قربانیوں میں سے اچھی قر بانی ہو گی۔ لیکن تیرے علاوہ کسی کی طر ف سے جذ عہ قربانی میں کفایت نہیں کر ے گا۔\"","f2":"(1)اس حدیث سے استدلال کیا گیا ہے کہ جس شخص نے قربانی کا التزام کیا ہو ا گر وہ قربانی اس سے ضائع ہوجائے بایں طور کہ وہ نماز عید سے پہلے قر بانی کردے، یا قر بانی کا جانور مرجائے، یا اسی طر ح کا کوئی مسئلہ بن جائے تو اس کے بدلے اس پر دوسر ی قربانی واجب اور ضروری ہوگی۔ بشرطیکہ وہ قربانی کر نے کی طاقت رکھتا ہو۔ اگروہ شخص دوسری قربانی کی استطا عت ہی نہیں رکھتا تو اس پر قربانی کر نا واجب نہیں ہے کیو نکہ ارشاد باری ہے: (لا یکلف اللہ نفسا الا و سعھا)(البقرۃ:2/286) \"اللہ کسی نفس کو نہیں تکلیف دیتا مگر اس کی وسعت کے مطابق ہی \" اسی طر ح بھی ارشاد بانی ہے: فاتقو اللہ ما استطعتم)(التغابن:64/16)\nاللہ تعالیٰ سے ڈر و جتنی طاقت رکھتے ہو۔ \" یا در ہے طاقت اور وسعت کے باوجو د اگر کوئی قربانی نہیں کرتا وہ گنا ہ گار ہے۔2۔ اس حدیث مبارکہ سے یہ اہم مسئلہ بھی ثابت ہو ا کہ احکام و مسائل میں مرجع صرف بنی صلی اللہ علیہ وسلم کی ذات مبارکہ ہے یہ حیثیت آپ ہی کی ہے کہ افراد امت میں سے کسی کو، کسی حکم کے ذریعے سے خاص کر دیں اور دوسرے لو گوں کو روک دیں جیسا کہ آپ نے حضرت براء بن عازب کے ماموں حضرت ابو بردہ بن نیار کے ساتھ کیا۔ 3 اس حدیث مبارکہ سے یہ مسئلہ بھی ثابت ہو تاہے کہ نماز عید کی ادائیگی سے پہلے قربانی کر نا قطعی طور پر ناجائز ہے، خوا ہ نیت نیکی اور ثوا ب کمانے ہی کی ہو جیسا کہ حضرت ابو بردہ رضی اللہ عنہ کی نیت اپنے اہل و عیال اور محلے دار (غیرب) ہمسایوں کو گوشت کھلانے کی تھی۔4 حدیث مبارکہ سے یہ بھی معلوم ہو تا ہے کہ امام کو چایہے خطبہ عید میں قربانی سے متعلق احکام و مسائل بیان کرے۔ 5 یہ حدیث اس بات پر بھی دلالت کرتی ہے کہ شارع علیہ السلام کا ایک شخص کو خطاب تمام لوگوں کے لیے خطاب ہو تاہے، لٰہذا دیگر لو گ بھی اس حکم کے مکلف اور پابند ہوتے ہیں حضرت ابو بردہ رضی اللہ عنہ کو بکری کا بچہ ذبح کرنے کی اجازت دی تو ساتھ ہی یہ بھی بیا ن فر ما دیا کہ تیرے بعداورکسی کے، لیے قربانی میں، اس عمر کا بکری کا بچہ کفایت نہیں کرے گا۔ اگر بنی صلی اللہ علیہ وسلم یہ الفاظ نہ فرماتے تو پھر ہرشخص کے لیے یہ اجازت ہوتی۔ 6 یہ بھی معلوم ہوتا ہے کہ نیک نیتی سے کیاجانے والا صالح عمل بھی اس وقت تک اللہ کے ہا صحیح اور قابل قبول نہیں ہوسکتا جب تک وہ شریعت مطہرہ کے مطابق سرانجام نہ د یا جائے۔7 اس حدیث میں یہ ذکر تو نہیں کہ امام سے پہلے قربانی نہیں کر نی چاہیے لیکن چونکہ اس دور میں بنی صلی اللہ علیہ وسلم نماز عید کے بعد سب لو گوں کے سامنےوہیں قر بانی کردیتے تھے۔ با قی لوگ بعد میں کرتے تھے، لٰہذ ا کہا جا سکتا ہے کہ امام کے بعدقربانی کر نی چاہیے لیکن اگر امام قربانی نہ کرے یا وہ عید گا ہ میں خطبہ کے فورا بعد نہ کرے تو لوگوں پر کوئی ایسی پابندی نہیں کہ وہ لازما امام صاحب سے بعد ہی کریں، البتہ نماز عید سے پہلے قطعا نہیں ہونی چاہیے۔ امام مالک رحمتہ اللہ علیہ تو ایسے امام کی امامت عید ہین درست نہیں سمجھتے جو قربانی نہ کرے، نیز ان کے نزدیک امام کو قربانی عید گا ہ میں سب سے پہلے کرنی چاہیے۔ خیر امام مالک رحمتہ اللہ علیہ کی رائے اور اجتہاد ہ ہے جس سے اتفاق ضروری نہیں۔8 اچھی قربانی ہوگی \" کیونکہ وہ بروقت ہوئی اور قبول ہوئی، بخلاف پہلی قربانی کے کہ وہ وقت سے پہلے ذبح ہونےکی وجہ سے قبولیت سے محرومی رہی۔9\"کفایت نہیں کرے گا\" رسول اللہ صلی اللہ علیہ وسلم کے مذکورالفاظ سے معلوم ہوتاہے کہ آپ کا مقصود یہ تھا کہ تیرے جیسا لا چار شخص بھی مثلا: جو غلطی سے قربانی بے وقت ذبح کر چکا ہو یا اس کی قربانی کا جانور مر گیا ہو، یا گم ہو گیا ہو اور وہ مزید خریدنے کی اسطاعت نہ رکھتا ہو، تو بکری کا جذعہ ذبح نہیں کر سکتا۔ یہی وجہ ہے کہ محدثین نے ظاہر کا خیا ل رکھتے ہوئے ان کسی کو بھی، خواہ وہ معذور و مجبو ر ہی ہو، جذعہ (بکرا) قربان کرنے کی اجازت نہیں دی۔ واللہ اعلم"}],[4395,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ قربانی کے دن رسول اللہ صلی اللہ علیہ وسلم نے نماز عید کے بعد ہمیں خطبہ دیا اور فرمایا: \"جس نے ہماری جیسی نماز پڑھی اور ہماری جیسی قربانی کی تو اس نے قربانی کی اور جس نے نماز عید سے پہلے قربانی کی تو وہ گوشت کی بکری ہے ۱؎ یہ سن کر ابوبردہ رضی اللہ عنہ نے عرض کیا: اللہ کے رسول! اللہ کی قسم! میں نماز کے لیے نکلنے سے پہلے ہی قربانی کر چکا ہوں، دراصل میں نے سمجھا کہ آج کا دن کھانے پینے کا دن ہے، تو میں نے جلدی کی اور کھایا اور اپنے بال بچوں نیز پڑوسیوں کو کھلایا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ تو گوشت کی بکری ہے\"۔ وہ بولے: میرے پاس بکری کا ایک چھوٹا بچہ ہے جو گوشت کی ان دو بکریوں سے بہتر ہے، کیا وہ میرے لیے کافی ہو گا؟ آپ نے فرمایا: \"ہاں، لیکن تمہارے بعد یہ کسی کے لیے کافی نہیں ہو گا\"۔\n§وضاحت\n۱؎: اس کے لیے قربانی کا ثواب نہیں۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے قربانی والے دن نماز عید کے بعد ہمیں خطبہ ارشاد فرمایا:’’جوشخص ہم جیسی نماز پڑھتا ہے اور ہم جیسی قربانی کرتی ہے، اس نے تو صحیح قربانی کی اور جس نے جیسی قربانی کرتا ہے، اس تو صحیح قربانی کی اور جس نے نماز پڑھنے سے پہلے ہی قربانی کر دی تو وہ گوشت والی بکری ہے(وہ صرف گوشت کے لیے ذبح کیا گیا جانور متصور ہو گا۔ قربانی نہیں ہو گی)۔‘‘ حضرت ابو بردہ رضی اللہ عنہ کہنے لگے: اے اللہ کے رسول! اللہ کی قسم! میں نے تو نماز کے لیے آنے سے پہلے قربانی ذبح کر دی تھی۔ میں نے سمجھا کہ یہ سارا دن ہی کھانے پینے کے لیے، اس لیے میں نے جلد بازی کی۔ خود بھی گوشت کھایا اور گھر والوں اور پڑوسیوں کو بھی کھلایا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ یہ تو گوشت والی بکری ہو گئی(قربانی نہیں ہوئی)۔‘‘ انھوں نے عرض کی: میرے پاس ایک جذعہ بکری ہے جو گوشت کے لحاظ سے دو بکریوں سے بھی بہتر ہے تو کیا وہ مجھ سے کفایت کر جائے گی؟ آپ نے فرمایا:’’ہاں۔ لیکن وہ تیرے علاوہ کسی اور سے کفایت نہیں کرے گی۔‘‘"}],[4396,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قربانی کے دن فرمایا: \"جس نے نماز سے پہلے ذبح کر لیا ہے، اسے چاہیئے کہ پھر سے قربانی کرے\"، ایک شخص نے کھڑے ہو کر عرض کیا: اللہ کے رسول! یہ ایسا دن ہے کہ جس میں ہر ایک کی گوشت کی خواہش ہوتی ہے، اور پھر انہوں نے پڑوسیوں کا حال بیان کیا، گویا رسول اللہ صلی اللہ علیہ وسلم نے ان کی تصدیق فرمائی۔ انہوں نے کہا: میرے پاس بکری کا ایک چھوٹا بچہ ہے جو مجھے گوشت والی دو بکریوں سے زیادہ ہے، تو انہیں اس کی رخصت دی گئی، لیکن مجھے نہیں معلوم کہ یہ رخصت دوسروں کے لیے ہے یا نہیں؟ اس کے بعد آپ صلی اللہ علیہ وسلم دو مینڈھوں کی طرف گئے اور انہیں ذبح کیا۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قربانیوں کے دن فرمایا:’’ جس شخص نے نماز عید سے پہلے قربانی ذبح کرلی ہے وہ دوبار ذبح کرے۔‘‘ ایک آدمی اٹھ کر کہنے لگا: اے اللہ کے رسول! یہ دن ایسا ہے کہ اس میں گوشت کی خواہش ہوتی ہے، پھر اس نے اپنے پروسیوں کی حالت شاقہ(محتاجی اور فقر و فاقے) کا ذکر کیا۔ ایسے لگتا تھا کہ رسول اللہ صلی اللہ علیہ وسلم بھی اس کی تصدیق فرما رہے ہیں۔ اس نے کہا: میرے پاس ایک جذعہ(بکری کا چھوٹی عمر کا بچہ) ہے جو گوشت کی دو بکریوں سے بھی مجھے زیادہ پسند ہے۔ آپ نے اسے وہی جذعہ ذبح کرنے کی رخصت دی۔ میں نہیں، پھر آپ دو مینڈھوں کی طرف متوجہ ہوئے اور انھیں ذبح کیا۔","f2":"1) عنوان کے ساتھ حدیث کی مناسبت بظاہر تو معلوم نہیں ہوتی۔ امام نسائی رحمہ اللہ نے غالباََ رسول اللہ صلی اللہ علیہ وسلم کے فرمان:’’جس نے نماز عید سے پہلے قربانی ذبح کر لی، وہ دوبارہ قربانی ذبح کرے۔‘‘ کو امام کے ذبح کرنے پر محمول کیا ہے۔ امام مالک رحمہ اللہ اور بعض دیگر اہل علم کا یہی قول ہے۔ لیکن راجح بات یہی ہے کہ امام کے ذبح کرنے سے پہلے بھی قربانی ذبح کی جا سکتی ہے بشر طیکہ نماز عید کے بعد ہو۔ ظاہر اََ تو حدیث مبارکہ سے یہی معلوم ہوتا ہے۔2) افضل یہ ہے کہ انسان اپنی قربانی کا جانور خود، اپنے ہاتھوں ہی سے ذبح کرے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے دونوں مینڈھے خود ہی ذبح کیے تھے۔ اس پراجماع ہے، تاہم اگر کوئی دوسرا شخص بھی ذبح کر دے تو قربانی جائز ہوگی۔ 3)پورے گھرانے کی طرف ایک جانور(بھیڑ، بکریا، چھترا، چھتری اور مینڈھے وغیرہ) قربانی کفایت کر جاتی ہے، تا ہم دو یا زیادہ جانور ذبح کرنا افضل اور پسندیدہ عمل ہے۔"}],[4397,"ابوبردہ بن نیار رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے پہلے ذبح کیا تو آپ صلی اللہ علیہ وسلم نے انہیں دوبارہ ذبح کرنے کا حکم دیا۔ انہوں نے عرض کیا: میرے پاس ایک سالہ بکری کا بچہ ہے جو مجھے دو مسنہ سے زیادہ پسند ہے، آپ نے فرمایا: \"اسی کو ذبح کر دو\"۔ عبیداللہ کی حدیث میں ہے کہ انہوں نے کہا: میرے پاس ایک جذعہ کے علاوہ اور کچھ نہیں ہے تو آپ نے انہیں اسی کو ذبح کرنے کا حکم دیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابو بردہ بن نیاز رضی اللہ عنہ سے منقول ہے کہ انھوں نے اپنی قربانی نبی اکرم صلی اللہ علیہ وسلم سے پہلے ذبح کر دی تھی تو نبی اکرم صلی اللہ علیہ وسلم نے انھیں دوبارہ قربانی کرنے کا حکم دیا۔ انھوں نے کہا: میرے پاس ایک جذعہ بکری ہے جو میرے نزدیک(گوشت کے لحاظ سے) بکری ہے جو میرے نزدیک(گوشت کے لحاظ سے) دو مسنوں سے بھی بہتر ہے۔ اس کے علاوہ اور کوئی نہیں۔ آپ نے فرمایا:’’اسے ذبح کردو۔‘‘"}],[4398,"جندب بن سفیان رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک دن کچھ قربانیاں کیں، تو ہم نے دیکھا کہ لوگ نماز عید سے پہلے ہی اپنے جانور ذبح کر چکے ہیں، جب آپ فارغ ہو کر لوٹے تو انہیں دیکھا کہ وہ نماز عید سے پہلے ہی ذبح کر چکے ہیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے نماز عید سے پہلے ذبح کیا تو اس کی جگہ دوسرا جانور ذبح کرے اور جس نے ذبح نہیں کیا یہاں تک کہ ہم نے نماز عید پڑھ لی تو وہ اللہ کے نام پر ذبح کرے\"۔","الألباني: صحيح",{"u2":"حضرت جندب بن سفیان رضی اللہ عنہ بیان کرتے ہیں کہ ہم نے ایک دن رسول اللہ صلی اللہ علیہ وسلم کے ساتھ قربانیاں ذبح کیں تو دیکھا کہ کچھ لوگ نماز سے پہلے ہی اپنی قربانیاں ذبح کر چکے تھے۔ جب آپ فارغ ہوئے تو آپ کو پتا چلا کہ وہ نماز سے پہلے ہی ذبح کر چکے ہیں تو آپ نے فرمایا:’’جس شخص نے قربانی نماز سے پہلے ذبح کی ہے، وہ اس کی جگہ اور قربانی ذبح کرے اور جس شخص نے نماز سے پہلے ذبح نہیں کی، وہ اب اللہ کا نام لے کر ذبح کرے۔‘‘","f2":"کسی ایک حدیث میں پوری تفصیلات ذکر نہیں ہوتیں، اس لیے اسے مختلف سندوں سے ذکر کیا جاتا تاکہ تمام تفصیلات معلوم ہو جائیں۔ فیصلہ کرتے وقت تمام تفصیلات کو مد نظر رکھا جاتا ہے۔"}],[4399,"محمد بن صفوان رضی اللہ عنہ سے روایت ہے کہ انہیں دو خرگوش ملے انہیں کوئی لوہا نہ ملا جس سے وہ انہیں ذبح کرتے تو انہیں پتھر سے ذبح کر دیا، پھر نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، اور کہا: اللہ کے رسول! میں نے دو خرگوش شکار کئے مجھے کوئی لوہا نہ مل سکا جس سے میں انہیں ذبح کرتا تو میں نے ان کو ایک تیز دھار والے پتھر سے ذبح کر دیا، کیا میں انہیں کھاؤں؟ آپ نے فرمایا: \"کھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت محمد بن صفوان رضی اللہ عنہ سے روایت ہے کہ انھوں نے دو خرگوش پکڑے لیکن ان کو ذبح کرنے کے لیے انھیں کوئی چھری و غیرہ نہ ملی تو انھوں نے ملی تو انھوں نے ان کو ایک تیز دھار پتھر سے ذبح کر دیا، پھ روہ نبی اکرم صلی اللہ علیہ وسلم کے پاس حاضر ہوئے اور عرض کی: اے اللہ کے رسول! میں نے دو خرگوش شکار کیے تھے لیکن مجھے کوئی چھری وغیرہ نہیں ملی جس سے ذبح کر تا۔ تومیں نے ایک تیز دھار پتھر سے ان کو ذبح کر دیا۔ کیان میں ان کو کھا سکتا ہوں؟ آپ نے فرمایا:؟ ہا ں، کھا لے۔\"","f2":"ذبح کرنے کا مقصد خون بہانا ہے جس کے چیز کے ساتھ بھی بہاد یاجائے جائز ہے، بشر طیکہ وہ تیز دھار ہو اور یکبار گی ذبح کرے۔ گلے پر دباو نہ دالے بلکہ تیزی سے کاٹ دے تاکہ مذبوح کو کم سے کم تکلیف ہو۔"}],[4400,"زید بن ثابت رضی اللہ عنہ سے روایت ہے کہ بھیڑیئے نے ایک بکری کے جسم میں دانت گاڑ دیے لوگوں نے اسے پتھر سے ذبح کیا تو نبی اکرم صلی اللہ علیہ وسلم نے اسے کھانے کی اجازت دے دی۔","الألباني: صحيح لغيره",{"u2":"حضرت زید بن ثابت رضی اللہ عنہ سے روایت ہے کہ ایک بھیڑ یے نے ایک بکری میں دانت گاڑ دیے۔ لوگوں نے (اس کو چھڑانے کے بعد) اسے ایک تیز دھار پتھر سے ذبح کردیا۔تو بنی اکرم صلی اللہ علیہ وسلم نے اس کے کھانے کی اجازت دی۔","f2":"اگر کسی جانور کو درند ہ کاٹ کھائے اور اس میں روح باقی ہو تو اسے ذبح کردیاجائے، وہ حلا ہو گا۔ہاں اگر وہ ذبح کرنے سے پہلے بے جان ہوتو خواہ سارا خون نکل چکا ہو، وہ جانور حر ام ہو گا۔"}],[4401,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! میں اپنا کتا چھوڑتا، اور شکار کو پا لیتا ہوں، میں پھر کوئی ایسی چیز نہیں پاتا جس سے میں ذبح کروں تو کیا میں دھاردار پتھر اور لکڑی سے ذبح کر سکتا ہوں؟ آپ نے فرمایا: \"جس چیز سے چاہو خون بہاؤ اور اس پر اللہ کا نام لو\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ عنہ نے فرمایا کہ میں نے عرض کی: اے اللہ کے رسول! میں اپنا کتا چھوڑتا ہوں اور شکار کر پکڑ لیتا ہوں لیکن مجھے کوئی ایسی چیز نہیں ملتی جس سے ذبح کر سکوں تو کیا میں اسے تیز دھار پتھر یا لکڑی سے ذبح کر سکتا ہوں؟ آپ نے فرمایا:’’ جس چیز سے بھی ہو سکے، خون بہا دے، البتہ اللہ عزو جل کا نام ضرور لے۔‘‘"}],[4402,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ انصار میں سے ایک شخص کی ایک اونٹنی تھی، جو احد پہاڑ کی طرف چرتی تھی، اسے عارضہ لاحق ہو گیا، تو اس نے اسے کھونٹی سے ذبح کر دیا۔ میں نے زید بن اسلم سے کہا: لکڑی کی کھونٹی یا لوہے کی؟ کہا: لوہا نہیں، بلکہ لکڑی کی کھونٹی سے، پھر اس انصاری نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر آپ سے پوچھا تو آپ نے اسے کھانے کا حکم دیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی کہ ایک انصاری کی اونٹنی احد کی طرف چر رہی تھی کہ وہ قریب المرگ ہو گئی۔ اس انصاری نے اسے ایک نوک دار کھونٹے کے ساتھ نحر(ذبح) کر دیا۔(راوی حدیث ایوب یا جریر نے کہا) میں نے پوچھا کہ وہ کھونٹا لکڑی کا تھا یا لو ہے کا؟ استاد نے کہا: نہیں، وہ لکڑی کا تھا، پھر وہ انصاری نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ سے مسئلہ پوچھا۔ آپ نے اسے کھانے کا حکم دیا۔","f2":"’’حکم دیا‘‘یعنی اجازت دی یا حقیقتاََ حکم مراد ہے کیونکہ شریعت کی رو سے حلال چیز کو ضائع کرنا جائز نہیں۔"}],[4403,"رافع بن خدیج رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس چیز سے (جانور کا) خون بہہ جائے اور اس پر اللہ کا نام لیا گیا ہو تو اسے کھاؤ، سوائے اس کے جو دانت اور ناخن سے ذبح کیا گیا ہو\"۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ جو چیز خون بہادے اور اللہ کا نام لیا گیا ہو تو(وہ ذبیحہ) کھا لے مگر دانت اور ناخن کا ذبح نہیں۔‘‘","f2":"دانت اور ناخن ذبح کرنے کے لیے نہیں بلکہ اور مقاصد کے لیے ہیں، اس لیے دانتوں اور ناخنوں سے ذبح کرنا و حشیانہ فعل ہے جیسا کہ آپ نے ایک ارشاد فرمایا کہ ناخن حبشیوں کی چھری ہے۔ یعنی یہ غیر مہذب قوموں کا شیوہ ہے۔ وہ لوگ چھوٹے موٹے جانوروں کی گردن منہ داخل کر کے دانتوں سے کاٹ دیتے تھے۔ اسی طرح بڑے بڑے ناخن رکھتے تھے۔ ذبح کرنے کے لیے ان کو استعمال کرتے تھے۔ ظاہر ہے شریعت اس ظالمانہ طریقے کو جائز قرار نہیں دے سکتی، البتہ دانت اور ناخن جسم سے الگ ہو چکے ہوں تو احناف کے نزدیک ان سے ذبح کیا جا سکتا ہے۔ بعض احادیث میں بھی یہ ذکر ہے کہ جو چیز بھی خون بہادے، اس سے ذبح کرنا جائز ہے، اس لیے بظاہر ان کی یہ بات معقول لگتی ہے مگر احادیث رسول کا تقاضا یہی ہے کہ ناخن اور دانت سے کسی بھی صورت ذبح نہ کیا جائے کیونکہ ایک دوسری روایت میں دانت سے ذبح نہ کرنے کی وجہ آپ نے یہ بیان فرمائی ہے کہ وہ ہڈی ہے۔ ظاہر ہے دانت الگ بھی ہو تو وہ ہڈی ہی رہتا ہے۔ ناخن بھی ہڈی ہی ہے۔"}],[4404,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! ہم کل دشمنوں سے ملیں گے اور ہمارے پاس چھریاں نہیں ہیں، تو آپ نے فرمایا: \"جس چیز سے (جانور کا) خون بہہ جائے اور اس پر اللہ کا نام لیا گیا ہو) تو اسے کھاؤ، جب تک کہ وہ آلہ دانت یا ناخن نہ ہو، اور جلد ہی تمہیں اس سلسلے میں بتاؤں گا، رہا دانت تو وہ ہڈی ہے اور رہا ناخن تو وہ حبشہ والوں کی چھری ہے\"۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ سے روایت ہے کہ میں عرض کی: اے اللہ کے رسول! ہم کل دشمن سے ملیں گے(اور وہاں جانور بھی بطور غنیمت ملیں گے) اور ہمارے پاس چھریاں وغیرہ نہ ہوں تو(ہم جانور کیسے ذبح کریں)؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جو چیز بھی خون بہا دے اور اللہ تعالیٰ کا نام لیا جائے تو(ذبیحہ حلال ہے) کھا سکتے ہو بشر طیکہ وہ چیز ناخن یا دانت نہ ہو۔ اور میں تمھیں اس کی وجہ بھی بیان کرتا ہوں کہ دانت تو ایک ہڈی ہے اور ناخن حبشیوں کی چھری ہے۔‘‘","f2":"حبشی لوگ ناخنوں سے چھری کا کام لیتے ہیں۔ ایک تو وہ کافر ہیں، اس لیے ان کی مشا بہت سے بچنا چاہیے اور دوسرا یہ کہ ذبح کرنے کا غیر مہذب طریقہ ہے۔"}],[4405,"شداد بن اوس رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے دو باتیں یاد کی ہیں، آپ نے فرمایا: \"اللہ تعالی نے تم پر ہر چیز میں احسان (اچھا سلوک کرنا) فرض کیا ہے، تو جب تم قتل کرو تو اچھی طرح قتل کرو، اور جب تم ذبح کرو تو اچھی طرح ذبح کرو، اور تم میں سے ہر ایک کو چاہیئے کہ اپنی چھری تیز کر لے اور اپنے جانور کو آرام پہنچائے ۱؎۔\n§وضاحت\n۱؎: اس حدیث سے اسلام میں کسی بھی جاندار کے ساتھ احسان :(اچھا برتاؤ کرنے ) کا ثبوت ملتا ہے، پس جو مذہب جانوروں کے ساتھ ذبح کی حالت میں بھی احسان کا داعی ہے وہ انسانی جانوں کے ساتھ کیسے سلوک کا حکم دے گا واضح ہے۔ سبق لیں اسلام پر تشدد کا الزام لگانے والے۔","الألباني: صحيح",{"u2":"حضرت شداد بن اوس رضی اللہ عنہ سے مروی ہے کہ دو باتیں میں نے رسول اللہ صلی اللہ علیہ وسلم سے خوب یاد رکھی ہیں۔ آپ نے فرمایا:’’اللہ تعالیٰ نے ضروری قرار دیا ہے کہ ہر چیز پر احسان کیا جائے، لہٰذا جب تم(کسی انسان کو قصاص میں یا کسی موذی جانور اور درندے وغیرہ کو) قتل کرنے لگو تو اچھے طریقے سے قتل کرو۔ اور جب تم ذبح کرنے لگو(کسی پرندے یا حلال جانور کو) تو اچھے طریقے سے ذبح کرو۔ اور ذبح کرتے وقت چھری تیز کر لیا کرو اور اپنے ذبیحہ کو آرام پہنچاؤ۔‘‘","f2":"1)جانور کو ذبح کرنے کے لیے چھری کو تیز کرنا چاہیے تا کہ ذبح ہونے والے جانور کو تکلیف کم ہو۔2) امام نووی رحمہ اللہ نے فرمایا ہے کہ حدیث قواعد اسلام کی جامع ہے۔ دیکھیے:(صحیح مسلم بشرح النووی:13/157)\n3) یہ حدیث مبارکہ اللہ تعالیٰ کے، اپنی تمام مخلوق کے ساتھ، بے پناہ لطف و کرم پر دلالت کرتی ہے۔ یہ اللہ تعالیٰ کی رحمت و شفقت ہی ہے کہ اس نے ضروری قرار دیا ہے کہ ہر چیز کے ساتھ احساس کیا جائے بلکہ اس نے جانوورں تک کے ساتھ سلوک کا حکم دیا ہے۔ اسی طرح غلاموں اور مجرموں کے ساتھ بھی، مثلاََ: اگر کسی مجرم کو قصاصاََ قتل کرنے کا حکم ہے، نہ کہ اسے ایذائیں دے دے کر قتل کیا جائے۔ مزید بر آں یہ بھی کہ قتل کے مجرم کو بھی کھانے، پینے، پہننے اور زندگی کی دیگر لذتوں سے جو جائز اور مناسب ہوں، محروم نہیں کرنا۔\n4) رسول اللہ صلی اللہ علیہ وسلم کے فرمان’’جب تم ذبح کرو تو اچھے طریقے سے ذبح کرو۔‘‘ کی بابت امام قرطبی رحمہ اللہ فرماتے ہیں: ذبح کرنے میں جانور کے ساتھ نرمی کا برتاؤ کرے۔ ذبھ کرنے کی خاطر اسے سختی، اور بے دردی سے نہ گرائے اور نہ اسے گھسٹیتے ہوئے ایک جگہ سے دوسری جگہ لے جائے، تیز چھری کے ساتھ اسے ذبح کرے۔(نیز گرائے اور نہ اسے گسٹیتے ہوئے ایک جگہ سے دوسری جگہ لے جائے، تیر چھری کرنے اور اس تقرب الٰہی حاصل کرنے کی نیت کرے۔ اسے قبلہ رخ لٹائے۔ اللہ کا نام لے کر ذبح کرے۔ جلدی جلدی ذبح کرے۔ جانور کا گلا اور اس کی گردن کی رگیں کاٹے۔ اسے آرام پہنچائے اور(ذبح کرنے کے فوراََ بعد اس کا چمڑا اور کھال اتار نا شروع نہ کرے بلکہ) ٹھنڈا ہونے دے۔(اس کا تڑپنا ختم ہو تو تب اس کی کھال اور چمڑا اتارے۔) اور(اس کے ساتھ ساتھ) اللہ تعالیٰ کا احسان مند ہو کر اس کے احساس اور فضل و کرم کا اعتراف وا قرار کرے، نیز اللہ تعالیٰ کے اس عظیم انعام واحسان پر کہ اس نے یہ جانور(جسے اس نے ذبح کیا ہے) اس کے لیے مسخر کر دیا تھا، اللہ تعالیٰ کا شکر ادا کرے، نیز اللہ تعالیٰ کا شکر ادا کرے۔ اگر اللہ چاہتا تو(اسے مسخر نہ فرماتا بلکہ) ہم پر مسلط کر دیتا۔ اسی طرح اگر وہ چاہتا تو اس جانور کو ہمارے لیے حلال کرنے کی بجائے ہم پر حرام کر دیتا(پھر ہم اس کا کیا بگاڑ سکتے تھے؟) اور ربیعہ کہتے ہیں کہ ذبح میں احساس یہ ہے کہ اسے دوسرے جانور کے سامنے ذبح نہ کرے(تاکہ دیکھنے والے کو تکلیف محسوس نہ ہو)۔ امام قرطبی رحمہ اللہ مزید فرماتے ہیں کہ آپ صلی اللہ علیہ وسلم کے فرمان:’’جب تم قتل کرو تو اچھے طریقے سے قتل کرو‘‘ کو ہر چیز کی باعت عموم پر محمول کیا جائے اور انھیں تکلیف اور عذاب دے کر نہ مارا جائے۔ دیکھیے:(المفھم:5/240‘241)۔\n5) اگر کسی شخص نے مقتول کو برے طریقے سے قتل کیا ہو تو اسے بھی برے طریقے سے قتل کیا جائے گا کیونکہ قصاص کا تقاضا یہی ہے۔ یہ بحث، المحاربہ میں تفصیل سے گزر چکی ہے۔"}],[4406,"اسماء بنت ابی بکر رضی اللہ عنہا کہتی ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں ایک گھوڑا ذبح کیا پھر ہم نے اسے کھایا ۱؎۔\n§وضاحت\n۱؎: گھوڑا نحر کیے جانے والے جانوروں میں سے نہیں ہے پھر بھی آپ کے سامنے نحر کیا گیا، اس سے ذبح کیے جانے والے جانورں کو نحر کرنے کا جواز ثابت ہوتا ہے، تو اس کے برعکس سے جائز ہو گا یعنی ذبح کئے جانے والے جانورں کو نحر بھی کیا جا سکتا ہے، لیکن یہ صرف جواز کی صورت ہے، زیادہ اچھا یہی ہے کہ نحر کئے جانے والے جانورں کو پہلے نحر ہی کیا جائے، اور پھر ذبح کیا جائے اور ذبح کئے جانے والے جانوروں کو ذبح کرنا ہی افضل ہے، :(ذبح کئے جانے والے جانور جیسے: بکری، دنبہ، بھیڑ، مینڈھا، مرغی، اور نحر کئے جانے والے جانور جیسے: گائے، بیل، گھوڑا اور اونٹ ) نحر میں پہلے دھاردار ہتھیار سے جانور کے سینے کے اوپری حصہ کے سوراخ میں مارا جاتا ہے، جب سارا خون نکل کر جانور ساکت ہو جاتا ہے تب گرا کر ذبح کیا جاتا ہے، نحر کے ذریعہ بڑے جانور پر آسانی سے قابو پا لیا جاتا ہے اس لیے ان کے حق میں نحر مشروع ہوا۔","الألباني: صحيح",{"u2":"حضرت اسماء بنت ابو بکر رضی اللہ عنہا سے روایت ہے کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں گھوڑا نحر کیا، پھر اسے کھایا۔","f2":"1) جو جانور ذبح کیے جاتے ہیں انھیں نحر اور جو نحر کیے جاتے ہیں انھیں ذبح کیا جاسکتا ہے۔2) اس حدیث سے اضح طور پر معلوم ہوتا ہے کہ گھوڑا حلال جانور ہے۔ جن لوگوں نے مکر وہ کہا ہے انھیں ٹھو کر لگی ہے، اس کی کراہت پر کوئی مستند صحیح دلیل موجود نہیں۔ صحابہ کرام رضی اللہ عنہم کے یہ الفاظ کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے زمانہ مبارک میں اس طرح کیا، مرفوع حدیث کے حکم میں ہوتا ہے۔ اسی طرح’’اس طرح کرنا سنت سے ہے۔‘‘ نیز’’ ہمیں اس طرح کرنے کا حکم دیا گیا‘‘ اور’’ہمیں اس سے روکا گیا‘‘ یا ان سے ملتے جلتے مفہوم والے دوسرے الفاظ، ان کے متعلق، محد ثین کرامj کا فیصلہ یہی ہے کہ ان کا حکم مرفوع حدیث ہی کا حکم ہے۔ 3)اونٹ کو نحر کیا جاتا ہے اور باقی جانوورں کو ذبح۔ ذبح کا طریقہ معروف ہے، نحر، کھڑے جانور کو گلے میں چھرا وغیرہ گھونپ کر کیا جاتا ہے۔ جب خون کافی حد تک بہہ جاتا ہے تو جانور گر پڑتا ہے، پھر اسے ذبح کر دیا جاتا ہے۔ اونٹ میں مسنون عمل نحرہی ہے، تاہم بوقت ضرورت ذبح میں بھی کوئی حرج ہیں۔ مذکورہ حدیث میں یا تو نحر ذبح کے معنی میں ہے اور عرب لوگ اکثر ایک لفظ اس سے ملتے جلتے لفظ کی جگہ استعمال کر لیتے ہیں۔ یا وہ گھوڑا قوی ہو گا اور قابو نہ آتا ہو گا، اس لیے کے ساتھ اونٹ والا سلوک کیا گیا۔واللہ اعلم۔"}],[4407,"زید بن ثابت رضی اللہ عنہ سے روایت ہے کہ ایک بھیڑیئے نے ایک بکری میں دانت گاڑ دئیے، لوگوں نے اسے دھاردار پتھر سے ذبح کیا، تو نبی اکرم صلی اللہ علیہ وسلم نے اسے کھانے کی اجازت دی۔","الألباني: صحيح",{"u2":"حضرت زید بن ثابت رضی اللہ عنہ سے مروی ہے کہ ایک بھیڑیے نے ایک بکری میں دانت گاڑ دئیے۔ لوگوں نے (اس سے چھڑا کر) اس کو ایک تیز دھار پتھر سے ذبح کر دیا۔ نبی اکرم صلی اللہ علیہ وسلم نے اس کو کھانے کی اجازت دے دی۔","f2":"دیکھیے حدیث نمبر4405"}],[4408,"ابو العشراء کے والد (مالک دارمی رضی اللہ عنہ) کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! کیا ذبح «ذکاۃ» صرف حلق اور سینے میں ہو گا؟ آپ نے فرمایا:\"اگر تم اس کی ران میں بھی کونچ دو تو کافی ہے\"۔","الألباني: ضعيف",{"u2":"حضرت ابو العشراء کے والد محترم بیان کرتے ہیں کہ میں نے عرض کی: اے اللہ کے رسول! کیا ذبح صرف حلق اور سینے کے گڑھے ہی میں ہو سکتا ہے؟ آپ نے فرمایا: ’’اگر تو اس کے ران میں نیزہ یا برچھی وغیرہ مار دے تو بھی کفایت کر جائے گا۔‘‘","f2":"اصل تو یہی ہے کہ حلق میں ذبح کیا جائے اور سینے کے گڑھے میں نحر کیا جائے کیونکہ اس طریقے سے خون تیزی سے نکل جائے گا۔ یہاں بڑی رگیں ہوتی ہیں۔ مگر کبھی مجبوری بن جاتی ہے جیسا کہ باب میں بیان کی گئی ہے تو جہاں بھی زخم لگایا جا سکے، لگا دیا جائے تا کہ خون نکل جائے۔ یہ جائز ہے مگر یہ مجبوری کے وقت ہی ہے۔"}],[4409,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! ہم کل دشمن سے ملیں گے اور ہمارے پاس چھریاں نہیں ہیں، آپ نے فرمایا: \"دانت اور ناخن کے علاوہ جس کسی آلہ سے (جانور کا) خون بہہ جائے اور اس پر اللہ کا نام لیا گیا ہو تو اسے کھاؤ\"، پھر رسول اللہ صلی اللہ علیہ وسلم کو کچھ اونٹ اور غنیمت کا مال ملا، ان میں سے ایک اونٹ بدک کر بھاگ گیا، ایک شخص نے اسے تیر مارا، جس سے وہ رک گیا، آپ نے فرمایا: \"ان جانوروں میں، یا یوں فرمایا: ان اونٹوں میں، جنگل کے وحشی جانوروں کی طرح بعض بدکنے والے ہوتے ہیں تو جو تم کو ان میں سے کوئی (پکڑنے میں) تھکا دے، تو اس کے ساتھ اسی طرح کرو\"۔","الألباني: صحيح",{"u2":"حضرت رافع رضی اللہ عنہ سے روایت ہے کہ میں نے عرض کی: اے اللہ کے رسول! کل ہمارا دشمن سے مقابلہ ہو گا۔ ہمارے پاس چھری قسم کی چیز نہیں (تو ذبح کیسے کریں؟) آپ نے فرمایا: ’’جو چیز بھی خون بہا دے اور اللہ تعالیٰ کا نام ذکر کر دیا جائے تو (ایسا ذبیحہ) کھایا جا سکتا ہے۔ علاوہ دانت اور ناخن کے۔‘‘رسول اللہ صلی اللہ علیہ وسلم کو غنیمت میں اونٹ حاصل ہوئے۔ ان میں سے ایک اونٹ بھاگ گیا۔ ایک آدمی نے اس کو (پیچھے سے) تیر مارا جس سے وہ رک گیا۔ آپ نے فرمایا: ’’یہ گھریلو جانور یا اونٹ بھی کبھی جنگلی جانوروں کی طرح بے قابو ہو جاتے ہیں، لہٰذا جو جانور تم سے بے قابو ہو جائے، اس سے یہی سلوک کرو۔‘‘","f2":"تفصیل کے لیے دیکھئے، حدیث ۴۳۰۲۔"}],[4410,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! ہم لوگ کل دشمن سے ملیں گے، اور ہمارے پاس چھریاں نہیں ہیں، آپ نے فرمایا:\"جس آلہ سے خون بہہ جائے اور وہ دانت ناخن نہ ہو اور اس پر اللہ کا نام لیا گیا ہو تو اسے کھاؤ، اور جلد ہی میں تمہیں اس کا سبب بتاتا ہوں، رہا دانت تو وہ ہڈی ہے اور رہا ناخن تو وہ حبشہ والوں کی چھری ہے\"، پھر مال غنیمت میں ہمیں کچھ بکریاں یا اونٹ ملے، ان میں سے ایک اونٹ بدک کر بھاگ گیا، ایک شخص نے ایک تیر اسے مارا جس سے وہ رک گیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ان اونٹوں میں کچھ جنگلی وحشیوں کی طرح بدکنے والے ہیں، لہٰذا جب تم کو ان میں سے کوئی تھکا دے تو اس کے ساتھ ایسا ہی کرو\"۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ سے روایت ہے کہ میں نے عرض کی: اے اللہ کے رسول! کل دشمن سے ہماری ملاقات ہو گی اور ہمارے پاس چھری (وغیرہ کچھ) نہیں۔ آپ نے فرمایا: ’’جو چیز بھی خون بہا دے بشرطیکہ اللہ کا نام لیا گیا ہو، اسے کھا سکتے ہو۔ علاوہ دانت اور ناخن کے۔ اور اس کی وجہ بھی میں تمہیں بیان کرتا ہوں: دانت تو ہڈی ہے اور ناخن حبشیوں کی چھری ہے‘‘۔ ہمیں اس جنگ میں اونٹ اور بکریاں مال غنیمت میں حاصل ہوئیں۔ ان میں سے ایک اونٹ بھاگ گیا تو ایک آدمی نے تیر مار کر اسے روک دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ اونٹ بھی کبھی جنگلی جانوروں کی طرح بھاگ اٹھتے ہیں۔ جب وہ تم سے بے قابو ہو جائیں تو تم ان سے یہی سلوک کرو۔‘‘","f2":"ابتدائی حصے کی تفصیل کے لیے دیکھئے، حدیث: ۴۴۰۸۔"}],[4411,"جریر بن عبداللہ رضی اللہ عنہ کہتے ہیں کہ جب غلام مشرکوں کے ملک میں بھاگ جائے تو پھر اس کا ذمہ نہیں ہے ۱؎۔\n§وضاحت\n۱؎: یعنی اس کی امان کی ذمہ داری اسلامی حکومت پر نہیں۔\nشداد بن اوس رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اللہ تعالی نے ہر چیز میں احسان (اچھا سلوک کرنا) فرض کیا ہے، لہٰذا جب تم قتل کرو تو اچھی طرح کرو اور جب ذبح کرو تو اچھی طرح ذبح کرو اور جب تم ذبح کرو تو اپنی چھری کو تیز کر لیا کرو اور ذبیحہ کو (ذبح کرتے وقت) آرام پہنچاؤ\"۔","الألباني: صحيح",{"u2":"حضرت شداد بن اوس رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’اللہ تعالیٰ نے ہر چیز کے ساتھ حسن سلوک فرض قرار دیا ہے، لہٰذا جب تم کسی کو (قصاص وغیرہ میں) قتل کرنے لگو تو اچھے طریقے سے قتل کرو اور جب تم کسی جانور کو ذبح کرنے لگو تو اچھے طریقے سے ذبح کرو۔ اور ذبح کرتے وقت اپنی چھری کو تیز کرو اور اپنے ذبیحہ کو جلدی نجات دو۔‘‘","f2":"اس حدیث کا تعلق متعلقہ باب کی بجائے آئندہ باب سے ہے اور سنن نسائی میں بہت جگہ ایسے ہی ہے۔"}],[4412,"جریر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب غلام مشرکوں کی زمین میں بھاگ کر چلا جائے تو اس کا خون حلال ہے\"۔\nشداد بن اوس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے احسان (اچھے سلوک اور برتاؤ) کو ہر چیز میں فرض کیا ہے، لہٰذا جب تم قتل کرو تو اچھی طرح کرو، اور جب ذبح کرو تو اچھی طرح کرو، اور تم اپنی چھریاں تیز کر لیا کرو اور جانور کو (ذبح کرتے وقت) آرام پہنچاؤ\"۔","الألباني: ضعيف الإسناد",{"u2":"حضرت شداد بن اوس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہر چیز سے حسن سلوک کرنا اللہ تعالیٰ نے فرض قرار دیا ہے، اس لیے جب تم کسی کو قتل کرنے لگو تو اچھے طریقے سے قتل کرو اور جب تم کسی جانور کو ذبح کرنے لگو تو اچھے طریقے سے ذبح کرو۔ ذبح کرنے والا شخص اپنی چھری کو تیز کرے اور اپنے مذبوح جانور کو راحت پہنچائے۔‘‘"}],[4413,"جریر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب غلام مشرکوں کی زمین میں بھاگ کر چلا جائے تو اس کا خون حلال ہے\"۔\nشداد بن اوس رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے سن کر دو باتیں یاد رکھیں ہیں، آپ نے فرمایا: \"اللہ تعالی نے ہر چیز میں احسان (اچھے سلوک اور برتاؤ) فرض کیا ہے، لہٰذا جب تم قتل کرو تو اچھی طرح کرو، اور جب تم ذبح کرو تو اچھی طرح کرو اور تم اپنی چھریاں تیز کر لو تاکہ تم اپنے جانور کو آرام دے سکو\"۔","الألباني: ضعيف الإسناد",{"u2":"حضرت شداد بن اوس رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبیٔ اکرم صلی اللہ علیہ وسلم سے دو باتیں سنیں۔ آپ نے فرمایا: ’’اللہ تعالیٰ نے ہر چیز سے حسن سلوک ضروری قرار دیا ہے، لہٰذا جب تم کسی کو قتل کرو تو اچھے طریقے سے کرو اور جب کسی جانور کو ذبح کرو تو اچھے طریقے سے ذبح کرو۔ ذبح کرنے والا شخص اپنی چھری کو تیز کرے اور اپنے ذبیحہ کو آرام پہنچائے۔‘‘","f2":"’’دو باتیں سنیں‘‘ ان سے مراد آئندہ باتیں ہی ہیں، یعنی اچھے طریقے سے قتل کرنا اور اچھے طریقے سے ذبح کرنا۔"}],[4414,"شداد بن اوس رضی اللہ عنہ کہتے ہیں کہ دو چیزیں ہیں جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سن کر یاد کی ہیں: \"اللہ تعالی نے ہر چیز میں احسان (اچھے سلوک اور برتاؤ) کو فرض کیا ہے، لہٰذا جب تم قتل کرو تو اچھی طرح کرو، اور جب تم ذبح کرو تو اچھی طرح کرو۔ تم اپنی چھریاں تیز کر لو اور جانور کو آرام دو\"۔","الألباني: صحيح",{"u2":"حضرت شداد بن اوس رضی اللہ عنہ سے منقول ہے کہ دو باتیں میں نے رسول اللہ صلی اللہ علیہ وسلم سے یاد رکھیں: (آپ نے فرمایا:) ’’یقینا اللہ تعالیٰ نے ہر چیز سے حسن سلوک ضروری قرار دیا ہے، لہٰذا جب تم کسی کو قتل کرنے لگو تو اچھے طریقے سے قتل کرو اور جب تم کسی جانور کو ذبح کرنے لگو تو اچھے طریقے سے ذبح کرو۔ ذبح کرنے والا اپنی چھری کو تیز کر لے اور اپنے ذبح ہونے والے جانور کو کم سے کم تکلیف پہنچائے۔ (مطلب یہ کہ یکبارگی ذبح کرے، دیر نہ لگائے۔)","f2":"ان مذکورہ احادیث کے تفصیلی احکام جاننے کے لیے ملاحظہ فرمائیں، حدیث: ۴۴۱۰ کے فوائد و مسائل۔"}],[4415,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سینگ دار دو چتکبرے مینڈھوں کی قربانی کی، آپ «اللہ اکبر» اور «بسم اللہ» پڑھ رہے تھے، میں نے دیکھا کہ آپ انہیں اپنے ہاتھ سے ذبح کر رہے ہیں اور اپنا پاؤں ان (کی گردن) کے پہلو پر رکھے ہوئے ہیں۔ (شعبہ کہتے ہیں) میں قتادہ نے عرض کیا: کیا آپ نے اسے انس سے سنا ہے؟ انہوں نے کہا: ہاں۔","الألباني: صحيح",{"u2":"حضرت قتادہ رحمہ اللہ نے کہا کہ میں نے حضرت انس رضی اللہ عنہ سے سنا، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے دو چتکبرے (سیاہ و سفید)، سینگوں والے مینڈھے قربانی فرمائے۔ ذبح فرماتے وقت آپ بسم اللہ و اللہ اکبر پڑھتے تھے۔ میں نے آپ کو اپنے دست مبارک سے انہیں ذبح فرماتے دیکھا جبکہ آپ نے اپنا قدم مبارک ان کے پہلو پر رکھا ہوا تھا۔\n(شعبہ نے کہا) میں نے (قتادہ سے) کہا: کیا آپ نے ان (حضرت انس رضی اللہ عنہ) سے سنا؟ انہوں نے فرمایا: ہاں۔","f2":"(۱) قربانی کا جانور ذبح کرتے وقت جانور کے پہلو پر اپنا پائوں رکھنا جائز ہے۔ اہل علم کا اس بات پر اتفاق ہے کہ جانور کو بائیں پہلو کے بل لٹایا جائے۔ اور اس صورت میں پائوں اس کے دائیں پہلو پر رکھا جائے گا۔ (۲) قربانی کا جانور ذبح کرتے وقت تسمیہ (بسم اللہ) پڑھنا مشروع ہے۔ اسی طرح تمام جانو ذبح کرتے وقت تسمیہ پڑھنی چاہیے۔ اس پر اجماع ہے۔ تسمیہ کے ساتھ ساتھ تکبیر (اللہ اکبر) پڑھنا بھی مشروع ہے جیسا کہ دیگر روایات میں اس کی تصریح موجود ہے۔ (۳) قربانی کا جانور اپنے ہاتھ سے ذبح کرنے کی مشروعیت بھی معلوم ہوتی ہے، تاہم بوقت ضرورت کسی اور کو بھی وکیل بنایا جا سکتا ہے۔ (۴) رسول اللہ صلی اللہ علیہ وسلم نے دو مینڈھے ذبح فرمائے، اس سے ایک سے زیادہ جانور قربان کرنے کی مشروعیت ثابت ہوتی ہے۔ (۵) اس حدیث مبارکہ سے یہ بھی معلوم ہوتا ہے کہ سینگوں والے خوبصورت جانور کی قربانی کرنا افضل ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے کیا، تاہم بغیر سینگوں والے جانور کی قربانی بھی درست ہے۔ (۶) جانور کو لٹانے کے بعد اس کے پہلو پر پائوں رکھ لینا چاہیے تاکہ وہ قابوں میں رہے۔ چھری قوت سے چل سکے اور وہ سر کو حرکت دے کر ذبح میں رکاوٹ نہ بنے، نیز اسے زیادہ تکلیف نہ ہو۔ یہ حکم قربانی سے خاص نہیں۔"}],[4416,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دو چتکبرے سینگ دار مینڈھے ذبح کرتے اور آپ «بسم اللہ» پڑھتے اور تکبیر بلند کرتے ۱؎، میں نے آپ کو دیکھا کہ آپ اپنے ہاتھ سے انہیں ذبح کر رہے ہیں اور آپ کا پیر ان (کی گردن) کے پہلو پر ہے۔\n§وضاحت\n۱؎: یعنی «بسم اللہ، اللہ اکبر» کہتے تھے، «بسم اللہ الرحمن الرحیم» نہیں کہتے تھے۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم دو سیاہ و سفید، سینگوں والے مینڈھے ذبح کرتے تھے۔ آپ بسم اللہ و اللہ اکبر پڑھتے تھے۔ میں نے آپ کو اپنے دست مبارک سے انہیں ذبح کرتے دیکھا۔ آپ نے اپنا پائوں مبارک ان کے پہلو پر رکھا ہوا تھا۔","f2":"ویسے تو ہر ذبیحہ پر بسم اللہ و اللہ اکبر پڑھنا چاہیے مگر قربانی پر پڑھنا انتہائی ضروری ہے کیونکہ اسے ذبح کرنے سے پہلے تو باقاعدہ نیت کی جاتی ہے۔ دلی طور پر بھی۔ ذبیحہ پر اگر اللہ کا نام لینا بھول جائے تو وہ ذبیحہ حلال ہو گا، البتہ جان بوجھ کر نہیں چھوڑنا چاہیے۔"}],[4417,"انس رضی اللہ عنہ کہتے ہیں کہ میں نے آپ کو یعنی نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ اپنے ہاتھ سے دو سینگ دار اور چتکبرے مینڈھے ذبح کر رہے ہیں، اور آپ کا پیر ان (کی گردن) کے پہلو پر ہے۔ آپ (ذبح کرتے ہوئے) «بسم اللہ، اللہ اکبر» کہہ رہے ہیں۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ بیان کترے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ دو سیاہ و سفید، سینگوں والے مینڈھوں کو بسم اللہ و اللہ اکبر پڑھتے ہوئے اپنے دست مبارک سے ذبح فرما رہے تھے اور اپنا قدم مبارک ان کے پہلو پر رکھا ہوا تھا۔"}],[4418,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے دو مینڈھوں کی قربانی کی جو سینگ دار اور چتکبرے تھے۔ آپ ان (کی گردن) کے پہلو پر قدم رکھ کر انہیں ذبح کر رہے تھے اور «بسم اللہ، اللہ اکبر» کہہ رہے تھے۔\n§وضاحت\n۱؎: زیادہ بہتر یہی ہے کہ اپنی قربانی خود اپنے ہاتھ سے ذبح کرے، لیکن جائز یہ بھی ہے کہ دوسرے سے کروائے، جیسا کہ اگلی حدیث میں آ رہا ہے۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے سینگوں والے سیاہ و سفید دو مینڈھے بسم اللہ و اللہ اکبر پڑھتے ہوئے قربان فرمائے جبکہ آپ نے ان کے پہلو پر پائوں مبارک رکھا ہوا تھا۔"}],[4419,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے ہاتھ سے اپنی بعض اونٹنیوں کو نحر کیا اور بعض کو دوسروں نے نحر کیا۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی قربانی کے کچھ اونٹ خود نحر فرمائے اور کچھ اونٹ کسی اور نے نحر کیے۔","f2":"یہ حجۃ الوداع کی بات ہے۔ آپ نے سو اونٹ قربانی کیے تھے۔ ان میں سے تریسٹھ (۶۳) آپ نے اپنے دست مبارک سے نحر کیے اور باقی سینتیس (۳۷) حضرت علی رضی اللہ عنہ نے آپ کا نائب بن کر نحر کیے۔"}],[4420,"اسماء رضی اللہ عنہا کہتی ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک گھوڑا نحر کیا اور اسے کھایا۔ قتیبہ نے :(«فاکلناہ» کے بجائے) «فاکلنا لحمہ» \"پھر ہم نے اس کا گوشت کھایا\" کہا۔ عبدہ بن سلیمان نے سفیان کی مخالفت کی ہے اور اسے یوں روایت کیا ہے۔","الألباني: صحيح",{"u2":"حضرت اسماء رضی اللہ عنہا فرماتی ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے دور میں گھوڑا نحر کیا اور پھر اس کا گوشت کھایا۔\nقتیبہ (استاد) نے کہا: فَأَکَلْنَا لَحْمَہٗ پھر ہم نے اس کا گوشت کھایا۔ عبدہ بن سلیمان نے اس کی مخالفت کی ہے۔","f2":"امام نسائی رحمہ اللہ فرماتے ہیں کہ عبدہ بن سلیمان نے اس روایت میں سفیان بن عیینہ کی مخالفت کی ہے۔ اگلی روایت میں اس مخالفت کی پوری وضاحت موجود ہے۔ وہ اس طرح کہ سفیان نے ہشام بن عروہ سے روایت کرتے ہوئے ذَبَحْنَا کے الفاظ بیان کیے ہیں جبکہ عبدہ بن سلیمان نے نَحَرْنَا کے الفاظ بیان کیے ہیں۔ مزید برآں یہ بھی کہ عبدہ بن سلیمان نے وَ نَحْنُ بِالْمَدِیْنَۃِ کے الفاظ بھی زیادہ بیان کیے ہیں۔"}],[4421,"اسماء رضی اللہ عنہا کہتی ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک گھوڑا ذبح کیا، ہم مدینے میں تھے پھر ہم نے اسے کھایا۔\n§وضاحت\n۱؎: یعنی «نحرنا» کی جگہ «ذبحنا» ہے، اور ہشام کے اکثر شاگردوں کی روایت «نحرنا» ہی کی ہے، صرف \"عبدہ\" کی روایت میں «ذبحنا»ہے اسی اختلاف الفاظ سے استدلال کرتے ہوئے مؤلف نے یہ باب باندھا ہے بہرحال نحر و ذبح دونوں جائز ہیں، مقصد خون بہانا ہے۔","الألباني: صحيح",{"u2":"حضرت اسماء رضی اللہ عنہا سے مروی ہے کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں مدینہ میں رہتے ہوئے گھوڑا ذبح (نحر) کیا اور پھر اسے کھایا۔"}],[4422,"عامر بن واثلہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے علی رضی اللہ عنہ سے سوال کیا: کیا رسول اللہ صلی اللہ علیہ وسلم لوگوں کو چھوڑ کر آپ کو کوئی راز کی بات بتاتے تھے؟ اس پر علی رضی اللہ عنہ غصہ ہو گئے یہاں تک کہ ان کا چہرہ لال پیلا ہو گیا اور کہا: آپ لوگوں کو چھوڑ کر مجھے کوئی بات راز کی نہیں بتاتے تھے، سوائے اس کے کہ آپ نے مجھے چار باتیں بتائیں، میں اور آپ ایک گھر میں تھے، آپ نے فرمایا: \"اللہ اس پر لعنت کرے جس نے اپنے والد (ماں یا باپ) پر لعنت کی، اللہ اس پر بھی لعنت کرے جس نے غیر اللہ کے لیے ذبح کیا، اللہ اس پر لعنت کرے جس نے کسی بدعتی کو پناہ دی ۱؎، اور اللہ تعالی اس پر لعنت کرے جس نے زمین کی حد کے نشانات بدل ڈالے\" ۲؎۔\n§وضاحت\n۱؎: یعنی اس کی تائید و حمایت کی اور بدعت سے خوش ہوا۔ ۲؎: مثلاً دو آدمیوں کی زمین کو الگ کرنے والے نشانات بدلے، اور اس سے مقصد دوسری کی زمین میں سے کچھ ہتھیا لینا ہو۔","الألباني: صحيح",{"u2":"حضرت عامر بن واثلہ سے روایت ہے کہ ایک شخص نے حضرت علی رضی اللہ عنہ سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم آپ کو لوگوں سے الگ کوئی پوشیدہ باتیں بتلایا کرتے تھے؟ حضرت علی رضی اللہ عنہ غضب ناک ہو گئے حتی کہ ان کا چہرہ سرخ ہو گیا۔ اور آپ نے فرمایا: آپ مجھے لوگوں سے الگ کوئی پوشیدہ بات نہیں بتلاتے تھے، البتہ ایک دفعہ آپ نے مجھے یہ چار باتیں ارشاد فرمائیں جبکہ اس وقت گھر میں، میں اور آپ ہی تھے۔ آپ نے فرمایا: ’’اللہ تعالیٰ اس شخص پر لعنت کرے جو اپنے باپ کو لعنت کرتا ہے۔ اللہ تعالیٰ اس شخص پر لعنت کرے جو غیر اللہ کے لیے ذبح کرتا ہے۔ اللہ تعالیٰ اس شخص پر لعنت کرے جو کسی بدعتی یا باغی کو ٹھکانا مہیا کرتا ہے اور اللہ تعالیٰ اس شخص پر بھی لعنت کرے جو زمین کی علامات کو تبدیل کرتا ہے۔‘‘","f2":"(۱) مؤلف رحمہ اللہ نے جو باب قائم کیا ہے اس کا مقصد ذبح لغیر اللہ کی مذمت ہے، لہٰذا جو شخص اللہ تعالیٰ کے سوا کسی اور ہستی (پیر، پیغمبر، نبی، قطب، ابدال، نیک صالح اور بزرگ وغیرہ) کے لیے، ان کی خوشنودی اور رضا حاصل کرنے کی خاطر جانور ذبح کرتا ہے، وہ ملعون ہے اور یہ بات یقینی ہے کہ لعنتی شخص، اللہ عز و جل کی رحمت سے دور اور محروم ہو جاتا ہے۔ (۲) اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ مذکورہ اعمال کبیرہ گناہ ہیں کیونکہ لعنت، مرتکب کبیرہ پر ہی کی جاتی ہے، مرتکب صغیر پر نہیں، نیز ان کے مرتکب کو لعنتی بھی قرار نہیں دیا گیا۔ (۳) اس حدیث مبارکہ سے شیعہ، روافض اور امامیہ وغیرہ کے عقیدے کی کھلی تردید ہوتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حضرت علی رضی اللہ عنہ کے خاص کوئی وصیت فرمائی تھی۔ اس کے ساتھ ساتھ یہ مبتدعین جن دیگر من گھڑت باتوں اور خرافات پر اپنے عقائد و افکار کی بنیاد رکھتے ہیں اس کی عمارت بھی، حضرت علی رضی اللہ عنہ کے مذکورہ فرمان کی وجہ سے دھڑام سے زمین بوس ہو جاتی ہے۔ ^اس گھر کو آگ لگ گئی گھر کے چراغ سے۔ فَلِلّٰہِ الْحَمْدُ عَلٰی ذٰلِکَ۔ بعض بے دین لوگوں نے عجیب عجیب باتیں مشہور کر رکھی تھیں جن میں ایک یہ بھی تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے اصل وحی کی تعلیم صرف حضرت علی رضی اللہ عنہ کو دی ہے جو کہ اس قرآن سے بہت زیادہ ہے۔ یہ بات خالص احمقانہ ہے، اس لیے حضرت علی رضی اللہ عنہ کو غصہ آ گیا۔ رضی اللہ عنہ و ارضاہ۔ پھر آپ نے بتایا کہ خصوصی تعلیم تو کوئی نہیں دی، البتہ یہ ہو سکتا ہے کہ کسی فرمان کے موقع پر میں اتفاقاً آپ کے پاس اکیلا تھا۔ مگر وہ فرمان بھی سب امت کے لیے ہے نہ کہ صرف میرے لیے۔ (۴) غیر اللہ کے لیے ذبح کرنے کا ایک مفہوم تو یہ ہے کہ ذبح کے وقت غیر اللہ کا نام لیا جائے، اسی طرح جو شخص غیر اللہ کی رضا کی خاطر جانور ذبح کرتا ہے، خواہ ذبح کے وقت اللہ کا نام لے، وہ بھی ذبح لغیر اللہ ہی ہے اور ایسا شخص ملعون ہے۔ (۵) ’’زمین کی علامات‘‘ ان علامات سے مراد یا تو صحرائی راستوں کی علامات ہیں جن کی مدد سے مسافر بھٹکنے سے محفوظ رہتے ہیں۔ ان علامات کو مٹانے سے ان کی موت کا خطرہ ہے، لہٰذا یہ سخت گناہ ہے۔ یا وہ علامات مراد ہیں جن کے ساتھ لوگوں کی ملکیت کی حد بندی ہوتی ہے۔ و اللہ اعلم۔"}],[4423,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تین دن کے بعد قربانی کا گوشت کھانے سے روکا ہے ۱؎۔\n§وضاحت\n۱؎: یہ پابندی شروع شروع میں تھی، پھر گوشت رکھنے کی اجازت دے دی گئی، جیسا کہ اگلے باب میں ہے، یہ حالات و ظروف کے لحاظ سے ہے، اگر لوگوں کو گوشت کی زیادہ حاجت ہے تو ذخیرہ اندوزی صحیح نہیں، بصورت دیگر صحیح ہے۔ :(دیکھئیے حدیث نمبر ۴۴۳۴ )۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تین دن سے زائد قربانیوں کا گوشت کھانے سے منع فرمایا۔","f2":"(۱) فقر و فاقہ کے مارے ہوئے لوگوں کی ضرورت کا خیال رکھتے ہوئے وقتی طور پر رسول اللہ صلی اللہ علیہ وسلم نے صحابۂ کرام رضی اللہ عنہم کو تین دن سے زیادہ قربانی کا گوشت کھانے اور ذخیرہ کرنے سے منع فرمایا دیا تھا، بعد ازاں جب حالات بہتر ہوگئے تو آپ علیہ السلام نے یہ پابندی ختم کر دی۔ آگے آنے والی احادیث میں اس کی تصریح موجود ہے۔ مذکورہ پس منظر کو سامنے رکھتے ہوئے معلوم ہوتا ہے کہ شارح علیہ السلام نے انسان کی مصلحت کا خوب خوب لحاظ رکھا ہے، لہٰذا اب بھی اگر حالات کی تنگی کی وجہ سے ایسی مشکلات کا سامنا ہو تو مذکرہ لائحہ عمل اختیار کیا جا سکتا ہے۔ (۲) اگلے باب میں امام نسائی رحمہ اللہ جو احادیث لائے ہیں ان میں تین دن سے زیادہ قربانیوں کے گوشت کھانے اور ذخیرہ کرنے کی رخصت ہے، اس لیے اب تین دن سے زائد گوشت کھایا بھی جا سکتا ہے، اور ذخیرہ بھی کیا جا سکتا ہے، البتہ فقراء کو دینا لازم ہے۔"}],[4424,"عبدالرحمٰن بن عوف رضی اللہ عنہ کے غلام ابو عبید کہتے ہیں کہ میں نے علی بن ابی طالب کرم اللہ وجہہ کو عید کے دن دیکھا، انہوں نے خطبے سے پہلے نماز شروع کی اور بلا اذان اور بلا اقامت پڑھی، پھر کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو منع فرماتے ہوئے سنا کہ کوئی تین دن سے زیادہ اپنی قربانی میں سے کوئی چیز روکے رکھے، (یعنی اسے چاہیئے کہ بانٹ دے)۔","الألباني: صحيح",{"u2":"حضرت ابو عبید سے روایت ہے کہ میں نے عید کے دن حضرت علی بن ابی طالب رضی اللہ عنہ کے ساتھ عید پڑھی۔ آپ نے خطبے سے پہلے نماز عید پڑھائی۔ اذان ہوئی نہ اقامت، پھر فرمانے لگے: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ تین دن سے زائد قربانی کا گوشت رکھنے سے منع فرماتے تھے۔","f2":"(۱) یہ حدیث مبارکہ خطبۂ عید کی مشروعیت پر واضح دلیل ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے خطبۂ عید پر مداومت اور ہمیشگی فرمائی ہے۔ (۲) اس حدیث مبارکہ سے یہ بھی معلوم ہوا کہ خطبۂ عید اور خطبۂ جمعۃ المبارک ایک دوسرے سے مختلف ہیں۔ خطبۂ عید، نماز عید کے بعد ہوتا ہے جبکہ خطبۂ جمعہ، نماز جمعہ سے پہلے ہوتا ہے، البتہ عید اور جمعہ دونوں کے خطبے کھڑے ہو کر دینا مشروع ہے الا کہ کوئی معقول شرعی عذر ہو۔ رسول اللہ صلی اللہ علیہ وسلم نے عید اور جمعۃ المبارک کا خطبہ ہمیشہ کھڑے ہو کر دیا ہے۔ (۳) نماز عیدین کے لیے اذان ہے نہ اقامت۔"}],[4425,"علی بن ابی طالب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے تمہیں منع فرمایا ہے کہ تم تین دن سے زیادہ اپنی قربانی کا گوشت کھاؤ۔","الألباني: صحيح",{"u2":"حضرت علی بن ابی طالب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تمہیں تین دن سے زائد اپنی قربانیوں کے گوشت کھانے سے منع فرما دیا ہے۔"}],[4426,"جابر بن عبداللہ رضی اللہ عنہما سے روایت کہ رسول اللہ صلی اللہ علیہ وسلم نے تین دن کے بعد قربانی کا گوشت کھانے سے منع فرمایا، پھر فرمایا: \"کھاؤ، توشہ (زاد سفر) بناؤ اور ذخیرہ کر کے رکھو\"۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے تین دن سے زائد قربانی کا گوشت کھانے سے منع فرمایا تھا، پھر آپ نے فرمایا: ’’اب کھائو۔ سفر میں بھی ساتھ لے جائو اور ذخیرہ بھی کرو۔‘‘","f2":"حدیث مبارکہ کے الفاظ سے ظاہراً یہ معلوم ہوتا ہے کہ اب قربانی کا گوشت کھانے اور ذخیرہ کرنے کا حکم ہے، یعنی ایسا کرنا ضروری ہے کیونکہ حدیث کے الفاظ ہیں: [کُلُوْا وَ تَزَوَّدُوْا وَ ادَّخِرُوْا] یعنی کھائو، زادِ راہ بنائو اور ذخیرہ کرو۔ یہ تینوں صیغے امر کے ہیں لیکن جب کوئی قرینہ صارفہ موجود ہو تو پھر امر استحباب، رخصت اور جواز وغیرہ پر بھی دلالت کرتا ہے۔ اس جگہ امر استحباب اور رخصت کے معنی میں ہے کیونکہ صحابہ کرام رضی اللہ عنہم نے اس سے رخصت ہی سمجھی ہے۔ بعض روایات میں الفاظ یہ ہیں: [اَنَّ رَسُوْلَ اللّٰہِV نَہَانَا اَنْ نَاْکُلَہٗ فَوْقَ ثَلَاثَۃِ اَیَّامٍ ثُمَّ رَخَّصَ لَنَا اَنْ نَّاْکُلَہٗ وَ نَدَّخِرَہٗ] ’’بے شک رسول اللہ صلی اللہ علیہ وسلم نے ہمیں تین دن سے زیادہ قربانی کا گوشت کھانے سے منع کیا تھا، پھر آپ نے ہمیں اس کے کھانے اور ذخیرہ کرنے کی رخصت دے دی۔‘‘ (دیکھئے حدیث: ۴۴۳۳)"}],[4427,"عبداللہ بن خباب سے روایت ہے کہ ابو سعید خدری رضی اللہ عنہ ایک سفر سے آئے تو ان کے گھر والوں نے انہیں قربانی کے گوشت میں سے کچھ پیش کیا، انہوں نے کہا: میں اسے نہیں کھا سکتا جب تک کہ معلوم نہ کر لوں، چنانچہ وہ اپنے اخیافی بھائی قتادہ بن نعمان کے پاس گئے (وہ بدری صحابی تھے) اور ان سے اس بارے میں پوچھا؟ انہوں نے کہا: تمہارے بعد نیا حکم ہوا جس سے تین دن بعد قربانی کا گوشت کھانے پر سے پابندی ہٹ گئی۔\n§وضاحت\n۱؎: \"اخیافی بھائی\" وہ بھائی، بہن جن کی ماں ایک ہو اور باپ الگ الگ ہوں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن خباب سے روایت ہے کہ ابو سعید خدری رضی اللہ عنہ ایک سفر سے واپس تشریف لائے تو ان کے گھر والوں نے ان کو قربانی کا گوشت پیش کیا۔ وہ فرمانے لگے: میں تو نہیں کھائوں گا حتیٰ کہ میں یہ مسئلہ پوچھوں، پھر وہ اپنے اخیافی (مادری) بھائی حضرت قتادہ بن نعمان رضی اللہ عنہ جو بدری صحابی تھے، کے پاس گئے اور ان سے اس کے متعلق پوچھا تو انہوں نے بتایا: آپ کے بعد ایک نیا حکم جاری ہو چکا ہے، اس حکم کو ختم کرنے کے لیے جس میں انہیں (صحابہ کرام کو) تین دن کے بعد قربانیوں کا گوشت کھانے سے منع کر دیا گیا تھا۔ (مطلب یہ ہے کہ تمہارے بعد ایک نیا حکم جاری ہو چکا ہے۔ جس سے تین دن کے بعد قربانی کا گوشت نہ کھانے کا حکم منسوخ ہو گیا ہے۔)"}],[4428,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تین دن سے زیادہ قربانی کا گوشت کھانے سے روکا ہے، پھر قتادہ رضی اللہ عنہ ابو سعید خدری رضی اللہ عنہ کے پاس آئے اور وہ ابو سعید خدری رضی اللہ عنہ کے اخیافی بھائی اور بدری صحابی تھے، ابوسعید نے قتادہ کو (گوشت) پیش کیا، تو وہ بولے: کیا اس سے رسول اللہ صلی اللہ علیہ وسلم نے روکا نہیں ہے؟ ابوسعید رضی اللہ عنہ نے کہا: اس سلسلہ میں ایک نیا حکم آیا ہے، رسول اللہ صلی اللہ علیہ وسلم نے ہمیں تین دن سے زیادہ اسے کھانے سے روکا تھا، پھر ہمیں اسے کھانے اور ذخیرہ کرنے کی رخصت دی۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تین دن سے زائد قربانی کا گوشت کھانے سے منع فرمایا ہے۔ حضرت قتادہ بن نعمان رضی اللہ عنہ آئے جو حضرت ابو سعید خدری رضی اللہ عنہ کے اخیافی (مادری) بھائی اور بدری صحابی تھے۔ گھر والوں نے انہیں گوشت پیش کیا تو وہ فرمانے لگے: کیا رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع نہیں فرمایا؟ حضرت ابو سعید خدری نے فرمایا: اس کی بابت نیا فرمان جاری ہو چکا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے پہلے تین دن سے زایدہ قربانی کا گوشت کھانے سے منع فرمایا تھا، پھر اجازت فرما دی کہ ہم کھا بھی سکتے ہیں اور ذخیرہ بھی کر سکتے ہیں۔","f2":"یہ روایت اوپر والی روایت کے مخالف ہے کہ اس میں رخصت والی روایت حضرت ابو قتادہ بیان فرما رہے ہیں اور حضرت ابو سعید کھانے سے انکار ہیں اور اس روایت میں حضرت ابو قتادہ کھانے سے انکار ہیں اور رخصت کی روایت کے راوی حضرت ابو سعید ہیں۔ پہلی روایت صحیح ہے کیونکہ وہ صحیح بخاری کے موافق ہے۔ اس روایت میں ’’قلب‘‘ ہو گیا ہے، یعنی یہ روایت مقلوب ہے۔"}],[4429,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تم لوگوں کو تین چیزوں سے روکا تھا: قبروں کی زیارت کرنے سے، اب ان کی زیارت کرو، اس زیارت سے تم میں خیر و بھلائی بڑھنی چاہیئے، میں نے تمہیں تین دن بعد قربانی کا گوشت کھانے سے روکا تھا، لیکن اب کھاؤ اور جتنا چاہو روک کر رکھو، میں نے تمہیں کچھ برتنوں میں پینے سے روکا تھا لیکن اب جس برتن میں چاہو پیو، لیکن کوئی نشہ لانے والی چیز نہ پیو۔ محمد بن معدان کی روایت میں «امسکوا»\"روک کر رکھنے\" کا ذکر نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت بریدہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں نے تمہیں تین باتوں سے روکا تھا: (ایک تو میں نے تمہیں) قبروں پر جانے سے (روکا تھا)۔ اب جایا کرو لیکن قبروں پر جانا تمہاری نیکی میں اضافے کا ذریعہ بننا چاہیے۔ (دوسرا) میں نے تمہیں تین دن سے زائد قربانیوں کا گوشت کھانے سے منع فرمایا تھا، اب کھائو جب تک چاہو۔ او رکھو جب تک چاہو۔ اور (تیسرا) میں نے تمہیں چند برتنوں میں (پانی یا نبیذ) پینے سے روکا تھا، اب تم جس برتن میں چاہو پی سکتے ہو لیکن کوئی نشے والی چیز نہ پینا۔‘‘\nمحمد (ابن معدان) نے وَ اَمْسِکُوْا کے الفاظ بیان کیے۔ (مطلب یہ کہ یہ الفاظ استاد عمرو بن منصور نے بیان کیے ہیں۔)"}],[4430,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تمہیں تین دن بعد قربانی کا گوشت کھانے سے، مشکیزے کے علاوہ کسی برتن میں نبیذ بنانے سے اور قبروں کی زیارت کرنے سے روکا تھا۔ لیکن اب تم جب تک چاہو قربانی کا گوشت کھاؤ اور سفر کے لیے توشہ بناؤ اور ذخیرہ کرو، اور جو قبروں کی زیارت کرنا چاہے (تو کرے) اس لیے کہ یہ آخرت کی یاد دلاتی ہے اور ہر مشروب پیو لیکن نشہ لانے والی چیز سے بچو\"۔","الألباني: صحيح لغيره",{"u2":"حضرت بریدہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں نے تمہیں تین دن سے زائد قربانی کا گوشت کھانے سے روکا تھا، اور مشکیزے کے علاوہ کسی برتن میں نبیذ بنانے سے بھی روکا تھا۔ اسی طرح قبروں پر جانے سے بھی منع کیا تھا۔ اب تم جب تک چاہو، قربانی کا گوشت کھا سکتے ہو۔ سفر میں ساتھ بھی لے جا سکتے ہو اور ذخیرہ بھی کر سکتے ہو۔ اور جو شخص چاہے، قبروں پر جا سکتا ہے کیونکہ وہ آخرت یاد دلاتی ہیں۔ اسی طرح اب تم ہر برتن میں نبیذ بنا کر پی سکتے ہو لیکن ہر نشے والی چیز سے بچو۔‘‘","f2":"(۱) مذکورہ بابا احادیث اس بات پر صریح طور پر دلالت کرتی ہے کہ پہلے قبروں کی زیارت کے لیے جانا ممنوع تھا، بعد ازاں اس کی اجازت دے دی گئی۔ اب عورتیں اور مرد، سب جا سکتے ہیں۔ جن احادیث میں عورتوں پر، قبرستان جانے کی صورت میں، لعنت کی گئی ہے ان کا مفہوم یہ ہے کہ جو عورتیں شرعی تقاضے پامال کریں اور ان کا لحاظ نہ رکھتے ہوئے قبروں کی زیارت کے لیے جائیں، نیز اسی طرح خاوندوں کے حقوق کا خیال کیے بغیر ان کا قبرستان آنا جانا لگا رہے تو وہ لعنت کی حق دار ٹھہریں گی۔ حدیث میں اجازت کے الفاظ اگرچہ مذکر کے صیغے سے مروی ہیں، تاہم عام احکام میں عورتیں بھی مرجوں کے تابع ہوتی ہیں جیسا کہ قرآن و حدیث کے دیگر بہت سے احکام میں ایسے ہے۔ (۲) یہ حدیث مبارکہ اس اہم مسئلے کی طرف بھی واضح راہنمائی کرتی ہے کہ احکام میں نسخ ہوتا ہے جیسا کہ زیارتِ قبول کی ممانعت کا حکم منسوخ کر دیا گیا اور قبرستان جانے کی رخصت دے دی گئی، اسی طرح پہلے چند مخصوص قسم کے برتنوں میں مشروبات پینے سے روکا گیا تھا، پھر بعد میں اس ممانعت والے حکم کو مکمل طور پر منسوخ کر کے ان برتنوں میں مشروبات پینے کی اجازت دے دی گئی اور وہ اجازت تاحال باقی ہے۔ ہاں، البتہ نشہ آور مشروب، خواہ تھوڑی مقدار میں استعمال کیا جائے یا زیادہ مقدار میں، ہر دو صورت میں اس کا پینا حرام اور ناجائز ہے اور یہ حرمت ہمیشہ ہمیشہ کے لیے ہے۔"}],[4431,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ اعرابیوں (دیہاتیوں) کی ایک جماعت عید الاضحی کے دن مدینے آئی، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کھاؤ اور تین دن تک ذخیرہ کر کے رکھو\"، اس کے بعد لوگوں نے کہا: اللہ کے رسول! لوگ اپنی قربانی سے فائدہ اٹھاتے تھے، ان کی چربی اٹھا کر رکھ لیتے اور ان کی کھالوں سے مشکیں بناتے تھے۔ آپ نے فرمایا: \"تو اب کیا ہوا؟\" وہ بولا: جو آپ نے قربانی کے گوشت جمع کر کے رکھنے سے روک دیا، آپ نے فرمایا: \"میں نے تو صرف اس جماعت کی وجہ سے روکا تھا جو مدینے آئی تھی، کھاؤ، ذخیرہ کرو اور صدقہ کرو\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ اعرابیوں کا ایک قافلہ مدینہ منودہ آیا۔ ادھر قربانیوں کا وقت آ گیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’(قربانیوں کا گوشت) تین دن رکھ کر کھا سکتے ہو (زائد نہیں)۔ اس کے بعد آئندہ سال) لوگوں کے عرض کی: اے اللہ کے رسول! لوگ اپنی قربانیوں سے فائدہ اٹھایا کرتے تھے۔ ان کی چربی پگھلا لیا کرتے تھے اور چمڑوں سے مشکیزے بنا لیا کرتے تھے۔ آپ نے فرمایا: ’’کیا مطلب؟‘‘ لوگوں نے کہا: آپ نے جو قربانی کا گوشت وغیرہ رکھنے سے روک دیا ہے۔ آپ نے فرمایا: ’’میں نے تو اس قافلے کی وجہ سے روکا تھا جو (دیہات سے) آیا تھا۔ اب تم کھائو، جمع بھی رکھو اور صدقہ بھی کرو۔‘‘","f2":"گویا پہلے سال آپ کا روکنا مخصوص حالات کی وجہ سے تھا جو اس قافلے کی آمد سے پیدا ہوئے تھے ورنہ اصولی طور پر قربانی کی ہر چیز، مثلاً: گوشت، چربی اور چمڑے وغیرہ سے دیر تک فائدہ اٹھایا جا سکتا ہے، البتہ فقراء اور سائلین کو دینا بھی ضروری ہے۔"}],[4432,"عابس کہتے ہیں کہ میں نے عائشہ رضی اللہ عنہا کے پاس جا کر عرض کیا: کیا رسول اللہ صلی اللہ علیہ وسلم تین دن بعد قربانی کا گوشت کھانے سے منع فرماتے تھے؟ بولیں: ہاں، لوگ سخت محتاج اور ضروت مند تھے، رسول اللہ صلی اللہ علیہ وسلم نے چاہا کہ مالدار لوگ غریبوں کو کھلائیں، پھر بولیں: میں نے آل محمد (گھر والوں) کو دیکھا کہ وہ لوگ پائے پندرہ دن بعد کھاتے تھے، میں نے کہا: یہ کس وجہ سے؟ وہ ہنسیں اور بولیں: محمد صلی اللہ علیہ وسلم کے گھر والوں نے کبھی بھی تین دن تک سالن روٹی پیٹ بھر کر نہیں کھائی یہاں تک کہ آپ صلی اللہ علیہ وسلم اللہ عزوجل کے پاس تشریف لے گئے۔","الألباني: صحيح",{"u2":"حضرت عابس سے روایت ہے کہ میں حضرت عائشہ رضی اللہ عنہا کے ہاں حاضر ہوا اور پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم قربانی کا گوشت تین دن سے زائد کھانے سے روکتے تھے؟ انہوں نے فرمایا: ہاں، لوگ بہت تنگ تھے، اس لیے رسول اللہ صلی اللہ علیہ وسلم نے بہتر سمجھا کہ مال دار لوگ فقیروں کو کھلائیں، پھر فرمانے لگیں: میں نے دیکھا ہے کہ آل محمد صلی اللہ علیہ وسلم پندرہ پندرہ دن کے بعد قربانی کے جانوروں کے پائے کھاتے تھے۔ میں نے کہا: ایسے کیوں؟ ہنس کر فرمانے لگیں: حضرت محمد صلی اللہ علیہ وسلم کے گھر والوں نے تین دن مسلسل سالن والی روٹی سیر ہو کر نہیں کھائی۔ حتی کہ آپ اللہ عز و جل کے پاس تشریف لے گئے۔","f2":"آغاز میں تنگ دستی تھی، بعد ازاں بے انتہا سخاوت کی وجہ سے آپ کے گھریلوں حالات اسی طرح سادہ رہتے تھے۔"}],[4433,"عابس کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے قربانی کے گوشت کے متعلق سوال کیا تو انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے لیے ایک ایک مہینے تک قربانی کے پائے رکھ چھوڑتے، پھر آپ اسے کھاتے۔","الألباني: صحيح",{"u2":"حضرت عابس نے کہا کہ میں نے حضرت عائشہ رضی اللہ عنہا سے قربانی کے گوشت کے بارے میں پوچھا۔ انہوں نے فرمایا: ہم ایک ایک ماہ تک قربانی کے پائے رسول اللہ صلی اللہ علیہ وسلم کے لیے رکھ چھوڑتے تھے۔ اور آپ کھا لیا کرتے تھے۔"}],[4434,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے تین دن سے زیادہ قربانی کا گوشت اٹھا کر رکھنے سے منع فرمایا پھر فرمایا: \"کھاؤ اور لوگوں کو کھلاؤ\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پہلے تین دن سے زائد قربانی کا گوشت رکھنے سے منع فرما دیا تھا، پھر آپ نے فرمایا: ’’(جب تک چاہو) کھائو اور (فقراء و مساکین کو بھی) کھلاؤ۔‘‘"}],[4435,"عبداللہ بن مغفل رضی اللہ عنہ کہتے ہیں کہ غزوہ خیبر کے دن چربی کی ایک مشک لٹکی ہوئی ہاتھ آئی، میں اس سے لپٹ گیا، میں نے کہا: اس میں سے میں کسی کو کچھ نہیں دوں گا، پھر میں مڑا تو دیکھا رسول اللہ صلی اللہ علیہ وسلم مسکرا رہے ہیں ۱؎۔\n§وضاحت\n۱؎: یعنی آپ صلی اللہ علیہ وسلم نے ان کو اس چربی کو لینے سے منع نہیں کیا، حالانکہ وہ یہودیوں کے ذبیحہ سے نکلی ہوئی تھی، جس سے ثابت ہوا کہ اہل کتاب :(یہود و نصاری ) کا ذبیحہ جائز ہے، :(سورۃ المائدہ آیت: ۵، میں بھی اس کی صراحت ہے ) مگر شرط یہ ہے کہ ذبح اسلامی طریقہ پر کیا گیا ہو، ان کا مشینی ذبیحہ جائز نہیں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مغفل رضی اللہ عنہ بیان کرتے ہیں کہ خیبر کے دن چربی کا ایک تھیلا (قلعہ سے) باہر پھینکا گیا۔ میں اس سے چمٹ گیا۔ میں نے (اپنے آپ سے) کہا: میں اس سے کسی کو کچھ نہیں دوں گا۔ اچانک میں مڑا تو رسول اللہ صلی اللہ علیہ وسلم (مجھے دیکھ سن کر) مسکرا رہے تھے۔","f2":"(۱) اہل کتاب، یعنی یہودی اور عیسائی لوگوں کے ذبیحے کے متعلق حکم شریعت یہ ہے کہ اسے کھایا جا سکتا ہے۔ قرآن مجید میں ارشاد باری تعالیٰ ہے: {وَ طَعَامُ الَّذِیْنَ اُوْتُوا الْکِتٰبَ حِلٌّ لَّکُمْ} (المائدۃ ۵:۵) ’’اہل کتاب (یہود و نصاری) کا طعام تمہارے لیے حلال ہے۔‘‘ مفسر قرآن حضرت عبداللہ بن عباس رضی اللہ عنہ فرماتے ہیں: [طَعَامُہُمْ، ذَبَائِحُہُمْ] یعنی اہل کتاب (یہود و نصاریٰ) کے طعام سے مراد ان کے ذبح شدہ جانور ہیں۔ دیکھئے: (صحیح البخاری الذبائح و الصید، قبل حدیث: ۵۵۰۸) (۲) ترجمۃ الباب (عنوان) کے ساتھ حدیث کی مناسبت اس طرح بنتی ہے کہ پھینکے گئے تھیلے میں جو چربی تھی وہ یقینا کسی ذبح شدہ جانور ہی کی تھی اور ظاہر ہے اسے کسی یہودی ہی نے ذبح کیا تھا۔ اگر ان کا ذبح شدہ جانور حلال نہ ہوتا تو اس جانور کی چربی بھی حلال نہ ہوتی، اور صحابیٔ رسول بھی اسے نہ اٹھاتے، رسول اللہ صلی اللہ علیہ وسلم بھی موجود تھے، وہ بھی منع فرما دیتے، لیکن بجائے روکنے کے آپ علیہ السلام اسے دیکھ کر مسکرا دئیے جس سے اس چربی کے حلال ہونے کا پتا چلتا ہے، نیز معلوم ہوا کہ اہل کتاب کے ساتھ جنگ ہو رہی ہو تب بھی ان کا ذبیحہ اور اس کے، تمام اجزاء حلال ہیں۔ (۳) یہودیوں کی بدکرداری کی وجہ سے گائے اور بکری کی کچھ چربی ان کے لیے حرام کر دی گئی تھی، اس کے باوجود حضرت عبداللہ بن مغفل رضی اللہ عنہ نے اسے اٹھا لیا کیونکہ وہ یہودیوں کے لیے حرام تھی، نہ کہ مسلمانوں کے لیے، اور رسول اللہ صلی اللہ علیہ وسلم نے مسکرا کر ان کے اس عمل کی توثیق فرما دی۔ صحیح بخاری اور صحیح مسلم میں یہ الفاظ بھی ہیں کہ جب میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا تو مجھے حیا آ گئی، یعنی میں شرمندہ سا ہو گیا۔ دیکھئے (صحیح البخاری، فرض الخمس، حدیث: ۳۱۵۳، و صحیح مسلم، الجہاد، حدیث: ۱۷۷۲) (۴) ’’مسکرا رہے تھے‘‘ میری حرص دیکھ کر۔ اسے تقریری حدیث کہا جاتا ہے۔ اور یہ بالاتفاق حجت شرعی ہے۔ یہ قطعی طور پر ناممکن ہے کہ شرعاً ایک کام ناجائز اور حرام ہو اور نبی صلی اللہ علیہ وسلم اسے دیکھ کر سمکرائیں یا خاموش رہیں۔"}],[4436,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ کچھ اعرابی (دیہاتی) ہمارے پاس گوشت لاتے تھے، ہمیں نہیں معلوم ہوتا کہ آیا انہوں نے اس پر اللہ کا نام لیا ہے یا نہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ اس پر اللہ کا نام لو اور کھاؤ\" ۱؎۔\n§وضاحت\n۱؎: معلوم ہوا کہ اس بابت خواہ مخواہ کا شک و شبہہ صحیح اور درست نہیں ہے، إلا یہ کہ پختہ طریقے سے ثابت ہو جائے کہ اس ذبیحہ پر اللہ کا نام نہیں لیا گیا ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ کچھ اعرابی لوگ ہمارے پاس گوشت لاتے تھے اور ہمیں معلوم نہیں ہوتا تھا انہوں نے (ذبح کرتے وقت) اللہ تعالیٰ کا نام لیا ہے یا نہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم اللہ تعالیٰ کا نام لے کر کھا لیا کرو۔‘‘","f2":"(۱) مسلمانوں اور اہل کتاب میں سے کسی بھی شخص کا ذبح کیا ہوا جانور حلال سمجھا جائے گا اور شک و شبہ ہونے کی صورت میں گوشت کھاتے ہوئے اللہ کا نام لینے سے شک و شبہ بھی زائل ہو جائے گا۔ لیکن سکھ، مجوسی اور مشرک وغیرہ کا ذبیحہ کھانا قطعاً جائز نہیں۔ (۲) مسلمانوں کے شہروں اور بازاروں وغیرہ میں پائی جانے والی اشیاء حلال سمجھی جائیں گی الا یہ کہ ان کی حرمت کی کوئی صریح دلیل موجود ہو، محض شک کی بنا پر کسی چیز کی حرمت ثابت نہیں ہوتی۔ اس مسئلے کی مزید وضاحت سعودی عرب کے مفتیٔ اعظم شیخ عبدالعزیز بن عبداللہ بن باز رحمہ اللہ کے کلام سے ملاحظہ فرمائیے۔ وہ فرماتے ہیں: ’’غیر اسلامی ملکوں کے بازاروں میں جو گوشت بک رہا ہوتا ہے، اگر اس کی بابت یہ معلوم ہو جائے کہ وہ اہل کتاب (یہودیوں یا عیسائیوں) کے ذبح کیے ہوئے جانوروں کا گوشت ہے تو وہ مسلمانوں کے لیے (اس وقت تک) حلال ہے جب تک یہ معلوم نہ ہو کہ (جس جانور کا وہ گوشت ہے) اس کو غیر شرعی طریقے سے ذبح کیا گیا تھا۔ یہ اس لیے کہ قرآنی نص کی رو سے تو اس کی اصل یہ ہے کہ وہ حلال ہے، لہٰذا اس صورت میں، قرآن کریم کی بیان کردہ اصل (حلت) سے اس وقت تک عدول نہیں کیا جائے گا جب تک کوئی ایسی پختہ دلیل نہ مل جائے جو اس (گوشت) کے حرام ہونے کا تقاضا کرتی ہو۔ اور اگر وہ گوشت (یہود و نصاریٰ کے علاوہ) دیگر کافروں کے ذبح کیے ہوئے جانوروں کا ہو تو وہ مسلمانوں پر حرام ہے اور بوجہ نص اور اجماع امت اس گوشت کو کھانا ناجائز ہے۔ ایسا گوشت محض کھاتے وقت اللہ کا نام لے لینے سے حلال نہیں ہو گا۔‘‘ و اللہ اعلم۔ دیکھئے: (ذخیرۃ العقبٰی شرح سنن النسائی: ۳۴/۵۱)"}],[4437,"عبداللہ بن عباس رضی اللہ عنہما آیت کریمہ: «ولا تأكلوا مما لم يذكر اسم اللہ عليه» \"جس پر اللہ کا نام نہ لیا گیا ہو اسے مت کھاؤ\" (الأنعام: ۱۲۱) کے بارے میں کہتے ہیں: (یہ اس وقت اتری جب) کفار و مشرکین نے مسلمانوں سے بحث کی تو کہا: جسے اللہ ذبح کرتا ہے (یعنی مر جائے) تو اسے تم نہیں کھاتے ہو اور جسے تم خود ذبح کرتے ہو اسے کھاتے ہو؟۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ نے اللہ تعالیٰ کے فرمان: {وَ لَا تَاْکُلُوْا مِمَّا لَمْ یُذْکَرِاسْمُ اللّٰہِ عَلَیْہِ} ’’وہ جانور نہ کھائو جس پر اللہ کا نام نہ لیا گیا ہو۔‘‘ کے بارے میں فرمایا: مشرکین نے مسلمانوں سے حجت بازی کی تھی کہ جس جانور کو اللہ تعالیٰ ذبح کرے، اسے تم نہیں کھاتے اور جسے تم خود ذبح کرتے ہو، اسے کھا لیتے ہو؟","f2":"معلوم ہوا آیت کریمہ میں وہ جانور مراد ہے جو خود بخود مر گیا ہو اور اسے ذبح کرنے کا موقع نہ ملا ہو۔ اسی طرح جس جانور کو اللہ تعالیٰ کی بجائے کسی اور کے نام پر ذبح کیا گیا ہو، وہ بھی حرام ہے۔ اسی طرح جس جانور کو مشرک نے ذبح کیا ہو، وہ بھی حرام ہے، خواہ اللہ یا غیر اللہ کا نام لے یا نہ کیونکہ اس کا اللہ تعالیٰ پر ایمان نہیں، البتہ موحد شخص ذبح کرتے وقت اللہ تعالیٰ کا نام لینا بھول جائے تو متفقہ طور پر اس کا ذبیحہ حلال ہے کیونکہ نسیان عذر ہے۔ ہاں، اگر موحد جان بوجھ کر ذبح کرتے وقت اللہ کا نام نہ لے تو اکثر اہل علم کے نزدیک ذبیحہ حرام ہے کیونکہ اس آیت میں وہ جانور کھانے سے منع کیا گیا ہے جس پر اللہ تعالیٰ کا نام نہ لیا گیا ہو مگر امام شافعی اور بعض دوسرے علماء نے ایسے ذبیحے کو حلال کہا ہے کیونکہ اللہ کا نام مومن کے دل میں قائم رہتا ہے۔ زبان سے ذکر کرے یا نہ کرے۔ سنن ابو داود کی ایک مرسل روایت بھی اس مفہوم میں آتی ہے۔ ان کے نزدیک مندرجہ بالا آیت: {مِمَّا لَمْ یُذْکَرِاسْمُ اللّٰہِ عَلَیْہِ} سے مردار جانور ہے یا وہ جانور جسے غیر اللہ کے نام پر ذبح کیا گیا ہو۔ و اللہ اعلم۔ لیکن جمہور اہل علم کی بات راجح ہے۔"}],[4438,"ابوثعلبہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \" «مجثمة» حلال نہیں ہے\"۔\n§وضاحت\n۱؎: «مجثمة» یعنی وہ جانور جس کو باندھ کر نشانہ لگا کر مسلسل تیر مارا جائے یہاں تک کہ وہ مر جائے۔","الألباني: صحيح",{"u2":"حضرت ابو ثعلبہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مجثمہ حلال نہیں۔‘‘","f2":"مجثمہ سے مراد وہ جانور ہے جسے باندھ کر دور سے تیروں وغیرہ کا نشانہ بنایا جائے اور وہ مر جائے۔ یہ حرام ہے۔ (تفصیل کے لیے دیکھئے، حدیث: ۴۳۳۱)"}],[4439,"ہشام بن زید کہتے ہیں کہ میں انس رضی اللہ عنہ کے ساتھ حکم (حکم بن ایوب) کے یہاں گیا تو دیکھا کہ چند لوگ امیر کے گھر میں ایک مرغی کو نشانہ بنا کر مار رہے ہیں، تو انس رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ہے کہ جانوروں کو باندھ کر اس طرح مارا جائے۔","الألباني: صحيح",{"u2":"حضرت ہشام بن زید سے منقول ہے کہ میں حضرت انس رضی اللہ عنہ کے ساتھ حکم بن ایوب کے پاس گیا تو کچھ لوگ امیر کے گھر میں ایک مرغی کو نشانہ بنا کر تیر مار رہے تھے۔ حضرت انس رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم ن ے منع فرمایا ہے کہ جانوروں کو باندھ کر نشانہ بنایا جائے۔","f2":"(۱) معلوم ہوا کسی بھی جاندار کو (جیسا کہ حدیث: ۴۴۴۶ وغیرہ میں آ رہا ہے) خواہ وہ انسان ہو، یا حیوان اور پرندہ یا درندہ وغیرہ اس کو بلا وجہ عذاب اور تکلیف دینا حرام ہے۔ (۲) اس حدیث مبارکہ سے یہ بھی معلوم ہوا کہ امر بالمعروف اور نہی عن المنکر ضروری ہے۔ اس میں کسی ملامت گر کی ملامت یا کسی صاحب اقتدار و اختیار شخص کا خوف نہیں ہونا چاہیے جیسا کہ حضرت انس بن مالک رضی اللہ عنہ نے کیا۔ انہوں نے حجاج بن یوسف کے چچیرے بھائی، اس کے نائب اور حاکم بصرہ حکم بن ایوب جیسے ظالم اور سفاک حکمران کے سامنے یہ فریضہ، کما حقہٗ ادا فرمایا۔ حکم بن ایوب کے متعلق معروف ہے کہ وہ بھی ظلم و جور میں اپنے چچا زاد حجاج بن یوسف کی طرح تھا۔ و اللہ اعلم۔"}],[4440,"عبداللہ بن جعفر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا گزر چند لوگوں کے پاس سے ہوا۔ وہ ایک مینڈھے کو تیر مار رہے تھے، آپ نے اسے پسند نہیں کیا اور فرمایا: \"جانوروں کا مثلہ نہ کرو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن جعفر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کچھ لوگوں کے پاس سے گزرے جو ایک مینڈھے کو نشانہ بنا کر تیر مار رہے تھے۔ آپ نے اس کو سخت ناپسند کیا اور فرمایا: ’’جانوروں کا مثلہ نہ کرو۔‘‘","f2":"مثلہ سے مراد ہے کس یکی شکل بگاڑنا یا زندہ سے کچھ گوشت الگ کرنا۔ ظاہر ہے کسی جاندار (حیوان یا پرندے) کو باندھ کر تیروں کے ساتھ نشانہ بنانے سے شکل بھی بگڑے گی کیونکہ تیر چہرے پر بھی لگ سکتے ہیں اور تیر لگنے سے گوشت بھی الگ ہو سکتا ہے۔"}],[4441,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس شخص پر لعنت بھیجی جس نے ایسی چیز کو نشانہ بنایا جو جاندار ہو ۱؎۔\n§وضاحت\n۱؎: یعنی نشانہ بازی کے مقصد سے نشانہ بنایا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس شخص پر لعنت فرمائی ہے جو کسی جاندار کو نشانہ بنائے۔"}],[4442,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"اللہ تعالی اس پر لعنت فرمائے جو جانوروں کا مثلہ کرے\" ۱؎۔\n§وضاحت\n۱؎: کسی جاندار کے ہاتھ پاؤں ناک اور کان وغیرہ اعضاء کو کاٹ کر اس کی شکل و صورت بگاڑ دینے کو مثلہ کہتے ہیں، مثلہ حرام ہے خواہ انسان کا ہو یا جانور کا، اور کسی حلال جانور کو ذبح کرنے کے بعد اس کے گوشت کی بوٹیاں بنانے کی کے مقصد سے اس کے ٹکڑے کرنا مثلہ نہیں ہے، مثلہ میں فقط شبیہ بگاڑ کر پھینک دینا مقصود ہوتا ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’الہل تعایٰ اس شخص پر لعنت فرمائے جو کسی جاندار کا مثلہ کرے۔‘‘"}],[4443,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی ایسی چیز کو نشانہ نہ بناؤ جس میں روح اور جان ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایسی چیز جس میں روح ہو اسے نشانہ نہ بناؤ۔‘‘"}],[4444,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم ایسی چیز کو نشانہ نہ بناؤ جس میں روح اور جان ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کسی جاندار چیز کو نشانہ بنانے سے منع فرمایا ہے۔","f2":"جاندار چیز کو نشانہ بنانا ظلم ہے اور ظلم حرام ہے۔ انسان پر ہو یا حیوان پر۔ حتیٰ کہ بے جان چیزوں پر بھی۔ ہر چیز کے ساتھ حسن سلوک فرض ہے۔ (تفصیل کے لیے دیکھئے، حدیث: ۴۳۳۱)"}],[4445,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی گوریا، یا اس سے چھوٹی کسی چڑیا کو بلا وجہ مارا تو اللہ تعالی قیامت کے دن اس سلسلے میں سوال کرے گا\"، عرض کیا گیا: اللہ کے رسول! تو اس کا صحیح طریقہ کیا ہے؟ آپ نے فرمایا: \"اس کا صحیح طریقہ یہ ہے کہ وہ اسے ذبح کر کے کھائے اور اس کا سر کاٹ کر یوں ہی نہ پھینک دے\"۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے مرفوعاً روایت ہے کہ آپ(صلی اللہ علیہ وسلم) نے فرمایا: ’’جس شخص نے چڑیا یا اس سے بڑے کسی جانور کو ناحق قتل کیا، اللہ تعالیٰ قیامت کے دن اس سے اس کے متعلق پوچھے گا۔‘‘ پوچھا گیا: اللہ کے رسول! اس کا حق کیا ہے؟ آپ نے فرمایا: اس کا حق یہ ہے کہ اسے ذبح کر کے کھائے۔ اس کا سر کاٹ کر پھینک نہ دے۔‘‘","f2":"تفصیل کے لیے دیکھئے، حدیث: ۴۳۵۴ کے فوائد و مسائل۔"}],[4446,"شرید رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جس نے بلا وجہ کوئی گوریا ماری تو وہ قیامت کے دن اللہ تعالی کے سامنے چلائے گی اور کہے گی: اے میرے رب! فلاں نے مجھے بلا وجہ مارا مجھے کسی فائدے کے لیے نہیں مارا\"۔","الألباني: ضعيف",{"u2":"حضرت شرید رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جس شخص نے ایک چڑیا کو بھی بے فائدہ قتل کیا، قیامت کے دن چڑیا اس شخص کے خلاف با آواز بلند اللہ تعالیٰ سے فریاد کرتے ہوئے کہے گی: اے میرے پروردگار! فلاں شخص نے مجھے بے فائدہ قتل کیا۔ کسی فائدے کے لیے ذبح نہیں کیا۔‘‘","f2":"’دبے فائدہ‘‘ نہ کھانے کے لیے، نہ کسی دوائی میں ڈالنے کے لیے بلکہ شغل اور کھیل کے طور پر۔ یہ فریاد خالی فریاد نہیں ہو گی بلکہ اس پر داد رسی بھی ہو گی۔ اور اس شخص کو سزا بھی ملے گی۔"}],[4447,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر کے دن پالتو گدھوں کے گوشت سے اور «جلالہ» پر سواری کرنے اور اس کا گوشت کھانے سے منع فرمایا۔\n§وضاحت\n۱؎: \"عبداللہ بن عمرو\" یعنی اگر راوی نے «محمد» کے بعد «عن أبیہ» کہا تھا تو «عبد الله بن عمرو» کی روایت ہو گی، اور اگر «عن جدہ» کہا تھا تو «عمرو بن العاص» کی روایت ہو گی، ابوداؤد میں بغیر شک کے «عمرو بن شعیب عن أبیہ، عن جدہ» ہے، یعنی \" عبداللہ بن عمرو \" رضی اللہ عنہما، مزی نے اس کو \" عبداللہ بن عمرو \" رضی اللہ عنہما ہی کی مسند ذکر کیا ہے۔ «جلالہ»: وہ جانور جو صرف نجاست یا اکثر نجاست کھاتا ہو۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب کے پردادا محترم (حضرت عبداللہ بن عمرو رضی اللہ عنہ) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر (کی جنگ) کے دن گھریلو (پالتو) گدھوں کے گوشت سے، نیز گندگی کھانے والے جانوروں کے گوشت اور سواری سے منع فرمایا تھا","f2":"(۱) جس جانور کی اکثر خوراک گندگی ہو، اس جانور (حیوان پا پرندے) کا گوشت کھانا ممنوع ہے۔ (۲) اس حدیث سے یہ مسئلہ بھی معلوم ہوا کہ جلالۃ، یعنی گندگی کھانے پر گزارا کرنے والے جانور پر سواری کرنا ممنوع ہے۔ (۳) گھریلو، یعنی پالتو گدھے کا گوشت تو مطلقاً حرام ہے، خواہ وہ گندگی کھائے یا نہ، البتہ اس پر سواری کرنا جائز ہے کیونکہ اسے پیدا ہی سواری اور باربرداری کے لیے کیا گیا ہے۔ اس کا پسینہ وغیرہ پاک ہے لیکن گندگی کھانے والا جانور، خواہ کوئی بھی ہو، اگر گندگی اس قدر کھائے کہ اس کے اثرات اس کے گوشت میں محسوس ہوں، مثلاً: گوشت سے گندگی کی بدبو آئے یا ذائقہ خراب ہو یا رنگ بدل جائے تو اسے نہ صرف کھانا حرام ہے بلکہ ایسے جانور پر سواری ببھی منع ہے کیونکہ اس کے پسینے میں بھی گندگی کے اثرات ہوں گے، لہٰذا پسینہ پلید ہو گا۔ سوار کے کپڑے لازماً جانور کے پسینے سے آلودہ ہو جائیں گے۔ وہ بھی پلید ہو جائیں گے۔ کپڑے جسم کو لگتے ہیں، لہٰذا سوار کا جسم بھی پلید ہو ائے گا، اس لیے سواری بھی منع ہے۔ پسینہ تو گوشت ہی سے پیدا ہوتا ہے۔ گوشت پلید تو پسینہ بھی پلید۔ البتہ معمولی گندگی کھانے والے جانور کا یہ حکم نہیں کیونکہ جانوروں کو خالص اور پاک خوراک کا پابند نہیں کیا جا سکتا۔ معمولی گندگی کے اثرات گوشت وغیرہ تک نہیں پہنچتے۔"}],[4448,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے «مجثمہ» (جو جانور باندھ کر نشانہ لگا کر مار ڈلا گیا ہو) سے، «جلالہ» (گندگی کھانے والے جانور) کے دودھ سے، اور مشک کے منہ سے منہ لگا کر پینے سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجثمہ، گندگی کھانے والے جانور کے دودھ اور مشکیزے کے منہ سے صاس کے منہ سے، منہ لگا کر) پانی پینے سے منع فرمایا ہے۔","f2":"(۱) عنوان کا مقصد بالکل واضح ہے کہ جس جانور کی ساری یا اکثر خوراک گندگی کھانا ہی ہے، اس جانور کا دودھ پینا ممنوع ہے۔ (۲) ممانعت کی وجہ ویہ ہے جو سابقہ حدیث کے فوائد و مسائل میں بیان ہو چکی ہے کہ گندگی کے اثرات، گندگی کھانے والے جانور کے دودھ میں سرایت کر جاتے ہیں۔ و اللہ اعلم۔ (۳) اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ مشکیزے کے منہ سے، منہ لگا کر پانی پینا ممنوع ہے۔ اس ممانعت کی وجہ یہ ہے کہ اس صورت میں اگر مشکیزے کے اندر کوئی کیڑا وغیرہ یا کوئی اور مضر چیز ہو گی تو وہ پینے والے کے منہ میں چلی جائے گی۔ اسی لیے رسول اللہ صلی اللہ علیہ وسلم نے ایسا کرنے سے روک دیا ہے۔ ہاں مجبوری کی صورت میں پیا جا سکتا ہے۔ عام اجازت نہیں۔"}],[4449,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے پاکیزہ کھانا وہ ہے جو آدمی اپنی (محنت کی) کمائی سے کھائے، اور آدمی کی اولاد اس کی کمائی ہے\" ۱؎۔\n§وضاحت\n۱؎: سب سے پاکیزہ کمائی کی بابت علماء کے تین اقوال ہیں: ۱- تجارت ۲- ہاتھ کی کمائی اور ایسا پیشہ جو کمتر درجے کا نہ ہو ۳- زراعت :(کھیتی باڑی )، ان میں سب سے بہتر کون ہے اس کا دارومدار حالات و ظروف پر ہے۔ راجح یہ ہے کہ سب سے بہتر اور پاکیزہ رزق وہ ہے جو حدیث رسول «جعل رزقی تحت ظل رمحی» کے مطابق بطور غنیمت حاصل ہو۔ اس لیے کہ یہ دین کے غلبہ کے لیے حاصل ہونے والی جدوجہد اور قتال میں حاصل مال ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’آدمی کی بہترین خوراک وہ ہے جو وہ اپنی محنت سے کما کر کھائے۔ اور اولاد بھی آدمی کی اپنی کمائی ہے۔‘‘","f2":"(۱) محنت سے کما کر کھانے کو رسول اللہ صلی اللہ علیہ وسلم نے بہترین اور پاکیزہ کمائی قرار دیا ہے۔ (۲) اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوا کہ اولاد کی کمائی میں والد کو، اولاد کی اجازت کے بغیر بھی، تصرف کرنے کا حق اور اختیار ہے۔ امام خطابی رحمہ اللہ فرماتے ہیں کہ اگر اولاد صاحب استطاعت ہو تو ان پر والدین کا نان و نفقہ واجب ہے۔ تمام فقہاء نے اولاد پر والدین کا خرچہ واجب اور ضروری قرار دیا ہے۔ (۳) ’’اولاد بھی آدمی کی اپنی کمائی ہے‘‘ گویا انسان کو یا تو اپنی محنت سے کما کر کھانا چاہیے یا اپنی اولاد کی کمائی سے کیونکہ وہ بھی غیر نہیں۔ اور اپنی اولاد کا مال کھانا عار بھی نہیں جبکہ اور کسی سے لے کر کھانا عار ہے، خواہ وہ سگا بھائی ہی ہو۔ اسلام کا منشا یہ ہے کہ کوئی شخص مفت خور یا منگتا نہیں ہونا چاہیے الا یہ کہ کوئی معذور ہو۔ کمائی کے قابل نہ ہو ورنہ کسی پر بوجھ بننا صدقہ لینے کے مترادف ہے۔ و اللہ اعلم۔"}],[4450,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تمہاری اولاد سب سے پاکیزہ کمائی ہے، لہٰذا تم اپنی اولاد کی کمائی میں سے کھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’تمہاری اولاد تمہاری ببہترین کمائی ہے، لہٰذا تم اپنی اولاد کی کمائی کھا سکتے ہو۔‘‘","f2":"’’کھا سکتے ہو‘‘ لکین ضرورت کے مطابق۔ یہ نہیں کہ اولاد کے مال کو ضائع کرتا پھرے یا انہیں بلاوجہ تنگ کرے۔ احادیث میں ’’کھانے‘‘ کا لفظ ہے۔ مراد تمام ضروریات ہیں، خواہ وہ خوراک سے متعلق ہوں یا لباس سے۔ علاج سے متعلق ہوں یا رہن سہن سے لیکن ضرورت اور احتیاج کے وقت اور مطابق۔ چونکہ خوراک انسان کا سب سے بڑا مسئلہ ہے، اس لیے اس کا خصوصاً ذکر فرمایا۔"}],[4451,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے پاکیزہ کھانا وہ ہے جو آدمی اپنی کمائی سے کھائے اور اس کی اولاد بھی اس کی کمائی ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’آدمی کی بہترین خوراک وہ ہے جو وہ اپنی محنت سے کما کر کھائے۔ اور اس کی اولاد بھی اس کی کمائی ہی ہے۔‘‘","f2":"بہترین محنب اور کمائی کیا ہے؟ علماء نے اپنے اپنے نقطۂ نظر سے اس کا تعین کیا ہے۔ بعض نے تجارت کو افضل پیشہ قرار دیا ہے کیونکہ یہ صاف ستھرا اور معزز پیشہ ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے اختیار فرمایا تھا۔ بعض علماء نے ہاتھ کی محنت کو افضل کہا ہے کیونکہ انبیاء علیہم السلام عموماً ہاتھ کی کوئی نہ کوئی محنت فرماتے تھے۔ بعض نے زراعت کو بہترین کمائی کہا ہے کیونکہ زراعت سے تمام مخلوقات اپنی اپنی خوراک حاصل کرتی ہیں۔ ظاہر ہے ان کی خوراک کا ثواب زراعت کرنے والے کو ملتا ہے اور اس کی کمائی سے پرندے، جانور، کیڑے مکوڑے اور غریب انسان مفت خوراک حاصل کرتے ہیں۔ بعض نے مال غنیمت کو افضل کمائی سمجھا ہے مگر یہ تو صرف فوج کو حاصل ہو سکتی ہے۔ آج کل کے دور میں فوج کے لیے بھی ممکن نہیں، لہٰذا یہ قول کمزور ہے۔ نہ ہر وقت لڑائی ہو سکتی ہے، نہ ہر شخص لڑ سکتا ہے اور نہ ہر لڑائی سے غنیمت حاصل ہو سکتی ہے۔ اصل بات یہ ہے کہ ہر شخص اپنی ذہنی استعداد اور رجحان کے ساتھ کوئی بھی پیشہ اختیار کر سکتا ہے۔ اس سے حلال کمائے تو وہی اس کے لیے افضل ہے۔"}],[4452,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے پاکیزہ کھانا وہ ہے جو آدمی اپنی کمائی سے کھائے اور اس کی اولاد بھی اس کی کمائی ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’انسان کی پاکیزہ ترین خوراک وہ ہے جو وہ اپنی کمائی سے کھائے۔ اور اس کی اولاد ببھی اس کی کمائی ہی ہے۔‘‘","f2":"’’اس کی کمائی ہے‘‘ کیونکہ اس نے بڑی محنت اور مشقت سے ان کو پال پوس کر جوان کیا ہے۔"}],[4453,"نعمان بن بشیر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا (اللہ کی قسم، میں آپ سے سن لینے کے بعد کسی سے نہیں سنوں گا)آپ فرما رہے تھے: \"حلال واضح ہے اور حرام واضح ہے، ان دونوں کے بیچ کچھ شبہ والی چیزیں ہیں\" (یا آپ نے «مشتبہات» کے بجائے «مشتبھۃً» کہا ۱؎)- اور فرمایا: \"میں تم سے اس سلسلے میں ایک مثال بیان کرتا ہوں: اللہ تعالی نے ایک چراگاہ بنائی تو اللہ کی چراگاہ یہ محرمات ہیں، جو جانور بھی اس چراگاہ کے پاس چرے گا قریب ہے کہ وہ اس میں داخل ہو جائے\" یا یوں فرمایا: \"جو بھی اس چراگاہ کے جانور پاس چرائے گا قریب ہے کہ وہ جانور اس میں سے میں چر لے۔ اور جو مشکوک کام کرے تو قریب ہے کہ وہ (حرام کام کرنے کی) جرات کر بیٹھے\"۔\n§وضاحت\n۱؎: گویا دنیاوی چیزیں تین طرح کی ہیں: حلال، حرام اور مشتبہ :(شک و شبہہ والی چیزیں ) پس حلال چیزیں وہ ہیں جو کتاب و سنت میں بالکل واضح ہیں جیسے دودھ، شہد، میوہ، گائے اور بکری وغیرہ، اسی طرح حرام چیزیں بھی کتاب و سنت میں واضح ہیں جیسے شراب، زنا، قتل اور جھوٹ وغیرہ اور مشتبہ وہ ہے جو کسی حد تک حلال سے اور کسی حد تک حرام سے، یعنی دونوں سے مشابہت رکھتی ہو جیسے رسول اللہ صلی اللہ علیہ وسلم نے راستہ میں ایک کھجور پڑی ہوئی دیکھی تو فرمایا کہ اگر اس بات کا ڈر نہ ہوتا کہ یہ صدقہ کی ہو سکتی ہے تو میں اسے کھا لیتا۔ اس لیے مشتبہ امر سے اپنے آپ کو بچا لینا ضروری ہے، کیونکہ اسے اپنانے کی صورت میں حرام میں پڑنے کا خطرہ ہے، نیز شبہ والی چیز میں پڑتے پڑتے آدمی حرام میں پڑنے اور اسے اپنانے کی جرات و جسارت کر سکتا ہے۔","الألباني: صحيح",{"u2":"حضرت نعمان بن بشیر رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا، اور اللہ کی قسم! میں آپ کے بعد کسی سے نہ سنوں گا، آپ فرما رہے تھے: ’’حلال واضح ہے، حرام بھی واضح ہے لیکن ان کے درمیان کچھ مشتبہ چیزیں بھی ہیں۔ اس سلسلے میں، میں تمہیں ایک مثال بیان کرتا ہوں۔ یقینا اللہ تعالیٰ نے کچھ علاقہ ممنوعہ قرار دیا ہے اور وہ علاقہ اللہ تعالیٰ کی حرام کردہ چیزیں ہیں۔ جو شخص اس ممنوعہ علاقے کے قریب قریب (جانور) چرائے گا، بہت ممکن ہے کہ وہ اس ممنوعہ علاقے میں چرنے لگے۔ اسی طرح جو شخص مشتبہ کام کرتا ہے، بہت ممکن ہے کہ وہ حرام کام پر بھی جرأت کر بیٹھے۔‘‘","f2":"(۱) کسب معاش میں شبہات سے بچنا چاہیے، یعنی انسان کی کمائی بالکل صاف ستھری اور حلال طیب ہونی چاہیے نہ کہ مشکوک و مشتبہ۔ (۲) حلال اور حرام، دونوں واضح ہیں لیکن اس شخص کے لیے جسے شرعی نصوص کا علم ہو۔ ہر کسی کو یہ فضیلت حاصل نہیں۔ یہ مرتبہ اور بصیرت راسخ فی العلم اہل علم کو حاصل ہو سکتا ہے۔ ذٰلِکَ فَضْلُ اللّٰہِ یُؤْتِیْہِ مَنْ یَّشَائُ۔ (۳) یہ حدیث بہت زیادہ قدر و منزلت والی ہے۔ اکثر محدثین کرام نے اسے ’’کتاب البیوع‘‘ میں بیان فرمایا ہے کیونکہ زیادہ تر شکوک و شبہات معاملات ہی میں ہوتے ہیں۔ مزید برآں یہ کہ اس حدیث کا تعلق نکاح و طلاق، مطعومات و مشروبات اور شکار وغیرہ کے ساتھ بھی ہے۔ جو شخص غور و فکر کرے گا، اسے یہ سب کچھ بخوبی معلوم ہو جائے گا۔ (۴) حلال و حرام کے درمیان ایک ایسا درجہ ہے جس کی معرفت اور پہنچان ضروری ہے اور اس سے بچنا بھی۔ اور وہ ایسے شبہات اور ایسی مشکوک و مشتبہ اشیاء کا درجہ ہے جن کی حلت و حرمت دونوں غیر واضح ہیں، اس لیے ایک عقل مند شخص کے لیے اس درجے کی معرفت بہت ضروری ہے۔ (۵) کسی مسئلے اور شرعی حکم کی وضاحت کے لیے مثال بیان کی جا سکتی ہے تاکہ وہ مسئلہ اچھی طرح سمجھ میں آ جائے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے مثال بیان فرمائی۔ (۶) جو شخص شبہات کا شکار ہوتا ہے، اس کا دین اور اس کی عزت داغ دار ہو جاتے ہیں۔ (۷) احکام کی تین قسمیں ہیں: ایک قسم ایسے احکام کی ہے کہ قرآن و حدیث میں انہیں بجا لانے کا تقاضا ہے اور نہ کرنے پر وعید ہے۔ دوسری قسم ایسے احکام کی ہے کہ ان کے نہ کرنے کی نص ہو اور کرنے پر وعید ہو۔ اور تیسری قسم ایسے احکام کی ہے جن کے کرنے یا نہ کرنے کے متعلق کوئی نص نہ ہو۔ پہلی قسم کے احکام واضح طور پر حلال ہیں اور دوسری قسم کے احکام واضح طور پر حرام جبکہ تیسری قسم کے احکام واضح طور پر حلال ہیں نہ واضح طور پر حرام بلکہ وہ مشتبہ ہیں۔ جن احکام کی صورت حال اس طرح ہو ان سے اجتناب کرنا چاہیے تاکہ انسان حرام کا مرتکب نہ ہو۔ (۸) ’’ممنوعہ علاقہ‘‘ عرب میں عام رواج تھا کہ بادشاہ اور سردار کچھ علاقہ اپنے جانوروں کے چرنے کے لیے مخصوص قرار دے دیتے تھے۔ عام لوگ وہاں جانور نہیں چرا سکتے تھے بلکہ لوگ ڈرتے ہوئے اس علاقے کے قریب بھی نہیں پھٹکتے تھے کہ کہیں غلطی ہی سے جانور اس علاقے میں داخل نہ ہو جائیں اور بادشاہ کے کارندوں کے ظلم و ستم کا نشانہ بن جائیں۔ رسول اللہ صلی اللہ علیہ وسلم نے یہی مثال حرام، حلال اور مشتبہ چیزوں کے لیے بیان فرمائی۔ مخصوص علاقہ ’’حرام ہے‘‘ قریبی علاقہ ’’مشتبہ‘‘ ہے۔ اور دور کا علاقہ ’’حلال‘‘ ہے۔ محفوظ وہی شخص ہے جو صرف حلال علاقے میں رہے۔ مشتبہ علاقے میں جانے والے کے لیے خطرہ ہے کہ وہ کسی وقت بھی حرام کے علاقے میں داخل ہو سکتا ہے۔ عموماً مشتبہ کام کرنے والا حرام سے نہیں بچ سکتا۔"}],[4454,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگوں پر ایک ایسا زمانہ آئے گا کہ آدمی کو اس بات کی فکر و پروا نہ ہو گی کہ اسے مال کہاں سے ملا، حلال طریقے سے یا حرام طریقے سے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’لوگوں پر ایک ایسا وقت آئے گا کہ آدمی پروا نہیں کرے گا کہ مال کہاں سے آ رہا ہے؟ حلال (طریقے) سے یا حرام سے؟‘‘","f2":"(۱) اس باب کے قائم کرنے سے امام صاحب رحمہ اللہ کا مقصد، کمائی میں شبہات سے بچنے کا شوق دلانا ہے کوینکہ جب انسان شبہات سے نہیں بچتا بلکہ ان کا شکار ہو جاتا ہے تو پھر مشتبہ اشیاء میں پڑنا اسے محرمات (اللہ تعالیٰ کی حرام کردہ اشیائ) کی طرف گھسیٹ لے جاتا ہے۔ (۲) یہ حدیث مبارکہ رسول اللہ صلی اللہ علیہ وسلم کی نبوت و رسالت کا کھلا معجزہ ہے کہ آپ صلی اللہ علیہ وسلم نے جس بات کی پیشین گوئی اپنے عہد مبارک میں فرمائی تھی وہ آج من و عن پوری ہو رہی ہے۔ (۳) اس حدیث مبارکہ سے یہ بھی ثابت ہوتا ہے کہ کسی بھی زمانے میں حلال، ساری دنیا سے مکمل طور پر، ختم نہیں ہو گا بلکہ کسی نہ کسی جگہ یہ موجود رہے گا، لہٰذا ضروری ہے کہ ہر مسلمان شخص کسب حلال کی کوشش کرے۔ جب وہ طلب حلال میں مخلص ہو گا تو اللہ تعالیٰ ضرور اس کی مدد فرمائے گا۔ (۴) ان تمام باتوں کا لب لباب یہ ہے کہ لوگوں کا مقصود صرف مال ہو گا۔ مال ملے جہاں سے بھی ملے۔ حلال و حرام کی تمیز نہیں رہے گی۔ آج ہمارے ملک میں عموماً یہی فضا ہے۔ ہر شخص، ہر ادارہ، ہر جماعت، ہر تنظیم حصول مال کو اولیں مقصد قرار دے رہے ہیں۔ حلال و حرام بعد کی بات ہے، حتی کہ مذہبی ادارے اور تنظیمیں بھی کوئی خاص احتیاط کا ثبوت نہیں دے رہے۔ الا ما شاء اللہ۔"}],[4455,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگوں پر ایک ایسا زمانہ آئے گا کہ وہ سود کھائیں گے اور جس نے اسے نہیں کھایا، اس پر بھی اس کا غبار پڑ کر رہے گا\"۔","الألباني: ضعيف",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’لوگوں پر ایسا وقت آئے گا کہ عموماً لوگ سود خور ہوں گے۔ جو شخص براہ راست سود خور نہ ہو گا، اسے سود کا غبار تو ضرور پہنچے گا۔‘‘"}],[4456,"عمرو بن تغلب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قیامت کی نشانیوں میں سے ایک نشانی یہ ہے کہ مال و دولت کا پھیلاؤ ہو جائے گا اور بہت زیادہ ہو جائے گا، تجارت کو ترقی ہو گی، علم اٹھ جائے گا ۱؎، ایک شخص مال بیچے گا، پھر کہے گا: نہیں، جب تک میں فلاں گھرانے کے سوداگر سے مشورہ نہ کر لوں، اور ایک بڑی آبادی میں کاتبوں کی تلاش ہو گی لیکن وہ نہیں ملیں گے\" ۲؎۔\n§وضاحت\n۱؎: اکثر نسخوں میں «يظهر العلم» ہے، اور بعض نسخوں میں «يظهر الجهل» ہے، یعنی لوگوں کے دنیاوی امور و معاملات میں مشغول ہونے کے سبب جہالت پھیل جائے گی، اور دوسری احادیث کے سیاق کو دیکھتے ہوئے «يظهر العلم» کا معنی یہاں \" علم کے اٹھ جانے یا ختم ہو جانے کے ہوں گے \"، واللہ اعلم۔ ۲؎: یعنی ایسے کاتبوں کی تلاش جو عدل و انصاف سے کام لیں اور ناحق کسی کا مال لینے کی ان کے اندر حرص و لالچ نہ ہو۔","الألباني: صحيح",{"u2":"حضرت عمرو بن تغلب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بے شک یہ بھی قیامت کی نشانیاں ہیں کہ مال عام اور بہت زیادہ ہو جائے گا۔ تجارت پھیل جائے گی۔ علم (دیکھنے میں) عام ہو گا (مگر) آدمی کوئی سودا کرے گا تو کہے گا: میں سودا پکا نہیں کرتا حتی کہ میں فلاں قبیلے کے تاجر سے مشورہ کر لوں۔ اور ایک بہت بڑے قبیلے میں کاتب تلاش کیا جائے گا تو نہیں ملے گا۔‘‘","f2":"(۱) ترجمۃ الباب کا مقصد تجارت اور سوداگری کی بابت فرامینِ رسول بیان کرنا ہے اور باب کے ساتھ حدیث کی مناسبت اس طرح بنتی ہے کہ اس میں تجارت کے عام ہونے اور علاماتِ قیامت میں سے ہونے کا ذکر ہے۔ (۲) کثرتِ مال قیامت کی نشانیوں میں سے ایک نشانی ہے۔ مال، انسان کے لیے خیر بھی ہو سکتا ہے اور شر بھی، تاہم دوسرا امکان بہت زیادہ ہے۔ اور یہ اس لیے کہ عام انسانوں کے انداز تجارت اور مال کمانے سے بخوبی یہ معلوم ہوتا ہے کہ انہیں صرف مال کمانے کی فکر ہے، اور وہ آخرت کی فکر سے بالکل عاری اور غافل ہو چکے ہیں۔ ہاں، البتہ جسے اللہ توفیق عطا فرمائے تو وہ اپنے مال کے ذریعے سے جنت ہی خریدتا ہے۔ اللہم اجعلنا منہم۔ (۳) یہ حدیث مبارکہ اس بات پر بھی دلالت کرتی ہے کہ دنیوی علم کا ظہور اور امت مسلمہ میں اس کا پھیلائو علاماتِ قیامت میں سے ہے۔ اور اس میں بھی امت کے لیے کوئی زیادہ خیر اور بھلائی نہیں الا یہ کہ افراد امت اس کے ساتھ ساتھ شرعی علم حاصل کریں اور وہ احکام شریعت سے، کما حقہٗ آگاہ ہوں، لیکن عام مشاہدہ اس کے برعکس ہی ہے، تاہم جو شخص علم دین حاصل کرنے کے ساتھ ساتھ عصری تعلیم بھی، صحیح طور پر حاصل کرتا ہے تو یہ سونے پہ سہاگا ہے اور یہ بہت زیادہ خیر و بھلائی والا عمل ہے۔ (۴) یہ حدیث مبارکہ رسول اللہ صلی اللہ علیہ وسلم کی نبوت کا کھلم کھلا اور صریح معجزہ ہے کہ آپ نے بہت عرصہ پہلے جن امور کی خبر دی تھی، وہ من و عن اسی طرح وقوع پذیر ہوئے جس طرح آپ نے بیان فرمایا تھا۔ (۵) ’’علم ہو گا‘‘ بعض نسخوں میں علم کی بجائے جہالت کا لفظ ہے اور وہ آئندہ کلام سے زیادہ مناسبت رکھتا ہے کہ اس قدر جہالت ہو گی کہ سوجھ بوجھ رکھنے والا اور دستاویز لکھنے والا خال خال ہی ملے گا۔ اگر یہاں لفظ علم ہی ہو تو پھر مناسبت یوں ہو گی کہ دیکھنے میں تو علم بہت ہو گا مگر لیاقت نہیں ہو گی حتی کہ نہ تجارت کی سوجھ بوجھ ہو گی نہ دستاویز لکھنا آئے گی۔ آج کل بھی کچھ ایسی ہی صورت حال پیدا ہو چکی ہے کہ سکول عام ہیں، استاد بھی بہت ہیں مگر نہ اساتذہ خلوص سے پڑھاتے ہیں نہ طلبہ محنت سے پڑھتے ہیں۔ نتیجہ یہ ہے کہ پڑھے لکھے جاہل بڑھ رہے ہیں۔"}],[4457,"حکیم بن حزام رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیچنے اور خریدنے والے دونوں کو جدا ہونے تک (مال کے بیچنے اور نہ بیچنے کے بارے میں) اختیار حاصل ہے، اگر سچ بولیں گے اور (عیب و ہنر کو) صاف صاف بیان کر دیں گے تو ان کی خرید و فروخت میں برکت ہو گی، اور اگر جھوٹ بولیں گے اور عیب کو چھپائیں گے تو ان کی خرید و فروخت کی برکت جاتی رہے گی\" ۱؎۔\n§وضاحت\n۱؎: یعنی: تجار کو اپنی خرید و فروخت کے معاملے میں جھوٹ سے بچنا چاہیئے، تبھی تجارت میں برکت ہو گی۔","الألباني: صحيح",{"u2":"حضرت حکیم بن حزام رضی اللہ عنہ سے رویات ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دو خرید و فروخت کرنے والے جبب تک ایک دوسرے سے جدا نہ ہوں، انہیں سودا ختم کرنے کا اختیار رہتا ہے۔ اگر وہ دونوں سچ بولیں اور ہر بات وضاحت سے بیان کر دیں تو ان کے سودے میں برکت ہو گی۔ اور اگر وہ جھوٹ بولیں اور صورت حال چھپا لیں تو ان کے سودے سے برکت اٹھ جائے گی۔‘‘","f2":"(۱) امام نسائی رحمہ اللہ نے جو باب قائم کیا ہے اس کا مقصد یہ ہے کہ تاجروں کے لیے ضروری ہے کہ وہ خرید و فروخت کرتے وقت شرعی تقاضوں کا لحاظ رکھتے ہوئے اپنے معاملات طے کریں۔ ایک دوسرے سے نہ تو جھوٹ بولیں اور نہ ایک دوسرے کو دھوکا دینے کی کوشش کریں بلکہ سچ کا دامن تھامے رکھیں اور ہر صورت میں سچی بات کریں اور سچ پر پہرہ دیتے رہیں۔ بائع اور مشتری دونوں کی یہ شرعی اور اخلاقی ذمہ داری ہے کہ وہ ایک دوسرے کی خیر خواہی کریں۔ بائع پر واجب ہے کہ وہ اپنی مبیع (جو چیز وہ بیچ رہا ہیض کے متعلق درست معلومات دے۔ اگر اس میں کوئی نقص اور عیب وغیرہ ہو تو خریدار کو اس سے مطلع کرے۔ دائو نہ لگائے۔ ایک مسلمان تاجر کے لیے قطعاً جائز نہیں کہ وہ عیب اور نقص والی یا دو نمبر چیز، بتائے بغیر فروخت کرے۔ یہ حرام ہے۔ (۲) حدیث مبارکہ سے یہ بات بھی معلوم ہوتی ہے کہ برکت تب ہو گی جب تجارت سچ پر مبنی ہو گی، اس لیے ضروری ہے کہ حصول برکت کے لیے تاجر لوگ سچ بول کر ہی اپنی تجارت کو فروغ دیں۔ تجارت میں جھوٹ بولنے اور سودے کا عیب چھپانے سے نہ صرف برکت حاصل نہیں ہوتی بلکہ الٹا نقصان ہوتا ہے۔ اور اس کے علاوہ ضمیر کی خلش الگ بے چین کرتی رہتی ہے۔ اعاذنا اللہ منہ۔ (۳) اس حدیث سے یہ مسئلہ بھی ثابت ہوتا ہے کہ دنیوی فوائد کا حقیقی اور بھرپور حصول بھی عمل صالح سے ہوتا ہے جبکہ گناہوں کی نحوست اور دنیا و آخرت، دونوں کی خیر و برکت تباہ و برباد ہو جاتی ہے، اس لیے اس زریں قانون فطرت کو ہمیشہ مدنظر رکھ کر اپنے تمام معاملات ترتیب دینے چاہئیں۔ (۴) ’’اختیار رہتا ہے‘‘ اسے خیار مجلس کہا جاتا ہے، یعنی جب تک فریقین سودے والی جگہ میں بیٹھے ہیں، وہ چاہیں تو ان میں سے کوئی بھی سودا واپس کرنے کا مطالبہ کر سکتا ہے۔ فریق ثانی کے لیے اسے ماننا لازم ہو گا، البتہ اگر مجلس بدل جائے تو پھر دونوں کی رضامندی ہی سے سودا واپس ہو سکتا ہے۔ احناف و موالک خیار مجلس کے قائل نہیں کہ خیار مجلس کی کوئی حد نہیں، نیز یہ اختیار اصول کے خلاف ہے کیونکہ طے شدہ سودے کو ایک فریق ختم نہیں کر سکتا۔ اس حدیث کی وہ تاویل کرتے ہیں کہ یہاں ’’جدا ہونے‘‘ سے مراد سودے کی بات چیت کا طے ہونا ہے، حالانکہ یہ بات بیان کرنے کی تو ضرورت ہی نہیں۔ یہ تو بدیہی بات ہے، نیز اس حدیث کو روایت کرنے والے صحابہ نے اسے ظاہری معنی پر ہی محمول کیا ہے۔ بعض دیگر احادیث میں صراحت ہے کہ واپسی کے ڈر سے کوئی جگہ نہ بدلے۔ گویا یہ معنی قطعی ہے کہ جب تک مجلس نہ بدلے، اختایر قائم رہتا ہے۔ باقی رہی اصول کی بات تو اصول بھی احادیث ہی سے ثابت ہوتے ہیں، نیز حدیث بھی تو اصول شرع میں سے ایک بنیادی اصل ہے، لہٰذا اصول کا نام لے کر کسی صحیح اور صریح حدیث کو رد نہیں کیا جا سکتا۔ (۵) ’’وضاحت سے بیان کریں‘‘ یعنی اپنی اپنی چیز کے عیوب و نقائص وغیرہ۔ (۶) ’’برکت اٹھ جائے گی‘‘ یعنی مال حرام ہو جائے گا اور کثیر ہونے کے باوجود ضروریات پوری نہیں کرے گا اور ضائع ہوتا رہے گا۔ پریشانی الگ ہو گی۔"}],[4458,"ابوذر رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تین لوگ ہیں جن سے اللہ تعالی قیامت کے دن نہ بات چیت کرے گا، اور نہ ان کی طرف دیکھے گا اور نہ ہی انہیں گناہوں سے پاک کرے گا اور ان کے لیے درد ناک عذاب ہو گا\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے آیت پڑھی ۱؎ تو ابوذر رضی اللہ عنہ نے کہا: وہ لوگ ناکام ہو گئے اور خسارے میں پڑ گئے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے تہبند کو ٹخنے سے نیچے لٹکانے والا ۲؎، جھوٹی قسم کھا کر اپنے سامان کو بیچنے والا، دے کر باربار احسان جتانے والا\"۔\n§وضاحت\n۱؎: اس آیت سے مراد سورۃ آل عمران کی آیت نمبر ۷۷ ہے جو اس طرح ہے «ولا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم» :(سورة آل عمران: 77 )۔ ۲؎: کسی کسی روایت میں «خیلاء» کا لفظ آیا ہے یعنی \" تکبر اور گھمنڈ سے ٹخنے سے نیچے ازار :(تہبند ) لٹکانے والا \" لیکن یہ وعید ہر حالت پر ہے چاہے ازار :(تہبند ) تکبر سے لٹکائے یا بغیر تکبر کے اور \" تکبر سے \" کا لفظ کوئی احترازی لفظ نہیں ہے، ٹخنے سے نیچے لٹکانے میں بہرحال تکبر و غرور کی کیفیت پیدا ہو ہی جاتی ہے اس لیے کسی روایت میں «خیلاء» کا لفظ آیا ہے۔ تکبر کے ساتھ مزید گناہ ہو گا اور عام حالت میں یہ کبیرہ گناہ ہے۔","الألباني: صحيح",{"u2":"حضرت ابو ذر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’تین شخص ایسے ہیں جن سے اللہ تعالیٰ قیامت کے دن نہ کلام کرے گا، نہ انہیں دیکھے گا اور نہ انہیں پاک کرے گا اور ان کے لیے دردناک عذاب ہو گا۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے یہ (مذکورہ) جملے ارشاد فرمائے تو حضرت ابوذر رضی اللہ عنہ نے کہا: وہ تو ناکام ہو گئے اور خسارے میں رہے۔ آپ نے فرمایا: ’’جو شخص اپنا تہ بند (زمین پر یا اپنے ٹخنوں سے نیچے) لٹکاتا ہے، جو شخص اپنا سامان جھوٹی قسم کھا کر بیچتا ہے اور جو شخص اپنے عطیے کا حسان جتلاتا ہے۔‘‘","f2":"(۱) مؤلف رحمہ اللہ نے جو عنوان قائم کیا ہے اس کا مقصد جھوٹ بول کر سودا بیچنے کی قباحت و شناعت بیان کرنے کے ساتھ ساتھ اس کے خطرناک نتائج سے آگاہ کرنا بھی ہے۔ (۲) اس حدیث مبارکہ سے اللہ تعالیٰ کی کئی ایک صفات معلوم ہوتی ہیں، مثلاً: کلام کرنا، دیکھنا اور تزکیہ کرنا وغیرہ۔ لین یہ بات ہمیشہ یاد رہے کہ اللہ تعالیٰ کی تمام صفات، اس کی ذات ہی کے شایانِ شان ہیں۔ مخلوق میں پائی جانے والی صفات کے مشابہ ہرگز ہرگز نہیں جیسا کہ ایک گمراہ فرقے مُشَبِّہَہْ کا عقیدہ ہے، نیز اس سے دیگر گمراہ فرقوں مُعَطِّلَہْ اور مُمَثِّلَہْ وغیرہ کا بھی مکمل طور پر رد ہوتا ہے جو اللہ تعالیٰ کی صفات کے منکر ہیں یا وہ اس کی صفات تو مانتے ہیں لیکن انہیں مخلوق کی صفات جیسا قرار دیتے ہیں۔ (۳) یہ حدیث دلالت کرتی ہے کہ اللہ تعالیٰ، قیامت کے دن اپنے مومن بندوں پر نظر کرم فرمائے گا۔ وہ انہیں محبت بھری نظر سے دیکھے گا، ان کا تزکیہ کرے گا اور نہیں عذاب سے بھی نجات عطا فرمائے گا۔ (۴) شلوار، تہ بن، پینٹ اور پائجامہ وغیرہ ٹخنوں سے نیچے لٹکانا، مردوں کے لیے بالکل حرام ہے۔ اور یہ سنگین جرم ہے۔ بعض لوگ جب نماز کے لیے مسجدوں میں آتے ہیں تو اس وقت ٹخنے ننگے کر لیتے ہیں اور نماز کے بعد پھر اسی پہلی حالت میں آ جاتے ہیں۔ یہ دو رنگی ہے۔ (۵) جھوٹی قسم کھا کر سودا بیچنا، تہ بند ٹخنوں سے نیچے لٹکانا نیز کسی کے ساتھ نیکی اور احسان کر کے جتلانا کبیرہ گناہ ہیں۔ اسی لیے رسول اللہ صلی اللہ علیہ وسلم نے ان گناہوں کا ارتکاب کرنے والوں کے لیے حدیث میں مذکور شدید وعید بیان فرمائی ہے۔ اعاذنا اللہ منہ۔ (۶) ’’نہ کلام کرے گا‘‘ یعنی محبت اور پیار سے باتیں نہیں کرے گا۔ رحمت و شفقت کی نظر سے نہیں دیکھے گا اور انہیں گناہوں کی معافی دے کر پاک نہیں کرے گا۔ مقصود ان باتوں کا یہ ہے کہ اللہ تعالیٰ ان سے ناراض اور غضب ناک رہے گا۔ غصے کی جھڑک اور ڈانٹ کو عرف عام میں کلام کرنا نہیں کہتے۔ اسی طرح غصے اور غضب کی نظر سے دیکھنے کو دیکھنا نہیں کہتے۔ (۷) ’’تہ بند لٹکاتا ہے‘‘ ایک دوسری روایت میں ہے جو شخص تکبر سے اپنا ازار زمین پر گھسیٹتا پھرتا ہے۔ ایک حدی ثمیں ٹخنے سے نیچے کپڑا لٹکانے کو تکبر کہا گیا ہے۔ ہاں اگر باوجود اہتمام اور خیال رکھنے کے بھی کبھی کبھار کپڑا ٹخنوں سے نیچے چلا جاتا ہے تو مذکورہ بالا وعید، ان شاء اللہ، اس پر صادق نہیں آتی۔"}],[4459,"ابوذر رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تین لوگ ہیں جن کی طرف اللہ تعالی قیامت کے دن نہیں دیکھے گا، اور نہ انہیں گناہوں سے پاک کرے گا، اور ان کے لیے درد ناک عذاب ہے: وہ شخص جو کوئی بھی چیز دیتا ہے تو احسان جتاتا ہے، جو غرور اور گھمنڈ سے تہبند لٹکاتا ہے اور جو جھوٹ بول کر اپنا سامان بیچتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوذر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تین شخص ایسے ہیں کہ اللہ تعالیٰ قیامت کے دن ان کو (نظر رحمت و محبت سے) نہیں دیکھے گا، اور نہ ان کو پاک کرے گا اور ان ے لیے تکلیف دہ عذاب ہو گا۔ وہ شخص جو اپنے عطیے پر احسان جتلاتا ہے۔ جو شخص اپنا تہ بند لٹکاتا ہے اور جو شخص جھوٹ بول کر اپنا سامان بیچتا ہے۔‘‘"}],[4460,"ابوقتادہ انصاری رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"تم لوگ خرید و فروخت میں کثرت سے قسم کھانے سے بچو، اس لیے کہ (قسم کھانے سے) سامان تو بک جاتا ہے، لیکن برکت ختم جاتی رہتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو قتادہ انصاری رضی اللہ عنہ سے مروی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’سودا کرتے وقت زیادہ قسمیں نہ کھایا کرو کیونکہ (جھوٹی) قسم سے سامان تو بک جاتا ہے مگر برکت اٹھ جاتی ہے‘‘"}],[4461,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"قسم کھانے سے سامان بک تو جاتا ہے، لیکن کمائی (کی برکت) ختم ہو جاتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’قسم اٹھانے سے سامان تو فروخت ہو جاتا ہے مگر کمائی (کی برکت) ختم ہو جاتی ہے۔‘‘","f2":"سامان بیچنے کے لیے جھوٹی قسم تو ایک طرف رہی، سچی قسمیں بھی نہیں کھانی چاہئیں کیونکہ جب قسم کھانے کی عادت بن جائے تو سچ جھوٹ کا امتیاز نہیں رہتا، نیز اس طرح اللہ تعالیٰ کے نام کی حرمت ختم ہو جاتی ہے۔ قسم اسی وقت کھائی جائے جب اس کے بغیر چارہ نہ رہے۔ برکت اٹھ جانے کا مفہوم دیکھئے حدیث نمبر: ۴۴۶۲ میں۔"}],[4462,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تین لوگ ہیں قیامت کے دن اللہ ان کی طرف نہیں دیکھے گا اور نہ انہیں گناہوں سے پاک کرے گا، ان کے لیے درد ناک عذاب ہے: ایک شخص وہ ہے جو راستے میں فاضل پانی کا مالک ہو اور مسافر کو دینے سے منع کرے، ایک وہ شخص جو دنیا کی خاطر کسی امام (خلیفہ) کے ہاتھ پر بیعت کرے، اگر وہ اس کا مطالبہ پورا کر دے تو عہد بیعت کو پورا کرے اور مطالبہ پورا نہ کرے تو عہد بیعت کو پورا نہ کرے، ایک وہ شخص جو عصر بعد کسی شخص سے کسی سامان پر مول تول کرے اور اس کے لیے اللہ کی قسم کھائے کہ یہ اتنے اتنے میں لیا گیا تھا تو دوسرا (یعنی خریدنے والا) اسے سچا جانے (حالانکہ اس نے اس سے کم قیمت میں خریدی تھی) ۱؎۔\n§وضاحت\n۱؎: اس حدیث سے عصر کے بعد کے وقت خرید و فروخت میں جھوٹی قسم کھانے پر وعید ہے، اس سے جہاں یہ حکم ثابت ہوا وہیں پر عصر کے بعد کی فضیلت ثابت ہوئی، اس وقت رب کی مرضی کے خلاف اس طرح کا اقدام جس میں اللہ تعالی کی عظمت و تقدیس کا سہارا لے کر آدمی دنیاوی ترقی کا خواہش معیوب ہے، جب کہ جھوٹ بول کر اور جھوٹی گواہی کے ذریعہ مقاصد حاصل کرنا ہر وقت معیوب اور غلط ہے، عصر بعد مزید شناعت و برائی ہے، شاید یہ وقت بازار کی بھیڑ اور اس میں لوگوں کے ریل پیل کا ہوتا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تین شخص ایسے ہیں کہ اللہ تعالیٰ قیامت کے دن ان سے کلام نہیں فرمائے گا، نہ ان کو دیکھے گا اور نہ ان کو پاک ہی کرے گا۔ اور ان کے لیے دردناک عذاب ہو گا۔ ایک وہ آدمی جس کے ہاں گزرگاہ کے پاس (اس کی ضرورت سے) فالتو پانی ہے لیکن وہ مسافر کو پانی لینے سے روک دے۔ دوسرا وہ آدمی جو صرف دنیوی مفاد کی خاطر کسی امام سے بیعت کرتا ہے۔ اگر امام اس کو اس کی منشا کے مطابق دیتا رہے تو وہ بیعت قر قائم رہتا ہے اور اگر نہ دے تو توڑ دیتا ہے۔ تیسرا وہ شخص جو کسی آدمی سے عصر کے بعد سامان کا بھائو کرتا ہے اور اللہ کی قسم کھا کر کہتا ہے کہ اس سامان کے بدلے اسے اس قدر رقم ملتی تھی (حالانکہ اسے اتنی رقم نہیں ملتی تھی) دوسرا اس کی تصدیق کر دیتا ہے (اور سامان خرید لیتا ہے)۔‘‘","f2":"(۱) اس حدیث مبارکہ میں اس شخص کی بابت سخت ترین وعیدہ ہے جو محض ذاتی مفاد کی خاطر حاکم وقت کی مخالفت کرتا ہے، اس کے ساتھ کی ہوئی بیعت توڑتا اور اس کے خلاف خروج وغیرہ کرتا ہے۔ اس جرم کے مرتکب کے لیی اس قدر شدید وعید کیوں ہے؟ یہ اس لیے ہے کہ امام وقت کی مخالفت کرنے کی وجہ سے مسلمانوں کا اتفاق پارا پارا ہو جائے گا اور امت میں شر، فساد اور ظلم پھیلے گا۔ یہ یاد رہے کہ وفائے عہد میں عزت و عفت، مال اور خون، سب چیزوں کی حفاظت شامل ہے۔ (۲) ہر وہ عمل جس سے اللہ کا قرب حاصل کیا جاتا ہے اگر اس سے مقصود اللہ تعالیٰ کی رضا کا حصول نہ ہو بلکہ اس سے صرف دنیوی فائدے کا حصول مطلوب ہو، تو وہ انسان کے لیے وبال اور اس کی آخرت کی تباہی و بربادی کا سبب ہوتا ہے۔ اَعَاذَنَا اللّٰہُ مِنْہُ۔ (۳) ’’تین شخص‘‘ حدیث میں جن تین اشخاص کا ذکر ہے، حدیث نمبر: ۴۴۶۳ میں ان میں سے صری ایک شخص کا ذکر ہے۔ اس طرح مجموعی طور پر پانچ شخص بن گئے۔ گویا تین کا لفظ حصر کے لیے نہیں بلکہ یادداشت کے لیے ہے۔ ویسے بھی تین میں زائد کی نفی نہیں۔ احادیث میں کئی مقامات پر ایسے ہے۔ اسے اختلاف پر محمول نہیں کرنا چاہیے بلکہ جو آپ کے ذہن میں تھے یا جن کو آپ نے موقع محل کے مناسب سمجھا، ذکر فرما دیا۔ اس سے باقی کی نفی نہیں ہو گی۔ (۴) ’دپانی سے روک دے‘‘ پانی زندگی کی بقا کے لیے اشد ضروری چیز ہے۔ اس کے نہ ملنے سے موت بھی واقع ہو سکتی ہے، نیز یہ اللہ تعالیٰ نے مفت مہیا کیا ہے، لہٰذا زائد پانی روکنے کا کوئی جواز نہیں، البتہ اگر اپنی ضرورت سے زائد نہ ہو تو روکا جا سکتا ہے لیکن پینے سے نہیں روکا جا سکتا الا یہ کہ اپنے پینے کے لیے رکھا گیا ہو۔ (۵) ’’عصر کے بعد‘‘ ممکن ہے یہ قید اتفاقی ہو کیونکہ عصر کے بعد خرید و فروخت زیادہ ہوتی ہے اور ہو سکتا ہے، یہ قید قصداً ذکر کی گئی ہو کیونکہ عصر دن کا آخر وقت ہے جو انسان کو موت اور قیامت کی یاد دلاتا ہے۔ اس لحاظ سے یہ توبہ و استغفار کا وقت ہے۔ ایسے وقت میں جھوٹی قسمیں کھانا انتہائی قبیح کام ہے۔"}],[4463,"قیس بن ابی غرزہ رضی اللہ عنہ کہتے ہیں کہ ہم مدینے میں (غلوں سے بھرے) وسق خریدتے اور بیچتے تھے، اور ہم اپنا نام «سمسار» (دلال) رکھتے تھے، لوگ بھی ہمیں اسی نام سے پکارتے تھے، ایک دن رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس نکل کر آئے اور ہمارا ایسا نام رکھا جو ہمارے رکھے ہوئے نام سے بہتر تھا، اور فرمایا: \"اے تاجروں کی جماعت! تمہاری خرید و فروخت میں قسم اور لغو باتیں آ جاتی ہیں، لہٰذا تم اس میں صدقہ کو ملا دیا کرو\" ۱؎۔\n§وضاحت\n۱؎: خرید و فروخت کے وقت زبان سے «لا واللہ» اور «بلی واللہ»، اللہ کی قسم، قسم اللہ کی ایمان سے وغیرہ وغیرہ جیسے قسمیہ الفاظ جو نکل جاتے ہیں ان کا شمار یمین لغو :(بیکار قسم ) میں ہوتا ہے، ان کا کفارہ صدقہ کرنا ہے۔","الألباني: صحيح",{"u2":"حضرت قیس بن ابی غرزہ رضی اللہ عنہ سے روایت ہے کہ ہم مدینہ منورہ میں غلے وغیرہ کی خرید و فروخت کیا کرتے تھے اور ہم اپنے آپ کو سمسار کہا کرتے تھے۔ لوگ بھی ہمیں اسی لفظ سے موسوم کرتے تھے حتی کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم ہمارے ہاں (بازار میں) تشریف لائے اور ہمیں ایسے نام سے پکارا جو ہمارے رکھے ہوئے نام سے بدرجہا بہتر تھا: آپ نے فرمایا: ’’اے تاجروں کی جماعت! تمہارے سودوں میں بلاقصد قسمیں اور فضول باتیں واقع ہوتی رہتی ہیں، لہٰذا تم صدقہ کیا کرو۔‘‘"}],[4464,"حکیم بن حزام رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خریدنے اور بیچنے والے جب تک جدا نہ ہو جائیں دونوں کو اختیار رہتا ہے ۱؎، اگر وہ عیب بیان کر دیں اور سچ بولیں تو ان کی خرید و فروخت میں برکت ہو گی، اور اگر وہ جھوٹ بولیں اور عیب چھپائیں تو ان کی بیع کی برکت ختم ہو جاتی ہے\"۔\n§وضاحت\n۱؎: یعنی: بیع کو فسخ :(کالعدم ) کر دینے کا اختیار دونوں فریق کو صرف اسی مجلس تک ہوتا ہے جس مجلس میں بیع کا معاملہ طے ہوا ہو، مجلس ختم ہو جانے کے بعد دونوں کا اختیار ختم ہو جاتا ہے اب معاملہ فریق ثانی کی رضا مندی پر ہو گا اگر وہ راضی نہ ہوا تو بیع نافذ رہے گی۔ الا یہ کہ معاملہ کے اندر کسی اور وقت تک کی شرط رکھی گئی ہو۔ تو اس وقت تک اختیار باقی رہے گا :(دیکھئیے اگلی حدیث )۔","الألباني: صحيح",{"u2":"حضرت حکیم بن حزام رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’خرید و فروخت کرنے والے دو شخص جدا ہونے سے پہلے بیع کی واپسی کا اختیار رکھتے ہیں۔ اگر وہ ہر بات واضح بیان کر دیں اور سچ بولیں تو ان کی بیع میں برکت ہو گی۔ اور اگر وہ جھوٹ بولیں اور صورت حال کو چھپائیں تو ان کی بیع سے برکت اٹھ جائے گی۔‘‘","f2":"تفصیل کے لیے دیکھئے، حدیث: ۴۴۶۲۔"}],[4465,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خریدنے اور بیچنے والا جب تک الگ الگ نہ ہو جائیں دونوں کو اپنے ساتھی پر اختیار رہتا ہے، سوائے اس بیع کے جس میں اختیار کی شرط ہو\" ۱؎۔\n§وضاحت\n۱؎: یعنی: وہ معاملہ جس میں طرفین سے یہ طے ہو کہ فلان تاریخ تک یا اتنے دن تک معاملہ کو ختم کرنے کا اختیار رہے گا، اس معاملہ میں مقررہ مدت تک حق اختیار اور حاصل رہے گا، باقی دیگر معاملات میں صرف معاملہ کی مجلس ختم ہونے تک اختیار رہے گا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’خرید و فروخت کرنے والے دو اشخاص میں سے ہر ایک کو اختیار ہوتا ہے کہ وہ جدا ہونے سے قبل سودا واپس کرے، البتہ بیع خیار میں ایسے نہیں ہوتا۔‘‘","f2":"(۱) اس حدیث مبارکہ سے خرید و فروخت کرنے والوں کے اختیار کا مسئلہ ثابت ہوتا ہے کہ بائع اور مشتری، دونوں کو اس وقت تک سودا کرنے یا نہ کرنے کا حاصل ہے جب تک کہ وہ اس مجلس سے الگ نہ ہو جائیں۔ جب وہ ایک دوسرے سے الگ ہو جائیں تو اختیار ختم ہو جائے گا، تاہم اگر وہ کچھ وقت تک ایک دوسرے کو سوچنے سمجھنے اور سودا کرنے یا نہ کرنے کا اختیار دے دیں تو پھر مقررہ وقت تک اختیار باقی رہے گا۔ وہ وقت گزر جانے کے بعد سودا پکا ہو جائے گا اور اختیار بھی ختم ہو جائے گا۔ (۲) اس حدیث سے بیع خیار کا، یعنی ایک دوسرے کو یا کسی ایک کا دوسرے کو اختیار دینے کا جواز ثابت ہوتا ہے۔ (۳) بیع خیار سے مراد وہ بیع ہے جس میں دونوں میں سے ہر ایک نے بیع کرتے وقت واپسی کا اختیار ختم کر دیا ہو اور کہہ دیا ہو کہ اگر واپس کنا ہے تو ابھی کر لو ورنہ واپسی نہیں ہو گی۔ ایسی صورت میں مجلس بیع قائم رہنے کے باوجود اختیار نہیں رہے گا۔ بیع خیار کے ایک دوسرے معنی بھی ہیں: وہ بیع جس میں زیادہ مدت (مثلاً: تین دن وغیرہ) تک واپسی کا اختیار رکھ لیا گیا ہو تو ایسی بیع میں مجلس برخاست ہونے کے باوجود مقررہ وقت تک واپسی کا اختیار رہے گا۔ دونوں مفہوم صحیح ہیں۔"}],[4466,"عبداللہ بن عمر رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خرید و فروخت کرنے والوں کو اس وقت تک اختیار رہتا ہے جب تک وہ الگ الگ نہ ہوں، یا پھر اختیار کی شرط ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’خرید و فروخت کرنے والے دو اشخاص جب تک جدا نہ ہوں، واپسی کا اختیار رکھتے ہیں الا یہ کہ بیع خیار ہو۔‘‘"}],[4467,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خرید و فروخت کرنے والوں کو اس وقت تک اختیار رہتا ہے جب تک وہ الگ نہ ہوں، سوائے اس کے کہ بیع اختیار کی شرط کے ساتھ ہوئی ہو، لہٰذا اگر بیع اختیار کی شرط کے ساتھ ہوئی ہے تو بیع ہو جاتی ہے\" (البتہ اختیار باقی رہتا ہے)۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دو سودا کرنے والے جب تک جدا نہ ہوں، واپسی کا اختایر رکھتے ہیں الا یہ کہ وہ سودا خیار والا ہو۔ اگر وسدے میں اختیار ختم کر دیا گیا ہو تو بیع پکی ہو گئی۔ (اب واپسی کا اختیار نہیں رہے گا، خواہ مجلس قائم بھی ہو)۔‘‘"}],[4468,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب دو آدمی بیع کریں تو ان میں سے ہر ایک کو اپنی بیع کا اس وقت تک اختیار رہتا ہے جب تک وہ دونوں الگ تھلگ نہ ہوں، یا پھر ان کی بیع میں اختیار کی شرط ہو، تو اگر بیع میں شرط اختیار ہو تو بیع ہو جاتی ہے (لیکن حق اختیار باقی رہتا ہے)\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب دو شخص سودا کریں تو ان میں سے ہر ایک کو اپنی بیع کی واپسی کے بارے میں ایک دوسرے کے جدا ہونے تک اختیار حاصل ہے۔ یا ان کی بیع میں اختیار ختم کر دیا گیا ہو۔ اگر ایسی بات ہے تو بیع پکی ہو گئی۔ (اب واپسی نہیں ہو گی)۔‘‘"}],[4469,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیع کرنے والے دونوں کو اس وقت تک اختیار رہتا ہے جب تک وہ الگ تھلگ نہ ہوں، یا پھر ان میں سے ایک دوسرے سے کہے کہ اختیار کی شرط کر لو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سودا کرنے والے دو شخص واپسی کا اختیار رکھتے ہیں جب تک وہ ایک دوسرے سے جدا نہ ہوں، یا پھر ان میں سے ایک دوسرے کو بیع کے دوران ہی میں کہہ دے کہ اب پسند کر لو۔ (بعد میں واپسی نہیں ہو گی۔ ایسی صورت میں اختیار نہیں رہے گا)۔‘‘"}],[4470,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیع کرنے والے دونوں کو اختیار رہتا ہے جب تک الگ تھلگ نہ ہوں، یا پھر وہ اختیاری خرید و فروخت ہو\"۔ نافع کی بعض روایتوں میں یوں ہے «أو يقول أحدهما للآخر اختر» \"یا ان میں سے ایک دوسرے سے یہ کہے: بیع میں اختیار کی شرط کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بیع کرنے والے دو افراد ایک دوسرے سے جدا ہونے تک بیع کی واپسی کا اختیار رکھتے ہیں الا یہ کہ وہ بیع خیار ہو‘‘ اور کبھی نافع نے کہا (آپ نے فرمایا تھا): ’’یا ان میں سے ایک دوسرے کو (بیع کرتے وقت) کہہ دے: اب پسند کر لے (بعد میں واپسی نہیں ہو گی)۔‘‘\nحضرت ابن عمر رضی اللہ عنہ سے بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سودا کرنے والے دو شخص ایک دوسرے سے جدا ہونے تک سودے کی واپسی کا اختیار رکھتے ہیں الا یہ کہ وہ اختیار والا سودا ہو۔‘‘ اور کبھی نافع نے کہا (آپ نے فرمایا تھا): ’’یا (سودا کرتے وقت) ایک نے دوسرے سے کہہ دیا ہو: ابھی پسند کر لے۔‘‘"}],[4471,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیع کرنے والے دونوں اختیار کے ساتھ رہتے ہیں یہاں تک کہ وہ الگ تھلگ ہو جائیں، یا بیع خیار (اختیاری بیع) کے ساتھ ہو\"۔ کبھی کبھی نافع نے یوں کہا: \" «أو يقول أحدهما للآخر اختر» یا یہ کہ ان میں سے ایک دوسرے سے کہے: بیع بالخیار کرو\"۔","الألباني: صحيح"],[4472,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب دو آدمی آپس میں خریدیں اور بیچیں تو ان میں سے ہر ایک کو اس وقت تک اختیار ہوتا ہے جب تک وہ جدا نہ ہوں، اور ایک دوسری بار نافع نے :(«حتى يفترقا» کے بجائے) «ما لم يتفرقا» کہا، حالانکہ وہ دونوں ایک جگہ تھے، یا یہ کہ ان میں سے ایک دوسرے کو اختیار دیدے، لہٰذا اگر ان میں سے ایک دوسرے کو اختیار دیدے اور وہ دونوں اس (شرط خیار) پر بیع کر لیں تو بیع ہو جائے گی، اب اگر وہ دونوں بیع کرنے کے بعد جدا ہو جائیں اور ان میں سے کسی ایک نے بیع ترک نہ کی تو بیع ہو جائے گی۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب دو شخص سودا کریں تو ان میں سے ہر ایک کو واپسی کا اختیار رہتا ہے حتی کہ وہ ایک دوسرے سے جدا ہوں۔‘‘ ایک اور مرتبہ (نافع نے ان الفاظ سے) بیان کیا کہ (آپ نے فرمایا: ’’ان دونوں کو اختیار ہے) جب تک وہ دونوں جدا نہ ہوں اور اکٹھے رہیں الا یہ کہ ان میں سے کوئی ایک، دوسرے کو (بیع کے وقت ہی) اختیار دے دے۔ اگر بیع کے وقت ہی ان دونوں میں سے ایک، دوسرے کو اختیار دے دے اور وہ دونوں اس پر سودا کر لیں تو بیع پکی ہو گئی۔ اور اگر سودا کرنے کے بعد وہ ایک دوسرے سے جدا ہو جائیں اور اس وقت تک کسی نے بیع واپس نہیں کی تو بیع پکی ہو گئی (اب واپس نہیں ہو گی)۔‘‘"}],[4473,"عبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خرید و فروخت کرنے والے دونوں اپنی بیع کے سلسلے میں اس وقت تک اختیار کے ساتھ رہتے ہیں جب تک وہ جدا نہ ہوں، سوائے اس کے کہ وہ بیع خیار (اختیاری خرید و فروخت) ہو\"۔ نافع کہتے ہیں: چنانچہ عبداللہ بن عمر رضی اللہ عنہما جب کوئی ایسی چیز خریدتے جو دل کو بھا گئی ہو تو صاحب معاملہ سے (فوراً) جدا ہو جاتے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دو سودا کرنے والے ایک دوسرے سے جدائی تک اپنی بیع کی واپسی کا اختیار رکھتے ہیں الا یہ کہ وہ بیع خیار والی ہو۔‘‘ نافع نے کہا: حضرت عبداللہ بن عمر رضی اللہ عنہ جب کوئی چیز خریدتے اور وہ چیز ان کو اچھی لگتی تو (سودا کرتے ہی) اپنے ساتھی سے جدا ہو جاتے (تاکہ وہ واپس نہ کر سکے)۔","f2":"’’جدا ہو جاتے‘‘ ویسے ایک دوسری روایت میں اس سے روکا گیا ہے، دیکھئے: (سنن ابی داود، البیوع، حدیث: ۳۴۵۶، و سنن النسائی، البیوع، حدیث: ۴۴۸۸) شاید حضرت عبداللہ رضی اللہ عنہ کو اس حدیث کا علم نہیں ہو گا۔ و اللہ اعلم۔"}],[4474,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خرید و فروخت کرنے والے دونوں کے درمیان اس وقت تک بیع پوری نہیں ہوتی جب تک وہ جدا نہ ہو جائیں، سوائے بیع خیار کے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دو سودا کرنے والے جب تک ایک دوسرے سے جدا نہیں ہو جاتے، ان کا سودا پکا نہیں ہوتا الا یہ کہ وہ سودا کرتے وقت اختیار ختم کر لیں۔‘‘"}],[4475,"عبداللہ بن عمر رضی اللہ عنہا کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیچنے اور خریدنے والے دونوں کے درمیان اس وقت تک بیع پوری نہیں ہوتی جب تک وہ جدا نہ ہو جائیں، سوائے بیع خیار کے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سودا کرنے والے دو اشخاص میں سے ہر ایک کے لیے سودا پکا نہیں ہوتا حتی کہ وہ جدا ہو جائیں مگر اختیار والا سودا۔‘‘"}],[4476,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"بیچنے اور خریدنے والے دونوں کے درمیان اس وقت تک بیع پوری نہیں ہوتی جب تک وہ جدا نہ ہو جائیں، سوائے بیع خیار کے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’سودا کرنے والے دو اشخاص کے درمیان بیع مستقل نہیں ہوتی حتی کہ وہ الگ الگ ہو جائیں علاوہ اختیار والی بیع کے۔‘‘"}],[4477,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیچنے اور خریدنے والے دونوں کے درمیان اس وقت تک بیع پوری نہیں ہوتی جب تک وہ دونوں جدا نہ ہو جائیں، سوائے بیع خیار کے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ کا فرمان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بیع کرنے والے دو افراد کے درمیان بیع پکی نہیں ہوتی حتی کہ وہ الگ الگ ہو جائیں علاوہ بیع خیار کے۔‘‘"}],[4478,"جریر رضی اللہ عنہ کہتے ہیں کہ جو کوئی غلام بھاگ کر مشرکوں کی سر زمین میں چلا جائے تو اس کا خون حلال ہے۔\nعبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"بیچنے اور خریدنے والے دونوں کے درمیان اس وقت تک بیع پوری نہیں ہوتی جب تک دونوں جدا نہ ہو جائیں، سوائے بیع خیار کے\"۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ابن عمر رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’سودا کرنے والے دو افراد کے درمیان سودا مستقل نہیں ہوتا حتی کہ ایک دوسرے سے الگ ہو جائیں مگر خیار والی بیع (کا حکم الگ ہے)۔‘‘"}],[4479,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیچنے اور خریدنے والے دونوں کے درمیان اس وقت تک بیع پوری نہیں ہوتی جب تک وہ جدا نہ ہو جائیں، سوائے بیع خیار کے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہر دو سودا کرنے والوں کے درمیان سودا پکا نہیں ہوتا حتی کہ ایک دوسرے سے الگ ہو جائیں مگر خیار والی بیع (کا حکم الگ ہے)۔‘‘"}],[4480,"عبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"بیچنے اور خریدنے والے دونوں کو اختیار رہتا ہے جب تک کہ وہ جدا نہ ہو جائیں، إلا یہ کہ وہ بیع خیار ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’سودا کرنے والے دو شخص جب تک جدا نہ ہوں، سودے کی واپسی کا اختیار رکھتے ہیں الا یہ کہ وہ بیع خیار والی ہو۔‘‘"}],[4481,"سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"بیچنے اور خریدنے والے دونوں کو اختیار رہتا ہے جب تک کہ وہ جدا نہ ہوں یا ان میں سے ہر ایک بیع کو اپنی مرضی کے مطابق لے اور وہ تین بار اختیار لیں\"۔","الألباني: ضعيف",{"u2":"حضرت مسرہ رضی اللہ عنہ سے منقول ہے کہ اللہ کے نبی صلی اللہ علیہ وسلم نے فرمایا: ’’سودا کرنے والیے دو شخص ایک دوسرے سے جدا ہونے تک سودے کی واپسی کا اختیار رکھتے ہیں، یا پھر ان میں سے ہر ایک اپنی پسند کی بیع کرے۔ اور وہ دونوں تین دفعہ ایک دوسرے کو اختیار دے دیں۔‘‘","f2":"’’یا پھر ان میں سے ہر ایک‘‘ اس سے مراد یہ ہے کہ ہر ایک دوسرے کو کہہ دے، کہ ابھی پسند کر لو، تمہیں اختایر ہے۔ بعد میں واپس نہیں ہو سکے گی۔ دونوں تین دفعہ اس بات کی صراحت کر لیں، پھر باوجود مجلس قائم ہونے کے واپسی کا اختیار نہیں رہے گا۔ اسی مفہوم کو سابقہ روایات میں بیع خیار کہا گیا ہے۔ بیع خیار کا دوسرا مفہوم حدیث نمبر: ۴۴۷۰ میں بیان ہو چکا ہے۔"}],[4482,"سمرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیچنے اور خریدنے والے دونوں کو اختیار ہوتا ہے جب تک کہ وہ جدا نہ ہوں اور ان میں سے ایک اپنے ساتھی سے راضی نہ ہو جائے، یا خواہش پوری نہ کر لے (یعنی بیع خیار تک)\"۔","الألباني: ضعيف",{"u2":"حضرت سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سودا کرنے والے دو شخص ایک دوسرے سے جدا ہونے تک بیع کی واپسی کا اختیار رکھتے ہیں۔ یا ان میں سے کوئی اپنے ساتھی سے اس کی حتمی رضامندی معلوم کر لے۔‘‘","f2":"’’حتمی رضامندی‘‘ یعنی واپسی کا اختیار ختم کر لے جیسا کہ بیع خیار کے مفہوم میں گزرا۔"}],[4483,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: خریدنے اور بیچنے والے دونوں کو اس وقت تک اختیار رہتا ہے جب تک وہ جدا نہ ہوں، سوائے اس کے کہ وہ بیع خیار ہو، اور (کسی فریق کے لیے) یہ حلال نہیں کہ وہ اپنے صاحب معاملہ سے اس اندیشے سے جدا ہو کہ کہیں وہ بیع فسخ کر دے ۱؎۔\n§وضاحت\n۱؎: معلوم ہوا کہ جدائی سے مراد جسمانی جدائی ہے، یعنی دونوں کی مجلس بدل جائے، نہ کہ مجلس ایک ہی ہو اور بات چیت کا موضوع بدل جائے جیسا کہ بعض علماء کا خیال ہے۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب کے پردادا محترم (حضرت عبداللہ بن عمرو رضی اللہ عنہ) سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’سودا کرنے والے دونوں شخص (بائع اور مشتری) جدا ہونے تک سودے کی واپسی کا اختیار رکھتے ہیں الا یہ کہ وہ سودے کے دوران میں اختیار ختم کر چکے ہوں۔ اور کسی ایک فریق کو اجازت نہیں کہ وہ سودے کی واپسی کے ڈر سے اپنے ساتھی سے جدا ہو جائے۔‘‘","f2":"(۱) یہ حدیث تفرق بالابدان، یعنی ایک دوسرے سے جسمانی اور بدنی طور پر الگ ہونے کی صریح دلیل ہے۔ بعض لوگوں کا مسلک ہے کہ کسی مجلس میں سودا طے ہو جانے کے بعد مجلس کے اندر دوسری باتیں شروع ہو جائیں تو اختیار ختم ہو جاتا ہے، یعنی یہ حضرات تفرق بالاقوال کے قائل ہیں۔ مذکورہ بالا حدیث سے واضح طور پر ان کے مسلک کا، جو خالصتا رائے پر مبنی ہے، رد ہو رہا ہے۔ حق یہ ہے کہ تفرق بالاقوال والا مسلک ازروئے دلائل مرجوح ہے اور صریح حدیث کے خلاف بھی۔ (۲) اس حدیث مبارکہ سے یہ بھی ثابت ہوا کہ اگر اسی مجلس میں ایک فریق نے دوسرے کو یہ اختیار دیا ہے کہ جو فیصلہ کرنا ہے ابھی اور اسی وقت کر لو، پھر سودا ہو جاتا ہے تو اب ان کا اختیار ختم ہو جائے گا، خواہ وہ مجلس کتنی دیر ہی برقرار رہے۔ (۳) یہ حدیث مبارکہ اس اہم مسئلے پر بھی دلالت کرتی ہے کہ بائع اور مشتری دونوں کے لیے ضروری ہے کہ وہ ایک دوسرے کی خیر خواہی کریں، لہٰذا دونوں میں سے کسی کے لیے بھی جائز نہیں کہ وہ سودا پکا کرنے کے لیے جلدی کرے اور طے ہوتے ہی دونوں میں سے کوئی ایک اس مجلس سے فوراً چلا جائے اور دوسرے فریق کو سوچنے سمجھنے کا موقع ہی نہ دے۔ اس کا نتیجہ یہ ہو گا کہ وہ شخص اپنے فیصلے پر نادم ہو گا اور پچھتائے گا، اس لیے یہ ضروری ہے کہ ان میں سے ہر ایک اپنے دوسرے ساتھی کو غور و فکر کی مہلت دے۔ (۴) ’’واپسی کے ڈر سے‘‘ کسی کو دھوکے میں رکھنا جائز نہیں چونکہ مجلس برقرار رکھنے تک واپسی کا حق ہے۔ اس حق کو زائل کرنے کی کوشش بھی حق تلفی میں آتی ہے۔ فریق ثانی سے خیر خواہی اور خلوص کا تقاضا یہ ہے کہ اسے اس کا حق استعمال کرنے کا پورا موقع دیا جائے۔ حدیث کے آخری الفاظ اس بات کی صریح دلیل ہیں کہ یہاں خیار مجلس ثابت کیا جا رہا ہے اور جب تک وہ جسمانی طور پر اکٹھے ہیں، یہ حق باقی رہتا ہے ورنہ جدا ہونے سے روکنے کے کیا معنی؟"}],[4484,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے ذکر کیا کہ وہ بیع میں دھوکہ کھا جاتا ہے تو آپ نے اس سے فرمایا:\"جب تم بیچو تو کہہ دیا کرو: فریب اور دھوکہ دھڑی نہ ہو، چنانچہ وہ شخص جب کوئی چیز بیچتا تو کہتا: دھوکہ دھڑی نہیں\" ۱؎۔\n§وضاحت\n۱؎: یہ کہہ دینے سے اسے اختیار حاصل ہو جاتا اگر بعد میں اسے پتہ چل جائے کہ اس کے ساتھ چالبازی کی گئی ہے تو وہ اسے فسخ کر سکتا ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے ذکر کیا کہ (اکثر و بیشتر) اس کے ساتھ سودے میں دھوکا اور فریب کیا جاتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تو سودا کرنے لگے تو کہہ دیا کر: دھوکا نہیں چلے گا۔‘‘ پھر وہ آدمی جب بھی سودا کرتا تو کہہ دیا کرتا تھا کہ دھوکا نہیں چلے گا۔","f2":"سنن بیہقی (۵/۲۷۳) کی روایت میں ہے: ’’پھر تجھے تین دن تک سودے کی واپسی کا اختیار ہو گا۔‘‘ گویا جب سودے میں تنبیہ کر دی جائے کہ دھوکا نہیں چلے گا، یعنی دھوکا نہ کرنا، میں سادہ آدمی ہوں۔ اس کے باوجود فریق ثانی چالاکی دکھا جائے تو اس سادہ شخص کو تین دن تک واپسی کا اختیار رہے گا۔ بعض فقہاء نے یہ رعایت صرف اسی شخص سے خاص کی ہے جس سے یہ مسئلہ صادر ہوا تھا، حالانکہ اس تخصیص کی کوئی وجہ نہیں۔ کیا سادہ لوگوں کو اس دنیا میں رہنے کا حق نہیں؟ یا ان کو دھوکا دینا شرعاً جائز ہے؟ اسلام تو ایسی خود غرضی کی اجازت نہیں دیتا، لہٰذا چالاک لوگوں کی بجائے سادہ مومنوں کی حمایت کرنا چاہیے اور دھوکا دینے والوں کی حوصلہ شکنی کرنا چاہیے اور وہ مندرجہ بالا صورت ہی میں ہے۔"}],[4485,"انس رضی اللہ عنہ سے روایت ہے کہ ایک شخص کم عقلی کا شکار تھا اور تجارت کرتا تھا، اس کے گھر والوں نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر کہا: اللہ کے نبی! آپ اسے تجارت کرنے سے روک دیجئیے، تو آپ نے اسے بلایا اور اسے اس سے روکا، اس نے کہا: اللہ کے نبی! میں تجارت سے باز نہیں آ سکتا، تو آپ نے فرمایا:\"جب بیچو تو کہو: فریب و دھوکہ نہیں\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے منقول ہے کہ ایک آدمی کی سوجھ بوجھ میں کچھ کمی تھی۔ وہ سودے کیا کرتا تھا (اور نقصان اٹھاتا تھا) اس کے گھر والوں نے نبی اکرم صلی اللہ علیہ وسلم کے پاس حاضر ہو کر عرض کی: اے اللہ کے نبی! اس پر سودے کرنے کی پابندی لگا دیں۔ اللہ کے نبی صلی اللہ علیہ وسلم نے اس شخص کو بلایا اور اسے سودے کرنے سے منع فرمایا۔ اس شخص نے کہا: اے اللہ کے نبی! میں سودا کرنے سے نہیں رک سکوں گا۔ آپ نے فرمایا: ’’جب تو سودا کرے تو کہہ دیا کر، دھوکا نہیں ہونا چاہیے۔ (ورنہ سودا واپس ہو جائے گا)۔‘‘","f2":"(۱) تجارت اور سوداگری میں دھوکا دینا، شرعاً ناجائز اور حرام ہے۔ ایسا تاجر جو لوگوں کو خرید و فروخت میں دھوکا دیتا ہے، وہ ان کا مال باطل طریقے سے کھاتا ہے اور یہ حرام ہے۔ (۲) اس حدیث مبارکہ سے یہ مسئلہ بھی ثابت ہوتا ہے کہ اگر ایک فریق کی طرف سے بھی کوئی ایسی شرط ہو جوو شرعاً جائز ہو تو وہ معتبر ہو گی۔ نہ صرف شرط معتبر ہو گی بلکہ اس کی وجہ سے سودا فسخ اور ختم کرنے کا اختایر بھی اسے حاصل ہو گا۔ (۳) یہ حدیث اس اہم مسئلے پر بھی دلالت کرتی ہے کہ خبر واحد قطعی طور پر حجت ہے۔ (۴) معقول عذر کی وجہ سے بالغ شخص پر تجارت نہ کرنے کی پابندی عائد کی جا سکتی ہے۔ (۵) ’’دھوکا نہیں ہونا چاہیے‘‘ گویا کہا جا رہا ہے: اگر دھوکا ہو گا تو سودا واپس ہو گا۔ اگر صراحتاً واپسی کی شرط لگانے سے واپسی ہو سکتی ہے تو کنایۃً واپسی کی شرط سے واپسی میں کیا حرج ہے؟"}],[4486,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی جب بکری یا اونٹنی بیچے تو اس کے تھن میں دودھ روک کر نہ رکھے\" ۱؎۔\n§وضاحت\n۱؎: کیونکہ ایسے جانور کو اگر بیچا جائے گا تو خریدار کے ساتھ دھوکہ ہو گا اور کسی کو دھوکہ دینا صحیح نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص بکری یا دودھ والی اونٹنی بیچنے کا ارادہ رکھتا ہو تو وہ اس کا دودھ دوہنا بند نہ کرے۔‘‘","f2":"’’بیچنے کا ارادہ رکھتا ہو‘‘ تاکہ خریدنے والے کو دھوکا نہ لگے، البتہ اگر بیچنے کا پروگرام نہ ہو اور دودھ تھوڑا ہو تو ناغہ کر کے دودھ دوہا جا سکتا ہے کیونکہ اس سے کسی کو دھوکا دینا مقصود نہیں۔ بعض کا خیال ہے دودھ پستانوں میں جمع رکھنے سے جانور کو تکلیف ہوتی ہے، لہٰذا دودھ دوہتے رہنا چاہیے لیکن یہ شرعی کی بجائے طبی مسئلہ ہے۔"}],[4487,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"آگے جا کر تجارتی قافلے سے مت ملو ۱؎ اور اونٹنیوں اور بکریوں کو ان کے تھنوں میں دودھ روک کر نہ رکھو ۲؎، اگر کسی نے ایسا جانور خرید لیا تو اسے اختیار ہے چاہے تو اسے رکھ لے اور چاہے تو اسے لوٹا دے اور (لوٹاتے وقت) اس کے ساتھ ایک صاع کھجور دیدے\" ۳؎۔\n§وضاحت\n۱؎: چونکہ باہر سے آنے والے تاجر کو بازار کی قیمت کا صحیح علم نہیں ہے اس لیے بازار میں پہنچنے سے پہلے اس سے سامان خریدنے میں تاجر کو دھوکہ ہو سکتا ہے، اسی لیے نبی اکرم صلی اللہ علیہ وسلم نے تاجروں کے بازار میں پہنچنے سے پہلے ان سے مل کر ان کا سامان خریدنے سے منع فرما دیا ہے اور اگر کوئی ایسا کرتا ہے تو تاجر کو اختیار حاصل ہو گا بیع کے نفاذ اور عدم نفاذ کے سلسلہ میں۔ ۲؎: تھن میں دو یا تین دن تک دودھ چھوڑے رکھنے اور نہ دوہنے کو «تصریہ» کہتے ہیں تاکہ اونٹنی یا بکری دودھاری سمجھی جائے اور جلد اور اچھے پیسوں میں بک جائے۔ ۳؎: تاکہ وہ اس دودھ کا بدل بن سکے جو خرید دار نے دوہ لیا ہے، نیز واضح رہے کہ کسی ثابت شدہ حدیث کی تردید یہ کہہ کر نہیں کی جا سکتی کہ کسی مخالف اصل سے اس کا ٹکراؤ ہے یا اس میں مثلیت نہیں پائی جا رہی ہے اس لیے عقل اسے تسلیم نہیں کرتی، بلکہ شریعت سے جو چیز ثابت ہو وہی اصل ہے اور اس پر عمل واجب ہے، اسی طرح حدیث مصراۃ ان احادیث میں سے ہے جو صحیح اور ثابت شدہ ہیں لہٰذا کسی قیل و قال کے بغیر اس پر عمل واجب ہے۔ کسی قیاس سے اس کو رد نہیں کیا جا سکتا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’غلے والے قافلوں کو (منڈی سے باہر جا کر) خرید و فروخت کے لیے نہ ملو اور اونٹنی یا بکری کا دودھ نہ روکو۔ جو شخص ایسا جانور خرید لے تو اسے (دودھ دوہنے کے بعد) دو چیزوں میں سے بہتر کا اختیار ہے۔ اگر چاہے تو جانور رکھ لے اور اگر واپس کرنا چاہے تو واپس کر دے اور اس کے ساتھ کھجوروں کا ایک صاع بھی دے۔‘‘","f2":"(۱) بیع المصراۃ، ناجائز اور حرام ہے کیونکہ اس میں دھوکا اور فریب ہے جو شرعاً ناجائز ہے۔ (۲) اس حدیث کی بابت امام ابن عبدالبر رحمہ اللہ فرماتے ہیں کہ یہ حدیث دھوکا دہی سے ممانعت، عیب کا پتا چلنے کے بعد خریدار کو چیز واپس کرنے ک اختیار اور مدتِ اختیار کے تعین میں اصل ہے، نیز اس سے معلوم ہوا کہ اصل بیع حرام نہیں (الا یہ کہ خریدار اس سے راضی نہ ہو، مطلب یہ کہ پوشیدہ عیب کا علم ہو جانے کے بد بھی اگر خریدار سودا واپس نہ کرنا چاہے، یعنی سودا فسخ نہ کرنا چاہے تو اسے، اس کا اختیار حاصل ہے کہ وہ سودا فسخ نہ کرے۔)(۳) جانور کے تھنوں میں دودھ، اس لیے روکا جاتا ہے تاکہ خریدار کو یہ معلوم ہو کہ جانور دودھیل (بہت دودھ دینے والا) ہے۔ اس طرح کے فریب کی وجہ سے خریدار زیادہ قیمت دینے پر تیار ہو جاتا ہے۔ (۴) تصریہ کی تفسیر باب میں بیان ہو چکی ہے۔ چونکہ اس کا مقصد خریدار کو دھوکا دینا ہے اور ایسا دھوکا لگنا بہت ممکن ہے، لہٰذا شریعت نے خریدار کو سودے کی منسوخی کا اختیار دیا ہے۔ اور اس میں کوئی اشکال نہیں۔ جمہور اہل علم اسی کے قائل ہیں، البتہ احناف کو یہ بات اصول کے خلاف معلوم ہوتی ہے کہ طے شدہ سودے کو ایک فریق کیسے منسوخ کر سکتا ہے؟ حالانکہ دھوکا ایک بہت بڑا سبب ہے جو کسی بھی عقد کو فسخ کر سکتا ہے۔ خود احناف عیب کی بنا پر سودے کے فسخ کے قائل ہیں۔ اگر عیب معلوم ہونے سے سودا فسخ ہو سکتا ہے تو دھوکا معلوم ہونے سے سودا فسخ کیوں نہیں ہو سکتا؟ (۵) ’’کھجوروں کا ایک صاع‘‘ اس دودھ کا معاوضہ جو پہلے مالک کے پاس ہوتے ہوئے جانور کے تھنوں میں جمع ہو چکا تھا اور خریدار نے وہ دودھ استعمال کیا۔ باقی رہی یہ بات کہ وہ دودھ تو کم و بیش ہو سکتا ہے، معاوضہ متعین کیوں کر دیا گیا؟ تو یہ دراصل قطع نزاع کے لیے ہے ورنہ قیمت کے تعین میں باہمی اختلاف ہو سکتا ہے۔ شریعت اس مسئلے میں ہم سے زیادہ سمجھ دار ہے۔ تبھی پیٹ کا بچہ ضائع کر دینے کی صورت میں شریعت نے ایک غلام یا گھوڑا معاوضہ مقرر کیا ہے۔ وہ بچہ پانچ ماہ کا بھی ہو سکتا ہے، نو ماہ کا بھی۔ اور یہ ضروری نہیں کہ غلام اور گھوڑے کی قیمت برابر ہو۔ بلکہ غلام اور غلام۔ نیز گھوڑے اور گھوڑے کی قیمت بھی برابر نہیں ہو سکتی۔ اسی طرح شریعت نے ہاتھوں اور پائوں کی ہر ہر انگلی کی دیت دس دس اونٹ مقرر کر رکھی ہے، خواہ وہ چھنگلی ہو یا انگوٹھا، خواہ ہاتھ سے ہو یا پائوں سے، حالانکہ سب کی جسامت او مفاد برابر نہیں۔ اور اونٹوں کی قیمت بھی ایک جیسی نہیں۔ صاع کیوں مقرر کیا گیا؟ حتی کہ انہوں نے اپنا غصہ راویٔ حدیث حضرت ابوہریرہ رضی اللہ عنہ پر بھی جھاڑا ہے کہ وہ فقیہ نہیں تھے۔ پوچھا جا سکتا ہے کہ اگر چار سال تک صبح و شام رسول اللہ صلی اللہ علیہ وسلم سے فیض یاب ہونے والے وہ صحابی فقیہ نہیں بنے تو آپ حضرات کی کی فقات کی سند کیا ہے؟ چاند پر نہیں تھوکنا چاہیے ورنہ اپنا منہ بھی دکھانے کے قابل نہیں رہتا۔ چاند کا کچھ نہیں بگڑتا، نیز یہ روایت حضرت ابوہریرہ رضی اللہ عنہ کا اپنا فتویٰ نہیں کہ ان پر اعتراض کیا جائے بلکہ یہ تو رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے جسے انہوں نے نقل فرمایا ہے، نیز یہ روایت تو احناف کے مسلمہ فقیہ صحابی حضرت عبداللہ بن مسعود رضی اللہ عنہ سے بھی آتی ہے۔ اب اپنے گھر کو تو ڈھانے سے رہے۔ بہتری اسی میں ہے کہ صحیح سند سے ثابت فرمان رسول کو بلاچون و چرا تسلیم کر لیا جائے اور شریعت کی باریکیوں کو شارع علیہ السلام کی بصیرت کے حوالے کر دیا جائے کہ رموز مملکت خویش خسرواں دانند۔ مختصراً یہ کہ رسول اللہ صلی اللہ علیہ وسلم نے ایسے جانور کے ساتھ ایک صاع کھجوریں دینے کا حکم اس لیے دیا ہے کہ اس جانور سے حاصل ہونے والے دودھ کا معاوضہ ہو جائے اور اس کی اصل وجہ یہ ہے کہ جب خریدار نے وہ جانور خریدا تھا تو کچھ دودھ اس کی ملکیت میں آنے سے پہلے پیدا ہو چکا تھا اور کچھ دودھ ملکیت میں آنے کے بعد پیدا ہوا ہے لیکن یہ قطعاً معلوم نہیں ہو سکتا کہ کتنے دودھ کی قیمت خریدار نے ادا کی ہے اور کتنا دودھ نیا ہے، اس لیے دودھ یا اس کی قیمت واپس کرنا ممکن ہی نہیں تھا، لہٰذا رسول اللہ صلی اللہ علیہ وسلم نے اس دودھ کے مقابلے میں ایک صاع کھجوریں مقرر فرما دیں تاکہ مشتری اور بائع کے درمیان اختلاف پیدا نہ ہو۔ خریدنے والے شخص کو جو دودھ حاصل ہوا ہے یہ صاع اس کا معاوضہ بن جائے گا۔ اس معاملے میں یہ نہیں دیکھا گیا کہ دودھ، معاوضے سے زیادہ تھا یا تھوڑا۔ حقیقت یہ ہے کہ دودھ کم تھا یا زیادہ، اس کو معلوم کرنے کا کوئی آلہ اور پیمانہ وجود میں آیا ہے نہ آ ہی سکتا ہے۔ و اللہ اعلم۔ (۶) جن علاقوں میں کھجور فراواں نہیں ہوتی، وہاں اس علاقے کی عام خوراک دی جا سکتی ہے، مثلاً: ہمارے علاقے میں گندم دی جا سکتی ہے۔ یہاں تو کھجوروں کا صاع بہت مہنگا ہو گا۔ کھجور کا تعین عرب علاقے کی مناسبت سے ہے کہ وہاں کھجور عام خوراک تھی اور با آسانی اور بہ افراط ملتی تھی، جیسے ہمارے ہاں گندم ہے۔ لیکن اس میں بھی مستحب یہی ہے کہ پورا صاع گندم دی جائے۔ اور اسی طرح جس علاقے کی خوراک چاول ہو، وہاں ایک صاع چاول دئیے جا سکتے ہیں۔ و اللہ اعلم۔"}],[4488,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کوئی ایسا جانور خریدا جس کا دودھ اس کے تھن میں روک رکھا گیا ہو تو جب اسے دو ہے اور اس پر راضی ہو جائے تو چاہیئے کہ اسے روک لے اور اگر اسے وہ ناپسند ہو تو اسے لوٹا دے اور اس کے ساتھ ایک صاع کھجور بھی دیدے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے ایسا جانور خریدا جس کا دودھ روکا گیا تھا تو (اس دھوکے کا پتا چل جانے پر) وہ (خریدار) چاہے تو اسے رکھ لے، چاہے واپس کر دے (لیکن واپسی کی صورت میں) اس کے ساتھ کھجوروں کا ایک صاع بھی دینا ہو گا۔‘‘"}],[4489,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کوئی «محفلہ» یا «مصراۃ» (دودھ تھن میں روکے ہوئے جانور کو) خریدا تو اسے تین دن تک اختیار ہے، اگر وہ اسے روکے رکھنا چاہے تو روک لے اور اگر لوٹانا چاہے تو اسے لوٹا دے اور اس کے ساتھ ایک صاع کھجور بھی دے، گیہوں کا دینا ضروری نہیں\"۔","الألباني: صحيح م خ نحوه دون ثلاثة أيام",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ ابو القاسم صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے ایسا جانور خریدا جس کا دودھ تھنوں میں جمع کیا گیا تھا، اسے تین دن تک اختیار رہتا ہے، چاہے تو رکھ لے، چاہے واپس کر دے اور ساتھ کھجوروں کا ایک صاع دے دے۔ گندم کا نہیں۔‘‘","f2":"(۱) ’’ابو القاسم‘‘ یہ رسول اللہ صلی اللہ علیہ وسلم کی کنیت تھی، یا تو آپ کے بڑے بیٹے قاسم کی نسبت سے یا اس لیے کہ آپ صلی اللہ علیہ وسلم اللہ کے حکم سے علم اور مال تقسیم فرماتے تھے۔ تقسیم کرنے والے کو بھی قاسم کہا جاتا ہے۔ عربوں میں کنیت کا عام رواج تھا۔ جب کسی کا احترام مقصود ہوتا تھا تو اسے کنیت سے پکارا جاتا تھا۔ (۲) ’’تین دن تک‘‘ کیونکہ اتنے دنوں میں اصل دودھ کا پتا چل جاتا ہے اور دھوکا واضح ہو جاتا ہے۔ (۳) ’’گندم کا نہیں‘‘ کیونکہ اس وقت عرب میں گندم بہت مہنگی تھی۔ خال خال کسی کے پاس تھوڑی بہت ہوتی تھی جیسے آج کل ہمارے ہاں کھجوریں ہیں، لہٰذا گندم کی نفی اس علاقے کے لحاظ سے ہے نہ کہ ہمارے علاقے کے لحاظ سے جہاں کی عام خوراک گندم ہے بلکہ یہاں گندم دی جائے گی۔ و اللہ اعلم۔"}],[4490,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ کیا کہ «خراج» (نفع) مال کی ضمانت سے جڑا ہوا ہے ۱؎۔\n§وضاحت\n۱؎: مثلاً خریدار نے ایک غلام خریدا اسی دوران غلام نے کچھ کمائی کی پھر غلام میں کچھ نقص اور عیب نکل آیا تو خریدار نے اسے بیچنے والے کو لوٹا دیا اس کے کمائی کا حقدار خریدار ہو گا بیچنے والا نہیں کیونکہ غلام کے کھو جانے یا بھاگ جانے کی صورت میں خریدار ہی اس کا ضامن ہے۔","الألباني: حسن",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ کسی چیز کا نفع اس کو ملے گا جو اس چیز کا ضامن ہو گا۔","f2":"مثلاً: کسی شخص نے کوئی جانور خریدا، چند دن کے بعد اس میں عیب یا دھوکے کا انکشاف ہوا تو بیع واپس ہو گئی مگر جتنے دن وہ جانور خریدار کے پاس رہا، اس سے حاصل ہونے والا دودھ وغیرہ اسی کا ہو گا کیونکہ ان دنوں اگر اس جانور کا نقصان ہو جاتا تو خریدار کے ذمے پڑتا۔ اسی طرح ان دنوں کے دوران میں خوراک وغیرہ بھی اسی کی ذمہ داری تھی۔"}],[4491,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے باہر نکل کر سامان خریدنے سے، مہاجر (شہری) کو دیہاتی کا مال بیچنے سے ۱؎، جانوروں کے تھن میں قیمت بڑھانے کے مقصد سے دودھ چھوڑنے سے، خود خریدنا مقصود نہ ہو لیکن دوسرے کو ٹھگانے کے لیے بڑھ بڑھ کر قیمت لگانے سے اور اپنے بھائی کے مول پر بھاؤ بڑھانے سے اور اپنی سوکن ۲؎ کے لیے طلاق کا مطالبہ کرنے سے منع فرمایا۔\n§وضاحت\n۱؎: «تلقی» :(شہر سے باہر جا کر بازار آنے والے تاجر کا مال خریدنے ) میں نیز دیہات سے شہر کے بازار میں مال لانے والے سے بازار سے پہلے ہی مال خرید لینے میں اس طرح کے دونوں تاجروں نیز شہر کے عام باشندوں کو بھی نقصان کا اندیشہ ہے اس لیے اس طرح کی خریداری سے منع کر دیا گیا ہے تاجر کا نقصان اس طرح ہو سکتا ہے کہ ہو سکتا ہے کہ بازار میں سامان کا بھاؤ زیادہ ہو اور تاجر کا نقصان ہو جائے اور شہر کے باشندوں کا نقصان اس طرح ہو گا کہ درمیان میں ایک اور واسطہ ہو جانے کے سبب سامان کا بھاؤ زیادہ ہو جائے۔ ۲؎: یعنی ہونے والی سوکن، اس کی صورت یہ ہے کہ کوئی آدمی اپنی کسی بیوی کی موجودگی میں کسی دوسری عورت کو نکاح کا پیغام دے تو وہ عورت اس سے اپنی پہلی بیوی کو طلاق دے دینے کی شرط رکھے، یہ ممنوع ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ کوئی تاجر تجارتی قافلے کو منڈی سے باہر جا کر ملے، یا کوئی شہری کسی اعرابی (دیہاتی) کی کوئی چیز بیچے، یا کوئی اپنے جانور کا دودھ روکے، یا کوئی شخص ناجائز بھائو بڑھائے یا کوئی شخص کسی دوسرے بھائی کے بھائو پر بھائو کرے۔ یا کوئی عورت اپنی سوکن کی طلاق کا مطالبہ کرے۔","f2":"(۱) ’’باہر جا کر ملے‘‘ یہ ایک طریقہ تھا تجارتی قافلے کو دھوکے میں رکھنے کا کہ منڈی میں داخل ہونے سے پہلے آگے جا کر تجارتی قافلے کے ساتھ سودے کر لیے جائیں تاکہ قافلے والوں کو منڈی کے بھائو کا علم نہ ہو سکے اور ان سے سستا مال خرید لیا جائے۔ دراصل اس میں دھوکا مقصود ہے، لہٰذا شریعت نے اس سے منع فرما دیا بلکہ قافلے کو منڈی میں آنے دیا جائے، پھر ان سے سودے کیے جائیں۔ (۲) ’’کوئی شہری کسی اعرابی‘‘ حدیث میں لفظ مہاجر استعمال ہوا ہے کیونکہ اس وقت اکثر مہاجر ہی تجارت کرتے تھے، انصار تو زمیندار تھے۔ فرمان کا مقصد یہ ہے کہ شہری آدمی دیہاتی کا سامان نہ بیچے کیونکہ اس سے مہنگائی پیدا ہو گی۔ آخر شہری نے اپنا کمیشن بھی تو نکالنا ہے۔ اگر دیہاتی خود اپنا سامان بیٹے گا تو ظاہر ہے، وہ سستا بیچے گا کیونکہ اس نے اسی دن بیچ کر گھر واپس جانا ہوتا ہے جبکہ شہری اسے کہتا ہے کہ سامان میرے پاس رکھ چھوڑو، جب بھائو تیز ہو گا تو میں بیچ دوں گا۔ اس طریقے سے مہنگائی بڑھتی ہے، اس لیے منع فرمایا۔ ہاں، اگر شہری دیہاتی کے لیے کوئی چیز خریدے تو اجازت ہے کیونکہ اس سے مہنگائی نہیں ہو گی بلکہ وہ سستی چیز خریدے گا تاکہ کچھ اپنے لیے بھی بچا سکے۔ (۳) ’’بھائو بڑھائے‘‘ کسی آدمی کی نیت چیز خردینے کی نہیں لیکن وہ جان بوج کر ایک چیز کا بھائو زیادہ لگاتا ہے تاکہ اصل خریدار کو دھوکا دیا جا سکے اور وہ مہنگی خریدے۔ عام طور پر ایسے لوگ دکاندار کے ایجنٹ ہوتے ہیں جو کمیشن لیتے ہیں۔ حقیقت یہ ہے کہ یہ بھی دھوکا ہے، اس لیے منع کیا گیا ہے۔ (۴) ’’طلاق کا مطالبہ کرے‘‘ کوئی عورت نکاح کے موقع پر یا بعد میں یہ شرط لگائے کہ اپنی پہلی بیوی کو طلاق دے۔ یا پہلی بیوی دوسری بیوی کی طلاق کا مطالبہ کرے یہ ناجائز ہے کیونکہ اس میں بھی خود غرضی اور حسد کارفرما ہے۔ ہر عورت کا اپنا اپنا نصیب ہے جس پر اسے قناعت کرنی چاہیے۔"}],[4492,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے منع فرمایا کہ شہری دیہاتی کا سامان بیچے، گرچہ وہ اس کا باپ یا بھائی ہی کیوں نہ ہو۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے منع فرمایا کہ کوئی شہری کسی دیہاتی کا مال بیچے اگرچہ وہ اس کا باپ یا بھائی ہو۔","f2":"دیکھئے حدیث: ۴۴۹۶ کا فائدہ نمبر: ۲۔"}],[4493,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ہمیں اس بات سے روکا گیا کہ کوئی شہری کسی دیہاتی کا سامان بیچے، گرچہ وہ اس کا بھائی یا باپ ہی کیوں نہ ہو۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ ہمیں منع فرمایا گیا کہ کوئی شہری کسی دیہاتی کے لیے سامان بیچے اگرچہ وہ اس کا باپ یا بھائی ہو۔"}],[4494,"انس رضی اللہ عنہ کہتے ہیں کہ ہمیں اس بات سے روکا گیا کہ کوئی شہری کسی دیہاتی کا سامان بیچے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ نے فرمایا: ہمیں روکا گیا ہے کہ کوئی شہری کسی دیہاتی کا سامان بیچے۔"}],[4495,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی شہری کسی دیہاتی کا سامان نہ بیچے، لوگوں کو چھوڑ دو، اللہ تعالی ان میں سے بعض کو بعض کے ذریعہ رزق (روزی) فراہم کرتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کوئی شہری سی دیہاتی کا سامان نہ بیچے بلکہ لوگوں کو خود بیچنے دو تاکہ اللہ تعالیٰ ان کو ایک دوسرے سے رزق عطا فرمائے۔‘‘","f2":"مقصود یہ ہے کہ معاملات فطری طریقے سے جاری رہنے چاہئیں۔ مصنوعی طریقے سے قلت پیدا کر کے یا ذخیرہ اندوزی کے ذریعے سے مہنگائی پیدا نہیں کرنا چاہیے بلکہ جوں جوں پیداوار آتی جائے، بازار میں فروخت ہوتی جائے اور ضرورت مند لوگوں تک پہنچتی رہے۔ ظاہر ہے اگر شہری دیہاتی کا مال بیچے گا تو ذخیرہ اندوزی کرے گا اور مصنوعی قلت پیدا کرے گا تاکہ پیداوار مہنگی فروخت ہو اور اس کا اپنا فائدہ ہو۔"}],[4496,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تجارتی قافلے سے (مال) خریدنے کے لیے باہر نکل کر نہ ملو، اور تم میں سے کوئی دوسرے کی بیع پر بیع نہ کرے، نہ بھاؤ پر بھاؤ بڑھانے کا کام کرو اور نہ شہری دیہاتی کا سامان بیچے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم سودے کرنے کے لیے تجارتی قافلوں کو منڈی سے باہر جا کر نہ ملو۔ اور کوئی شخص دوسرے کے سودے پر سودا نہ کرے۔ اور ناجائز بھائو نہ بڑھائو۔ اور شہری دیہاتی کا مال نہ بیچے۔‘‘"}],[4497,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بھاؤ پر بھاؤ بڑھانے سے، شہری کا باہر جا کر دیہاتی سے مال لینے سے اور اس بات سے منع فرمایا کہ شہری دیہاتی کا سامان بیچے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بھائو بڑھانے، تجارتی قافلوں کو آگے جا کر ملنے اور شہری کو دیہاتی کا مال بیچنے سے منع فرمایا ہے۔","f2":"تفصیلات حدیث: ۴۴۹۶ میں بیان ہو چکی ہیں۔"}]]);
